--
-- Name: add_planet_stock(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_planet_stock(p_system_id text, p_resource text, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_cap integer; v_have integer; v_fit integer;
begin
  if p_amount is null or p_amount <= 0 then return 0; end if;
  v_cap := planet_stock_cap(p_system_id);
  -- строка склада под блокировкой: два одновременных пополнения не поднимут запас выше предела
  insert into planet_stock (system_id, resource, amount) values (p_system_id, p_resource, 0)
  on conflict (system_id, resource) do nothing;
  select amount into v_have from planet_stock
   where system_id = p_system_id and resource = p_resource for update;
  v_fit := least(p_amount, greatest(0, v_cap - coalesce(v_have, 0)));
  if v_fit = 0 then return 0; end if;
  update planet_stock set amount = amount + v_fit where system_id = p_system_id and resource = p_resource;
  return v_fit;
end;
$$;


--
-- Name: apply_ship_refit(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ship_refit(p_ship_id uuid, p_upgrades text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare r record;
  v_hp int := 0; v_sh int := 0; v_fore int := 0; v_dmg int := 0;
  v_vis int := 0; v_mv int := 0; v_han int := 0; v_cap int := 0;
  v_tr boolean := false;
begin
  for r in select * from researches where id = any(p_upgrades) loop
    if    r.effect_kind = 'hull'        then v_hp   := v_hp   + r.effect_value;
    elsif r.effect_kind = 'shield'      then v_sh   := v_sh   + r.effect_value;
    elsif r.effect_kind = 'fore_shield' then v_fore := v_fore + r.effect_value;
    elsif r.effect_kind = 'damage'      then v_dmg  := v_dmg  + r.effect_value;
    elsif r.effect_kind = 'vision'      then v_vis  := v_vis  + r.effect_value;
    elsif r.effect_kind = 'move'        then v_mv   := v_mv   + r.effect_value;
    elsif r.effect_kind = 'hangar'      then v_han  := v_han  + r.effect_value;
    elsif r.effect_kind = 'capacity'    then v_cap  := v_cap  + r.effect_value;
    elsif r.effect_kind = 'tractor'     then v_tr   := true;
    end if;
  end loop;

  update ships s set
    upgrades = p_upgrades,
    bonus_hp = v_hp, bonus_shield = v_sh, bonus_fore = v_fore,
    bonus_damage = v_dmg, bonus_vision = v_vis, bonus_move = v_mv,
    bonus_hangar = v_han, bonus_capacity = v_cap, has_tractor = v_tr,
    hp = least(s.hp, t.max_hp + v_hp),
    shield_fore      = least(coalesce(s.shield_fore, 0),      t.max_shield + v_sh + v_fore),
    shield_aft       = least(coalesce(s.shield_aft, 0),       t.max_shield + v_sh),
    shield_port      = least(coalesce(s.shield_port, 0),      t.max_shield + v_sh),
    shield_starboard = least(coalesce(s.shield_starboard, 0), t.max_shield + v_sh)
  from ship_types t
  where s.id = p_ship_id and t.id = s.ship_type;
end;
$$;


--
-- Name: apply_ship_upgrades(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ship_upgrades(p_ship_id uuid, p_upgrades text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare r record;
  v_hp int := 0; v_sh int := 0; v_fore int := 0; v_dmg int := 0;
  v_vis int := 0; v_mv int := 0; v_han int := 0; v_cap int := 0;
  v_tr boolean := false;
begin
  for r in select * from researches where id = any(p_upgrades) loop
    if    r.effect_kind = 'hull'        then v_hp  := v_hp  + r.effect_value;
    elsif r.effect_kind = 'shield'      then v_sh  := v_sh  + r.effect_value;
    elsif r.effect_kind = 'fore_shield' then v_fore := v_fore + r.effect_value;
    elsif r.effect_kind = 'damage'      then v_dmg := v_dmg + r.effect_value;
    elsif r.effect_kind = 'vision'      then v_vis := v_vis + r.effect_value;
    elsif r.effect_kind = 'move'        then v_mv  := v_mv  + r.effect_value;
    elsif r.effect_kind = 'hangar'      then v_han := v_han + r.effect_value;
    elsif r.effect_kind = 'capacity'    then v_cap := v_cap + r.effect_value;
    elsif r.effect_kind = 'tractor'     then v_tr  := true;
    end if;
  end loop;

  update ships set
    upgrades = p_upgrades,
    bonus_hp = v_hp, bonus_shield = v_sh, bonus_fore = v_fore,
    bonus_damage = v_dmg, bonus_vision = v_vis, bonus_move = v_mv,
    bonus_hangar = v_han, bonus_capacity = v_cap, has_tractor = v_tr,
    hp = (select max_hp from ship_types where id = ships.ship_type) + v_hp,
    shield_fore      = (select max_shield from ship_types where id = ships.ship_type) + v_sh + v_fore,
    shield_aft       = (select max_shield from ship_types where id = ships.ship_type) + v_sh,
    shield_port      = (select max_shield from ship_types where id = ships.ship_type) + v_sh,
    shield_starboard = (select max_shield from ship_types where id = ships.ship_type) + v_sh
  where id = p_ship_id;
end;
$$;


--
-- Name: apply_unit_upgrades(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_unit_upgrades(p_unit_id uuid, p_upgrades text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare r record;
  v_hp int := 0; v_dmg int := 0; v_vis int := 0; v_mv int := 0; v_rng int := 0;
begin
  for r in select * from researches where id = any(p_upgrades) loop
    if    r.effect_kind = 'hp'           then v_hp := v_hp + r.effect_value;
    elsif r.effect_kind = 'hp_slow'      then v_hp := v_hp + r.effect_value; v_mv := v_mv - 1;
    elsif r.effect_kind = 'damage'       then v_dmg := v_dmg + r.effect_value;
    elsif r.effect_kind = 'vision'       then v_vis := v_vis + r.effect_value;
    elsif r.effect_kind = 'move'         then v_mv := v_mv + r.effect_value;
    elsif r.effect_kind = 'weapon_range' then v_rng := v_rng + r.effect_value;
    end if;
  end loop;

  update unit_positions set
    upgrades = p_upgrades,
    bonus_hp = v_hp, bonus_damage = v_dmg, bonus_vision = v_vis,
    bonus_move = v_mv, bonus_range = v_rng,
    hp = (select max_hp from unit_types where id = unit_positions.unit_type) + v_hp
  where id = p_unit_id;
end;
$$;


--
-- Name: approach_warning_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approach_warning_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare c record; v_owner uuid; v_pct numeric; v_trade boolean;
begin
  for c in
    select cm.id, cm.name, cm.faction, cm.user_id, cm.moving_from, cm.moving_to,
           cm.departed_at, cm.arrives_at
    from commanders cm
    join systems s on s.id = cm.moving_to
    where cm.moving_to is not null
      and cm.arrives_at > now()
      and cm.warned_at is null
      and not s.is_deep_space
  loop
    v_pct := extract(epoch from now() - c.departed_at)
             / nullif(extract(epoch from c.arrives_at - c.departed_at), 0) * 100;

    continue when coalesce(v_pct, 0) < game_setting_int('approach_warn_pct', 80);

    select sc.controller_user_id into v_owner
    from system_control sc
    join profiles p on p.id = sc.controller_user_id
    where sc.system_id = c.moving_to and p.faction is distinct from c.faction;

    if v_owner is not null then
      -- Летит ли этот флот за покупкой именно на эту планету
      v_trade := exists (
        select 1 from supply_routes sr
        where sr.commander_id = c.id and sr.status = 'active' and sr.order_id is not null
          and sr.stops -> sr.stop_index ->> 'system_id' = c.moving_to
          and supply_pickup_live(sr.stops -> sr.stop_index));

      if v_trade then
        perform log_event(v_owner,
                          (select faction from systems where id = c.moving_to),
                          c.moving_to, 'trade_approaching',
                          (select nickname from profiles where id = c.user_id),
                          greatest(0, ceil(extract(epoch from c.arrives_at - now()))::integer),
                          'private', null);
      else
        perform log_event(v_owner,
                          (select faction from systems where id = c.moving_to),
                          c.moving_to, 'enemy_approaching',
                          c.name,
                          greatest(0, ceil(extract(epoch from c.arrives_at - now()))::integer),
                          'private',
                          jsonb_build_object('from', c.moving_from));
      end if;
    end if;

    update commanders set warned_at = now() where id = c.id;
  end loop;
end;
$$;


--
-- Name: archive_faction_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_faction_role(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_lead boolean; r record; m record;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_me;
  if not faction_power(v_me, v_fac, 'manage_roles') then
    raise exception 'Должностями управляет лидер и те, кому он это поручил';
  end if;
  perform pg_advisory_xact_lock(hashtext('faction_roles:' || v_fac));
  v_lead := is_faction_leader(v_me, v_fac);

  select * into r from faction_roles where id = p_id and faction = v_fac and not archived for update;
  if not found then raise exception 'Должность не найдена'; end if;

  if not v_lead then
    if exists (select 1 from faction_role_members where user_id = v_me and role_id = p_id) then
      raise exception 'Свою должность упраздняет лидер или тот, кто стоит выше';
    end if;
    if not (r.powers <@ my_faction_powers()) then
      raise exception 'Эта должность выше твоих полномочий';
    end if;
  end if;

  for m in select user_id from faction_role_members where role_id = p_id loop
    perform log_event(m.user_id, v_fac, null, 'role_removed', r.name, 1, 'private',
                      jsonb_build_object('by', (select nickname from profiles where id = v_me)));
  end loop;

  update faction_role_members set role_id = null, assigned_by = v_me, assigned_at = now()
  where role_id = p_id;
  update faction_roles set archived = true where id = p_id;
end;
$$;


--
-- Name: assert_dock_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_dock_ready(p_ship_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; v_station record; v_sys_faction text; v_busy record;
begin
  -- созревшие заказы выдаём сразу, не дожидаясь крона
  perform settle_due_orders();
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into s from ships where id = p_ship_id;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  perform assert_planet_operational(s.system_id);

  select * into v_station from space_stations where system_id = s.system_id for update;
  if not found then raise exception 'В этой системе нет космической станции'; end if;

  perform assert_production_access(v_user, s.system_id, null);

  if v_station.completes_at is not null and v_station.completes_at > now() then
    raise exception 'Станция ещё строится';
  end if;

  select faction into v_sys_faction from systems where id = s.system_id;
  if v_station.faction is distinct from v_sys_faction then
    raise exception 'Трофейная станция не работает на нового хозяина';
  end if;

  if not is_ship_at_dock(p_ship_id) then
    raise exception 'Подведи корабль к станции — док работает только у причала';
  end if;

  if exists (select 1 from repair_orders where ship_id = p_ship_id and not delivered) then
    raise exception 'Этот корабль уже в работе';
  end if;

  select * into v_busy from shipyard_busy(s.system_id);
  if found then
    raise exception 'Стапель занят: % будет готов через % с',
      v_busy.name,
      greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer);
  end if;
end;
$$;


--
-- Name: assert_planet_operational(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_planet_operational(p_system_id text) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
begin
  if is_capture_active(p_system_id) then
    raise exception 'На планете идёт захват — производство и стройка остановлены';
  end if;
end;
$$;


--
-- Name: assert_production_access(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_production_access(p_user uuid, p_system_id text, p_building_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare e text;
begin
  e := production_access_error(p_user, p_system_id, p_building_id);
  if e is not null then raise exception '%', e; end if;
end;
$$;


--
-- Name: assign_faction_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_faction_role(p_user_id uuid, p_role_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); v_fac text; v_lead boolean; v_mine text[];
  v_target_fac text; cur record; nr record; v_by text;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction, nickname into v_fac, v_by from profiles where id = v_me;
  if not faction_power(v_me, v_fac, 'manage_roles') then
    raise exception 'Назначает лидер и те, кому он это поручил';
  end if;
  perform pg_advisory_xact_lock(hashtext('faction_roles:' || v_fac));
  v_lead := is_faction_leader(v_me, v_fac);
  v_mine := my_faction_powers();

  select faction into v_target_fac from profiles where id = p_user_id;
  if v_target_fac is distinct from v_fac then raise exception 'Игрок не из твоей фракции'; end if;
  if is_faction_leader(p_user_id, v_fac) then
    raise exception 'Лидеру должность не нужна — у него все полномочия';
  end if;

  select r.* into cur from faction_role_members m join faction_roles r on r.id = m.role_id
  where m.user_id = p_user_id and r.faction = v_fac and not r.archived;

  if p_role_id is not null then
    select * into nr from faction_roles where id = p_role_id and faction = v_fac and not archived;
    if not found then raise exception 'Должность не найдена'; end if;
  end if;

  if not v_lead then
    if p_user_id = v_me then
      raise exception 'Свою должность меняет лидер или тот, кто стоит выше';
    end if;
    if cur.id is not null and not (cur.powers <@ v_mine) then
      raise exception 'Этот игрок выше тебя по полномочиям';
    end if;
    if p_role_id is not null and not (nr.powers <@ v_mine) then
      raise exception 'Эта должность выше твоих полномочий';
    end if;
  end if;

  if p_role_id is not distinct from cur.id then return; end if;

  insert into faction_role_members (user_id, role_id, assigned_by, assigned_at)
  values (p_user_id, p_role_id, v_me, now())
  on conflict (user_id) do update
    set role_id = excluded.role_id, assigned_by = excluded.assigned_by, assigned_at = excluded.assigned_at;

  -- Одно событие на назначение: игрок видит его у себя, фракция — в сводке
  if p_role_id is null then
    perform log_event(p_user_id, v_fac, null, 'role_removed', cur.name, 1, 'faction',
                      jsonb_build_object('by', v_by));
  else
    perform log_event(p_user_id, v_fac, null, 'role_assigned', nr.name, 1, 'faction',
                      jsonb_build_object('by', v_by));
  end if;
end;
$$;


--
-- Name: assign_ship(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_ship(p_ship_id uuid, p_commander_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_ship_system text;
  v_ship_owner uuid;
  v_ship_flying boolean;
  v_cmd_system text;
  v_cmd_moving text;
  v_cmd_unlocked boolean;
begin
  if v_user_id is null then
    raise exception 'Не авторизован';
  end if;

  select system_id, owner_user_id, in_transit
    into v_ship_system, v_ship_owner, v_ship_flying
  from ships where id = p_ship_id;

  if v_ship_system is null then
    raise exception 'Корабль не найден';
  end if;

  if v_ship_owner <> v_user_id then
    raise exception 'Это не твой корабль';
  end if;

  if v_ship_flying then
    raise exception 'Корабль в гиперпространстве';
  end if;

  if exists (select 1 from ships where id = p_ship_id and carrier_ship_id is not null) then
    raise exception 'Истребитель в ангаре летит вместе с носителем';
  end if;

  if p_commander_id is null then
    update ships set commander_id = null where id = p_ship_id;
    return;
  end if;

  select current_system, moving_to, unlocked
    into v_cmd_system, v_cmd_moving, v_cmd_unlocked
  from commanders where id = p_commander_id and user_id = v_user_id;

  if v_cmd_unlocked is null then
    raise exception 'Командир не найден';
  end if;

  if not v_cmd_unlocked then
    raise exception 'Командир ещё не разблокирован';
  end if;

  if v_cmd_moving is not null then
    raise exception 'Командир в пути';
  end if;

  if v_cmd_system is distinct from v_ship_system then
    raise exception 'Командир находится в другой системе';
  end if;

  update ships set commander_id = p_commander_id where id = p_ship_id;
end;
$$;


--
-- Name: automove_box_ok(text, text, uuid, integer, integer, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_box_ok(p_layer text, p_sys text, p_id uuid, p_x integer, p_y integer, p_w integer, p_h integer, p_faction text, p_vehicle boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_band text;
begin
  if p_layer = 'ground' then
    return ground_box_free_for(p_sys, p_x, p_y, p_w, p_h, p_id, p_faction, coalesce(p_vehicle, false));
  end if;
  v_band := hyperspace_band_at(p_y, p_h);
  if v_band is not null and v_band is distinct from hyperspace_side(p_sys, p_faction) then
    return false;
  end if;
  return is_ship_box_free(p_sys, p_x, p_y, p_w, p_h, p_id);
end;
$$;


--
-- Name: automove_close(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_close(p_id uuid, p_status text, p_reason text, p_x integer, p_y integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update auto_moves set status = p_status, stop_reason = p_reason, final_x = p_x, final_y = p_y,
         path = case when p_status = 'done' then '[]'::jsonb else path end,
         updated_at = now()
  where id = p_id and status = 'active';
end;
$$;


--
-- Name: automove_flags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_flags() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare g record; l record; v_n int; v_name text;
begin
  for g in
    select distinct on (f.group_key) f.group_key, f.layer, f.entity_id, f.x, f.y
    from auto_move_stops f
    where f.reason = 'damaged' and f.handled_at is null
    order by f.group_key, f.created_at
  loop
    update auto_moves m set status = 'stopped', stop_reason = 'damaged', updated_at = now(),
           final_x = case when m.layer = 'ground' then (select u.x from unit_positions u where u.id = m.unit_id)
                          else (select s.x from ships s where s.id = m.ship_id) end,
           final_y = case when m.layer = 'ground' then (select u.y from unit_positions u where u.id = m.unit_id)
                          else (select s.y from ships s where s.id = m.ship_id) end
    where m.id in (select b.id from auto_moves b
                   where (b.group_id = g.group_key or b.id = g.group_key) and b.status = 'active'
                   for update of b skip locked);

    if not exists (select 1 from auto_move_reports r where r.group_key = g.group_key) then
      select count(*) into v_n from auto_moves where group_id = g.group_key or id = g.group_key;
      select * into l from auto_moves where group_id = g.group_key or id = g.group_key order by member_idx limit 1;
      if found then
        insert into auto_move_reports (group_key, kind) values (g.group_key, 'damaged') on conflict do nothing;
        perform log_event(l.owner_user_id, l.faction, l.system_id, 'automove_stopped',
          case when v_n > 1 then 'Отряд: ' else '' end || coalesce(l.label, '') || ' — под огнём',
          v_n, 'private',
          jsonb_build_object(case when g.layer = 'space' then 'ship_id' else 'unit_id' end, g.entity_id,
                             'x', g.x, 'y', g.y, 'layer', g.layer,
                             'reason', 'damaged', 'count', v_n, 'group_id', l.group_id));
      end if;
    end if;

    -- Отметка закрыта, только когда весь отряд уже стоит
    if not exists (select 1 from auto_moves where (group_id = g.group_key or id = g.group_key) and status = 'active') then
      update auto_move_stops set handled_at = now()
      where group_key = g.group_key and reason = 'damaged' and handled_at is null;
    end if;
  end loop;

  for g in
    select f.group_key, count(*)::int as n,
           (array_agg(f.entity_id order by f.created_at))[1] as entity_id,
           (array_agg(f.layer order by f.created_at))[1] as layer,
           (array_agg(f.x order by f.created_at))[1] as x,
           (array_agg(f.y order by f.created_at))[1] as y
    from auto_move_stops f
    where f.reason = 'captured' and f.handled_at is null
    group by f.group_key
  loop
    select * into l from auto_moves
    where (group_id = g.group_key or id = g.group_key) and (unit_id = g.entity_id or ship_id = g.entity_id)
    order by started_at desc limit 1;
    if found then
      select count(*) into v_n from auto_moves where group_id = g.group_key or id = g.group_key;
      if g.layer = 'space' then
        select t.name into v_name from ships s join ship_types t on t.id = s.ship_type where s.id = g.entity_id;
      else
        select t.name into v_name from unit_positions u join unit_types t on t.id = u.unit_type where u.id = g.entity_id;
      end if;
      perform log_event(l.owner_user_id, l.faction, l.system_id, 'automove_stopped',
        case when v_n > 1 then 'Отряд: ' else '' end || coalesce(v_name, l.label, '') ||
        case when g.layer = 'space' then ' — корабль перехватили' else ' — бойца перехватили' end,
        g.n, 'private',
        jsonb_build_object(case when g.layer = 'space' then 'ship_id' else 'unit_id' end, g.entity_id,
                           'x', g.x, 'y', g.y, 'layer', g.layer,
                           'reason', 'captured', 'count', g.n, 'group_id', l.group_id));
    end if;
    update auto_move_stops set handled_at = now()
    where group_key = g.group_key and reason = 'captured' and handled_at is null;
  end loop;

  -- ручные/отменённые отметки, по которым строки уже не активны, закрываем
  update auto_move_stops f set handled_at = now()
  where f.reason in ('manual', 'cancelled') and f.handled_at is null
    and not exists (select 1 from auto_moves a where a.status = 'active'
                    and (a.unit_id = f.entity_id or a.ship_id = f.entity_id));
end;
$$;


--
-- Name: automove_hop_clear(text, text, integer, integer, integer, integer, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_hop_clear(p_layer text, p_sys text, p_x0 integer, p_y0 integer, p_x1 integer, p_y1 integer, p_w integer, p_h integer, p_faction text, p_vehicle boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with n as (select greatest(abs(p_x1 - p_x0), abs(p_y1 - p_y0)) as n),
  pts as (
    select p_x0 + floor((2 * (p_x1 - p_x0) * k + n.n)::numeric / (2 * n.n))::int as px,
           p_y0 + floor((2 * (p_y1 - p_y0) * k + n.n)::numeric / (2 * n.n))::int as py
    from n cross join lateral generate_series(1, n.n) k
    where n.n > 0)
  select not exists (
    select 1 from pts, automove_obstacles(p_layer, p_sys, p_faction, p_vehicle) o
    where pts.px < o.ox + o.ow and pts.px + p_w > o.ox
      and pts.py < o.oy + o.oh and pts.py + p_h > o.oy
      and not (p_x0 < o.ox + o.ow and p_x0 + p_w > o.ox and p_y0 < o.oy + o.oh and p_y0 + p_h > o.oy));
$$;


--
-- Name: automove_manual(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_manual(p_layer text, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_x int; v_y int;
begin
  if coalesce(current_setting('app.automove', true), '') = '1' then return; end if;
  if not exists (select 1 from auto_moves where status = 'active'
                 and ((p_layer = 'ground' and unit_id = p_id) or (p_layer = 'space' and ship_id = p_id))) then
    return;
  end if;

  if p_layer = 'ground' then
    select x, y into v_x, v_y from unit_positions where id = p_id;
  else
    select x, y into v_x, v_y from ships where id = p_id;
  end if;

  update auto_moves m set status = 'stopped', stop_reason = 'manual', final_x = v_x, final_y = v_y, updated_at = now()
  where m.id in (select b.id from auto_moves b where b.status = 'active'
                   and ((p_layer = 'ground' and b.unit_id = p_id) or (p_layer = 'space' and b.ship_id = p_id))
                 for update of b skip locked);
  if not found then
    -- строку держит другая транзакция — отметка, тик снимет автоход
    insert into auto_move_stops (group_key, reason, layer, entity_id, x, y)
    select coalesce(a.group_id, a.id), 'manual', p_layer, p_id, v_x, v_y from auto_moves a
    where a.status = 'active' and ((p_layer = 'ground' and a.unit_id = p_id) or (p_layer = 'space' and a.ship_id = p_id))
    limit 1;
  end if;
end;
$$;


--
-- Name: automove_obstacles(text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_obstacles(p_layer text, p_sys text, p_faction text, p_vehicle boolean) RETURNS TABLE(ox integer, oy integer, ow integer, oh integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select ps.x, ps.y, 6, 6 from planet_slots ps
   where p_layer = 'ground' and ps.system_id = p_sys
  union all
  select sb.x, sb.y, sb.size, sb.size from settlement_box() sb where p_layer = 'ground'
  union all
  select s.x, s.y, s.w, s.h from field_structures s join structure_types st on st.id = s.type_id
   where p_layer = 'ground' and s.system_id = p_sys and s.faction = p_faction
     and (not st.enterable or (st.infantry_only and coalesce(p_vehicle, false)))
  union all
  select z.x, z.y, z.size, z.size from station_slots z where p_layer = 'space' and z.system_id = p_sys
  union all
  select 0,
         case when hyperspace_side(p_sys, p_faction) = 'top'
              then game_setting_int('space_grid_cells', 150) - game_setting_int('hyperspace_zone_height', 14)
              else 0 end,
         game_setting_int('space_grid_cells', 150), game_setting_int('hyperspace_zone_height', 14)
   where p_layer = 'space';
$$;


--
-- Name: automove_on_damage(text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_on_damage(p_layer text, p_id uuid, p_x integer, p_y integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_grp uuid;
begin
  select coalesce(a.group_id, a.id) into v_grp from auto_moves a
  where a.status = 'active' and ((p_layer = 'ground' and a.unit_id = p_id) or (p_layer = 'space' and a.ship_id = p_id))
  limit 1;
  if not found then return; end if;

  insert into auto_move_stops (group_key, reason, layer, entity_id, x, y)
  values (v_grp, 'damaged', p_layer, p_id, p_x, p_y);

  update auto_moves m set status = 'stopped', stop_reason = 'damaged', updated_at = now(),
         final_x = case when m.layer = 'ground' then (select u.x from unit_positions u where u.id = m.unit_id)
                        else (select s.x from ships s where s.id = m.ship_id) end,
         final_y = case when m.layer = 'ground' then (select u.y from unit_positions u where u.id = m.unit_id)
                        else (select s.y from ships s where s.id = m.ship_id) end
  where m.id in (select b.id from auto_moves b
                 where (b.group_id = v_grp or b.id = v_grp) and b.status = 'active'
                 for update of b skip locked);
end;
$$;


--
-- Name: automove_path(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_path(p_x0 integer, p_y0 integer, p_x1 integer, p_y1 integer, p_range integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_array(
           p_x0 + floor((2 * (p_x1 - p_x0) * k + q.n)::numeric / (2 * q.n))::int,
           p_y0 + floor((2 * (p_y1 - p_y0) * k + q.n)::numeric / (2 * q.n))::int) order by k), '[]'::jsonb)
  from (select ceil(greatest(abs(p_x1 - p_x0), abs(p_y1 - p_y0))::numeric / greatest(1, p_range))::int as n) q
  cross join lateral generate_series(1, q.n) k;
$$;


--
-- Name: automove_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_report() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  g record; l record;
  v_n int; v_arr int; v_near int; v_blk int; v_dmg int;
  v_type text; v_reason text; v_subject text;
begin
  for g in
    select distinct coalesce(a.group_id, a.id) as gk
    from auto_moves a
    where a.status <> 'active' and a.updated_at > now() - interval '30 minutes'
      and not exists (select 1 from auto_move_reports r where r.group_key = coalesce(a.group_id, a.id))
  loop
    continue when exists (select 1 from auto_moves b where (b.group_id = g.gk or b.id = g.gk) and b.status = 'active');

    select count(*), count(*) filter (where status = 'done'),
           count(*) filter (where stop_reason = 'arrived_near'),
           count(*) filter (where stop_reason = 'blocked'),
           count(*) filter (where stop_reason = 'damaged')
      into v_n, v_arr, v_near, v_blk, v_dmg
    from auto_moves where group_id = g.gk or id = g.gk;

    -- Урон сообщает automove_flags
    continue when v_dmg > 0;

    if v_arr > 0 then
      v_type := 'automove_arrived';
      v_reason := case when v_near > 0 then 'arrived_near' else 'arrived' end;
    elsif v_blk > 0 then
      v_type := 'automove_stopped';
      v_reason := 'blocked';
    else
      -- отмена, ручной ход, посадка/прыжок/гибель — без события
      insert into auto_move_reports (group_key, kind) values (g.gk, 'silent') on conflict do nothing;
      continue;
    end if;

    select * into l from auto_moves
    where group_id = g.gk or id = g.gk
    order by case when v_type = 'automove_arrived' then (status <> 'done')
                  else (stop_reason is distinct from 'blocked') end,
             member_idx
    limit 1;

    v_subject := case when v_n > 1 then 'Отряд: ' else '' end || coalesce(l.label, '') ||
      case
        when v_type = 'automove_stopped' then ' — путь перекрыт'
        when v_arr < v_n then ' — дошли не все'
        when v_near > 0 then ' — рядом с целью: точка занята'
        else ''
      end;

    insert into auto_move_reports (group_key, kind) values (g.gk, v_type) on conflict do nothing;
    if found then
      perform log_event(l.owner_user_id, l.faction, l.system_id, v_type, v_subject, v_n, 'private',
        jsonb_build_object(case when l.layer = 'space' then 'ship_id' else 'unit_id' end,
                           coalesce(l.ship_id, l.unit_id),
                           'x', l.final_x, 'y', l.final_y, 'layer', l.layer,
                           'reason', v_reason, 'count', v_n, 'arrived', v_arr, 'group_id', l.group_id));
    end if;
  end loop;
end;
$$;


--
-- Name: automove_route(text, text, integer, integer, integer, integer, integer, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_route(p_layer text, p_sys text, p_x0 integer, p_y0 integer, p_x1 integer, p_y1 integer, p_w integer, p_h integer, p_range integer, p_faction text, p_vehicle boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  g int; mx int; my int; m int := 14; r int := greatest(1, coalesce(p_range, 1));
  tx int; ty int; rx0 int; ry0 int; rx1 int; ry1 int; rw int; rh int; n int;
  blk boolean[]; par int[]; q int[]; qh int := 1; qt int := 0;
  o record; ax int; ay int; bx int; by_ int; xx int; yy int;
  s int; t int; cur int; cx int; cy int; nx int; ny int; ni int; i int; j int; k int;
  best int; bestd int; beste int; dd int; ee int; sblk boolean;
  path int[]; plen int; hops jsonb; prevx int; prevy int; px int; py int; hx int; hy int;
  ok boolean; steps int; res jsonb := '[]'::jsonb; ring int; found boolean;
  dxs int[] := array[1, -1, 0, 0, 1, 1, -1, -1];
  dys int[] := array[0, 0, 1, -1, 1, -1, 1, -1];
begin
  g := case when p_layer = 'ground' then game_setting_int('ground_grid_cells', 144)
            else game_setting_int('space_grid_cells', 150) end;
  mx := g - p_w; my := g - p_h;
  tx := least(greatest(p_x1, 0), mx); ty := least(greatest(p_y1, 0), my);
  if p_x0 = tx and p_y0 = ty then return '[]'::jsonb; end if;

  rx0 := greatest(0, least(p_x0, tx) - m); rx1 := least(mx, greatest(p_x0, tx) + m);
  ry0 := greatest(0, least(p_y0, ty) - m); ry1 := least(my, greatest(p_y0, ty) + m);
  rx0 := least(rx0, p_x0); ry0 := least(ry0, p_y0); rx1 := greatest(rx1, p_x0); ry1 := greatest(ry1, p_y0);
  rw := rx1 - rx0 + 1; rh := ry1 - ry0 + 1; n := rw * rh;

  blk := array_fill(false, array[n]);
  for o in select * from automove_obstacles(p_layer, p_sys, p_faction, p_vehicle) loop
    ax := greatest(rx0, o.ox - p_w + 1); bx := least(rx1, o.ox + o.ow - 1);
    ay := greatest(ry0, o.oy - p_h + 1); by_ := least(ry1, o.oy + o.oh - 1);
    if ax <= bx and ay <= by_ then
      for yy in ay .. by_ loop
        for xx in ax .. bx loop
          blk[(yy - ry0) * rw + (xx - rx0) + 1] := true;
        end loop;
      end loop;
    end if;
  end loop;

  s := (p_y0 - ry0) * rw + (p_x0 - rx0) + 1;
  t := (ty - ry0) * rw + (tx - rx0) + 1;
  sblk := blk[s];

  hops := automove_path(p_x0, p_y0, tx, ty, r);
  ok := true; prevx := p_x0; prevy := p_y0;
  for i in 0 .. jsonb_array_length(hops) - 1 loop
    hx := (hops -> i ->> 0)::int; hy := (hops -> i ->> 1)::int;
    steps := greatest(abs(hx - prevx), abs(hy - prevy));
    for k in 1 .. steps loop
      px := prevx + floor((2 * (hx - prevx) * k + steps)::numeric / (2 * steps))::int;
      py := prevy + floor((2 * (hy - prevy) * k + steps)::numeric / (2 * steps))::int;
      if blk[(py - ry0) * rw + (px - rx0) + 1] and not (sblk and i = 0) then ok := false; exit; end if;
    end loop;
    exit when not ok;
    prevx := hx; prevy := hy;
  end loop;
  if ok then return hops; end if;

  if blk[t] then
    found := false;
    for ring in 1 .. greatest(rw, rh) loop
      best := null; bestd := null;
      for yy in greatest(ry0, ty - ring) .. least(ry1, ty + ring) loop
        for xx in greatest(rx0, tx - ring) .. least(rx1, tx + ring) loop
          continue when greatest(abs(xx - tx), abs(yy - ty)) <> ring;
          ni := (yy - ry0) * rw + (xx - rx0) + 1;
          continue when blk[ni];
          ee := (xx - tx) * (xx - tx) + (yy - ty) * (yy - ty)
              + (xx - p_x0) * (xx - p_x0) + (yy - p_y0) * (yy - p_y0);
          if best is null or ee < bestd then best := ni; bestd := ee; end if;
        end loop;
      end loop;
      if best is not null then t := best; found := true; exit; end if;
    end loop;
    if not found or t = s then return '[]'::jsonb; end if;
    tx := rx0 + (t - 1) % rw; ty := ry0 + (t - 1) / rw;
  end if;

  par := array_fill(0, array[n]);
  q := array_fill(0, array[n]);
  par[s] := s; qt := 1; q[1] := s;
  best := s; bestd := greatest(abs(p_x0 - tx), abs(p_y0 - ty));
  beste := (p_x0 - tx) * (p_x0 - tx) + (p_y0 - ty) * (p_y0 - ty);
  while qh <= qt loop
    cur := q[qh]; qh := qh + 1;
    exit when cur = t;
    cx := rx0 + (cur - 1) % rw; cy := ry0 + (cur - 1) / rw;
    dd := greatest(abs(cx - tx), abs(cy - ty));
    ee := (cx - tx) * (cx - tx) + (cy - ty) * (cy - ty);
    if dd < bestd or (dd = bestd and ee < beste) then best := cur; bestd := dd; beste := ee; end if;
    for i in 1 .. 8 loop
      nx := cx + dxs[i]; ny := cy + dys[i];
      continue when nx < rx0 or nx > rx1 or ny < ry0 or ny > ry1;
      ni := (ny - ry0) * rw + (nx - rx0) + 1;
      continue when par[ni] <> 0;
      continue when blk[ni] and not (blk[cur] and sblk);
      if i > 4 and not (blk[cur] and sblk) then
        continue when blk[(cy - ry0) * rw + (nx - rx0) + 1] or blk[(ny - ry0) * rw + (cx - rx0) + 1];
      end if;
      par[ni] := cur; qt := qt + 1; q[qt] := ni;
    end loop;
  end loop;
  if par[t] <> 0 then best := t; end if;
  if best = s then return '[]'::jsonb; end if;

  path := '{}'; cur := best;
  while cur <> s loop
    path := cur || path;
    cur := par[cur];
  end loop;
  plen := coalesce(array_length(path, 1), 0);

  prevx := p_x0; prevy := p_y0; i := 0;
  while i < plen loop
    j := least(plen, i + r);
    loop
      hx := rx0 + (path[j] - 1) % rw; hy := ry0 + (path[j] - 1) / rw;
      exit when j = i + 1;
      ok := not blk[path[j]];
      if ok and greatest(abs(hx - prevx), abs(hy - prevy)) <= r then
        steps := greatest(abs(hx - prevx), abs(hy - prevy));
        for k in 1 .. steps loop
          px := prevx + floor((2 * (hx - prevx) * k + steps)::numeric / (2 * steps))::int;
          py := prevy + floor((2 * (hy - prevy) * k + steps)::numeric / (2 * steps))::int;
          if blk[(py - ry0) * rw + (px - rx0) + 1]
             and not (sblk and blk[(prevy - ry0) * rw + (prevx - rx0) + 1]) then ok := false; exit; end if;
        end loop;
      else
        ok := false;
      end if;
      exit when ok;
      j := j - 1;
    end loop;
    res := res || jsonb_build_array(jsonb_build_array(hx, hy));
    prevx := hx; prevy := hy; i := j;
  end loop;
  return res;
end;
$$;


--
-- Name: automove_ship_hp_trg(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_ship_hp_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (select 1 from auto_moves where ship_id = new.id and status = 'active') then
    perform automove_on_damage('space', new.id, new.x, new.y);
  end if;
  return null;
end;
$$;


--
-- Name: automove_step(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_step(p_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  am record; e record;
  v_eid uuid; v_cx int; v_cy int; v_w int; v_h int; v_fac text; v_veh boolean := false;
  v_cd int; v_max int := game_setting_int('ship_action_max', 2); v_el int; v_ap int;
  v_own int; v_range int; v_grid int; v_path jsonb; v_px int; v_py int; v_final boolean;
  v_nx int; v_ny int; v_new_path jsonb; v_reason text; v_ok boolean; v_err text; v_prev text;
  v_cur_ring int; v_cur_d int; c record; v_grp uuid; v_mate boolean; v_bt int; v_tick text; v_flag text;
begin
  select * into am from auto_moves where id = p_id;
  if not found or am.status <> 'active' then return 'skip'; end if;

  -- Порядок: сначала юнит/корабль, потом строка автохода; занято — пропускаем до следующего тика
  if am.layer = 'ground' then
    select u.*, t.width_cells as tw, t.height_cells as th, t.is_vehicle as tveh, t.action_seconds as tcd
      into e
    from unit_positions u join unit_types t on t.id = u.unit_type
    where u.id = am.unit_id for update of u skip locked;
  else
    select s.*, t.width_cells as tw, t.height_cells as th
      into e
    from ships s join ship_types t on t.id = s.ship_type
    where s.id = am.ship_id for update of s skip locked;
  end if;
  if not found then return 'busy'; end if;

  select * into am from auto_moves where id = p_id for update skip locked;
  if not found then return 'busy'; end if;
  if am.status <> 'active' then return 'skip'; end if;
  v_grp := coalesce(am.group_id, am.id);

  -- Отметки, оставленные без ожидания блокировок
  if exists (select 1 from auto_move_stops f where f.group_key = v_grp and f.reason = 'damaged') then
    perform automove_close(am.id, 'stopped', 'damaged', e.x, e.y);
    return 'damaged';
  end if;
  select f.reason into v_flag from auto_move_stops f
  where f.entity_id = e.id and f.reason in ('manual', 'cancelled') and f.created_at >= am.started_at
  order by f.created_at limit 1;
  if v_flag is not null then
    perform automove_close(am.id, 'stopped', v_flag, e.x, e.y);
    return v_flag;
  end if;

  -- Перехват (подчинение разума, захват): автоход прежнего хозяина снимается с событием
  if e.owner_user_id is distinct from am.owner_user_id then
    perform automove_close(am.id, 'stopped', 'lost', e.x, e.y);
    insert into auto_move_stops (group_key, reason, layer, entity_id, x, y)
    values (v_grp, 'captured', am.layer, e.id, e.x, e.y);
    return 'captured';
  end if;

  -- Потерян: посадка, транзит, ангар, гибель
  if am.layer = 'ground' then
    if e.system_id is distinct from am.system_id
       or e.layer is distinct from 'ground' or e.x is null or e.carrier_unit_id is not null
       or e.carrier_ship_id is not null or e.transit_to is not null or e.hp <= 0 then
      perform automove_close(am.id, 'stopped', 'lost', e.x, e.y);
      return 'lost';
    end if;
    v_eid := e.id; v_cx := e.x; v_cy := e.y; v_w := e.tw; v_h := e.th; v_fac := e.faction;
    v_veh := coalesce(e.tveh, false);
    v_grid := game_setting_int('ground_grid_cells', 144);

    -- Ждём, не отменяя: обучение
    if e.training_until is not null and e.training_until > now() then return 'wait'; end if;

    v_cd := coalesce(e.tcd, game_setting_int('ship_action_cooldown_seconds', 30));
    select us.move_range into v_own from unit_stats(e.id) us;
  else
    if e.system_id is distinct from am.system_id
       or e.in_transit or e.carrier_ship_id is not null or e.x is null or e.hp <= 0 then
      perform automove_close(am.id, 'stopped', 'lost', e.x, e.y);
      return 'lost';
    end if;
    v_eid := e.id; v_cx := e.x; v_cy := e.y; v_fac := e.faction;
    v_w := ship_box_w(e.tw, e.th, e.facing);
    v_h := ship_box_h(e.tw, e.th, e.facing);
    v_grid := game_setting_int('space_grid_cells', 150);

    v_cd := game_setting_int('ship_action_cooldown_seconds', 30);
    select ss.move_range into v_own from ship_stats(e.id) ss;
  end if;

  -- ОД (как unit_ap_state / ship_ap_state)
  v_el := floor(extract(epoch from now() - coalesce(e.ap_updated_at, now())))::int;
  v_ap := least(v_max, coalesce(e.ap, 0) + v_el / greatest(1, v_cd));
  if v_ap < 1 then return 'wait'; end if;

  v_range := greatest(1, least(am.step_range, coalesce(v_own, am.step_range)));

  -- Защита от бесконечных обходов
  if am.steps_done >= 2 * ceil(v_grid::numeric / v_range)::int + 20 then
    perform automove_close(am.id, 'stopped', 'blocked', v_cx, v_cy);
    return 'blocked';
  end if;

  v_path := am.path;
  while jsonb_array_length(v_path) > 0
        and (v_path -> 0 ->> 0)::int = v_cx and (v_path -> 0 ->> 1)::int = v_cy loop
    v_path := v_path - 0;
  end loop;

  if jsonb_array_length(v_path) = 0 then
    perform automove_close(am.id, 'done',
      case when v_cx = am.target_x and v_cy = am.target_y then 'arrived' else 'arrived_near' end, v_cx, v_cy);
    return 'arrived';
  end if;

  if greatest(abs((v_path -> 0 ->> 0)::int - v_cx), abs((v_path -> 0 ->> 1)::int - v_cy)) > v_range then
    v_path := automove_route(am.layer, am.system_id, v_cx, v_cy, am.target_x, am.target_y,
                             v_w, v_h, v_range, v_fac, v_veh);
    update auto_moves set path = v_path, step_range = v_range where id = am.id;
  end if;

  v_px := (v_path -> 0 ->> 0)::int;
  v_py := (v_path -> 0 ->> 1)::int;
  v_final := jsonb_array_length(v_path) = 1;
  v_reason := null;

  if automove_box_ok(am.layer, am.system_id, v_eid, v_px, v_py, v_w, v_h, v_fac, v_veh)
     and automove_hop_clear(am.layer, am.system_id, v_cx, v_cy, v_px, v_py, v_w, v_h, v_fac, v_veh) then
    v_nx := v_px; v_ny := v_py;
    v_new_path := v_path - 0;
    if v_final then v_reason := 'arrived'; end if;
  else
    if am.group_id is not null and am.blocked_ticks < 2 then
      if am.layer = 'ground' then
        select exists (
          select 1 from auto_moves b
          join unit_positions m on m.id = b.unit_id
          join unit_types mt on mt.id = m.unit_type
          where b.group_id = am.group_id and b.status = 'active' and b.id <> am.id and m.x is not null
            and boxes_overlap(v_px, v_py, v_w, v_h, m.x, m.y, mt.width_cells, mt.height_cells)) into v_mate;
      else
        select exists (
          select 1 from auto_moves b
          join ships m on m.id = b.ship_id
          join ship_types mt on mt.id = m.ship_type
          where b.group_id = am.group_id and b.status = 'active' and b.id <> am.id and m.x is not null
            and boxes_overlap(v_px, v_py, v_w, v_h, m.x, m.y,
                              ship_box_w(mt.width_cells, mt.height_cells, m.facing),
                              ship_box_h(mt.width_cells, mt.height_cells, m.facing))) into v_mate;
      end if;
      if v_mate then
        update auto_moves set blocked_ticks = blocked_ticks + 1, updated_at = now() where id = am.id;
        return 'wait_mate';
      end if;
    end if;

    if v_final then
      v_cur_ring := greatest(abs(v_cx - am.target_x), abs(v_cy - am.target_y));
      for c in
        select q.cx, q.cy from (
          select am.target_x + dx as cx, am.target_y + dy as cy,
                 greatest(abs(dx), abs(dy)) as ring, dx * dx + dy * dy as e2
          from generate_series(-4, 4) dx, generate_series(-4, 4) dy) q
        where q.ring between 1 and 4 and q.ring < v_cur_ring
          and greatest(abs(q.cx - v_cx), abs(q.cy - v_cy)) between 1 and v_range
        order by q.ring, q.e2, greatest(abs(q.cx - v_cx), abs(q.cy - v_cy)), q.cy, q.cx
      loop
        if automove_box_ok(am.layer, am.system_id, v_eid, c.cx, c.cy, v_w, v_h, v_fac, v_veh)
           and automove_hop_clear(am.layer, am.system_id, v_cx, v_cy, c.cx, c.cy, v_w, v_h, v_fac, v_veh) then
          v_nx := c.cx; v_ny := c.cy; exit;
        end if;
      end loop;

      if v_nx is not null then
        v_new_path := '[]'::jsonb;
        v_reason := 'arrived_near';
      elsif v_cur_ring <= 4 then
        perform automove_close(am.id, 'done', 'arrived_near', v_cx, v_cy);
        return 'arrived_near';
      end if;
    else
      v_cur_d := greatest(abs(v_cx - am.target_x), abs(v_cy - am.target_y));
      for c in
        select q.cx, q.cy from (
          select v_px + dx as cx, v_py + dy as cy,
                 greatest(abs(dx), abs(dy)) as ring
          from generate_series(-3, 3) dx, generate_series(-3, 3) dy) q
        where q.ring between 1 and 3
          and greatest(abs(q.cx - v_cx), abs(q.cy - v_cy)) between 1 and v_range
          and greatest(abs(q.cx - am.target_x), abs(q.cy - am.target_y)) <= v_cur_d
        order by q.ring,
                 greatest(abs(q.cx - am.target_x), abs(q.cy - am.target_y)),
                 (q.cx - am.target_x) * (q.cx - am.target_x) + (q.cy - am.target_y) * (q.cy - am.target_y),
                 q.cy, q.cx
      loop
        if automove_box_ok(am.layer, am.system_id, v_eid, c.cx, c.cy, v_w, v_h, v_fac, v_veh)
           and automove_hop_clear(am.layer, am.system_id, v_cx, v_cy, c.cx, c.cy, v_w, v_h, v_fac, v_veh) then
          v_nx := c.cx; v_ny := c.cy; exit;
        end if;
      end loop;

      if v_nx is not null then
        v_new_path := automove_route(am.layer, am.system_id, v_nx, v_ny, am.target_x, am.target_y,
                                     v_w, v_h, v_range, v_fac, v_veh);
        if jsonb_array_length(v_new_path) = 0 then v_reason := 'arrived'; end if;
      end if;
    end if;
  end if;

  if v_nx is null then
    update auto_moves set blocked_ticks = blocked_ticks + 1, updated_at = now()
    where id = am.id returning blocked_ticks into v_bt;
    if v_bt >= 3 then
      perform automove_close(am.id, 'stopped', 'blocked', v_cx, v_cy);
      return 'blocked';
    end if;
    return 'blocked_wait';
  end if;

  v_prev := current_setting('request.jwt.claims', true);
  v_tick := current_setting('app.automove', true);
  perform set_config('request.jwt.claims',
    json_build_object('sub', am.owner_user_id::text, 'role', 'authenticated')::text, true);
  perform set_config('app.automove', '1', true);
  v_ok := true;
  begin
    if am.layer = 'ground' then
      perform move_ground_unit(v_eid, v_nx, v_ny);
    else
      perform move_ship(v_eid, v_nx, v_ny, null::integer);
    end if;
  exception when others then perform err_db('automove_step', sqlstate, sqlerrm, false);
    v_ok := false;
    v_err := sqlerrm;
  end;
  perform set_config('app.automove', coalesce(v_tick, ''), true);
  perform set_config('request.jwt.claims', coalesce(v_prev, ''), true);

  if not v_ok then
    if v_err like 'Юнит ещё не готов%' or v_err like 'Действие ещё не восстановилось%'
       or v_err like 'Боец оглушён%' or v_err like 'Боец прижат огнём%'
       or v_err like '%притягивающим лучом%' then
      return 'wait';
    end if;
    update auto_moves set blocked_ticks = blocked_ticks + 1, updated_at = now()
    where id = am.id returning blocked_ticks into v_bt;
    if v_bt >= 3 then
      perform automove_close(am.id, 'stopped', 'blocked', v_cx, v_cy);
      return 'blocked';
    end if;
    return 'error: ' || v_err;
  end if;

  -- Разведчика могла сжечь глушилка: строки уже нет
  update auto_moves set path = v_new_path, steps_done = steps_done + 1, blocked_ticks = 0,
         last_step_at = now(), updated_at = now()
  where id = am.id;
  if not found then return 'gone'; end if;

  if jsonb_array_length(v_new_path) = 0 then
    perform automove_close(am.id, 'done', coalesce(v_reason, 'arrived'), v_nx, v_ny);
    return coalesce(v_reason, 'arrived');
  end if;
  return 'step';
end;
$$;


--
-- Name: automove_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_max int := game_setting_int('ship_action_max', 2);
  v_cd int := game_setting_int('ship_action_cooldown_seconds', 30);
begin
  if not pg_try_advisory_xact_lock(hashtext('automove_tick')) then return; end if;

  begin perform automove_flags();
  exception when others then perform err_db('automove_tick', sqlstate, sqlerrm, true); raise warning 'automove_flags: %', sqlerrm; end;

  for r in
    select a.id
    from auto_moves a
    left join unit_positions u on a.layer = 'ground' and u.id = a.unit_id
    left join unit_types t on t.id = u.unit_type
    left join ships s on a.layer = 'space' and s.id = a.ship_id
    where a.status = 'active'
      and case when a.layer = 'ground' then
            u.id is null or u.x is null or u.transit_to is not null or u.carrier_unit_id is not null
            or u.carrier_ship_id is not null or u.owner_user_id <> a.owner_user_id
            or u.system_id <> a.system_id or u.hp <= 0
            or least(v_max, u.ap + floor(extract(epoch from now() - coalesce(u.ap_updated_at, now())))::int
                                   / greatest(1, coalesce(t.action_seconds, v_cd))) >= 1
          else
            s.id is null or s.x is null or s.in_transit or s.carrier_ship_id is not null
            or s.owner_user_id <> a.owner_user_id or s.system_id <> a.system_id or s.hp <= 0
            or least(v_max, s.ap + floor(extract(epoch from now() - coalesce(s.ap_updated_at, now())))::int
                                   / greatest(1, v_cd)) >= 1
          end
    order by coalesce(a.group_id, a.id),
             (coalesce(u.x, s.x) * (a.target_x - coalesce(u.x, s.x))
              + coalesce(u.y, s.y) * (a.target_y - coalesce(u.y, s.y))) desc nulls last,
             a.member_idx
  loop
    begin
      perform automove_step(r.id);
    exception when others then perform err_db('automove_tick', sqlstate, sqlerrm, true);
      raise warning 'automove_tick %: %', r.id, sqlerrm;
    end;
  end loop;

  begin perform automove_flags();
  exception when others then perform err_db('automove_tick', sqlstate, sqlerrm, true); raise warning 'automove_flags: %', sqlerrm; end;
  begin perform automove_report();
  exception when others then perform err_db('automove_tick', sqlstate, sqlerrm, true); raise warning 'automove_report: %', sqlerrm; end;
end;
$$;


--
-- Name: automove_unit_hp_trg(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automove_unit_hp_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (select 1 from auto_moves where unit_id = new.id and status = 'active') then
    perform automove_on_damage('ground', new.id, new.x, new.y);
  end if;
  return null;
end;
$$;


--
-- Name: boarding_drop_ship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.boarding_drop_ship(p_ship uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  delete from ships where id = p_ship;
$$;


--
-- Name: box_gap(integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.box_gap(ax integer, ay integer, aw integer, ah integer, bx integer, by integer, bw integer, bh integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(greatest(bx - (ax + aw - 1), ax - (bx + bw - 1), 0),
                  greatest(by - (ay + ah - 1), ay - (by + bh - 1), 0));
$$;


--
-- Name: boxes_overlap(integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.boxes_overlap(ax integer, ay integer, aw integer, ah integer, bx integer, by integer, bw integer, bh integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select ax < bx + bw and ax + aw > bx and ay < by + bh and ay + ah > by;
$$;


--
-- Name: build_district(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_district(p_system_id text, p_slot integer, p_district text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_faction text; v_credits integer; st record; dt record; v_slots integer;
        v_until timestamptz;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  if not exists (select 1 from system_control where system_id = p_system_id and controller_user_id = v_me) then
    raise exception 'Кварталы строит только управляющий планетой';
  end if;
  perform assert_planet_operational(p_system_id);

  select faction, credits into v_faction, v_credits from profiles where id = v_me for update;
  if (select faction from systems where id = p_system_id) is distinct from v_faction then
    raise exception 'Планета чужой фракции';
  end if;

  select * into st from settlement_state where system_id = p_system_id for update;
  if not found then raise exception 'Поселение не найдено'; end if;
  select district_slots into v_slots from settlement_levels where level = st.level;
  if p_slot is null or p_slot < 1 or p_slot > v_slots then
    raise exception 'Этот участок откроется на следующем уровне поселения';
  end if;

  select * into dt from district_types where id = p_district;
  if not found then raise exception 'Неизвестный квартал'; end if;
  if exists (select 1 from settlement_districts where system_id = p_system_id and slot = p_slot) then
    raise exception 'Участок уже занят';
  end if;
  if exists (select 1 from settlement_districts where system_id = p_system_id and district_id = p_district) then
    raise exception 'Такой квартал уже есть';
  end if;
  if v_credits < dt.cost_credits then raise exception 'Не хватает кредитов: нужно %', dt.cost_credits; end if;

  perform take_build_resources(p_system_id, dt.cost_resources, 1);
  update profiles set credits = credits - dt.cost_credits where id = v_me;

  v_until := now() + make_interval(secs => dt.build_seconds);
  insert into settlement_districts (system_id, slot, district_id, completes_at, built_by)
  values (p_system_id, p_slot, p_district, v_until, v_me);
  perform log_event(v_me, v_faction, p_system_id, 'district_started', dt.name, 1, 'private',
                    jsonb_build_object('slot', p_slot, 'until', v_until));
  return v_until;
end;
$$;


--
-- Name: build_structure(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_structure(p_unit_id uuid, p_type text, p_x integer, p_y integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; ut record; st record; sys record;
  v_faction text; v_credits integer;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
  v_attack integer := game_setting_int('ground_attack_zone_height', 4);
  v_range integer := game_setting_int('engineer_build_range', 2);
  v_slot integer := 6;
  v_id uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.x is null or u.layer <> 'ground' then raise exception 'Инженер должен стоять на земле'; end if;
  if u.hp <= 0 then raise exception 'Юнит уничтожен'; end if;

  select * into ut from unit_types where id = u.unit_type;
  if not coalesce(ut.can_build, false) then raise exception 'Строить умеет только инженер'; end if;

  select * into st from structure_types where id = p_type;
  if not found then raise exception 'Неизвестная постройка'; end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user for update;
  if st.faction is distinct from v_faction or u.faction is distinct from v_faction then
    raise exception 'Эта постройка не для твоей фракции';
  end if;

  if st.research_id is not null and not exists (
    select 1 from player_research where user_id = v_user and research_id = st.research_id
  ) then
    raise exception 'Сначала изучи: %', (select name from researches where id = st.research_id);
  end if;

  select id, faction, is_deep_space into sys from systems where id = u.system_id;
  if sys.faction is distinct from v_faction or coalesce(sys.is_deep_space, false) then
    raise exception 'Инженер строит только на планетах своей фракции';
  end if;

  perform assert_planet_operational(u.system_id);
  perform pg_advisory_xact_lock(hashtext('field_structures:' || u.system_id));

  if p_x is null or p_y is null or p_x < 0 or p_y < 0
     or p_x + st.width_cells > v_grid or p_y + st.height_cells > v_grid then
    raise exception 'Место вне карты';
  end if;

  if p_y + st.height_cells > v_grid - v_attack then
    raise exception 'В полосе вторжения не строят';
  end if;

  if box_gap(u.x, u.y, ut.width_cells, ut.height_cells, p_x, p_y, st.width_cells, st.height_cells) > v_range then
    raise exception 'Слишком далеко: инженер строит не дальше % клеток от себя', v_range;
  end if;

  if exists (select 1 from deploy_zones z where z.system_id = u.system_id
             and boxes_overlap(p_x, p_y, st.width_cells, st.height_cells, z.x, z.y, z.size, z.size)) then
    raise exception 'Зона высадки должна оставаться свободной';
  end if;

  -- Кольцо захвата всегда свободно: иначе постройками можно запереть планету
  if exists (select 1 from settlement_zone_box() b
             where boxes_overlap(p_x, p_y, st.width_cells, st.height_cells, b.x, b.y, b.size, b.size)) then
    raise exception 'У поселения не строят: кольцо захвата должно оставаться свободным';
  end if;

  if exists (select 1 from planet_slots ps where ps.system_id = u.system_id
             and boxes_overlap(p_x, p_y, st.width_cells, st.height_cells, ps.x, ps.y, v_slot, v_slot)) then
    raise exception 'Здесь участок под здание';
  end if;

  if exists (select 1 from field_structures s where s.system_id = u.system_id
             and boxes_overlap(p_x, p_y, st.width_cells, st.height_cells, s.x, s.y, s.w, s.h)) then
    raise exception 'Место занято';
  end if;

  -- В окоп и бункер можно построиться прямо под своими бойцами,
  -- остальное ставится только на пустую землю
  if exists (
    select 1 from unit_positions o join unit_types ot on ot.id = o.unit_type
    where o.system_id = u.system_id and o.layer = 'ground' and o.x is not null
      and boxes_overlap(p_x, p_y, st.width_cells, st.height_cells, o.x, o.y, ot.width_cells, ot.height_cells)
      and (not st.enterable
           or o.faction is distinct from v_faction
           or (st.infantry_only and ot.is_vehicle))
  ) then
    raise exception 'Место занято';
  end if;

  if (select count(*) from field_structures s
      where s.system_id = u.system_id and s.type_id = p_type) >= st.max_per_planet then
    raise exception 'На планете уже предел: % шт.', st.max_per_planet;
  end if;

  if v_credits < st.cost then
    raise exception 'Недостаточно кредитов: нужно %', st.cost;
  end if;

  perform take_build_resources(u.system_id, st.cost_resources, 1);

  insert into field_structures (system_id, type_id, owner_user_id, faction, x, y, w, h, hp, completes_at)
  values (u.system_id, p_type, v_user, v_faction, p_x, p_y, st.width_cells, st.height_cells,
          st.max_hp, now() + make_interval(secs => st.build_seconds))
  returning id into v_id;

  update profiles set credits = credits - st.cost where id = v_user;
  -- Одна сводка на все заложенные постройки, пока игрок её не прочитал
  perform log_event_digest(v_user, v_faction, 'structure_started', 'fs:' || v_id,
                           u.system_id, (select name from systems where id = u.system_id),
                           st.name, null, null);
  return v_id;
end;
$$;


--
-- Name: building_line_used(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.building_line_used(p_building_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select (select count(*) from unit_orders
          where building_id = p_building_id and not delivered)::integer
       + (select count(*) from repair_orders
          where building_id = p_building_id and not delivered)::integer;
$$;


--
-- Name: building_slot_cap(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.building_slot_cap(p_system_id text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select game_setting_int('base_building_slots', 7)
       + coalesce((select l.extra_building_slots
                   from settlement_state s join settlement_levels l on l.level = s.level
                   where s.system_id = p_system_id), 0);
$$;


--
-- Name: building_slot_need_level(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.building_slot_need_level(p_slot integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when p_slot <= game_setting_int('base_building_slots', 7) then 0
              else (select min(level) from settlement_levels
                    where game_setting_int('base_building_slots', 7) + extra_building_slots >= p_slot)
         end;
$$;


--
-- Name: buy_market_lot(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buy_market_lot(p_lot_id uuid, p_amount integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  l record; v_faction text; v_cost integer; v_credits integer; v_id uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_amount < 1 then raise exception 'Некорректное количество'; end if;

  select * into l from market_lots where id = p_lot_id for update;
  if not found or not l.active then raise exception 'Лот не найден'; end if;
  if l.seller_user_id = v_user then raise exception 'Это твой собственный лот'; end if;

  select faction into v_faction from profiles where id = v_user;
  if l.open_to = 'faction' and l.seller_faction is distinct from v_faction then
    raise exception 'Продавец торгует только со своими';
  end if;

  if l.amount_left < p_amount then
    raise exception 'В лоте осталось только %', l.amount_left;
  end if;

  v_cost := p_amount * l.price_per_unit;
  select credits into v_credits from profiles where id = v_user;
  if v_credits < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;

  update profiles set credits = credits - v_cost where id = v_user;
  update market_lots set amount_left = amount_left - p_amount where id = p_lot_id;

  insert into market_orders (lot_id, buyer_user_id, amount_left, price_per_unit,
                             paid, expires_at)
  values (p_lot_id, v_user, p_amount, l.price_per_unit, v_cost,
          now() + make_interval(hours => game_setting_int('market_order_hours', 24)))
  returning id into v_id;

  perform log_event(l.seller_user_id, l.seller_faction, l.system_id, 'market_sold',
                    l.resource, p_amount, 'private',
                    jsonb_build_object('price', l.price_per_unit));

  return v_id;
end;
$$;


--
-- Name: camo_hidden(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.camo_hidden(p_system text, p_layer text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare u record; v_me text; v_found boolean;
begin
  if p_layer is distinct from 'ground' or p_x is null then return false; end if;
  select faction into v_me from profiles where id = auth.uid();

  -- Быстрый выход: чужой маскировки на планете нет — прятаться негде
  if not exists (
    select 1 from field_structures s join structure_types st on st.id = s.type_id
    where s.system_id = p_system and st.kind = 'camo'
      and s.faction is distinct from v_me and s.completes_at <= now()
  ) then
    return false;
  end if;

  select up.owner_user_id, up.faction, up.revealed_until,
         ut.width_cells as w, ut.height_cells as h
    into u
  from unit_positions up join unit_types ut on ut.id = up.unit_type
  where up.system_id = p_system and up.layer = p_layer and up.x = p_x and up.y = p_y
    and up.hp > 0
  limit 1;
  v_found := found;
  if not v_found then return false; end if;

  if u.owner_user_id is not null and u.owner_user_id = auth.uid() then return false; end if;
  if v_me is not null and u.faction = v_me then return false; end if;
  if u.revealed_until is not null and u.revealed_until > now() then return false; end if;
  if radar_covers(p_system, v_me, p_x, p_y, u.w, u.h) then return false; end if;

  if not exists (
    select 1 from field_structures s join structure_types st on st.id = s.type_id
    where s.system_id = p_system and st.kind = 'camo' and s.faction = u.faction
      and s.completes_at <= now()
      and boxes_overlap(p_x, p_y, u.w, u.h,
                        s.x - st.radius, s.y - st.radius, s.w + st.radius * 2, s.h + st.radius * 2)
  ) then
    return false;
  end if;

  return not observer_near(p_system, p_x, p_y, u.w, u.h, game_setting_int('camo_detect_cells', 3));
end;
$$;


--
-- Name: can_see_building(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_building(p_system text, p_faction text, p_slot integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me text; ps record;
begin
  select faction into v_me from profiles where id = auth.uid();
  if v_me is null then return false; end if;

  -- Своя постройка или своя планета (трофеи на взятой планете тоже свои)
  if p_faction = v_me then return true; end if;
  if exists (select 1 from systems where id = p_system and faction = v_me) then return true; end if;

  select x, y into ps from planet_slots where system_id = p_system and slot_index = p_slot;
  if not found then return false; end if;

  if radar_covers(p_system, v_me, ps.x, ps.y, 6, 6) then return true; end if;

  -- Те же правила обзора, что и у can_see_position: свои бойцы и союзники
  -- с ретранслятором, любая клетка участка в пределах дальности обзора
  return exists (
    select 1 from unit_positions u join unit_types t on t.id = u.unit_type
    where u.system_id = p_system and u.layer = 'ground' and u.hp > 0 and u.x is not null
      and (u.owner_user_id = auth.uid()
           or (u.faction = v_me
               and has_relay(auth.uid(), p_system, 'ground')
               and has_relay(u.owner_user_id, p_system, 'ground')))
      and box_gap(u.x, u.y, 1, 1, ps.x, ps.y, 6, 6) <= t.vision_range + coalesce(u.bonus_vision, 0));
end;
$$;


--
-- Name: can_see_position(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_position(p_system_id text, p_layer text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_faction text; v_sys_faction text;
begin
  if p_layer = 'ground' and is_in_ground_attack_zone(p_y) then
    select faction into v_faction from profiles where id = auth.uid();
    select faction into v_sys_faction from systems where id = p_system_id;
    return v_faction is not null and v_sys_faction is distinct from v_faction;
  end if;

  -- Узел связи поселения видит окрестности
  if p_layer = 'ground' and comms_covers(p_system_id,
       (select faction from profiles where id = auth.uid()), p_x, p_y) then
    return true;
  end if;

  -- Радар фракции видит свой квадрат без всяких войск рядом
  if p_layer = 'ground' and radar_covers(p_system_id,
       (select faction from profiles where id = auth.uid()), p_x, p_y, 1, 1) then
    return true;
  end if;

  return exists (
    select 1
    from unit_positions u
    join unit_types t on t.id = u.unit_type
    where u.system_id = p_system_id
      and u.layer = p_layer
      and u.hp > 0
      and u.x is not null
      and (
        u.owner_user_id = auth.uid()
        or (
          u.faction = (select faction from profiles where id = auth.uid())
          and has_relay(auth.uid(), p_system_id, p_layer)
          and has_relay(u.owner_user_id, p_system_id, p_layer)
        )
      )
      and greatest(abs(u.x - p_x), abs(u.y - p_y)) <= t.vision_range + u.bonus_vision
  );
end;
$$;


--
-- Name: can_see_ship_box(text, integer, integer, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_ship_box(p_system_id text, p_x integer, p_y integer, p_type text, p_facing integer, p_faction text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_my_faction text; v_band text; v_w integer; v_h integer;
begin
  if p_x is null or p_y is null then return false; end if;

  select faction into v_my_faction from profiles where id = auth.uid();
  if v_my_faction is null then return false; end if;

  -- Свои по фракции видны всегда
  if p_faction is not distinct from v_my_faction then return true; end if;

  -- Чужая зона прыжка закрыта, своя — видна (как и раньше)
  v_band := hyperspace_band_at(p_y, 1);
  if v_band is not null then
    return v_band is not distinct from hyperspace_side(p_system_id, v_my_faction);
  end if;

  select ship_box_w(t.width_cells, t.height_cells, coalesce(p_facing, 0)),
         ship_box_h(t.width_cells, t.height_cells, coalesce(p_facing, 0))
    into v_w, v_h
  from ship_types t where t.id = p_type;
  v_w := coalesce(v_w, 1); v_h := coalesce(v_h, 1);

  return exists (
    select 1
    from ships s
    join ship_types st on st.id = s.ship_type
    cross join lateral (
      select ship_box_w(st.width_cells, st.height_cells, s.facing) as w,
             ship_box_h(st.width_cells, st.height_cells, s.facing) as h) b
    where s.system_id = p_system_id
      and s.owner_user_id = auth.uid()
      and s.hp > 0
      and not s.in_transit
      and s.carrier_ship_id is null
      and s.x is not null
      and greatest(
            greatest(p_x - (s.x + b.w - 1), s.x - (p_x + v_w - 1), 0),
            greatest(p_y - (s.y + b.h - 1), s.y - (p_y + v_h - 1), 0))
          <= st.vision_range + coalesce(s.bonus_vision, 0)
  );
end;
$$;


--
-- Name: can_see_structure(text, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_structure(p_system text, p_faction text, p_type text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me text; v_kind text;
begin
  select faction into v_me from profiles where id = auth.uid();
  if v_me is null then return false; end if;
  if p_faction = v_me then return true; end if;

  select kind into v_kind from structure_types where id = p_type;
  if v_kind = 'landmine' then return false; end if;
  if v_kind = 'camo' then
    return observer_near(p_system, p_x, p_y, p_w, p_h, game_setting_int('camo_detect_cells', 3))
        or radar_covers(p_system, v_me, p_x, p_y, p_w, p_h);
  end if;

  return exists (select 1 from generate_series(p_x, p_x + p_w - 1) gx,
                               generate_series(p_y, p_y + p_h - 1) gy
                 where can_see_position(p_system, 'ground', gx, gy));
end;
$$;


--
-- Name: can_see_unit(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_unit(p_unit_type text, p_system_id text, p_layer text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_stealth integer;
begin
  if p_x is null then return false; end if;

  select stealth_range into v_stealth from unit_types where id = p_unit_type;

  if v_stealth is null then
    return can_see_position(p_system_id, p_layer, p_x, p_y)
       and not camo_hidden(p_system_id, p_layer, p_x, p_y);
  end if;

  -- Скрытный: важно расстояние до наблюдателя, а не его обзор. Радар видит и его.
  return exists (
    select 1
    from unit_positions o
    where o.system_id = p_system_id
      and o.layer = p_layer
      and o.hp > 0
      and o.x is not null
      and o.owner_user_id = auth.uid()
      and greatest(abs(o.x - p_x), abs(o.y - p_y)) <= v_stealth
  ) or (p_layer = 'ground' and radar_covers(p_system_id,
          (select faction from profiles where id = auth.uid()), p_x, p_y, 1, 1));
end;
$$;


--
-- Name: cancel_commander_route(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_commander_route(p_commander_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception 'Не авторизован'; end if;
  update commanders set route = null where id = p_commander_id and user_id = auth.uid();
  if not found then raise exception 'Командир не найден'; end if;
end;
$$;


--
-- Name: cancel_market_lot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_market_lot(p_lot_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); l record; v_fit integer;
begin
  select * into l from market_lots where id = p_lot_id for update;
  if not found or not l.active then raise exception 'Лот не найден'; end if;
  if l.seller_user_id <> v_user then raise exception 'Это не твой лот'; end if;
  -- товар возвращается на склад планеты, с которой выставлен (и если планету уже передали другому управляющему —
  -- иначе лот висел бы вечно); при захвате врагом лоты закрываются раньше (refund_pending_on_capture)
  -- пока есть оплаченные брони, снимать нельзя: покупатель уже в пути
  if exists (select 1 from market_orders o where o.lot_id = p_lot_id and o.status = 'reserved') then
    raise exception 'По лоту есть неисполненные брони — дождись вывоза или их истечения';
  end if;

  -- что не влезло на склад, остаётся в лоте — не сгорает
  v_fit := add_planet_stock(l.system_id, l.resource, l.amount_left);
  update market_lots
     set amount_left = amount_left - v_fit,
         active = (amount_left - v_fit) > 0
   where id = p_lot_id;
  return v_fit;
end;
$$;


--
-- Name: cancel_planet_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_planet_request(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update planet_requests set status = 'cancelled', resolved_at = now()
  where id = p_id and user_id = auth.uid() and status = 'pending';
  if not found then raise exception 'Запрос не найден или уже рассмотрен'; end if;
end;
$$;


--
-- Name: cancel_transfer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_transfer(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare t record; v_name text;
begin
  select * into t from troop_transfers where id = p_id for update;
  if not found or t.from_user <> auth.uid() then raise exception 'Передача не найдена'; end if;
  if t.status <> 'pending' then raise exception 'Передача уже закрыта'; end if;

  update troop_transfers set status = 'cancelled', resolved_at = now() where id = p_id;
  select nickname into v_name from profiles where id = t.from_user;
  perform log_event(t.to_user, t.faction, null, 'transfer_cancelled',
                    v_name || ' · ' || coalesce(t.summary, ''), 1, 'private',
                    jsonb_build_object('transfer_id', p_id));
end;
$$;


--
-- Name: cap_hero_damage(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cap_hero_damage(p_target uuid, p_damage integer) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_cap integer;
begin
  select ceil((t.max_hp + u.bonus_hp)
              * game_setting_int('hero_damage_cap_pct', 35) / 100.0)::integer
    into v_cap
  from unit_positions u join unit_types t on t.id = u.unit_type
  where u.id = p_target and u.hero_id is not null;

  if v_cap is null then return p_damage; end if;   -- обычный юнит, без потолка
  return least(p_damage, greatest(1, v_cap));
end;
$$;


--
-- Name: capture_counts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_counts(p_system_id text) RETURNS TABLE(attackers integer, defenders integer, attacker_faction text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with sys as (select faction from systems where id = p_system_id),
  units as (
    select u.faction, count(*)::integer as n
    from unit_positions u
    join unit_types t on t.id = u.unit_type
    where u.system_id = p_system_id
      and u.layer = 'ground'
      and u.hp > 0
      and u.x is not null
      and not t.is_vehicle
      and u.faction in ('republic', 'cis')
      and is_in_settlement_zone(u.x, u.y)
    group by u.faction
  )
  select
    coalesce((select n from units where faction is distinct from (select faction from sys)), 0),
    coalesce((select n from units where faction = (select faction from sys)), 0),
    (select faction from units where faction is distinct from (select faction from sys) order by n desc limit 1);
$$;


--
-- Name: capture_goal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_goal(p_system text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_base integer := game_setting_int('capture_seconds', 60); v_m numeric := 1; v_s integer; v_g timestamptz; v_goal integer;
begin
  if loyalty_on('effects') then
    v_s := loyalty_support(p_system);
    if v_s is not null then
      v_m := (loyalty_stage_of(v_s) ->> 'm')::numeric;
      v_g := loyalty_grace_until(p_system);
      if v_g is not null and v_g > now() then v_m := greatest(v_m, 1); end if;
    end if;
  end if;
  v_goal := greatest(30, round(v_base * v_m))::integer;
  if loyalty_capital(p_system) then v_goal := greatest(v_goal, least(v_base, game_setting_int('loyalty_capital_min_s', 21600))); end if;
  return v_goal;
end;
$$;


--
-- Name: capture_progress(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_progress(p_system_id text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(0, least(
    coalesce(sc.goal, game_setting_int('capture_seconds', 60)),
    sc.progress + sc.rate * extract(epoch from now() - sc.updated_at)
  ))
  from system_capture sc
  where sc.system_id = p_system_id;
$$;


--
-- Name: capture_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_capture_flag text := set_config('app.capture_transfer', '1', true);
  sysrec record; c record; v_row record;
  v_goal integer := game_setting_int('capture_seconds', 60);
  v_progress numeric; v_rate integer; v_status text; v_faction text; v_g integer;
begin
  for sysrec in
    select distinct s.id, s.faction
    from systems s
    where s.faction is not null
      and (exists (
        select 1 from unit_positions u
        join unit_types t on t.id = u.unit_type
        where u.system_id = s.id and u.layer = 'ground' and u.hp > 0
          and u.x is not null and not t.is_vehicle
          and is_in_settlement_zone(u.x, u.y))
      or exists (select 1 from system_capture sc where sc.system_id = s.id))
  loop
    select * into c from capture_counts(sysrec.id);
    select * into v_row from system_capture where system_id = sysrec.id;

    v_progress := coalesce(capture_progress(sysrec.id), 0);
    v_faction  := coalesce(v_row.faction, c.attacker_faction);

    if v_faction is null then
      delete from system_capture where system_id = sysrec.id;
      continue;
    end if;

    if c.attackers > c.defenders then
      -- О начале захвата сообщаем один раз, когда полоса только пошла
      if v_row is null or v_row.status is distinct from 'capturing' then
        perform log_event(
          (select controller_user_id from system_control where system_id = sysrec.id),
          sysrec.faction, sysrec.id, 'capture_started',
          c.attacker_faction, c.attackers, 'private',
          jsonb_build_object('attackers', c.attackers, 'defenders', c.defenders));

        -- Поселение поднимает ополчение (сбор раз в несколько часов)
        begin
          perform raise_militia(sysrec.id);
        exception when others then perform err_db('capture_tick', sqlstate, sqlerrm, true);
          raise warning 'raise_militia %: %', sysrec.id, sqlerrm;
        end;

        -- Подполье: сеть и народ, ждущий врага, встают за наступающих (sql/loyalty.sql)
        begin
          perform raise_partisans(sysrec.id, c.attacker_faction);
        exception when others then perform err_db('capture_tick', sqlstate, sqlerrm, true);
          raise warning 'raise_partisans %: %', sysrec.id, sqlerrm;
        end;
      end if;

      v_rate := 1; v_status := 'capturing';
      v_faction := coalesce(c.attacker_faction, v_faction);
    elsif c.defenders > c.attackers then
      v_rate := -1; v_status := 'reverting';
    elsif c.attackers = 0 then
      v_rate := 0; v_status := 'stalled';
    else
      v_rate := 0; v_status := 'contested';
    end if;

    if v_progress <= 0 and v_rate <= 0 then
      delete from system_capture where system_id = sysrec.id;
      continue;
    end if;

    -- Срок захвата — снимок на старте полосы: настроения планеты (sql/loyalty.sql)
    if v_row is null or v_row.goal is null or v_row.status = 'distribution' or v_progress <= 0
       or v_row.faction is distinct from v_faction then
      v_g := capture_goal(sysrec.id);
    else
      v_g := v_row.goal;
    end if;

    if v_progress >= v_g then
      perform refund_pending_on_capture(sysrec.id);

      update systems set faction = v_faction where id = sysrec.id;

      -- Ополчение прежних хозяев расходится, иначе оно тут же «захватывало» бы обратно
      delete from unit_positions u
      using npc_brains nb
      where nb.unit_id = u.id and nb.kind in ('militia', 'partisan') and u.system_id = sysrec.id;
      delete from system_control where system_id = sysrec.id;

      -- Стороны перевернулись: разводим тех, кто остался в чужих зонах
      perform evacuate_zones_after_capture(sysrec.id, v_faction);

      update system_capture
      set progress = 0, rate = 0, status = 'distribution',
          faction = v_faction, updated_at = now()
      where system_id = sysrec.id;

      perform log_event(null, v_faction, sysrec.id, 'planet_captured', null, 1, 'all',
                        jsonb_build_object('from_faction', sysrec.faction));
      continue;
    end if;

    if v_row is null
       or v_row.rate is distinct from v_rate
       or v_row.faction is distinct from v_faction
       or v_row.status is distinct from v_status
       or v_row.goal is distinct from v_g then

      insert into system_capture (system_id, faction, progress, rate, status, updated_at, goal)
      values (sysrec.id, v_faction, v_progress, v_rate, v_status, now(), v_g)
      on conflict (system_id) do update
        set faction = excluded.faction, progress = excluded.progress,
            rate = excluded.rate, status = excluded.status,
            updated_at = excluded.updated_at, goal = excluded.goal;
    end if;
  end loop;
end;
$$;


--
-- Name: check_cargo_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_cargo_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_owner uuid;
begin
  select owner_user_id into v_owner from ships where id = new.ship_id;
  if v_owner is distinct from auth.uid() and auth.uid() is not null then
    raise exception 'Это не твой корабль';
  end if;
  return new;
end;
$$;


--
-- Name: check_ship_commander(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_ship_commander() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_cmd_owner uuid;
begin
  if new.commander_id is null then
    return new;
  end if;

  select user_id into v_cmd_owner from commanders where id = new.commander_id;

  if v_cmd_owner is distinct from new.owner_user_id then
    raise exception 'Командир принадлежит другому игроку';
  end if;

  return new;
end;
$$;


--
-- Name: claim_ready_now(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ready_now() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  -- Работаем, только если у самого игрока что-то уже готово:
  -- пустой вызов ничего не трогает
  if exists (select 1 from research_orders
             where owner_user_id = v_user and not delivered and completes_at <= now()) then
    perform deliver_ready_research();
  end if;
  if exists (select 1 from unit_orders
             where owner_user_id = v_user and not delivered and completes_at <= now()) then
    perform deliver_ready_units();
  end if;
  if exists (select 1 from repair_orders
             where owner_user_id = v_user and not delivered and completes_at <= now()) then
    perform deliver_ready_repairs();
  end if;
  if exists (select 1 from hero_training
             where owner_user_id = v_user and not delivered and completes_at <= now()) then
    perform deliver_ready_training();
  end if;
  if exists (select 1 from ship_orders
             where owner_user_id = v_user and not delivered and completes_at <= now()) then
    perform deliver_ready_ships();
  end if;
end;
$$;


--
-- Name: claim_tutorial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_tutorial() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); v_faction text; st record; s record;
  v_total integer; v_extra text := ''; v_id uuid; n integer; v_planet text;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_faction from profiles where id = v_me;

  perform tutorial_eval(v_me);
  select * into st from tutorial_state where user_id = v_me for update;
  if not found or st.status <> 'active' then raise exception 'Курс уже пройден'; end if;
  if not st.step_done then raise exception 'Задание ещё не выполнено'; end if;

  select * into s from tutorial_steps where ord = st.step_ord;
  select count(*) into v_total from tutorial_steps;

  update profiles set credits = credits + s.reward_credits where id = v_me;

  if s.id = 'army' then
    v_id := tutorial_give_ship(v_me, v_faction);
    st.meta := st.meta || jsonb_build_object('ship_id', v_id);
    v_extra := tutorial_fill('{ship} ждёт на орбите {capital_gen}', v_faction);
  elsif s.id = 'assign' then
    n := tutorial_give_troops(v_me, v_faction);
    v_extra := n || ' бойцов ждут в зоне высадки ' || tutorial_fill('{capital_gen}', v_faction);
  elsif s.id = 'drop' then
    v_id := tutorial_spawn_target(v_me, st.step_since);
    st.meta := st.meta || jsonb_build_object('target_id', v_id);
    v_extra := case when v_id is null then '' else 'Рядом с твоими бойцами замечен мародёр' end;
  elsif s.id = 'planet' then
    -- На свежей планете сырья может не хватить даже на казарму и найм —
    -- без стартового запаса новичок застрял бы на следующих шагах
    select sc.system_id into v_planet from system_control sc
    where sc.controller_user_id = v_me
    order by (select max(g.created_at) from game_events g
              where g.user_id = v_me and g.type = 'planet_granted' and g.system_id = sc.system_id) desc nulls last
    limit 1;
    if v_planet is not null then
      perform add_planet_stock(v_planet, 'durasteel', 200);
      perform add_planet_stock(v_planet, 'electronics', 100);
      perform add_planet_stock(v_planet, 'cells', 100);
      perform add_planet_stock(v_planet, 'food', 100);
      st.meta := st.meta || jsonb_build_object('planet_id', v_planet);
      v_extra := 'Сырьё доставлено на склад: ' || (select name from systems where id = v_planet);
    end if;
  elsif s.id = 'final' then
    update commanders set unlocked = true,
           current_system = coalesce(current_system, tutorial_capital(v_faction))
    where user_id = v_me and slot_index = 2;
    v_extra := 'Второй командир ждёт в ' || case v_faction when 'republic' then 'Корусанте' else 'Раксусе' end;
  end if;

  if st.step_ord >= v_total then
    update tutorial_state set status = 'finished', step_done = false, finished_at = now(),
           meta = st.meta where user_id = v_me;
    perform log_event(v_me, v_faction, null, 'tutorial_finished', 'Второй командир', 1, 'private',
                      jsonb_build_object('tutorial', true));
  else
    update tutorial_state set step_ord = st.step_ord + 1, step_since = now(),
           step_done = false, meta = st.meta where user_id = v_me;
    perform tutorial_eval(v_me);
  end if;

  return jsonb_build_object('ok', true, 'credits', s.reward_credits, 'extra', v_extra,
                            'finished', st.step_ord >= v_total);
end;
$$;


--
-- Name: cleanup_old_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_records() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_ev integer; v_tasks integer; v_tr integer;
        v_am integer; v_ams integer; v_amr integer; v_slog integer; v_stakes integer;
begin
  -- Лента событий: 30 дней — столько же смотрит статистика игрока.
  -- planet_granted оставляем: по нему обучение выбирает планету новичка.
  delete from game_events
    where created_at < now() - interval '30 days' and type <> 'planet_granted';
  get diagnostics v_ev = row_count;

  -- Условия поселений: игре нужны только текущие сутки, неделю держим для разборов
  delete from settlement_tasks where cycle_start < now() - interval '7 days';
  get diagnostics v_tasks = row_count;

  -- Закрытые передачи войск (позиции удаляются каскадом)
  delete from troop_transfers
    where status <> 'pending'
      and coalesce(resolved_at, expires_at, created_at) < now() - interval '14 days';
  get diagnostics v_tr = row_count;

  -- Автоход: завершённые приказы и служебные отметки старше суток
  delete from auto_moves where status <> 'active' and updated_at < now() - interval '1 day';
  get diagnostics v_am = row_count;
  delete from auto_move_stops where created_at < now() - interval '1 day';
  get diagnostics v_ams = row_count;
  delete from auto_move_reports where created_at < now() - interval '1 day';
  get diagnostics v_amr = row_count;

  -- Снабжение: журнал рейсов и учёт вывоза — неделя (дневной лимит смотрит только текущие сутки)
  delete from supply_route_log where at < now() - interval '7 days';
  get diagnostics v_slog = row_count;
  delete from supply_takes where taken_at < now() - interval '7 days';
  get diagnostics v_stakes = row_count;

  return jsonb_build_object('game_events', v_ev, 'settlement_tasks', v_tasks,
    'troop_transfers', v_tr,
    'auto_moves', v_am, 'auto_move_stops', v_ams, 'auto_move_reports', v_amr,
    'supply_route_log', v_slog, 'supply_takes', v_stakes);
end;
$$;


--
-- Name: close_requests_on_faction_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_requests_on_faction_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o record;
begin
  for o in select * from planet_requests
           where system_id = new.id and status = 'pending' and faction is distinct from new.faction
  loop
    update planet_requests set status = 'closed', resolved_at = now() where id = o.id;
    perform log_event(o.user_id, o.faction, o.system_id, 'planet_request_closed',
                      null, 1, 'private', jsonb_build_object('request_id', o.id));
  end loop;
  return null;
end;
$$;


--
-- Name: commander_free_cargo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commander_free_cargo(p_commander_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select coalesce(sum(greatest(0, st.capacity - ship_load_used(s.id))), 0)::integer
         * game_setting_int('cargo_units_per_slot', 2)
  from ships s
  cross join lateral ship_stats(s.id) st
  where s.commander_id = p_commander_id and not s.in_transit;
$$;


--
-- Name: commander_route_continue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commander_route_continue(p_commander_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare c record; v_fac text; v_goal text; v_path text[]; v_prev text; v_err text;
begin
  select * into c from commanders where id = p_commander_id for update;
  if not found or c.moving_to is not null or coalesce(cardinality(c.route), 0) = 0 then
    return false;
  end if;

  v_goal := c.route[cardinality(c.route)];
  select faction into v_fac from profiles where id = c.user_id;
  v_path := convoy_route_to(c.current_system, v_goal, v_fac);

  if v_path is null or cardinality(v_path) < 2 then
    update commanders set route = null where id = c.id;
    perform log_event(c.user_id, v_fac, c.current_system, 'route_stalled',
                      'путь к цели перекрыт', 1, 'private',
                      jsonb_build_object('commander', c.name, 'goal', v_goal));
    return false;
  end if;

  -- Прыжок — той же функцией, что у игрока, от его имени: все проверки общие
  v_prev := current_setting('request.jwt.claims', true);
  perform set_config('request.jwt.claims',
    json_build_object('sub', c.user_id::text, 'role', 'authenticated')::text, true);
  begin
    perform start_commander_move(c.id, v_path[2]);
  exception when others then perform err_db('commander_route_continue', sqlstate, sqlerrm, false);
    v_err := sqlerrm;
  end;
  perform set_config('request.jwt.claims', coalesce(v_prev, ''), true);

  if v_err is not null then
    update commanders set route = null where id = c.id;
    perform log_event(c.user_id, v_fac, c.current_system, 'route_stalled', v_err, 1, 'private',
                      jsonb_build_object('commander', c.name, 'goal', v_goal));
    return false;
  end if;

  update commanders
  set route = case when cardinality(v_path) > 2 then v_path[3:] else null end
  where id = c.id;
  return true;
end;
$$;


--
-- Name: comms_covers(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_covers(p_system text, p_faction text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_faction is not null
     and (select faction from systems where id = p_system) = p_faction
     and settlement_has_district(p_system, 'comms')
     and exists (select 1 from settlement_box() b
                 where box_gap(p_x, p_y, 1, 1, b.x, b.y, b.size, b.size)
                       <= (select effect_value from district_types where id = 'comms'));
$$;


--
-- Name: construct_building(text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.construct_building(p_system_id text, p_slot_index integer, p_building_type_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_faction text;
  v_cost integer;
  v_credits integer;
  v_type_faction text;
  v_is_space boolean;
  v_seconds integer;
begin
  if v_user_id is null then
    raise exception 'Не авторизован';
  end if;

  if not exists (
    select 1 from system_control sc
    where sc.system_id = p_system_id and sc.controller_user_id = v_user_id
  ) then
    raise exception 'Нет прав на строительство в этой системе';
  end if;

  perform assert_planet_operational(p_system_id);

  -- Участок должен существовать и быть открыт уровнем поселения
  declare v_slot record; v_need integer;
  begin
    select * into v_slot from planet_slots where system_id = p_system_id and slot_index = p_slot_index;
    if not found then raise exception 'Нет такого участка'; end if;

    if p_slot_index > building_slot_cap(p_system_id) then
      v_need := building_slot_need_level(p_slot_index);
      raise exception 'Участок откроется, когда поселение станет «%»',
        coalesce((select name from settlement_levels where level = v_need), 'больше');
    end if;

    -- Здание не встаёт на головы бойцам: иначе они оказались бы внутри стен
    if exists (select 1 from unit_positions u join unit_types t on t.id = u.unit_type
               where u.system_id = p_system_id and u.layer = 'ground' and u.x is not null
                 and boxes_overlap(u.x, u.y, t.width_cells, t.height_cells, v_slot.x, v_slot.y, 6, 6)) then
      raise exception 'На участке стоят войска — сначала отведи их';
    end if;
  end;

  select faction, credits into v_faction, v_credits from profiles where id = v_user_id;

  select cost, faction, is_space into v_cost, v_type_faction, v_is_space
  from building_types where id = p_building_type_id;

  if v_cost is null then
    raise exception 'Неизвестный тип постройки';
  end if;

  -- Нельзя построить здание чужой фракции, даже если подсунуть его id вручную.
  if v_type_faction is distinct from v_faction then
    raise exception 'Эта постройка недоступна твоей фракции';
  end if;

  if v_is_space then
    raise exception 'Космические объекты строятся на орбитальной карте';
  end if;

  -- Добыча возможна только там, где сырьё залегает
  declare
    v_needs boolean; v_res text; v_res_name text;
    v_prim text; v_sec text; v_max integer; v_have integer;
  begin
    select needs_local_resource, produces_resource, max_per_planet into v_needs, v_res, v_max
    from building_types where id = p_building_type_id;

    if v_needs then
      select primary_resource, secondary_resource into v_prim, v_sec
      from systems where id = p_system_id;

      if v_res is distinct from v_prim and v_res is distinct from v_sec then
        select name into v_res_name from resources where id = v_res;
        raise exception 'На этой планете нет такого сырья: %', coalesce(v_res_name, v_res);
      end if;
    end if;

    -- Предел на планете. Две закладки разом не должны обе проскочить под предел:
    -- стройки одной планеты идут по очереди.
    if v_max is not null then
      perform pg_advisory_xact_lock(hashtext('construct:' || p_system_id));

      select count(*) into v_have
      from buildings b join building_types t on t.id = b.building_type_id
      where b.system_id = p_system_id
        and (t.id = p_building_type_id
             or (v_needs and t.needs_local_resource and t.produces_resource = v_res));

      if v_have >= v_max then
        if v_needs then
          select name into v_res_name from resources where id = v_res;
          raise exception 'Больше нельзя: на планете уже % на добыче «%» (предел %)',
            v_have, coalesce(v_res_name, v_res), v_max;
        end if;
        raise exception 'Больше нельзя: на планете уже % таких (предел %)', v_have, v_max;
      end if;
    end if;
  end;

  if v_credits < v_cost then
    raise exception 'Недостаточно кредитов';
  end if;

  select value::integer into v_seconds from game_settings where key = 'build_seconds';
  v_seconds := coalesce(v_seconds, 60);
  -- законы фракции: ±% времени стройки
  v_seconds := greatest(5, round(v_seconds * (100 + effect_sum(p_system_id, 'build_time')) / 100.0)::integer);

  insert into buildings (system_id, slot_index, building_type_id, owner_user_id, faction, completes_at)
  values (p_system_id, p_slot_index, p_building_type_id, v_user_id, v_faction,
          now() + make_interval(secs => v_seconds));

  perform take_build_resources(p_system_id,
             (select cost_resources from building_types where id = p_building_type_id), 1);

  update profiles set credits = credits - v_cost where id = v_user_id;
end;
$$;


--
-- Name: construct_space_station(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.construct_space_station(p_system_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_faction text; v_credits integer; v_cost integer; v_seconds integer;
begin
  if v_user_id is null then raise exception 'Не авторизован'; end if;

  perform assert_planet_operational(p_system_id);

  if not exists (
    select 1 from system_control sc
    where sc.system_id = p_system_id and sc.controller_user_id = v_user_id
  ) then
    raise exception 'Нет прав на строительство в этой системе';
  end if;

  if exists (select 1 from space_stations where system_id = p_system_id) then
    raise exception 'В этой системе уже есть станция';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user_id;

  select cost into v_cost from building_types where is_space and faction = v_faction limit 1;
  v_cost := coalesce(v_cost, 5000);

  if v_credits < v_cost then
    raise exception 'Недостаточно кредитов: нужно %', v_cost;
  end if;

  select value::integer into v_seconds from game_settings where key = 'station_build_seconds';
  v_seconds := coalesce(v_seconds, 60);

  insert into space_stations (system_id, owner_user_id, faction, completes_at)
  values (p_system_id, v_user_id, v_faction, now() + make_interval(secs => v_seconds));

  update profiles set credits = credits - v_cost where id = v_user_id;
end;
$$;


--
-- Name: convoy_route(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convoy_route(p_from text, p_to text, p_faction text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  frontier text[] := array[p_from];
  visited  text[] := array[p_from];
  parent   jsonb  := jsonb_build_object(p_from, null);
  nxt text[]; n text; cur text; path text[]; d integer := 0;
begin
  if p_from = p_to then return array[p_from]; end if;

  while coalesce(array_length(frontier, 1), 0) > 0 and d < 20 loop
    d := d + 1;
    nxt := '{}';

    for cur in select unnest(frontier) loop
      for n in
        select case when h.system_a = cur then h.system_b else h.system_a end
        from hyperlanes h
        join systems s on s.id = case when h.system_a = cur then h.system_b else h.system_a end
        where (h.system_a = cur or h.system_b = cur)
          and not s.is_deep_space
          and s.faction = p_faction
      loop
        continue when n = any(visited);
        visited := visited || n;
        nxt := nxt || n;
        parent := parent || jsonb_build_object(n, cur);

        if n = p_to then
          path := array[n];
          cur := parent ->> n;
          while cur is not null loop
            path := array[cur] || path;
            cur := parent ->> cur;
          end loop;
          return path;
        end if;
      end loop;
    end loop;

    frontier := nxt;
  end loop;

  return null;
end;
$$;


--
-- Name: convoy_route_to(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convoy_route_to(p_from text, p_to text, p_faction text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  frontier text[] := array[p_from];
  visited  text[] := array[p_from];
  parent   jsonb  := jsonb_build_object(p_from, null);
  nxt text[]; n text; cur text; path text[]; d integer := 0;
begin
  if p_from = p_to then return array[p_from]; end if;

  while coalesce(array_length(frontier, 1), 0) > 0 and d < 20 loop
    d := d + 1;
    nxt := '{}';

    for cur in select unnest(frontier) loop
      for n in
        select case when h.system_a = cur then h.system_b else h.system_a end
        from hyperlanes h
        join systems s on s.id = case when h.system_a = cur then h.system_b else h.system_a end
        where (h.system_a = cur or h.system_b = cur)
          and (not s.is_deep_space or (s.id = p_to and void_find_open(p_to)))
          and (s.faction = p_faction
               or s.id = p_to)          -- в цель можно, даже если она чужая
      loop
        continue when n = any(visited);
        visited := visited || n;
        parent := parent || jsonb_build_object(n, cur);

        if n = p_to then
          path := array[n];
          cur := parent ->> n;
          while cur is not null loop
            path := array[cur] || path;
            cur := parent ->> cur;
          end loop;
          return path;
        end if;

        -- дальше через чужую цель не идём: она только конечная
        nxt := nxt || n;
      end loop;
    end loop;

    frontier := nxt;
  end loop;

  return null;
end;
$$;


--
-- Name: covered_damage(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.covered_damage(p_target uuid, p_damage integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select cap_hero_damage(p_target,
           greatest(1, round(p_damage * (100 - structure_cover(p_target)) / 100.0)::integer));
$$;


--
-- Name: create_market_lot(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_market_lot(p_system_id text, p_resource text, p_amount integer, p_price integer, p_open_to text DEFAULT 'faction'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_faction text; v_hub text; v_id uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_amount is null or p_amount < 1 then raise exception 'Некорректное количество'; end if;
  if p_price is null or p_price < game_setting_int('market_min_price', 1) then
    raise exception 'Цена не может быть меньше %', game_setting_int('market_min_price', 1);
  end if;
  if p_open_to not in ('faction', 'all') then
    raise exception 'Непонятный круг покупателей';
  end if;

  if not exists (select 1 from system_control sc
                 where sc.system_id = p_system_id and sc.controller_user_id = v_user) then
    raise exception 'Планета не под твоим контролем';
  end if;

  select faction into v_faction from profiles where id = v_user;
  v_hub := case when v_faction = 'republic' then 'rep_logistics' else 'cis_logistics' end;

  -- Торгуют через логистический узел: без него планета не в сети
  if not exists (
    select 1 from buildings b join building_types bt on bt.id = b.building_type_id
    where b.system_id = p_system_id and bt.code = v_hub
      and (b.completes_at is null or b.completes_at <= now())
      and b.faction = (select faction from systems where id = p_system_id)
  ) then
    raise exception 'На этой планете нет достроенного логистического узла';
  end if;

  -- торги — не склад сверх предела: на лотах с планеты не больше, чем вмещают её склады
  perform pg_advisory_xact_lock(hashtext('lots:' || p_system_id || ':' || p_resource));
  if (select coalesce(sum(amount_left), 0) from market_lots
       where system_id = p_system_id and resource = p_resource and active) + p_amount > planet_stock_cap(p_system_id) then
    raise exception 'На торгах с этой планеты уже % — вместе с новым лотом больше, чем вмещают её склады (%)',
      (select coalesce(sum(amount_left), 0) from market_lots
        where system_id = p_system_id and resource = p_resource and active), planet_stock_cap(p_system_id);
  end if;

  perform take_planet_stock(p_system_id, p_resource, p_amount);

  insert into market_lots (seller_user_id, seller_faction, system_id, resource,
                           amount_left, price_per_unit, open_to)
  values (v_user, v_faction, p_system_id, p_resource, p_amount, p_price, p_open_to)
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: create_supply_route(uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supply_route(p_commander_id uuid, p_name text, p_stops jsonb, p_loop boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); cm record; v_fac text; v_stops jsonb; v_id uuid; v_name text; v_ships integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_user;

  if not supply_has_hub(v_user) then
    raise exception 'Нужен штаб снабжения: достроенный логистический узел хотя бы на одной планете';
  end if;

  select * into cm from commanders where id = p_commander_id and user_id = v_user for update;
  if not found then raise exception 'Командир не найден'; end if;
  if not cm.unlocked then raise exception 'Командир ещё не открыт'; end if;
  if cm.moving_to is not null then raise exception 'Командир в пути — дождись прибытия'; end if;
  if cm.current_system is null then raise exception 'Неизвестно, где стоит флот'; end if;
  if exists (select 1 from supply_routes r where r.commander_id = p_commander_id and r.status <> 'stopped') then
    raise exception 'У этого командира уже есть рейс — заверши его';
  end if;
  select count(*)::integer into v_ships from ships s
   where s.commander_id = p_commander_id and s.carrier_ship_id is null;
  if v_ships = 0 then raise exception 'У командира не осталось кораблей'; end if;

  v_stops := supply_normalize_stops(p_stops, v_fac, coalesce(p_loop, true));
  v_name := left(nullif(btrim(coalesce(p_name, '')), ''), 40);
  if v_name is null then
    select 'Рейс ' || string_agg(s.name, ' — ' order by o) into v_name
    from jsonb_array_elements(v_stops) with ordinality x(st, o)
    join systems s on s.id = x.st ->> 'system_id' where o <= 2;
    v_name := left(v_name, 40);
  end if;

  insert into supply_routes (owner_user_id, commander_id, name, stops, loop, status, stop_index, phase,
                             expect_system, last_note)
  values (v_user, p_commander_id, v_name, v_stops, coalesce(p_loop, true), 'active', 0, 'travel',
          cm.current_system, 'Рейс запущен')
  returning id into v_id;

  perform supply_log(v_id, cm.current_system, 'Рейс запущен', 0);
  return v_id;
end $$;


--
-- Name: create_transfer(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_transfer(p_to uuid, p_items jsonb, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_faction text; v_to_faction text; v_me_name text;
  v_id uuid; it record; v_block text; v_sys text; v_owner uuid; v_n integer := 0;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  if p_to is null or p_to = v_me then raise exception 'Выбери союзника'; end if;

  select faction, nickname into v_faction, v_me_name from profiles where id = v_me;
  select faction into v_to_faction from profiles where id = p_to;
  if v_faction is null or v_to_faction is distinct from v_faction then
    raise exception 'Передавать войска можно только союзнику своей фракции';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Ничего не выбрано';
  end if;
  if jsonb_array_length(p_items) > 300 then
    raise exception 'За один раз можно передать не больше 300 единиц';
  end if;

  perform transfer_expire_old();

  if (select count(*) from troop_transfers
      where from_user = v_me and status = 'pending') >= 5 then
    raise exception 'Не больше пяти неподтверждённых передач одновременно';
  end if;

  insert into troop_transfers (from_user, to_user, faction, note)
  values (v_me, p_to, v_faction, nullif(left(btrim(coalesce(p_note, '')), 140), ''))
  returning id into v_id;

  for it in
    select distinct x->>'kind' as kind, (x->>'id')::uuid as id
    from jsonb_array_elements(p_items) x
  loop
    v_owner := null; v_sys := null;
    if it.kind = 'ship' then
      select owner_user_id, system_id into v_owner, v_sys from ships where id = it.id for update;
      v_block := transfer_block_ship(it.id);
    elsif it.kind = 'unit' then
      select owner_user_id, system_id into v_owner, v_sys from unit_positions where id = it.id for update;
      v_block := transfer_block_unit(it.id);
    else
      raise exception 'Неизвестный вид передачи';
    end if;

    if v_owner is distinct from v_me then raise exception 'Это не твои войска'; end if;
    if v_block is not null then raise exception 'Нельзя передать: %', v_block; end if;

    if exists (select 1 from troop_transfer_items ti
               join troop_transfers tt on tt.id = ti.transfer_id
               where ti.item_id = it.id and tt.status = 'pending' and tt.id <> v_id) then
      raise exception 'Часть войск уже ждёт подтверждения в другой передаче';
    end if;

    insert into troop_transfer_items (transfer_id, kind, item_id, system_id, snapshot)
    values (v_id, it.kind, it.id, v_sys, transfer_snapshot(it.kind, it.id));
    v_n := v_n + 1;
  end loop;

  update troop_transfers set summary = transfer_summary(v_id) where id = v_id;

  perform log_event(p_to, v_faction, null, 'transfer_offer',
                    v_me_name || ' · ' || transfer_summary(v_id), 1, 'private',
                    jsonb_build_object('transfer_id', v_id));
  return v_id;
end;
$$;


--
-- Name: damage_multiplier(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.damage_multiplier(p_attacker text, p_target text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select multiplier from damage_matrix
     where attacker_class = p_attacker and target_class = p_target), 1.0);
$$;


--
-- Name: deliver_ready_repairs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_ready_repairs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  o record; s record; f record; b record; i integer;
  v_merged text[];
begin
  for o in
    select * from repair_orders
    where not delivered and completes_at <= now()
    order by completes_at
    for update skip locked
  loop
    if o.kind = 'unit' then
      update unit_positions u
      set hp = least(t.max_hp + u.bonus_hp, u.hp + coalesce(o.heal_amount, t.max_hp + u.bonus_hp))
      from unit_types t
      where u.id = o.unit_id and t.id = u.unit_type;

    elsif o.kind = 'ship' then
      -- Чиним носитель и всё, что стоит в его ангаре
      update ships sh
      set hp = case when sh.id = o.ship_id
                      then least(t.max_hp + sh.bonus_hp, sh.hp + coalesce(o.heal_amount, t.max_hp + sh.bonus_hp))
                    else t.max_hp + sh.bonus_hp end,
          trophy = case when sh.id = o.ship_id then false else sh.trophy end,
          jump_lock_until = case when sh.id = o.ship_id then null else sh.jump_lock_until end
      from ship_types t
      where t.id = sh.ship_type
        and (sh.id = o.ship_id or sh.carrier_ship_id = o.ship_id);

    elsif o.kind = 'refit' then
      select * into s from ships where id = o.ship_id;
      if found then
        select array(select distinct x from unnest(
                 coalesce(s.upgrades, '{}') || coalesce(o.upgrades, '{}')) x)
          into v_merged;
        perform apply_ship_refit(o.ship_id, v_merged);
      end if;

    elsif o.kind = 'hangar' then
      select * into s from ships where id = o.ship_id;
      if found then
        select * into f from ship_types
        where faction = s.faction and is_fighter and hull_class = 'fighter' limit 1;
        select * into b from ship_types
        where faction = s.faction and is_fighter and hull_class = 'bomber' limit 1;

        for i in 1..coalesce(o.fighters, 0) loop
          exit when f.id is null;
          insert into ships (system_id, ship_type, owner_user_id, faction,
                             x, y, hp, facing, carrier_ship_id)
          values (s.system_id, f.id, s.owner_user_id, s.faction,
                  null, null, coalesce(f.max_hp, 90), s.facing, s.id);
        end loop;

        for i in 1..coalesce(o.bombers, 0) loop
          exit when b.id is null;
          insert into ships (system_id, ship_type, owner_user_id, faction,
                             x, y, hp, facing, carrier_ship_id)
          values (s.system_id, b.id, s.owner_user_id, s.faction,
                  null, null, coalesce(b.max_hp, 140), s.facing, s.id);
        end loop;
      end if;
    end if;

    update repair_orders set delivered = true where id = o.id;

    perform log_event(o.owner_user_id, o.faction, o.system_id, 'repair_done',
                      null, 1, 'private', jsonb_build_object('kind', o.kind, 'unit_id', o.unit_id, 'ship_id', o.ship_id,
     'layer', case when o.ship_id is not null then 'space' else 'ground' end));
  end loop;
end;
$$;


--
-- Name: deliver_ready_research(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_ready_research() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare o record;
begin
  for o in
    select ro.*, rs.name
    from research_orders ro
    join researches rs on rs.id = ro.research_id
    where not ro.delivered and ro.completes_at <= now()
    for update of ro skip locked
  loop
    insert into player_research (user_id, research_id)
    values (o.owner_user_id, o.research_id)
    on conflict do nothing;

    update research_orders set delivered = true where id = o.id;

    -- Событие личное: изученное принадлежит игроку, союзникам оно
    -- ничего не даёт
    perform log_event(o.owner_user_id, o.faction, o.system_id,
                      'research_done', o.name, 1, 'private', jsonb_build_object('slot', (select b.slot_index from buildings b where b.id = o.building_id)));
  end loop;
end;
$$;


--
-- Name: deliver_ready_ships(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_ready_ships() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  o record; slot record; t record; f record; b record;
  cx integer; cy integer; r integer; dx integer; dy integer;
  v_placed boolean; v_ship uuid; i integer; v_facing integer;
begin
  for o in
    select * from ship_orders
    where not delivered and completes_at <= now()
    order by completes_at
    for update skip locked
  loop
    select * into slot from station_slots where system_id = o.system_id;
    if not found then continue; end if;

    select * into t from ship_types where id = o.ship_type;
    v_facing := hyperspace_facing(hyperspace_side(o.system_id, o.faction));
    v_placed := false;

    for r in 1..40 loop
      exit when v_placed;
      for dy in -r..r loop
        exit when v_placed;
        for dx in -r..r loop
          continue when abs(dx) <> r and abs(dy) <> r;

          cx := slot.x + dx * ship_box_w(t.width_cells, t.height_cells, v_facing);
          cy := slot.y + dy * ship_box_h(t.width_cells, t.height_cells, v_facing);

          continue when hyperspace_band_at(cy, ship_box_h(t.width_cells, t.height_cells, v_facing)) is not null;

          if is_ship_space_free(o.system_id, cx, cy,
                ship_box_w(t.width_cells, t.height_cells, v_facing),
                ship_box_h(t.width_cells, t.height_cells, v_facing)) then

            insert into ships (system_id, ship_type, owner_user_id, faction, x, y, hp, facing)
            values (o.system_id, o.ship_type, o.owner_user_id, o.faction, cx, cy,
                    coalesce(t.max_hp, 1000), v_facing)
            returning id into v_ship;

            if coalesce(array_length(o.upgrades, 1), 0) > 0 then
              perform apply_ship_upgrades(v_ship, o.upgrades);
            end if;

            select * into f from ship_types
            where faction = o.faction and is_fighter and hull_class = 'fighter' limit 1;
            select * into b from ship_types
            where faction = o.faction and is_fighter and hull_class = 'bomber' limit 1;

            for i in 1..coalesce(o.fighters, 0) loop
              exit when f.id is null;
              insert into ships (system_id, ship_type, owner_user_id, faction,
                                 x, y, hp, facing, carrier_ship_id)
              values (o.system_id, f.id, o.owner_user_id, o.faction,
                      null, null, coalesce(f.max_hp, 90), v_facing, v_ship);
            end loop;

            for i in 1..coalesce(o.bombers, 0) loop
              exit when b.id is null;
              insert into ships (system_id, ship_type, owner_user_id, faction,
                                 x, y, hp, facing, carrier_ship_id)
              values (o.system_id, b.id, o.owner_user_id, o.faction,
                      null, null, coalesce(b.max_hp, 140), v_facing, v_ship);
            end loop;

            update ship_orders set delivered = true where id = o.id;
            v_placed := true;
            exit;
          end if;
        end loop;
      end loop;
    end loop;
  end loop;
end;
$$;


--
-- Name: deliver_ready_training(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_ready_training() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare o record; u record; t record; spot record;
begin
  for o in
    select * from hero_training
    where not delivered and completes_at <= now()
    order by completes_at
    for update skip locked
  loop
    insert into hero_learned (hero_id, ability_id)
    values (o.hero_id, o.ability_id)
    on conflict do nothing;

    perform hero_apply_passives(o.hero_id);

    select * into u from unit_positions where hero_id = o.hero_id;

    if not found then
      -- юнита нет вовсе: герой погиб, пока учился
      update hero_training set delivered = true where id = o.id;
      continue;
    end if;

    select * into t from unit_types where id = u.unit_type;

    select * into spot
    from find_deploy_box(u.system_id, t.width_cells, t.height_cells, 0, 0)
    limit 1;

    if not found then
      continue;   -- в зонах высадки тесно, вернём на следующем тике
    end if;

    update unit_positions
    set x = spot.x, y = spot.y, training_until = null,
        ap = 2, ap_updated_at = now()
    where id = u.id;

    update hero_training set delivered = true where id = o.id;

    perform log_event(o.owner_user_id, u.faction, u.system_id, 'hero_trained',
                      u.hero_name, 1, 'private',
                      jsonb_build_object('ability', o.ability_id, 'unit_id', u.id, 'x', u.x, 'y', u.y));
  end loop;
end;
$$;


--
-- Name: deliver_ready_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_ready_units() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  o record; spot record; placed integer; v_hp integer; v_w integer; v_h integer; v_new uuid; h record;
begin
  for o in select * from unit_orders where not delivered and completes_at <= now() order by completes_at for update skip locked loop
    select max_hp, width_cells, height_cells into v_hp, v_w, v_h from unit_types where id = o.unit_type;
    v_w := coalesce(v_w, 1); v_h := coalesce(v_h, 1);
    placed := 0;
    while placed < o.quantity loop
      -- у постройки; если вокруг неё всё занято — в зоне высадки, как раньше
      select * into spot from find_spawn_box_near(o.system_id, o.building_id, v_w, v_h) limit 1;
      if not found then
        select * into spot from find_deploy_box(o.system_id, v_w, v_h, coalesce(o.target_x, 0), coalesce(o.target_y, 0)) limit 1;
      end if;
      exit when not found;
      insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type, quantity, hp)
      values (o.system_id, 'ground', spot.x, spot.y, o.owner_user_id, o.faction, o.unit_type, 1, coalesce(v_hp, 100))
      returning id into v_new;
      if o.hero_id is not null then
        select name, portrait into h from heroes where id = o.hero_id;
        if found then update unit_positions set hero_id = o.hero_id, hero_name = h.name, portrait = h.portrait where id = v_new; end if;
      end if;
      if coalesce(array_length(o.upgrades, 1), 0) > 0 then perform apply_unit_upgrades(v_new, o.upgrades); end if;
      placed := placed + 1;
    end loop;
    if placed >= o.quantity then
      update unit_orders set delivered = true where id = o.id;
    elsif placed > 0 then
      update unit_orders set quantity = quantity - placed where id = o.id;
    end if;
  end loop;
end;
$$;


--
-- Name: demolish_building(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.demolish_building(p_building_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_system_id text; v_building_type_id uuid;
  v_bld_faction text; v_sys_faction text;
  v_cost integer; v_half integer; v_pending integer; v_credits integer;
begin
  if v_user_id is null then raise exception 'Не авторизован'; end if;

  select system_id, building_type_id, faction
    into v_system_id, v_building_type_id, v_bld_faction
  from buildings where id = p_building_id for update;

  if v_system_id is null then raise exception 'Постройка не найдена'; end if;

  perform assert_planet_operational(v_system_id);

  if not exists (
    select 1 from system_control sc
    where sc.system_id = v_system_id and sc.controller_user_id = v_user_id
  ) then
    raise exception 'Нет прав на снос в этой системе';
  end if;

  if exists (select 1 from production_leases l where l.building_id = p_building_id
             and l.status in ('offered','active') and lease_effective_status(l) in ('offered','active')) then
    raise exception 'Здание сдано в аренду или предложено — дождись конца срока или отзови предложение';
  end if;

  v_pending := building_line_used(p_building_id);

  if v_pending > 0 then
    raise exception 'Сначала дождись окончания производства: в очереди % заказ(ов)', v_pending;
  end if;

  select cost into v_cost from building_types where id = v_building_type_id;
  v_half := floor(coalesce(v_cost, 0) / 2.0);

  select faction into v_sys_faction from systems where id = v_system_id;

  if v_bld_faction is distinct from v_sys_faction then
    select credits into v_credits from profiles where id = v_user_id;
    if v_credits < v_half then
      raise exception 'Снос трофейной постройки стоит %, не хватает кредитов', v_half;
    end if;
    delete from buildings where id = p_building_id;
    update profiles set credits = credits - v_half where id = v_user_id;
  else
    delete from buildings where id = p_building_id;
    update profiles set credits = credits + v_half where id = v_user_id;
    perform refund_build_resources(v_system_id,
      (select cost_resources from building_types where id = v_building_type_id), 0.5);
  end if;
end;
$$;


--
-- Name: demolish_district(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.demolish_district(p_system_id text, p_slot integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_cost integer; v_back integer; v_faction text; v_res jsonb;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  if not exists (select 1 from system_control where system_id = p_system_id and controller_user_id = v_me) then
    raise exception 'Сносить кварталы может только управляющий планетой';
  end if;
  select faction into v_faction from profiles where id = v_me for update;
  if (select faction from systems where id = p_system_id) is distinct from v_faction then
    raise exception 'Планета чужой фракции';
  end if;
  perform assert_planet_operational(p_system_id);

  select dt.cost_credits, dt.cost_resources into v_cost, v_res
  from settlement_districts sd join district_types dt on dt.id = sd.district_id
  where sd.system_id = p_system_id and sd.slot = p_slot for update of sd;
  if not found then raise exception 'На участке ничего нет'; end if;

  v_back := coalesce(v_cost, 0) / 2;
  delete from settlement_districts where system_id = p_system_id and slot = p_slot;
  update profiles set credits = credits + v_back where id = v_me;
  perform refund_build_resources(p_system_id, v_res, 0.5);
  return v_back;
end;
$$;


--
-- Name: demolish_space_station(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.demolish_space_station(p_system_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_faction text; v_credits integer; v_cost integer; v_half integer;
  v_station_faction text; v_sys_faction text;
begin
  if v_user_id is null then raise exception 'Не авторизован'; end if;

  perform assert_planet_operational(p_system_id);

  if not exists (
    select 1 from system_control sc
    where sc.system_id = p_system_id and sc.controller_user_id = v_user_id
  ) then
    raise exception 'Нет прав на снос в этой системе';
  end if;

  if exists (select 1 from production_leases l where l.system_id = p_system_id and l.building_id is null
             and l.status in ('offered','active') and lease_effective_status(l) in ('offered','active')) then
    raise exception 'Верфь сдана в аренду или предложена — дождись конца срока или отзови предложение';
  end if;

  select faction into v_station_faction from space_stations where system_id = p_system_id for update;
  if v_station_faction is null then raise exception 'Станция не найдена'; end if;

  if exists (select 1 from ship_orders so
             where so.system_id = p_system_id and not so.delivered) then
    raise exception 'Сначала дождись схода корабля со стапеля';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user_id;
  select faction into v_sys_faction from systems where id = p_system_id;

  select cost into v_cost from building_types
  where is_space and faction = v_station_faction limit 1;
  v_half := floor(coalesce(v_cost, 5000) / 2.0);

  if v_station_faction is distinct from v_sys_faction then
    -- Трофейная: расчистка космоса стоит денег, как и на земле
    if v_credits < v_half then
      raise exception 'Снос вражеской станции стоит %, не хватает кредитов', v_half;
    end if;
    delete from space_stations where system_id = p_system_id;
    update profiles set credits = credits - v_half where id = v_user_id;
  else
    delete from space_stations where system_id = p_system_id;
    update profiles set credits = credits + v_half where id = v_user_id;
  end if;
end;
$$;


--
-- Name: demolish_structure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.demolish_structure(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); s record; v_back integer; v_hp bigint; v_max bigint; v_res jsonb;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select fs.owner_user_id, fs.hp, st.cost, st.max_hp, st.cost_resources, fs.system_id into s
  from field_structures fs join structure_types st on st.id = fs.type_id
  where fs.id = p_id for update of fs;
  if not found then raise exception 'Укрепление не найдено'; end if;
  if s.owner_user_id is distinct from v_user then raise exception 'Разобрать может только тот, кто строил'; end if;

  v_max := greatest(1, coalesce(s.max_hp, 1));
  v_hp := greatest(0, least(coalesce(s.hp, 0), v_max));
  v_back := (coalesce(s.cost, 0)::bigint * v_hp / (2 * v_max))::integer;
  delete from field_structures where id = p_id;
  update profiles set credits = credits + v_back where id = v_user;
  if (select faction from systems where id = s.system_id)
     is not distinct from (select faction from profiles where id = v_user) then
    select jsonb_object_agg(e.key, coalesce((e.value #>> '{}')::bigint, 0) * v_hp / (2 * v_max))
      into v_res from jsonb_each(coalesce(s.cost_resources, '{}'::jsonb)) e;
    perform refund_build_resources(s.system_id, v_res, 1);
  end if;
  return v_back;
end;
$$;


--
-- Name: destroy_structure(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.destroy_structure(p_id uuid, p_by uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s record;
begin
  select fs.*, st.name as type_name into s
  from field_structures fs join structure_types st on st.id = fs.type_id
  where fs.id = p_id;
  if not found then return; end if;

  perform log_event(s.owner_user_id, s.faction, s.system_id, 'structure_lost', s.type_name, 1, 'private',
                    jsonb_build_object('x', s.x, 'y', s.y));
  if p_by is not null and p_by is distinct from s.owner_user_id then
    perform log_event(p_by, (select faction from profiles where id = p_by), s.system_id,
                      'structure_destroyed', s.type_name, 1, 'private', jsonb_build_object('x', s.x, 'y', s.y));
  end if;
  delete from field_structures where id = p_id;
end;
$$;


--
-- Name: dev_admin_grant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_admin_grant(p_user uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into dev_admins (user_id, note) values (p_user, p_note)
  on conflict (user_id) do update set revoked_at = null, granted_at = now(), note = coalesce(excluded.note, dev_admins.note);
$$;


--
-- Name: dev_admin_revoke(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_admin_revoke(p_user uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update dev_admins set revoked_at = now() where user_id = p_user and revoked_at is null;
$$;


--
-- Name: dev_assert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_assert() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v uuid := auth.uid();
begin
  if v is null or not exists (select 1 from dev_admins where user_id = v and revoked_at is null) then
    raise exception 'Нет доступа' using errcode = '42501';
  end if;
  return v;
end;
$$;


--
-- Name: dev_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_catalog() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert();
begin
  return jsonb_build_object(
    'me', v_me,
    'players', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'nick', coalesce(p.nickname, '—'), 'faction', p.faction, 'credits', p.credits,
                        'planet', (select sc.system_id from system_control sc where sc.controller_user_id = p.id limit 1)) order by p.nickname), '[]') from profiles p),
    'systems', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'faction', s.faction, 'station', exists (select 1 from station_slots z where z.system_id = s.id)) order by s.name), '[]') from systems s),
    'resources', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name) order by r.name), '[]') from resources r),
    'units', (select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name, 'faction', u.faction, 'vehicle', coalesce(u.is_vehicle, false)) order by u.faction, coalesce(u.is_vehicle, false), u.name), '[]')
                from unit_types u where not coalesce(u.is_hero, false) and u.faction in ('republic', 'cis')),
    'ships', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'faction', t.faction, 'cls', t.hull_class) order by t.faction, t.max_hp, t.name), '[]')
                from ship_types t where not coalesce(t.is_fighter, false) and t.faction in ('republic', 'cis'))
  );
end;
$$;


--
-- Name: dev_client_error_resolve(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_client_error_resolve(p_sig text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_n integer;
begin
  update client_errors set resolved_at = now(), resolved_by = v_me
   where (p_sig is null and (resolved_at is null or last_at > resolved_at)) or sig = p_sig;
  get diagnostics v_n = row_count;
  perform dev_note(v_me, 'errors_resolved', null, null, jsonb_build_object('n', v_n));
  return v_n;
end;
$$;


--
-- Name: dev_client_errors(boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_client_errors(p_open boolean DEFAULT true, p_limit integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  perform dev_assert();
  select coalesce(jsonb_agg(x order by x.last_at desc), '[]'::jsonb) into v from (
    select c.sig, c.msg, c.src, c.line, c.col, c.stack, c.page, c.ctx, c.ua, c.n, c.users,
           c.first_at, c.last_at, c.resolved_at, p.nickname as last_nick,
           (c.resolved_at is not null and c.last_at > c.resolved_at) as again
      from client_errors c left join profiles p on p.id = c.last_user
     where not coalesce(p_open, true) or c.resolved_at is null or c.last_at > c.resolved_at
     order by c.last_at desc
     limit least(greatest(coalesce(p_limit, 60), 1), 200)
  ) x;
  return jsonb_build_object(
    'rows', v,
    'open', (select count(*) from client_errors c where c.resolved_at is null or c.last_at > c.resolved_at),
    'day',  (select count(*) from client_errors c where c.last_at > now() - interval '24 hours'),
    'total', (select count(*) from client_errors));
end;
$$;


--
-- Name: dev_credits(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_credits(p_user uuid, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_new integer;
begin
  if p_amount is null or abs(p_amount) > 10000000 then raise exception 'Сумма от −10 000 000 до 10 000 000'; end if;
  update profiles set credits = greatest(0, credits + p_amount) where id = p_user returning credits into v_new;
  if not found then raise exception 'Игрок не найден'; end if;
  perform dev_note(v_me, 'credits', p_user, null, jsonb_build_object('amount', p_amount, 'now', v_new));
  return v_new;
end;
$$;


--
-- Name: dev_error_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_error_counts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform dev_assert();
  return jsonb_build_object(
    'client', (select count(*) from client_errors c where c.resolved_at is null or c.last_at > c.resolved_at),
    'server', (select count(*) from server_errors e where e.resolved_at is null or e.last_at > e.resolved_at));
end;
$$;


--
-- Name: dev_event_recent(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_event_recent(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert();
begin
  return (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'event', m.event_id, 'tier', m.tier, 'map', m.map, 'status', m.status, 'test', m.test,
            'at', m.created_at, 'winner', m.winner, 'why', m.result->>'why', 't', (m.result->>'t')::integer,
            'players', (select jsonb_agg(coalesce(p->>'nick', p->>'user')) from jsonb_array_elements(m.players) p)) order by m.created_at desc), '[]'::jsonb)
          from (select * from event_matches order by created_at desc limit greatest(1, least(50, p_limit))) m);
end;
$$;


--
-- Name: dev_event_start(text, integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_event_start(p_event text, p_tier integer, p_role text, p_map text DEFAULT NULL::text, p_bots integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); e record; r jsonb; v_players jsonb := '[]'::jsonb; v_id uuid; v_nick text; v_side text; i integer; n integer;
begin
  select * into e from event_catalog where id = p_event;
  if not found or not e.ready then raise exception 'Этот ивент ещё не открыт'; end if;
  if p_map is not null and not (p_map = any(e.maps)) then raise exception 'У ивента нет такой карты'; end if;
  select nickname, faction into v_nick, v_side from profiles where id = v_me;
  update event_queue set state = 'left', left_at = now() where user_id = v_me and state = 'waiting';
  update event_matches set status = 'aborted', ended_at = now(), result = jsonb_build_object('why', 'новый тест')
   where status in ('forming', 'live') and test and created_by = v_me;
  for r in select * from jsonb_array_elements(e.roles) loop
    if r->>'id' = p_role then
      v_players := v_players || jsonb_build_array(jsonb_build_object('user', v_me, 'role', p_role, 'side', r->>'side', 'nick', v_nick));
      n := greatest((r->>'min')::integer - 1, case when e.kind = 'pve' then least((r->>'max')::integer, coalesce(p_bots, 1)) - 1 else 0 end);
    else
      n := case when (r->>'max')::integer = 1 then 1 else greatest((r->>'min')::integer, least((r->>'max')::integer, coalesce(p_bots, 1))) end;
    end if;
    for i in 1..n loop
      v_players := v_players || jsonb_build_array(jsonb_build_object('user', 'bot:' || (r->>'id') || ':' || i, 'role', r->>'id', 'side', r->>'side', 'bot', true));
    end loop;
  end loop;
  if not exists (select 1 from jsonb_array_elements(v_players) p where p->>'user' = v_me::text) then raise exception 'Нет такой роли'; end if;
  insert into event_matches (event_id, tier, map, players, test, created_by)
  values (p_event, greatest(1, least(3, p_tier)), coalesce(p_map, e.maps[1 + floor(random() * array_length(e.maps, 1))::integer]), v_players, true, v_me)
  returning id into v_id;
  insert into dev_log (admin, action, target, data) values (v_me, 'event_start', v_me, jsonb_build_object('event', p_event, 'tier', p_tier, 'role', p_role, 'match', v_id));
  return event_status();
end;
$$;


--
-- Name: dev_finish(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_finish(p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); a integer; b integer; c integer; d integer; e integer; f integer; g integer; h integer;
begin
  if not exists (select 1 from systems where id = p_system) then raise exception 'Нет такой планеты'; end if;
  update buildings set completes_at = now() where system_id = p_system and completes_at > now(); get diagnostics a = row_count;
  update unit_orders set completes_at = now() where system_id = p_system and not coalesce(delivered, false) and completes_at > now(); get diagnostics b = row_count;
  update research_orders set completes_at = now() where system_id = p_system and not coalesce(delivered, false) and completes_at > now(); get diagnostics c = row_count;
  update ship_orders set completes_at = now() where system_id = p_system and not coalesce(delivered, false) and completes_at > now(); get diagnostics d = row_count;
  update repair_orders set completes_at = now() where system_id = p_system and not coalesce(delivered, false) and completes_at > now(); get diagnostics e = row_count;
  update field_structures set completes_at = now() where system_id = p_system and completes_at > now(); get diagnostics f = row_count;
  update space_stations set completes_at = now() where system_id = p_system and completes_at > now(); get diagnostics g = row_count;
  update settlement_state set upgrade_until = now() where system_id = p_system and upgrade_until > now(); get diagnostics h = row_count;
  perform settle_due_orders();
  perform dev_note(v_me, 'finish', null, p_system, jsonb_build_object('buildings', a, 'units', b, 'research', c, 'ships', d, 'repairs', e, 'structs', f, 'station', g, 'settlement', h));
  return jsonb_build_object('buildings', a, 'units', b, 'research', c, 'ships', d, 'repairs', e, 'structs', f, 'station', g, 'settlement', h);
end;
$$;


--
-- Name: dev_galaxy_event_end(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_galaxy_event_end(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert();
begin
  update galaxy_events set status = 'ended', ends_at = least(ends_at, now()) where id = p_id;
  update faction_effects set ends_at = least(ends_at, now()) where source = 'event:' || p_id;
  perform dev_note(v_me, 'galaxy_event_end', null, null, jsonb_build_object('event', p_id));
end;
$$;


--
-- Name: dev_galaxy_event_start(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_galaxy_event_start(p_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_id uuid;
begin
  v_id := ge_start(p_type, true);
  if v_id is null then raise exception 'Цели для события не нашлось — все подходящие планеты заняты другими событиями'; end if;
  perform dev_note(v_me, 'galaxy_event', null, null, jsonb_build_object('type', p_type, 'event', v_id));
  return jsonb_build_object('id', v_id, 'systems', (select systems from galaxy_events where id = v_id));
end;
$$;


--
-- Name: dev_galaxy_event_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_galaxy_event_types() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert();
begin
  return (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'title', title, 'scope', scope, 'tone', tone) order by sort), '[]'::jsonb)
          from galaxy_event_types where active);
end;
$$;


--
-- Name: dev_is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select auth.uid() is not null and exists (select 1 from dev_admins where user_id = auth.uid() and revoked_at is null);
$$;


--
-- Name: dev_loyalty(text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_loyalty(p_system text, p_value integer, p_cell_faction text DEFAULT NULL::text, p_cell_level integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_me uuid := dev_assert(); v_del text := 'del' || 'ete from ';
begin
  if not exists (select 1 from planet_loyalty where system_id = p_system) then raise exception 'У планеты нет шкалы настроений'; end if;
  if p_value is not null then
    if p_value < -100 or p_value > 100 then raise exception 'Шкала от −100 до 100'; end if;
    perform loyalty_set(p_system, p_value, null, 'dev');
  end if;
  if p_cell_faction is not null then
    if p_cell_faction not in ('republic', 'cis') then raise exception 'Сторона — republic или cis'; end if;
    if coalesce(p_cell_level, 0) <= 0 then
      execute v_del || 'loyalty_cells where system_id = $1 and faction = $2' using p_system, p_cell_faction;
    else
      insert into loyalty_cells (system_id, faction, level) values (p_system, p_cell_faction, least(3, p_cell_level))
      on conflict (system_id, faction) do update set level = excluded.level, updated_at = now();
    end if;
  end if;
  perform dev_note(v_me, 'loyalty', null, p_system, jsonb_build_object('value', p_value, 'cell', p_cell_faction, 'level', p_cell_level));
  return (select jsonb_build_object('v', value, 'cells', (select coalesce(jsonb_agg(jsonb_build_object('faction', faction, 'level', level)), '[]'::jsonb)
            from loyalty_cells where system_id = p_system)) from planet_loyalty where system_id = p_system);
end;
$_$;


--
-- Name: dev_note(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_note(p_admin uuid, p_action text, p_target uuid, p_system text, p_data jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into dev_log (admin, action, target, system_id, data) values (p_admin, p_action, p_target, p_system, p_data);
$$;


--
-- Name: dev_recent(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_recent(p_limit integer DEFAULT 30) RETURNS TABLE(at timestamp with time zone, admin text, action text, target text, system_id text, data jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform dev_assert();
  return query
  select l.at, coalesce(pa.nickname, '?'), l.action, pt.nickname, l.system_id, l.data
    from dev_log l left join profiles pa on pa.id = l.admin left join profiles pt on pt.id = l.target
   order by l.id desc limit least(greatest(coalesce(p_limit, 30), 1), 100);
end;
$$;


--
-- Name: dev_report_send(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_report_send(p_user uuid, p_report text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_side text; v_sys text; v_pick text; v_id uuid;
begin
  select faction into v_side from profiles where id = p_user;
  if v_side is null then raise exception 'У игрока нет стороны'; end if;
  select system_id into v_sys from system_control where controller_user_id = p_user order by random() limit 1;
  if v_sys is null then raise exception 'У игрока нет своей планеты — донесениям некуда приходить'; end if;
  v_pick := coalesce(p_report, report_pick(p_user, v_side), (select id from report_catalog where side = v_side and active and not chain and cat <> 'site' order by random() limit 1));
  if not exists (select 1 from report_catalog where id = v_pick and side = v_side) then raise exception 'Донесение другой стороны'; end if;
  if (select cat from report_catalog where id = v_pick) = 'site' then raise exception 'Донесения участков приходят сами — им нужен участок'; end if;
  v_id := report_deliver(p_user, v_pick, v_sys, null);
  perform dev_note(v_me, 'report_send', p_user, v_sys, jsonb_build_object('report', v_pick));
  return jsonb_build_object('id', v_id, 'report', v_pick, 'system', v_sys);
end;
$$;


--
-- Name: dev_research_all(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_research_all(p_user uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_faction text; n integer;
begin
  select faction into v_faction from profiles where id = p_user;
  if v_faction not in ('republic', 'cis') then raise exception 'У игрока нет фракции'; end if;
  insert into player_research (user_id, research_id)
  select p_user, r.id from researches r
   where r.id not like (case v_faction when 'republic' then 'cis\_%' else 'rep\_%' end)
  on conflict do nothing;
  get diagnostics n = row_count;
  perform dev_note(v_me, 'research_all', p_user, null, jsonb_build_object('added', n));
  return n;
end;
$$;


--
-- Name: dev_server_error_resolve(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_server_error_resolve(p_sig text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_n integer;
begin
  update server_errors set resolved_at = now(), resolved_by = v_me
   where (p_sig is null and (resolved_at is null or last_at > resolved_at)) or sig = p_sig;
  get diagnostics v_n = row_count;
  perform dev_note(v_me, 'errors_resolved', null, null, jsonb_build_object('n', v_n, 'server', true));
  return v_n;
end;
$$;


--
-- Name: dev_server_errors(boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_server_errors(p_open boolean DEFAULT true, p_limit integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  perform dev_assert();
  select coalesce(jsonb_agg(x order by x.last_at desc), '[]'::jsonb) into v from (
    select e.sig, e.source, e.ctx, e.msg, e.state, e.data, e.n, e.first_at, e.last_at, e.resolved_at,
           (e.resolved_at is not null and e.last_at > e.resolved_at) as again
      from server_errors e
     where not coalesce(p_open, true) or e.resolved_at is null or e.last_at > e.resolved_at
     order by e.last_at desc
     limit least(greatest(coalesce(p_limit, 60), 1), 200)) x;
  return jsonb_build_object(
    'rows', v,
    'open', (select count(*) from server_errors e where e.resolved_at is null or e.last_at > e.resolved_at),
    'day', (select count(*) from server_errors e where e.last_at > now() - interval '24 hours'),
    'total', (select count(*) from server_errors));
end;
$$;


--
-- Name: dev_settlement_level(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_settlement_level(p_system text, p_level integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert();
begin
  if p_level is null or p_level < 1 or p_level > 4 then raise exception 'Уровень от 1 до 4'; end if;
  update settlement_state set level = p_level, upgrade_until = null, upgrade_to = null where system_id = p_system;
  if not found then raise exception 'У планеты нет поселения'; end if;
  perform dev_note(v_me, 'settlement_level', null, p_system, jsonb_build_object('level', p_level));
end;
$$;


--
-- Name: dev_ships(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_ships(p_user uuid, p_system text, p_ship_type text, p_qty integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_faction text; v_st record; i integer; v_ids uuid[] := '{}'; v_id uuid; v_ok integer;
begin
  select faction into v_faction from profiles where id = p_user;
  if v_faction not in ('republic', 'cis') then raise exception 'У игрока нет фракции'; end if;
  select * into v_st from ship_types where id = p_ship_type;
  if not found or coalesce(v_st.is_fighter, false) then raise exception 'Нет такого корабля'; end if;
  if v_st.faction is distinct from v_faction then raise exception 'Корабль другой фракции'; end if;
  if not exists (select 1 from station_slots where system_id = p_system) then raise exception 'У этой системы нет орбиты со станцией'; end if;
  if p_qty is null or p_qty < 1 or p_qty > 5 then raise exception 'От 1 до 5 за раз'; end if;
  for i in 1..p_qty loop
    insert into ship_orders (system_id, ship_type, owner_user_id, faction, completes_at, fighters, bombers, upgrades)
    values (p_system, p_ship_type, p_user, v_faction, now(), coalesce(v_st.hangar_slots, 0), 0, '{}') returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  perform deliver_ready_ships();
  select count(*) into v_ok from ship_orders where id = any(v_ids) and delivered;
  update ship_orders set delivered = true where id = any(v_ids) and not delivered;
  perform dev_note(v_me, 'ships', p_user, p_system, jsonb_build_object('type', p_ship_type, 'qty', p_qty, 'placed', v_ok));
  return v_ok;
end;
$$;


--
-- Name: dev_stock(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_stock(p_system text, p_resource text, p_amount integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); r record;
begin
  if not exists (select 1 from systems where id = p_system) then raise exception 'Нет такой планеты'; end if;
  if p_amount is null or abs(p_amount) > 1000000 then raise exception 'Количество от −1 000 000 до 1 000 000'; end if;
  if p_resource <> 'all' and not exists (select 1 from resources where id = p_resource) then raise exception 'Нет такого сырья'; end if;
  for r in select id from resources where p_resource = 'all' or id = p_resource loop
    insert into planet_stock (system_id, resource, amount) values (p_system, r.id, greatest(0, p_amount))
    on conflict (system_id, resource) do update set amount = greatest(0, planet_stock.amount + p_amount);
  end loop;
  perform dev_note(v_me, 'stock', null, p_system, jsonb_build_object('resource', p_resource, 'amount', p_amount));
  return (select coalesce(jsonb_object_agg(resource, amount), '{}') from planet_stock where system_id = p_system);
end;
$$;


--
-- Name: dev_tutorial_done(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_tutorial_done(p_user uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_ord integer;
begin
  update tutorial_state set step_done = true where user_id = p_user and status = 'active' returning step_ord into v_ord;
  if not found then raise exception 'Обучение не идёт'; end if;
  perform dev_note(v_me, 'tutorial_done', p_user, null, jsonb_build_object('step', v_ord));
  return v_ord;
end;
$$;


--
-- Name: dev_units(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_units(p_user uuid, p_system text, p_unit_type text, p_qty integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_faction text; v_ut record; v_id uuid; v_left integer;
begin
  select faction into v_faction from profiles where id = p_user;
  if v_faction not in ('republic', 'cis') then raise exception 'У игрока нет фракции'; end if;
  select * into v_ut from unit_types where id = p_unit_type;
  if not found or coalesce(v_ut.is_hero, false) then raise exception 'Нет такого бойца'; end if;
  if v_ut.faction is distinct from v_faction then raise exception 'Боец другой фракции'; end if;
  if not exists (select 1 from systems where id = p_system) then raise exception 'Нет такой планеты'; end if;
  if p_qty is null or p_qty < 1 or p_qty > 50 then raise exception 'От 1 до 50 за раз'; end if;
  insert into unit_orders (system_id, building_id, unit_type, owner_user_id, faction, quantity, completes_at, upgrades)
  values (p_system, null, p_unit_type, p_user, v_faction, p_qty, now(), '{}') returning id into v_id;
  perform deliver_ready_units();
  select case when delivered then 0 else quantity end into v_left from unit_orders where id = v_id;
  if coalesce(v_left, 0) > 0 then update unit_orders set delivered = true where id = v_id; end if;
  perform dev_note(v_me, 'units', p_user, p_system, jsonb_build_object('type', p_unit_type, 'qty', p_qty, 'placed', p_qty - coalesce(v_left, 0)));
  return p_qty - coalesce(v_left, 0);
end;
$$;


--
-- Name: dev_void_find_poke(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_void_find_poke(p_find uuid, p_what text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); f record; v_need int := greatest(1, game_setting_int('void_find_hold_min', 180)) * 60;
begin
  select * into f from void_finds where id = p_find and status = 'active';
  if not found then raise exception 'Находка уже закрыта'; end if;
  if p_what = 'guards' then
    update void_finds set guards = (select coalesce(jsonb_agg(g || '{"hp":0}'::jsonb order by (g ->> 'i')::int), '[]'::jsonb) from jsonb_array_elements(guards) g),
                          guards_down_at = coalesce(guards_down_at, now()), tick_at = now()
     where id = f.id;
  elsif p_what = 'hold:republic' then
    update void_finds set hold_rep = greatest(hold_rep, v_need - 60), guards_down_at = coalesce(guards_down_at, now()) where id = f.id;
  elsif p_what = 'hold:cis' then
    update void_finds set hold_cis = greatest(hold_cis, v_need - 60), guards_down_at = coalesce(guards_down_at, now()) where id = f.id;
  elsif p_what = 'end' then
    perform void_find_finish(f.id, null);
  else
    raise exception 'Неизвестное действие';
  end if;
  perform dev_note(v_me, 'void_find', null, null, jsonb_build_object('find', f.id, 'what', p_what));
  return void_find_room(f.system_id);
end $$;


--
-- Name: dev_void_find_start(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_void_find_start(p_type text DEFAULT NULL::text, p_system text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := dev_assert(); v_id uuid;
begin
  v_id := void_find_spawn(nullif(p_type, ''), nullif(p_system, ''), true);
  if v_id is null then raise exception 'Свободного узла на фронте не нашлось'; end if;
  perform dev_note(v_me, 'void_find', null, null, jsonb_build_object('type', p_type, 'find', v_id));
  return jsonb_build_object('id', v_id, 'system', (select system_id from void_finds where id = v_id));
end $$;


--
-- Name: dispatch_market_pickup(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_market_pickup(p_commander_id uuid, p_order_id uuid, p_to_system text, p_return_home boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  cm record; o record; v_pickup text; v_res text; v_faction text; v_pfac text; v_to_faction text; v_to_name text;
  v_free integer; v_ships integer; v_path text[]; v_back text[]; v_hops integer; v_sec integer; v_stops jsonb;
  v_id uuid; v_name text; v_pname text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if not supply_has_hub(v_user) then
    raise exception 'Нужен штаб снабжения: достроенный логистический узел хотя бы на одной планете';
  end if;

  select * into o from market_orders where id = p_order_id for update;
  if not found or o.buyer_user_id <> v_user then raise exception 'Бронь не найдена'; end if;
  if o.status <> 'reserved' or o.amount_left <= 0 then raise exception 'Бронь уже закрыта'; end if;
  if o.expires_at <= now() then raise exception 'Срок брони истёк'; end if;
  if exists (select 1 from supply_routes sr where sr.order_id = p_order_id and sr.status <> 'stopped') then
    raise exception 'За этой покупкой уже отправлен флот';
  end if;

  select l.system_id, l.resource into v_pickup, v_res from market_lots l where l.id = o.lot_id;
  select s.faction, s.name into v_pfac, v_pname from systems s where s.id = v_pickup;
  select faction into v_faction from profiles where id = v_user;

  select * into cm from commanders where id = p_commander_id and user_id = v_user for update;
  if not found then raise exception 'Командир не найден'; end if;
  if not cm.unlocked then raise exception 'Командир ещё не открыт'; end if;
  if cm.moving_to is not null then raise exception 'Командир в пути — дождись прибытия'; end if;
  if cm.current_system is null then raise exception 'Неизвестно, где стоит флот'; end if;
  if exists (select 1 from supply_routes sr where sr.commander_id = p_commander_id and sr.status <> 'stopped') then
    raise exception 'У этого командира уже есть рейс — заверши его';
  end if;
  select count(*)::integer into v_ships from ships s where s.commander_id = p_commander_id and s.carrier_ship_id is null;
  if v_ships = 0 then raise exception 'У командира не осталось кораблей'; end if;

  select faction, name into v_to_faction, v_to_name from systems where id = p_to_system and not is_deep_space;
  if v_to_name is null then raise exception 'Такой планеты нет'; end if;
  if v_to_faction is distinct from v_faction then raise exception 'Выгружать можно только на планету своей стороны'; end if;

  -- весь заказ должен влезть: иначе часть осталась бы у продавца
  v_free := commander_free_cargo(p_commander_id);
  if o.amount_left > v_free then
    raise exception 'Во флот не влезет: куплено % ед., свободно % ед.', o.amount_left, v_free;
  end if;

  -- путь к продавцу через свои миры (сама планета продавца может быть чужой) и от него к месту выгрузки
  if cm.current_system = v_pickup then v_path := array[v_pickup];
  elsif v_pfac is distinct from v_faction then v_path := convoy_route_to(cm.current_system, v_pickup, v_faction);
  else v_path := convoy_route(cm.current_system, v_pickup, v_faction); end if;
  if v_path is null then raise exception 'До продавца нет пути через миры своей стороны'; end if;
  if p_to_system <> v_pickup and convoy_route(v_pickup, p_to_system, v_faction) is null then
    raise exception 'От продавца до % нет пути через миры своей стороны', v_to_name;
  end if;

  -- успеет ли флот до конца брони (по времени прыжков без событий)
  v_hops := coalesce(array_length(v_path, 1), 1) - 1;
  v_sec := v_hops * game_setting_int('travel_seconds', 60);
  if now() + make_interval(secs => v_sec) >= o.expires_at then
    raise exception 'Флот не успеет до конца брони: лететь около % мин', ceil(v_sec / 60.0);
  end if;

  v_stops := jsonb_build_array(jsonb_build_object('system_id', v_pickup, 'actions', jsonb_build_array(
               jsonb_build_object('op', 'pickup', 'order_id', p_order_id, 'resource', v_res, 'mode', 'amount', 'amount', o.amount_left))));
  -- выгружается только сама покупка: другой груз в трюмах флота остаётся при нём
  if p_to_system = v_pickup then
    v_stops := jsonb_set(v_stops, '{0,actions}', (v_stops -> 0 -> 'actions')
                 || jsonb_build_array(jsonb_build_object('op', 'unload', 'resource', v_res, 'mode', 'amount', 'amount', o.amount_left)));
  else
    v_stops := v_stops || jsonb_build_array(jsonb_build_object('system_id', p_to_system, 'actions', jsonb_build_array(
                 jsonb_build_object('op', 'unload', 'resource', v_res, 'mode', 'amount', 'amount', o.amount_left))));
  end if;
  if coalesce(p_return_home, false) and cm.current_system not in (p_to_system, v_pickup) then
    if convoy_route(p_to_system, cm.current_system, v_faction) is null then
      raise exception 'От % нет пути домой через миры своей стороны', v_to_name;
    end if;
    v_stops := v_stops || jsonb_build_array(jsonb_build_object('system_id', cm.current_system, 'actions', '[]'::jsonb));
  end if;

  v_name := left('Вывоз: ' || lower(coalesce((select name from resources where id = v_res), v_res)) || ' с ' || v_pname, 40);
  insert into supply_routes (owner_user_id, commander_id, name, stops, loop, status, stop_index, phase,
                             expect_system, last_note, order_id)
  values (v_user, p_commander_id, v_name, v_stops, false, 'active', 0, 'travel',
          cm.current_system, 'Флот отправлен за покупкой', p_order_id)
  returning id into v_id;
  perform supply_log(v_id, cm.current_system, 'Флот отправлен за покупкой: ' || o.amount_left || ' '
    || supply_res_gen(v_res) || ' · ' || v_pname || ' → ' || v_to_name, 0);
  perform log_event(v_user, v_faction, cm.current_system, 'convoy_departed', cm.name, o.amount_left, 'private',
                    jsonb_build_object('pickup', v_pickup, 'to', p_to_system, 'resource', v_res, 'route_id', v_id));

  -- первый шаг сразу, не дожидаясь такта: прыжок или погрузка, если флот уже у продавца.
  -- Встал на первом же шаге (флот не в зоне прыжка и т. п.) — отправка не состоялась, причина игроку
  perform supply_route_step(v_id);
  if (select status from supply_routes where id = v_id) = 'stalled' then
    raise exception '%', (select last_note from supply_routes where id = v_id);
  end if;
  return v_id;
end;
$$;


--
-- Name: drop_hero_with_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_hero_with_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if old.hero_id is not null and not old.delivered then
    delete from heroes where id = old.hero_id;
  end if;
  return old;
end;
$$;


--
-- Name: duel_log(text, uuid, uuid, boolean, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duel_log(p_layer text, p_shooter uuid, p_target uuid, p_hit boolean, p_dmg integer, p_killed boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s jsonb; t jsonb;
begin
  s := duel_snap(p_layer, p_shooter);
  t := duel_snap(p_layer, p_target);
  if s is null or t is null then return; end if;
  if p_killed then t := t || jsonb_build_object('hp', 0); end if;
  perform duel_upsert((s ->> 'owner')::uuid, p_layer, s, t, 'out', p_hit, p_dmg, p_killed);
  perform duel_upsert((t ->> 'owner')::uuid, p_layer, t, s, 'inc', p_hit, p_dmg, p_killed);
  if p_killed then perform set_config('app.duel_kill', p_target::text, true); end if;
end;
$$;


--
-- Name: duel_snap(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duel_snap(p_layer text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r jsonb;
begin
  if p_layer = 'space' then
    select jsonb_build_object('id', s.id, 'owner', s.owner_user_id, 'faction', s.faction,
             'system', s.system_id, 'name', coalesce(s.name, t.name),
             'tname', case when s.name is not null then t.name end, 'img', t.image,
             'hp', greatest(0, s.hp), 'max', t.max_hp + coalesce(s.bonus_hp, 0),
             'x', s.x, 'y', s.y,
             'player', (select nickname from profiles where id = s.owner_user_id))
      into r
    from ships s join ship_types t on t.id = s.ship_type where s.id = p_id;
  else
    select jsonb_build_object('id', u.id, 'owner', u.owner_user_id, 'faction', u.faction,
             'system', u.system_id, 'name', coalesce(u.hero_name, t.name),
             'img', coalesce(u.portrait, t.image), 'veh', coalesce(t.is_vehicle, false),
             'hp', greatest(0, u.hp), 'max', t.max_hp + coalesce(u.bonus_hp, 0),
             'x', u.x, 'y', u.y,
             'player', (select nickname from profiles where id = u.owner_user_id))
      into r
    from unit_positions u join unit_types t on t.id = u.unit_type where u.id = p_id;
  end if;
  return r;
end;
$$;


--
-- Name: duel_upsert(uuid, text, jsonb, jsonb, text, boolean, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duel_upsert(p_user uuid, p_layer text, p_me jsonb, p_en jsonb, p_dir text, p_hit boolean, p_dmg integer, p_killed boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare g record; m jsonb; v_k text; v_us jsonb; v_side jsonb; v_lost jsonb; v_result text;
begin
  if p_user is null or p_me is null or p_en is null then return; end if;
  v_k := p_layer || ':' || (p_en ->> 'id');
  perform pg_advisory_xact_lock(hashtext('duel:' || p_user::text || ':' || v_k));

  select * into g from game_events
  where user_id = p_user and type = 'duel' and meta ->> 'k' = v_k
    and meta ->> 'result' is null
    and created_at > now() - interval '15 minutes'
  order by created_at desc limit 1
  for update;

  m := case when g.id is not null then g.meta else jsonb_build_object(
         'k', v_k, 'layer', p_layer, 'started', now(),
         'out', jsonb_build_object('shots', 0, 'hits', 0, 'dmg', 0),
         'inc', jsonb_build_object('shots', 0, 'hits', 0, 'dmg', 0),
         'us', '[]'::jsonb, 'lost', '[]'::jsonb) end;

  v_side := m -> p_dir;
  v_side := v_side || jsonb_build_object(
    'shots', coalesce((v_side ->> 'shots')::integer, 0) + 1,
    'hits',  coalesce((v_side ->> 'hits')::integer, 0) + case when p_hit then 1 else 0 end,
    'dmg',   coalesce((v_side ->> 'dmg')::integer, 0) + case when p_hit then coalesce(p_dmg, 0) else 0 end);
  m := m || jsonb_build_object(p_dir, v_side);

  v_us := coalesce((select jsonb_agg(x) from jsonb_array_elements(m -> 'us') x
                    where x ->> 'id' <> p_me ->> 'id'), '[]'::jsonb);
  v_us := jsonb_build_array(p_me - 'owner' - 'faction' - 'system' - 'player') || v_us;
  if jsonb_array_length(v_us) > 6 then
    v_us := (select jsonb_agg(q.x order by q.o) from
              (select e.x, e.o from jsonb_array_elements(v_us) with ordinality e(x, o) order by e.o limit 6) q);
  end if;

  v_result := null;
  v_lost := coalesce(m -> 'lost', '[]'::jsonb);
  if p_killed and p_dir = 'out' then
    v_result := 'won';
  elsif p_killed and p_dir = 'inc' then
    v_lost := v_lost || jsonb_build_array(p_me ->> 'name');
  end if;

  m := m || jsonb_build_object(
    'en', p_en - 'owner' - 'faction' - 'system',
    'us', v_us, 'lost', v_lost,
    'x', p_en -> 'x', 'y', p_en -> 'y',
    'unit_id', case when p_layer = 'ground' then p_me ->> 'id' end,
    'ship_id', case when p_layer = 'space' then p_me ->> 'id' end,
    'layer', p_layer);
  if v_result is not null then m := m || jsonb_build_object('result', v_result); end if;

  if g.id is not null then
    update game_events
    set meta = m, amount = coalesce(amount, 0) + 1, subject = p_en ->> 'name',
        system_id = p_me ->> 'system', created_at = now(), seen_at = null
    where id = g.id;
  else
    insert into game_events (user_id, faction, system_id, type, subject, amount, visibility, meta)
    values (p_user, p_me ->> 'faction', p_me ->> 'system', 'duel', p_en ->> 'name', 1, 'private', m);
  end if;
end;
$$;


--
-- Name: effect_sum(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.effect_sum(p_system text, p_kind text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(case when p_kind = 'mood' then -30 else -50 end, least(case when p_kind = 'mood' then 30 else 50 end,
         coalesce((select sum(value) from active_effects where system_id = p_system and kind = p_kind and starts_at <= now() and ends_at > now()), 0)
       + coalesce((select sum(fe.value) from faction_effects fe join systems s on s.faction = fe.faction
                   where s.id = p_system and fe.kind = p_kind and fe.starts_at <= now() and fe.ends_at > now()
                     and (fe.system_id is null or fe.system_id = p_system)), 0)))::integer;
$$;


--
-- Name: err_db(text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.err_db(p_fn text, p_state text, p_msg text, p_all boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_state in ('40P01', '40001', '55P03') then return; end if;
  if not coalesce(p_all, true) and p_state = 'P0001' then return; end if;
  perform err_log('db', p_fn, p_msg, p_state, null);
end;
$$;


--
-- Name: err_log(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.err_log(p_source text, p_ctx text, p_msg text, p_state text DEFAULT NULL::text, p_data jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_msg text; v_ctx text; v_sig text;
begin
  v_msg := left(coalesce(nullif(btrim(p_msg), ''), '(без текста)'), 1000);
  v_ctx := left(p_ctx, 120);
  -- в подпись — текст без id, чисел и значений в кавычках: одна ошибка с разными данными — одна строка
  v_sig := md5(coalesce(p_source, '') || '|' || coalesce(v_ctx, '') || '|' ||
               regexp_replace(regexp_replace(regexp_replace(v_msg,
                 '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '‹id›', 'gi'),
                 '"[^"]*"', '"…"', 'g'),
                 '[0-9]+', '#', 'g'));
  if not exists (select 1 from server_errors where sig = v_sig)
     and (select count(*) from server_errors) >= 3000 then return; end if;
  insert into server_errors as e (sig, source, ctx, msg, state, data)
  values (v_sig, left(p_source, 16), v_ctx, v_msg, left(p_state, 8), p_data)
  on conflict (sig) do update
     set n = least(e.n + 1, 2000000000), last_at = now(), msg = excluded.msg,
         state = coalesce(excluded.state, e.state), data = coalesce(excluded.data, e.data);
exception when others then
  null;   -- журнал молчит сам
end;
$$;


--
-- Name: err_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.err_scan() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s record; r record; v_max bigint; v_at timestamptz; v_n integer := 0; v_seen timestamptz; v_prev text;
begin
  if not pg_try_advisory_xact_lock(hashtext('err_scan')) then return 0; end if;
  select * into s from server_error_scan where id = 1 for update;

  -- pg_cron: задания, упавшие целиком
  select coalesce(max(runid), s.cron_runid) into v_max from cron.job_run_details where runid > s.cron_runid;
  for r in
    select j.jobname, d.return_message, d.start_time
      from cron.job_run_details d left join cron.job j on j.jobid = d.jobid
     where d.runid > s.cron_runid and d.runid <= v_max and d.status = 'failed'
     order by d.runid limit 500
  loop
    perform err_log('cron', coalesce(r.jobname, 'cron'), coalesce(r.return_message, 'задание упало'), null,
                    jsonb_build_object('at', r.start_time));
    v_n := v_n + 1;
  end loop;

  -- сервер боёв: ошибки из журнала и перезапуск без «остановки» (процесс упал)
  select coalesce(max(at), s.rt_at) into v_at from rt_server_log where at > s.rt_at;
  for r in
    select l.at, l.level, l.msg, l.data from rt_server_log l
     where l.at > s.rt_at and l.at <= v_at
       and (l.level = 'error' or l.msg like 'журнал: пропущено%' or l.msg = 'сервер запущен')
     order by l.at limit 2000
  loop
    if r.msg = 'сервер запущен' then
      select p.msg into v_prev from rt_server_log p where p.at < r.at and p.at > r.at - interval '2 hours'
       order by p.at desc limit 1;
      if v_prev is not null and v_prev not like 'остановка%'
         and not exists (select 1 from rt_server_log q where q.msg like 'остановка%' and q.at < r.at and q.at > r.at - interval '60 seconds') then
        perform err_log('rt', 'перезапуск', 'Сервер боёв перезапустился без остановки — процесс упал', null,
                        jsonb_build_object('at', r.at, 'before', v_prev));
        v_n := v_n + 1;
      end if;
      continue;
    end if;
    perform err_log('rt', r.msg, coalesce(r.data ->> 'err', r.data ->> 'error', r.msg), null, r.data);
    v_n := v_n + 1;
  end loop;

  -- сервер боёв молчит (сердцебиение — каждые 20 с): одна запись на каждое пропадание
  select max(seen_at) into v_seen from rt_servers where id = 'main';
  if v_seen is not null and v_seen < now() - interval '3 minutes' then
    if s.rt_down_at is null or s.rt_down_at < v_seen then
      perform err_log('rt', 'нет связи', 'Сервер боёв не на связи с базой больше 3 минут', null,
                      jsonb_build_object('seen_at', v_seen));
      update server_error_scan set rt_down_at = now() where id = 1;
      v_n := v_n + 1;
    end if;
  end if;

  update server_error_scan set cron_runid = v_max, rt_at = v_at where id = 1;
  return v_n;
end;
$$;


--
-- Name: ev_buildings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ev_buildings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_name text;
begin
  if tg_op = 'INSERT' then
    -- Раньше здесь писалось «Постройка готова» в момент закладки.
    -- Теперь — «Стройка началась»; о готовности сообщит notify_ready_buildings.
    if new.completes_at is not null and new.completes_at > now() then
      select name into v_name from building_types where id = new.building_type_id;
      perform log_event(new.owner_user_id, new.faction, new.system_id,
                        'building_started', coalesce(v_name, 'постройка'), 1, 'private',
                        jsonb_build_object('slot', new.slot_index, 'building_id', new.id,
                                           'until', new.completes_at));
    end if;
  else
    select name into v_name from building_types where id = old.building_type_id;
    perform log_event(old.owner_user_id, old.faction, old.system_id,
                      'building_demolished', coalesce(v_name, 'постройка'), 1, 'private',
                      jsonb_build_object('slot', old.slot_index));
  end if;
  return null;
end $$;


--
-- Name: ev_commander_move(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ev_commander_move() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_faction text;
begin
  -- Прыжки рейсов снабжения не засоряют ленту и сводку фракции
  if coalesce(current_setting('app.supply_quiet', true), '') = 'on' then return null; end if;
  if old.moving_to is not null and new.moving_to is null
     and exists (select 1 from supply_routes sr
                 where sr.commander_id = new.id and sr.status = 'active') then
    return null;
  end if;
  -- Промежуточная остановка дальнего маршрута — без записей в ленте
  if coalesce(cardinality(new.route), 0) > 0 then return null; end if;
  select faction into v_faction from profiles where id = new.user_id;

  if old.moving_to is null and new.moving_to is not null then
    perform log_event(new.user_id, v_faction, new.moving_to,
                      'fleet_departed', new.moving_from, 1, 'faction',
                      jsonb_build_object('commander', new.name, 'arrives_at', new.arrives_at));
  elsif old.moving_to is not null and new.moving_to is null then
    perform log_event(new.user_id, v_faction, new.current_system,
                      'fleet_arrived', null, 1, 'faction',
                      jsonb_build_object('commander', new.name));
  end if;
  return null;
end $$;


--
-- Name: ev_ships(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ev_ships() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    perform log_event(new.owner_user_id, new.faction, new.system_id,
                      'ship_built', new.ship_type, 1, 'private', jsonb_build_object('ship_id', new.id, 'x', new.x, 'y', new.y, 'layer', 'space'));
  elsif coalesce(current_setting('app.duel_kill', true), '') = old.id::text then
    null;  -- сбит в схватке: в ленте хозяина уже есть сводка
  else
    -- Пока это просто «корабля больше нет». Когда появится бой, боевая
    -- функция допишет отдельное событие с тем, кто именно его сбил.
    perform log_event(old.owner_user_id, old.faction, old.system_id,
                      'ship_lost', old.ship_type, 1, 'private',
                      jsonb_build_object('hp', old.hp, 'x', old.x, 'y', old.y, 'layer', 'space'));
  end if;
  return null;
end $$;


--
-- Name: ev_stations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ev_stations() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.completes_at is not null and new.completes_at > now() then
      perform log_event(new.owner_user_id, new.faction, new.system_id, 'station_started',
                        coalesce(new.name, 'Орбитальная станция'), 1, 'private',
                        jsonb_build_object('layer', 'space', 'until', new.completes_at));
    end if;
  else
    perform log_event(old.owner_user_id, old.faction, old.system_id, 'station_demolished',
                      coalesce(old.name, 'Орбитальная станция'), 1, 'private',
                      jsonb_build_object('layer', 'space'));
  end if;
  return null;
end $$;


--
-- Name: ev_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ev_units() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.carrier_ship_id is not null then return null; end if;
    perform log_event(new.owner_user_id, new.faction, new.system_id,
                      'unit_deployed', new.unit_type, 1, 'private', jsonb_build_object('unit_id', new.id, 'x', new.x, 'y', new.y));
  else
    -- Удаление юнита — это и гибель, и погрузка обратно в трюм.
    -- Различаем по прочности: у погруженного она осталась.
    if old.hp > 0 and old.carrier_ship_id is null then
      perform log_event(old.owner_user_id, old.faction, old.system_id,
                        'unit_loaded', old.unit_type, 1, 'private', jsonb_build_object('x', old.x, 'y', old.y));
    elsif coalesce(current_setting('app.duel_kill', true), '') = old.id::text then
      null;  -- погиб в схватке: строка уже в сводке
    elsif not exists (
      select 1 from game_events g
      where g.user_id = old.owner_user_id and g.type = 'unit_killed'
        and g.created_at = now() and g.system_id is not distinct from old.system_id
        and g.subject in (old.unit_type, (select t.name from unit_types t where t.id = old.unit_type))
    ) then
      perform log_event(old.owner_user_id, old.faction, old.system_id,
                        'unit_killed', old.unit_type, 1, 'private', jsonb_build_object('x', old.x, 'y', old.y));
    end if;
  end if;
  return null;
end $$;


--
-- Name: evacuate_zones_after_capture(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evacuate_zones_after_capture(p_system_id text, p_new_faction text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  sh record; u record;
  v_side text; v_band text; v_dest text;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
  v_ah integer := game_setting_int('ground_attack_zone_height', 4);
  cy integer; cx integer; v_moved boolean;
begin
  -- ===== Космос =====
  for sh in
    select s.id, s.faction, s.y, s.owner_user_id,
           ship_box_h(t.width_cells, t.height_cells, s.facing) as bh,
           t.name
    from ships s join ship_types t on t.id = s.ship_type
    where s.system_id = p_system_id and not s.in_transit
  loop
    v_band := hyperspace_band_at(sh.y, sh.bh);
    continue when v_band is null;

    v_side := hyperspace_side(p_system_id, sh.faction);
    continue when v_band = v_side;      -- уже на своей стороне

    if sh.faction = p_new_faction then
      -- Победитель: выталкиваем вперёд, планета теперь его
      perform push_ship_out_of_band(sh.id);
      perform log_event(sh.owner_user_id, sh.faction, p_system_id,
                        'fleet_pushed_out', sh.name, 1, 'private', null);
    else
      -- Проигравший: уводим на ближайшую свою планету по гиперлиниям
      v_dest := nearest_friendly_system(p_system_id, sh.faction);

      if v_dest is not null and place_ship_in_hyperspace(sh.id, v_dest) then
        perform log_event(sh.owner_user_id, sh.faction, v_dest,
                          'fleet_evacuated', sh.name, 1, 'private',
                          jsonb_build_object('from', p_system_id));
      else
        -- Некуда отступать — остаёмся, но хотя бы не в чужой зоне
        perform push_ship_out_of_band(sh.id);
        perform log_event(sh.owner_user_id, sh.faction, p_system_id,
                          'fleet_stranded', sh.name, 1, 'private', null);
      end if;
    end if;
  end loop;

  -- ===== Земля =====
  -- Полоса вторжения теперь принадлежит бывшему хозяину: он стал
  -- нападающим. Войска победителя выводим из неё вперёд, на поле.
  for u in
    select up.id, up.x, up.y, up.owner_user_id, t.width_cells, t.height_cells, t.name
    from unit_positions up join unit_types t on t.id = up.unit_type
    where up.system_id = p_system_id and up.layer = 'ground'
      and up.x is not null and up.faction = p_new_faction
      and is_in_ground_attack_zone(up.y)
  loop
    v_moved := false;
    cy := v_grid - v_ah - u.height_cells;

    while cy >= 0 and not v_moved loop
      for cx in greatest(0, u.x - 10)..least(v_grid - u.width_cells, u.x + 10) loop
        if is_ground_box_free(p_system_id, cx, cy, u.width_cells, u.height_cells, u.id) then
          update unit_positions set x = cx, y = cy where id = u.id;
          v_moved := true;
          exit;
        end if;
      end loop;
      cy := cy - u.height_cells;
    end loop;

    if v_moved then
      perform log_event(u.owner_user_id, p_new_faction, p_system_id,
                        'troops_pushed_out', u.name, 1, 'private', null);
    end if;
  end loop;
end;
$$;


--
-- Name: event_bots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_bots() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); q event_queue; e record; v_call uuid; v_sel bigint[] := '{}'; v_ids bigint[]; r jsonb;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select * into q from event_queue where user_id = v_me and state = 'waiting' order by id desc limit 1;
  if not found then raise exception 'Сначала запишись на ивент'; end if;
  if q.call_id is not null then raise exception 'Сбор уже идёт'; end if;
  if (select kind from event_catalog where id = q.event_id) = 'pve' then raise exception 'Против бота сбор начнётся сам — соперник не нужен'; end if;
  if not pg_try_advisory_xact_lock(hashtext('event_match:' || q.event_id || ':' || q.tier)) then raise exception 'Подбор занят — попробуй через секунду'; end if;
  if exists (select 1 from event_queue x where x.event_id = q.event_id and x.tier = q.tier and x.state = 'waiting' and x.side <> q.side) then
    raise exception 'Соперник уже записался — ждём сбора';
  end if;
  if now() - q.joined_at < make_interval(secs => event_setting_int('event_bots_after_seconds', 180)) then raise exception 'Ботов можно позвать после 3 минут ожидания'; end if;
  select * into e from event_catalog where id = q.event_id;
  for r in select * from jsonb_array_elements(e.roles) loop
    select coalesce(array_agg(x.id), '{}') into v_ids
      from (select x.id from event_queue x where x.event_id = q.event_id and x.tier = q.tier and x.role = r->>'id' and x.state = 'waiting' and x.side = q.side
            order by x.joined_at limit (r->>'max')::integer) x;
    v_sel := v_sel || v_ids;
  end loop;
  v_call := gen_random_uuid();
  update event_queue set call_id = v_call, call_mode = 'bots', called_at = now(), ready_at = case when id = q.id then now() end where id = any(v_sel);
  perform event_call_start(v_call) where (select bool_and(ready_at is not null) from event_queue where call_id = v_call and state = 'waiting');
  return event_status();
end;
$$;


--
-- Name: event_call_start(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_call_start(p_call uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q event_queue; e record; r jsonb; v_players jsonb := '[]'::jsonb; v_id uuid; v_map text; n integer; i integer; v_bots boolean;
begin
  select * into q from event_queue where call_id = p_call and state = 'waiting' limit 1;
  if not found then return null; end if;
  select * into e from event_catalog where id = q.event_id;
  v_bots := q.call_mode = 'bots';
  for r in select * from jsonb_array_elements(e.roles) loop
    select count(*) into n from event_queue where call_id = p_call and state = 'waiting' and role = r->>'id';
    v_players := v_players || coalesce((select jsonb_agg(jsonb_build_object('user', x.user_id, 'role', x.role, 'side', x.side, 'nick', x.nick) order by x.joined_at)
                                          from event_queue x where x.call_id = p_call and x.state = 'waiting' and x.role = r->>'id'), '[]'::jsonb);
    if v_bots and n < (r->>'min')::integer then
      for i in 1..(case when n > 0 then (r->>'min')::integer - n when (r->>'max')::integer = 1 then 1
                        else greatest((r->>'min')::integer, least((r->>'max')::integer, 2)) end) loop
        v_players := v_players || jsonb_build_array(jsonb_build_object('user', 'bot:' || (r->>'id') || ':' || i, 'role', r->>'id', 'side', r->>'side', 'bot', true));
      end loop;
    end if;
  end loop;
  v_map := e.maps[1 + floor(random() * array_length(e.maps, 1))::integer];
  insert into event_matches (event_id, tier, map, players, day, bots, reward_k)
  values (q.event_id, q.tier, v_map, v_players, q.day, v_bots,
          case when v_bots then greatest(0, least(100, event_setting_int('event_bots_reward_pct', 50))) / 100.0 else 1 end)
  returning id into v_id;
  update event_queue set state = 'matched', match_id = v_id where call_id = p_call and state = 'waiting';
  return v_id;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: event_days; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_days (
    day date NOT NULL,
    event_id text NOT NULL,
    tier integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_days_tier_check CHECK (((tier >= 1) AND (tier <= 3)))
);


--
-- Name: event_day_row(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_day_row(p_day date) RETURNS public.event_days
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare d event_days; v_prev text; v_pick text; w integer[]; r numeric; v_tier integer;
begin
  select * into d from event_days where day = p_day;
  if found then return d; end if;
  perform pg_advisory_xact_lock(hashtext('event_day'));
  select * into d from event_days where day = p_day;
  if found then return d; end if;
  select event_id into v_prev from event_days where day < p_day order by day desc limit 1;
  select id into v_pick from event_catalog where ready and (pair is null or id < pair or not exists (select 1 from event_catalog p where p.id = event_catalog.pair and p.ready))
     and (v_prev is null or (id <> v_prev and pair is distinct from v_prev)
          or (select count(*) from event_catalog c where c.ready and (c.pair is null or c.id < c.pair or not exists (select 1 from event_catalog p where p.id = c.pair and p.ready))) = 1)
   order by random() limit 1;
  if v_pick is null then return null; end if;
  select array_agg(case when x ~ '^\d+$' then x::integer else 0 end) into w
    from unnest(string_to_array(coalesce((select value from game_settings where key = 'event_tier_weights'), '40,40,20'), ',')) x;
  if coalesce(array_length(w, 1), 0) < 3 or w[1] + w[2] + w[3] <= 0 then w := array[40, 40, 20]; end if;
  r := random() * (w[1] + w[2] + w[3]);
  v_tier := case when r < w[1] then 1 when r < w[1] + w[2] then 2 else 3 end;
  insert into event_days (day, event_id, tier) values (p_day, v_pick, v_tier) on conflict (day) do nothing;
  select * into d from event_days where day = p_day;
  return d;
end;
$_$;


--
-- Name: event_expire(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_expire() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n integer; tz text := event_tz(); v_day date := (now() at time zone event_tz())::date;
  v_close timestamptz := (((now() at time zone event_tz())::date) + make_interval(hours => event_setting_int('event_close_hour', 23))) at time zone event_tz();
begin
  update event_matches set status = 'aborted', ended_at = now(), result = coalesce(result, '{}'::jsonb) || jsonb_build_object('why', 'сервер боя не открыл матч')
   where status = 'forming' and created_at < now() - interval '3 minutes';
  get diagnostics n = row_count;
  update event_matches set status = 'aborted', ended_at = now(), result = coalesce(result, '{}'::jsonb) || jsonb_build_object('why', 'бой не завершён')
   where status = 'live' and (started_at < now() - interval '45 minutes' or coalesce(beat_at, started_at) < now() - interval '2 minutes');
  update event_queue set state = 'expired', left_at = now() where state = 'waiting' and joined_at < now() - interval '30 minutes' and call_id is null;
  update event_queue set state = 'expired', left_at = now()
   where state = 'waiting' and call_id is null and (coalesce(day, (joined_at at time zone tz)::date) < v_day or now() >= v_close);
  return n;
end;
$$;


--
-- Name: event_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_history(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(x order by x->>'at' desc), '[]'::jsonb) from (
    select jsonb_build_object('id', m.id, 'event', m.event_id, 'tier', m.tier, 'map', m.map, 'status', m.status, 'test', m.test,
                              'at', coalesce(m.ended_at, m.created_at), 'winner', m.winner, 'why', m.result->>'why', 't', (m.result->>'t')::integer,
                              'role', (select p->>'role' from jsonb_array_elements(m.players) p where p->>'user' = auth.uid()::text limit 1),
                              'award', (select to_jsonb(a) - 'match_id' - 'user_id' from event_awards a where a.match_id = m.id and a.user_id = auth.uid())) x
    from event_matches m
    where exists (select 1 from jsonb_array_elements(m.players) p where p->>'user' = auth.uid()::text)
    order by m.created_at desc limit greatest(1, least(50, p_limit))) s;
$$;


--
-- Name: event_join(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_join(p_event text, p_tier integer, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_side text; v_nick text; e record; r jsonb; v_today jsonb;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction, nickname into v_side, v_nick from profiles where id = v_me;
  if v_side is null then raise exception 'Сначала выбери сторону'; end if;
  v_today := event_today_for((select faction from profiles where id = v_me));
  if not coalesce((v_today->>'open')::boolean, false) then raise exception 'Ивенты открыты с 18:00 до 23:00 по времени сервера'; end if;
  if p_event is distinct from v_today->>'event' then raise exception 'Сегодня открыт другой ивент'; end if;
  select * into e from event_catalog where id = p_event;
  if not found or not e.ready then raise exception 'Этот ивент ещё не открыт'; end if;
  select x into r from jsonb_array_elements(e.roles) x where x->>'id' = p_role;
  if r is null then raise exception 'Нет такой роли'; end if;
  if r->>'side' <> v_side then raise exception 'Эта роль — за другую сторону'; end if;
  if (event_my_match(v_me)).id is not null then raise exception 'Ты уже в бою ивента'; end if;
  if exists (select 1 from event_queue where user_id = v_me and state = 'waiting' and call_id is not null) then raise exception 'Идёт сбор — подтверди или выйди'; end if;
  update event_queue set state = 'left', left_at = now() where user_id = v_me and state = 'waiting';
  insert into event_queue (user_id, event_id, tier, role, side, nick, day)
  values (v_me, p_event, (v_today->>'tier')::integer, p_role, v_side, v_nick, (v_today->>'day')::date);
  perform event_match_try(p_event, (v_today->>'tier')::integer);
  return event_status();
end;
$$;


--
-- Name: event_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_leave() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); q event_queue;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select * into q from event_queue where user_id = v_me and state = 'waiting' order by id desc limit 1;
  update event_queue set state = 'left', left_at = now() where user_id = v_me and state = 'waiting';
  if q.call_id is not null then
    update event_queue set call_id = null, call_mode = null, called_at = null, ready_at = null where call_id = q.call_id and state = 'waiting';
  end if;
  return event_status();
end;
$$;


--
-- Name: event_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_list() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_side text; v_today jsonb;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_side from profiles where id = v_me;
  v_today := event_today_for((select faction from profiles where id = v_me));
  return jsonb_build_object(
    'side', v_side,
    'today', v_today,
    'paid', event_paid_today(v_me, (v_today->>'day')::date),
    'bots_pct', event_setting_int('event_bots_reward_pct', 50),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'ready', c.ready, 'roles', c.roles, 'maps', c.maps) order by c.sort), '[]'::jsonb) from event_catalog c where v_side = any(c.sides)),
    'trophies', (select coalesce(jsonb_agg(jsonb_build_array(t.event_id, t.tier)), '[]'::jsonb) from event_trophies t where t.user_id = v_me),
    'titles', (select coalesce(jsonb_agg(t.title order by t.at), '[]'::jsonb) from event_titles t where t.user_id = v_me),
    'profile', (select to_jsonb(p) - 'user_id' from event_profile p where p.user_id = v_me),
    'waiting', (select coalesce(jsonb_object_agg(x.k, x.n), '{}'::jsonb) from (select event_id || ':' || tier || ':' || role k, count(*) n from event_queue where state = 'waiting' group by 1) x),
    'admin', exists (select 1 from dev_admins where user_id = v_me and revoked_at is null));
end;
$$;


--
-- Name: event_match_try(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_match_try(p_event text, p_tier integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  e record; r jsonb; ok boolean := true; full_ boolean := true; oldest timestamptz; n integer; v_call uuid; v_at timestamptz; v_all boolean;
  v_ids bigint[]; v_sel bigint[] := '{}';
begin
  if not pg_try_advisory_xact_lock(hashtext('event_match:' || p_event || ':' || p_tier)) then return null; end if;
  select * into e from event_catalog where id = p_event and ready;
  if not found then return null; end if;
  select call_id, min(called_at), bool_and(ready_at is not null) into v_call, v_at, v_all
    from event_queue where event_id = p_event and tier = p_tier and state = 'waiting' and call_id is not null group by call_id limit 1;
  if v_call is not null then
    if v_all then return event_call_start(v_call); end if;
    if v_at < now() - make_interval(secs => event_setting_int('event_call_seconds', 120)) then
      update event_queue set state = 'left', left_at = now() where call_id = v_call and state = 'waiting' and ready_at is null;
      update event_queue set call_id = null, call_mode = null, called_at = null, ready_at = null where call_id = v_call and state = 'waiting';
    else
      return null;
    end if;
  end if;
  for r in select * from jsonb_array_elements(e.roles) loop
    select count(*) into n from event_queue q where q.event_id = p_event and q.tier = p_tier and q.role = r->>'id' and q.state = 'waiting';
    if n < (r->>'min')::integer then ok := false; end if;
    if n < (r->>'max')::integer then full_ := false; end if;
  end loop;
  if not ok then return null; end if;
  select min(joined_at) into oldest from event_queue q where q.event_id = p_event and q.tier = p_tier and q.state = 'waiting';
  if not full_ and oldest > now() - interval '30 seconds' then return null; end if;
  for r in select * from jsonb_array_elements(e.roles) loop
    select coalesce(array_agg(x.id), '{}') into v_ids
      from (select q.id from event_queue q where q.event_id = p_event and q.tier = p_tier and q.role = r->>'id' and q.state = 'waiting'
            order by q.joined_at limit (r->>'max')::integer) x;
    v_sel := v_sel || v_ids;
  end loop;
  v_call := gen_random_uuid();
  update event_queue set call_id = v_call, call_mode = 'pvp', called_at = now(), ready_at = null where id = any(v_sel);
  return null;
end;
$$;


--
-- Name: event_matches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_matches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id text NOT NULL,
    tier integer NOT NULL,
    map text NOT NULL,
    status text DEFAULT 'forming'::text NOT NULL,
    players jsonb DEFAULT '[]'::jsonb NOT NULL,
    test boolean DEFAULT false NOT NULL,
    created_by uuid,
    seed integer DEFAULT (floor((random() * (1000000)::double precision)))::integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    result jsonb,
    winner text,
    beat_at timestamp with time zone,
    day date,
    reward_k numeric DEFAULT 1 NOT NULL,
    bots boolean DEFAULT false NOT NULL,
    CONSTRAINT event_matches_status_check CHECK ((status = ANY (ARRAY['forming'::text, 'live'::text, 'done'::text, 'aborted'::text])))
);


--
-- Name: event_my_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_my_match(p_user uuid) RETURNS public.event_matches
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select m.* from event_matches m
  where m.status in ('forming', 'live') and m.created_at > now() - interval '2 hours'
    and exists (select 1 from jsonb_array_elements(m.players) p where p->>'user' = p_user::text)
  order by m.created_at desc limit 1;
$$;


--
-- Name: event_paid_today(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_paid_today(p_user uuid, p_day date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'win', exists (select 1 from event_awards a where a.user_id = p_user and a.paid and a.won and (a.at at time zone event_tz())::date = p_day),
    'any', exists (select 1 from event_awards a where a.user_id = p_user and a.paid and (a.at at time zone event_tz())::date = p_day));
$$;


--
-- Name: event_rating(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_rating(p_side text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('nick', pr.nickname, 'side', pr.faction, 'points', e.points, 'wins', e.wins, 'games', e.games, 'title', e.title, 'me', e.user_id = auth.uid()) order by e.points desc, e.wins desc), '[]'::jsonb)
  from (select ep.* from event_profile ep join profiles p2 on p2.id = ep.user_id
        where ep.games > 0 and (p_side is null or p2.faction = p_side)
        order by ep.points desc, ep.wins desc limit 50) e
  join profiles pr on pr.id = e.user_id;
$$;


--
-- Name: event_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_ready() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); q event_queue;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select * into q from event_queue where user_id = v_me and state = 'waiting' and call_id is not null order by id desc limit 1;
  if not found then raise exception 'Сбора нет — он мог закончиться'; end if;
  update event_queue set ready_at = coalesce(ready_at, now()) where id = q.id;
  perform event_match_try(q.event_id, q.tier);
  return event_status();
end;
$$;


--
-- Name: event_setting_int(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_setting_int(p_key text, p_def integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select coalesce((select case when value ~ '^\d{1,6}$' then value::integer end from game_settings where key = p_key), p_def);
$_$;


--
-- Name: event_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); q event_queue; m event_matches; cnt jsonb; e record; v_call jsonb; v_today jsonb; v_bots_in integer; v_other integer; v_day date;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  perform event_expire();
  select * into q from event_queue where user_id = v_me and state = 'waiting' order by id desc limit 1;
  if found then
    perform event_match_try(q.event_id, q.tier);
    select * into q from event_queue where id = q.id;
  end if;
  m := event_my_match(v_me);
  v_today := event_today_for((select faction from profiles where id = v_me));
  v_day := (v_today->>'day')::date;
  if q.id is not null and q.state = 'waiting' then
    select coalesce(jsonb_object_agg(x.role, x.n), '{}'::jsonb) into cnt
      from (select role, count(*) n from event_queue where event_id = q.event_id and tier = q.tier and state = 'waiting' group by role) x;
    if q.call_id is not null then
      select jsonb_build_object('mode', q.call_mode, 'at', min(x.called_at),
               'deadline', min(x.called_at) + make_interval(secs => event_setting_int('event_call_seconds', 120)),
               'total', count(*), 'ready', count(x.ready_at), 'me_ready', q.ready_at is not null,
               'who', jsonb_agg(jsonb_build_object('nick', x.nick, 'role', x.role, 'ready', x.ready_at is not null) order by x.joined_at))
        into v_call from event_queue x where x.call_id = q.call_id and x.state = 'waiting';
    else
      select * into e from event_catalog where id = q.event_id;
      select count(*) into v_other from event_queue x where x.event_id = q.event_id and x.tier = q.tier and x.state = 'waiting' and x.side <> q.side;
      v_bots_in := case when e.kind = 'pvp' then greatest(0, event_setting_int('event_bots_after_seconds', 180) - extract(epoch from now() - q.joined_at)::integer) end;
    end if;
  end if;
  return jsonb_build_object(
    'queue', case when q.id is not null and q.state = 'waiting' then jsonb_build_object('event', q.event_id, 'tier', q.tier, 'role', q.role, 'since', q.joined_at,
              'wait', extract(epoch from now() - q.joined_at)::integer, 'counts', cnt, 'call', v_call,
              'bots_in', case when q.call_id is null and coalesce(v_other, 0) = 0 then v_bots_in end) end,
    'match', case when m.id is not null then jsonb_build_object('id', m.id, 'event', m.event_id, 'tier', m.tier, 'map', m.map, 'status', m.status, 'players', m.players, 'test', m.test, 'bots', m.bots) end,
    'today', v_today,
    'paid', event_paid_today(v_me, v_day),
    'bots_pct', event_setting_int('event_bots_reward_pct', 50),
    'server', rt_server_status());
end;
$$;


--
-- Name: event_title_set(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_title_set(p_title text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid();
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  if p_title is not null and not exists (select 1 from event_titles where user_id = v_me and title = p_title) then raise exception 'Этот титул ещё не получен'; end if;
  insert into event_profile (user_id, title) values (v_me, p_title) on conflict (user_id) do update set title = excluded.title;
  return jsonb_build_object('ok', true, 'title', p_title);
end;
$$;


--
-- Name: event_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_today() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  tz text := event_tz(); v_now timestamptz := now(); v_day date; v_open timestamptz; v_close timestamptz; v_next timestamptz; d event_days; v_is boolean;
begin
  v_day := (v_now at time zone tz)::date;
  v_open := (v_day + make_interval(hours => event_setting_int('event_open_hour', 18))) at time zone tz;
  v_close := (v_day + make_interval(hours => event_setting_int('event_close_hour', 23))) at time zone tz;
  v_is := v_now >= v_open and v_now < v_close;
  v_next := case when v_now < v_open then v_open else ((v_day + 1) + make_interval(hours => event_setting_int('event_open_hour', 18))) at time zone tz end;
  if v_is then d := event_day_row(v_day); end if;
  return jsonb_build_object('day', v_day, 'open', v_is and d.event_id is not null, 'event', d.event_id, 'tier', d.tier,
                            'opens_at', v_open, 'closes_at', v_close, 'next_at', v_next, 'now', v_now, 'tz', tz);
end;
$$;


--
-- Name: event_today_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_today_for(p_side text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare t jsonb := event_today(); e record;
begin
  if t->>'event' is null or p_side is null then return t; end if;
  select id, sides, pair into e from event_catalog where id = t->>'event';
  if e.id is not null and not (p_side = any(e.sides)) and e.pair is not null
     and exists (select 1 from event_catalog p where p.id = e.pair and p.ready and p_side = any(p.sides)) then
    t := t || jsonb_build_object('event', e.pair, 'pair_of', e.id);
  end if;
  return t;
end;
$$;


