--
-- Name: faction_power(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faction_power(p_user uuid, p_faction text, p_power text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_user is not null and p_faction is not null
    -- чужой штаб не выяснить: спрашивают о себе или о своей стороне (cron и сервер — без входа)
    and (auth.uid() is null or p_user = auth.uid()
         or p_faction = (select pr0.faction from profiles pr0 where pr0.id = auth.uid()))
    and (
    is_faction_leader(p_user, p_faction)
    or exists (select 1 from faction_role_members m
               join faction_roles r on r.id = m.role_id
               join profiles pr on pr.id = m.user_id
               where m.user_id = p_user and r.faction = p_faction and not r.archived
                 and pr.faction = p_faction and p_power = any(r.powers)));
$$;


