$$;


--
-- Name: find_deploy_box(text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_deploy_box(p_system_id text, p_w integer, p_h integer, p_from_x integer DEFAULT 0, p_from_y integer DEFAULT 0) RETURNS TABLE(x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with spots as (
    select z.x + dx as x, z.y + dy as y
    from deploy_zones z,
         generate_series(0, z.size - p_h) dy,
         generate_series(0, z.size - p_w) dx
    where z.system_id = p_system_id
      and z.size >= greatest(p_w, p_h)
  )
  select s.x, s.y from spots s
  where is_ground_box_free(p_system_id, s.x, s.y, p_w, p_h, null)
  order by greatest(abs(s.x - p_from_x), abs(s.y - p_from_y)), s.y, s.x;
$$;


--
-- Name: find_spawn_box_near(text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_spawn_box_near(p_system_id text, p_building uuid, p_w integer, p_h integer) RETURNS TABLE(x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with slot as (
    select ps.x, ps.y, 6 as size
      from buildings b join planet_slots ps on ps.system_id = b.system_id and ps.slot_index = b.slot_index
     where b.id = p_building and b.system_id = p_system_id
  ),
  ring as (
    select s.x + dx as x, s.y + dy as y, greatest(abs(dx + (p_w - 1) / 2.0 - s.size / 2.0), abs(dy + (p_h - 1) / 2.0 - s.size / 2.0)) as d
      from slot s, generate_series(-8, s.size + 7) dx, generate_series(-8, s.size + 7) dy
     where (dx + p_w <= 0 or dx >= s.size or dy + p_h <= 0 or dy >= s.size)     -- не на самом участке
  )
  select r.x, r.y from ring r
   where r.x >= 0 and r.y >= 0 and r.x + p_w <= game_setting_int('ground_grid_cells', 144) and r.y + p_h <= game_setting_int('ground_grid_cells', 144)
     and not is_in_ground_attack_zone(r.y + p_h - 1)
     and not exists (select 1 from settlement_zone_box() z where r.x < z.x + z.size and r.x + p_w > z.x and r.y < z.y + z.size and r.y + p_h > z.y)
     and is_ground_box_free(p_system_id, r.x, r.y, p_w, p_h, null)
   order by r.d, r.y, r.x;
$$;


--
-- Name: finish_commander_move(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_commander_move(p_commander_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_from text;
  v_to text;
  sh record;
begin
  select moving_from, moving_to into v_from, v_to
  from commanders
  where id = p_commander_id and moving_to is not null and arrives_at <= now()
  for update;

  if v_to is null then
    return;
  end if;

  update commanders
  set current_system = moving_to,
      moving_from = null,
      moving_to = null,
      departed_at = null,
      arrives_at = null
  where id = p_commander_id and moving_to is not null;

  for sh in
    select id from ships
    where commander_id = p_commander_id and system_id = v_from
      and in_transit and carrier_ship_id is null
    order by id
  loop
    perform place_ship_in_hyperspace(sh.id, v_to);
  end loop;

  -- Дальний маршрут: следующий прыжок без участия игрока
  perform commander_route_continue(p_commander_id);
end;
$$;


--
-- Name: finish_due_commander_moves(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_due_commander_moves() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c record; sh record;
begin
  for c in
    select id from commanders
    where moving_to is not null and arrives_at <= now()
  loop
    begin
      perform finish_commander_move(c.id);
    exception when others then
      perform err_db('finish_due_commander_moves', sqlstate, sqlerrm, true);
    end;
  end loop;

  for sh in
    select s.id, cm.current_system
    from ships s
    join commanders cm on cm.id = s.commander_id
    where s.in_transit and s.carrier_ship_id is null
      and cm.moving_to is null and cm.current_system is not null
    for update of s skip locked
  loop
    begin
      perform place_ship_in_hyperspace(sh.id, sh.current_system);
    exception when others then
      perform err_db('finish_due_commander_moves.place', sqlstate, sqlerrm, true);
    end;
  end loop;
end;
$$;


--
-- Name: finish_scout_moves(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_scout_moves() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; ut record; spot record; v_sys_faction text;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
  v_ah integer := game_setting_int('ground_attack_zone_height', 4);
  cx integer; cy integer; tries integer;
begin
  for r in
    select * from unit_positions
    where transit_to is not null and transit_arrives <= now()
    for update skip locked
  loop
    -- Один сбойный разведчик не должен останавливать доставку остальных
    begin
      -- Старый полёт в точку пустоты: разворачиваем домой
      if exists (select 1 from systems where id = r.transit_to and is_deep_space) then
        update unit_positions set transit_to = r.system_id, transit_arrives = now()
        where id = r.id;
        continue;
      end if;

      select * into ut from unit_types where id = r.unit_type;
      select faction into v_sys_faction from systems where id = r.transit_to;

      if v_sys_faction is not distinct from r.faction then
        select * into spot
        from find_deploy_box(r.transit_to, ut.width_cells, ut.height_cells, 0, 0)
        limit 1;

        if found then
          update unit_positions
          set system_id = r.transit_to, x = spot.x, y = spot.y,
              transit_to = null, transit_arrives = null
          where id = r.id;
        end if;
      else
        tries := 0;
        loop
          tries := tries + 1;
          exit when tries > 80;

          cx := floor(random() * (v_grid - ut.width_cells))::integer;
          cy := v_grid - v_ah + floor(random() * (v_ah - ut.height_cells + 1))::integer;

          if is_ground_box_free(r.transit_to, cx, cy, ut.width_cells, ut.height_cells, r.id) then
            update unit_positions
            set system_id = r.transit_to, x = cx, y = cy,
                transit_to = null, transit_arrives = null
            where id = r.id;
            exit;
          end if;
        end loop;
      end if;

      if (select x from unit_positions where id = r.id) is not null then
        perform log_event(r.owner_user_id, r.faction, r.transit_to,
                          'scout_arrived', ut.name, 1, 'private', (select jsonb_build_object('unit_id', p.id, 'x', p.x, 'y', p.y) from unit_positions p where p.id = r.id));
      end if;
    exception when others then perform err_db('finish_scout_moves', sqlstate, sqlerrm, true);
      raise warning 'finish_scout_moves: разведчик % не сел: %', r.id, sqlerrm;
    end;
  end loop;
end;
$$;


--
-- Name: forbid_buildings_in_deep_space(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_buildings_in_deep_space() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (select 1 from systems
             where id = new.system_id and is_deep_space) then
    raise exception 'В открытом космосе строить негде';
  end if;
  return new;
end;
$$;


--
-- Name: forbid_owner_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_owner_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.owner_user_id is distinct from old.owner_user_id then
    if coalesce(current_setting('app.owner_transfer', true), '') = '1' then
      return new;
    end if;

    raise exception 'Владельца менять нельзя';
  end if;

  return new;
end;
$$;


--
-- Name: forbid_units_in_deep_space(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_units_in_deep_space() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.carrier_ship_id is null and new.carrier_unit_id is null
     and exists (select 1 from systems where id = new.system_id and is_deep_space) then
    raise exception 'В открытом космосе нет поверхности — высаживать некуда';
  end if;
  return new;
end;
$$;


--
-- Name: free_deploy_cells(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.free_deploy_cells(p_system_id text, p_from_x integer, p_from_y integer) RETURNS TABLE(x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with cells as (
    select z.x + dx as x, z.y + dy as y
    from deploy_zones z,
         generate_series(0, z.size - 1) dx,
         generate_series(0, z.size - 1) dy
    where z.system_id = p_system_id
      and is_my_faction_system(p_system_id)
  )
  select c.x, c.y from cells c
  where not exists (
    select 1 from unit_positions u
    join unit_types t on t.id = u.unit_type
    where u.system_id = p_system_id and u.layer = 'ground'
      and u.x is not null
      and c.x < u.x + t.width_cells and c.x + 1 > u.x
      and c.y < u.y + t.height_cells and c.y + 1 > u.y
  )
  order by
    greatest(abs(c.x - p_from_x), abs(c.y - p_from_y)),
    c.y, c.x;
$$;


--
-- Name: free_deploy_cells_internal(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.free_deploy_cells_internal(p_system_id text, p_from_x integer, p_from_y integer) RETURNS TABLE(x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with cells as (
    select z.x + dx as x, z.y + dy as y
    from deploy_zones z,
         generate_series(0, z.size - 1) dx,
         generate_series(0, z.size - 1) dy
    where z.system_id = p_system_id
  )
  select c.x, c.y from cells c
  where not exists (
    select 1 from unit_positions u
    join unit_types t on t.id = u.unit_type
    where u.system_id = p_system_id and u.layer = 'ground'
      and u.x is not null
      and c.x < u.x + t.width_cells and c.x + 1 > u.x
      and c.y < u.y + t.height_cells and c.y + 1 > u.y
  )
  order by
    greatest(abs(c.x - p_from_x), abs(c.y - p_from_y)),
    c.y, c.x;
$$;


--
-- Name: galaxy_event_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.galaxy_event_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_next timestamptz; v_id uuid; v_lo integer := event_setting_int('galaxy_event_gap_min', 18); v_hi integer := event_setting_int('galaxy_event_gap_max', 36);
begin
  if not pg_try_advisory_xact_lock(hashtext('galaxy_event_tick')) then return 0; end if;
  update galaxy_events set status = 'ended' where status = 'active' and ends_at <= now();
  select next_at into v_next from galaxy_event_state where k = 1 for update;
  if v_next is null then insert into galaxy_event_state (k, next_at) values (1, now()) on conflict (k) do nothing; v_next := now(); end if;
  if v_next > now() then return 0; end if;
  if (select count(*) from galaxy_events where status = 'active' and ends_at > now() and not dev) >= event_setting_int('galaxy_event_max', 2) then return 0; end if;
  v_id := ge_start(null, false);
  update galaxy_event_state set next_at = now() + make_interval(mins => (v_lo * 60 + floor(random() * greatest(1, (v_hi - v_lo) * 60)))::integer)
   where k = 1;
  return case when v_id is null then 0 else 1 end;
end;
$$;


--
-- Name: galaxy_events_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.galaxy_events_state() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  return jsonb_build_object(
    'now', now(), 'faction', v_fac,
    'active', (select coalesce(jsonb_agg(x order by x->>'ends'), '[]'::jsonb) from (
       select jsonb_build_object('id', g.id, 'type', t.id, 'title', ge_fill(t.title, c.name, g.faction), 'text', ge_fill(t.text, c.name, g.faction),
                'glyph', t.glyph, 'tone', t.tone, 'scope', g.scope, 'faction', g.faction, 'center', g.center, 'center_name', c.name,
                'effects', t.effects, 'actions', t.actions, 'result', g.result, 'started', g.started_at, 'ends', g.ends_at,
                'planets', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'faction', s.faction,
                               'mine', exists (select 1 from system_control sc where sc.system_id = s.id and sc.controller_user_id = v_me))
                             order by (s.id = g.center) desc, s.name), '[]'::jsonb)
                            from systems s where s.id = any(g.systems))) x
       from galaxy_events g join galaxy_event_types t on t.id = g.type_id left join systems c on c.id = g.center
       where g.status = 'active' and g.ends_at > now()) q),
    'recent', (select coalesce(jsonb_agg(x order by x->>'ended' desc), '[]'::jsonb) from (
       select jsonb_build_object('title', ge_fill(t.title, c.name, g.faction), 'glyph', t.glyph, 'tone', t.tone, 'scope', g.scope,
                'center_name', c.name, 'faction', g.faction, 'ended', g.ends_at) x
       from galaxy_events g join galaxy_event_types t on t.id = g.type_id left join systems c on c.id = g.center
       where g.ends_at <= now() and g.ends_at > now() - interval '5 days'
       order by g.ends_at desc limit 6) q),
    'next_hint', (select next_at > now() from galaxy_event_state where k = 1));
end;
$$;


--
-- Name: game_setting_int(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.game_setting_int(p_key text, p_default integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select coalesce((select value::integer from game_settings where key = p_key), p_default);
$$;


--
-- Name: ge_fill(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ge_fill(p_text text, p_planet text, p_faction text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select replace(replace(replace(replace(p_text,
    '{planet}', coalesce(p_planet, 'планеты')),
    '{faction}', case p_faction when 'republic' then 'Республика' when 'cis' then 'Конфедерация' else 'Фракция' end),
    '{faction_gen}', case p_faction when 'republic' then 'Республики' when 'cis' then 'Конфедерации' else 'фракции' end),
    '{house}', case p_faction when 'republic' then 'Сенате' when 'cis' then 'Совете' else 'правительстве' end);
$$;


--
-- Name: ge_neighbors(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ge_neighbors(p_system text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct n), '{}') from (
    select case when system_a = p_system then system_b else system_a end n
    from hyperlanes where system_a = p_system or system_b = p_system) q
  where n in (select id from systems where faction in ('republic', 'cis') and not coalesce(is_deep_space, false));
$$;


--
-- Name: ge_start(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ge_start(p_type text DEFAULT NULL::text, p_dev boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t galaxy_event_types; v_busy text[]; v_center text; v_fac text; v_sys text[]; v_id uuid; s text; e jsonb; k text; v_ctrl uuid;
  v_res jsonb := '{}'::jsonb; v_raided integer := 0; v_gifts integer := 0; v_n integer; v_title text; v_name text;
begin
  select coalesce(array_agg(distinct x), '{}') into v_busy from galaxy_events g, unnest(g.systems) x
   where g.status = 'active' and g.ends_at > now() and g.scope in ('sector', 'planet', 'front');
  if p_type is not null then
    select * into t from galaxy_event_types where id = p_type and active;
    if not found then raise exception 'Нет такого события'; end if;
  else
    select * into t from galaxy_event_types et
    where et.active
      and et.id not in (select type_id from galaxy_events order by started_at desc limit 3)
      and not exists (select 1 from galaxy_events g where g.type_id = et.id and g.status = 'active' and g.ends_at > now())
      and not (et.scope = 'galaxy' and exists (select 1 from galaxy_events g join galaxy_event_types gt on gt.id = g.type_id
                                               where g.status = 'active' and g.ends_at > now() and gt.scope = 'galaxy'))
    order by -ln(random()) / greatest(et.weight, 1) limit 1;
    if not found then return null; end if;
  end if;

  if t.scope = 'galaxy' then
    select coalesce(array_agg(id), '{}') into v_sys from systems where faction in ('republic', 'cis') and not coalesce(is_deep_space, false);
  elsif t.scope = 'faction' then
    v_fac := coalesce(t.faction, case when random() < 0.5 then 'republic' else 'cis' end);
    select coalesce(array_agg(id), '{}') into v_sys from systems where faction = v_fac and not coalesce(is_deep_space, false);
  else
    select s0.id into v_center from systems s0 left join system_control sc on sc.system_id = s0.id
    where s0.faction in ('republic', 'cis') and not coalesce(s0.is_deep_space, false) and not (s0.id = any(v_busy))
      and (t.scope <> 'front' or exists (select 1 from unnest(ge_neighbors(s0.id)) nb join systems s1 on s1.id = nb where s1.faction <> s0.faction))
    order by -ln(random()) / case when sc.controller_user_id is not null then 3 else 1 end limit 1;
    if v_center is null then return null; end if;
    if t.scope = 'sector' then
      select array_agg(x) into v_sys from (select v_center x union select nb from unnest(ge_neighbors(v_center)) nb where not (nb = any(v_busy))) q;
    else
      v_sys := array[v_center];
    end if;
  end if;
  if coalesce(array_length(v_sys, 1), 0) = 0 then return null; end if;

  select name into v_name from systems where id = v_center;
  v_title := ge_fill(t.title, v_name, v_fac);
  insert into galaxy_events (type_id, scope, faction, center, systems, ends_at, dev)
  values (t.id, t.scope, v_fac, v_center, v_sys, now() + make_interval(hours => t.hours), p_dev)
  returning id into v_id;

  for e in select * from jsonb_array_elements(t.effects) loop
    if t.scope = 'galaxy' then
      insert into faction_effects (faction, kind, value, title, source, starts_at, ends_at)
      select f, e->>'kind', (e->>'value')::integer, v_title, 'event:' || v_id, now(), now() + make_interval(hours => t.hours)
      from unnest(array['republic', 'cis']) f;
    elsif t.scope = 'faction' then
      insert into faction_effects (faction, kind, value, title, source, starts_at, ends_at)
      values (v_fac, e->>'kind', (e->>'value')::integer, v_title, 'event:' || v_id, now(), now() + make_interval(hours => t.hours));
    else
      insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at)
      select x.faction, e->>'kind', (e->>'value')::integer, v_title, 'event:' || v_id, x.id, now(), now() + make_interval(hours => t.hours)
      from systems x where x.id = any(v_sys) and x.faction in ('republic', 'cis');
    end if;
  end loop;

  if t.scope not in ('galaxy', 'faction') then
    foreach s in array v_sys loop
      select controller_user_id into v_ctrl from system_control where system_id = s;
      if t.actions ? 'raid' and v_ctrl is not null then
        begin perform spawn_marauder_gang(s, (t.actions->>'raid')::integer); v_raided := v_raided + 1;
        exception when others then perform err_db('ge_start', sqlstate, sqlerrm, true); null; end;
      end if;
      if t.actions ? 'stock' then
        for k, v_n in select key, value::integer from jsonb_each_text(t.actions->'stock') loop
          begin perform add_planet_stock(s, k, v_n); exception when others then perform err_db('ge_start', sqlstate, sqlerrm, true); null; end;
        end loop;
      end if;
      if t.actions ? 'gift' and v_ctrl is not null then
        for v_n in 1..greatest(1, (t.actions->>'gift')::integer) loop
          begin if report_gift(s, v_ctrl, false) is not null then v_gifts := v_gifts + 1; end if;
          exception when others then perform err_db('ge_start', sqlstate, sqlerrm, true); null; end;
        end loop;
      end if;
      if t.actions ? 'credits' and v_ctrl is not null then
        update profiles set credits = credits + (t.actions ->> 'credits')::integer where id = v_ctrl;
        v_res := v_res || jsonb_build_object('paid', coalesce((v_res ->> 'paid')::integer, 0) + 1);
      end if;
      if t.actions ? 'unrest' and exists (select 1 from systems x where x.id = s and x.faction in ('republic', 'cis')) then
        begin
          insert into settlement_unrest (system_id, value) values (s, greatest(0, least(100, (t.actions ->> 'unrest')::integer)))
          on conflict (system_id) do update
            set value = greatest(0, least(100, settlement_unrest.value + (t.actions ->> 'unrest')::integer)), updated_at = now();
        exception when others then perform err_db('ge_start', sqlstate, sqlerrm, true); null; end;
      end if;
      if v_ctrl is not null then
        perform log_event(v_ctrl, (select faction from systems where id = s), s, 'galaxy_event', v_title, 1, 'private',
                          jsonb_build_object('event', v_id, 'type', t.id, 'tone', t.tone));
      end if;
    end loop;
    if v_raided > 0 then v_res := v_res || jsonb_build_object('raid', v_raided, 'gang', (t.actions->>'raid')::integer); end if;
    if t.actions ? 'stock' then v_res := v_res || jsonb_build_object('stock', t.actions->'stock'); end if;
    if v_gifts > 0 then v_res := v_res || jsonb_build_object('gift', v_gifts); end if;
    if v_res ? 'paid' then v_res := v_res || jsonb_build_object('credits', (t.actions ->> 'credits')::integer); end if;
    if t.actions ? 'unrest' then v_res := v_res || jsonb_build_object('unrest', (t.actions ->> 'unrest')::integer); end if;
    update galaxy_events set result = v_res where id = v_id;
  end if;

  perform log_event(null, coalesce(v_fac, (select faction from systems where id = v_center)), v_center, 'galaxy_event', v_title, 1, 'all',
                    jsonb_build_object('event', v_id, 'type', t.id, 'tone', t.tone, 'scope', t.scope));
  return v_id;
end;
$$;


--
-- Name: ge_trade_mod(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ge_trade_mod() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(-50, least(100, coalesce(sum((t.actions ->> 'trade')::integer), 0)))::integer  -- без событий — 0 (greatest/least пропускают null)
    from galaxy_events g join galaxy_event_types t on t.id = g.type_id
   where g.status = 'active' and g.ends_at > now() and t.actions ? 'trade' and g.scope = 'galaxy';
$$;


--
-- Name: ge_travel_mod(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ge_travel_mod(p_from text, p_to text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(-50, least(100, coalesce(sum((t.actions ->> 'travel')::integer), 0)))::integer  -- без событий — 0 (greatest/least пропускают null)
    from galaxy_events g join galaxy_event_types t on t.id = g.type_id
   where g.status = 'active' and g.ends_at > now() and t.actions ? 'travel'
     and (g.scope = 'galaxy' or g.systems && array[p_from, p_to]);
$$;


--
-- Name: get_building_queue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_building_queue(p_building_id uuid) RETURNS TABLE(unit_type text, unit_name text, quantity integer, completes_at timestamp with time zone, seconds_left integer, mine boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select * from (
    select uo.unit_type, coalesce(uo.hero_name, ut.name) as unit_name,
           uo.quantity, uo.completes_at,
           greatest(0, ceil(extract(epoch from uo.completes_at - now()))::integer) as seconds_left,
           uo.owner_user_id = auth.uid() as mine
    from unit_orders uo
    left join unit_types ut on ut.id = uo.unit_type
    where uo.building_id = p_building_id and not uo.delivered

    union all

    select u2.unit_type,
           'Ремонт: ' || coalesce(u2.hero_name, ut2.name, 'юнит') as unit_name,
           1, ro.completes_at,
           greatest(0, ceil(extract(epoch from ro.completes_at - now()))::integer),
           ro.owner_user_id = auth.uid()
    from repair_orders ro
    left join unit_positions u2 on u2.id = ro.unit_id
    left join unit_types ut2 on ut2.id = u2.unit_type
    where ro.building_id = p_building_id and not ro.delivered
  ) q
  -- очередь видна только своей стороне: чужую казарму в обход тумана войны не разглядеть
  where exists (select 1 from buildings bd join profiles pr on pr.id = auth.uid()
                where bd.id = p_building_id and bd.faction = pr.faction)
  order by q.completes_at
  limit 1;
$$;


--
-- Name: get_building_slots(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_building_slots(p_system_id text) RETURNS TABLE(slot_index integer, x integer, y integer, need_level integer, need_name text, unlocked boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select ps.slot_index, ps.x, ps.y, nl.lvl, sl.name,
         case when (select faction from systems where id = p_system_id)
                   = (select faction from profiles where id = auth.uid())
              then ps.slot_index <= building_slot_cap(p_system_id) end
  from planet_slots ps
  cross join lateral (select building_slot_need_level(ps.slot_index) as lvl) nl
  left join settlement_levels sl on sl.level = nl.lvl
  where ps.system_id = p_system_id
  order by ps.slot_index;
$$;


--
-- Name: get_building_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_building_status(p_building_id uuid) RETURNS TABLE(code text, name text, produces_resource text, produces_name text, produces_color text, per_day integer, consumes jsonb, storage_bonus integer, next_at timestamp with time zone, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare b record; bt record; s record; v_rate integer; v_status text; k text;
  v_need integer; v_have integer; v_room integer;
begin
  select * into b from buildings where id = p_building_id;
  if not found then return; end if;

  if not exists (select 1 from system_control sc
                 where sc.system_id = b.system_id and sc.controller_user_id = auth.uid()) then
    return;
  end if;

  select * into bt from building_types where id = b.building_type_id;
  select * into s from systems where id = b.system_id;

  v_rate := case
    when bt.produces_resource is null then 0
    when bt.consumes <> '{}'::jsonb then bt.produces_per_day
    when bt.produces_resource = s.primary_resource then bt.produces_per_day
    when bt.produces_resource = s.secondary_resource then bt.produces_per_day / 2
    else 0 end;

  -- Почему стоит: для добычи — нет залежи, для передела — нет сырья или места
  v_status := 'working';
  if b.completes_at is not null and b.completes_at > now() then
    v_status := 'building';
  elsif bt.produces_resource is not null and bt.consumes = '{}'::jsonb and v_rate = 0 then
    v_status := 'no_deposit';
  elsif bt.consumes <> '{}'::jsonb then
    for k in select jsonb_object_keys(bt.consumes) loop
      v_need := (bt.consumes ->> k)::integer;
      select coalesce(amount, 0) into v_have from planet_stock
      where system_id = b.system_id and resource = k;
      if coalesce(v_have, 0) < v_need then v_status := 'no_input'; end if;
    end loop;

    if v_status = 'working' then
      select planet_stock_cap(b.system_id)
             - coalesce((select amount from planet_stock
                         where system_id = b.system_id and resource = bt.produces_resource), 0)
        into v_room;
      if v_room <= 0 then v_status := 'no_room'; end if;
    end if;
  elsif bt.produces_resource is null then
    v_status := 'passive';
  end if;

  return query select
    bt.code, bt.name,
    bt.produces_resource,
    (select r.name from resources r where r.id = bt.produces_resource),
    (select r.color from resources r where r.id = bt.produces_resource),
    v_rate, bt.consumes, bt.storage_bonus,
    case when bt.produces_resource is null then null
         else coalesce(b.last_extract_at, b.completes_at, now())
              + make_interval(secs => game_setting_int('settlement_day_seconds', 86400))
    end,
    v_status;
end;
$$;


--
-- Name: get_carried_units(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_carried_units(p_carrier_unit_id uuid DEFAULT NULL::uuid, p_ship_id uuid DEFAULT NULL::uuid) RETURNS TABLE(unit_id uuid, unit_type text, unit_name text, unit_image text, hp integer, slots integer, passengers integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select u.id, u.unit_type, t.name, t.image, u.hp,
         unit_total_slots(u.id),
         (select count(*)::integer from unit_positions p where p.carrier_unit_id = u.id)
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  where u.owner_user_id = auth.uid()
    and ((p_carrier_unit_id is not null and u.carrier_unit_id = p_carrier_unit_id)
      or (p_ship_id is not null and u.carrier_ship_id = p_ship_id
          and (coalesce(t.is_vehicle, false) or coalesce(t.is_hero, false))))
  order by t.name;
$$;


--
-- Name: get_dock_ships(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dock_ships(p_system_id text) RETURNS TABLE(ship_id uuid, ship_type text, name text, image text, hp integer, full_hp integer, missing integer, repair_cost integer, repair_seconds integer, hangar_used integer, hangar_max integer, at_dock boolean, busy boolean, upgrades text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select s.id, s.ship_type, coalesce(s.name, t.name), t.image,
         s.hp, st.max_hp, q.missing, q.cost, q.seconds,
         hangar_used(s.id), st.hangar_slots,
         is_ship_at_dock(s.id),
         exists (select 1 from repair_orders ro
                 where ro.ship_id = s.id and not ro.delivered),
         s.upgrades
  from ships s
  join ship_types t on t.id = s.ship_type
  cross join lateral ship_stats(s.id) st
  cross join lateral ship_repair_quote(s.id) q
  where s.system_id = p_system_id
    and s.owner_user_id = auth.uid()
    and s.carrier_ship_id is null
    and not s.in_transit
    and not t.is_fighter
  order by t.name;
$$;


--
-- Name: get_drop_ready_cargo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_drop_ready_cargo(p_system_id text) RETURNS TABLE(ship_id uuid, ship_name text, zone integer, unit_type text, unit_name text, unit_image text, quantity integer, x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select s.id, coalesce(s.name, st.name),
         is_in_orbital_drop(s.x, s.y,
           ship_box_w(st.width_cells, st.height_cells, s.facing),
           ship_box_h(st.width_cells, st.height_cells, s.facing)),
         u.unit_type, ut.name, ut.image, count(*)::integer, s.x, s.y
  from ships s
  join ship_types st on st.id = s.ship_type
  join unit_positions u on u.carrier_ship_id = s.id
  join unit_types ut on ut.id = u.unit_type
  where s.system_id = p_system_id
    and s.owner_user_id = auth.uid()
    and not s.in_transit
    and not coalesce(ut.is_vehicle, false) and not coalesce(ut.is_hero, false)
  group by s.id, st.name, st.width_cells, st.height_cells, s.facing, s.x, s.y,
           u.unit_type, ut.name, ut.image
  order by st.name, ut.name;
$$;


--
-- Name: get_drop_ready_vehicles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_drop_ready_vehicles(p_system_id text) RETURNS TABLE(unit_id uuid, unit_type text, unit_name text, unit_image text, ship_id uuid, ship_name text, zone integer, width_cells integer, height_cells integer, passengers integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select u.id, u.unit_type, t.name, t.image,
         s.id, coalesce(s.name, st.name),
         is_in_orbital_drop(s.x, s.y,
           ship_box_w(st.width_cells, st.height_cells, s.facing),
           ship_box_h(st.width_cells, st.height_cells, s.facing)),
         t.width_cells, t.height_cells,
         (select count(*)::integer from unit_positions p where p.carrier_unit_id = u.id)
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  join ships s on s.id = u.carrier_ship_id
  join ship_types st on st.id = s.ship_type
  where u.owner_user_id = auth.uid()
    and s.system_id = p_system_id
    and not s.in_transit
    and (coalesce(t.is_vehicle, false) or coalesce(t.is_hero, false))
  order by t.name;
$$;


--
-- Name: get_enemy_transits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_enemy_transits(p_system_id text) RETURNS TABLE(commander_id uuid, commander_name text, owner_name text, faction text, from_system text, from_name text, to_system text, to_name text, ships integer, seconds_left integer, cargo text, lane_system text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with me as (
    select faction from profiles where id = auth.uid()
  ),
  -- Штаб должен стоять на этой планете и быть достроенным,
  -- а планета — под нашим контролем
  post as (
    select b.system_id
    from buildings b
    join building_types bt on bt.id = b.building_type_id
    join systems s on s.id = b.system_id
    where b.system_id = p_system_id
      and bt.code in ('rep_hq', 'cis_control')
      and (b.completes_at is null or b.completes_at <= now())
      and b.faction = s.faction
      and exists (select 1 from system_control sc
                  where sc.system_id = p_system_id
                    and sc.controller_user_id = auth.uid())
  )
  select c.id, c.name, coalesce(p.nickname, 'неизвестный'), c.faction,
         c.moving_from, sf.name, c.moving_to, st.name,
         (select count(*)::integer from ships sh where sh.commander_id = c.id),
         greatest(0, ceil(extract(epoch from c.arrives_at - now()))::integer),
         (select string_agg(distinct r.name, ', ')
          from ships sh
          join ship_resource_cargo rc on rc.ship_id = sh.id
          join resources r on r.id = rc.resource
          where sh.commander_id = c.id),
         lane_system(c.moving_from, c.moving_to)
  from commanders c
  join me on true
  join post on true
  join profiles p on p.id = c.user_id
  join systems sf on sf.id = c.moving_from
  join systems st on st.id = c.moving_to
  where c.moving_to is not null
    and c.arrives_at is not null
    and c.arrives_at > now()
    and c.faction is distinct from me.faction
    -- Видим то, что идёт через нашу систему или её соседей
    and (
      system_hops(p_system_id, c.moving_from) <= game_setting_int('intel_range_jumps', 1)
      or system_hops(p_system_id, c.moving_to) <= game_setting_int('intel_range_jumps', 1)
    )
  order by c.arrives_at;
$$;


--
-- Name: get_event_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_event_counts() RETURNS TABLE(category text, unseen integer, total integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select coalesce(e.category, 'build'),
         count(*) filter (where g.seen_at is null
                            and coalesce(e.category, 'build') <> 'income')::integer,
         count(*)::integer
  from game_events g
  left join event_types e on e.type = g.type
  where g.user_id = auth.uid()
    and not coalesce((g.meta ->> 'quiet')::boolean, false)
    and g.created_at > now() - interval '7 days'
  group by 1;
$$;


--
-- Name: get_event_feed(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_event_feed(p_category text DEFAULT NULL::text, p_limit integer DEFAULT 60) RETURNS TABLE(id uuid, created_at timestamp with time zone, type text, category text, title text, tone text, jumpable boolean, subject text, amount integer, system_id text, system_name text, is_deep_space boolean, seen boolean, meta jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select g.id, g.created_at, g.type,
         coalesce(e.category, 'build'),
         coalesce(e.title, g.type),
         coalesce(e.tone, 'neutral'),
         coalesce(e.jumpable, false) and g.system_id is not null,
         coalesce(r.name, sn.name, ut.name, st.name, g.subject),
         g.amount,
         g.system_id, s.name, coalesce(s.is_deep_space, false),
         g.seen_at is not null,
         -- откуда пришёл флот тоже бывает кодом — переводим и его
         case when g.meta ? 'from' and exists (select 1 from systems x where x.id = g.meta ->> 'from')
              then g.meta || jsonb_build_object('from_name',
                     (select x.name from systems x where x.id = g.meta ->> 'from'))
              else g.meta end
  from game_events g
  left join event_types e on e.type = g.type
  left join systems s on s.id = g.system_id
  left join resources r on r.id = g.subject
  left join systems sn on sn.id = g.subject
  left join unit_types ut on ut.id = g.subject
  left join ship_types st on st.id = g.subject
  where g.user_id = auth.uid()
    and not coalesce((g.meta ->> 'quiet')::boolean, false)
    and (p_category is null or coalesce(e.category, 'build') = p_category)
  order by g.created_at desc
  limit greatest(1, least(200, p_limit));
$$;


--
-- Name: get_faction_economy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faction_economy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_fac text;
begin
  select faction into v_fac from profiles where id = auth.uid();
  if not faction_power(auth.uid(), v_fac, 'economy') then
    raise exception 'Хозяйство фракции видит лидер и те, кому он это поручил';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', s.id, 'name', s.name,
      'controller', (select p.nickname from system_control sc join profiles p on p.id = sc.controller_user_id
                     where sc.system_id = s.id),
      'level', ss.level, 'level_name', sl.name, 'satisfaction', ss.satisfaction,
      'income', case when ss.system_id is null then 0 else settlement_day_income(s.id) end,
      'slots', building_slot_cap(s.id),
      'used', (select count(*) from buildings b where b.system_id = s.id),
      'cap', planet_stock_cap(s.id),
      'stock', coalesce((
        select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name, 'color', r.color, 'amount', ps.amount)
                         order by r.sort_order)
        from planet_stock ps join resources r on r.id = ps.resource
        where ps.system_id = s.id and ps.amount > 0), '[]'::jsonb),
      'per_day', coalesce((
        select jsonb_agg(jsonb_build_object('id', q.res, 'name', r.name, 'color', r.color, 'amount', q.n)
                         order by r.sort_order)
        from (select bt.produces_resource res,
                     sum(case when s.primary_resource = bt.produces_resource then bt.produces_per_day
                              when s.secondary_resource = bt.produces_resource then bt.produces_per_day / 2
                              else bt.produces_per_day end)::integer n
              from buildings b join building_types bt on bt.id = b.building_type_id
              where b.system_id = s.id and bt.produces_resource is not null
                and b.faction = s.faction
                and (b.completes_at is null or b.completes_at <= now())
              group by bt.produces_resource) q
        join resources r on r.id = q.res where q.n > 0), '[]'::jsonb),
      'buildings', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'slot', b.slot_index, 'name', bt.name,
                 'state', case when b.completes_at is not null and b.completes_at > now() then 'build'
                               when b.faction is distinct from s.faction then 'trophy' else 'ok' end,
                 'owner', (select nickname from profiles where id = b.owner_user_id))
               order by b.slot_index)
        from buildings b join building_types bt on bt.id = b.building_type_id
        where b.system_id = s.id), '[]'::jsonb),
      'orders', (select count(*) from unit_orders o where o.system_id = s.id and not o.delivered),
      'research', (select count(*) from research_orders o where o.system_id = s.id and not o.delivered))
      order by s.name)
    from systems s
    left join settlement_state ss on ss.system_id = s.id
    left join settlement_levels sl on sl.level = ss.level
    where s.faction = v_fac and not coalesce(s.is_deep_space, false)), '[]'::jsonb);
end;
$$;


--
-- Name: get_faction_feed(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faction_feed(p_limit integer) RETURNS TABLE(created_at timestamp with time zone, type text, title text, tone text, subject text, system_id text, system_name text, actor_name text, amount integer, meta jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_fac text;
begin
  if auth.uid() is null then
    raise exception 'Нужно войти в игру';
  end if;
  select p.faction into v_fac from profiles p where p.id = auth.uid();
  if v_fac is null then
    return;
  end if;

  return query
  select g.created_at, g.type,
         case when g.type = 'planet_captured' then
                case when g.faction = v_fac then 'Планета взята' else 'Планета потеряна' end
              else coalesce(e.title, g.type) end,
         case when g.type = 'planet_captured' then
                case when g.faction = v_fac then 'good' else 'bad' end
              else coalesce(e.tone, 'neutral') end,
         case when g.type = 'capture_started' then
                case g.subject when 'republic' then 'Республика' when 'cis' then 'КНС' else g.subject end
              else coalesce(r.name, sn.name, ut.name, st.name, g.subject) end,
         g.system_id, s.name, pr.nickname, g.amount,
         case when g.meta ? 'from' and exists (select 1 from systems x where x.id = g.meta ->> 'from')
              then g.meta || jsonb_build_object('from_name',
                     (select x.name from systems x where x.id = g.meta ->> 'from'))
              else g.meta end
  from game_events g
  left join event_types e on e.type = g.type
  left join systems s on s.id = g.system_id
  left join profiles pr on pr.id = g.user_id
  left join resources r on r.id = g.subject
  left join systems sn on sn.id = g.subject
  left join unit_types ut on ut.id = g.subject
  left join ship_types st on st.id = g.subject
  where (g.visibility = 'faction' and g.faction = v_fac)
     or g.visibility = 'all'
     or (g.visibility = 'private' and g.faction = v_fac
         and g.type in ('capture_started', 'enemy_approaching', 'planet_granted', 'planet_revoked'))
  order by g.created_at desc
  limit greatest(1, least(50, coalesce(p_limit, 20)));
end;
$$;


--
-- Name: get_faction_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faction_orders() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_fac text; d record;
begin
  select faction into v_fac from profiles where id = auth.uid();
  if v_fac is null then return null; end if;
  select * into d from faction_directives where faction = v_fac;

  return jsonb_build_object(
    'can_edit', faction_power(auth.uid(), v_fac, 'orders'),
    'directive', case when d.faction is null or btrim(d.text) = '' then null else
      jsonb_build_object('text', d.text, 'at', d.updated_at,
                         'by', (select nickname from profiles where id = d.updated_by)) end,
    'targets', coalesce((
      select jsonb_agg(jsonb_build_object(
               'system_id', t.system_id, 'name', s.name, 'kind', t.kind, 'note', t.note,
               'own', s.faction = v_fac, 'at', t.created_at,
               'by', (select nickname from profiles where id = t.created_by))
             order by case t.kind when 'attack' then 0 when 'defend' then 1
                                  when 'gather' then 2 else 3 end, t.created_at desc)
      from faction_targets t join systems s on s.id = t.system_id
      where t.faction = v_fac and t.active), '[]'::jsonb));
end;
$$;


--
-- Name: get_faction_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faction_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_fac text;
  v_enemy text;
  v_goal integer := game_setting_int('capture_seconds', 60);
  v_leader uuid;
  v_res jsonb;
begin
  if v_me is null then
    raise exception 'Нужно войти в игру';
  end if;

  select faction into v_fac from profiles where id = v_me;
  if v_fac is null then
    return jsonb_build_object('faction', null);
  end if;
  v_enemy := case v_fac when 'republic' then 'cis' when 'cis' then 'republic' else null end;

  select leader_user_id into v_leader from faction_leadership where faction = v_fac;

  with
  edges as (
    select system_a a, system_b b from hyperlanes
    union select system_b, system_a from hyperlanes
  ),
  -- Соседство планет: напрямую или через одну точку глубокого космоса
  nb as (
    select e.a, e.b from edges e
    join systems sb on sb.id = e.b and not sb.is_deep_space
    union
    select e1.a, e2.b from edges e1
    join systems d on d.id = e1.b and d.is_deep_space
    join edges e2 on e2.a = d.id and e2.b <> e1.a
    join systems sb on sb.id = e2.b and not sb.is_deep_space
  ),
  own as (
    select s.id, s.name from systems s
    where s.faction = v_fac and not s.is_deep_space
  ),
  enemy_nb as (
    select o.id, count(distinct x.id)::int n,
           jsonb_agg(distinct x.name) names
    from own o
    join nb on nb.a = o.id
    join systems x on x.id = nb.b and x.faction = v_enemy and not x.is_deep_space
    group by o.id
  ),
  caps as (
    select sc.system_id, sc.faction, sc.status, sc.rate, sc.goal,
           coalesce(capture_progress(sc.system_id), 0) progress
    from system_capture sc
  ),
  planets as (
    select o.id, o.name,
           ctl.controller_user_id cid, cp.nickname cname,
           ss.level, sl.name level_name, ss.satisfaction,
           case when ss.system_id is null then 0 else settlement_day_income(o.id) end income,
           ss.fed, ss.food_short,
           (ss.upgrade_until is not null and ss.upgrade_until > now()) upgrading,
           coalesce(en.n, 0) enemy_n, coalesce(en.names, '[]'::jsonb) enemy_names,
           c.status cstatus, c.faction cfaction, c.progress cprogress, c.rate crate, coalesce(c.goal, v_goal) cgoal,
           case
             when c.status = 'distribution' and c.faction = v_fac then 'distribution'
             when c.status is not null and c.status <> 'distribution' and c.faction is distinct from v_fac then 'capture'
             when coalesce(en.n, 0) > 0 then 'front'
             else 'rear'
           end status
    from own o
    left join system_control ctl on ctl.system_id = o.id
    left join profiles cp on cp.id = ctl.controller_user_id
    left join settlement_state ss on ss.system_id = o.id
    left join settlement_levels sl on sl.level = ss.level
    left join enemy_nb en on en.id = o.id
    left join caps c on c.system_id = o.id
  )
  select jsonb_build_object(
    'faction', v_fac,
    'enemy', v_enemy,
    'server_now', now(),
    'next_payout', next_payout_at(),
    'capture_goal', v_goal,
    'leader', case when v_leader is null then null else
       jsonb_build_object('id', v_leader, 'nickname', (select nickname from profiles where id = v_leader)) end,
    'my_role', case when v_leader = v_me then 'leader' else 'member' end,
    'my_powers', to_jsonb(my_faction_powers()),
    'counts', jsonb_build_object(
       'planets_own', (select count(*) from own),
       'planets_enemy', (select count(*) from systems where faction = v_enemy and not is_deep_space),
       'planets_front', (select count(*) from planets where status in ('front', 'capture')),
       'players_own', (select count(*) from profiles where faction = v_fac),
       'players_enemy', (select count(*) from profiles where faction = v_enemy),
       'online_own', (select count(*) from profiles where faction = v_fac
                        and (last_seen_at > now() - interval '5 minutes' or id = v_me)),
       'units_own', (select coalesce(sum(u.quantity), 0) from unit_positions u
                       join unit_types t on t.id = u.unit_type
                       where u.faction = v_fac
                         and u.layer = 'ground' and u.hp > 0 and not coalesce(t.is_hero, false)),
       'heroes_own', (select count(*) from unit_positions u
                       join unit_types t on t.id = u.unit_type
                       where u.faction = v_fac
                         and u.hp > 0 and coalesce(t.is_hero, false)),
       'ships_own', (select count(*) from ships sh join ship_types st on st.id = sh.ship_type
                       where sh.faction = v_fac and not coalesce(st.is_fighter, false)),
       'fighters_own', (select count(*) from ships sh join ship_types st on st.id = sh.ship_type
                       where sh.faction = v_fac and coalesce(st.is_fighter, false)),
       'ships_moving', (select count(*) from ships sh where sh.faction = v_fac and sh.in_transit),
       'commanders_own', (select count(*) from commanders where faction = v_fac and unlocked),
       'stations_own', (select count(*) from space_stations where faction = v_fac
                          and (completes_at is null or completes_at <= now())),
       'income_day', (select coalesce(sum(income), 0) from planets),
       'income_last', (select coalesce(sum(ss.last_income), 0) from settlement_state ss
                         join own o on o.id = ss.system_id
                         where ss.last_paid_at > now() - interval '25 hours'),
       'settlements', coalesce((
          select jsonb_agg(jsonb_build_object('level', l.level, 'name', l.name, 'count', l.n) order by l.level)
          from (select p.level, max(p.level_name) name, count(*) n from planets p
                where p.level is not null group by p.level) l), '[]'::jsonb)
    ),
    'members', coalesce((
       select jsonb_agg(jsonb_build_object(
                'id', m.id, 'nickname', m.nickname,
                'planets', m.planets,
                'last_seen_at', case when m.id = v_me then now() else m.last_seen_at end,
                'is_leader', m.id = v_leader, 'is_me', m.id = v_me,
                'role', (select r.name from faction_role_members fm join faction_roles r on r.id = fm.role_id
                         where fm.user_id = m.id and r.faction = v_fac and not r.archived))
              order by (m.id = v_leader) desc,
                       (m.id = v_me or m.last_seen_at > now() - interval '5 minutes') desc,
                       m.planets desc, m.nickname)
       from (select pr.id, pr.nickname, pr.last_seen_at,
                    (select count(*) from planets p where p.cid = pr.id)::int planets
             from profiles pr where pr.faction = v_fac) m), '[]'::jsonb),
    'planets', coalesce((
       select jsonb_agg(jsonb_build_object(
                'id', p.id, 'name', p.name,
                'controller_id', p.cid, 'controller', p.cname,
                'level', p.level, 'level_name', p.level_name,
                'satisfaction', p.satisfaction, 'income', p.income,
                'fed', p.fed, 'food_short', p.food_short, 'upgrading', p.upgrading,
                'status', p.status,
                'enemy_neighbours', p.enemy_n, 'enemy_names', p.enemy_names,
                'capture', case when p.cstatus is null then null else jsonb_build_object(
                   'status', p.cstatus, 'faction', p.cfaction,
                   'progress', round(p.cprogress, 1), 'rate', p.crate, 'goal', p.cgoal) end)
              order by case p.status when 'capture' then 0 when 'distribution' then 1
                                     when 'front' then 2 else 3 end,
                       p.enemy_n desc, p.name)
       from planets p), '[]'::jsonb),
    'captures', coalesce((
       select jsonb_agg(jsonb_build_object(
                'system_id', c.system_id, 'name', s.name,
                'role', case when c.faction = v_fac then 'attack' else 'defend' end,
                'status', c.status, 'faction', c.faction,
                'progress', round(c.progress, 1), 'rate', c.rate, 'goal', coalesce(c.goal, v_goal),
                'seconds_left', case when c.rate > 0 then ceil((coalesce(c.goal, v_goal) - c.progress) / c.rate)
                                     when c.rate < 0 then ceil(c.progress / -c.rate)
                                     else null end)
              order by (c.faction <> v_fac) desc, c.progress desc)
       from caps c
       join systems s on s.id = c.system_id
       where c.status <> 'distribution'
         and (c.faction = v_fac or s.faction = v_fac)), '[]'::jsonb)
  ) into v_res;

  return v_res;
end;
$$;


--
-- Name: get_faction_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faction_staff() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_leader uuid;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null then return null; end if;
  select leader_user_id into v_leader from faction_leadership where faction = v_fac;

  return jsonb_build_object(
    'faction', v_fac,
    'is_leader', v_leader = v_me,
    'leader', case when v_leader is null then null else
       jsonb_build_object('id', v_leader, 'nickname', (select nickname from profiles where id = v_leader)) end,
    'powers', to_jsonb(my_faction_powers()),
    'my_role', (select r.id from faction_role_members m join faction_roles r on r.id = m.role_id
                where m.user_id = v_me and r.faction = v_fac and not r.archived),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'name', r.name, 'powers', to_jsonb(r.powers),
               'members', coalesce((
                 select jsonb_agg(jsonb_build_object('id', p.id, 'nickname', p.nickname,
                                                     'last_seen_at', p.last_seen_at) order by p.nickname)
                 from faction_role_members m join profiles p on p.id = m.user_id
                 where m.role_id = r.id and p.faction = v_fac), '[]'::jsonb))
             order by r.created_at)
      from faction_roles r where r.faction = v_fac and not r.archived), '[]'::jsonb),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'nickname', p.nickname, 'is_leader', p.id = v_leader,
               'role_id', (select m.role_id from faction_role_members m
                           join faction_roles r on r.id = m.role_id
                           where m.user_id = p.id and r.faction = v_fac and not r.archived))
             order by (p.id = v_leader) desc, p.nickname)
      from profiles p where p.faction = v_fac), '[]'::jsonb));
end;
$$;


--
-- Name: get_faction_systems(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faction_systems() RETURNS TABLE(system_id text, name text, controller_user_id uuid, controller_nickname text, pending boolean, buildings integer, primary_resource text, primary_name text, primary_color text, secondary_resource text, secondary_name text, secondary_color text, satisfaction integer, income integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select s.id, s.name, sc.controller_user_id, p.nickname,
         coalesce(cap.status = 'distribution', false),
         (select count(*)::integer from buildings b where b.system_id = s.id),
         s.primary_resource, rp.name, rp.color,
         s.secondary_resource, rs.name, rs.color,
         ss.satisfaction,
         case when ss.satisfaction is null then 0
              else settlement_day_income(ss.system_id) end
  from systems s
  left join system_control sc on sc.system_id = s.id
  left join profiles p on p.id = sc.controller_user_id
  left join system_capture cap on cap.system_id = s.id
  left join settlement_state ss on ss.system_id = s.id
  left join resources rp on rp.id = s.primary_resource
  left join resources rs on rs.id = s.secondary_resource
  where s.faction = (select faction from profiles where id = auth.uid())
    and not s.is_deep_space
  order by coalesce(cap.status = 'distribution', false) desc, s.name;
$$;


--
-- Name: get_hangar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hangar(p_ship_id uuid) RETURNS TABLE(fighter_id uuid, name text, image text, hp integer, max_hp integer, slots_used integer, slots_total integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select f.id, ft.name, ft.image, f.hp, ft.max_hp,
         hangar_used(p_ship_id), ct.hangar_slots
  from ships c
  join ship_types ct on ct.id = c.ship_type
  left join ships f on f.carrier_ship_id = c.id
  left join ship_types ft on ft.id = f.ship_type
  where c.id = p_ship_id and c.owner_user_id = auth.uid()
    and f.id is not null;
$$;


--
-- Name: get_hero_roster(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hero_roster(p_building_id uuid DEFAULT NULL::uuid) RETURNS TABLE(hero_id uuid, name text, portrait text, unit_type text, unit_name text, hired_at timestamp with time zone, died_at timestamp with time zone, died_system_id text, kills integer, on_map boolean, system_id text, unit_id uuid, hp integer, learned integer, training_name text, training_left integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select h.id, h.name, h.portrait,
         h.unit_type, ut.name,
         h.hired_at, h.died_at, h.died_system_id,
         coalesce((select count(*)::integer from hero_kills k where k.hero_id = h.id), 0),
         u.x is not null,
         u.system_id, u.id, u.hp,
         coalesce((select count(*)::integer from hero_learned l where l.hero_id = h.id), 0),
         a.name,
         case when t.completes_at is null then null
              else greatest(0, ceil(extract(epoch from t.completes_at - now()))::integer)
         end
  from heroes h
  join unit_types ut on ut.id = h.unit_type
  left join unit_positions u on u.hero_id = h.id
  left join hero_training t on t.hero_id = h.id and not t.delivered
  left join hero_abilities a on a.id = t.ability_id
  where h.owner_user_id = auth.uid()
    and (p_building_id is null or h.faction = (
          select b.faction from buildings b where b.id = p_building_id))
  order by h.died_at nulls first, h.hired_at;
$$;


--
-- Name: get_hero_tree(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hero_tree(p_hero_id uuid) RETURNS TABLE(ability_id text, name text, description text, icon text, kind text, branch text, tier integer, requires text[], cost_credits integer, kills_required integer, train_seconds integer, tree_col numeric, tree_row numeric, learned boolean, unlocked boolean, kills_have integer, in_training boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with me as (
    select h.id, h.faction,
           (select count(*)::integer from hero_kills k where k.hero_id = h.id) as kills
    from heroes h
    where h.id = p_hero_id and h.owner_user_id = auth.uid()
  ),
  known as (
    select ability_id from hero_learned where hero_id = p_hero_id
  )
  select a.id, a.name, a.description, a.icon, a.kind,
         a.branch, a.tier, a.requires,
         a.cost_credits, a.kills_required, a.train_seconds,
         a.tree_col, a.tree_row,
         a.id in (select ability_id from known),
         not exists (
           select 1 from unnest(a.requires) req
           where req not in (select ability_id from known)
         ),
         me.kills,
         exists (select 1 from hero_training t
                 where t.hero_id = p_hero_id and t.ability_id = a.id and not t.delivered)
  from hero_abilities a, me
  where a.faction = me.faction
  order by a.tree_col, a.tree_row;
$$;


--
-- Name: get_income_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_summary() RETURNS TABLE(system_id text, system_name text, satisfaction integer, last_income integer, paid_today integer, last_paid_at timestamp with time zone, tasks_failed integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.id, s.name, ss.satisfaction,
         settlement_day_income(ss.system_id),
         case when ss.last_paid_at > now() - interval '24 hours'
              then coalesce(ss.last_income, 0) else 0 end,
         ss.last_paid_at,
         greatest(0, coalesce(ss.last_total, 0) - coalesce(ss.last_done, 0))
  from system_control sc
  join systems s on s.id = sc.system_id
  join settlement_state ss on ss.system_id = s.id
  where sc.controller_user_id = auth.uid() and not s.is_deep_space
  order by settlement_day_income(ss.system_id) desc;
$$;


--
-- Name: get_landable_fighters(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_landable_fighters(p_system_id text) RETURNS TABLE(fighter_id uuid, name text, image text, hp integer, max_hp integer, carrier_id uuid, carrier_name text, zone integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select f.id, coalesce(f.name, ft.name), ft.image, f.hp, ft.max_hp,
         c.id, coalesce(c.name, ct.name),
         is_in_orbital_drop(c.x, c.y,
           ship_box_w(ct.width_cells, ct.height_cells, c.facing),
           ship_box_h(ct.width_cells, ct.height_cells, c.facing))
  from ships f
  join ship_types ft on ft.id = f.ship_type
  join ships c on c.id = f.carrier_ship_id
  join ship_types ct on ct.id = c.ship_type
  where f.owner_user_id = auth.uid()
    and c.system_id = p_system_id
    and not c.in_transit
  order by ft.name;
$$;


--
-- Name: get_lease_partners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lease_partners() RETURNS TABLE(user_id uuid, nickname text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.id, p.nickname from profiles p
  where p.faction = (select faction from profiles where id = auth.uid())
    and p.id <> auth.uid() and coalesce(p.nickname, '') <> ''
  order by lower(p.nickname);
$$;


--
-- Name: get_loadable_ships(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_loadable_ships(p_system text) RETURNS TABLE(ship_id uuid, ship_name text, free_slots integer, x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select s.id, coalesce(s.name, st.name),
         (select capacity from ship_stats(s.id)) - ship_load_used(s.id),
         s.x, s.y
  from ships s join ship_types st on st.id = s.ship_type
  where s.system_id = p_system and s.owner_user_id = auth.uid()
    and s.carrier_ship_id is null and not coalesce(s.in_transit, false)
    and (select capacity from ship_stats(s.id)) - ship_load_used(s.id) > 0
    and is_in_orbital_drop(s.x, s.y, ship_box_w(st.width_cells, st.height_cells, s.facing), ship_box_h(st.width_cells, st.height_cells, s.facing)) is not null
  order by st.name;
$$;


--
-- Name: get_market_lots(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_market_lots(p_resource text DEFAULT NULL::text) RETURNS TABLE(lot_id uuid, resource text, resource_name text, amount_left integer, price_per_unit integer, system_id text, system_name text, seller_faction text, seller_name text, open_to text, mine boolean, foreign_side boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select l.id, l.resource, r.name, l.amount_left, l.price_per_unit,
         l.system_id, s.name, l.seller_faction,
         coalesce(p.nickname, 'неизвестный'), l.open_to,
         l.seller_user_id = auth.uid(),
         l.seller_faction is distinct from me.faction
  from market_lots l
  join resources r on r.id = l.resource
  join systems s on s.id = l.system_id
  left join profiles p on p.id = l.seller_user_id
  cross join (select faction from profiles where id = auth.uid()) me
  where l.active and l.amount_left > 0
    and (p_resource is null or l.resource = p_resource)
    and (l.seller_user_id = auth.uid()
         or l.open_to = 'all'
         or l.seller_faction = me.faction)
  order by r.sort_order, l.price_per_unit;
$$;


--
-- Name: get_move_options(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_move_options(p_target text) RETURNS TABLE(commander_id uuid, name text, from_system text, from_name text, ships integer, ready integer, fleet jsonb, cargo jsonb, resources integer, left_behind integer, route text[], route_names text[], busy text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_fac text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_user;

  return query
  with cmd as (
    select c.id, c.name, c.current_system, c.slot_index, r.path,
      (select 'На рейсе снабжения «' || sr.name || '»' from supply_routes sr
          where sr.commander_id = c.id and sr.status = 'active' limit 1) as busy
    from commanders c
    cross join lateral (select convoy_route_to(c.current_system, p_target, v_fac) as path) r
    where c.user_id = v_user and c.unlocked and c.moving_to is null
      and c.current_system is not null and c.current_system <> p_target
      and r.path is not null
  ),
  fl as (
    select s.id, s.commander_id, s.ship_type, t.name, t.image,
           is_in_hyperspace_zone(s.y, ship_box_h(t.width_cells, t.height_cells, s.facing),
                                 hyperspace_side(s.system_id, s.faction)) as rdy
    from ships s
    join ship_types t on t.id = s.ship_type
    join cmd on cmd.id = s.commander_id and cmd.current_system = s.system_id
    where not s.in_transit and s.carrier_ship_id is null
  ),
  inside as (
    select fl.commander_id, 'fighter'::text kind, ft.name, ft.image, 1 as n
    from fl join ships f on f.carrier_ship_id = fl.id
    join ship_types ft on ft.id = f.ship_type
    union all
    select fl.commander_id, case when ut.is_hero then 'hero' when ut.is_vehicle then 'vehicle' else 'unit' end,
           coalesce(u.hero_name, ut.name), coalesce(u.portrait, ut.image), 1
    from fl join unit_positions u on u.carrier_ship_id = fl.id
    join unit_types ut on ut.id = u.unit_type
    union all
    select fl.commander_id, 'unit', ut.name, ut.image, 1
    from fl join unit_positions v on v.carrier_ship_id = fl.id
    join unit_positions u on u.carrier_unit_id = v.id
    join unit_types ut on ut.id = u.unit_type
  )
  select cmd.id, cmd.name, cmd.current_system, sy.name,
    (select count(*)::integer from fl where fl.commander_id = cmd.id),
    (select count(*)::integer from fl where fl.commander_id = cmd.id and fl.rdy),
    coalesce((select jsonb_agg(jsonb_build_object('name', g.name, 'image', g.image, 'count', g.n)
                                order by g.n desc, g.name)
              from (select fl.name, fl.image, count(*)::integer n from fl
                    where fl.commander_id = cmd.id group by fl.name, fl.image) g), '[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object('kind', g.kind, 'name', g.name,
                                                  'image', g.image, 'count', g.n)
                                order by g.kind, g.n desc, g.name)
              from (select i.kind, i.name, i.image, sum(i.n)::integer n from inside i
                    where i.commander_id = cmd.id group by i.kind, i.name, i.image) g), '[]'::jsonb),
    coalesce((select sum(r.amount)::integer from fl
              join ship_resource_cargo r on r.ship_id = fl.id
              where fl.commander_id = cmd.id), 0),
    (select count(*)::integer from ships s
     where s.owner_user_id = v_user and s.system_id = cmd.current_system
       and not s.in_transit and s.carrier_ship_id is null and s.commander_id is null),
    cmd.path,
    (select array_agg(coalesce(s2.name, p.sid) order by p.ord)
       from unnest(cmd.path) with ordinality p(sid, ord) left join systems s2 on s2.id = p.sid),
    cmd.busy
  from cmd
  join systems sy on sy.id = cmd.current_system
  order by (cmd.busy is not null), cardinality(cmd.path), sy.name, cmd.slot_index;
end;
$$;


--
-- Name: get_my_commanders_at(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_commanders_at(p_system_id text) RETURNS TABLE(commander_id uuid, name text, ships integer, ready integer, busy boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select c.id, c.name,
         (select count(*)::integer from ships s
          where s.commander_id = c.id and s.system_id = p_system_id and not s.in_transit),
         (select count(*)::integer from ships s
          join ship_types t on t.id = s.ship_type
          where s.commander_id = c.id and s.system_id = p_system_id and not s.in_transit
            and is_in_hyperspace_zone(
                  s.y, ship_box_h(t.width_cells, t.height_cells, s.facing),
                  hyperspace_side(p_system_id, s.faction))),
         c.moving_to is not null
  from commanders c
  where c.user_id = auth.uid() and c.unlocked and c.current_system = p_system_id
  order by c.slot_index;
$$;


--
-- Name: get_my_leases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_leases() RETURNS TABLE(id uuid, role text, status text, system_id text, system_name text, building_id uuid, target_name text, image text, partner_name text, hours integer, price integer, created_at timestamp with time zone, offer_expires_at timestamp with time zone, starts_at timestamp with time zone, ends_at timestamp with time zone, seconds_left integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.id,
         case when l.lessor_id = auth.uid() then 'lessor' else 'lessee' end,
         lease_effective_status(l),
         l.system_id, s.name, l.building_id, l.target_name,
         case when l.building_id is null then
                (select bt.image from building_types bt where bt.is_space and bt.faction = l.faction limit 1)
              else (select bt.image from buildings b join building_types bt on bt.id = b.building_type_id
                    where b.id = l.building_id) end,
         (select nickname from profiles where id = case when l.lessor_id = auth.uid() then l.lessee_id else l.lessor_id end),
         l.hours, l.price, l.created_at, l.offer_expires_at, l.starts_at, l.ends_at,
         case when lease_effective_status(l) = 'active'
              then greatest(0, ceil(extract(epoch from l.ends_at - now())))::integer
              when lease_effective_status(l) = 'offered'
              then greatest(0, ceil(extract(epoch from l.offer_expires_at - now())))::integer
              else 0 end
  from production_leases l
  join systems s on s.id = l.system_id
  where (l.lessor_id = auth.uid() or l.lessee_id = auth.uid())
    and greatest(l.created_at, coalesce(l.closed_at, l.ends_at, l.offer_expires_at)) > now() - interval '7 days'
  order by (lease_effective_status(l) in ('offered','active')) desc, l.created_at desc
  limit 40;
$$;


--
-- Name: get_my_market_lots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_market_lots() RETURNS TABLE(lot_id uuid, resource text, resource_name text, amount_left integer, price_per_unit integer, system_id text, system_name text, open_to text, reserved integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select l.id, l.resource, r.name, l.amount_left, l.price_per_unit,
         l.system_id, s.name, l.open_to,
         coalesce((select sum(o.amount_left)::integer from market_orders o
                   where o.lot_id = l.id and o.status = 'reserved'), 0)
  from market_lots l
  join resources r on r.id = l.resource
  join systems s on s.id = l.system_id
  where l.seller_user_id = auth.uid() and l.active
    and (l.amount_left > 0
         or exists (select 1 from market_orders o
                    where o.lot_id = l.id and o.status = 'reserved'))
  order by r.sort_order;
$$;


--
-- Name: get_my_market_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_market_orders() RETURNS TABLE(order_id uuid, resource text, resource_name text, amount_left integer, price_per_unit integer, paid integer, system_id text, system_name text, expires_at timestamp with time zone, seconds_left integer, status text, fleet_sent boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select o.id, l.resource, r.name, o.amount_left, o.price_per_unit, o.paid,
         l.system_id, s.name, o.expires_at,
         greatest(0, ceil(extract(epoch from o.expires_at - now()))::integer),
         o.status,
         exists (select 1 from supply_routes sr where sr.order_id = o.id and sr.status <> 'stopped')
  from market_orders o
  join market_lots l on l.id = o.lot_id
  join resources r on r.id = l.resource
  join systems s on s.id = l.system_id
  where o.buyer_user_id = auth.uid() and o.status = 'reserved'
  order by o.expires_at;
$$;


--
-- Name: get_my_planet_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_planet_requests() RETURNS TABLE(request_id uuid, system_id text, system_name text, status text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select r.id, r.system_id, s.name, r.status, r.created_at
  from planet_requests r join systems s on s.id = r.system_id
  where r.user_id = auth.uid()
    and (r.status = 'pending' or r.resolved_at > now() - interval '3 days')
  order by (r.status = 'pending') desc, r.created_at desc
  limit 20;
$$;


--
-- Name: get_my_processes_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_processes_v2() RETURNS TABLE(system_id text, system_name text, place text, kind text, subject text, quantity integer, seconds_left integer, total_seconds integer, layer text, slot_index integer, target text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with mine as (
    select s.id, s.name, s.faction
    from systems s
    join system_control sc on sc.system_id = s.id
    where sc.controller_user_id = auth.uid()
  )
  select m.id, m.name, bt.name, 'construction', bt.name, 1,
         greatest(0, ceil(extract(epoch from b.completes_at - now()))::integer),
         greatest(1, ceil(extract(epoch from b.completes_at - b.built_at))::integer),
         'ground', b.slot_index, 'slot'
  from mine m
  join buildings b on b.system_id = m.id
  join building_types bt on bt.id = b.building_type_id
  where b.completes_at is not null and b.completes_at > now()

  union all

  select m.id, m.name, coalesce(bt.name, 'Постройка'), 'unit', ut.name, uo.quantity,
         greatest(0, ceil(extract(epoch from uo.completes_at - now()))::integer),
         greatest(1, ceil(extract(epoch from uo.completes_at - uo.ordered_at))::integer),
         'ground', b.slot_index, 'open'
  from mine m
  join unit_orders uo on uo.system_id = m.id and not uo.delivered
  left join buildings b on b.id = uo.building_id
  left join building_types bt on bt.id = b.building_type_id
  left join unit_types ut on ut.id = uo.unit_type

  union all

  select m.id, m.name, 'Орбита', 'construction', 'Орбитальная станция', 1,
         greatest(0, ceil(extract(epoch from ss.completes_at - now()))::integer),
         greatest(1, ceil(extract(epoch from ss.completes_at - ss.built_at))::integer),
         'space', null::integer, 'station'
  from mine m
  join space_stations ss on ss.system_id = m.id
  where ss.completes_at is not null and ss.completes_at > now()

  union all

  select m.id, m.name, 'Орбитальная станция', 'ship', st.name, 1,
         greatest(0, ceil(extract(epoch from so.completes_at - now()))::integer),
         greatest(1, ceil(extract(epoch from so.completes_at - so.ordered_at))::integer),
         'space', null::integer, 'shipyard'
  from mine m
  join ship_orders so on so.system_id = m.id and not so.delivered
  left join ship_types st on st.id = so.ship_type

  union all

  select m.id, m.name, coalesce(bt.name, 'Научный центр'), 'research', rs.name, 1,
         greatest(0, ceil(extract(epoch from ro.completes_at - now()))::integer),
         greatest(1, ceil(extract(epoch from ro.completes_at - ro.ordered_at))::integer),
         'ground', b.slot_index, 'open'
  from mine m
  join research_orders ro on ro.system_id = m.id and not ro.delivered
                         and ro.owner_user_id = auth.uid()
  join researches rs on rs.id = ro.research_id
  left join buildings b on b.id = ro.building_id
  left join building_types bt on bt.id = b.building_type_id

  union all

  -- Простаивающий цех найма
  select m.id, m.name, bt.name, 'idle', 'hire', 0, 0, 0, 'ground', b.slot_index, 'open'
  from mine m
  join buildings b on b.system_id = m.id
  join building_types bt on bt.id = b.building_type_id
  where (b.completes_at is null or b.completes_at <= now())
    and b.faction = m.faction
    and exists (select 1 from unit_types ut where ut.produced_by = bt.code)
    and not exists (select 1 from unit_orders uo where uo.building_id = b.id and not uo.delivered)

  union all

  -- Свободная лаборатория
  select m.id, m.name, bt.name, 'idle', 'research', 0, 0, 0, 'ground', b.slot_index, 'open'
  from mine m
  join buildings b on b.system_id = m.id
  join building_types bt on bt.id = b.building_type_id
  where bt.code in ('rep_research', 'cis_lab')
    and (b.completes_at is null or b.completes_at <= now())
    and b.faction = m.faction
    and not exists (select 1 from research_orders ro
                    where ro.owner_user_id = auth.uid() and not ro.delivered)

  union all

  -- Пустая верфь
  select m.id, m.name, 'Орбитальная станция', 'idle', 'shipyard', 0, 0, 0, 'space', null::integer, 'shipyard'
  from mine m
  join space_stations ss on ss.system_id = m.id
  where (ss.completes_at is null or ss.completes_at <= now())
    and ss.faction = m.faction
    and not exists (select 1 from ship_orders so where so.system_id = m.id and not so.delivered)

  order by 2, 4, 7;
$$;


--
-- Name: get_my_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_profile() RETURNS TABLE(id uuid, nickname text, faction text, access_code text, credits integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select id, nickname, faction, access_code, credits
  from profiles
  where id = auth.uid();
$$;


--
-- Name: get_my_supply_planets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_supply_planets() RETURNS TABLE(system_id text, system_name text, resource text, resource_name text, color text, stock integer, cap integer, share boolean, keep_min integer, max_per_day integer, audience text, want_min integer, taken_today integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_since timestamptz := last_payout_at();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  return query
  select s.id, s.name, r.id, r.name, r.color,
         coalesce(ps.amount, 0)::integer,
         planet_stock_cap(s.id),
         coalesce(ru.share, false), coalesce(ru.keep_min, 0), ru.max_per_day,
         coalesce(ru.audience, 'faction'), coalesce(ru.want_min, 0),
         coalesce((select sum(t.amount) from supply_takes t
                   where t.system_id = s.id and t.resource = r.id and t.taken_at >= v_since and t.owner_user_id = v_user), 0)::integer
  from system_control sc
  join systems s on s.id = sc.system_id and not s.is_deep_space
  cross join resources r
  left join planet_stock ps on ps.system_id = s.id and ps.resource = r.id
  left join supply_rules ru on ru.system_id = s.id and ru.resource = r.id and ru.set_by = v_user
  where sc.controller_user_id = v_user
  order by s.name, r.sort_order;
end $$;


--
-- Name: get_my_supply_routes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_supply_routes() RETURNS TABLE(id uuid, name text, commander_id uuid, commander_name text, ships integer, free_cargo integer, cargo jsonb, stops jsonb, loop boolean, status text, stop_index integer, phase text, here_system_id text, here_name text, next_name text, seconds_left integer, last_note text, cycles integer, moved_total integer, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  return query
  select r.id, r.name, r.commander_id, c.name,
         (select count(*)::integer from public.ships s where s.commander_id = r.commander_id and s.carrier_ship_id is null),
         commander_free_cargo(r.commander_id),
         coalesce((select jsonb_object_agg(x.res, x.amt)
                   from (select rc.resource as res, sum(rc.amount)::integer as amt
                         from ship_resource_cargo rc join public.ships s on s.id = rc.ship_id
                         where s.commander_id = r.commander_id
                         group by rc.resource) x), '{}'::jsonb),
         coalesce((select jsonb_agg(x.st || jsonb_build_object(
                     'system_name', sy.name,
                     'actions', coalesce((select jsonb_agg(y.a || jsonb_build_object(
                                   'resource_name', case when y.a ->> 'resource' = '*' then 'Всё' else rs.name end)
                                   order by y.ao)
                                 from jsonb_array_elements(x.st -> 'actions') with ordinality y(a, ao)
                                 left join resources rs on rs.id = y.a ->> 'resource'), '[]'::jsonb))
                   order by x.o)
                   from jsonb_array_elements(r.stops) with ordinality x(st, o)
                   left join systems sy on sy.id = x.st ->> 'system_id'), '[]'::jsonb),
         r.loop, r.status, r.stop_index, r.phase,
         case when c.moving_to is null then c.current_system end,
         hs.name,
         ns.name,
         (case when c.moving_to is not null and c.arrives_at is not null
                then greatest(0, ceil(extract(epoch from c.arrives_at - now())))
              when r.phase = 'waiting' and r.wait_until is not null and r.status = 'active'
                then greatest(0, ceil(extract(epoch from r.wait_until - now())))
              else 0 end)::integer,
         r.last_note, r.cycles, r.moved_total, r.updated_at
  from supply_routes r
  left join commanders c on c.id = r.commander_id
  left join systems hs on hs.id = c.current_system
  left join systems ns on ns.id = (r.stops -> r.stop_index ->> 'system_id')
  where r.owner_user_id = v_user
    and (r.status <> 'stopped' or r.updated_at > now() - interval '1 day')
  order by (r.status = 'stopped'), r.created_at;
end $$;


--
-- Name: get_my_transfers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_transfers() RETURNS TABLE(transfer_id uuid, direction text, partner_name text, status text, summary text, note text, created_at timestamp with time zone, seconds_left integer, items jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.id,
         case when t.to_user = auth.uid() then 'in' else 'out' end,
         p.nickname,
         case when t.status = 'pending' and t.expires_at <= now() then 'expired' else t.status end,
         t.summary, t.note, t.created_at,
         greatest(0, extract(epoch from (t.expires_at - now()))::integer),
         coalesce((select jsonb_agg(jsonb_build_object('kind', ti.kind, 'system_id', ti.system_id,
                                                       'system_name', sy.name, 'snapshot', ti.snapshot)
                                    order by sy.name, ti.kind, ti.snapshot->>'name')
                   from troop_transfer_items ti join systems sy on sy.id = ti.system_id
                   where ti.transfer_id = t.id), '[]'::jsonb)
  from troop_transfers t
  join profiles p on p.id = case when t.to_user = auth.uid() then t.from_user else t.to_user end
  where (t.to_user = auth.uid() or t.from_user = auth.uid())
    and (t.status = 'pending' or t.resolved_at > now() - interval '2 days')
    and t.created_at > now() - interval '3 days'
  order by (t.status = 'pending' and t.expires_at > now()) desc, t.created_at desc
  limit 30;
$$;


--
-- Name: get_pending_lease_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_lease_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::integer from production_leases l
  where l.lessee_id = auth.uid() and l.status = 'offered' and lease_effective_status(l) = 'offered';
$$;


--
-- Name: get_pending_transfer_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_transfer_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::integer from troop_transfers
  where to_user = auth.uid() and status = 'pending' and expires_at > now();
$$;


--
-- Name: get_planet_request_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_planet_request_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when faction_power(auth.uid(), p.faction, 'planet_requests')
              then (select count(*)::integer from planet_requests r
                    where r.faction = p.faction and r.status = 'pending')
              else 0 end
  from profiles p where p.id = auth.uid();
$$;


--
-- Name: get_planet_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_planet_requests() RETURNS TABLE(request_id uuid, system_id text, system_name text, requester_id uuid, requester_name text, controller_name text, fresh boolean, note text, created_at timestamp with time zone, rivals integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_faction text;
begin
  select faction into v_faction from profiles where id = auth.uid();
  if not faction_power(auth.uid(), v_faction, 'planet_requests') then
    raise exception 'Запросы видит лидер и те, кому он это поручил';
  end if;

  return query
  select r.id, r.system_id, s.name, r.user_id, p.nickname, cp.nickname,
         coalesce(cap.status = 'distribution', false), r.note, r.created_at,
         (select count(*)::integer from planet_requests o
          where o.system_id = r.system_id and o.status = 'pending' and o.id <> r.id)
  from planet_requests r
  join systems s on s.id = r.system_id
  join profiles p on p.id = r.user_id
  left join system_control sc on sc.system_id = r.system_id
  left join profiles cp on cp.id = sc.controller_user_id
  left join system_capture cap on cap.system_id = r.system_id
  where r.faction = v_faction and r.status = 'pending'
  order by r.created_at;
end;
$$;


--
-- Name: get_planet_stock(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_planet_stock(p_system_id text) RETURNS TABLE(resource text, name text, kind text, amount integer, cap integer, is_primary boolean, is_secondary boolean, per_day integer, color text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select r.id, r.name, r.kind,
         coalesce(ps.amount, 0),
         planet_stock_cap(p_system_id),
         s.primary_resource = r.id,
         s.secondary_resource = r.id,
         coalesce((
           select sum(case
                        when ms.building_id is not null then mine_day_estimate(b.id)
                        when s.primary_resource = bt.produces_resource
                          then bt.produces_per_day
                        when s.secondary_resource = bt.produces_resource
                          then bt.produces_per_day / 2
                        else bt.produces_per_day
                      end)::integer
           from buildings b join building_types bt on bt.id = b.building_type_id
           left join mine_sites ms on ms.building_id = b.id
           where b.system_id = p_system_id
             and bt.produces_resource = r.id
             and (b.completes_at is null or b.completes_at <= now())
         ), 0),
         r.color
  from systems s
  cross join resources r
  left join planet_stock ps on ps.system_id = s.id and ps.resource = r.id
  where s.id = p_system_id
    and (exists (select 1 from system_control sc
                 where sc.system_id = p_system_id
                   and sc.controller_user_id = auth.uid())
         or exists (select 1 from production_leases l
                    where l.system_id = p_system_id and l.lessee_id = auth.uid()
                      and l.status = 'active' and lease_is_live(l)))
  order by r.sort_order;
$$;


--
-- Name: get_repairable_units(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_repairable_units(p_building_id uuid) RETURNS TABLE(unit_id uuid, unit_type text, name text, image text, hero_name text, portrait text, hp integer, full_hp integer, missing integer, cost integer, seconds integer, x integer, y integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select u.id, u.unit_type, t.name, t.image,
         u.hero_name, u.portrait,
         u.hp, q.full_hp, q.missing, q.cost, q.seconds, u.x, u.y
  from buildings b
  join building_types bt on bt.id = b.building_type_id
  join unit_positions u
    on u.system_id = b.system_id and u.layer = 'ground'
   and u.owner_user_id = auth.uid() and u.x is not null
  join unit_types t on t.id = u.unit_type
  cross join lateral repair_quote(u.id) q
  where b.id = p_building_id
    and repair_building_kind(bt.code) is not null
    and (case when t.is_vehicle then 'vehicle' else 'infantry' end)
        = repair_building_kind(bt.code)
    and q.missing > 0
    and is_box_in_deploy_zone(b.system_id, u.x, u.y, t.width_cells, t.height_cells)
    and not exists (select 1 from repair_orders ro
                    where ro.unit_id = u.id and not ro.delivered)
  order by q.missing desc, t.name;
$$;


--
-- Name: get_requestable_planets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_requestable_planets() RETURNS TABLE(system_id text, name text, controller_name text, mine boolean, fresh boolean, requested boolean, primary_name text, primary_color text, secondary_name text, secondary_color text, satisfaction integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.system_id, f.name, f.controller_nickname,
         f.controller_user_id is not distinct from auth.uid(),
         f.pending,
         exists (select 1 from planet_requests r
                 where r.system_id = f.system_id and r.user_id = auth.uid() and r.status = 'pending'),
         f.primary_name, f.primary_color, f.secondary_name, f.secondary_color, f.satisfaction
  from get_faction_systems() f
  order by (f.controller_user_id is null) desc, f.pending desc, f.name;
$$;


--
-- Name: get_researches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_researches() RETURNS TABLE(id text, name text, description text, category text, icon text, icon_image text, scope text, applies_to text[], applies_units text[], tier integer, cost integer, seconds integer, effect_kind text, effect_value integer, ability_damage integer, done boolean, in_progress boolean, seconds_left integer, available boolean, requires_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with me as (select faction from profiles where id = auth.uid()),
  my_ships as (select coalesce(array_agg(st.id), '{}') as ids
               from ship_types st where st.faction = (select faction from me)),
  my_units as (select coalesce(array_agg(ut.id), '{}') as ids
               from unit_types ut where ut.faction = (select faction from me))
  select r.id, r.name, r.description, r.category, r.icon, r.icon_image, r.scope,
         array(select unnest(r.applies_to)    intersect select unnest((select ids from my_ships))),
         array(select unnest(r.applies_units) intersect select unnest((select ids from my_units))),
         r.tier, r.cost, r.research_seconds, r.effect_kind, r.effect_value, r.ability_damage,
         pr.research_id is not null,
         ro.id is not null,
         greatest(0, coalesce(ceil(extract(epoch from ro.completes_at - now()))::integer, 0)),
         (r.requires is null or exists (
            select 1 from player_research p2
            where p2.user_id = auth.uid() and p2.research_id = r.requires)),
         req.name
  from researches r
  left join player_research pr on pr.research_id = r.id and pr.user_id = auth.uid()
  left join research_orders ro
    on ro.research_id = r.id and ro.owner_user_id = auth.uid() and not ro.delivered
  left join researches req on req.id = r.requires
  where r.applies_to && (select ids from my_ships)
     or r.applies_units && (select ids from my_units)
  order by r.sort_order;
$$;


--
-- Name: get_route_candidates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_route_candidates(p_target text) RETURNS TABLE(commander_id uuid, name text, from_system text, from_name text, ships integer, ready integer, fleet jsonb, cargo jsonb, resources integer, left_behind integer, route text[], route_names text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_fac text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_user;

  return query
  with cmd as (
    select c.id, c.name, c.current_system, c.slot_index, r.path
    from commanders c
    cross join lateral (select convoy_route_to(c.current_system, p_target, v_fac) as path) r
    where c.user_id = v_user and c.unlocked and c.moving_to is null
      and c.current_system is not null and c.current_system <> p_target
      and r.path is not null
      and not exists (select 1 from supply_routes sr where sr.commander_id = c.id and sr.status = 'active')
  ),
  fl as (
    select s.id, s.commander_id, s.ship_type, t.name, t.image,
           is_in_hyperspace_zone(s.y, ship_box_h(t.width_cells, t.height_cells, s.facing),
                                 hyperspace_side(s.system_id, s.faction)) as rdy
    from ships s
    join ship_types t on t.id = s.ship_type
    join cmd on cmd.id = s.commander_id and cmd.current_system = s.system_id
    where not s.in_transit and s.carrier_ship_id is null
  ),
  inside as (
    select fl.commander_id, 'fighter'::text kind, ft.name, ft.image, 1 as n
    from fl join ships f on f.carrier_ship_id = fl.id
    join ship_types ft on ft.id = f.ship_type
    union all
    select fl.commander_id, case when ut.is_hero then 'hero' when ut.is_vehicle then 'vehicle' else 'unit' end,
           coalesce(u.hero_name, ut.name), coalesce(u.portrait, ut.image), 1
    from fl join unit_positions u on u.carrier_ship_id = fl.id
    join unit_types ut on ut.id = u.unit_type
    union all
    select fl.commander_id, 'unit', ut.name, ut.image, 1
    from fl join unit_positions v on v.carrier_ship_id = fl.id
    join unit_positions u on u.carrier_unit_id = v.id
    join unit_types ut on ut.id = u.unit_type
  )
  select cmd.id, cmd.name, cmd.current_system, sy.name,
    (select count(*)::integer from fl where fl.commander_id = cmd.id),
    (select count(*)::integer from fl where fl.commander_id = cmd.id and fl.rdy),
    coalesce((select jsonb_agg(jsonb_build_object('name', g.name, 'image', g.image, 'count', g.n)
                                order by g.n desc, g.name)
              from (select fl.name, fl.image, count(*)::integer n from fl
                    where fl.commander_id = cmd.id group by fl.name, fl.image) g), '[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object('kind', g.kind, 'name', g.name,
                                                  'image', g.image, 'count', g.n)
                                order by g.kind, g.n desc, g.name)
              from (select i.kind, i.name, i.image, sum(i.n)::integer n from inside i
                    where i.commander_id = cmd.id group by i.kind, i.name, i.image) g), '[]'::jsonb),
    coalesce((select sum(r.amount)::integer from fl
              join ship_resource_cargo r on r.ship_id = fl.id
              where fl.commander_id = cmd.id), 0),
    (select count(*)::integer from ships s
     where s.owner_user_id = v_user and s.system_id = cmd.current_system
       and not s.in_transit and s.carrier_ship_id is null and s.commander_id is null),
    cmd.path,
    (select array_agg(coalesce(s2.name, p.sid) order by p.ord)
       from unnest(cmd.path) with ordinality p(sid, ord) left join systems s2 on s2.id = p.sid)
  from cmd
  join systems sy on sy.id = cmd.current_system
  order by cardinality(cmd.path), sy.name, cmd.slot_index;
end;
$$;


--
-- Name: get_scout_destinations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scout_destinations(p_unit_id uuid) RETURNS TABLE(system_id text, name text, faction text, friendly boolean, seconds integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare u record; ut record; v_here text;
begin
  select * into u from unit_positions where id = p_unit_id;
  if not found or u.owner_user_id <> auth.uid() or u.x is null then return; end if;

  select * into ut from unit_types where id = u.unit_type;
  if not ut.is_scout then return; end if;

  v_here := u.system_id;

  return query
  select s.id, s.name, s.faction,
         s.faction is not distinct from u.faction,
         game_setting_int('scout_transit_seconds', 60)
  from hyperlanes h
  join systems s on s.id = case when h.system_a = v_here then h.system_b else h.system_a end
  where (h.system_a = v_here or h.system_b = v_here)
    and not s.is_deep_space
  order by s.name;
end;
$$;


--
-- Name: get_scouted_commanders(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scouted_commanders(p_system_id text) RETURNS TABLE(commander_name text, player_name text, faction text, arriving boolean, seconds_left integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select c.name, p.nickname, c.faction,
         c.arrives_at is not null and c.arrives_at > now(),
         greatest(0, coalesce(ceil(extract(epoch from c.arrives_at - now()))::integer, 0))
  from commanders c
  left join profiles p on p.id = c.user_id
  where has_scout_on(p_system_id)
    and c.faction is distinct from (select faction from profiles where id = auth.uid())
    and (
      c.current_system = p_system_id

      or (
        c.moving_to = p_system_id
        and c.arrives_at > now()
        and c.departed_at is not null
        -- Доля пройденного пути: считаем от общей длительности перелёта
        and extract(epoch from now() - c.departed_at)
            >= extract(epoch from c.arrives_at - c.departed_at)
               * game_setting_int('scout_warn_progress', 80) / 100.0
      )
    )
  order by 4, 1;
$$;


--
-- Name: get_scouted_commanders_map(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scouted_commanders_map() RETURNS TABLE(system_id text, enemies integer, names text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select c.current_system,
         count(*)::integer,
         string_agg(coalesce(p.nickname, 'неизвестный') || ' · ' || c.name, ', ' order by c.name)
  from commanders c
  left join profiles p on p.id = c.user_id
  join systems s on s.id = c.current_system
  where c.current_system is not null
    and c.moving_to is null
    and c.unlocked
    and not s.is_deep_space
    and c.faction is distinct from (select faction from profiles where id = auth.uid())
    and has_scout_on(c.current_system)
  group by c.current_system;
$$;


--
-- Name: get_server_clock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_server_clock() RETURNS TABLE(now_at timestamp with time zone, tz text, tz_label text, payout_hour integer, lock_hours integer, last_payout timestamp with time zone, next_payout timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select now(), server_tz(),
         coalesce((select value from game_settings where key = 'server_tz_label'), 'МСК'),
         game_setting_int('payout_hour', 4), game_setting_int('payout_lock_hours', 4),
         last_payout_at(), next_payout_at();
$$;


--
-- Name: get_server_time(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_server_time() RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    AS $$
  select now();
$$;


--
-- Name: get_settlement_dev(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_settlement_dev(p_system_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); v_faction text; sy record; st record; lv record; nx record;
  v_eff integer; v_stock jsonb; v_ctrl boolean; v_block text; k text;
  v_credits integer; v_need_food integer; v_have_food integer; v_fields integer;
  v_short text;
begin
  select faction into v_faction from profiles where id = v_me;
  select id, faction, is_deep_space into sy from systems where id = p_system_id;
  if v_faction is null or sy.faction is distinct from v_faction or coalesce(sy.is_deep_space, false) then
    return null;
  end if;

  select * into st from settlement_state where system_id = p_system_id;
  if not found then return null; end if;

  select * into lv from settlement_levels where level = st.level;
  select * into nx from settlement_levels where level = st.level + 1;

  v_eff := settlement_effective(p_system_id);
  select coalesce(jsonb_object_agg(resource, amount), '{}') into v_stock
  from planet_stock where system_id = p_system_id;
  v_ctrl := exists (select 1 from system_control where system_id = p_system_id and controller_user_id = v_me);
  select credits into v_credits from profiles where id = v_me;

  -- Почему нельзя расширить — первой причиной, по порядку важности
  if nx.level is null then v_block := 'Высший уровень';
  elsif not v_ctrl then v_block := 'Расширять может только управляющий планетой';
  elsif st.upgrade_until is not null then v_block := 'Расширение уже идёт';
  elsif is_capture_active(p_system_id) then v_block := 'Идёт захват — стройка остановлена';
  elsif st.dev_points < nx.dev_need then v_block := 'Нужно очков развития: ' || st.dev_points || ' из ' || nx.dev_need;
  elsif v_eff < nx.min_satisfaction then v_block := 'Нужно довольство не ниже ' || nx.min_satisfaction || ' (сейчас ' || v_eff || ')';
  elsif coalesce(v_credits, 0) < nx.cost_credits then v_block := 'Не хватает кредитов: нужно ' || nx.cost_credits;
  else
    for k in select jsonb_object_keys(nx.cost_resources) loop
      if coalesce((v_stock ->> k)::integer, 0) < (nx.cost_resources ->> k)::integer then
        v_short := coalesce((select name from resources where id = k), k);
        v_block := 'На складе не хватает: ' || v_short || ' ' || coalesce((v_stock ->> k)::integer, 0)
                   || ' из ' || (nx.cost_resources ->> k);
        exit;
      end if;
    end loop;
  end if;

  v_need_food := coalesce(lv.food_per_day, 0);
  v_have_food := coalesce((v_stock ->> 'food')::integer, 0);
  v_fields := case when settlement_has_district(p_system_id, 'fields')
                   then (select effect_value from district_types where id = 'fields') else 0 end;

  return jsonb_build_object(
    'level', st.level, 'level_name', lv.name, 'max_level', (select max(level) from settlement_levels),
    'dev_points', st.dev_points, 'dev_need', nx.dev_need,
    'satisfaction', st.satisfaction, 'effective', v_eff,
    'factors', coalesce((select jsonb_agg(jsonb_build_object('label', f.label, 'value', f.value))
                         from settlement_factors(p_system_id) f), '[]'),
    'income', settlement_day_income(p_system_id), 'income_mult',
      round(lv.income_mult * case when settlement_has_district(p_system_id, 'market')
                     then 1 + (select effect_value from district_types where id = 'market') / 100.0 else 1 end, 2),
    'next', case when nx.level is null then null else jsonb_build_object(
        'level', nx.level, 'name', nx.name, 'dev_need', nx.dev_need, 'min_satisfaction', nx.min_satisfaction,
        'credits', nx.cost_credits, 'resources', nx.cost_resources, 'seconds', nx.build_seconds,
        'slots', nx.district_slots,
        'build_slots', nx.extra_building_slots - coalesce(lv.extra_building_slots, 0),
        'food_per_day', nx.food_per_day, 'income_mult', nx.income_mult) end,
    'upgrade_until', st.upgrade_until, 'upgrade_to', st.upgrade_to,
    'upgrade_seconds_left', case when st.upgrade_until is null then 0
                                 else greatest(0, ceil(extract(epoch from st.upgrade_until - now())))::integer end,
    'stock', v_stock,
    'food', jsonb_build_object(
        'per_day', v_need_food, 'fields', v_fields, 'have', v_have_food, 'fed', st.fed,
        'days_left', case when v_need_food - v_fields > 0 then floor(v_have_food / (v_need_food - v_fields)::numeric)::integer end),
    'militia', jsonb_build_object(
        'count', settlement_militia_count(p_system_id), 'why', settlement_militia_why(p_system_id), 'k', loyalty_militia_k(p_system_id),
        'ready', st.militia_ready_at is null or st.militia_ready_at <= now(),
        'ready_in', case when st.militia_ready_at is null then 0
                         else greatest(0, ceil(extract(epoch from st.militia_ready_at - now())))::integer end,
        'alive', (select count(*) from npc_brains b join unit_positions u on u.id = b.unit_id
                  where b.system_id = p_system_id and b.kind = 'militia' and u.hp > 0)),
    'slots', lv.district_slots,
    'build_slots', building_slot_cap(p_system_id),
    'build_used', (select count(*)::integer from buildings b where b.system_id = p_system_id),
    'districts', coalesce((select jsonb_agg(jsonb_build_object(
        'slot', sd.slot, 'id', sd.district_id, 'name', dt.name, 'icon', dt.icon, 'effect', dt.effect,
        'image', dt.image, 'building', sd.completes_at > now(),
        'seconds_left', greatest(0, ceil(extract(epoch from sd.completes_at - now())))::integer) order by sd.slot)
      from settlement_districts sd join district_types dt on dt.id = sd.district_id
      where sd.system_id = p_system_id), '[]'),
    'is_controller', v_ctrl,
    'can_upgrade', v_block is null,
    'upgrade_block', v_block);
end;
$$;


--
-- Name: get_settlement_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_settlement_state(p_system_id text) RETURNS TABLE(satisfaction integer, income integer, next_income integer, cycle_started timestamp with time zone, seconds_left integer, total_paid integer, controller text, is_controller boolean, structure_bonus integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select st.satisfaction,
         settlement_day_income(st.system_id),
         settlement_day_income(st.system_id,
           least(game_setting_int('settlement_satisfaction_max',100),
                 settlement_effective(st.system_id) + game_setting_int('settlement_satisfaction_step',15))),
         st.cycle_started,
         greatest(0, ceil(extract(epoch from next_payout_at() - now()))::integer),
         st.total_paid,
         p.nickname,
         coalesce(sc.controller_user_id = auth.uid(), false),
         settlement_structure_bonus(st.system_id)
  from settlement_state st
  join systems sys on sys.id = st.system_id
  left join system_control sc on sc.system_id = st.system_id
  left join profiles p on p.id = sc.controller_user_id
  where st.system_id = p_system_id
    and sys.faction = (select faction from profiles where id = auth.uid());
$$;


--
-- Name: get_settlement_tasks(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_settlement_tasks(p_system_id text) RETURNS TABLE(id uuid, kind text, target integer, done_now boolean, payload jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select t.id, t.kind, t.target, settlement_task_done(t.id),
         case when t.kind = 'marauder' then marauder_task_view(t.payload) else t.payload end
  from settlement_tasks t
  join settlement_state st on st.system_id = t.system_id
  join systems sys on sys.id = t.system_id
  where t.system_id = p_system_id
    and t.cycle_start = st.cycle_started
    and sys.faction = (select faction from profiles where id = auth.uid())
  order by t.kind;
$$;


--
-- Name: get_ship_holds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ship_holds() RETURNS TABLE(ship_id uuid, unit_type text, unit_name text, unit_image text, quantity integer, is_vehicle boolean, passengers integer, slots integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  -- Пехота — счётчиком по типу, техника и герои — каждый своей строкой
  select u.carrier_ship_id, u.unit_type, t.name, t.image, count(*)::integer, false, 0,
         (count(*) * coalesce(t.slot_size, 1))::integer
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  where u.carrier_ship_id is not null
    and u.owner_user_id = auth.uid()
    and not coalesce(t.is_vehicle, false) and not coalesce(t.is_hero, false)
  group by u.carrier_ship_id, u.unit_type, t.name, t.image, t.slot_size

  union all

  select u.carrier_ship_id, u.unit_type, t.name, t.image, 1, true,
         (select count(*)::integer from unit_positions p where p.carrier_unit_id = u.id),
         unit_total_slots(u.id)
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  where u.carrier_ship_id is not null
    and u.owner_user_id = auth.uid()
    and (coalesce(t.is_vehicle, false) or coalesce(t.is_hero, false))

  order by 6 desc, 3;
$$;


--
-- Name: get_ship_loadable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ship_loadable(p_ship_id uuid) RETURNS TABLE(unit_type text, name text, image text, slot_size integer, available integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select u.unit_type, t.name, t.image, t.slot_size, count(*)::integer
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  join ships s on s.id = p_ship_id
  where s.owner_user_id = auth.uid()
    and u.system_id = s.system_id
    and u.layer = 'ground'
    and u.owner_user_id = auth.uid()
    and is_in_deploy_zone(u.system_id, u.x, u.y)
  group by u.unit_type, t.name, t.image, t.slot_size
  order by t.name;
$$;


--
-- Name: get_ship_resource_cargo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ship_resource_cargo(p_ship_id uuid) RETURNS TABLE(resource text, name text, amount integer, slots integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select rc.resource, r.name, rc.amount, resource_slots(rc.amount)
  from ship_resource_cargo rc
  join resources r on r.id = rc.resource
  join ships s on s.id = rc.ship_id
  where rc.ship_id = p_ship_id and s.owner_user_id = auth.uid()
  order by r.sort_order;
$$;


--
-- Name: get_shipyard_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_shipyard_state(p_system_id text) RETURNS TABLE(busy_name text, seconds_left integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select b.name, greatest(0, ceil(extract(epoch from b.completes_at - now())))::integer
  from shipyard_busy(p_system_id) b
  where auth.uid() is not null
    -- верфь видна только своей стороне (что строится и чинится у врага — разведданные)
    and exists (select 1 from systems sy join profiles pr on pr.id = auth.uid()
                where sy.id = p_system_id and sy.faction = pr.faction);
$$;


--
-- Name: get_stock_cap_parts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stock_cap_parts(p_system_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_base integer; v_dist integer; v_dep integer; v_n integer;
begin
  if auth.uid() is null then raise exception 'Не авторизован'; end if;
  -- предел склада и складские постройки — только по планетам своей стороны
  if not exists (select 1 from systems sy join profiles pr on pr.id = auth.uid()
                  where sy.id = p_system_id and sy.faction = pr.faction) then
    return null;
  end if;
  v_base := game_setting_int('planet_stock_base_cap', 200);
  v_dist := case when settlement_has_district(p_system_id, 'warehouses')
                 then (select effect_value from district_types where id = 'warehouses') else 0 end;
  select coalesce(sum(bt.storage_bonus), 0)::integer, count(*)::integer into v_dep, v_n
    from buildings b join building_types bt on bt.id = b.building_type_id
    join systems sy on sy.id = b.system_id
   where b.system_id = p_system_id and bt.storage_bonus > 0
     and (b.completes_at is null or b.completes_at <= now())
     and b.faction = sy.faction;
  return jsonb_build_object('base', v_base, 'district', coalesce(v_dist, 0), 'depots', v_dep, 'depot_count', v_n,
                            'total', planet_stock_cap(p_system_id));
end $$;


--
-- Name: get_supply_commanders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_commanders() RETURNS TABLE(commander_id uuid, name text, system_id text, system_name text, ships integer, free_cargo integer, ready boolean, busy text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  return query
  select c.id, c.name, c.current_system, s.name, q.n, commander_free_cargo(c.id),
         (c.moving_to is null and q.n > 0 and q.rdy = q.n),
         case when exists (select 1 from supply_routes r where r.commander_id = c.id
                           and r.status in ('active', 'paused', 'stalled')) then 'route'
              when c.moving_to is not null then 'moving' end
  from commanders c
  left join systems s on s.id = c.current_system
  cross join lateral (
    select count(*)::integer as n,
           (count(*) filter (where is_in_hyperspace_zone(
             sh.y, ship_box_h(t.width_cells, t.height_cells, sh.facing),
             hyperspace_side(c.current_system, sh.faction))))::integer as rdy
    from public.ships sh join ship_types t on t.id = sh.ship_type
    where sh.commander_id = c.id and sh.system_id = c.current_system
      and not sh.in_transit and sh.carrier_ship_id is null
  ) q
  where c.user_id = v_user and c.unlocked
  order by c.slot_index;
end $$;


--
-- Name: get_supply_grants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_grants() RETURNS TABLE(id uuid, other_user_id uuid, other_name text, direction text, status text, requested_by_me boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  return query
  select g.id,
         case when g.owner_user_id = v_user then g.grantee_user_id else g.owner_user_id end,
         p.nickname,
         case when g.owner_user_id = v_user then 'i_trust' else 'trusts_me' end,
         g.status,
         coalesce(g.requested_by = v_user, false),
         g.created_at
  from supply_grants g
  left join profiles p on p.id = case when g.owner_user_id = v_user then g.grantee_user_id else g.owner_user_id end
  where (g.owner_user_id = v_user or g.grantee_user_id = v_user)
    and g.status in ('pending', 'active')
  order by g.created_at desc;
end $$;


--
-- Name: get_supply_hub(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_hub() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select auth.uid() is not null and supply_has_hub(auth.uid());
$$;


--
-- Name: get_supply_map(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_map() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_fac text;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select p.faction into v_fac from profiles p where p.id = v_me;

  return (
    with fl as (
      select r.id, r.name, r.status, r.phase, r.loop, r.stop_index, r.stops, r.wait_until, r.order_id,
             c.name as cname, c.current_system, c.moving_from, c.moving_to, c.departed_at, c.arrives_at
      from supply_routes r join commanders c on c.id = r.commander_id
      where r.owner_user_id = v_me and r.status <> 'stopped'
    ),
    ids as (
      select s.id from systems s where s.faction = v_fac and not s.is_deep_space
      union select x.value ->> 'system_id' from fl cross join lateral jsonb_array_elements(fl.stops) x
      union select fl.current_system from fl
      union select fl.moving_from from fl
      union select fl.moving_to from fl
    ),
    sy as (select s.* from systems s where s.id in (select ids.id from ids where ids.id is not null))
    select jsonb_build_object(
      'now', now(),
      'faction', v_fac,
      'systems', (select coalesce(jsonb_agg(jsonb_build_object(
                    'id', s.id, 'name', s.name, 'tex', s.texture, 'x', s.world_x, 'y', s.world_y,
                    'faction', s.faction, 'deep', s.is_deep_space,
                    'mine', exists (select 1 from system_control sc where sc.system_id = s.id and sc.controller_user_id = v_me),
                    -- хаб — только на планетах своей стороны: чужие постройки закрыты туманом (can_see_building),
                    -- а постройки снабжения работают только у нынешней стороны планеты (sql/supply_fixes.sql)
                    'hub', s.faction = v_fac and exists (select 1 from buildings b join building_types bt on bt.id = b.building_type_id
                                    where b.system_id = s.id and bt.code in ('rep_logistics', 'cis_logistics')
                                      and b.faction = s.faction and (b.completes_at is null or b.completes_at <= now()))
                  ) order by s.name), '[]'::jsonb) from sy s),
      'lanes', (select coalesce(jsonb_agg(jsonb_build_array(h.system_a, h.system_b)), '[]'::jsonb) from hyperlanes h
                 where h.system_a in (select sy.id from sy) and h.system_b in (select sy.id from sy)),
      'fleets', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', fl.id, 'name', fl.name, 'commander', fl.cname, 'status', fl.status, 'phase', fl.phase,
                   'loop', fl.loop, 'idx', fl.stop_index, 'pickup', fl.order_id is not null,
                   'stops', (select coalesce(jsonb_agg(x.value ->> 'system_id' order by x.ordinality), '[]'::jsonb)
                               from jsonb_array_elements(fl.stops) with ordinality x),
                   'at', case when fl.moving_to is null then fl.current_system end,
                   'from', case when fl.moving_to is not null then coalesce(fl.moving_from, fl.current_system) end,
                   'to', fl.moving_to, 'dep', fl.departed_at, 'arr', fl.arrives_at,
                   'wait', case when fl.phase = 'waiting' then fl.wait_until end
                 ) order by fl.name), '[]'::jsonb) from fl)
    )
  );
end $$;


--
-- Name: get_supply_network(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_network() RETURNS TABLE(system_id text, system_name text, controller_id uuid, controller_name text, is_mine boolean, resource text, resource_name text, color text, available integer, need integer, audience text, can_take boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_fac text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select p.faction into v_fac from profiles p where p.id = v_user;

  return query
  select q.sid, q.sname, q.ctrl, q.cname, q.mine, q.rid, q.rname, q.rcolor,
         case when q.can then q.avail else 0 end, q.nd, q.aud, q.can
  from (
    select s.id as sid, s.name as sname, sc.controller_user_id as ctrl, pc.nickname as cname,
           (sc.controller_user_id = v_user) as mine,
           r.id as rid, r.name as rname, r.color as rcolor, r.sort_order as rso,
           ti.available as avail,
           greatest(0, coalesce(ru.want_min, 0) - ti.stock)::integer as nd,
           coalesce(ru.audience, 'faction') as aud,
           ti.can_take as can,
           coalesce(ru.share, false) as shr
    from systems s
    join system_control sc on sc.system_id = s.id and sc.controller_user_id is not null
    left join profiles pc on pc.id = sc.controller_user_id
    cross join resources r
    left join supply_rules ru on ru.system_id = s.id and ru.resource = r.id
                             and ru.set_by = sc.controller_user_id
    cross join lateral supply_take_info(s.id, r.id, v_user) ti
    where s.faction = v_fac and not s.is_deep_space
  ) q
  where (q.shr and q.avail > 0) or q.nd > 0
  order by q.mine desc, q.sname, q.rso;
end $$;


--
-- Name: get_supply_partners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_partners() RETURNS TABLE(user_id uuid, nickname text, planets integer, trust_status text, i_trust boolean, trusts_me boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_fac text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select p.faction into v_fac from profiles p where p.id = v_user;
  return query
  select q.id, q.nick, q.pl,
         case when q.pin then 'pending_in' when q.pout then 'pending_out'
              when q.itr or q.tme then 'active' end,
         q.itr, q.tme
  from (
    select p.id, p.nickname as nick,
           (select count(*)::integer from system_control sc join systems s on s.id = sc.system_id
             where sc.controller_user_id = p.id and s.faction = v_fac and not s.is_deep_space) as pl,
           exists (select 1 from supply_grants g where g.owner_user_id = v_user and g.grantee_user_id = p.id
                   and g.status = 'pending') as pin,
           exists (select 1 from supply_grants g where g.owner_user_id = p.id and g.grantee_user_id = v_user
                   and g.status = 'pending') as pout,
           exists (select 1 from supply_grants g where g.owner_user_id = v_user and g.grantee_user_id = p.id
                   and g.status = 'active') as itr,
           exists (select 1 from supply_grants g where g.owner_user_id = p.id and g.grantee_user_id = v_user
                   and g.status = 'active') as tme
    from profiles p
    where p.faction = v_fac and p.id <> v_user
  ) q
  order by q.pl desc, q.nick;
end $$;


--
-- Name: get_supply_route_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_route_log(p_route_id uuid) RETURNS TABLE(at timestamp with time zone, system_name text, text text, moved integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if not exists (select 1 from supply_routes r where r.id = p_route_id and r.owner_user_id = v_user) then
    raise exception 'Рейс не найден';
  end if;
  return query
  select l.at, s.name, l.text, l.moved
  from supply_route_log l left join systems s on s.id = l.system_id
  where l.route_id = p_route_id
  order by l.id desc
  limit 30;
end $$;


--
-- Name: get_supply_takes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supply_takes(p_system_id text) RETURNS TABLE(taken_at timestamp with time zone, taker_name text, resource_name text, amount integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if not exists (select 1 from system_control sc
                 where sc.system_id = p_system_id and sc.controller_user_id = v_user) then
    raise exception 'Это не твоя планета';
  end if;
  return query
  select t.taken_at, coalesce(p.nickname, 'неизвестный'), coalesce(r.name, t.resource), t.amount
  from supply_takes t
  left join profiles p on p.id = t.taker_user_id
  left join resources r on r.id = t.resource
  where t.system_id = p_system_id and t.owner_user_id = v_user
  order by t.taken_at desc
  limit 30;
end $$;


--
-- Name: get_system_buildings(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_buildings(p_system_id text) RETURNS TABLE(id uuid, system_id text, slot_index integer, building_type_id uuid, owner_user_id uuid, faction text, built_at timestamp with time zone, completes_at timestamp with time zone, type_name text, type_code text, type_icon text, type_image text, type_cost integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select
    b.id, b.system_id, b.slot_index, b.building_type_id, b.owner_user_id, b.faction,
    b.built_at,
    case when b.owner_user_id = auth.uid() then b.completes_at else null end,
    bt.name, bt.code, bt.icon, bt.image, bt.cost
  from buildings b
  join building_types bt on bt.id = b.building_type_id
  where b.system_id = p_system_id
    and can_see_building(b.system_id, b.faction, b.slot_index);
$$;


--
-- Name: get_system_leases(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_leases(p_system_id text) RETURNS TABLE(id uuid, building_id uuid, status text, role text, lessee_name text, lessor_name text, ends_at timestamp with time zone, seconds_left integer, hours integer, price integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.id, l.building_id, lease_effective_status(l),
         case when l.lessor_id = auth.uid() then 'lessor' else 'lessee' end,
         (select nickname from profiles where id = l.lessee_id),
         (select nickname from profiles where id = l.lessor_id),
         l.ends_at,
         case when lease_effective_status(l) = 'active'
              then greatest(0, ceil(extract(epoch from l.ends_at - now())))::integer
              when lease_effective_status(l) = 'offered'
              then greatest(0, ceil(extract(epoch from l.offer_expires_at - now())))::integer
              else 0 end,
         l.hours, l.price
  from production_leases l
  where l.system_id = p_system_id and l.status in ('offered','active')
    and (l.lessor_id = auth.uid() or l.lessee_id = auth.uid())
    and lease_effective_status(l) in ('offered','active');
$$;


--
-- Name: get_system_resources(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_resources(p_system_id text) RETURNS TABLE(resource text, name text, kind text, role text, color text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select r.id, r.name, r.kind,
         case when s.primary_resource = r.id then 'primary' else 'secondary' end,
         r.color
  from systems s
  join resources r on r.id in (s.primary_resource, s.secondary_resource)
  where s.id = p_system_id
  order by case when s.primary_resource = r.id then 0 else 1 end;
$$;


--
-- Name: get_system_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_summary(p_system_id text) RETURNS TABLE(kind text, name text, faction text, captured boolean, building_state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'building', bt.name, b.faction,
         b.faction is distinct from s.faction,
         case
           when b.completes_at is not null and b.completes_at > now() then 'строится'
           when b.faction is distinct from s.faction then 'трофей, не работает'
           else 'работает'
         end
  from buildings b
  join building_types bt on bt.id = b.building_type_id
  join systems s on s.id = b.system_id
  where b.system_id = p_system_id
    and s.faction = (select pf.faction from profiles pf where pf.id = auth.uid())

  union all

  select 'station', coalesce(ss.name, 'Орбитальная станция'), ss.faction,
         ss.faction is distinct from s.faction,
         case
           when ss.completes_at is not null and ss.completes_at > now() then 'строится'
           when ss.faction is distinct from s.faction then 'трофей, не работает'
           else 'работает'
         end
  from space_stations ss
  join systems s on s.id = ss.system_id
  where ss.system_id = p_system_id
    and s.faction = (select pf.faction from profiles pf where pf.id = auth.uid())

  order by 1, 2;
$$;


--
-- Name: get_trade_post_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trade_post_info() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when auth.uid() is null then null else
    jsonb_build_object('pct', game_setting_int('trade_post_pct', 60), 'mod', ge_trade_mod()) end;
$$;


--
-- Name: get_trade_prices(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trade_prices(p_system_id text) RETURNS TABLE(resource text, name text, color text, amount integer, price integer, total integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select r.id, r.name, r.color,
         coalesce(ps.amount, 0),
         trade_post_price(r.id),
         coalesce(ps.amount, 0) * trade_post_price(r.id)
  from resources r
  left join planet_stock ps on ps.resource = r.id and ps.system_id = p_system_id
  where exists (select 1 from system_control sc
                where sc.system_id = p_system_id and sc.controller_user_id = auth.uid())
  order by r.sort_order;
$$;


--
-- Name: get_transfer_partners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_transfer_partners() RETURNS TABLE(user_id uuid, nickname text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.id, p.nickname
  from profiles p
  where p.faction = (select faction from profiles where id = auth.uid())
    and p.id <> auth.uid()
    and p.nickname is not null
  order by lower(p.nickname);
$$;


--
-- Name: get_transferable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_transferable() RETURNS TABLE(kind text, item_id uuid, system_id text, system_name text, is_deep_space boolean, snapshot jsonb, block text, offered boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'ship'::text, s.id, s.system_id, sy.name, sy.is_deep_space,
         transfer_snapshot('ship', s.id), transfer_block_ship(s.id),
         exists (select 1 from troop_transfer_items ti
                 join troop_transfers tt on tt.id = ti.transfer_id
                 where ti.item_id = s.id and tt.status = 'pending' and tt.expires_at > now())
  from ships s join systems sy on sy.id = s.system_id
  where s.owner_user_id = auth.uid() and s.carrier_ship_id is null
  union all
  select 'unit', u.id, u.system_id, sy.name, sy.is_deep_space,
         transfer_snapshot('unit', u.id), transfer_block_unit(u.id),
         exists (select 1 from troop_transfer_items ti
                 join troop_transfers tt on tt.id = ti.transfer_id
                 where ti.item_id = u.id and tt.status = 'pending' and tt.expires_at > now())
  from unit_positions u join systems sy on sy.id = u.system_id
  where u.owner_user_id = auth.uid() and u.x is not null;
$$;


--
-- Name: get_tutorial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tutorial() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); v_faction text; st record; cur record;
  v_steps jsonb; v_total integer; v_leader boolean := false; v_lead jsonb := '{}'::jsonb;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_faction from profiles where id = v_me;
  if v_faction is null then return jsonb_build_object('status', 'no_faction'); end if;

  insert into tutorial_state (user_id) values (v_me) on conflict (user_id) do nothing;
  perform tutorial_eval(v_me);
  select * into st from tutorial_state where user_id = v_me;
  select count(*) into v_total from tutorial_steps;

  select jsonb_agg(jsonb_build_object(
           'ord', t.ord, 'chapter', t.chapter, 'chapter_title', t.chapter_title,
           'title', tutorial_fill(t.title, v_faction),
           'reward_credits', t.reward_credits,
           'reward_label', tutorial_fill(t.reward_label, v_faction),
           'state', case when st.status = 'finished' or t.ord < st.step_ord then 'done'
                         when t.ord = st.step_ord then 'current' else 'locked' end)
         order by t.ord)
    into v_steps from tutorial_steps t;

  select * into cur from tutorial_steps where ord = st.step_ord;

  -- Лидер не может просить планету сам у себя: он выдаёт её себе
  -- в панели управления фракции. Тексты шагов про планету — под него.
  v_leader := exists (select 1 from faction_leadership where leader_user_id = v_me);
  if v_leader and cur.id in ('request', 'planet') then
    v_lead := jsonb_build_object(
      'leader', true,
      'goal', 'Назначь себя управляющим планеты в панели управления фракции',
      'hint', 'Кнопка фракции внизу → «Панель управления фракции» → у нужной планеты выбери себя',
      'text', case v_faction when 'republic' then
        'Ты лидер фракции, командир: планеты раздаёшь ты — и себе тоже. Открой панель управления фракции и назначь себя управляющим любой нашей планеты. Запросы остальных игроков будут приходить в уведомления и в окно фракции — не заставляй их ждать.'
      else
        'Вы назначены лидером фракции. Распределение планет — ваша прерогатива, включая собственное назначение. Откройте панель управления фракции и назначьте себя управляющим одной из планет Конфедерации. Запросы других командиров поступают в уведомления и окно фракции. Промедление снижает эффективность фронта.'
      end);
  end if;

  return jsonb_build_object(
    'status', st.status,
    'faction', v_faction,
    'total', v_total,
    'step_ord', st.step_ord,
    'step_done', st.step_done,
    'step_since', st.step_since,
    'mentor', jsonb_build_object(
      'name', case v_faction when 'republic' then 'Коммандер Рэйн' else 'Тактик Т-47' end,
      'role', case v_faction when 'republic' then 'наставник Великой армии' else 'тактический дроид Конфедерации' end,
      'image', case v_faction when 'republic' then 'assets/ui/mentor_republic.jpg' else 'assets/ui/mentor_cis.jpg' end,
      'fallback', case v_faction when 'republic' then 'assets/units/rep_officer.jpg' else 'assets/units/cis_bx.jpg' end),
    'current', case when st.status = 'finished' then null else jsonb_build_object(
      'ord', cur.ord, 'id', cur.id, 'chapter', cur.chapter, 'chapter_title', cur.chapter_title,
      'title', tutorial_fill(cur.title, v_faction),
      'goal', tutorial_fill(cur.goal, v_faction),
      'hint', tutorial_fill(cur.hint, v_faction),
      'text', tutorial_fill(case v_faction when 'republic' then cur.mentor_republic else cur.mentor_cis end, v_faction),
      'kind', cur.check_kind, 'key', cur.check_key,
      'reward_credits', cur.reward_credits,
      'reward_label', tutorial_fill(cur.reward_label, v_faction)) || v_lead end,
    'focus', case when st.status = 'finished' then null
                  else tutorial_focus(v_me, v_faction, st.meta) end,
    'steps', v_steps);
end;
$$;


--
-- Name: grant_supply_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_supply_access(p_grantee_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_fac text; v_gfac text; g record; v_found boolean; v_id uuid; v_name text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_grantee_user_id is null or p_grantee_user_id = v_user then raise exception 'Себе доверять не нужно'; end if;
  select faction, nickname into v_fac, v_name from profiles where id = v_user;
  select faction into v_gfac from profiles where id = p_grantee_user_id;
  if v_gfac is null then raise exception 'Игрок не найден'; end if;
  if v_gfac is distinct from v_fac then raise exception 'Доверять можно только своей стороне'; end if;

  select * into g from supply_grants x
   where x.owner_user_id = v_user and x.grantee_user_id = p_grantee_user_id
     and x.status in ('pending', 'active')
   for update;
  v_found := found;
  if v_found and g.status = 'active' then return g.id; end if;

  if v_found then
    update supply_grants set status = 'active', decided_at = now() where id = g.id;
    v_id := g.id;
  else
    insert into supply_grants (owner_user_id, grantee_user_id, status, requested_by, decided_at)
    values (v_user, p_grantee_user_id, 'active', v_user, now())
    returning id into v_id;
  end if;

  perform log_event(p_grantee_user_id, v_fac, null, 'supply_access_granted', v_name, 1, 'private',
                    jsonb_build_object('grant_id', v_id, 'from_user', v_user));
  return v_id;
end $$;


--
-- Name: ground_box_free_for(text, integer, integer, integer, integer, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ground_box_free_for(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer, p_ignore_unit uuid, p_faction text, p_vehicle boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_x >= 0 and p_y >= 0
    and p_x + p_w <= game_setting_int('ground_grid_cells', 144)
    and p_y + p_h <= game_setting_int('ground_grid_cells', 144)
    and planet_cell_ok(p_system_id, p_x, p_y, p_w, p_h, case when p_vehicle then 'track' else 'foot' end)
    and not exists (
      select 1 from unit_positions u
      join unit_types t on t.id = u.unit_type
      where u.system_id = p_system_id and u.layer = 'ground' and u.x is not null
        and (p_ignore_unit is null or u.id <> p_ignore_unit)
        and p_x < u.x + t.width_cells and p_x + p_w > u.x
        and p_y < u.y + t.height_cells and p_y + p_h > u.y
    )
    and not exists (
      select 1 from field_structures s join structure_types st on st.id = s.type_id
      where s.system_id = p_system_id
        and p_x < s.x + s.w and p_x + p_w > s.x
        and p_y < s.y + s.h and p_y + p_h > s.y
        and (not st.enterable
             or s.faction is distinct from p_faction
             or (st.infantry_only and p_vehicle))
    )
    and not ground_box_on_building(p_system_id, p_x, p_y, p_w, p_h)
    and ground_site_at(p_system_id, p_x, p_y, p_w, p_h) is null;
$$;


--
-- Name: ground_box_on_building(text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ground_box_on_building(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from buildings b
    join planet_slots ps on ps.system_id = b.system_id and ps.slot_index = b.slot_index
    where b.system_id = p_system_id
      and p_x < ps.x + 6 and p_x + p_w > ps.x
      and p_y < ps.y + 6 and p_y + p_h > ps.y
  );
$$;


--
-- Name: ground_site_at(text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ground_site_at(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when exists (select 1 from settlement_box() sb
                 where p_x < sb.x + sb.size and p_x + p_w > sb.x
                   and p_y < sb.y + sb.size and p_y + p_h > sb.y) then 'settlement'
    when exists (select 1 from planet_slots ps
                 where ps.system_id = p_system_id
                   and p_x < ps.x + 6 and p_x + p_w > ps.x
                   and p_y < ps.y + 6 and p_y + p_h > ps.y) then 'plot'
  end;
$$;


