--
-- Name: hero_apply_passives(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hero_apply_passives(p_hero_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  r record;
  v_hp int := 0; v_dmg int := 0; v_vis int := 0;
  v_mv int := 0; v_rng int := 0; v_acc int := 0; v_ev int := 0;
begin
  for r in
    select a.effect_kind as k1, a.effect_value as v1,
           a.effect2_kind as k2, a.effect2_value as v2
    from hero_learned hl join hero_abilities a on a.id = hl.ability_id
    where hl.hero_id = p_hero_id and a.kind = 'passive'
  loop
    for i in 1..2 loop
      declare
        k text := case i when 1 then r.k1 else r.k2 end;
        v int := coalesce(case i when 1 then r.v1 else r.v2 end, 0);
      begin
        if    k = 'hp'       then v_hp  := v_hp  + v;
        elsif k = 'damage'   then v_dmg := v_dmg + v;
        elsif k = 'vision'   then v_vis := v_vis + v;
        elsif k = 'move'     then v_mv  := v_mv  + v;
        elsif k = 'range'    then v_rng := v_rng + v;
        elsif k = 'accuracy' then v_acc := v_acc + v;
        elsif k = 'evasion'  then v_ev  := v_ev  + v;
        end if;
      end;
    end loop;
  end loop;

  update unit_positions u set
    bonus_hp = v_hp, bonus_damage = v_dmg, bonus_vision = v_vis,
    bonus_move = v_mv, bonus_range = v_rng,
    bonus_accuracy = v_acc, bonus_evasion = v_ev,
    hp = least(u.hp, t.max_hp + v_hp)
  from unit_types t
  where u.hero_id = p_hero_id and t.id = u.unit_type;
end;
$$;


--
-- Name: hero_hire_check(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hero_hire_check(p_building_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_faction text; v_credits integer;
  v_system text; v_completes timestamptz; v_btype_code text;
  v_bld_faction text; v_sys_faction text; v_slots integer;
  v_type record; v_busy record; v_free integer;
  k text; v_need integer; v_have integer; v_rname text;
begin
  if v_user is null then return 'Не авторизован'; end if;

  select b.system_id, b.completes_at, bt.code, b.faction, b.production_slots
    into v_system, v_completes, v_btype_code, v_bld_faction, v_slots
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.id = p_building_id;
  if v_system is null then return 'Постройка не найдена'; end if;

  begin
    perform assert_planet_operational(v_system);
  exception when others then perform err_db('hero_hire_check', sqlstate, sqlerrm, false);
    return sqlerrm;
  end;

  if production_access_error(v_user, v_system, p_building_id) is not null then
    return production_access_error(v_user, v_system, p_building_id);
  end if;

  select faction into v_sys_faction from systems where id = v_system;
  if v_bld_faction is distinct from v_sys_faction then
    return 'Трофейная постройка не работает на нового хозяина — её можно только снести';
  end if;
  if v_completes is not null and v_completes > now() then
    return 'Постройка ещё не достроена';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user;
  select * into v_type from unit_types
  where produced_by = v_btype_code and is_hero and faction = v_faction limit 1;
  if not found then return 'Эта постройка не готовит одарённых'; end if;

  if building_line_used(p_building_id) >= coalesce(v_slots, 1) then
    select uo.completes_at, coalesce(uo.hero_name, ut.name) as name into v_busy
    from unit_orders uo left join unit_types ut on ut.id = uo.unit_type
    where uo.building_id = p_building_id and not uo.delivered
    order by uo.completes_at limit 1;
    if found then
      return format('Обряд уже идёт: %s будет готов через %s с', v_busy.name,
                    greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer));
    end if;
    return 'Постройка занята: дождись окончания работ';
  end if;

  v_free := spawn_space(v_system, p_building_id);
  if v_free < 1 then return 'У постройки нет места'; end if;

  if v_credits < v_type.cost then
    return format('Недостаточно кредитов: нужно %s', v_type.cost);
  end if;

  for k in select jsonb_object_keys(coalesce(v_type.cost_resources, '{}'::jsonb)) loop
    v_need := coalesce((v_type.cost_resources ->> k)::integer, 0);
    continue when v_need <= 0;
    select amount into v_have from planet_stock where system_id = v_system and resource = k;
    if coalesce(v_have, 0) < v_need then
      select name into v_rname from resources where id = k;
      return format('На планете не хватает: %s (нужно %s, есть %s)',
                    coalesce(v_rname, k), v_need, coalesce(v_have, 0));
    end if;
  end loop;

  return null;
end;
$$;


--
-- Name: hero_strike(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hero_strike(p_hero_unit uuid, p_target uuid, p_damage integer) RETURNS TABLE(damage integer, killed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare t record; tt record; v_hp integer; v_dmg integer; v_dead boolean := false;
begin
  select * into t from unit_positions where id = p_target for update;
  select * into tt from unit_types where id = t.unit_type;

  v_dmg := greatest(1, p_damage);
  v_dmg := covered_damage(p_target, v_dmg);

  v_hp := greatest(0, t.hp - v_dmg);
  update unit_positions set hp = v_hp where id = p_target;

  if v_hp <= 0 then
    v_dead := true;
    perform log_event(t.owner_user_id, t.faction, t.system_id,
                      'unit_killed', tt.name, 1, 'private', jsonb_build_object('x', t.x, 'y', t.y));
    perform record_hero_kill(p_hero_unit, t.unit_type, t.faction,
                             t.owner_user_id, t.system_id);
    delete from unit_positions where id = p_target;
  end if;

  return query select v_dmg, v_dead;
end;
$$;


--
-- Name: hire_hero(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_hero(p_building_id uuid, p_name text, p_target_x integer DEFAULT NULL::integer, p_target_y integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_user uuid := auth.uid();
  v_faction text; v_credits integer;
  v_system text; v_completes timestamptz; v_btype_code text;
  v_bld_faction text; v_sys_faction text;
  v_slots integer; v_speed integer; v_active integer;
  v_type record; v_name text; v_portrait text;
  v_seconds integer; v_free integer; v_busy record;
  v_hero uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  v_name := btrim(coalesce(p_name, ''));
  if length(v_name) < 2 then raise exception 'Кличка слишком короткая'; end if;
  if length(v_name) > 24 then raise exception 'Кличка длиннее 24 символов'; end if;
  if v_name !~ '^[[:alnum:] ''-]+$' then
    raise exception 'В кличке можно использовать только буквы, цифры, пробел, дефис и апостроф';
  end if;

  select b.system_id, b.completes_at, bt.code, b.faction,
         b.production_slots, b.speed_bonus_pct
    into v_system, v_completes, v_btype_code, v_bld_faction, v_slots, v_speed
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.id = p_building_id
  for update of b;

  if v_system is null then raise exception 'Постройка не найдена'; end if;

  perform assert_planet_operational(v_system);

  perform assert_production_access(v_user, v_system, p_building_id);

  select faction into v_sys_faction from systems where id = v_system;
  if v_bld_faction is distinct from v_sys_faction then
    raise exception 'Трофейная постройка не работает на нового хозяина — её можно только снести';
  end if;

  if v_completes is not null and v_completes > now() then
    raise exception 'Постройка ещё не достроена';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user;

  -- Тип героя определяется самой постройкой: храм даёт джедая,
  -- святилище даст ситха, когда тот появится. Одна функция на обе стороны.
  select * into v_type from unit_types
  where produced_by = v_btype_code and is_hero and faction = v_faction
  limit 1;

  if not found then
    raise exception 'Эта постройка не готовит одарённых';
  end if;

  v_active := building_line_used(p_building_id);

  if v_active >= coalesce(v_slots, 1) then
    select uo.completes_at, coalesce(uo.hero_name, ut.name) as name into v_busy
    from unit_orders uo
    left join unit_types ut on ut.id = uo.unit_type
    where uo.building_id = p_building_id and not uo.delivered
    order by uo.completes_at limit 1;

    raise exception 'Обряд уже идёт: % будет готов через % с',
      v_busy.name,
      greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer);
  end if;

  if exists (select 1 from heroes
             where owner_user_id = v_user and died_at is null
               and lower(name) = lower(v_name)) then
    raise exception 'Кличка % уже занята', v_name;
  end if;

  if p_target_x is not null and p_target_y is not null then
    if not is_deploy_cell_free(v_system, p_target_x, p_target_y) then
      raise exception 'Эта клетка занята или вне зоны высадки';
    end if;
  end if;

  -- Наземка 2.0: герой выходит у самой постройки; зоны высадки — запас
  v_free := spawn_space(v_system, p_building_id);
  if v_free < 1 then
    raise exception 'У постройки нет места';
  end if;

  if v_credits < v_type.cost then
    raise exception 'Недостаточно кредитов: нужно %', v_type.cost;
  end if;

  -- Портрет тянем один раз и запоминаем в личности героя
  select image into v_portrait from hero_portraits
  where faction = v_faction order by random() limit 1;

  if v_portrait is null then v_portrait := v_type.image; end if;

  insert into heroes (owner_user_id, faction, unit_type, name, portrait, home_system_id)
  values (v_user, v_faction, v_type.id, v_name, v_portrait, v_system)
  returning id into v_hero;

  -- В отличие от рядовых юнитов, время берём из самого типа,
  -- а не из общей настройки unit_build_seconds
  v_seconds := greatest(5, round(v_type.build_seconds * (100 - coalesce(v_speed, 0)) / 100.0)::integer);

  insert into unit_orders (system_id, building_id, unit_type, owner_user_id, faction,
                           quantity, completes_at, target_x, target_y,
                           hero_id, hero_name)
  values (v_system, p_building_id, v_type.id, v_user, v_faction, 1,
          now() + make_interval(secs => v_seconds),
          p_target_x, p_target_y, v_hero, v_name);

  perform take_build_resources(v_system, v_type.cost_resources, 1);

  update profiles set credits = credits - v_type.cost where id = v_user;

  perform log_event(v_user, v_faction, v_system, 'hero_hired',
                    v_name, 1, 'private',
                    jsonb_build_object('unit_type', v_type.id));

  return v_hero;
end;
$_$;


--
-- Name: hyperspace_band_at(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hyperspace_band_at(p_y integer, p_h integer DEFAULT 1) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_y < game_setting_int('hyperspace_zone_height', 14) then 'top'
    when p_y + p_h > game_setting_int('space_grid_cells', 150)
                     - game_setting_int('hyperspace_zone_height', 14) then 'bottom'
    else null
  end;
$$;


--
-- Name: hyperspace_facing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hyperspace_facing(p_side text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_side = 'top' then 180 else 0 end;
$$;


--
-- Name: hyperspace_side(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hyperspace_side(p_system_id text, p_faction text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_faction is null then null
    when coalesce((select faction from systems where id = p_system_id), 'neutral') = 'neutral'
      then case when p_faction = 'republic' then 'top' else 'bottom' end
    when (select faction from systems where id = p_system_id) = p_faction then 'top'
    else 'bottom'
  end;
$$;


--
-- Name: init_ship_shields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.init_ship_shields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_max integer;
begin
  select max_shield into v_max from ship_types where id = new.ship_type;
  v_max := coalesce(v_max, 0);
  new.shield_fore       := coalesce(new.shield_fore, v_max);
  new.shield_aft        := coalesce(new.shield_aft, v_max);
  new.shield_port       := coalesce(new.shield_port, v_max);
  new.shield_starboard  := coalesce(new.shield_starboard, v_max);
  return new;
end;
$$;


--
-- Name: interception_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interception_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare i record; tgt record; sh record;
begin
  for i in
    select * from interceptions where status = 'pending' and resolves_at <= now()
  loop
    -- Досаживаем перехватчика в пустоту, если крон перелётов не успел
    perform finish_commander_move(i.hunter_commander);

    select * into tgt from commanders where id = i.target_commander;

    if tgt.moving_to is null or tgt.arrives_at is null or tgt.arrives_at <= now() then
      update interceptions set status = 'missed' where id = i.id;

      perform log_event(i.hunter_user, null, i.lane_system, 'interception_missed',
                        null, 1, 'private', null);
      continue;
    end if;

    -- Вырываем цель из гиперпространства
    for sh in
      select id from ships
      where commander_id = tgt.id and system_id = tgt.moving_from
      order by id
    loop
      perform place_ship_in_hyperspace(sh.id, i.lane_system);
    end loop;

    update commanders
    set current_system = i.lane_system, route = null,
        moving_from = null, moving_to = null,
        departed_at = null, arrives_at = null
    where id = tgt.id;

    update interceptions set status = 'engaged' where id = i.id;

    perform log_event(i.hunter_user, null, i.lane_system, 'interception_engaged',
                      tgt.name, 1, 'private', null);
    perform log_event(i.target_user, tgt.faction, i.lane_system, 'fleet_intercepted',
                      tgt.name, 1, 'private', null);
  end loop;
end;
$$;


--
-- Name: is_box_in_attack_zone(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_box_in_attack_zone(p_y integer, p_h integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select p_y >= game_setting_int('ground_grid_cells', 144)
                - game_setting_int('ground_attack_zone_height', 4)
     and p_y + p_h <= game_setting_int('ground_grid_cells', 144);
$$;


--
-- Name: is_box_in_deploy_zone(text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_box_in_deploy_zone(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1 from deploy_zones z
    where z.system_id = p_system_id
      and p_x >= z.x and p_x + p_w <= z.x + z.size
      and p_y >= z.y and p_y + p_h <= z.y + z.size
  );
$$;


--
-- Name: is_capture_active(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_capture_active(p_system_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
    select 1 from system_capture
    where system_id = p_system_id and progress > 0 and status <> 'distribution'
  );
$$;


--
-- Name: is_deploy_cell_free(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_deploy_cell_free(p_system_id text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select case when not is_my_faction_system(p_system_id) then false
  else
    exists (
      select 1 from deploy_zones z
      where z.system_id = p_system_id
        and p_x >= z.x and p_x < z.x + z.size
        and p_y >= z.y and p_y < z.y + z.size
    )
    and is_ground_box_free(p_system_id, p_x, p_y, 1, 1, null)
  end;
$$;


--
-- Name: is_faction_leader(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_faction_leader(p_user uuid, p_faction text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from faction_leadership
                 where faction = p_faction and leader_user_id = p_user);
$$;


--
-- Name: is_ground_box_free(text, integer, integer, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_ground_box_free(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer, p_ignore_unit uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_x is not null and p_y is not null and p_w is not null and p_h is not null
    and p_x >= 0 and p_y >= 0
    and p_x + p_w <= game_setting_int('ground_grid_cells', 144)
    and p_y + p_h <= game_setting_int('ground_grid_cells', 144)
    and planet_cell_ok(p_system_id, p_x, p_y, p_w, p_h, case when p_w >= 2 then 'track' else 'foot' end)
    and not exists (
      select 1 from unit_positions u
      join unit_types t on t.id = u.unit_type
      where u.system_id = p_system_id
        and u.layer = 'ground'
        and u.x is not null
        and (p_ignore_unit is null or u.id <> p_ignore_unit)
        and p_x < u.x + t.width_cells and p_x + p_w > u.x
        and p_y < u.y + t.height_cells and p_y + p_h > u.y
    )
    and not exists (
      select 1 from field_structures s
      where s.system_id = p_system_id
        and p_x < s.x + s.w and p_x + p_w > s.x
        and p_y < s.y + s.h and p_y + p_h > s.y
    )
    and not ground_box_on_building(p_system_id, p_x, p_y, p_w, p_h)
    and ground_site_at(p_system_id, p_x, p_y, p_w, p_h) is null;
$$;


--
-- Name: is_in_deploy_zone(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_deploy_zone(p_system_id text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1 from deploy_zones z
    where z.system_id = p_system_id
      and p_x >= z.x and p_x < z.x + z.size
      and p_y >= z.y and p_y < z.y + z.size
  );
$$;


--
-- Name: is_in_ground_attack_zone(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_ground_attack_zone(p_y integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select p_y >= game_setting_int('ground_grid_cells', 144)
                - game_setting_int('ground_attack_zone_height', 4)
     and p_y < game_setting_int('ground_grid_cells', 144);
$$;


--
-- Name: is_in_hyperspace_zone(integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_hyperspace_zone(p_y integer, p_h integer, p_side text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select case p_side
    when 'top' then p_y >= 0
      and p_y + p_h <= game_setting_int('hyperspace_zone_height', 14)
    when 'bottom' then
      p_y >= game_setting_int('space_grid_cells', 150)
             - game_setting_int('hyperspace_zone_height', 14)
      and p_y + p_h <= game_setting_int('space_grid_cells', 150)
    else false
  end;
$$;


--
-- Name: is_in_orbital_drop(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_orbital_drop(p_x integer, p_y integer, p_w integer, p_h integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select z.idx
  from orbital_drop_zones() z
  where p_x >= z.x and p_x + p_w <= z.x + z.size
    and p_y >= z.y and p_y + p_h <= z.y + z.size
  limit 1;
$$;


--
-- Name: is_in_settlement_zone(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_settlement_zone(p_x integer, p_y integer) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare c integer; s integer; m integer;
begin
  select (coalesce(max(case when key = 'ground_grid_cells' then value end)::integer, 144)
        - coalesce(max(case when key = 'ground_attack_zone_height' then value end)::integer, 4)
        - coalesce(max(case when key = 'settlement_size' then value end)::integer, 6)) / 2,
         coalesce(max(case when key = 'settlement_size' then value end)::integer, 6),
         coalesce(max(case when key = 'settlement_zone_margin' then value end)::integer, 2)
    into c, s, m
  from game_settings
  where key in ('ground_grid_cells', 'ground_attack_zone_height', 'settlement_size', 'settlement_zone_margin');
  -- Пустые координаты — не в зоне (как и прежде: exists давал false)
  return coalesce(p_x >= c - m and p_x < c + s + m and p_y >= c - m and p_y < c + s + m, false);
end $$;


--
-- Name: is_my_faction_system(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_my_faction_system(p_system_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1 from systems s
    join profiles p on p.faction = s.faction
    where s.id = p_system_id and p.id = auth.uid()
  );
$$;


--
-- Name: is_ship_at_dock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_ship_at_dock(p_ship_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select coalesce((
    select greatest(
             greatest(sl.x - s.x, s.x - (sl.x + sl.size - 1), 0),
             greatest(sl.y - s.y, s.y - (sl.y + sl.size - 1), 0))
           <= game_setting_int('dock_gap_cells', 2)
    from ships s
    join ship_types t on t.id = s.ship_type
    join station_slots sl on sl.system_id = s.system_id
    where s.id = p_ship_id and not s.in_transit and s.x is not null
  ), false);
$$;


--
-- Name: is_ship_box_free(text, integer, integer, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_ship_box_free(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer, p_ignore_ship uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select p_x >= 0 and p_y >= 0
    and p_x + p_w <= game_setting_int('space_grid_cells', 150)
    and p_y + p_h <= game_setting_int('space_grid_cells', 150)
    and not exists (
      select 1 from ships s
      join ship_types t on t.id = s.ship_type
      where s.system_id = p_system_id
        and not s.in_transit
        and (p_ignore_ship is null or s.id <> p_ignore_ship)
        and p_x < s.x + ship_box_w(t.width_cells, t.height_cells, s.facing)
        and p_x + p_w > s.x
        and p_y < s.y + ship_box_h(t.width_cells, t.height_cells, s.facing)
        and p_y + p_h > s.y
    )
    and not exists (
      select 1 from station_slots z
      where z.system_id = p_system_id
        and p_x < z.x + z.size and p_x + p_w > z.x
        and p_y < z.y + z.size and p_y + p_h > z.y
    );
$$;


--
-- Name: is_ship_space_free(text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_ship_space_free(p_system_id text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select is_ship_box_free(p_system_id, p_x, p_y, p_w, p_h, null);
$$;


--
-- Name: issue_settlement_tasks(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_settlement_tasks(p_system_id text, p_cycle timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_mar uuid;
  v_raid timestamptz := marauder_raid_slot(p_cycle);
  v_gang uuid[];
  v_factories integer; v_medical integer;
  v_pool text[];
  v_pick text;
  i integer;
begin
  -- без управляющего условий нет: довольство падает само (sql/settlement_conditions.sql)
  if not exists (select 1 from system_control c where c.system_id = p_system_id and c.controller_user_id is not null) then
    return;
  end if;
  insert into settlement_tasks (system_id, cycle_start, kind, target)
  values (p_system_id, p_cycle, 'guard', 1 + floor(random() * 5)::integer);

  select count(*) into v_factories
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.system_id = p_system_id and bt.code in ('rep_vehicle', 'cis_vehicle');

  select count(*) into v_medical
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.system_id = p_system_id and bt.code in ('rep_medical', 'cis_repair');

  -- Только то, что имеет смысл на этой планете: просить снести второй
  -- завод там, где он один, значит выдать невыполнимую задачу
  v_pool := array['marauder','donation','festival','orbit','patrol']::text[];
  if v_factories > 1 then v_pool := array_append(v_pool, 'factories'); end if;
  -- Налёт бывает только днём: окно этих суток уже прошло — мародёров не выдаём
  if v_raid is null then v_pool := array_remove(v_pool, 'marauder'); end if;

  for i in 1..2 loop
    exit when coalesce(array_length(v_pool, 1), 0) = 0;

    v_pick := v_pool[1 + floor(random() * array_length(v_pool, 1))::integer];
    v_pool := array_remove(v_pool, v_pick);

    if v_pick = 'marauder' then
      -- Банда приходит днём: утром разведка называет время, к нему отряд и появится
      -- (marauder_raid_tick). Сколько их будет, решается в момент налёта.
      insert into settlement_tasks (system_id, cycle_start, kind, target, payload)
      values (p_system_id, p_cycle, 'marauder', 1,
              jsonb_build_object('stage', 'scouted', 'raid_at', v_raid,
                                 'raid_ends', v_raid + make_interval(hours => game_setting_int('marauder_raid_hours', 3))));
      perform marauder_notify(p_system_id, 'marauder_scouted',
                              'Разведка: банда подойдёт около ' || marauder_hhmm(v_raid), 1,
                              jsonb_build_object('raid_at', v_raid), false);

    elsif v_pick = 'donation' then
      insert into settlement_tasks (system_id, cycle_start, kind, target)
      values (p_system_id, p_cycle, 'donation', 50 + floor(random() * 4)::integer * 50);

    elsif v_pick = 'festival' then
      insert into settlement_tasks (system_id, cycle_start, kind, target)
      values (p_system_id, p_cycle, 'festival', 200);

    else
      insert into settlement_tasks (system_id, cycle_start, kind, target)
      values (p_system_id, p_cycle, v_pick, 1);
    end if;
  end loop;
end;
$$;


--
-- Name: jam_scout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jam_scout(p_unit_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare u record; s record;
begin
  select up.id, up.system_id, up.owner_user_id, up.faction, up.x, up.y, t.name, t.width_cells w, t.height_cells h
    into u
  from unit_positions up join unit_types t on t.id = up.unit_type
  where up.id = p_unit_id and up.layer = 'ground' and up.x is not null and up.hp > 0 and t.is_scout;
  if not found then return false; end if;

  select fs.owner_user_id, fs.faction into s
  from field_structures fs join structure_types st on st.id = fs.type_id
  join systems sy on sy.id = fs.system_id
  where fs.system_id = u.system_id and st.kind = 'jammer' and fs.completes_at <= now()
    and sy.faction = fs.faction and fs.faction is distinct from u.faction
    and box_gap(u.x, u.y, u.w, u.h, fs.x, fs.y, fs.w, fs.h) <= st.radius
  limit 1;
  if not found then return false; end if;

  delete from unit_positions where id = u.id;
  perform log_event(u.owner_user_id, u.faction, u.system_id, 'unit_killed', u.name, 1, 'private',
                    jsonb_build_object('jammed', true, 'x', u.x, 'y', u.y));
  perform log_event(s.owner_user_id, s.faction, u.system_id, 'scout_jammed', u.name, 1, 'private',
                    jsonb_build_object('x', u.x, 'y', u.y));
  return true;
end;
$$;


--
-- Name: jettison_commander_cargo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jettison_commander_cargo(p_commander_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_user uuid := auth.uid(); cm record; v_fac text; g record; v_total int := 0;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select * into cm from commanders where id = p_commander_id for update;
  if not found or cm.user_id <> v_user then raise exception 'Это не твой командир'; end if;
  if exists (select 1 from supply_routes x where x.commander_id = cm.id and x.status = 'active') then
    raise exception 'Командир на рейсе снабжения — сначала поставь рейс на паузу или заверши его';
  end if;
  select faction into v_fac from profiles where id = v_user;
  for g in
    select rc.resource, sum(rc.amount)::int as amt, min(s.system_id) as sys
    from ship_resource_cargo rc join ships s on s.id = rc.ship_id
    where s.commander_id = cm.id and s.owner_user_id = v_user
    group by rc.resource
  loop
    v_total := v_total + g.amt;
    perform log_event(v_user, v_fac, g.sys, 'cargo_lost',
      coalesce((select name from resources where id = g.resource), g.resource) || ' — выброшено из трюма', g.amt, 'private',
      jsonb_build_object('layer', 'space'));
  end loop;
  execute 'del' || 'ete from ship_resource_cargo rc using ships s where s.id = rc.ship_id and s.commander_id = $1 and s.owner_user_id = $2'
    using cm.id, v_user;
  return v_total;
end $_$;


--
-- Name: land_fighter(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.land_fighter(p_fighter_id uuid, p_x integer, p_y integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  f record; c record; ct record; ut record;
  v_sys_faction text; v_attacking boolean; v_new uuid;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into f from ships where id = p_fighter_id for update;
  if not found then raise exception 'Истребитель не найден'; end if;
  if f.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if f.carrier_ship_id is null then raise exception 'Садиться можно только из ангара'; end if;

  select * into c from ships where id = f.carrier_ship_id;
  if c.in_transit then raise exception 'Носитель в гиперпространстве'; end if;
  select * into ct from ship_types where id = c.ship_type;

  if is_in_orbital_drop(c.x, c.y,
       ship_box_w(ct.width_cells, ct.height_cells, c.facing),
       ship_box_h(ct.width_cells, ct.height_cells, c.facing)) is null then
    raise exception 'Носитель должен целиком стоять в площадке сброса';
  end if;

  select faction into v_sys_faction from systems where id = c.system_id;
  v_attacking := v_sys_faction is distinct from f.faction;

  if p_x < 0 or p_y < 0 or p_x >= v_grid or p_y >= v_grid then
    raise exception 'Клетка вне карты';
  end if;

  if v_attacking then
    if not is_in_ground_attack_zone(p_y) then
      raise exception 'Садиться можно только в полосе вторжения';
    end if;
  else
    if not is_in_deploy_zone(c.system_id, p_x, p_y) then
      raise exception 'Клетка вне зоны высадки';
    end if;
  end if;

  if p_x is null or p_y is null then raise exception 'Клетка вне карты'; end if;
  if not is_ground_box_free(c.system_id, p_x, p_y, 1, 1, null) then
    raise exception 'Клетка занята';
  end if;

  select * into ut from unit_types where id = f.ship_type;
  if not found then raise exception 'Для этого истребителя нет наземного типа'; end if;

  -- Переезд из ships в unit_positions: на грунте он живёт как юнит
  insert into unit_positions (system_id, layer, x, y, owner_user_id,
                              faction, unit_type, quantity, hp)
  values (c.system_id, 'ground', p_x, p_y, v_user, f.faction, f.ship_type, 1, f.hp)
  returning id into v_new;

  delete from ships where id = p_fighter_id;

  return v_new;
end;
$$;


--
-- Name: lane_system(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lane_system(p_a text, p_b text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select id from systems
  where is_deep_space
    and id in ('lane_' || p_a || '_' || p_b, 'lane_' || p_b || '_' || p_a)
  limit 1;
$$;


--
-- Name: last_payout_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.last_payout_at() RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select ((date_trunc('day', (now() at time zone server_tz())
                             - make_interval(hours => game_setting_int('payout_hour', 4)))
           + make_interval(hours => game_setting_int('payout_hour', 4)))
          at time zone server_tz());
$$;


--
-- Name: law_badge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_badge() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::integer from faction_bills b join profiles p on p.id = auth.uid() and p.faction = b.faction
  where b.status = 'voting' and b.vote_ends_at > now()
    and not exists (select 1 from faction_votes v where v.bill_id = b.id and v.user_id = p.id);
$$;


--
-- Name: law_close(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_close(p_bill uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare b faction_bills; v_yes integer; v_no integer; v_need integer; v_title text; v_ok boolean;
begin
  select * into b from faction_bills where id = p_bill for update;
  if not found or b.status <> 'voting' then return null; end if;
  select count(*) filter (where yes), count(*) filter (where not yes) into v_yes, v_no from faction_votes where bill_id = b.id;
  v_need := law_quorum(b.faction);
  v_ok := v_yes > v_no and v_yes + v_no >= v_need;
  select title into v_title from faction_laws where id = b.law_id;
  if v_ok then
    update faction_bills set status = 'active', yes = v_yes, no = v_no, need = v_need, closed_at = now(),
           starts_at = now(), ends_at = now() + make_interval(days => event_setting_int('law_days', 7))
     where id = b.id;
    perform law_enact(b.id);
    perform law_notify(b.faction, b.proposed_by, 'law_passed', v_title, jsonb_build_object('bill', b.id, 'yes', v_yes, 'no', v_no), null);
    return 'passed';
  end if;
  update faction_bills set status = 'failed', yes = v_yes, no = v_no, need = v_need, closed_at = now() where id = b.id;
  perform law_notify(b.faction, b.proposed_by, 'law_failed', v_title,
    jsonb_build_object('bill', b.id, 'yes', v_yes, 'no', v_no, 'need', v_need, 'quorum', v_yes + v_no < v_need), null);
  return 'failed';
end;
$$;


--
-- Name: law_decree(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_decree(p_law text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; l faction_laws; v_id uuid; v_next timestamptz;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null or not is_faction_leader(v_me, v_fac) then raise exception 'Указ издаёт только лидер фракции'; end if;
  perform pg_advisory_xact_lock(hashtext('faction_laws:' || v_fac));
  perform law_tick();
  select * into l from faction_laws where id = p_law and active;
  if not found or l.faction <> v_fac then raise exception 'Такого закона нет'; end if;
  if l.funds is not null then raise exception 'Денежные законы принимает только голосование'; end if;
  select max(created_at) + make_interval(days => event_setting_int('law_decree_cooldown_days', 7)) into v_next
    from faction_bills where faction = v_fac and mode = 'decree';
  if v_next > now() then raise exception 'Следующий указ — через % ч', ceil(extract(epoch from v_next - now()) / 3600)::integer; end if;
  if exists (select 1 from faction_bills where law_id = l.id and status in ('voting', 'active')) then
    raise exception 'Этот закон уже действует или за него голосуют';
  end if;
  if (select count(*) from faction_bills where faction = v_fac and status in ('voting', 'active')) >= event_setting_int('law_slots', 2) then
    raise exception 'Уже % закона — действующие и на голосовании', event_setting_int('law_slots', 2);
  end if;
  insert into faction_bills (faction, law_id, mode, status, proposed_by, closed_at, starts_at, ends_at)
  values (v_fac, l.id, 'decree', 'active', v_me, now(), now(), now() + make_interval(hours => event_setting_int('law_decree_hours', 24)))
  returning id into v_id;
  perform law_enact(v_id);
  perform law_notify(v_fac, v_me, 'law_decree', l.title, jsonb_build_object('bill', v_id, 'law', l.id), v_me);
  return law_state();
end;
$$;


--
-- Name: law_enact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_enact(p_bill uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare b faction_bills; l faction_laws; e jsonb;
begin
  select * into b from faction_bills where id = p_bill;
  select * into l from faction_laws where id = b.law_id;
  for e in select * from jsonb_array_elements(l.effects) loop
    insert into faction_effects (faction, kind, value, title, source, source_id, starts_at, ends_at)
    values (b.faction, e->>'kind', (e->>'value')::integer, l.title, case when b.mode = 'decree' then 'decree' else 'law' end, b.id, b.starts_at, b.ends_at);
  end loop;
  if l.funds ? 'now' then
    perform treasury_add(b.faction, (l.funds->>'now')::integer, 'law', b.proposed_by, null, null, l.title);
  end if;
end;
$$;


--
-- Name: law_members(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_members(p_faction text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::integer from profiles
  where faction = p_faction and last_seen_at > now() - make_interval(days => event_setting_int('law_active_days', 7));
$$;


--
-- Name: law_notify(text, uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_notify(p_faction text, p_by uuid, p_type text, p_title text, p_meta jsonb, p_skip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare m record;
begin
  perform log_event(p_by, p_faction, null, p_type, p_title, 1, 'faction', p_meta);
  for m in select id from profiles where faction = p_faction and id is distinct from p_skip loop
    perform log_event(m.id, p_faction, null, p_type, p_title, 1, 'private', p_meta);
  end loop;
end;
$$;


--
-- Name: law_propose(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_propose(p_law text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; l faction_laws; v_id uuid; v_retry timestamptz;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null then raise exception 'Нет фракции'; end if;
  if not faction_power(v_me, v_fac, 'laws') then raise exception 'Законы предлагает лидер и те, кому он это поручил'; end if;
  perform pg_advisory_xact_lock(hashtext('faction_laws:' || v_fac));
  perform law_tick();
  select * into l from faction_laws where id = p_law and active;
  if not found or l.faction <> v_fac then raise exception 'Такого закона нет'; end if;
  if exists (select 1 from faction_bills where law_id = l.id and status = 'active') then raise exception 'Этот закон уже действует'; end if;
  if exists (select 1 from faction_bills where law_id = l.id and status = 'voting') then raise exception 'За этот закон уже голосуют'; end if;
  select max(closed_at) + make_interval(hours => event_setting_int('law_retry_hours', 48)) into v_retry
    from faction_bills where law_id = l.id and status = 'failed';
  if v_retry > now() then raise exception 'Закон недавно отклонили — снова можно через % ч', ceil(extract(epoch from v_retry - now()) / 3600)::integer; end if;
  if (select count(*) from faction_bills where faction = v_fac and status in ('voting', 'active')) >= event_setting_int('law_slots', 2) then
    raise exception 'Уже % закона — действующие и на голосовании. Новый — когда один из них закончится', event_setting_int('law_slots', 2);
  end if;
  if l.funds ? 'now' and coalesce((select credits from faction_treasury where faction = v_fac), 0) < 0 then
    raise exception 'Казна в долгу — новый заём не дадут, пока долг не погашен';
  end if;
  insert into faction_bills (faction, law_id, mode, status, proposed_by, vote_ends_at)
  values (v_fac, l.id, 'vote', 'voting', v_me, now() + make_interval(hours => event_setting_int('law_vote_hours', 48)))
  returning id into v_id;
  insert into faction_votes (bill_id, user_id, yes) values (v_id, v_me, true);
  perform law_notify(v_fac, v_me, 'law_proposed', l.title, jsonb_build_object('bill', v_id, 'law', l.id), v_me);
  if law_members(v_fac) <= 1 then perform law_close(v_id); end if;
  return law_state();
end;
$$;


--
-- Name: law_quorum(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_quorum(p_faction text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(1, least(greatest(law_members(p_faction), 1), greatest(2, ceil(law_members(p_faction) / 3.0)::integer)));
$$;


--
-- Name: law_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_state() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_lead boolean; v_last timestamptz; v_used integer;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null then return jsonb_build_object('faction', null); end if;
  perform law_tick();
  v_lead := is_faction_leader(v_me, v_fac);
  select max(created_at) into v_last from faction_bills where faction = v_fac and mode = 'decree';
  select count(*) into v_used from faction_bills where faction = v_fac and status in ('voting', 'active');
  return jsonb_build_object(
    'faction', v_fac, 'now', now(), 'is_leader', v_lead,
    'can_propose', faction_power(v_me, v_fac, 'laws'),
    'decree_at', case when v_last is null then null else v_last + make_interval(days => event_setting_int('law_decree_cooldown_days', 7)) end,
    'slots', event_setting_int('law_slots', 2), 'used', v_used,
    'members', law_members(v_fac), 'quorum', law_quorum(v_fac),
    'vote_hours', event_setting_int('law_vote_hours', 48), 'law_days', event_setting_int('law_days', 7),
    'decree_hours', event_setting_int('law_decree_hours', 24), 'retry_hours', event_setting_int('law_retry_hours', 48),
    'treasury', coalesce((select credits from faction_treasury where faction = v_fac), 0),
    'laws', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'title', l.title, 'text', l.text, 'effects', l.effects, 'funds', l.funds,
               'busy', (select b.status from faction_bills b where b.law_id = l.id and b.status in ('voting', 'active') limit 1),
               'retry_at', (select max(b.closed_at) + make_interval(hours => event_setting_int('law_retry_hours', 48)) from faction_bills b
                            where b.law_id = l.id and b.status = 'failed'
                              and b.closed_at > now() - make_interval(hours => event_setting_int('law_retry_hours', 48))))
             order by l.sort), '[]'::jsonb) from faction_laws l where l.faction = v_fac and l.active),
    'bills', (select coalesce(jsonb_agg(x order by x->>'status' desc, x->>'at'), '[]'::jsonb) from (
       select jsonb_build_object('id', b.id, 'law', b.law_id, 'title', l.title, 'text', l.text, 'effects', l.effects, 'funds', l.funds, 'mode', b.mode, 'status', b.status,
                'by', p.nickname, 'at', b.created_at, 'vote_ends', b.vote_ends_at, 'starts', b.starts_at, 'ends', b.ends_at,
                'yes', case when b.status = 'voting' then (select count(*) from faction_votes v where v.bill_id = b.id and v.yes) else b.yes end,
                'no', case when b.status = 'voting' then (select count(*) from faction_votes v where v.bill_id = b.id and not v.yes) else b.no end,
                'mine', (select v.yes from faction_votes v where v.bill_id = b.id and v.user_id = v_me)) x
       from faction_bills b join faction_laws l on l.id = b.law_id left join profiles p on p.id = b.proposed_by
       where b.faction = v_fac and b.status in ('voting', 'active')) q),
    'history', (select coalesce(jsonb_agg(x order by x->>'at' desc), '[]'::jsonb) from (
       select jsonb_build_object('id', b.id, 'title', l.title, 'mode', b.mode, 'status', b.status, 'by', p.nickname,
                'at', coalesce(case when b.status = 'expired' then b.ends_at end, b.closed_at, b.created_at), 'yes', b.yes, 'no', b.no, 'need', b.need) x
       from faction_bills b join faction_laws l on l.id = b.law_id left join profiles p on p.id = b.proposed_by
       where b.faction = v_fac and b.status in ('failed', 'expired')
       order by coalesce(b.closed_at, b.created_at) desc limit 8) q));
end;
$$;


--
-- Name: law_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_n integer := 0;
begin
  if not pg_try_advisory_xact_lock(hashtext('law_tick')) then return 0; end if;
  for r in select id from faction_bills where status = 'voting' and vote_ends_at <= now() loop
    perform law_close(r.id); v_n := v_n + 1;
  end loop;
  for r in select b.id, b.faction, l.title, l.funds from faction_bills b join faction_laws l on l.id = b.law_id
           where b.status = 'active' and b.ends_at <= now() loop
    update faction_bills set status = 'expired' where id = r.id;
    perform log_event(null, r.faction, null, 'law_expired', r.title, 1, 'faction', jsonb_build_object('bill', r.id));
    if r.funds ? 'end' then
      perform treasury_add(r.faction, (r.funds->>'end')::integer, 'debt', null, null, null, r.title);
      perform log_event(null, r.faction, null, 'treasury_debt', r.title, abs((r.funds->>'end')::integer), 'faction', jsonb_build_object('bill', r.id));
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: law_vote(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.law_vote(p_bill uuid, p_yes boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; b faction_bills;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  if p_yes is null then raise exception 'За или против?'; end if;
  select faction into v_fac from profiles where id = v_me;
  select * into b from faction_bills where id = p_bill for update;
  if not found or b.faction is distinct from v_fac then raise exception 'Голосование не найдено'; end if;
  if b.status <> 'voting' or b.vote_ends_at <= now() then raise exception 'Голосование уже закончилось'; end if;
  insert into faction_votes (bill_id, user_id, yes) values (b.id, v_me, p_yes)
  on conflict (bill_id, user_id) do update set yes = excluded.yes, at = now();
  if (select count(*) from faction_votes where bill_id = b.id) >= greatest(law_members(v_fac), 1) then perform law_close(b.id); end if;
  return law_state();
end;
$$;


--
-- Name: leader_revoke_planet(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leader_revoke_planet(p_system text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_ctl uuid;
begin
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null or not is_faction_leader(v_me, v_fac) then raise exception 'Снять управляющего может только лидер фракции'; end if;
  if (select faction from systems where id = p_system) is distinct from v_fac then raise exception 'Это не планета твоей фракции'; end if;
  select controller_user_id into v_ctl from system_control where system_id = p_system for update;
  if v_ctl is null then raise exception 'У планеты нет управляющего'; end if;
  if is_capture_active(p_system) then raise exception 'Идёт захват — управляющего не меняют'; end if;
  update system_control set controller_user_id = null where system_id = p_system;
  return true;
end;
$$;


--
-- Name: lease_allowed_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_allowed_code(p_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_code in ('rep_barracks','cis_droid','rep_vehicle','cis_vehicle','rep_temple','cis_sith');
$$;


--
-- Name: lease_cancel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_cancel(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare l public.production_leases; v text;
begin
  select * into l from production_leases where id = p_id and lessor_id = auth.uid() for update;
  if not found then raise exception 'Предложение не найдено'; end if;
  v := lease_effective_status(l);
  if v = 'active' then raise exception 'Аренда уже идёт — отозвать её нельзя, дождись конца срока'; end if;
  if v <> 'offered' then raise exception 'Предложение уже не действует'; end if;
  update production_leases set status = 'cancelled', closed_at = now() where id = p_id;
  perform log_event(l.lessee_id, l.faction, l.system_id, 'lease_cancelled', l.target_name, 0, 'private',
    jsonb_build_object('lease_id', l.id, 'player', (select nickname from profiles where id = l.lessor_id)));
end;
$$;


--
-- Name: production_leases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.production_leases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lessor_id uuid NOT NULL,
    lessee_id uuid NOT NULL,
    faction text NOT NULL,
    system_id text NOT NULL,
    building_id uuid,
    target_name text NOT NULL,
    hours integer NOT NULL,
    price integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'offered'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    offer_expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    closed_at timestamp with time zone,
    CONSTRAINT production_leases_hours_check CHECK (((hours >= 1) AND (hours <= 48))),
    CONSTRAINT production_leases_price_check CHECK (((price >= 0) AND (price <= 1000000))),
    CONSTRAINT production_leases_status_check CHECK ((status = ANY (ARRAY['offered'::text, 'active'::text, 'declined'::text, 'cancelled'::text, 'expired'::text, 'ended'::text, 'void'::text])))
);


--
-- Name: lease_effective_status(public.production_leases); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_effective_status(l public.production_leases) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when l.status = 'active' and l.ends_at <= now() then 'ended'
    when l.status = 'active' and not lease_is_live(l) then 'void'
    when l.status = 'offered' and l.offer_expires_at <= now() then 'expired'
    when l.status = 'offered' and (not exists (select 1 from system_control sc
          where sc.system_id = l.system_id and sc.controller_user_id = l.lessor_id)
          or not lease_target_ok(l)) then 'void'
    else l.status end;
$$;


--
-- Name: lease_end(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_end(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare l public.production_leases;
begin
  select * into l from production_leases where id = p_id and lessee_id = auth.uid() for update;
  if not found then raise exception 'Аренда не найдена'; end if;
  if lease_effective_status(l) <> 'active' then raise exception 'Аренда уже закончилась'; end if;
  update production_leases set status = 'ended', ends_at = least(ends_at, now()), closed_at = now() where id = p_id;
  perform log_event(l.lessor_id, l.faction, l.system_id, 'lease_returned', l.target_name, 0, 'private',
    jsonb_build_object('lease_id', l.id, 'player', (select nickname from profiles where id = l.lessee_id)));
end;
$$;


--
-- Name: lease_is_live(public.production_leases); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_is_live(l public.production_leases) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.status = 'active' and l.ends_at > now()
     and exists (select 1 from system_control sc
                 where sc.system_id = l.system_id and sc.controller_user_id = l.lessor_id)
     and lease_target_ok(l);
$$;


--
-- Name: lease_left_text(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_left_text(p_until timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when extract(epoch from p_until - now()) >= 3600 then
      floor(extract(epoch from p_until - now()) / 3600)::int || ' ч ' ||
      floor(mod(extract(epoch from p_until - now())::numeric, 3600) / 60)::int || ' мин'
    else greatest(1, ceil(extract(epoch from p_until - now()) / 60))::int || ' мин' end;
$$;


--
-- Name: lease_live_for(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_live_for(p_system_id text, p_building_id uuid) RETURNS public.production_leases
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.* from production_leases l
  where l.system_id = p_system_id and l.building_id is not distinct from p_building_id
    and l.status = 'active' and lease_is_live(l)
  order by l.starts_at desc limit 1;
$$;


--
-- Name: lease_offer(text, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_offer(p_system_id text, p_building_id uuid, p_lessee uuid, p_hours integer, p_price integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid(); v_fac text; v_sys_fac text; v_lessee_fac text; v_lessee_name text;
  b record; st record; v_name text; v_id uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_lessee is null or p_lessee = v_user then raise exception 'Выбери союзника — себе сдавать нельзя'; end if;
  if p_hours is null or p_hours < 1 or p_hours > 48 then raise exception 'Срок аренды — от 1 до 48 часов'; end if;
  if p_price is null or p_price < 0 or p_price > 1000000 then raise exception 'Плата — от 0 до 1 000 000 кр.'; end if;

  perform assert_planet_operational(p_system_id);
  if not exists (select 1 from system_control sc where sc.system_id = p_system_id and sc.controller_user_id = v_user) then
    raise exception 'Сдавать производство может только управляющий планетой';
  end if;

  select faction into v_fac from profiles where id = v_user;
  select faction into v_sys_fac from systems where id = p_system_id;
  select faction, nickname into v_lessee_fac, v_lessee_name from profiles where id = p_lessee;
  if v_lessee_fac is null then raise exception 'Игрок не найден'; end if;
  if v_lessee_fac is distinct from v_fac then raise exception 'Сдавать можно только союзнику своей фракции'; end if;
  if v_sys_fac is distinct from v_fac then raise exception 'Планета чужой фракции'; end if;

  if p_building_id is null then
    select * into st from space_stations where system_id = p_system_id;
    if not found then raise exception 'В этой системе нет космической станции'; end if;
    if st.faction is distinct from v_sys_fac then raise exception 'Трофейную станцию сдать нельзя'; end if;
    if st.completes_at is not null and st.completes_at > now() then raise exception 'Станция ещё строится'; end if;
    v_name := 'Верфь';
  else
    select bl.*, bt.code, bt.name as type_name into b
    from buildings bl join building_types bt on bt.id = bl.building_type_id
    where bl.id = p_building_id and bl.system_id = p_system_id;
    if not found then raise exception 'Постройка не найдена'; end if;
    if not lease_allowed_code(b.code) then
      raise exception 'В аренду сдаются казармы, заводы техники, храм и верфь';
    end if;
    if b.faction is distinct from v_sys_fac then raise exception 'Трофейную постройку сдать нельзя'; end if;
    if b.completes_at is not null and b.completes_at > now() then raise exception 'Постройка ещё не достроена'; end if;
    v_name := b.type_name;
  end if;

  perform pg_advisory_xact_lock(hashtext('lease:' || p_system_id || ':' || coalesce(p_building_id::text, 'station')));
  perform lease_settle(p_system_id, p_building_id);
  if exists (select 1 from production_leases where system_id = p_system_id
             and building_id is not distinct from p_building_id and status in ('offered','active')) then
    raise exception 'Это производство уже сдано или предложено — сначала отзови прежнее предложение';
  end if;

  insert into production_leases (lessor_id, lessee_id, faction, system_id, building_id, target_name, hours, price)
  values (v_user, p_lessee, v_fac, p_system_id, p_building_id, v_name, p_hours, p_price)
  returning id into v_id;

  perform log_event(p_lessee, v_fac, p_system_id, 'lease_offered', v_name, p_price, 'private',
    jsonb_build_object('lease_id', v_id, 'player', (select nickname from profiles where id = v_user),
                       'hours', p_hours));
  return v_id;
end;
$$;


--
-- Name: lease_on_control_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_on_control_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.controller_user_id is not distinct from old.controller_user_id then
    return new;
  end if;
  perform lease_void_check(new.system_id);
  return new;
end;
$$;


--
-- Name: lease_on_system_faction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_on_system_faction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.faction is distinct from old.faction then
    perform lease_void_check(new.id);
  end if;
  return new;
end;
$$;


--
-- Name: lease_respond(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_respond(p_id uuid, p_accept boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare l public.production_leases; v_user uuid := auth.uid(); v_credits integer; v_eff text;
  v_busy timestamptz; v_busy_name text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select * into l from production_leases where id = p_id and lessee_id = v_user for update;
  if not found then raise exception 'Предложение не найдено'; end if;
  if l.status <> 'offered' then raise exception 'На это предложение уже ответили'; end if;

  v_eff := lease_effective_status(l);
  if v_eff <> 'offered' then
    update production_leases set status = v_eff, closed_at = now() where id = p_id;
    return case when v_eff = 'expired' then '!Предложение истекло'
                else '!Предложение больше не действует: у хозяина нет этой планеты или постройки' end;
  end if;

  if not p_accept then
    update production_leases set status = 'declined', closed_at = now() where id = p_id;
    perform log_event(l.lessor_id, l.faction, l.system_id, 'lease_declined', l.target_name, 0, 'private',
      jsonb_build_object('lease_id', l.id, 'player', (select nickname from profiles where id = v_user)));
    return 'declined';
  end if;

  if l.building_id is null then
    select completes_at, name into v_busy, v_busy_name from shipyard_busy(l.system_id);
  else
    select min(x.completes_at) into v_busy from (
      select completes_at from unit_orders where building_id = l.building_id and not delivered
      union all
      select completes_at from repair_orders where building_id = l.building_id and not delivered) x;
  end if;
  if v_busy is not null then
    raise exception 'Линия ещё занята прежним заказом — освободится через %. Прими предложение после этого',
      lease_left_text(greatest(v_busy, now() + interval '1 minute'));
  end if;

  perform 1 from profiles where id in (v_user, l.lessor_id) order by id for update;
  select credits into v_credits from profiles where id = v_user;
  if coalesce(v_credits, 0) < l.price then
    raise exception 'Не хватает кредитов: аренда стоит %', l.price;
  end if;
  update profiles set credits = credits - l.price where id = v_user;
  update profiles set credits = credits + l.price where id = l.lessor_id;

  update production_leases
  set status = 'active', starts_at = now(), ends_at = now() + make_interval(hours => l.hours)
  where id = p_id;

  perform log_event(l.lessor_id, l.faction, l.system_id, 'lease_accepted', l.target_name, l.price, 'private',
    jsonb_build_object('lease_id', l.id, 'player', (select nickname from profiles where id = v_user),
                       'hours', l.hours));
  return 'active';
end;
$$;


--
-- Name: lease_settle(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_settle(p_system_id text, p_building_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare l public.production_leases; v text;
begin
  for l in select * from production_leases
           where system_id = p_system_id and building_id is not distinct from p_building_id
             and status in ('offered','active') for update loop
    v := lease_effective_status(l);
    if v <> l.status then
      update production_leases set status = v, closed_at = coalesce(closed_at, now()) where id = l.id;
    end if;
  end loop;
end;
$$;


--
-- Name: lease_target_ok(public.production_leases); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_target_ok(l public.production_leases) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when l.building_id is null then
           exists (select 1 from space_stations st join systems s on s.id = st.system_id
                   where st.system_id = l.system_id and st.faction = s.faction)
         else
           exists (select 1 from buildings b join systems s on s.id = b.system_id
                   where b.id = l.building_id and b.system_id = l.system_id and b.faction = s.faction)
         end;
$$;


--
-- Name: lease_void_check(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_void_check(p_system_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare l public.production_leases; v text; v_back integer; v_have integer;
begin
  for l in select * from production_leases
           where system_id = p_system_id and status in ('offered','active') for update loop
    v := lease_effective_status(l);
    if v = l.status then continue; end if;
    update production_leases set status = v, closed_at = coalesce(closed_at, now()) where id = l.id;
    if v = 'void' and l.status = 'active' then
      v_back := 0;
      if l.price > 0 and l.ends_at > now() then
        v_back := floor(l.price * extract(epoch from l.ends_at - now()) / (l.hours * 3600.0))::integer;
        select greatest(0, credits) into v_have from profiles where id = l.lessor_id for update;
        v_back := least(greatest(v_back, 0), coalesce(v_have, 0), l.price);
        if v_back > 0 then
          update profiles set credits = credits - v_back where id = l.lessor_id;
          update profiles set credits = credits + v_back where id = l.lessee_id;
        end if;
      end if;
      perform log_event(l.lessee_id, l.faction, l.system_id, 'lease_void', l.target_name, v_back, 'private',
        jsonb_build_object('lease_id', l.id, 'player', (select nickname from profiles where id = l.lessor_id)));
    end if;
  end loop;
end;
$$;


--
-- Name: load_market_order(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_market_order(p_ship_id uuid, p_order_id uuid, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; o record; l record; st record;
  v_used integer; v_need integer; v_pay integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_amount < 1 then raise exception 'Некорректное количество'; end if;

  select * into o from market_orders where id = p_order_id for update;
  if not found then raise exception 'Бронь не найдена'; end if;
  if o.buyer_user_id <> v_user then raise exception 'Это не твоя бронь'; end if;
  if o.status <> 'reserved' then raise exception 'Бронь уже закрыта'; end if;
  if o.expires_at <= now() then raise exception 'Срок брони истёк'; end if;
  if o.amount_left < p_amount then
    raise exception 'По брони осталось только %', o.amount_left;
  end if;

  select * into l from market_lots where id = o.lot_id;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  -- Грузиться нужно там, где лежит товар. Планета при этом может быть
  -- чужой — именно бронь и даёт право подойти к чужому складу.
  if s.system_id <> l.system_id then
    raise exception 'Товар лежит в системе %, веди корабль туда', l.system_id;
  end if;

  select * into st from ship_stats(p_ship_id);
  v_used := ship_load_used(p_ship_id);
  v_need := resource_slots(p_amount);

  if v_used + v_need > st.capacity then
    raise exception 'В трюме не хватает места: занято % из %, нужно ещё %',
      v_used, st.capacity, v_need;
  end if;

  insert into ship_resource_cargo (ship_id, resource, amount)
  values (p_ship_id, l.resource, p_amount)
  on conflict (ship_id, resource) do update
    set amount = ship_resource_cargo.amount + excluded.amount;

  v_pay := p_amount * o.price_per_unit;
  update profiles set credits = credits + v_pay where id = l.seller_user_id;

  update market_orders
  set amount_left = amount_left - p_amount,
      status = case when amount_left - p_amount <= 0 then 'collected' else 'reserved' end
  where id = p_order_id;

  perform log_event(l.seller_user_id, l.seller_faction, l.system_id, 'market_paid',
                    l.resource, p_amount, 'private',
                    jsonb_build_object('credits', v_pay));
  perform log_event(v_user, s.faction, l.system_id, 'market_collected',
                    l.resource, p_amount, 'private', null);

  return st.capacity - ship_load_used(p_ship_id);
end;
$$;


--
-- Name: load_resource_to_ship(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_resource_to_ship(p_ship_id uuid, p_resource text, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; st record; v_used integer; v_need integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_amount is null or p_amount < 1 then raise exception 'Некорректное количество'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  -- Грузить можно только со своей планеты: чужие склады берут штурмом,
  -- а не подлетают и вывозят
  if not exists (select 1 from system_control sc
                 where sc.system_id = s.system_id and sc.controller_user_id = v_user) then
    raise exception 'Планета не под твоим контролем';
  end if;

  select * into st from ship_stats(p_ship_id);
  v_used := ship_load_used(p_ship_id);
  v_need := resource_slots(p_amount);

  if v_used + v_need > st.capacity then
    raise exception 'В трюме не хватает места: занято % из %, нужно ещё %',
      v_used, st.capacity, v_need;
  end if;

  perform take_planet_stock(s.system_id, p_resource, p_amount);

  insert into ship_resource_cargo (ship_id, resource, amount)
  values (p_ship_id, p_resource, p_amount)
  on conflict (ship_id, resource) do update
    set amount = ship_resource_cargo.amount + excluded.amount;

  return st.capacity - ship_load_used(p_ship_id);
end;
$$;


--
-- Name: load_to_ship(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_to_ship(p_ship_id uuid, p_unit_type text, p_quantity integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; st record; v_used integer; v_need integer; v_ids uuid[];
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_quantity < 1 then raise exception 'Некорректное количество'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;
  if s.carrier_ship_id is not null then raise exception 'Корабль стоит в ангаре носителя'; end if;
  -- войска грузят только из площадки сброса — как и высаживают (sql/load_pad.sql)
  if (select is_in_orbital_drop(s.x, s.y, ship_box_w(t.width_cells, t.height_cells, s.facing), ship_box_h(t.width_cells, t.height_cells, s.facing))
        from ship_types t where t.id = s.ship_type) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса — на орбите коснись корабля, потом квадрата «ПЛОЩАДКА»';
  end if;

  if (select is_hero from unit_types where id = p_unit_type) then
    raise exception 'Одарённого нельзя грузить пачкой — выбери его на карте';
  end if;

  select * into st from ship_stats(p_ship_id);

  -- Грузим только из зоны высадки — ровно тех, кого показывает список.
  -- Сначала самых прокачанных и целых: их обычно и везут в бой.
  select array_agg(id) into v_ids from (
    select u.id
    from unit_positions u
    where u.system_id = s.system_id and u.layer = 'ground'
      and u.owner_user_id = v_user and u.unit_type = p_unit_type and u.x is not null
      and is_in_deploy_zone(u.system_id, u.x, u.y)
    order by coalesce(cardinality(u.upgrades), 0) desc, u.hp desc, u.id
    limit p_quantity
    for update of u) q;

  if coalesce(cardinality(v_ids), 0) < p_quantity then
    raise exception 'В зоне высадки столько нет: доступно %', coalesce(cardinality(v_ids), 0);
  end if;

  select coalesce(sum(unit_total_slots(i)), 0) into v_need from unnest(v_ids) i;
  v_used := ship_load_used(p_ship_id);
  if v_used + v_need > st.capacity then
    raise exception 'В трюме не хватает места: занято % из %', v_used, st.capacity;
  end if;

  -- Боец едет в трюме сам собой: улучшения, раны и откаты остаются при нём
  update unit_positions
  set x = null, y = null, carrier_ship_id = p_ship_id
  where id = any(v_ids);

  perform log_event(v_user, s.faction, s.system_id, 'unit_loaded', p_unit_type, cardinality(v_ids), 'private', null);

  return st.capacity - ship_load_used(p_ship_id);
end;
$$;


--
-- Name: load_unit_from_ground(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_unit_from_ground(p_unit_id uuid, p_ship_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; s record; t record; st record;
  v_sys_faction text; v_attacking boolean;
  v_need integer; v_used integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.layer <> 'ground' then raise exception 'Грузить можно только с поверхности'; end if;
  if u.x is null then raise exception 'Юнит уже погружен'; end if;
  if u.hp <= 0 then raise exception 'Юнит уничтожен'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;
  if s.system_id <> u.system_id then raise exception 'Корабль у другой планеты'; end if;

  select * into t from ship_types where id = s.ship_type;
  select * into st from ship_stats(p_ship_id);
  select faction into v_sys_faction from systems where id = s.system_id;
  v_attacking := v_sys_faction is distinct from s.faction;

  if is_in_orbital_drop(s.x, s.y,
       ship_box_w(t.width_cells, t.height_cells, s.facing),
       ship_box_h(t.width_cells, t.height_cells, s.facing)) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса';
  end if;

  if v_attacking then
    if not is_in_ground_attack_zone(u.y) then
      raise exception 'Забрать можно только из полосы вторжения';
    end if;
  else
    if not is_in_deploy_zone(u.system_id, u.x, u.y) then
      raise exception 'Юнит вне зоны высадки';
    end if;
  end if;

  v_need := unit_total_slots(p_unit_id);
  v_used := ship_load_used(p_ship_id);
  if v_used + v_need > st.capacity then
    raise exception 'В трюме не хватает места: занято % из %', v_used, st.capacity;
  end if;

  -- Боец едет в трюме сам собой: улучшения, раны и откаты остаются при нём
  update unit_positions
  set x = null, y = null, carrier_ship_id = p_ship_id
  where id = p_unit_id;

  perform log_event(v_user, u.faction, u.system_id, 'unit_loaded', u.unit_type, 1, 'private',
                    jsonb_build_object('x', u.x, 'y', u.y));

  return st.capacity - ship_load_used(p_ship_id);
end;
$$;


--
-- Name: load_vehicle_to_ship(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_vehicle_to_ship(p_unit_id uuid, p_ship_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; ut record; s record; t record; st record;
  v_sys_faction text; v_attacking boolean;
  v_need integer; v_used integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.x is null then raise exception 'Юнит уже погружен'; end if;

  select * into ut from unit_types where id = u.unit_type;
  if not (ut.is_vehicle or ut.is_hero) then raise exception 'Для пехоты используется обычная погрузка'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;
  if s.system_id <> u.system_id then raise exception 'Корабль у другой планеты'; end if;

  select * into t from ship_types where id = s.ship_type;
  select * into st from ship_stats(p_ship_id);

  if is_in_orbital_drop(s.x, s.y,
       ship_box_w(t.width_cells, t.height_cells, s.facing),
       ship_box_h(t.width_cells, t.height_cells, s.facing)) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса';
  end if;

  select faction into v_sys_faction from systems where id = s.system_id;
  v_attacking := v_sys_faction is distinct from s.faction;

  if v_attacking then
    if not is_box_in_attack_zone(u.y, ut.height_cells) then
      raise exception 'Забрать можно только из полосы вторжения';
    end if;
  else
    if not is_box_in_deploy_zone(u.system_id, u.x, u.y, ut.width_cells, ut.height_cells) then
      raise exception 'Техника вне зоны высадки';
    end if;
  end if;

  v_need := unit_total_slots(p_unit_id);
  v_used := ship_load_used(p_ship_id);

  if v_used + v_need > st.capacity then
    raise exception 'В трюме не хватает места: нужно %, занято % из %',
      v_need, v_used, st.capacity;
  end if;

  update unit_positions
  set x = null, y = null, carrier_ship_id = p_ship_id
  where id = p_unit_id;

  return st.capacity - ship_load_used(p_ship_id);
end;
$$;


--
-- Name: log_control_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_control_transfer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_faction text; v_name text;
begin
  -- Захват отчитывается сам, отдельным событием: не дублируем
  if coalesce(current_setting('app.capture_transfer', true), '') = '1' then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.controller_user_id is not distinct from old.controller_user_id then
    return new;
  end if;

  select faction into v_faction from systems where id = new.system_id;

  if tg_op = 'UPDATE' and old.controller_user_id is not null then
    perform log_event(old.controller_user_id, v_faction, new.system_id,
                      'planet_revoked', null, 1, 'private', null);
  end if;

  if new.controller_user_id is not null then
    perform log_event(new.controller_user_id, v_faction, new.system_id,
                      'planet_granted', null, 1, 'private', null);
  end if;

  return new;
end;
$$;


--
-- Name: log_event(uuid, text, text, text, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_event(p_user_id uuid, p_faction text, p_system_id text, p_type text, p_subject text DEFAULT NULL::text, p_amount integer DEFAULT 1, p_visibility text DEFAULT 'private'::text, p_meta jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE sql
    AS $$
  insert into game_events (user_id, faction, system_id, type, subject, amount, visibility, meta)
  select p_user_id, p_faction, p_system_id, p_type, p_subject, p_amount, p_visibility, p_meta
  where not (p_user_id is null and coalesce(p_visibility, 'private') = 'private')
    and not (coalesce(current_setting('app.boarding_quiet', true), '') = '1'
             and p_type in ('unit_killed', 'ship_lost', 'cargo_lost'));
$$;


--
-- Name: log_event_digest(uuid, text, text, text, text, text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_event_digest(p_user uuid, p_faction text, p_type text, p_key text, p_system text, p_base text, p_what text, p_n integer, p_extra text, p_bump boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  g record; v_lines jsonb; v_pos integer; v_line jsonb; v_sys text; v_multi boolean;
  v_sum integer; v_cnt integer; v_subject text; v_parts text; v_found boolean; v_side integer;
begin
  if p_user is null then return; end if;

  -- Сводка живёт, пока игрок её не прочитал: одно событие на тип
  select * into g from game_events
  where user_id = p_user and type = p_type and seen_at is null
    and coalesce((meta ->> 'digest')::boolean, false)
    and created_at > now() - interval '24 hours'
  order by created_at desc limit 1
  for update;
  v_found := found;

  v_line := jsonb_build_object('k', p_key, 'sys', p_system, 'base', p_base,
                               'what', p_what, 'n', p_n, 'extra', p_extra);

  if not v_found then
    v_lines := jsonb_build_array(v_line);
  else
    v_lines := coalesce(g.meta -> 'lines', '[]'::jsonb);
    select (x.ord - 1)::integer into v_pos
    from jsonb_array_elements(v_lines) with ordinality x(val, ord)
    where x.val ->> 'k' = p_key limit 1;

    if v_pos is not null then
      -- Та же строка уже есть: простой повтор (цех всё ещё стоит) ничего
      -- не меняет и не поднимает событие наверх
      if not p_bump then return; end if;
      v_lines := jsonb_set(v_lines, array[v_pos::text],
        (v_lines -> v_pos) || jsonb_build_object(
          'n', case when p_n is null then null
                    else coalesce((v_lines -> v_pos ->> 'n')::integer, 0) + p_n end,
          'extra', p_extra));
    elsif jsonb_array_length(v_lines) < 40 then
      v_lines := v_lines || jsonb_build_array(v_line);
    end if;
  end if;

  -- Готовый текст каждой строки: клиенту остаётся только вывести
  select jsonb_agg(val || jsonb_build_object('txt',
           coalesce(val ->> 'base', '') ||
           case when val ->> 'what' is not null then ': ' || (val ->> 'what') else '' end ||
           case when val ->> 'n' is not null
                then case when p_type in ('marauder_loot', 'supply_taken') then ' −' else ' +' end || (val ->> 'n')
                else '' end ||
           case when coalesce(val ->> 'extra', '') <> '' then ' · ' || (val ->> 'extra') else '' end)
         order by ord)
    into v_lines
  from jsonb_array_elements(v_lines) with ordinality x(val, ord);

  select count(distinct val ->> 'sys') > 1, min(val ->> 'sys'),
         coalesce(sum((val ->> 'n')::integer), 0)
    into v_multi, v_sys, v_sum
  from jsonb_array_elements(v_lines) x(val);

  select count(*) into v_cnt from jsonb_array_elements(v_lines);

  if p_type = 'settlement_income' then
    select count(distinct val ->> 'sys') into v_cnt from jsonb_array_elements(v_lines) x(val);
    select count(distinct val ->> 'sys') filter (where coalesce(val ->> 'k', '') not like 'fs:%'),
           count(*) filter (where coalesce(val ->> 'k', '') like 'fs:%')
      into v_cnt, v_side
    from jsonb_array_elements(v_lines) x(val);
    v_subject := '+' || v_sum || ' кр. · ' || concat_ws(' · ',
      case when v_cnt > 0 then ru_plural(v_cnt, 'поселение', 'поселения', 'поселений') end,
      case when v_side > 0 then ru_plural(v_side, 'кантина', 'кантины', 'кантин') end);
  elsif p_type in ('resource_extracted', 'resource_refined') then
    select string_agg(w || ' +' || s, ', ' order by s desc) into v_parts
    from (select val ->> 'what' w, sum((val ->> 'n')::integer) s
          from jsonb_array_elements(v_lines) x(val) group by 1) q;
    v_subject := v_parts;
  elsif p_type = 'structure_built' then
    v_subject := 'Готово: ' || ru_plural(v_cnt, 'постройка', 'постройки', 'построек');
  elsif p_type = 'turret_report' then
    v_subject := 'Выстрелов: ' || v_sum;
  elsif p_type = 'supply_taken' then
    v_subject := 'Вывезено: ' || v_sum;
  elsif p_type = 'supply_delivered' then
    v_subject := 'Доставлено: ' || v_sum;
  elsif p_type = 'marauder_loot' then
    v_subject := 'Урон постройкам: ' || v_sum;
  elsif p_type = 'npc_return_fire' then
    v_subject := 'Урон по мародёрам: ' || v_sum;
  elsif p_type = 'production_idle' then
    v_subject := 'Стоит ' || ru_plural(v_cnt, 'цех', 'цеха', 'цехов');
  else
    v_subject := ru_plural(v_cnt, 'запись', 'записи', 'записей');
  end if;

  if not v_found then
    insert into game_events (user_id, faction, system_id, type, subject, amount, visibility, meta)
    values (p_user, p_faction, case when v_multi then null else v_sys end, p_type, v_subject,
            1, 'private', jsonb_build_object('digest', true, 'total', v_sum, 'lines', v_lines));
  else
    update game_events
    set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('digest', true, 'total', v_sum, 'lines', v_lines),
        subject = v_subject,
        amount = 1,
        system_id = case when v_multi then null else v_sys end,
        created_at = case when p_bump or v_pos is null then now() else created_at end
    where id = g.id;
  end if;
end;
$$;


--
-- Name: log_lost_cargo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_lost_cargo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare r record;
begin
  for r in select resource, amount from ship_resource_cargo where ship_id = old.id loop
    perform log_event(old.owner_user_id, old.faction, old.system_id,
                      'cargo_lost', r.resource, r.amount, 'private', null);
  end loop;
  return old;
end;
$$;


--
-- Name: loyalty_agit_cd(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_agit_cd(p_system text, p_faction text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select max(o.launched_at) + make_interval(hours => game_setting_int('loyalty_agit_cd_h', 12))
    from spy_ops o
   where o.kind = 'agitate' and o.target_system = p_system and o.attacker_faction = p_faction
     and o.launched_at > now() - make_interval(hours => game_setting_int('loyalty_agit_cd_h', 12))
     and o.result is distinct from 'void';
$$;


--
-- Name: loyalty_agit_chance(text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_agit_chance(p_system text, p_wins integer, p_at timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(10, least(90, spy_chance_known(p_wins, p_at)
       - least(40, 4 * loyalty_garrison(p_system))
       - case when settlement_has_district(p_system, 'comms') then game_setting_int('spy_comms_pct', 10) else 0 end
       - loyalty_agit_pen(p_system)));
$$;


--
-- Name: loyalty_agit_pen(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_agit_pen(p_system text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when coalesce(loyalty_support(p_system), 0) >= 80 then 15 when coalesce(loyalty_support(p_system), 0) >= 50 then 8 else 0 end;
$$;


--
-- Name: loyalty_agitate_resolve(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_agitate_resolve(p_op uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o spy_ops; g spy_groups; sy record; pl planet_loyalty; v_ctl uuid; v_lead uuid; v_to uuid; v_ch integer; v_roll numeric;
  v_aname text; v_afac text; v_gain integer := game_setting_int('loyalty_agit_gain', 4); v_fail integer := game_setting_int('loyalty_agit_fail', 2);
  v_bounty integer := game_setting_int('spy_bounty', 300); v_lvl integer; v_new integer; v_s integer;
begin
  select * into o from spy_ops where id = p_op and status = 'go' for update;
  if not found then return; end if;
  select * into g from spy_groups where id = o.group_id for update;
  select id, name, faction into sy from systems where id = o.target_system;
  select controller_user_id into v_ctl from system_control where system_id = o.target_system;
  select nickname into v_aname from profiles where id = o.attacker;
  v_afac := case o.attacker_faction when 'republic' then 'Республики' else 'КНС' end;

  -- планета перешла к своим или шкала выключена — возвращаются ни с чем
  if sy.faction is null or sy.faction not in ('republic', 'cis') or sy.faction = o.attacker_faction or not loyalty_on('ops') then
    update spy_ops set status = 'acted', acted_at = now(), result = 'void' where id = p_op;
    perform log_event(o.attacker, o.attacker_faction, o.target_system, 'spy_result',
      'Агитация: ' || coalesce(sy.name, 'планета') || ' уже не вражеская — группа возвращается', null, 'private', '{}'::jsonb);
    return;
  end if;

  insert into planet_loyalty (system_id, value, home) values (o.target_system, 0, 0) on conflict (system_id) do nothing;
  select * into pl from planet_loyalty where system_id = o.target_system for update;
  v_ch := loyalty_agit_chance(o.target_system, g.wins, now());
  v_roll := random() * 100;
  select leader_user_id into v_lead from faction_leadership where faction = sy.faction;

  if v_roll >= v_ch then
    -- жители выдали агитаторов: группа схвачена, хозяин — с наградой, народ теплеет к власти
    update spy_ops set status = 'acted', acted_at = now(), result = 'caught', chance = v_ch, roll = v_roll, victim = v_ctl,
                       revealed = true, reveal_at = now(), effect = jsonb_build_object('loyalty', v_fail) where id = p_op;
    update spy_groups set status = 'lost', lost_at = now() where id = g.id;
    if v_ctl is not null then update profiles set credits = credits + v_bounty where id = v_ctl; end if;
    v_new := loyalty_set(o.target_system, pl.value + v_fail * loyalty_side(sy.faction), null, 'agit_caught');
    for v_to in select distinct x from unnest(array[v_ctl, v_lead]) x where x is not null loop
      perform log_event(v_to, sy.faction, o.target_system, 'loyalty_agit_caught',
        sy.name || ': жители выдали агитаторов ' || v_afac || ' (группа игрока ' || coalesce(v_aname, '?') || ') · поддержка +' || v_fail
        || case when v_to = v_ctl then ' · награда ' || v_bounty || ' кр.' else '' end, v_fail, 'private', jsonb_build_object('op', o.id));
    end loop;
    perform log_event(o.attacker, o.attacker_faction, o.target_system, 'spy_result',
      'Провал: ' || g.name || ' в плену — агитация, ' || sy.name || ' · шанс был ' || v_ch || ' %', null, 'private', '{}'::jsonb);
    return;
  end if;

  -- успех: народ качнулся к нам, сеть подполья окрепла
  insert into loyalty_cells (system_id, faction, level) values (o.target_system, o.attacker_faction, 1)
  on conflict (system_id, faction) do update set level = least(3, loyalty_cells.level + 1), updated_at = now()
  returning level into v_lvl;
  v_new := loyalty_set(o.target_system, pl.value + v_gain * loyalty_side(o.attacker_faction), null, 'agit');
  v_s := v_new * loyalty_side(sy.faction);
  update spy_ops set status = 'acted', acted_at = now(), result = 'ok', chance = v_ch, roll = v_roll, victim = v_ctl,
                     effect = jsonb_build_object('loyalty', v_gain, 'cell', v_lvl), revealed = true, reveal_at = now()
   where id = p_op;
  for v_to in select distinct x from unnest(array[v_ctl, v_lead]) x where x is not null loop
    perform log_event(v_to, sy.faction, o.target_system, 'loyalty_agit',
      sy.name || ': агитаторы ' || v_afac || ' · поддержка −' || v_gain || ', подполье ур. ' || v_lvl, v_lvl, 'private',
      jsonb_build_object('op', o.id, 'level', v_lvl, 'value', v_s));
  end loop;
  perform log_event(o.attacker, o.attacker_faction, o.target_system, 'spy_result',
    g.name || ': «Агитация» — успех, ' || sy.name || ' · поддержка врага −' || v_gain || ', наша сеть подполья ур. ' || v_lvl, null, 'private', '{}'::jsonb);
end;
$$;


--
-- Name: loyalty_battle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_battle(p_system text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sy record; v_s integer; v_enemy text; v_g timestamptz; v_cell integer;
begin
  if not loyalty_on('effects') then return null; end if;
  select id, faction into sy from systems where id = p_system;
  if coalesce(sy.faction, '') not in ('republic', 'cis') then return null; end if;
  v_s := loyalty_support(p_system);
  if v_s is null then return null; end if;
  v_enemy := case sy.faction when 'republic' then 'cis' else 'republic' end;
  v_g := loyalty_grace_until(p_system);
  select level into v_cell from loyalty_cells where system_id = p_system and faction = v_enemy;
  return jsonb_build_object('stage', loyalty_stage_of(v_s) ->> 'k',
    'reveal', case when (v_g is null or v_g <= now()) and not loyalty_capital(p_system) and (v_s <= -50 or coalesce(v_cell, 0) >= 3) then v_enemy end);
end;
$$;


--
-- Name: loyalty_calc(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_calc(p_system text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sy record; pl record; c record; v_side integer; v_s integer; v_home integer; v_d integer; v_eff integer; v_un integer;
  v_gar integer; v_ef integer; v_rows jsonb := '[]'::jsonb; v_sum integer := 0; v_cap integer := game_setting_int('loyalty_day_cap', 8);
  v_total integer;
begin
  select id, name, faction into sy from systems where id = p_system and not coalesce(is_deep_space, false);
  if not found or sy.faction is null or sy.faction not in ('republic', 'cis') then return null; end if;
  select * into pl from planet_loyalty where system_id = p_system;
  if not found then return null; end if;
  v_side := loyalty_side(sy.faction);
  v_s := pl.value * v_side; v_home := pl.home * v_side;

  if v_home <> v_s then
    v_d := round((v_home - v_s) * game_setting_int('loyalty_drift_pct', 10) / 100.0)::integer;
    if v_d = 0 then v_d := sign(v_home - v_s)::integer; end if;
    v_sum := v_sum + v_d; v_rows := v_rows || jsonb_build_object('k', 'home', 'label', 'Исконные настроения', 'value', v_d);
  end if;

  v_eff := coalesce(settlement_effective(p_system), 0);
  if v_eff >= 70 then v_sum := v_sum + 2; v_rows := v_rows || jsonb_build_object('k', 'mood', 'label', 'Довольство 70+', 'value', 2);
  elsif v_eff >= 40 then v_sum := v_sum + 1; v_rows := v_rows || jsonb_build_object('k', 'mood', 'label', 'Довольство 40+', 'value', 1);
  elsif v_eff < 25 then v_sum := v_sum - 1; v_rows := v_rows || jsonb_build_object('k', 'mood', 'label', 'Довольство ниже 25', 'value', -1);
  end if;

  if exists (select 1 from settlement_riots r where r.system_id = p_system and r.status = 'active') then
    v_sum := v_sum - 4; v_rows := v_rows || jsonb_build_object('k', 'unrest', 'label', 'Мятеж', 'value', -4);
  else
    v_un := coalesce((select value from settlement_unrest where system_id = p_system), 0);
    if v_un >= 75 then v_sum := v_sum - 2; v_rows := v_rows || jsonb_build_object('k', 'unrest', 'label', 'Забастовки', 'value', -2);
    elsif v_un >= 50 then v_sum := v_sum - 1; v_rows := v_rows || jsonb_build_object('k', 'unrest', 'label', 'Волнения', 'value', -1); end if;
  end if;

  if not exists (select 1 from system_control sc where sc.system_id = p_system and sc.controller_user_id is not null) then
    v_sum := v_sum - 1; v_rows := v_rows || jsonb_build_object('k', 'ruler', 'label', 'Нет управляющего', 'value', -1);
  end if;

  v_gar := loyalty_garrison(p_system);
  if v_gar >= 5 then v_sum := v_sum + 1; v_rows := v_rows || jsonb_build_object('k', 'garrison', 'label', 'Гарнизон в поселении: ' || v_gar, 'value', 1); end if;

  if exists (select 1 from unit_positions x
              where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.carrier_ship_id is null
                and x.faction in ('republic', 'cis') and x.faction <> sy.faction) then
    v_sum := v_sum - 1; v_rows := v_rows || jsonb_build_object('k', 'enemy', 'label', 'Враг на планете', 'value', -1);
  end if;

  v_ef := effect_sum(p_system, 'loyalty');
  if v_ef <> 0 then v_sum := v_sum + v_ef; v_rows := v_rows || jsonb_build_object('k', 'effects', 'label', 'Законы и проекты', 'value', v_ef); end if;

  for c in select faction, level from loyalty_cells where system_id = p_system and faction <> sy.faction order by faction loop
    v_sum := v_sum - c.level;
    v_rows := v_rows || jsonb_build_object('k', 'cell', 'label', 'Подполье ' || case c.faction when 'republic' then 'Республики' else 'КНС' end
                                            || ' · ур. ' || c.level, 'value', -c.level);
  end loop;

  v_total := greatest(-v_cap, least(v_cap, v_sum));
  v_total := greatest(-100 - v_s, least(100 - v_s, v_total));
  return jsonb_build_object('delta', v_total, 'raw', v_sum, 'rows', v_rows, 'cap', v_cap, 's', v_s, 'home', v_home,
                            'eff', v_eff, 'garrison', v_gar);
end;
$$;


--
-- Name: loyalty_capital(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_capital(p_system text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_system = any(string_to_array(replace(coalesce((select value from game_settings where key = 'unrest_capitals'), ''), ' ', ''), ','));
$$;


--
-- Name: loyalty_day(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_day(p_system text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare sy record; pl planet_loyalty; c jsonb; r record; v_side integer; v_ch integer; v_gar integer; v_comms boolean;
  v_ctl uuid; v_del text := 'del' || 'ete from ';
begin
  if not loyalty_on('scale') then return; end if;
  select id, name, faction into sy from systems where id = p_system and not coalesce(is_deep_space, false);
  if not found or coalesce(sy.faction, '') not in ('republic', 'cis') then return; end if;
  insert into planet_loyalty (system_id, value, home) values (p_system, 0, 0) on conflict (system_id) do nothing;
  select * into pl from planet_loyalty where system_id = p_system for update;
  c := loyalty_calc(p_system);
  if c is null then return; end if;
  v_side := loyalty_side(sy.faction);
  perform loyalty_set(p_system, pl.value + (c ->> 'delta')::integer * v_side, c -> 'rows', 'day');

  -- Сеть врага раскрывается сама: донесения жителей и патрули гарнизона
  v_gar := coalesce((c ->> 'garrison')::integer, 0);
  v_comms := settlement_has_district(p_system, 'comms');
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  for r in select * from loyalty_cells where system_id = p_system and faction <> sy.faction for update loop
    v_ch := 10 + least(45, 3 * v_gar) + case when v_comms then 15 else 0 end;
    continue when random() * 100 >= v_ch;
    if r.level <= 1 then
      execute v_del || 'loyalty_cells where system_id = $1 and faction = $2' using p_system, r.faction;
    else
      update loyalty_cells set level = level - 1, updated_at = now() where system_id = p_system and faction = r.faction;
    end if;
    if v_ctl is not null then
      perform log_event(v_ctl, sy.faction, p_system, 'loyalty_cell_found',
        sy.name || ': ' || case when r.level <= 1 then 'подполье врага раскрыто и разгромлено' else 'часть подполья врага раскрыта · ур. ' || (r.level - 1) end,
        r.level - 1, 'private', jsonb_build_object('faction', r.faction, 'level', r.level - 1));
    end if;
    perform log_event(null, r.faction, p_system, 'loyalty_cell_lost',
      sy.name || ': ' || case when r.level <= 1 then 'сеть подполья раскрыта — её больше нет' else 'сеть подполья частично раскрыта · ур. ' || (r.level - 1) end,
      r.level - 1, 'faction', jsonb_build_object('level', r.level - 1));
  end loop;
end;
$_$;


--
-- Name: loyalty_garrison(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_garrison(p_system text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::integer from unit_positions x join unit_types t on t.id = x.unit_type join systems s on s.id = x.system_id
   where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.carrier_ship_id is null
     and not t.is_vehicle and x.faction = s.faction and x.owner_user_id is not null and is_in_settlement_zone(x.x, x.y);
$$;


--
-- Name: loyalty_grace_until(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_grace_until(p_system text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select pl.captured_at + make_interval(hours => game_setting_int('loyalty_grace_hours', 72))
    from planet_loyalty pl where pl.system_id = p_system;
$$;


--
-- Name: loyalty_map(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_map() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text;
begin
  select faction into v_fac from profiles where id = v_me;
  return jsonb_build_object(
    'enabled', loyalty_on('scale'), 'effects', loyalty_on('effects'), 'ops', loyalty_on('ops'), 'faction', v_fac, 'now', now(),
    'next_at', next_payout_at(),
    'planets', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.name, 'v', pl.value, 'home', pl.home, 'faction', s.faction,
        's', case when s.faction in ('republic', 'cis') then pl.value * loyalty_side(s.faction) end,
        'capital', loyalty_capital(s.id),
        'grace', case when pl.captured_at + make_interval(hours => game_setting_int('loyalty_grace_hours', 72)) > now()
                      then pl.captured_at + make_interval(hours => game_setting_int('loyalty_grace_hours', 72)) end,
        'trend', case when s.faction = v_fac then pl.last_delta * loyalty_side(s.faction) end,
        'cell', case when v_fac is null then null
                     when s.faction = v_fac then (select max(level) from loyalty_cells c where c.system_id = s.id and c.faction <> v_fac)
                     else (select level from loyalty_cells c where c.system_id = s.id and c.faction = v_fac) end,
        'goal', case when s.faction in ('republic', 'cis') then capture_goal(s.id) end)
        order by s.name), '[]'::jsonb)
      from systems s join planet_loyalty pl on pl.system_id = s.id
     where not coalesce(s.is_deep_space, false)),
    'base', game_setting_int('capture_seconds', 60));
end;
$$;


--
-- Name: loyalty_militia_k(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_militia_k(p_system text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s integer; v_k numeric; v_g timestamptz;
begin
  if not loyalty_on('effects') then return 1; end if;
  v_s := loyalty_support(p_system);
  if v_s is null then return 1; end if;
  v_k := (loyalty_stage_of(v_s) ->> 'mi')::numeric;
  v_g := loyalty_grace_until(p_system);
  if v_g is not null and v_g > now() then v_k := greatest(v_k, 0.5); end if;
  return v_k;
end;
$$;


--
-- Name: loyalty_on(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_on(p_what text DEFAULT 'effects'::text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select game_setting_int('loyalty_enabled', 1) = 1
     and (p_what = 'scale' or game_setting_int('loyalty_' || p_what || '_enabled', 1) = 1);
$$;


--
-- Name: loyalty_on_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_on_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_del text := 'del' || 'ete from ';
begin
  if new.faction is distinct from old.faction then
    insert into planet_loyalty (system_id, value, home) values (new.id, 0, 0) on conflict (system_id) do nothing;
    update planet_loyalty set captured_at = now(), partisans_at = null, updated_at = now() where system_id = new.id;
    execute v_del || 'loyalty_cells where system_id = $1' using new.id;
    update faction_effects set ends_at = now() where system_id = new.id and source = 'loyalty' and ends_at > now();
    update loyalty_sweeps set status = 'void', result = jsonb_build_object('why', 'captured') where system_id = new.id and status = 'go';
  end if;
  return null;
end;
$_$;


--
-- Name: loyalty_set(text, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_set(p_system text, p_new integer, p_rows jsonb, p_why text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sy record; pl planet_loyalty; v_side integer; v_old_s integer; v_new_s integer; s_old jsonb; s_new jsonb;
  v_ctl uuid; v_lead uuid; v_to uuid; v_enemy text; v_meta jsonb; v_new integer := greatest(-100, least(100, p_new));
begin
  if p_new is null then raise exception 'loyalty_set: пустое значение шкалы (%)', p_system; end if;
  select id, name, faction into sy from systems where id = p_system;
  select * into pl from planet_loyalty where system_id = p_system for update;
  if not found then
    insert into planet_loyalty (system_id, value, home) values (p_system, 0, 0) returning * into pl;
  end if;
  v_side := loyalty_side(sy.faction);
  update planet_loyalty set value = v_new, updated_at = now(),
         last_delta = case when p_why = 'day' then v_new - pl.value else last_delta end,
         last_rows = case when p_why = 'day' then p_rows else last_rows end,
         last_at = case when p_why = 'day' then now() else last_at end
   where system_id = p_system;
  insert into planet_loyalty_log (system_id, value, delta, owner, rows)
  values (p_system, v_new, v_new - pl.value, sy.faction, case when p_why = 'day' then p_rows else jsonb_build_array(jsonb_build_object('k', p_why)) end);

  if v_side = 0 then return v_new; end if;
  v_old_s := pl.value * v_side; v_new_s := v_new * v_side;

  -- «Народ предан»: доход и добыча +5 % до следующей выдачи (как штрафы напряжения, sql/unrest_riot.sql)
  update faction_effects set ends_at = now() where system_id = p_system and source = 'loyalty' and ends_at > now();
  if loyalty_on('effects') and v_new_s >= 80 then
    insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at)
    select sy.faction, k, 5, 'Народ предан', 'loyalty', p_system, now(), next_payout_at() + interval '1 hour'
      from unnest(array['extract', 'income']) k;
  end if;

  s_old := loyalty_stage_of(v_old_s); s_new := loyalty_stage_of(v_new_s);
  if (s_new ->> 'n')::integer = (s_old ->> 'n')::integer then return v_new; end if;

  select controller_user_id into v_ctl from system_control where system_id = p_system;
  select leader_user_id into v_lead from faction_leadership where faction = sy.faction;
  v_meta := jsonb_build_object('value', v_new_s, 'prev', v_old_s, 'state', s_new ->> 'k', 'state_t', s_new ->> 't', 'planet', sy.name,
                               'up', (s_new ->> 'n')::integer > (s_old ->> 'n')::integer);
  for v_to in select distinct x from unnest(array[v_ctl, v_lead]) x where x is not null loop
    perform log_event(v_to, sy.faction, p_system, 'loyalty_stage', sy.name || ': народ ' || (s_new ->> 't') || ' · ' || v_new_s, v_new_s, 'private', v_meta);
  end loop;
  -- Врагу — когда планета качнулась к нему до подполья и ниже: окно для наступления
  if (s_new ->> 'n')::integer <= -2 and (s_new ->> 'n')::integer < (s_old ->> 'n')::integer then
    v_enemy := case sy.faction when 'republic' then 'cis' else 'republic' end;
    perform log_event(null, v_enemy, p_system, 'loyalty_chance', sy.name || ': народ ' || (s_new ->> 't'), -v_new_s, 'faction',
                      v_meta || jsonb_build_object('value', -v_new_s, 'prev', -v_old_s));
  end if;
  return v_new;
end;
$$;


--
-- Name: loyalty_side(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_side(p_faction text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_faction when 'republic' then 1 when 'cis' then -1 else 0 end;
$$;


--
-- Name: loyalty_stage_of(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_stage_of(p_s integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_s >= 80  then '{"k":"devoted","t":"предан","n":3,"m":2,"mi":1.5}'::jsonb
    when p_s >= 50  then '{"k":"loyal","t":"верен","n":2,"m":1.5,"mi":1.25}'::jsonb
    when p_s >= 20  then '{"k":"calm","t":"спокоен","n":1,"m":1,"mi":1}'::jsonb
    when p_s >= -19 then '{"k":"waver","t":"колеблется","n":0,"m":0.8,"mi":0.5}'::jsonb
    when p_s >= -49 then '{"k":"murmur","t":"ропщет","n":-1,"m":0.6,"mi":0}'::jsonb
    when p_s >= -79 then '{"k":"under","t":"ушёл в подполье","n":-2,"m":0.35,"mi":0}'::jsonb
    else                 '{"k":"wait","t":"ждёт врага","n":-3,"m":0.2,"mi":0}'::jsonb end;
$$;


--
-- Name: loyalty_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_state(p_system text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; sy record; pl planet_loyalty; v_side integer; v_s integer; v_own boolean; v_hist jsonb;
  v_res jsonb; v_g timestamptz; v_enemy text; v_cell integer; v_bat jsonb; w loyalty_sweeps; v_last timestamptz;
begin
  if v_me is null then return null; end if;
  select faction into v_fac from profiles where id = v_me;
  select id, name, faction into sy from systems where id = p_system and not coalesce(is_deep_space, false);
  if not found then return null; end if;
  select * into pl from planet_loyalty where system_id = p_system;
  if not found then return null; end if;
  v_side := loyalty_side(sy.faction);
  v_s := case when v_side <> 0 then pl.value * v_side end;
  v_own := v_fac is not null and sy.faction = v_fac;
  v_g := loyalty_grace_until(p_system);
  v_enemy := case sy.faction when 'republic' then 'cis' when 'cis' then 'republic' end;

  v_res := jsonb_build_object(
    'enabled', loyalty_on('scale'), 'effects', loyalty_on('effects'), 'ops', loyalty_on('ops'),
    'system', p_system, 'name', sy.name, 'faction', sy.faction, 'mine', v_own,
    'v', pl.value, 'home', pl.home, 's', v_s, 'stage', case when v_s is not null then loyalty_stage_of(v_s) end,
    'capital', loyalty_capital(p_system), 'grace', case when v_g > now() then v_g end,
    'goal', case when v_s is not null then capture_goal(p_system) end, 'base', game_setting_int('capture_seconds', 60),
    'next_at', next_payout_at());

  if v_own then
    select coalesce(jsonb_agg(jsonb_build_object('at', l.at, 'value', l.value * v_side, 'delta', l.delta * v_side) order by l.at), '[]'::jsonb)
      into v_hist from (select * from planet_loyalty_log where system_id = p_system and owner = sy.faction order by at desc limit 10) l;
    select * into w from loyalty_sweeps where system_id = p_system and status = 'go' order by started_at desc limit 1;
    select max(started_at) into v_last from loyalty_sweeps where system_id = p_system and status in ('ok', 'fail');
    v_res := v_res || jsonb_build_object(
      'forecast', loyalty_calc(p_system), 'history', v_hist,
      'last_delta', case when pl.last_delta is not null then pl.last_delta * v_side end, 'last_rows', coalesce(pl.last_rows, '[]'::jsonb), 'last_at', pl.last_at,
      'cells', (select coalesce(jsonb_agg(jsonb_build_object('faction', c.faction, 'level', c.level, 'since', c.created_at)), '[]'::jsonb)
                  from loyalty_cells c where c.system_id = p_system and c.faction <> sy.faction),
      'militia_k', loyalty_militia_k(p_system),
      'sweep', jsonb_build_object(
        'active', case when w.id is not null then jsonb_build_object('id', w.id, 'started_at', w.started_at, 'resolves_at', w.resolves_at) end,
        'block', loyalty_sweep_block(p_system, v_me),
        'chance', loyalty_sweep_chance(p_system), 'garrison', loyalty_garrison(p_system),
        'need', game_setting_int('loyalty_sweep_need', 5), 'cost', game_setting_int('loyalty_sweep_cost', 300),
        'minutes', game_setting_int('loyalty_sweep_min', 120),
        'cd_until', case when v_last is not null then v_last + make_interval(hours => game_setting_int('loyalty_sweep_cd_h', 24)) end,
        'last', (select jsonb_build_object('status', x.status, 'at', x.resolves_at, 'chance', x.chance) from loyalty_sweeps x
                  where x.system_id = p_system and x.status in ('ok', 'fail') order by x.started_at desc limit 1)),
      'effects', (select coalesce(jsonb_agg(jsonb_build_object('kind', fe.kind, 'value', fe.value, 'title', fe.title, 'source', fe.source, 'ends', fe.ends_at)), '[]'::jsonb)
                    from faction_effects fe where fe.faction = sy.faction and (fe.system_id is null or fe.system_id = p_system)
                     and fe.kind = 'loyalty' and fe.starts_at <= now() and fe.ends_at > now()));
  elsif v_fac in ('republic', 'cis') and v_s is not null then
    select level into v_cell from loyalty_cells where system_id = p_system and faction = v_fac;
    v_bat := loyalty_battle(p_system);
    v_res := v_res || jsonb_build_object(
      'cell', v_cell, 'agit_cd', loyalty_agit_cd(p_system, v_fac),
      'partisans', case when loyalty_capital(p_system) or (v_g is not null and v_g > now()) then 0
                        else least(9, coalesce(v_cell, 0) * 2 + case when v_s <= -80 then 3 when v_s <= -50 and v_cell is not null then 1 else 0 end) end,
      'intel', case when v_bat ->> 'reveal' = v_fac then jsonb_build_object(
          'infantry', (select count(*) from unit_positions x join unit_types t on t.id = x.unit_type
                        where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.faction = sy.faction
                          and not t.is_vehicle and not coalesce(t.is_hero, false) and is_in_settlement_zone(x.x, x.y)),
          'vehicles', (select count(*) from unit_positions x join unit_types t on t.id = x.unit_type
                        where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.faction = sy.faction and t.is_vehicle),
          'heroes', (select count(*) from unit_positions x join unit_types t on t.id = x.unit_type
                        where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.faction = sy.faction and coalesce(t.is_hero, false)),
          'militia', settlement_militia_count(p_system)) end);
  end if;
  return v_res;
end;
$$;


--
-- Name: loyalty_support(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_support(p_system text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select pl.value * loyalty_side(s.faction)
    from systems s join planet_loyalty pl on pl.system_id = s.id
   where s.id = p_system and s.faction in ('republic', 'cis');
$$;


--
-- Name: loyalty_sweep(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_sweep(p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_why text; v_cost integer := game_setting_int('loyalty_sweep_cost', 300); sy record; v_id uuid;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  perform 1 from profiles where id = v_me for update;
  perform 1 from planet_loyalty where system_id = p_system for update;
  v_why := loyalty_sweep_block(p_system, v_me);
  if v_why is not null then raise exception '%', v_why; end if;
  select id, name, faction into sy from systems where id = p_system;
  update profiles set credits = credits - v_cost where id = v_me;
  insert into loyalty_sweeps (system_id, faction, user_id, resolves_at, cost)
  values (p_system, sy.faction, v_me, now() + make_interval(mins => game_setting_int('loyalty_sweep_min', 120)), v_cost)
  returning id into v_id;
  perform log_event(v_me, sy.faction, p_system, 'loyalty_sweep', sy.name || ': облава началась — итог через ' ||
                    case when game_setting_int('loyalty_sweep_min', 120) % 60 = 0 then (game_setting_int('loyalty_sweep_min', 120) / 60)::text || ' ч'
                         else game_setting_int('loyalty_sweep_min', 120)::text || ' мин' end, v_cost, 'private', jsonb_build_object('sweep', v_id));
  return loyalty_state(p_system);
end;
$$;


--
-- Name: loyalty_sweep_block(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_sweep_block(p_system text, p_user uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sy record; v_fac text; v_ctl uuid; v_last timestamptz; v_need integer := game_setting_int('loyalty_sweep_need', 5); v_gar integer;
begin
  if not loyalty_on('ops') then return 'Облавы сейчас недоступны'; end if;
  select faction into v_fac from profiles where id = p_user;
  select id, faction into sy from systems where id = p_system;
  if v_fac is null or sy.faction is distinct from v_fac then return 'Облава — только на своей планете'; end if;
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  if v_ctl is distinct from p_user and not is_faction_leader(p_user, v_fac) then return 'Облаву объявляет управляющий планетой или лидер фракции'; end if;
  if not exists (select 1 from loyalty_cells where system_id = p_system and faction <> sy.faction) then return 'Подполья врага на планете нет'; end if;
  if exists (select 1 from loyalty_sweeps where system_id = p_system and status = 'go') then return 'Облава уже идёт'; end if;
  select max(started_at) into v_last from loyalty_sweeps where system_id = p_system and status in ('ok', 'fail');
  if v_last > now() - make_interval(hours => game_setting_int('loyalty_sweep_cd_h', 24)) then
    return 'Следующая облава — через ' || ceil(extract(epoch from v_last + make_interval(hours => game_setting_int('loyalty_sweep_cd_h', 24)) - now()) / 3600) || ' ч';
  end if;
  v_gar := loyalty_garrison(p_system);
  if v_gar < v_need then return 'Нужно не меньше ' || v_need || ' своих бойцов в поселении (сейчас ' || v_gar || ')'; end if;
  if coalesce((select credits from profiles where id = p_user), 0) < game_setting_int('loyalty_sweep_cost', 300) then
    return 'Не хватает кредитов: нужно ' || game_setting_int('loyalty_sweep_cost', 300);
  end if;
  return null;
end;
$$;


--
-- Name: loyalty_sweep_chance(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_sweep_chance(p_system text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select least(90, least(85, 40 + 4 * loyalty_garrison(p_system)) + case when settlement_has_district(p_system, 'comms') then 10 else 0 end);
$$;


--
-- Name: loyalty_sweep_finish(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_sweep_finish(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare w loyalty_sweeps; sy record; pl planet_loyalty; c loyalty_cells; v_ch integer; v_roll numeric; v_gain integer := game_setting_int('loyalty_sweep_gain', 3);
  v_new integer; v_del text := 'del' || 'ete from ';
begin
  select * into w from loyalty_sweeps where id = p_id and status = 'go' for update;
  if not found then return; end if;
  select id, name, faction into sy from systems where id = w.system_id;
  if sy.faction is distinct from w.faction then
    update loyalty_sweeps set status = 'void', result = jsonb_build_object('why', 'captured') where id = p_id;
    return;
  end if;
  select * into pl from planet_loyalty where system_id = w.system_id for update;
  select * into c from loyalty_cells where system_id = w.system_id and faction <> sy.faction order by level desc, created_at limit 1 for update;
  if not found then
    update loyalty_sweeps set status = 'void', result = jsonb_build_object('why', 'no_cell') where id = p_id;
    perform log_event(w.user_id, sy.faction, w.system_id, 'loyalty_sweep', sy.name || ': облава — подполья уже нет, ловить некого', 0, 'private', jsonb_build_object('sweep', w.id));
    return;
  end if;
  v_ch := loyalty_sweep_chance(w.system_id);
  v_roll := random() * 100;
  if v_roll < v_ch then
    execute v_del || 'loyalty_cells where system_id = $1 and faction = $2' using w.system_id, c.faction;
    v_new := loyalty_set(w.system_id, pl.value + v_gain * loyalty_side(sy.faction), null, 'sweep');
    update loyalty_sweeps set status = 'ok', chance = v_ch, roll = v_roll, result = jsonb_build_object('faction', c.faction, 'level', c.level, 'gain', v_gain) where id = p_id;
    perform log_event(w.user_id, sy.faction, w.system_id, 'loyalty_sweep',
      sy.name || ': облава удалась — подполье ' || case c.faction when 'republic' then 'Республики' else 'КНС' end || ' разгромлено, поддержка +' || v_gain,
      v_gain, 'private', jsonb_build_object('sweep', w.id, 'ok', true));
    perform log_event(null, c.faction, w.system_id, 'loyalty_cell_lost', sy.name || ': облава — сеть подполья разгромлена', 0, 'faction', jsonb_build_object('level', 0));
  else
    v_new := loyalty_set(w.system_id, pl.value - 1 * loyalty_side(sy.faction), null, 'sweep_fail');
    update loyalty_sweeps set status = 'fail', chance = v_ch, roll = v_roll, result = jsonb_build_object('faction', c.faction, 'level', c.level) where id = p_id;
    perform log_event(w.user_id, sy.faction, w.system_id, 'loyalty_sweep',
      sy.name || ': облава впустую — подполье ушло, жители озлоблены · поддержка −1 · шанс был ' || v_ch || ' %', -1, 'private', jsonb_build_object('sweep', w.id, 'ok', false));
  end if;
end;
$_$;


--
-- Name: loyalty_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record;
begin
  for r in select id from loyalty_sweeps where status = 'go' and resolves_at <= now() order by resolves_at loop
    begin perform loyalty_sweep_finish(r.id);
    exception when others then perform err_db('loyalty_tick', sqlstate, sqlerrm, true); end;
  end loop;
end;
$$;


--
-- Name: marauder_alarm(uuid, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marauder_alarm(p_attacker uuid, p_system text, p_faction text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_x is null or p_y is null then return; end if;
  if not exists (select 1 from npc_brains b where b.unit_id = p_attacker and b.kind = 'marauder') then
    return;
  end if;
  if p_faction is distinct from (select faction from systems where id = p_system) then return; end if;
  if not exists (select 1 from settlement_zone_box() z
                 where box_gap(p_x, p_y, coalesce(p_w, 1), coalesce(p_h, 1), z.x, z.y, z.size, z.size)
                       <= game_setting_int('marauder_militia_margin', 4)) then
    return;
  end if;
  perform raise_militia(p_system);
exception when others then perform err_db('marauder_alarm', sqlstate, sqlerrm, true);
  raise warning 'marauder_alarm %: %', p_system, sqlerrm;
end;
$$;


--
-- Name: marauder_hhmm(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marauder_hhmm(p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select to_char(p_at at time zone server_tz(), 'HH24:MI') || ' ' ||
         coalesce((select value from game_settings where key = 'server_tz_label'), 'МСК');
$$;


--
-- Name: marauder_notify(text, text, text, integer, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marauder_notify(p_system text, p_type text, p_subject text, p_amount integer, p_meta jsonb, p_near boolean) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; v_n integer := 0;
  v_r integer := game_setting_int('marauder_notify_radius', 15);
  v_fac text := (select faction from systems where id = p_system);
begin
  if v_fac is null then return 0; end if;
  for r in
    select distinct on (q.uid) q.uid
    from (select c.controller_user_id as uid, null::text as fac
          from system_control c
          where c.system_id = p_system and c.controller_user_id is not null
          union all
          select u.owner_user_id, u.faction
          from unit_positions u
          join unit_types ut on ut.id = u.unit_type
          cross join settlement_zone_box() z
          where p_near and u.system_id = p_system and u.layer = 'ground' and u.x is not null
            and u.hp > 0 and u.owner_user_id is not null and u.faction = v_fac
            and box_gap(u.x, u.y, ut.width_cells, ut.height_cells, z.x, z.y, z.size, z.size) <= v_r) q
    left join profiles p on p.id = q.uid
    where coalesce(p.faction, q.fac) = v_fac
    order by q.uid
  loop
    perform log_event(r.uid, v_fac, p_system, p_type, p_subject, p_amount, 'private', p_meta);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: marauder_raid_slot(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marauder_raid_slot(p_cycle timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tz text := server_tz();
  v_ph integer := game_setting_int('payout_hour', 4);
  v_day timestamp;
  v_lo timestamptz; v_hi timestamptz; v_end timestamptz; v_steps integer;
begin
  v_day := date_trunc('day', (p_cycle at time zone v_tz) - make_interval(hours => v_ph));
  v_lo := (v_day + make_interval(hours => game_setting_int('marauder_window_start', 12))) at time zone v_tz;
  v_hi := (v_day + make_interval(hours => game_setting_int('marauder_window_end', 20))) at time zone v_tz;
  v_end := (v_day + interval '1 day' + make_interval(hours => v_ph)) at time zone v_tz;
  v_hi := least(v_hi, v_end - make_interval(hours => game_setting_int('marauder_raid_hours', 3)));
  v_lo := greatest(v_lo, now() + make_interval(mins => game_setting_int('marauder_warn_minutes', 30)));
  v_lo := to_timestamp(ceil(extract(epoch from v_lo) / 300) * 300);
  if v_lo >= v_hi then return null; end if;
  v_steps := floor(extract(epoch from v_hi - v_lo) / 300)::integer;
  return v_lo + make_interval(mins => 5 * floor(random() * greatest(1, v_steps))::integer);
end;
$$;


--
-- Name: marauder_raid_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marauder_raid_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t record; ld record;
  v_stage text; v_at timestamptz; v_end timestamptz; v_ids uuid[]; v_gang uuid[];
  v_alive integer; v_n integer; v_acts integer := 0;
  v_warn integer := game_setting_int('marauder_warn_minutes', 30);
begin
  -- Брошенный мародёр без мозга (налёт стёрся) уходит. Кроме цели обучения: она ждёт игрока.
  insert into npc_brains (unit_id, kind, system_id, home_x, home_y, leash, state, last_hp)
  select u.id, 'marauder', u.system_id, coalesce(u.x, 0), coalesce(u.y, 0), 8, 'leave', u.hp
  from unit_positions u
  where u.faction = 'marauder' and u.owner_user_id is null
    and coalesce(u.updated_at, '-infinity'::timestamptz) < now() - interval '10 minutes'
    and not exists (select 1 from npc_brains b where b.unit_id = u.id)
    and not exists (select 1 from tutorial_state ts
                    where ts.status = 'active' and ts.meta ->> 'target_id' = u.id::text)
  on conflict (unit_id) do nothing;

  for t in
    select tk.id, tk.system_id, tk.payload
    from settlement_tasks tk
    join settlement_state st on st.system_id = tk.system_id and st.cycle_started = tk.cycle_start
    join systems sy on sy.id = tk.system_id
    where tk.kind = 'marauder' and sy.faction is not null
      and coalesce(tk.payload ->> 'stage', '') in ('scouted', 'warned', 'raid', 'escaped', 'cancelled')
    order by tk.system_id
    for update of tk skip locked
  loop
    v_stage := t.payload ->> 'stage';
    v_ids := array(select j.v::uuid
                   from jsonb_array_elements_text(coalesce(t.payload -> 'unit_ids', '[]'::jsonb)) j(v));

    if v_stage in ('escaped', 'cancelled') then
      update npc_brains set state = 'leave'
      where unit_id = any(v_ids) and state is distinct from 'leave';
      continue;
    end if;

    v_at := (t.payload ->> 'raid_at')::timestamptz;
    v_end := (t.payload ->> 'raid_ends')::timestamptz;
    continue when v_at is null or v_end is null;

    if v_stage = 'scouted' and now() < v_at and now() >= v_at - make_interval(mins => v_warn) then
      perform marauder_notify(t.system_id, 'marauder_approach',
                              'Банда будет у поселения около ' || marauder_hhmm(v_at), 1,
                              jsonb_build_object('raid_at', v_at), true);
      update settlement_tasks
      set payload = payload || jsonb_build_object('stage', 'warned', 'warned_at', now())
      where id = t.id;
      v_acts := v_acts + 1;

    elsif v_stage in ('scouted', 'warned') and now() >= v_at then
      if now() >= v_end then
        update settlement_tasks set payload = payload || jsonb_build_object('stage', 'calm') where id = t.id;
        continue;
      end if;

      v_n := case when settlement_effective(t.system_id) < 30 then 2 + floor(random() * 2)::integer else 1 end;
      v_gang := spawn_marauder_gang(t.system_id, v_n);
      continue when coalesce(array_length(v_gang, 1), 0) = 0;
      v_n := array_length(v_gang, 1);

      update settlement_tasks
      set target = v_n,
          payload = payload || jsonb_build_object('stage', 'raid', 'unit_id', v_gang[1],
                                                  'unit_ids', to_jsonb(v_gang), 'spawned_at', now())
      where id = t.id;

      select u.x, u.y into ld from unit_positions u where u.id = v_gang[1];
      perform marauder_notify(t.system_id, 'marauder_raid',
        case when v_n > 1 then 'Банда: ' || ru_plural(v_n, 'налётчик', 'налётчика', 'налётчиков')
             else 'Одиночный налётчик' end || ' · уйдёт около ' || marauder_hhmm(v_end),
        1, jsonb_build_object('count', v_n, 'x', ld.x, 'y', ld.y, 'raid_ends', v_end), true);
      v_acts := v_acts + 1;

    elsif v_stage = 'raid' then
      select count(*) into v_alive from unit_positions u where u.id = any(v_ids) and u.hp > 0;
      -- Самооборона (sql/settlement_conditions.sql): на планете нет живого боя, а своих бойцов в зоне
      -- поселения не меньше, чем налётчиков, — гарнизон отбивает налёт сам, условие выполнено
      if v_alive > 0
         and not exists (select 1 from rt_battles rb where rb.system_id = t.system_id and rb.status = 'active'
                            and rb.heartbeat_at > now() - interval '2 minutes')
         and (select count(*) from unit_positions g join systems gs on gs.id = g.system_id
               where g.system_id = t.system_id and g.layer = 'ground' and g.hp > 0 and g.x is not null
                 and g.carrier_ship_id is null and g.owner_user_id is not null and g.faction = gs.faction
                 and is_in_settlement_zone(g.x, g.y)) >= v_alive then
        update unit_positions set hp = 0 where id = any(v_ids) and hp > 0;
        update npc_brains set state = 'leave' where unit_id = any(v_ids);
        update settlement_tasks
        set payload = payload || jsonb_build_object('stage', 'defeated', 'garrison', true, 'ended_at', now())
        where id = t.id;
        perform marauder_notify(t.system_id, 'marauder_defeated', 'Гарнизон отбил налёт · условие выполнено', 1,
                                jsonb_build_object('count', cardinality(v_ids), 'garrison', true), true);
        v_acts := v_acts + 1;
        continue;
      end if;
      if v_alive = 0 then
        update settlement_tasks
        set payload = payload || jsonb_build_object('stage', 'defeated', 'ended_at', now())
        where id = t.id;
        perform marauder_notify(t.system_id, 'marauder_defeated',
                                'Банда разбита · условие выполнено', 1,
                                jsonb_build_object('count', cardinality(v_ids)), true);
        v_acts := v_acts + 1;
      elsif now() >= v_end then
        update settlement_tasks
        set payload = payload || jsonb_build_object('stage', 'escaped', 'escaped', true,
                                                    'left', v_alive, 'ended_at', now())
        where id = t.id;
        update npc_brains set state = 'leave' where unit_id = any(v_ids);
        perform marauder_notify(t.system_id, 'marauder_left',
                                'Ушло ' || ru_plural(v_alive, 'налётчик', 'налётчика', 'налётчиков') ||
                                ' · условие провалено', 1,
                                jsonb_build_object('count', v_alive), true);
        v_acts := v_acts + 1;
      end if;
    end if;
  end loop;
  return v_acts;
end;
$$;


--
-- Name: marauder_task_view(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marauder_task_view(p jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(p, '{}'::jsonb) || jsonb_build_object(
    'alive', (select count(*) from unit_positions u
              where u.hp > 0
                and u.id in (select j.v::uuid
                             from jsonb_array_elements_text(coalesce(p -> 'unit_ids', '[]'::jsonb)) j(v))),
    'total', jsonb_array_length(coalesce(p -> 'unit_ids', '[]'::jsonb)));
$$;


--
-- Name: mark_events_seen(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_events_seen(p_category text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_n integer;
begin
  update game_events g
  set seen_at = now()
  where g.user_id = auth.uid() and g.seen_at is null
    and (p_category is null
         or coalesce((select category from event_types e where e.type = g.type), 'build')
            = p_category);

  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


--
-- Name: mark_hero_dead(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_hero_dead() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare h record;
begin
  if old.hero_id is not null then
    update heroes set died_at = now(), died_system_id = old.system_id
    where id = old.hero_id and died_at is null;

    select name, owner_user_id, faction into h from heroes where id = old.hero_id;

    if h.owner_user_id is not null then
      perform log_event(h.owner_user_id, h.faction, old.system_id, 'hero_died',
                        h.name, 1, 'private',
                        jsonb_build_object('x', old.x, 'y', old.y));
    end if;
  end if;
  return old;
end;
$$;


--
-- Name: market_expire_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_expire_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare o record; v_back integer;
begin
  for o in
    select * from market_orders mo
     where mo.status = 'reserved' and mo.expires_at <= now()
       and not (mo.expires_at > now() - interval '6 hours'
                and exists (select 1 from supply_routes sr where sr.order_id = mo.id and sr.status = 'active'))
     for update skip locked
  loop
    begin
      v_back := o.amount_left * o.price_per_unit;
      update profiles set credits = credits + v_back where id = o.buyer_user_id;
      update market_lots set amount_left = amount_left + o.amount_left where id = o.lot_id;
      update market_orders set status = 'expired', amount_left = 0 where id = o.id;
      perform log_event(o.buyer_user_id, null, null, 'market_expired', null, v_back, 'private', null);
    exception when others then
      perform err_db('market_expire_tick', sqlstate, sqlerrm, true);
    end;
  end loop;
end;
$$;


--
-- Name: mine_accrue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_accrue(p_shift uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sh mine_shifts; v_to timestamptz; v_h numeric;
begin
  select * into sh from mine_shifts where id = p_shift and status = 'run' for update;
  if not found then return; end if;
  v_to := least(now(), sh.ends_at);
  v_h := extract(epoch from v_to - sh.last_tick) / 3600.0;
  if v_h <= 0 then return; end if;
  update mine_shifts
     set accrued = least(coalesce(cap, 1e9), accrued + base_rate * greatest(0, 100 + effect_sum(system_id, 'extract')) / 100.0 * v_h),
         last_tick = v_to
   where id = p_shift;
end;
$$;


--
-- Name: mine_auto_set(uuid, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_auto_set(p_building uuid, p_on boolean, p_len integer, p_pace text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites;
begin
  s := mine_own(p_building);
  if p_len not in (8, 12, 16) then raise exception 'Автосмена — 8, 12 или 16 часов'; end if;
  if p_pace not in ('careful', 'normal', 'rush') then raise exception 'Нет такого темпа'; end if;
  update mine_sites set auto_on = coalesce(p_on, false), auto_len = p_len, auto_pace = p_pace where building_id = p_building;
  return mine_site_state(p_building);
end;
$$;


--
-- Name: mine_avail(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_avail(p_building uuid, p_kind text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(0,
           (select case when p_kind = 'h' then ms.humans else ms.droids end from mine_sites ms where ms.building_id = p_building)
         - coalesce((select sum(n) from mine_hurt h where h.building_id = p_building and h.kind = p_kind and h.until > now()), 0)
         - coalesce((select case when p_kind = 'h' then sh.humans else sh.droids end from mine_shifts sh where sh.building_id = p_building and sh.status = 'run'), 0))::integer;
$$;


--
-- Name: mine_day_estimate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_day_estimate(p_building uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v_h integer; v_d integer; v_rate numeric; v_rest integer;
begin
  select * into s from mine_sites where building_id = p_building;
  if not found or not s.auto_on or s.gone then return 0; end if;
  v_d := least(s.droids, s.places); v_h := least(s.humans, s.places - v_d);
  if v_h + v_d = 0 then return 0; end if;
  v_rate := mine_rate_h(s.system_id, s.resource, v_h, v_d, s.auto_len, s.auto_pace, true, true)
          * coalesce(mine_mult(p_building, 'extract'), 1)
          * greatest(0, 100 + effect_sum(s.system_id, 'extract')) / 100.0;
  v_rest := greatest(case when v_h > 0 then mine_rest_min('h', s.auto_len, s.auto_pace) else 0 end,
                     case when v_d > 0 then mine_rest_min('d', s.auto_len, s.auto_pace) else 0 end);
  return floor(v_rate * s.auto_len * 24.0 / (s.auto_len + v_rest / 60.0))::integer;
end;
$$;


--
-- Name: mine_finish(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_finish(p_shift uuid, p_status text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sh mine_shifts; s mine_sites; v_got integer; v_put integer; v_end timestamptz; v_hours numeric; v_n integer;
  v_ctrl uuid; v_fac text; v_hurt numeric := game_setting_int('mine_rush_hurt_pct', 10); v_wear numeric; v_pw numeric;
  v_res text; v_hh integer; v_hd integer; v_full boolean; v_chance numeric; v_ref boolean; v_used jsonb; k text; v_back integer;
begin
  perform mine_accrue(p_shift);
  select * into sh from mine_shifts where id = p_shift and status = 'run' for update;
  if not found then return 0; end if;
  select * into s from mine_sites where building_id = sh.building_id for update;
  v_end := least(now(), sh.ends_at);
  v_hours := greatest(0, extract(epoch from v_end - sh.started_at) / 3600.0);
  v_full := v_hours >= sh.len_h * 0.5;                        -- задача засчитывается, если отработали хотя бы половину
  v_got := case when p_status = 'lost' then 0 else round(sh.accrued)::integer end;
  v_ref := mine_is_refine(sh.resource);
  -- цех: сырьё ушло на сделанное, остаток взятого возвращается на склад планеты (сорванная смена — пропало)
  if sh.input is not null then
    v_used := '{}'::jsonb;
    for k in select jsonb_object_keys(sh.input) loop
      v_n := least((sh.input ->> k)::integer, ceil(v_got * coalesce((sh.input_k ->> k)::numeric, 0))::integer);
      v_used := v_used || jsonb_build_object(k, case when p_status = 'lost' then (sh.input ->> k)::integer else v_n end);
      v_back := (sh.input ->> k)::integer - v_n;
      if p_status <> 'lost' and v_back > 0 then
        perform add_planet_stock(sh.system_id, k, v_back);   -- в пределах склада планеты, как вся добыча
      end if;
    end loop;
    update mine_shifts set input_used = v_used where id = p_shift;
  end if;
  if s.building_id is null then
    update mine_shifts set status = p_status, ended_at = v_end, delivered = v_got where id = p_shift;
    return v_got;
  end if;
  v_put := least(v_got, greatest(0, mine_site_cap(s.system_id) - coalesce(s.stock, 0)));
  -- износ: отработанные часы бригады; обслуживание — наоборот, чинит
  v_pw := case sh.pace when 'careful' then 0.5 when 'rush' then 2 else 1 end
        * case when settlement_has_district(s.system_id, 'workshops') then 0.7 else 1 end;
  if sh.task = 'maint' then
    v_wear := - (sh.humans + sh.droids) * v_hours * 2 * (1 + 0.5 * least(s.techs, mine_max_techs(s.places)));
    v_res := 'износ −' || round(least(s.wear, -v_wear))::integer || ' %';
  else
    v_wear := v_hours * v_pw * (sh.humans * game_setting_int('mine_wear_h_x100', 8) + sh.droids * game_setting_int('mine_wear_d_x100', 18)) / 100.0
            * case when sh.task = 'survey' then 0.5 else 1 end;
  end if;
  if sh.task = 'prep' and p_status <> 'lost' then
    if v_full then update mine_sites set prep_bonus = 25 where building_id = sh.building_id;
      v_res := case when v_ref then 'линия налажена: следующая переработка +25 %' else 'вскрыша готова: следующая добыча +25 %' end;
    else v_res := case when v_ref then 'наладка не закончена' else 'вскрыша не закончена' end; end if;
  elsif sh.task = 'survey' and p_status <> 'lost' then
    v_chance := least(0.6, 0.12 * v_hours * (sh.humans + sh.droids) / 6.0);
    if random() < v_chance then
      update mine_sites set vein_until = greatest(coalesce(vein_until, now()), now()) + interval '24 hours' where building_id = sh.building_id;
      v_res := case when v_ref then 'режим отлажен: сырья на 25 % меньше на 24 ч' else 'найдена богатая жила: +40 % на 24 ч' end;
    else v_res := case when v_ref then 'отладить режим не вышло' else 'жилы не нашли' end || ' (шанс был ' || round(v_chance * 100)::integer || ' %)'; end if;
  end if;
  update mine_shifts set status = p_status, ended_at = v_end, delivered = v_got, lost = v_got - v_put, result = v_res where id = p_shift;
  update mine_sites
     set stock = stock + v_put, lost = lost + (v_got - v_put),
         wear = least(100, greatest(0, wear + v_wear)),
         worked_hours = worked_hours + case when sh.task = 'extract' then v_hours * (sh.humans + sh.droids) else 0 end,
         humans_rest_until = case when sh.humans > 0 then greatest(coalesce(humans_rest_until, now()), v_end + make_interval(mins => mine_rest_min('h', v_hours, sh.pace))) else humans_rest_until end,
         droids_rest_until = case when sh.droids > 0 then greatest(coalesce(droids_rest_until, now()), v_end + make_interval(mins => mine_rest_min('d', v_hours, sh.pace))) else droids_rest_until end
   where building_id = sh.building_id;
  -- аврал: травмы людей и поломки дроидов; бригадир — вдвое реже; госпиталь и мастерские — вдвое короче
  if sh.pace = 'rush' and p_status = 'done' then
    if s.foremen > 0 then v_hurt := v_hurt / 2; end if;
    v_hh := game_setting_int('mine_hurt_hours', 12) * case when settlement_has_district(s.system_id, 'hospital') then 0.5 else 1 end;
    v_hd := game_setting_int('mine_hurt_hours', 12) * case when settlement_has_district(s.system_id, 'workshops') then 0.5 else 1 end;
    v_n := floor(sh.humans * v_hurt / 100.0 + random())::integer;
    if v_n > 0 then insert into mine_hurt (building_id, kind, n, until) values (sh.building_id, 'h', v_n, now() + make_interval(hours => v_hh)); end if;
    v_n := floor(sh.droids * v_hurt / 100.0 + random())::integer;
    if v_n > 0 then insert into mine_hurt (building_id, kind, n, until) values (sh.building_id, 'd', v_n, now() + make_interval(hours => v_hd)); end if;
  end if;
  if v_got > 0 then
    select sc.controller_user_id, s2.faction into v_ctrl, v_fac
      from systems s2 left join system_control sc on sc.system_id = s2.id where s2.id = sh.system_id;
    if v_ctrl is not null then
      perform log_event_digest(v_ctrl, v_fac, case when v_ref then 'resource_refined' else 'resource_extracted' end, sh.system_id || ':' || sh.resource, sh.system_id,
        (select name from systems where id = sh.system_id), (select name from resources where id = sh.resource), v_got,
        case when v_got > v_put then 'склад участка полон, потеряно ' || (v_got - v_put) end);
    end if;
  end if;
  return v_got;
end;
$$;


--
-- Name: mine_fire(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_fire(p_building uuid, p_kind text, p_n integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v_busy integer;
begin
  s := mine_own(p_building);
  if p_kind not in ('h', 'd', 'f', 't', 'g') then raise exception 'Неизвестный вид рабочих'; end if;
  if p_n is null or p_n < 1 then raise exception 'Некорректное число'; end if;
  if p_kind in ('f', 't', 'g') then
    if p_n > (case p_kind when 'f' then s.foremen when 't' then s.techs else s.guards end) then raise exception 'Столько нет'; end if;
    update mine_sites set foremen = foremen - case when p_kind = 'f' then p_n else 0 end,
                          techs = techs - case when p_kind = 't' then p_n else 0 end,
                          guards = guards - case when p_kind = 'g' then p_n else 0 end
     where building_id = p_building;
    return mine_site_state(p_building);
  end if;
  select coalesce(case when p_kind = 'h' then humans else droids end, 0) into v_busy from mine_shifts where building_id = p_building and status = 'run';
  if p_n > (case when p_kind = 'h' then s.humans else s.droids end) - coalesce(v_busy, 0) then
    raise exception 'Столько свободных нет: на смене рабочих не увольняют';
  end if;
  update mine_sites set humans = humans - case when p_kind = 'h' then p_n else 0 end,
                        droids = droids - case when p_kind = 'd' then p_n else 0 end
   where building_id = p_building;
  return mine_site_state(p_building);
end;
$$;


--
-- Name: mine_flush(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_flush(p_building uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v integer;
begin
  select * into s from mine_sites where building_id = p_building for update;
  if not found or s.stock <= 0 then return 0; end if;
  v := add_planet_stock(s.system_id, s.resource, s.stock);
  if v > 0 then update mine_sites set stock = stock - v where building_id = p_building; end if;
  return v;
end;
$$;


--
-- Name: mine_hire(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_hire(p_building uuid, p_kind text, p_n integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v_cost integer; v_cr integer; v_price integer;
begin
  s := mine_own(p_building);
  if p_kind not in ('h', 'd', 'f', 't', 'g') then raise exception 'Неизвестный вид рабочих'; end if;
  if p_n is null or p_n < 1 or p_n > 50 then raise exception 'Некорректное число'; end if;
  if p_kind in ('h', 'd') and s.humans + s.droids + p_n > s.places * game_setting_int('mine_staff_per_place', 2) then
    raise exception 'В бараке нет места: всего не больше % рабочих', s.places * game_setting_int('mine_staff_per_place', 2);
  end if;
  if p_kind = 'f' and s.foremen + p_n > mine_max_foremen(s.places) then raise exception 'Бригадиров не больше %', mine_max_foremen(s.places); end if;
  if p_kind = 't' and s.techs + p_n > mine_max_techs(s.places) then raise exception 'Техников не больше %', mine_max_techs(s.places); end if;
  if p_kind = 'g' and s.guards + p_n > mine_max_guards(s.places) then raise exception 'Охраны не больше %', mine_max_guards(s.places); end if;
  v_price := case p_kind when 'h' then game_setting_int('mine_hire_human', 150) when 'd' then game_setting_int('mine_hire_droid', 300)
                         when 'f' then game_setting_int('mine_hire_foreman', 600) when 'g' then game_setting_int('mine_hire_guard', 350)
                         else game_setting_int('mine_hire_tech', 400) end;
  if settlement_has_district(s.system_id, 'market') then v_price := round(v_price * 0.8); end if;
  v_cost := p_n * v_price;
  select credits into v_cr from profiles where id = auth.uid() for update;
  if coalesce(v_cr, 0) < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;
  update profiles set credits = credits - v_cost where id = auth.uid();
  update mine_sites set humans = humans + case when p_kind = 'h' then p_n else 0 end,
                        droids = droids + case when p_kind = 'd' then p_n else 0 end,
                        foremen = foremen + case when p_kind = 'f' then p_n else 0 end,
                        techs = techs + case when p_kind = 't' then p_n else 0 end,
                        guards = guards + case when p_kind = 'g' then p_n else 0 end
   where building_id = p_building;
  return mine_site_state(p_building);
end;
$$;


--
-- Name: mine_input_base(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_input_base(p_resource text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (select jsonb_object_agg(k, round((bt.consumes ->> k)::numeric / bt.produces_per_day, 4)) from jsonb_object_keys(bt.consumes) k)
    from building_types bt
   where bt.produces_resource = p_resource and bt.consumes <> '{}'::jsonb and bt.produces_per_day > 0
   order by bt.code limit 1;
$$;


--
-- Name: mine_input_k(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_input_k(p_building uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (select jsonb_object_agg(e.key, round(e.value::numeric * case when s.vein_until > now() then 0.75 else 1 end, 4))
            from jsonb_each_text(b) e)
    from mine_sites s, mine_input_base(s.resource) b
   where s.building_id = p_building and b is not null;
$$;


--
-- Name: mine_input_room(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_input_room(p_building uuid, p_upkeep_ore integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select floor(min(greatest(0, coalesce(ps.amount, 0) - case when e.key = 'ore' then coalesce(p_upkeep_ore, 0) else 0 end) / e.value::numeric))::integer
    from mine_sites s
    cross join lateral jsonb_each_text(mine_input_k(s.building_id)) e
    left join planet_stock ps on ps.system_id = s.system_id and ps.resource = e.key
   where s.building_id = p_building and e.value::numeric > 0;
$$;


--
-- Name: mine_input_text(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_input_text(p_building uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'на единицу — ' || string_agg(lower(r.name) || ' ' || replace(trim(trailing '.' from trim(trailing '0' from round(e.value::numeric, 2)::text)), '.', ','), ', ')
         || ' (на планете ' || string_agg(lower(r.name) || ' ' || coalesce(ps.amount, 0), ', ') || ')'
    from mine_sites s
    cross join lateral jsonb_each_text(mine_input_k(s.building_id)) e
    join resources r on r.id = e.key
    left join planet_stock ps on ps.system_id = s.system_id and ps.resource = e.key
   where s.building_id = p_building;
$$;


--
-- Name: mine_is_refine(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_is_refine(p_resource text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from building_types where produces_resource = p_resource and consumes <> '{}'::jsonb);
$$;


--
-- Name: mine_len_k(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_len_k(p_kind text, p_len integer) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when p_kind = 'h' then
    case p_len when 1 then 1.40 when 2 then 1.25 when 4 then 1.10 when 8 then 1.00 when 12 then 0.85 when 16 then 0.70 end
  else
    case p_len when 1 then 0.95 when 2 then 0.92 when 4 then 0.90 when 8 then 0.85 when 12 then 0.82 when 16 then 0.80 end
  end;
$$;


--
-- Name: mine_max_foremen(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_max_foremen(p_places integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select case when p_places >= 14 then 2 else 1 end; $$;


--
-- Name: mine_max_guards(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_max_guards(p_places integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select p_places / 6 + 1; $$;


--
-- Name: mine_max_techs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_max_techs(p_places integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select p_places / 6 + 1; $$;


--
-- Name: mine_mult(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_mult(p_building uuid, p_task text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (1 + 0.10 * least(s.foremen, mine_max_foremen(s.places)))
       * (1 + 0.03 * mine_stars(s.worked_hours))
       * (1 - least(100, greatest(0, s.wear)) * 0.004)
       * case when s.vein_until > now() and not mine_is_refine(s.resource) then 1.4 else 1 end
       * case when coalesce(p_task, 'extract') = 'extract' then 1 + s.prep_bonus / 100.0 else 1 end
  from mine_sites s where s.building_id = p_building;
$$;


--
-- Name: mine_sites; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mine_sites (
    building_id uuid NOT NULL,
    system_id text NOT NULL,
    resource text NOT NULL,
    humans integer DEFAULT 0 NOT NULL,
    droids integer DEFAULT 0 NOT NULL,
    places integer DEFAULT 6 NOT NULL,
    stock integer DEFAULT 0 NOT NULL,
    lost integer DEFAULT 0 NOT NULL,
    humans_rest_until timestamp with time zone,
    droids_rest_until timestamp with time zone,
    auto_on boolean DEFAULT true NOT NULL,
    auto_len integer DEFAULT 8 NOT NULL,
    auto_pace text DEFAULT 'normal'::text NOT NULL,
    worked_hours numeric DEFAULT 0 NOT NULL,
    gone boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    foremen integer DEFAULT 0 NOT NULL,
    techs integer DEFAULT 0 NOT NULL,
    wear numeric DEFAULT 0 NOT NULL,
    prep_bonus integer DEFAULT 0 NOT NULL,
    vein_until timestamp with time zone,
    idle_since timestamp with time zone,
    guards integer DEFAULT 0 NOT NULL,
    spoiled_until timestamp with time zone,
    CONSTRAINT mine_sites_droids_check CHECK ((droids >= 0)),
    CONSTRAINT mine_sites_humans_check CHECK ((humans >= 0))
);


--
-- Name: mine_own(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_own(p_building uuid) RETURNS public.mine_sites
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare b record; s mine_sites;
begin
  if auth.uid() is null then raise exception 'Не авторизован'; end if;
  select bd.system_id, bd.faction, bd.completes_at, bt.produces_resource res, bt.consumes, sy.faction sys_faction
    into b from buildings bd join building_types bt on bt.id = bd.building_type_id join systems sy on sy.id = bd.system_id
   where bd.id = p_building;
  if not found then raise exception 'Постройка не найдена'; end if;
  if b.res is null then raise exception 'Это не производственная постройка'; end if;
  if not exists (select 1 from system_control sc where sc.system_id = b.system_id and sc.controller_user_id = auth.uid()) then
    raise exception 'Производством управляет хозяин планеты';
  end if;
  if b.completes_at is not null and b.completes_at > now() then raise exception 'Постройка ещё не достроена'; end if;
  if b.faction is distinct from b.sys_faction then raise exception 'Трофейная постройка не работает на нового хозяина — её можно только снести'; end if;
  perform mine_site_ensure(p_building);
  -- порядок блокировок как у mine_tick и mine_finish: сначала идущая смена, потом участок (иначе взаимная блокировка)
  perform 1 from mine_shifts where building_id = p_building and status = 'run' for update;
  select * into s from mine_sites where building_id = p_building for update;
  return s;
end;
$$;


--
-- Name: mine_pace_k(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_pace_k(p_pace text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_pace when 'careful' then 0.80 when 'rush' then 1.35 else 1.00 end;
$$;


--
-- Name: mine_raid_chance(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_raid_chance(p_defense integer, p_n integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when coalesce(p_defense, 0) >= greatest(1, p_n) then 100
              else round(80.0 * greatest(0, coalesce(p_defense, 0)) / greatest(1, p_n))::integer end;
$$;


--
-- Name: mine_raid_cycle(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_raid_cycle(p_at timestamp with time zone) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select ((p_at at time zone server_tz()) - make_interval(hours => game_setting_int('payout_hour', 4)))::date;
$$;


--
-- Name: mine_raid_defense(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_raid_defense(p_building uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(spy_guards(p_building), 0)
       + case when exists (select 1 from mine_shifts sh where sh.building_id = p_building and sh.status = 'run' and sh.task = 'guard') then 1 else 0 end;
$$;


--
-- Name: mine_raid_resolve(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_raid_resolve(p_raid uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r mine_raids; s mine_sites; v_ctl uuid; v_fac text; v_bname text; v_slot integer; v_bfac text;
  v_def integer; v_ch integer; v_roll numeric; v_sh mine_shifts; v_have integer; v_take integer := 0; v_bounty integer := 0;
  v_meta jsonb; v_rname text;
begin
  select * into r from mine_raids where id = p_raid and status in ('plan', 'warned') for update;
  if not found then return; end if;
  -- порядок блокировок как у mine_finish (смена, потом участок), иначе возможна взаимная блокировка с mine_tick
  select * into v_sh from mine_shifts where building_id = r.building_id and status = 'run' for update;
  select * into s from mine_sites where building_id = r.building_id for update;
  select sc.controller_user_id, sy.faction into v_ctl, v_fac from systems sy left join system_control sc on sc.system_id = sy.id where sy.id = r.system_id;
  select bd.slot_index, bt.name, bd.faction into v_slot, v_bname, v_bfac
    from buildings bd join building_types bt on bt.id = bd.building_type_id where bd.id = r.building_id;

  -- цели больше нет, планета ничья или чужая, идёт захват — налёта не было
  if s.building_id is null or s.gone or v_slot is null or v_ctl is null or v_bfac is distinct from v_fac or is_capture_active(r.system_id) then
    update mine_raids set status = 'done', result = 'void', acted_at = now() where id = p_raid;
    return;
  end if;

  v_def := mine_raid_defense(r.building_id);
  v_ch := mine_raid_chance(v_def, r.n);
  v_roll := random() * 100;
  v_meta := jsonb_build_object('slot', v_slot, 'building_id', r.building_id, 'raid', r.id);

  if v_roll < v_ch then
    v_bounty := game_setting_int('mine_raid_bounty', 40) * r.n;
    update profiles set credits = credits + v_bounty where id = v_ctl;
    update mine_raids set status = 'done', result = 'repelled', acted_at = now(), defense = v_def, chance = v_ch, roll = v_roll, bounty = v_bounty
     where id = p_raid;
    perform log_event(v_ctl, v_fac, r.system_id, 'mine_raid_repelled',
      v_bname || ': охрана отбила налёт — ' || ru_plural(r.n, 'налётчик', 'налётчика', 'налётчиков') || ' · +' || v_bounty || ' кр.',
      null, 'private', v_meta);
    return;
  end if;

  -- не отбили: бригада бросает смену, банда выносит часть ресурса участка со склада планеты, ломает оборудование
  if v_sh.id is not null then perform mine_finish(v_sh.id, 'stopped'); end if;
  select coalesce(amount, 0) into v_have from planet_stock where system_id = r.system_id and resource = s.resource for update;
  v_take := least(game_setting_int('mine_raid_loot_max', 60), floor(coalesce(v_have, 0) * game_setting_int('mine_raid_loot_pct', 20) / 100.0))::integer;
  if v_take > 0 then update planet_stock set amount = amount - v_take where system_id = r.system_id and resource = s.resource; end if;
  update mine_sites set wear = least(100, wear + game_setting_int('mine_raid_wear', 10)) where building_id = r.building_id;
  select name into v_rname from resources where id = s.resource;
  update mine_raids set status = 'done', result = 'lost', acted_at = now(), defense = v_def, chance = v_ch, roll = v_roll,
                        loot = v_take, loot_res = case when v_take > 0 then s.resource end, shift_cut = v_sh.id is not null
   where id = p_raid;
  perform log_event(v_ctl, v_fac, r.system_id, 'mine_raid_lost',
    v_bname || ': ' || case when v_take > 0 then 'банда ушла с добычей — −' || v_take || ' ' || lower(coalesce(v_rname, s.resource)) else 'банда прорвалась, склад пуст' end
      || case when v_sh.id is not null then ', смена оборвана' else '' end || ', износ +' || game_setting_int('mine_raid_wear', 10) || ' %',
    null, 'private', v_meta);
end;
$$;


--
-- Name: mine_raid_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_raid_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_cycle date := mine_raid_cycle(now()); v_pct integer; v_b uuid; v_places integer; v_at timestamptz;
  v_bname text; v_slot integer; v_warn integer := game_setting_int('marauder_warn_minutes', 30);
begin
  if game_setting_int('mine_raid_enabled', 1) = 0 then return; end if;

  -- план на сутки: один бросок на планету; нет налёта — строка «none», чтобы не бросать снова
  for r in select sy.id, sc.controller_user_id from systems sy join system_control sc on sc.system_id = sy.id
            join profiles pr on pr.id = sc.controller_user_id
           where sc.controller_user_id is not null and sy.faction is not null and not sy.is_deep_space
             and pr.created_at < now() - interval '7 days'
             and exists (select 1 from mine_sites ms join buildings bd on bd.id = ms.building_id
                          where ms.system_id = sy.id and not ms.gone and bd.faction is not distinct from sy.faction)
             and not exists (select 1 from mine_raids mr where mr.system_id = sy.id and mr.cycle = v_cycle) loop
    begin
      v_pct := case when settlement_effective(r.id) < 30 then game_setting_int('mine_raid_pct_low', 50) else game_setting_int('mine_raid_pct', 30) end;
      v_at := marauder_raid_slot(now());
      if v_at is null or random() * 100 >= v_pct then
        insert into mine_raids (system_id, cycle, status) values (r.id, v_cycle, 'none') on conflict (system_id, cycle) do nothing;
        continue;
      end if;
      select ms.building_id, ms.places into v_b, v_places from mine_sites ms join buildings bd on bd.id = ms.building_id join systems sy on sy.id = ms.system_id
       where ms.system_id = r.id and not ms.gone and bd.faction is not distinct from sy.faction order by random() limit 1;
      insert into mine_raids (system_id, cycle, building_id, status, raid_at, n)
      values (r.id, v_cycle, v_b, 'plan', v_at, 1 + ceil(coalesce(v_places, 6) / 6.0)::integer)
      on conflict (system_id, cycle) do nothing;
    exception when others then perform err_db('mine_raid_tick', sqlstate, sqlerrm, true); end;
  end loop;

  -- предупреждение хозяину за полчаса
  for r in select mr.* from mine_raids mr where mr.status = 'plan' and now() >= mr.raid_at - make_interval(mins => v_warn) and now() < mr.raid_at loop
    begin
      update mine_raids set status = 'warned' where id = r.id and status = 'plan';
      continue when not found;
      select bd.slot_index, bt.name into v_slot, v_bname from buildings bd join building_types bt on bt.id = bd.building_type_id where bd.id = r.building_id;
      if v_slot is not null then
        perform log_event(sc.controller_user_id, sy.faction, r.system_id, 'mine_raid_warn',
          v_bname || ': ' || ru_plural(r.n, 'налётчик', 'налётчика', 'налётчиков') || ' будут около ' || marauder_hhmm(r.raid_at)
            || ' · защитников на посту: ' || mine_raid_defense(r.building_id),
          null, 'private', jsonb_build_object('slot', v_slot, 'building_id', r.building_id, 'raid', r.id, 'raid_at', r.raid_at))
          from systems sy join system_control sc on sc.system_id = sy.id where sy.id = r.system_id and sc.controller_user_id is not null;
      end if;
    exception when others then perform err_db('mine_raid_tick', sqlstate, sqlerrm, true); end;
  end loop;

  -- такт опоздал: предупреждения не было или налёт давно должен был начаться — отменить, игрока не наказывать
  update mine_raids set status = 'done', result = 'void', acted_at = now() where status in ('plan', 'warned') and now() >= raid_at
     and (status = 'plan' or now() > raid_at + interval '10 minutes' or tries >= 5);

  -- налёт; сбой — ещё попытка через минуту, после пяти налёт отменяется (строкой выше)
  for r in select id from mine_raids where status = 'warned' and now() >= raid_at order by raid_at loop
    begin perform mine_raid_resolve(r.id);
    exception when others then
      perform err_db('mine_raid_tick', sqlstate, sqlerrm, true);
      update mine_raids set tries = tries + 1 where id = r.id;
    end;
  end loop;
end;
$$;


--
-- Name: mine_rate_h(text, text, integer, integer, integer, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_rate_h(p_system_id text, p_resource text, p_humans integer, p_droids integer, p_len integer, p_pace text, p_fed_h boolean, p_fed_d boolean) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select game_setting_int('mine_rate_x100', 125) / 100.0 * mine_res_k(p_system_id, p_resource) * mine_pace_k(p_pace)
       * (p_humans * mine_len_k('h', p_len) * case when p_fed_h then 1 else game_setting_int('mine_hungry_pct', 80) / 100.0 end
        + p_droids * mine_len_k('d', p_len) * case when p_fed_d then 1 else game_setting_int('mine_hungry_pct', 80) / 100.0 end);
$$;


--
-- Name: mine_report_fx(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_report_fx(p_building uuid, p_fx jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; sh mine_shifts; h jsonb; v_out jsonb := '{}'::jsonb; v_hurt jsonb := '[]'::jsonb; v_n integer; v_tot integer; v_k text;
  v_w numeric;
begin
  -- порядок блокировок как у mine_finish и mine_tick (смена, потом участок), иначе возможна взаимная блокировка
  select * into sh from mine_shifts where building_id = p_building and status = 'run' for update;
  select * into s from mine_sites where building_id = p_building for update;
  if not found or s.gone or p_fx is null then return v_out; end if;
  if p_fx ? 'wear' then
    v_w := least(100, greatest(0, s.wear + (p_fx->>'wear')::numeric));
    update mine_sites set wear = v_w where building_id = p_building;
    -- в итог — сколько реально прибавилось (у потолка 100 % меньше заявленного)
    if round(v_w - s.wear) <> 0 then v_out := v_out || jsonb_build_object('wear', round(v_w - s.wear)::integer); end if;
  end if;
  -- как вскрыша (у цеха — наладка линии): к следующей смене основной работы
  if p_fx ? 'prep' then
    update mine_sites set prep_bonus = greatest(prep_bonus, (p_fx->>'prep')::integer) where building_id = p_building;
    v_out := v_out || jsonb_build_object('prep', (p_fx->>'prep')::integer);
  end if;
  if p_fx ? 'vein' then
    update mine_sites set vein_until = greatest(coalesce(vein_until, now()), now()) + make_interval(hours => (p_fx->>'vein')::integer) where building_id = p_building;
    v_out := v_out || jsonb_build_object('vein', (p_fx->>'vein')::integer);
  end if;
  for h in select * from jsonb_array_elements(coalesce(p_fx->'hurt', '[]'::jsonb)) loop
    v_k := h->>'k';
    continue when v_k not in ('h', 'd');
    -- считаем от тех, кто ещё не выбыл (уже бастующих или сломанных второй раз не считаем)
    v_tot := greatest(0, case when v_k = 'h' then s.humans else s.droids end
                         - coalesce((select sum(n) from mine_hurt where building_id = p_building and kind = v_k and until > now()), 0))::integer;
    v_n := least(v_tot, coalesce((h->>'n')::integer, ceil(v_tot * coalesce((h->>'pct')::numeric, 0) / 100.0)::integer));
    continue when coalesce(v_n, 0) <= 0;
    -- выбывших не держат на смене: если они там — смена обрывается (сделанное сохраняется), как при диверсии
    if sh.id is not null and (case when v_k = 'h' then sh.humans else sh.droids end) > 0 then
      perform mine_finish(sh.id, 'stopped');
      sh := null;                                                  -- смена закрыта: второй выбывший её не трогает
    end if;
    insert into mine_hurt (building_id, kind, n, until, reason)
    values (p_building, v_k, v_n, now() + make_interval(hours => greatest(1, coalesce((h->>'h')::integer, 4))), coalesce(h->>'why', 'rush'));
    v_hurt := v_hurt || jsonb_build_object('k', v_k, 'n', v_n, 'h', greatest(1, coalesce((h->>'h')::integer, 4)), 'why', coalesce(h->>'why', 'rush'));
  end loop;
  if jsonb_array_length(v_hurt) > 0 then v_out := v_out || jsonb_build_object('hurt', v_hurt); end if;
  return v_out;
end;
$$;


--
-- Name: mine_report_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_report_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare tz text := event_tz(); v_day date := (now() at time zone event_tz())::date; p record; s record; v_pick text; v_id uuid;
  v_start integer := event_setting_int('report_start_hour', 10); v_end integer := event_setting_int('report_end_hour', 22);
  v_due timestamptz; v_n integer := 0; v_opts text[];
begin
  if not pg_try_advisory_xact_lock(hashtext('mine_report_tick')) then return 0; end if;
  for p in select distinct pf.id from profiles pf join system_control sc on sc.controller_user_id = pf.id
            join mine_sites ms on ms.system_id = sc.system_id and not ms.gone
           where pf.faction is not null and pf.last_seen_at > now() - make_interval(days => event_setting_int('report_seen_days', 3)) loop
    begin
      continue when abs(hashtext(p.id::text || v_day::text || ':site-p')) % 100 >= game_setting_int('mine_report_pct', 40);
      v_due := ((v_day + make_interval(hours => v_start)) at time zone tz)
               + make_interval(mins => abs(hashtext(p.id::text || v_day::text || ':site-t')) % greatest(60, (v_end - v_start) * 60 - 30));
      continue when now() < v_due or now() >= ((v_day + make_interval(hours => v_end)) at time zone tz);
      continue when exists (select 1 from player_reports pr where pr.user_id = p.id and pr.day = v_day and pr.building_id is not null);
      select ms.building_id, ms.system_id, ms.humans, ms.droids, ms.vein_until, mine_is_refine(ms.resource) refine into s
        from mine_sites ms join system_control sc on sc.system_id = ms.system_id and sc.controller_user_id = p.id
        join buildings bd on bd.id = ms.building_id join systems sy on sy.id = ms.system_id
       where not ms.gone and bd.faction is not distinct from sy.faction
       order by random() limit 1;
      continue when s.building_id is null or is_capture_active(s.system_id);
      v_opts := array[case when s.refine then 's_line_fault' else 's_cave_in' end];
      if s.humans > 0 then v_opts := array_append(v_opts, 's_bonus'); end if;
      if not s.refine and coalesce(s.vein_until, now()) <= now() then v_opts := array_append(v_opts, 's_vein'); end if;
      if s.droids > 0 then v_opts := array_append(v_opts, 's_droid_glitch'); end if;
      v_pick := v_opts[1 + floor(random() * array_length(v_opts, 1))::integer];
      continue when not exists (select 1 from report_catalog where id = v_pick and active);
      v_id := report_deliver(p.id, v_pick, s.system_id, null);
      if v_id is not null then update player_reports set building_id = s.building_id where id = v_id; v_n := v_n + 1; end if;
    exception when others then perform err_db('mine_report_tick', sqlstate, sqlerrm, true); end;
  end loop;
  return v_n;
end;
$$;


--
-- Name: mine_res_k(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_res_k(p_system_id text, p_resource text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select max(bt.produces_per_day)::numeric / greatest(1, game_setting_int('mine_refine_base', 120))
       from building_types bt where bt.produces_resource = p_resource and bt.consumes <> '{}'::jsonb),
    (select case when s.primary_resource = p_resource then 1.0 when s.secondary_resource = p_resource then 0.5 else 0 end
       from systems s where s.id = p_system_id), 0);
$$;


--
-- Name: mine_rest_min(text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_rest_min(p_kind text, p_hours numeric, p_pace text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when p_kind = 'h' then greatest(60, round(p_hours * 30 * case p_pace when 'careful' then 0.5 when 'rush' then 1.5 else 1 end))
              else greatest(30, round(p_hours * 15 * case p_pace when 'careful' then 0.5 when 'rush' then 1.5 else 1 end)) end::integer;
$$;


--
-- Name: mine_rested(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_rested(p_building uuid, p_kind text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select case when p_kind = 'h' then ms.humans_rest_until else ms.droids_rest_until end from mine_sites ms where ms.building_id = p_building), now()) <= now();
$$;


--
-- Name: mine_shift_start(uuid, integer, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_shift_start(p_building uuid, p_len integer, p_pace text, p_humans integer, p_droids integer) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select mine_shift_start(p_building, p_len, p_pace, p_humans, p_droids, 'extract');
$$;


--
-- Name: mine_shift_start(uuid, integer, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_shift_start(p_building uuid, p_len integer, p_pace text, p_humans integer, p_droids integer, p_task text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v_task text := coalesce(p_task, 'extract');
begin
  s := mine_own(p_building);
  perform assert_planet_operational(s.system_id);
  if p_len not in (1, 2, 4, 8, 12, 16) then raise exception 'Нет такой длины смены'; end if;
  if p_pace not in ('careful', 'normal', 'rush') then raise exception 'Нет такого темпа'; end if;
  if v_task not in ('extract', 'prep', 'survey', 'maint', 'guard') then raise exception 'Нет такой задачи'; end if;
  p_humans := coalesce(p_humans, 0); p_droids := coalesce(p_droids, 0);
  if p_humans < 0 or p_droids < 0 or p_humans + p_droids < 1 then raise exception 'Выбери, кто выйдет на смену'; end if;
  if p_humans + p_droids > s.places then raise exception 'Мест работы: %', s.places; end if;
  if mine_res_k(s.system_id, s.resource) <= 0 and v_task <> 'maint' then raise exception 'На планете нет залежи'; end if;
  if v_task = 'maint' and s.wear <= 0 then raise exception 'Оборудование в порядке — обслуживать нечего'; end if;
  if exists (select 1 from mine_shifts where building_id = p_building and status = 'run') then raise exception 'Смена уже идёт'; end if;
  if p_humans > 0 and not mine_rested(p_building, 'h') then raise exception 'Люди ещё отдыхают'; end if;
  if p_droids > 0 and not mine_rested(p_building, 'd') then raise exception 'Дроиды ещё на обслуживании'; end if;
  if p_humans > mine_avail(p_building, 'h') then raise exception 'Свободных людей: %', mine_avail(p_building, 'h'); end if;
  if p_droids > mine_avail(p_building, 'd') then raise exception 'Свободных дроидов: %', mine_avail(p_building, 'd'); end if;
  perform mine_start(p_building, p_len, p_pace, p_humans, p_droids, false, auth.uid(), v_task);
  return mine_site_state(p_building);
end;
$$;


--
-- Name: mine_shift_stop(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_shift_stop(p_building uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v_id uuid;
begin
  s := mine_own(p_building);
  select id into v_id from mine_shifts where building_id = p_building and status = 'run';
  if v_id is null then raise exception 'Смена не идёт'; end if;
  perform mine_finish(v_id, 'stopped');
  perform mine_flush(p_building);
  return mine_site_state(p_building);
end;
$$;


--
-- Name: mine_site_cap(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_site_cap(p_system text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select game_setting_int('mine_site_cap', 300) + case when settlement_has_district(p_system, 'warehouses') then 300 else 0 end;
$$;


--
-- Name: mine_site_ensure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_site_ensure(p_building uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare b record;
begin
  if exists (select 1 from mine_sites where building_id = p_building) then return true; end if;
  select bd.id, bd.system_id, bd.faction, bd.completes_at, bt.produces_resource res, bt.consumes, s.faction sys_faction
    into b
  from buildings bd join building_types bt on bt.id = bd.building_type_id join systems s on s.id = bd.system_id
  where bd.id = p_building;
  if not found or b.res is null then return false; end if;
  if b.completes_at is not null and b.completes_at > now() then return false; end if;
  insert into mine_sites (building_id, system_id, resource, droids, places, techs)
  values (p_building, b.system_id, b.res, game_setting_int('mine_places_start', 6), game_setting_int('mine_places_start', 6), 1)
  on conflict (building_id) do nothing;
  return true;
end;
$$;


--
-- Name: mine_site_ok(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_site_ok(p_building uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from buildings bd join systems s on s.id = bd.system_id
                 where bd.id = p_building and (bd.completes_at is null or bd.completes_at <= now())
                   and bd.faction is not distinct from s.faction);
$$;


--
-- Name: mine_site_raids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_site_raids(p_building uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', r.id, 'raid_at', r.raid_at, 'approach_at', r.raid_at - make_interval(mins => game_setting_int('mine_raid_approach_min', 3)),
           'n', r.n, 'seed', r.seed, 'acted_at', r.acted_at, 'result', r.result, 'defense', r.defense, 'chance', r.chance,
           'loot', r.loot, 'loot_res', r.loot_res, 'bounty', r.bounty, 'shift_cut', r.shift_cut)
         order by r.raid_at desc), '[]'::jsonb)
    from mine_raids r
   where r.building_id = p_building and r.status <> 'none' and r.result is distinct from 'void'
     and r.raid_at - make_interval(mins => game_setting_int('marauder_warn_minutes', 30)) <= now()
     and r.raid_at > now() - interval '24 hours';
$$;


--
-- Name: mine_site_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_site_state(p_building uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; sh mine_shifts; v_eff integer; v_last jsonb; v_hurt jsonb; v_res record; v_run jsonb; v_market boolean; v_ik jsonb; v_ref jsonb;
begin
  s := mine_own(p_building);
  select * into sh from mine_shifts where building_id = p_building and status = 'run';
  if found then perform mine_accrue(sh.id); select * into sh from mine_shifts where id = sh.id; end if;
  v_eff := effect_sum(s.system_id, 'extract');
  v_market := settlement_has_district(s.system_id, 'market');
  select r.id, r.name, r.color into v_res from resources r where r.id = s.resource;
  v_run := case when sh.id is null then null else jsonb_build_object(
    'id', sh.id, 'started_at', sh.started_at, 'ends_at', sh.ends_at, 'len', sh.len_h, 'pace', sh.pace, 'task', sh.task, 'mult', round(sh.mult, 3),
    'humans', sh.humans, 'droids', sh.droids, 'fed_h', sh.fed_h, 'fed_d', sh.fed_d, 'auto', sh.auto,
    'accrued', round(sh.accrued, 2), 'rate', round(sh.base_rate * greatest(0, 100 + v_eff) / 100.0, 3),
    'cap', sh.cap, 'input', sh.input) end;
  select coalesce(jsonb_agg(jsonb_build_object('started_at', x.started_at, 'ended_at', x.ended_at, 'len', x.len_h, 'pace', x.pace, 'task', x.task,
           'humans', x.humans, 'droids', x.droids, 'got', x.delivered, 'lost', x.lost, 'status', x.status, 'auto', x.auto,
           'fed', x.fed_h and x.fed_d, 'result', x.result, 'used', x.input_used) order by x.started_at desc), '[]'::jsonb)
    into v_last
  from (select * from mine_shifts where building_id = p_building and status <> 'run' order by started_at desc limit 6) x;
  select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'n', n, 'until', until, 'why', reason) order by until), '[]'::jsonb) into v_hurt
  from mine_hurt where building_id = p_building and until > now();
  -- цех: что и сколько уходит на единицу готового (с отлаженным режимом — меньше), сколько сырья на планете
  v_ik := mine_input_k(p_building);
  if v_ik is not null then
    select jsonb_build_object('econ', s.vein_until > now(), 'room', mine_input_room(p_building, 0), 'idle', s.idle_since is not null,
             'inputs', jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name, 'color', r.color, 'k', (v_ik ->> r.id)::numeric,
               'have', coalesce((select amount from planet_stock where system_id = s.system_id and resource = r.id), 0)) order by r.sort_order))
      into v_ref
      from resources r where v_ik ? r.id;
  end if;
  return jsonb_build_object(
    'now', now(), 'building_id', p_building, 'system_id', s.system_id, 'refine', v_ref,
    'res', jsonb_build_object('id', v_res.id, 'name', v_res.name, 'color', v_res.color), 'res_k', mine_res_k(s.system_id, s.resource),
    'humans', s.humans, 'droids', s.droids, 'places', s.places, 'staff_max', s.places * game_setting_int('mine_staff_per_place', 2),
    'guards', s.guards, 'guards_max', mine_max_guards(s.places), 'garrison', settlement_has_district(s.system_id, 'garrison'),
    'comms', settlement_has_district(s.system_id, 'comms'), 'spoiled', coalesce(s.spoiled_until > now(), false), 'ops', spy_site_ops(p_building),
    'foremen', s.foremen, 'techs', s.techs, 'foremen_max', mine_max_foremen(s.places), 'techs_max', mine_max_techs(s.places),
    'avail_h', mine_avail(p_building, 'h'), 'avail_d', mine_avail(p_building, 'd'),
    'rest_h', case when s.humans_rest_until > now() then s.humans_rest_until end,
    'rest_d', case when s.droids_rest_until > now() then s.droids_rest_until end,
    'hurt', v_hurt, 'stock', s.stock, 'site_cap', mine_site_cap(s.system_id), 'lost', s.lost,
    'wear', round(s.wear, 1), 'stars', mine_stars(s.worked_hours), 'hours', round(s.worked_hours), 'hours_next', mine_star_next(s.worked_hours),
    'prep', s.prep_bonus, 'vein_until', case when s.vein_until > now() then s.vein_until end,
    'mult', round(coalesce(mine_mult(p_building, 'extract'), 1), 3),
    'upgrade', mine_upgrade_cost(s.places),
    'districts', jsonb_build_object('hospital', settlement_has_district(s.system_id, 'hospital'), 'workshops', settlement_has_district(s.system_id, 'workshops'),
                                    'market', v_market, 'warehouses', settlement_has_district(s.system_id, 'warehouses')),
    'auto', jsonb_build_object('on', s.auto_on, 'len', s.auto_len, 'pace', s.auto_pace), 'day', mine_day_estimate(p_building),
    'run', v_run, 'last', v_last, 'eff', v_eff, 'capture', is_capture_active(s.system_id),
    'planet', jsonb_build_object(
      'cap', planet_stock_cap(s.system_id),
      'res', coalesce((select amount from planet_stock where system_id = s.system_id and resource = s.resource), 0),
      'food', coalesce((select amount from planet_stock where system_id = s.system_id and resource = 'food'), 0),
      'ore', coalesce((select amount from planet_stock where system_id = s.system_id and resource = 'ore'), 0),
      'durasteel', coalesce((select amount from planet_stock where system_id = s.system_id and resource = 'durasteel'), 0),
      'electronics', coalesce((select amount from planet_stock where system_id = s.system_id and resource = 'electronics'), 0)),
    'credits', (select credits from profiles where id = auth.uid()),
    'cfg', jsonb_build_object(
      'rate', game_setting_int('mine_rate_x100', 125) / 100.0, 'hungry', game_setting_int('mine_hungry_pct', 80) / 100.0,
      'hire_h', round(game_setting_int('mine_hire_human', 150) * case when v_market then 0.8 else 1 end),
      'hire_d', round(game_setting_int('mine_hire_droid', 300) * case when v_market then 0.8 else 1 end),
      'hire_f', round(game_setting_int('mine_hire_foreman', 600) * case when v_market then 0.8 else 1 end),
      'hire_g', round(game_setting_int('mine_hire_guard', 350) * case when v_market then 0.8 else 1 end),
      'spy', jsonb_build_object('guard', game_setting_int('spy_guard_pct', 12), 'watch', game_setting_int('spy_watch_pct', 20), 'comms', game_setting_int('spy_comms_pct', 10)),
      'hire_t', round(game_setting_int('mine_hire_tech', 400) * case when v_market then 0.8 else 1 end),
      'hurt_pct', game_setting_int('mine_rush_hurt_pct', 10), 'hurt_hours', game_setting_int('mine_hurt_hours', 12),
      'wear_h', game_setting_int('mine_wear_h_x100', 8) / 100.0, 'wear_d', game_setting_int('mine_wear_d_x100', 18) / 100.0,
      'lens', jsonb_build_array(1, 2, 4, 8, 12, 16), 'auto_lens', jsonb_build_array(8, 12, 16),
      'k_h', (select jsonb_object_agg(l, mine_len_k('h', l)) from unnest(array[1, 2, 4, 8, 12, 16]) l),
      'k_d', (select jsonb_object_agg(l, mine_len_k('d', l)) from unnest(array[1, 2, 4, 8, 12, 16]) l),
      'pace', jsonb_build_object('careful', mine_pace_k('careful'), 'normal', 1, 'rush', mine_pace_k('rush')),
      'rest', jsonb_build_object('careful', 0.5, 'normal', 1, 'rush', 1.5),
      'task', jsonb_build_object('extract', 1, 'prep', mine_task_k('prep'), 'survey', 0, 'maint', 0, 'guard', mine_task_k('guard'))));
end;
$$;


--
-- Name: mine_star_next(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_star_next(p_hours numeric) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when p_hours < 150 then 150 when p_hours < 400 then 400 when p_hours < 900 then 900
              when p_hours < 1800 then 1800 when p_hours < 3500 then 3500 end;
$$;


--
-- Name: mine_stars(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_stars(p_hours numeric) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when p_hours >= 3500 then 5 when p_hours >= 1800 then 4 when p_hours >= 900 then 3
              when p_hours >= 400 then 2 when p_hours >= 150 then 1 else 0 end;
$$;


--
-- Name: mine_start(uuid, integer, text, integer, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_start(p_building uuid, p_len integer, p_pace text, p_humans integer, p_droids integer, p_auto boolean, p_by uuid) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select mine_start(p_building, p_len, p_pace, p_humans, p_droids, p_auto, p_by, 'extract');
$$;


--
-- Name: mine_start(uuid, integer, text, integer, integer, boolean, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_start(p_building uuid, p_len integer, p_pace text, p_humans integer, p_droids integer, p_auto boolean, p_by uuid, p_task text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; v_fh boolean := true; v_fd boolean := true; v_id uuid; v_have integer; v_mult numeric; v_task text := coalesce(p_task, 'extract');
  v_rate numeric; v_ik jsonb; v_cap integer; v_take jsonb; k text; v_n integer;
begin
  select * into s from mine_sites where building_id = p_building for update;
  if p_humans > 0 then
    select amount into v_have from planet_stock where system_id = s.system_id and resource = 'food' for update;
    if coalesce(v_have, 0) >= p_humans and coalesce(s.spoiled_until, now()) <= now() then update planet_stock set amount = amount - p_humans where system_id = s.system_id and resource = 'food';
    else v_fh := false; end if;
    -- испорченный диверсантами паёк: эта смена людей без пайка, дальше снова как обычно
    if s.spoiled_until > now() then update mine_sites set spoiled_until = null where building_id = p_building; end if;
  end if;
  if p_droids > 0 then
    select amount into v_have from planet_stock where system_id = s.system_id and resource = 'ore' for update;
    if coalesce(v_have, 0) >= p_droids then update planet_stock set amount = amount - p_droids where system_id = s.system_id and resource = 'ore';
    else v_fd := false; end if;
  end if;
  v_mult := coalesce(mine_mult(p_building, v_task), 1);
  v_rate := mine_rate_h(s.system_id, s.resource, p_humans, p_droids, p_len, p_pace, v_fh, v_fd) * v_mult * mine_task_k(v_task);
  -- цех: сырьё на всю смену берётся со склада планеты сейчас (по нынешним эффектам), остаток вернётся по концу
  v_ik := mine_input_k(p_building);
  if v_ik is not null and v_rate > 0 then
    v_cap := least(mine_input_room(p_building, 0),
                   ceil(v_rate * p_len * greatest(0, 100 + effect_sum(s.system_id, 'extract')) / 100.0)::integer);
    if coalesce(v_cap, 0) < 1 then raise exception 'Не хватает сырья: %', mine_input_text(p_building); end if;
    v_take := '{}'::jsonb;
    for k in select jsonb_object_keys(v_ik) loop
      v_n := ceil(v_cap * (v_ik ->> k)::numeric)::integer;
      perform take_planet_stock(s.system_id, k, v_n);
      v_take := v_take || jsonb_build_object(k, v_n);
    end loop;
  end if;
  if v_task = 'extract' and s.prep_bonus > 0 then update mine_sites set prep_bonus = 0 where building_id = p_building; end if;
  insert into mine_shifts (building_id, system_id, resource, ends_at, len_h, pace, humans, droids, fed_h, fed_d, base_rate, auto, started_by, task, mult,
                           input_k, input, cap)
  values (p_building, s.system_id, s.resource, now() + make_interval(hours => p_len), p_len, p_pace, p_humans, p_droids, v_fh, v_fd,
          v_rate, p_auto, p_by, v_task, v_mult, case when v_take is not null then v_ik end, v_take, v_cap)
  returning id into v_id;
  update mine_sites set idle_since = null where building_id = p_building and idle_since is not null;
  return v_id;
end;
$$;


--
-- Name: mine_task_k(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_task_k(p_task text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_task when 'prep' then 0.2 when 'survey' then 0 when 'maint' then 0 when 'guard' then 0.6 else 1 end;
$$;


--
-- Name: mine_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_h integer; v_d integer;
begin
  -- новые участки и цеха: готовые добывающие и перерабатывающие здания своей фракции
  for r in select bd.id from buildings bd join building_types bt on bt.id = bd.building_type_id join systems s on s.id = bd.system_id
           where bt.produces_resource is not null
             and (bd.completes_at is null or bd.completes_at <= now()) and bd.faction is not distinct from s.faction
             and not exists (select 1 from mine_sites ms where ms.building_id = bd.id) loop
    begin perform mine_site_ensure(r.id);
    exception when others then perform err_db('mine_tick', sqlstate, sqlerrm, true); end;
  end loop;
  -- идущие смены
  for r in select id, building_id, ends_at from mine_shifts where status = 'run' loop
    begin
      if not mine_site_ok(r.building_id) then
        perform mine_finish(r.id, 'lost');
        update mine_sites set auto_on = false, gone = not exists (select 1 from buildings where id = r.building_id) where building_id = r.building_id;
      elsif now() >= r.ends_at then perform mine_finish(r.id, 'done');
      else
        perform mine_accrue(r.id);
        -- цех переработал всё взятое сырьё — смена кончается раньше, бригада раньше уходит на отдых
        if exists (select 1 from mine_shifts where id = r.id and status = 'run' and cap is not null and accrued >= cap - 0.001) then
          perform mine_finish(r.id, 'done');
        end if;
      end if;
    exception when others then perform err_db('mine_tick', sqlstate, sqlerrm, true); end;
  end loop;
  -- техники чинят оборудование: каждый — 1 % в час (тик раз в минуту)
  begin
    update mine_sites
       set wear = greatest(0, wear - least(techs, mine_max_techs(places)) * game_setting_int('mine_tech_repair_x100', 100) / 100.0 / 60.0)
     where wear > 0 and techs > 0 and not gone;
  exception when others then perform err_db('mine_tick', sqlstate, sqlerrm, true); end;
  -- автосмены: бригада отдохнула — новая смена всеми свободными (дроиды первыми), не больше мест
  for r in select ms.* from mine_sites ms where ms.auto_on and not ms.gone
             and not exists (select 1 from mine_shifts sh where sh.building_id = ms.building_id and sh.status = 'run') loop
    begin
      if not mine_site_ok(r.building_id) then
        update mine_sites set auto_on = false, gone = not exists (select 1 from buildings where id = r.building_id) where building_id = r.building_id;
        continue;
      end if;
      if mine_res_k(r.system_id, r.resource) <= 0 or is_capture_active(r.system_id) then continue; end if;
      v_h := case when mine_rested(r.building_id, 'h') then mine_avail(r.building_id, 'h') else 0 end;
      v_d := case when mine_rested(r.building_id, 'd') then mine_avail(r.building_id, 'd') else 0 end;
      v_d := least(v_d, r.places); v_h := least(v_h, r.places - v_d);    -- дроиды первыми: долгие смены — их работа
      -- цех без сырья ждёт; хозяину — одна строка «цех стоит», пока сырьё не появится
      if v_h + v_d > 0 and mine_is_refine(r.resource) and coalesce(mine_input_room(r.building_id, v_d), 0) < 1 then
        if r.idle_since is null then
          update mine_sites set idle_since = now() where building_id = r.building_id;
          perform log_event_digest(sc.controller_user_id, sy.faction, 'production_idle', r.building_id::text, r.system_id, sy.name,
                                   (select name from resources where id = r.resource), null, 'не хватает сырья', false)
             from systems sy left join system_control sc on sc.system_id = sy.id where sy.id = r.system_id;
        end if;
        continue;
      end if;
      if v_h + v_d > 0 then perform mine_start(r.building_id, r.auto_len, r.auto_pace, v_h, v_d, true, null, 'extract'); end if;
    exception when others then perform err_db('mine_tick', sqlstate, sqlerrm, true); end;
  end loop;
  -- склад участка → склад планеты
  for r in select building_id from mine_sites where stock > 0 and not gone loop
    begin perform mine_flush(r.building_id);
    exception when others then perform err_db('mine_tick', sqlstate, sqlerrm, true); end;
  end loop;
end;
$$;


--
-- Name: mine_upgrade(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_upgrade(p_building uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s mine_sites; c jsonb; v_cr integer;
begin
  s := mine_own(p_building);
  c := mine_upgrade_cost(s.places);
  if c is null then raise exception 'Участок уже наибольший'; end if;
  perform assert_planet_operational(s.system_id);
  select credits into v_cr from profiles where id = auth.uid() for update;
  if coalesce(v_cr, 0) < (c ->> 'credits')::integer then raise exception 'Недостаточно кредитов: нужно %', c ->> 'credits'; end if;
  perform take_planet_stock(s.system_id, 'durasteel', (c ->> 'durasteel')::integer);
  perform take_planet_stock(s.system_id, 'electronics', (c ->> 'electronics')::integer);
  update profiles set credits = credits - (c ->> 'credits')::integer where id = auth.uid();
  update mine_sites set places = (c ->> 'places')::integer where building_id = p_building;
  return mine_site_state(p_building);
end;
$$;


--
-- Name: mine_upgrade_cost(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mine_upgrade_cost(p_places integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when p_places < 10 then '{"places": 10, "credits": 2500, "durasteel": 60, "electronics": 0}'::jsonb
              when p_places < 14 then '{"places": 14, "credits": 5000, "durasteel": 120, "electronics": 40}'::jsonb
              when p_places < 18 then '{"places": 18, "credits": 9000, "durasteel": 200, "electronics": 80}'::jsonb end;
$$;


--
-- Name: move_ground_unit(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_ground_unit(p_unit_id uuid, p_x integer, p_y integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; t record; us record;
  v_dist integer;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.x is null then raise exception 'Юнит находится в транспорте'; end if;
  if u.hp <= 0 then raise exception 'Юнит уничтожен'; end if;

  select * into t from unit_types where id = u.unit_type;
  select * into us from unit_stats(p_unit_id);

  v_dist := greatest(abs(p_x - u.x), abs(p_y - u.y));
  if v_dist = 0 then raise exception 'Юнит уже здесь'; end if;
  if v_dist > us.move_range then
    raise exception 'Слишком далеко: за один ход максимум % клеток', us.move_range;
  end if;

  if p_x < 0 or p_y < 0
     or p_x + t.width_cells > v_grid or p_y + t.height_cells > v_grid then
    raise exception 'Клетка вне карты';
  end if;

  if t.is_vehicle and exists (
    select 1 from field_structures s join structure_types st on st.id = s.type_id
    where s.system_id = u.system_id and st.enterable and st.infantry_only
      and s.faction = u.faction
      and boxes_overlap(p_x, p_y, t.width_cells, t.height_cells, s.x, s.y, s.w, s.h)
  ) then
    raise exception 'Технике туда не въехать: окоп, бункер и маскировочная сеть — только для пехоты';
  end if;

  if ground_box_on_building(u.system_id, p_x, p_y, t.width_cells, t.height_cells) then
    raise exception 'Здесь стоит здание базы — обойди его';
  end if;

  if ground_site_at(u.system_id, p_x, p_y, t.width_cells, t.height_cells) = 'settlement' then
    raise exception 'В само поселение не войти — встань в кольце вокруг него';
  end if;
  if ground_site_at(u.system_id, p_x, p_y, t.width_cells, t.height_cells) = 'plot' then
    raise exception 'Это участок под застройку — обойди его';
  end if;

  if not ground_box_free_for(u.system_id, p_x, p_y, t.width_cells, t.height_cells,
                             p_unit_id, u.faction, coalesce(t.is_vehicle, false)) then
    raise exception 'Место занято';
  end if;

  perform spend_unit_action(p_unit_id);
  update unit_positions set x = p_x, y = p_y where id = p_unit_id;
  perform jam_scout(p_unit_id);
  -- Ручной ход отменяет автоход этого юнита (шаги самого автохода — нет)
  perform public.automove_manual('ground', p_unit_id);
end;
$$;


--
-- Name: move_ship(uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_ship(p_ship_id uuid, p_x integer, p_y integer, p_facing integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; t record; st record;
  v_facing integer; v_w integer; v_h integer; v_dist integer;
  v_grid integer := game_setting_int('space_grid_cells', 150);
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;
  if s.carrier_ship_id is not null then raise exception 'Корабль в ангаре'; end if;

  select * into t from ship_types where id = s.ship_type;
  select * into st from ship_stats(p_ship_id);

  -- Разворот необязателен: если не передан, корабль идёт как стоит
  v_facing := coalesce(p_facing, s.facing);

  v_w := ship_box_w(t.width_cells, t.height_cells, v_facing);
  v_h := ship_box_h(t.width_cells, t.height_cells, v_facing);

  v_dist := greatest(abs(p_x - s.x), abs(p_y - s.y));
  if v_dist = 0 and v_facing = s.facing then raise exception 'Корабль уже здесь'; end if;

  if v_dist > st.move_range then
    raise exception 'Слишком далеко: за один ход максимум % клеток', st.move_range;
  end if;

  if p_x < 0 or p_y < 0 or p_x + v_w > v_grid or p_y + v_h > v_grid then
    raise exception 'Клетка вне карты';
  end if;

  if hyperspace_band_at(p_y, v_h) is not null
     and hyperspace_band_at(p_y, v_h) is distinct from hyperspace_side(s.system_id, s.faction) then
    raise exception 'Это зона гиперпространства противника';
  end if;

  if not is_ship_box_free(s.system_id, p_x, p_y, v_w, v_h, p_ship_id) then
    raise exception 'Место занято';
  end if;

  perform spend_ship_action(p_ship_id);
  update ships set x = p_x, y = p_y, facing = v_facing where id = p_ship_id;
  -- Ручной ход отменяет автоход этого корабля (шаги самого автохода — нет)
  perform public.automove_manual('space', p_ship_id);
end;
$$;


--
-- Name: my_faction_powers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_faction_powers() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p.faction is null then '{}'::text[]
    when is_faction_leader(p.id, p.faction) then faction_power_list()
    else coalesce((select r.powers from faction_role_members m
                   join faction_roles r on r.id = m.role_id
                   where m.user_id = p.id and r.faction = p.faction and not r.archived), '{}'::text[])
  end
  from profiles p where p.id = auth.uid();
$$;


--
-- Name: nearest_friendly_system(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nearest_friendly_system(p_from text, p_faction text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with recursive walk(id, depth) as (
    select p_from, 0
    union all
    select case when h.system_a = w.id then h.system_b else h.system_a end, w.depth + 1
    from walk w
    join hyperlanes h on h.system_a = w.id or h.system_b = w.id
    where w.depth < 6
  )
  select w.id
  from walk w
  join systems s on s.id = w.id
  where s.faction = p_faction and w.id <> p_from
  order by w.depth
  limit 1;
$$;


--
-- Name: next_payout_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_payout_at() RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select last_payout_at() + interval '1 day';
$$;


--
-- Name: notify_ready_buildings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_ready_buildings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record;
begin
  for r in
    select b.id, b.owner_user_id, b.faction, b.system_id, b.slot_index, bt.name
    from buildings b join building_types bt on bt.id = b.building_type_id
    where not b.notified and (b.completes_at is null or b.completes_at <= now())
    for update of b skip locked
  loop
    update buildings set notified = true where id = r.id;
    perform log_event(r.owner_user_id, r.faction, r.system_id, 'building_built', r.name, 1, 'private',
                      jsonb_build_object('slot', r.slot_index, 'building_id', r.id));
  end loop;

  for r in
    select s.id, s.owner_user_id, s.faction, s.system_id, s.name
    from space_stations s
    where not s.notified and (s.completes_at is null or s.completes_at <= now())
    for update of s skip locked
  loop
    update space_stations set notified = true where id = r.id;
    perform log_event(r.owner_user_id, r.faction, r.system_id, 'station_built',
                      coalesce(r.name, 'Орбитальная станция'), 1, 'private',
                      jsonb_build_object('layer', 'space'));
  end loop;
end $$;


--
-- Name: npc_cell_ok(text, integer, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_cell_ok(p_system text, p_x integer, p_y integer, p_unit uuid, p_faction text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_x >= 2 and p_y >= 2
     and p_x < game_setting_int('ground_grid_cells', 144) - 2
     and p_y < game_setting_int('ground_grid_cells', 144) - 2
     and not is_in_ground_attack_zone(p_y)
     and not exists (select 1 from settlement_box() b
                     where boxes_overlap(p_x, p_y, 1, 1, b.x, b.y, b.size, b.size))
     and not exists (select 1 from deploy_zones d
                     where d.system_id = p_system
                       and boxes_overlap(p_x, p_y, 1, 1, d.x, d.y, d.size, d.size))
     and ground_box_free_for(p_system, p_x, p_y, 1, 1, p_unit, p_faction, false);
$$;


--
-- Name: npc_cells(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_cells(p_unit uuid, p_range integer) RETURNS TABLE(x integer, y integer, tm integer, home_dist integer, in_zone boolean, cover integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with me as (
    select u.id, u.system_id, u.faction, u.x, u.y, b.home_x, b.home_y
    from unit_positions u join npc_brains b on b.unit_id = u.id
    where u.id = p_unit and u.x is not null
  ),
  cfg as (
    select game_setting_int('ground_grid_cells', 144) as grid,
           game_setting_int('ground_grid_cells', 144) - game_setting_int('ground_attack_zone_height', 4) as band,
           exists (select 1 from me, field_structures s join structure_types st on st.id = s.type_id
                   where s.system_id = me.system_id and st.kind = 'turret'
                     and s.faction in ('republic', 'cis')) as turrets
  ),
  -- Занятые клетки рядом: чужие юниты и постройки, куда пехоте этой фракции нельзя
  occ as (
    select o.x + ox as ox, o.y + oy as oy
    from me
    join unit_positions o on o.system_id = me.system_id and o.layer = 'ground' and o.x is not null
                         and o.id <> me.id
                         and o.x between me.x - p_range - 4 and me.x + p_range
                         and o.y between me.y - p_range - 4 and me.y + p_range
    join unit_types ot on ot.id = o.unit_type
    cross join lateral generate_series(0, ot.width_cells - 1) ox
    cross join lateral generate_series(0, ot.height_cells - 1) oy
    union
    select s.x + sx, s.y + sy
    from me
    join field_structures s on s.system_id = me.system_id
                           and s.x between me.x - p_range - 4 and me.x + p_range
                           and s.y between me.y - p_range - 4 and me.y + p_range
    join structure_types st on st.id = s.type_id
    cross join lateral generate_series(0, s.w - 1) sx
    cross join lateral generate_series(0, s.h - 1) sy
    where not st.enterable or s.faction is distinct from me.faction
  )
  select c.cx, c.cy,
         case when cfg.turrets then npc_turret_margin(me.system_id, c.cx, c.cy) end,
         greatest(abs(c.cx - me.home_x), abs(c.cy - me.home_y)),
         boxes_overlap(c.cx, c.cy, 1, 1, z.x, z.y, z.size, z.size),
         -- Своё укрытие (окоп, бункер) в этой клетке; у мародёров построек нет
         case when me.faction = 'marauder' then 0
              else coalesce((select max(st.cover_pct) from field_structures s
                             join structure_types st on st.id = s.type_id
                             where s.system_id = me.system_id and s.faction = me.faction
                               and s.completes_at <= now() and st.cover_pct > 0
                               and boxes_overlap(c.cx, c.cy, 1, 1, s.x, s.y, s.w, s.h)), 0)::integer end
  from me
  cross join cfg
  cross join settlement_zone_box() z
  cross join settlement_box() sb
  cross join lateral (select me.x + dx as cx, me.y + dy as cy
                      from generate_series(-p_range, p_range) dx, generate_series(-p_range, p_range) dy
                      where dx <> 0 or dy <> 0) c
  where c.cx >= 2 and c.cy >= 2 and c.cx < cfg.grid - 2 and c.cy < least(cfg.grid - 2, cfg.band)
    and not boxes_overlap(c.cx, c.cy, 1, 1, sb.x, sb.y, sb.size, sb.size)
    and not exists (select 1 from occ where occ.ox = c.cx and occ.oy = c.cy)
    and not exists (select 1 from deploy_zones d
                    where d.system_id = me.system_id
                      and boxes_overlap(c.cx, c.cy, 1, 1, d.x, d.y, d.size, d.size))
    -- Мародёр в кольцо захвата не заходит; оказался внутри — шагает только наружу или вдоль,
    -- не глубже (глубина — клеток до внешнего края кольца)
    and (me.faction <> 'marauder'
         or (case when boxes_overlap(c.cx, c.cy, 1, 1, z.x, z.y, z.size, z.size)
                  then least(c.cx - z.x, z.x + z.size - 1 - c.cx, c.cy - z.y, z.y + z.size - 1 - c.cy) + 1
                  else 0 end)
            <= (case when boxes_overlap(me.x, me.y, 1, 1, z.x, z.y, z.size, z.size)
                     then least(me.x - z.x, z.x + z.size - 1 - me.x, me.y - z.y, z.y + z.size - 1 - me.y) + 1
                     else 0 end));
$$;


--
-- Name: npc_enemies(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_enemies(p_unit uuid, p_radius integer) RETURNS TABLE(id uuid, x integer, y integer, w integer, h integer, gap integer, hp integer, max_hp integer, wr integer, cover integer, in_ring boolean, visible boolean, cap integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with me as (
    select u.id, u.system_id, u.faction, u.x, u.y, t.width_cells as w, t.height_cells as h,
           greatest(0, t.vision_range + u.bonus_vision) as vis,
           coalesce(b.kind, 'marauder') as kind
    from unit_positions u
    join unit_types t on t.id = u.unit_type
    left join npc_brains b on b.unit_id = u.id
    where u.id = p_unit and u.layer = 'ground' and u.x is not null
  )
  select e.id, e.x, e.y, et.width_cells, et.height_cells, g.gap, e.hp,
         et.max_hp + e.bonus_hp, et.weapon_range + e.bonus_range,
         structure_cover(e.id),
         boxes_overlap(e.x, e.y, et.width_cells, et.height_cells, z.x, z.y, z.size, z.size),
         g.gap <= me.vis and (sc.cap is null or g.gap <= sc.cap),
         sc.cap
  from me
  cross join settlement_zone_box() z
  join unit_positions e on e.system_id = me.system_id and e.layer = 'ground'
                       and e.x is not null and e.hp > 0 and e.id <> me.id
  join unit_types et on et.id = e.unit_type
  cross join lateral (select box_gap(me.x, me.y, me.w, me.h, e.x, e.y, et.width_cells, et.height_cells) as gap) g
  cross join lateral (
    select case when (case when me.kind = 'militia'
                           then radar_covers(me.system_id, me.faction, e.x, e.y, et.width_cells, et.height_cells)
                           else false end)
                then null
                else least(et.stealth_range,
                           case when coalesce(e.revealed_until, '-infinity'::timestamptz) <= now()
                                 and exists (
                                   select 1 from field_structures c join structure_types ct on ct.id = c.type_id
                                   where c.system_id = e.system_id and ct.kind = 'camo' and c.faction = e.faction
                                     and c.completes_at <= now()
                                     and boxes_overlap(e.x, e.y, et.width_cells, et.height_cells,
                                                       c.x - ct.radius, c.y - ct.radius,
                                                       c.w + ct.radius * 2, c.h + ct.radius * 2))
                                then game_setting_int('camo_detect_cells', 3) end)
           end as cap) sc
  where g.gap <= p_radius
    and not is_in_ground_attack_zone(e.y)
    and e.faction is distinct from me.faction
    -- Мародёрам враги — войска сторон; ополчению — все чужие, мародёры тоже
    and (me.kind = 'militia' or e.faction in ('republic', 'cis'));
$$;


--
-- Name: npc_fire_structure(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_fire_structure(p_attacker uuid, p_structure uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  a record; at_ record; ast record; s record;
  v_dmg integer; v_hp integer;
begin
  -- Мародёр грабит полевую постройку; хозяину — строка в сводке «Мародёры грабят»
  select * into a from unit_positions where id = p_attacker for update;
  if not found or a.x is null or a.hp <= 0 then return null; end if;

  select fs.*, st.name as type_name, sy.name as sys_name into s
  from field_structures fs
  join structure_types st on st.id = fs.type_id
  join systems sy on sy.id = fs.system_id
  where fs.id = p_structure
  for update of fs;
  if not found or s.system_id <> a.system_id or s.faction = a.faction then return null; end if;

  select * into at_ from unit_types where id = a.unit_type;
  select * into ast from unit_stats(p_attacker);
  if coalesce(ast.weapon_range, 0) <= 0 or coalesce(ast.damage, 0) <= 0 then return null; end if;
  if box_gap(a.x, a.y, at_.width_cells, at_.height_cells, s.x, s.y, s.w, s.h) > ast.weapon_range then
    return null;
  end if;

  perform reveal_unit(p_attacker);
  -- Грабят у поселения — поднимается ополчение
  perform marauder_alarm(p_attacker, s.system_id, s.faction, s.x, s.y, s.w, s.h);
  if floor(random() * 100) >= greatest(5, least(95, ast.accuracy)) then return 0; end if;

  v_dmg := greatest(1, round(ast.damage * damage_multiplier(at_.hull_class, 'structure')
                             * structure_damage_mult(p_attacker))::integer);
  update field_structures set hp = greatest(0, field_structures.hp - v_dmg)
  where id = p_structure returning field_structures.hp into v_hp;

  perform log_event_digest(s.owner_user_id, s.faction, 'marauder_loot', 'fs:' || s.id,
                           s.system_id, s.sys_name, s.type_name, v_dmg,
                           case when v_hp <= 0 then 'разрушено' end);
  if v_hp <= 0 then
    perform destroy_structure(p_structure, null);
  end if;
  return v_dmg;
end;
$$;


--
-- Name: npc_fire_unit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_fire_unit(p_attacker uuid, p_target uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  a record; at_ record; t record; tt record; sh record;
  v_kind text; v_hp integer;
begin
  -- Выстрел NPC по юниту: как attack_unit, только без игрока. Очко действия тратит вызывающий.
  select * into a from unit_positions where id = p_attacker for update;
  if not found or a.x is null or a.hp <= 0 then return null; end if;
  select * into t from unit_positions where id = p_target for update;
  if not found or t.x is null or t.hp <= 0 then return null; end if;
  if t.system_id <> a.system_id or t.layer <> a.layer or t.faction = a.faction then return null; end if;

  select * into at_ from unit_types where id = a.unit_type;
  select * into tt from unit_types where id = t.unit_type;
  if coalesce(at_.weapon_range, 0) <= 0 or coalesce(at_.damage, 0) <= 0 then return null; end if;
  if box_gap(a.x, a.y, at_.width_cells, at_.height_cells, t.x, t.y, tt.width_cells, tt.height_cells)
     > (select s.weapon_range from unit_stats(p_attacker) s) then
    return null;
  end if;

  v_kind := coalesce((select b.kind from npc_brains b where b.unit_id = p_attacker), a.faction);
  select * into sh from npc_shot(p_attacker, p_target);
  perform reveal_unit(p_attacker);
  -- Мародёры напали у поселения — поднимается ополчение
  perform marauder_alarm(p_attacker, t.system_id, t.faction, t.x, t.y, tt.width_cells, tt.height_cells);

  if floor(random() * 100) >= sh.chance then
    perform trench_return_fire(p_target, p_attacker);
    perform npc_return_fire(p_target, p_attacker);
    return 0;
  end if;

  update unit_positions set hp = greatest(0, hp - sh.dmg) where id = p_target returning hp into v_hp;

  if v_hp > 0 then
    perform log_event(t.owner_user_id, t.faction, t.system_id, 'unit_damaged', tt.name, sh.dmg, 'private',
                      jsonb_build_object('x', t.x, 'y', t.y, 'hp_left', v_hp, 'npc', v_kind, 'unit_id', t.id));
    perform trench_return_fire(p_target, p_attacker);
    perform npc_return_fire(p_target, p_attacker);
  else
    perform log_event(t.owner_user_id, t.faction, t.system_id, 'unit_killed', tt.name, 1, 'private', jsonb_build_object('npc', v_kind, 'x', t.x, 'y', t.y));
    -- Цель пала, но соседи успевают прикрыть
    perform npc_return_fire(p_target, p_attacker);
    delete from unit_positions where id = p_target;
  end if;
  return sh.dmg;
end;
$$;


--
-- Name: npc_loot(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_loot(p_unit uuid, p_structure uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1
    from unit_positions a join unit_types at_ on at_.id = a.unit_type
    join field_structures s on s.id = p_structure
    where a.id = p_unit and a.x is not null and a.hp > 0
      and s.system_id = a.system_id and s.faction <> a.faction
      and box_gap(a.x, a.y, at_.width_cells, at_.height_cells, s.x, s.y, s.w, s.h)
          <= (select st.weapon_range from unit_stats(p_unit) st)) then
    return 'wait';
  end if;
  if not npc_spend(p_unit) then return 'wait'; end if;
  perform npc_state(p_unit, 'loot');
  return 'loot:' || coalesce(npc_fire_structure(p_unit, p_structure)::text, 'x');
end;
$$;


--
-- Name: npc_marauder_act(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_marauder_act(p_unit uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  me record; br record; us record; tg record; cl record; lt record;
  v_hard integer; v_home integer; v_low boolean; v_aggro boolean; v_tm integer; v_in_turret boolean;
  k_id uuid[]; k_x integer[]; k_y integer[]; k_w integer[]; k_h integer[]; k_wr integer[];
  k_gap integer[]; k_hp integer[]; k_cv integer[];
  c_ok boolean := false; c_x integer[]; c_y integer[]; c_tm integer[]; c_hd integer[];
  c_iz boolean[]; c_cv integer[];
  v_near integer; v_foes integer; v_allies integer; v_tgt uuid; v_turrets boolean;
  v_lx integer; v_ly integer; v_bucket bigint; v_dist integer; v_band integer; v_in_zone boolean;
  m_x integer[]; m_y integer[]; m_vis integer[]; d_x integer[]; d_y integer[]; d_s integer[];
  g_x integer[]; g_y integer[]; g_w integer[]; g_h integer[]; g_wr integer[];
begin
  perform npc_remember(p_unit);

  select * into me from unit_positions where id = p_unit for update;
  if not found or me.x is null or me.hp <= 0 or me.layer <> 'ground' then return null; end if;
  select * into br from npc_brains where unit_id = p_unit;
  if not found then return null; end if;
  if not npc_ready(p_unit) then return 'wait'; end if;

  select * into us from unit_stats(p_unit);
  v_hard := greatest(14, br.leash + 6);               -- дальше от логова не уходит никогда
  v_home := greatest(abs(me.x - br.home_x), abs(me.y - br.home_y));
  v_low := me.hp * 100 <= us.max_hp * 35;
  v_aggro := coalesce(br.aggro_until > now(), false);
  v_tm := npc_turret_margin(me.system_id, me.x, me.y);
  v_in_turret := coalesce(v_tm, 1) <= 0;

  -- Соседи по банде в 6 клетках: их глаза — наши глаза
  select array_agg(m.x), array_agg(m.y), array_agg(greatest(0, mt.vision_range + m.bonus_vision))
    into m_x, m_y, m_vis
  from npc_brains mb
  join unit_positions m on m.id = mb.unit_id
  join unit_types mt on mt.id = m.unit_type
  where mb.kind = 'marauder' and mb.system_id = br.system_id and mb.unit_id <> p_unit
    and m.x is not null and m.hp > 0 and greatest(abs(m.x - me.x), abs(m.y - me.y)) <= 6;

  -- Кого знаем: видим сами, помним обидчика, видят соседи по банде
  select coalesce(array_agg(e.id order by e.gap, e.id), '{}'),
         array_agg(e.x order by e.gap, e.id), array_agg(e.y order by e.gap, e.id),
         array_agg(e.w order by e.gap, e.id), array_agg(e.h order by e.gap, e.id),
         array_agg(e.wr order by e.gap, e.id), array_agg(e.gap order by e.gap, e.id),
         array_agg(e.hp order by e.gap, e.id), array_agg(e.cover order by e.gap, e.id), min(e.gap)
    into k_id, k_x, k_y, k_w, k_h, k_wr, k_gap, k_hp, k_cv, v_near
  from npc_enemies(p_unit, 12) e
  where e.visible
     or (v_aggro and e.id = br.target_id and e.gap <= 10)
     or exists (select 1 from unnest(m_x, m_y, m_vis) m(x, y, vis)
                cross join lateral (select box_gap(m.x, m.y, 1, 1, e.x, e.y, e.w, e.h) as v) mg
                where mg.v <= m.vis and (e.cap is null or mg.v <= e.cap));

  -- Добить: цель падает с одного попадания при хорошем шансе — стреляем в любом состоянии
  select k.id into v_tgt
  from unnest(k_id, k_gap, k_hp) k(id, gap, hp) cross join lateral npc_shot(p_unit, k.id) s
  where k.gap <= us.weapon_range and s.dmg >= k.hp and s.chance >= 50
  order by s.chance desc, k.hp desc, k.id
  limit 1;
  if found then return npc_shoot(p_unit, v_tgt, 'fight'); end if;

  -- Отход: ранен и враг в 5 клетках — в клетку подальше от ближайшего врага, при равенстве ближе к дому
  if v_low and v_near is not null and v_near <= 5 then
    if not c_ok then
      select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
        into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
      c_ok := true;
    end if;
    select c.x, c.y, d.v as dmin into cl
    from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
    cross join lateral (select min(box_gap(c.x, c.y, 1, 1, k.x, k.y, k.w, k.h)) as v
                        from unnest(k_x, k_y, k_w, k_h) k(x, y, w, h)) d
    where (c.home_dist <= v_hard or c.home_dist < v_home)
      and (coalesce(c.tm, 1) > 0 or v_in_turret)
    order by d.v desc, c.home_dist, c.x, c.y
    limit 1;
    if found and cl.dmin > v_near then
      -- Запоминаем, от кого бежим: скрывшись из виду, не пойдёт к нему обратно
      update npc_brains set target_id = k_id[1], aggro_until = greatest(aggro_until, now() + interval '60 seconds')
      where unit_id = p_unit;
      return npc_step(p_unit, cl.x, cl.y, 'retreat');
    end if;
    -- Загнали в угол — отстреливается ниже
  end if;

  -- Под турелью не стоим: выходим из радиуса, по возможности оставаясь в дальности выстрела
  if v_in_turret then
    if not c_ok then
      select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
        into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
      c_ok := true;
    end if;
    select c.x, c.y, c.tm into cl
    from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
    where c.home_dist <= v_hard or c.home_dist < v_home
    order by (coalesce(c.tm, 1) > 0) desc,
             exists (select 1 from unnest(k_x, k_y, k_w, k_h) k(x, y, w, h)
                     where box_gap(c.x, c.y, 1, 1, k.x, k.y, k.w, k.h) <= us.weapon_range) desc,
             c.tm desc nulls first, c.home_dist, c.x, c.y
    limit 1;
    if found and coalesce(cl.tm, 99) > v_tm then
      return npc_step(p_unit, cl.x, cl.y, 'evade');
    end if;
  end if;

  if cardinality(k_id) > 0 then
    -- Бьём того, кого свалим быстрее всего: меньше ожидаемых выстрелов, меньше прочности, без укрытия, ближе
    select k.id into v_tgt
    from unnest(k_id, k_gap, k_hp, k_cv) k(id, gap, hp, cv) cross join lateral npc_shot(p_unit, k.id) s
    where k.gap <= us.weapon_range
    order by ceil(k.hp::numeric / greatest(1, s.dmg)) * 100.0 / greatest(5, s.chance),
             k.hp, (k.cv > 0), k.gap, k.id
    limit 1;
    if found then return npc_shoot(p_unit, v_tgt, 'fight'); end if;

    if not v_low then
      -- Без злости на толпу не лезем: враг может достать — отходим из-под огня, иначе выжидаем
      if not v_aggro then
        select count(*) into v_foes from unnest(k_gap) k(gap) where k.gap <= 7;
        select 1 + count(*) into v_allies
        from unnest(m_x, m_y) m(x, y) where greatest(abs(m.x - me.x), abs(m.y - me.y)) <= 4;

        if v_foes > v_allies + 1 then
          if exists (select 1 from unnest(k_gap, k_wr) k(gap, wr) where k.gap <= k.wr + 1) then
            if not c_ok then
              select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
                into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
              c_ok := true;
            end if;
            select c.x, c.y, d.v as dmin into cl
            from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
            cross join lateral (select min(box_gap(c.x, c.y, 1, 1, k.x, k.y, k.w, k.h)) as v
                                from unnest(k_x, k_y, k_w, k_h) k(x, y, w, h)) d
            where (c.home_dist <= v_hard or c.home_dist < v_home) and (coalesce(c.tm, 1) > 0 or v_in_turret)
            order by d.v desc, c.home_dist, c.x, c.y
            limit 1;
            if found and cl.dmin > v_near then
              return npc_step(p_unit, cl.x, cl.y, 'wary');
            end if;
          end if;
          return npc_state(p_unit, 'wary');
        end if;
      end if;

      -- Сближение: встать ровно на дальность выстрела, не заходя под турели,
      -- подальше от остальных стволов
      if not c_ok then
        select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
          into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
        c_ok := true;
      end if;
      for tg in
        select k.x, k.y, k.w, k.h, k.gap
        from unnest(k_x, k_y, k_w, k_h, k_gap, k_hp, k_id) k(x, y, w, h, gap, hp, id)
        order by k.gap, k.hp, k.id
        limit 3
      loop
        select c.x, c.y, g.v as gt into cl
        from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
        cross join lateral (select box_gap(c.x, c.y, 1, 1, tg.x, tg.y, tg.w, tg.h) as v) g
        cross join lateral (select count(*) as v from unnest(k_x, k_y, k_w, k_h, k_wr) k(x, y, w, h, wr)
                            where box_gap(c.x, c.y, 1, 1, k.x, k.y, k.w, k.h) <= k.wr) t
        where (c.home_dist <= v_hard or c.home_dist < v_home)
          and (coalesce(c.tm, 1) > 0 or v_in_turret)
        order by (g.v <= us.weapon_range) desc,
                 case when g.v <= us.weapon_range then us.weapon_range - g.v else g.v end,
                 t.v, coalesce(c.tm, 99) desc, c.home_dist, c.x, c.y
        limit 1;
        if found and cl.gt < tg.gap then
          return npc_step(p_unit, cl.x, cl.y, 'hunt');
        end if;
      end loop;

      -- Напрямую не подойти (цель за кольцом захвата): обходим кольцо снаружи —
      -- к ближайшей клетке вне кольца, откуда цель достаётся
      select k.x, k.y, k.w, k.h into tg
      from unnest(k_x, k_y, k_w, k_h, k_gap, k_hp, k_id) k(x, y, w, h, gap, hp, id)
      order by k.gap, k.hp, k.id
      limit 1;
      select p.x, p.y into v_lx, v_ly
      from settlement_zone_box() z
      cross join lateral (select gx as x, gy as y
                          from generate_series(tg.x - us.weapon_range, tg.x + tg.w - 1 + us.weapon_range) gx,
                               generate_series(tg.y - us.weapon_range, tg.y + tg.h - 1 + us.weapon_range) gy) p
      where not boxes_overlap(p.x, p.y, 1, 1, z.x, z.y, z.size, z.size)
        and p.x >= 2 and p.y >= 2 and not is_in_ground_attack_zone(p.y)
        and greatest(abs(p.x - br.home_x), abs(p.y - br.home_y)) <= v_hard
        and coalesce(npc_turret_margin(me.system_id, p.x, p.y), 1) > 0
      order by greatest(abs(p.x - me.x), abs(p.y - me.y)), p.x, p.y
      limit 1;
      if v_lx is not null then
        select c.x, c.y, greatest(abs(c.x - v_lx), abs(c.y - v_ly)) as d,
               (c.x - v_lx) * (c.x - v_lx) + (c.y - v_ly) * (c.y - v_ly) as e into cl
        from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
        where (c.home_dist <= v_hard or c.home_dist < v_home)
          and (coalesce(c.tm, 1) > 0 or v_in_turret)
        order by 3, 4, c.x, c.y
        limit 1;
        if found and (cl.d, cl.e) < (greatest(abs(me.x - v_lx), abs(me.y - v_ly)),
                                     (me.x - v_lx) * (me.x - v_lx) + (me.y - v_ly) * (me.y - v_ly)) then
          return npc_step(p_unit, cl.x, cl.y, 'hunt');
        end if;
      end if;
      return npc_state(p_unit, 'hold');
    end if;
  end if;

  -- Раненый без драки — к логову, но не ближе 6 клеток к известным врагам; там отлёживается
  if v_low then
    if v_home > 2 then
      if not c_ok then
        select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
          into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
        c_ok := true;
      end if;
      select c.x, c.y, c.home_dist into cl
      from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
      cross join lateral (select min(box_gap(c.x, c.y, 1, 1, k.x, k.y, k.w, k.h)) as v
                          from unnest(k_x, k_y, k_w, k_h) k(x, y, w, h)) d
      where (coalesce(c.tm, 1) > 0 or v_in_turret)
        and coalesce(d.v, 99) > 5
      order by c.home_dist, c.x, c.y
      limit 1;
      if found and cl.home_dist < v_home then
        return npc_step(p_unit, cl.x, cl.y, 'regroup');
      end if;
    end if;
    return npc_state(p_unit, 'rest');
  end if;

  -- Грабёж: вражеские постройки в 8 клетках, кроме турелей; сперва добыча, кантина, радар, глушилка
  for lt in
    select f.id, f.x, f.y, f.w, f.h, box_gap(me.x, me.y, 1, 1, f.x, f.y, f.w, f.h) as gap
    from field_structures f join structure_types stt on stt.id = f.type_id
    where f.system_id = me.system_id and f.faction in ('republic', 'cis') and stt.kind <> 'turret'
      and box_gap(me.x, me.y, 1, 1, f.x, f.y, f.w, f.h) <= 8
      and (stt.kind <> 'camo'
           or box_gap(me.x, me.y, 1, 1, f.x, f.y, f.w, f.h) <= game_setting_int('camo_detect_cells', 3))
    order by (stt.kind in ('extractor', 'cantina', 'radar', 'jammer')) desc, f.hp,
             box_gap(me.x, me.y, 1, 1, f.x, f.y, f.w, f.h), f.id
    limit 3
  loop
    if lt.gap <= us.weapon_range then
      return npc_loot(p_unit, lt.id);
    end if;

    if not c_ok then
      select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
        into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
      c_ok := true;
    end if;
    select c.x, c.y, g.v as gt into cl
    from unnest(c_x, c_y, c_tm, c_hd) c(x, y, tm, home_dist)
    cross join lateral (select box_gap(c.x, c.y, 1, 1, lt.x, lt.y, lt.w, lt.h) as v) g
    where (c.home_dist <= v_hard or c.home_dist < v_home)
      and (coalesce(c.tm, 1) > 0 or v_in_turret)
    order by (g.v <= us.weapon_range) desc,
             case when g.v <= us.weapon_range then us.weapon_range - g.v else g.v end,
             c.home_dist, c.x, c.y
    limit 1;
    if found and cl.gt < lt.gap then
      return npc_step(p_unit, cl.x, cl.y, 'loot');
    end if;
  end loop;

  -- Слоняться у поселения: точка за кольцом захвата вне выстрела (дальность + 2..4 клетки),
  -- меняется раз в ~2 минуты.
  -- У банды общий дом — и точка общая. Занятость клетки не важна: встанем рядом.
  v_bucket := (extract(epoch from now())::bigint
               + ((hashtext(br.system_id || ':' || br.home_x || ':' || br.home_y)::bigint % 120) + 120) % 120) / 120;
  v_turrets := exists (select 1 from field_structures s join structure_types st on st.id = s.type_id
                       where s.system_id = me.system_id and st.kind = 'turret' and s.faction in ('republic', 'cis'));
  v_band := game_setting_int('ground_grid_cells', 144) - game_setting_int('ground_attack_zone_height', 4);
  select array_agg(d.x), array_agg(d.y), array_agg(d.size) into d_x, d_y, d_s
  from deploy_zones d where d.system_id = me.system_id;

  -- Сперва точки в пределах поводка, нет таких — до 14 клеток от логова
  -- Кто стоит в кольце и докуда бьёт: туда, где достают, не встаём, если есть выбор
  select array_agg(g.x), array_agg(g.y), array_agg(gt.width_cells), array_agg(gt.height_cells),
         array_agg(gt.weapon_range + coalesce(g.bonus_range, 0))
    into g_x, g_y, g_w, g_h, g_wr
  from unit_positions g
  join unit_types gt on gt.id = g.unit_type
  cross join settlement_zone_box() gz
  where g.system_id = me.system_id and g.layer = 'ground' and g.x is not null and g.hp > 0
    and g.faction in ('republic', 'cis') and coalesce(gt.weapon_range, 0) > 0
    and coalesce(gt.splash_size, 0) = 0
    and boxes_overlap(g.x, g.y, gt.width_cells, gt.height_cells, gz.x, gz.y, gz.size, gz.size);

  foreach v_dist in array array[br.leash, v_hard] loop
    select hc.x, hc.y into v_lx, v_ly
    from settlement_zone_box() z
    cross join lateral (select gx as x, gy as y
                        from generate_series(greatest(z.x - us.weapon_range - 4, br.home_x - v_dist), least(z.x + z.size + us.weapon_range + 3, br.home_x + v_dist)) gx,
                             generate_series(greatest(z.y - us.weapon_range - 4, br.home_y - v_dist), least(z.y + z.size + us.weapon_range + 3, br.home_y + v_dist)) gy) hc
    where box_gap(hc.x, hc.y, 1, 1, z.x, z.y, z.size, z.size) between us.weapon_range + 2 and us.weapon_range + 4
      and hc.x >= 2 and hc.y >= 2 and hc.y < v_band
      and not exists (select 1 from unnest(d_x, d_y, d_s) d(x, y, s)
                      where boxes_overlap(hc.x, hc.y, 1, 1, d.x, d.y, d.s, d.s))
      and case when v_turrets then coalesce(npc_turret_margin(me.system_id, hc.x, hc.y), 1) > 0 else true end
    order by (select count(*) from unnest(g_x, g_y, g_w, g_h, g_wr) g(x, y, w, h, wr)
              where box_gap(hc.x, hc.y, 1, 1, g.x, g.y, g.w, g.h) <= g.wr),
             md5(br.system_id || ':' || br.home_x || ':' || br.home_y || ':' || v_bucket || ':' || hc.x || ':' || hc.y)
    limit 1;
    exit when v_lx is not null;
  end loop;

  v_lx := coalesce(v_lx, br.home_x);
  v_ly := coalesce(v_ly, br.home_y);
  v_dist := greatest(abs(me.x - v_lx), abs(me.y - v_ly));
  if v_dist <= 1 and not is_in_settlement_zone(me.x, me.y) then return npc_state(p_unit, 'lurk'); end if;

  if not c_ok then
    select array_agg(c.x), array_agg(c.y), array_agg(c.tm), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
      into c_x, c_y, c_tm, c_hd, c_iz, c_cv from npc_cells(p_unit, us.move_range) c;
    c_ok := true;
  end if;
  -- Оказался в кольце — первым делом выйти из него
  v_in_zone := is_in_settlement_zone(me.x, me.y);
  select c.x, c.y, c.in_zone, greatest(abs(c.x - v_lx), abs(c.y - v_ly)) as d into cl
  from unnest(c_x, c_y, c_tm, c_hd, c_iz) c(x, y, tm, home_dist, in_zone)
  where (not c.in_zone or v_in_zone) and coalesce(c.tm, 1) > 0
    and (c.home_dist <= v_hard or c.home_dist < v_home)
  order by c.in_zone, greatest(abs(c.x - v_lx), abs(c.y - v_ly)),
           (c.x - v_lx) * (c.x - v_lx) + (c.y - v_ly) * (c.y - v_ly), c.x, c.y
  limit 1;
  if found and ((v_in_zone and not cl.in_zone) or cl.d < v_dist) then
    return npc_step(p_unit, cl.x, cl.y, 'lurk');
  end if;
  return npc_state(p_unit, 'lurk');
end;
$$;


--
-- Name: npc_militia_act(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_militia_act(p_unit uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  me record; br record; us record; tg record; cl record; zb record;
  k_id uuid[]; k_x integer[]; k_y integer[]; k_w integer[]; k_h integer[]; k_wr integer[];
  k_gap integer[]; k_hp integer[]; k_cv integer[]; k_ring boolean[];
  c_x integer[]; c_y integer[]; c_hd integer[]; c_iz boolean[]; c_cv integer[];
  m_x integer[]; m_y integer[]; m_vis integer[];
  v_home integer; v_in boolean; v_tgt uuid;
begin
  perform npc_remember(p_unit);

  select * into me from unit_positions where id = p_unit for update;
  if not found or me.x is null or me.hp <= 0 or me.layer <> 'ground' then return null; end if;
  select * into br from npc_brains where unit_id = p_unit;
  if not found then return null; end if;
  if not npc_ready(p_unit) then return 'wait'; end if;

  select * into us from unit_stats(p_unit);
  select * into zb from settlement_zone_box();
  v_home := greatest(abs(me.x - br.home_x), abs(me.y - br.home_y));
  v_in := boxes_overlap(me.x, me.y, 1, 1, zb.x, zb.y, zb.size, zb.size);

  -- Рядом (в радиусе восприятия) никого чужого — смотреть не на что: на посту просто стоим
  if not exists (select 1 from unit_positions e
                 where e.system_id = me.system_id and e.layer = 'ground' and e.x is not null and e.hp > 0
                   and e.faction is distinct from me.faction
                   and e.x between me.x - us.vision_range - 4 and me.x + us.vision_range + 3
                   and e.y between me.y - us.vision_range - 4 and me.y + us.vision_range + 3) then
    if v_home <= 1 then return npc_state(p_unit, 'hold'); end if;
  end if;

  -- Ополчение смотрит общими глазами: враг, замеченный любым ополченцем планеты, известен всем
  select array_agg(m.x), array_agg(m.y), array_agg(greatest(0, mt.vision_range + m.bonus_vision))
    into m_x, m_y, m_vis
  from npc_brains mb
  join unit_positions m on m.id = mb.unit_id
  join unit_types mt on mt.id = m.unit_type
  where mb.kind = br.kind and mb.system_id = br.system_id and mb.unit_id <> p_unit and m.faction = me.faction
    and m.x is not null and m.hp > 0;

  select coalesce(array_agg(e.id order by e.gap, e.id), '{}'),
         array_agg(e.x order by e.gap, e.id), array_agg(e.y order by e.gap, e.id),
         array_agg(e.w order by e.gap, e.id), array_agg(e.h order by e.gap, e.id),
         array_agg(e.wr order by e.gap, e.id), array_agg(e.gap order by e.gap, e.id),
         array_agg(e.hp order by e.gap, e.id), array_agg(e.cover order by e.gap, e.id),
         array_agg(e.in_ring order by e.gap, e.id)
    into k_id, k_x, k_y, k_w, k_h, k_wr, k_gap, k_hp, k_cv, k_ring
  from npc_enemies(p_unit, us.vision_range + 2) e
  where e.visible
     or exists (select 1 from unnest(m_x, m_y, m_vis) m(x, y, vis)
                cross join lateral (select box_gap(m.x, m.y, 1, 1, e.x, e.y, e.w, e.h) as v) mg
                where mg.v <= m.vis and (e.cap is null or mg.v <= e.cap));

  -- Огонь: сперва по тем, кто уже в кольце захвата, затем кого свалим быстрее
  select k.id into v_tgt
  from unnest(k_id, k_gap, k_hp, k_cv, k_ring) k(id, gap, hp, cv, ring)
  cross join lateral npc_shot(p_unit, k.id) s
  where k.gap <= us.weapon_range
  order by k.ring desc,
           ceil(k.hp::numeric / greatest(1, s.dmg)) * 100.0 / greatest(5, s.chance),
           k.hp, (k.cv > 0), k.gap, k.id
  limit 1;
  if found then return npc_shoot(p_unit, v_tgt, 'fight'); end if;

  -- Дальше стрелять не в кого — понадобятся клетки для шага
  if v_home > 1 or cardinality(k_id) > 0 then
    select array_agg(c.x), array_agg(c.y), array_agg(c.home_dist), array_agg(c.in_zone), array_agg(c.cover)
      into c_x, c_y, c_hd, c_iz, c_cv
    from npc_cells(p_unit, us.move_range) c;
  end if;

  -- Ушёл с поста дальше поводка — назад
  if v_home > br.leash then
    select c.x, c.y, c.home_dist into cl
    from unnest(c_x, c_y, c_hd, c_cv) c(x, y, home_dist, cover)
    order by c.home_dist, c.cover desc, c.x, c.y
    limit 1;
    if found and cl.home_dist < v_home then
      return npc_step(p_unit, cl.x, cl.y, 'return');
    end if;
    return npc_state(p_unit, 'hold');
  end if;

  -- Враг рядом, но не достать: подтянуться на дистанцию выстрела, из кольца не выходя
  -- (снаружи — только обратно в кольцо или ближе к нему), укрытие в приоритете
  if cardinality(k_id) > 0 then
    select k.x, k.y, k.w, k.h, k.gap into tg
    from unnest(k_x, k_y, k_w, k_h, k_gap, k_hp, k_ring, k_id) k(x, y, w, h, gap, hp, ring, id)
    order by k.ring desc, k.gap, k.hp, k.id
    limit 1;

    select c.x, c.y, g.v as gt into cl
    from unnest(c_x, c_y, c_hd, c_iz, c_cv) c(x, y, home_dist, in_zone, cover)
    cross join lateral (select box_gap(c.x, c.y, 1, 1, tg.x, tg.y, tg.w, tg.h) as v) g
    cross join lateral (select count(*) as v from unnest(k_x, k_y, k_w, k_h, k_wr) k(x, y, w, h, wr)
                        where box_gap(c.x, c.y, 1, 1, k.x, k.y, k.w, k.h) <= k.wr) t
    where c.home_dist <= br.leash
      and box_gap(c.x, c.y, 1, 1, zb.x, zb.y, zb.size, zb.size) <= 2
      and (c.in_zone or not v_in)
    order by (g.v <= us.weapon_range) desc, c.cover desc, t.v, c.in_zone desc,
             case when g.v <= us.weapon_range then us.weapon_range - g.v else g.v end, c.home_dist, c.x, c.y
    limit 1;
    if found and cl.gt < tg.gap then
      return npc_step(p_unit, cl.x, cl.y, 'advance');
    end if;
    return npc_state(p_unit, 'hold');
  end if;

  -- Тихо — на свой пост
  if v_home > 1 then
    select c.x, c.y, c.home_dist into cl
    from unnest(c_x, c_y, c_hd, c_cv) c(x, y, home_dist, cover)
    order by c.home_dist, c.cover desc, c.x, c.y
    limit 1;
    if found and cl.home_dist < v_home then
      return npc_step(p_unit, cl.x, cl.y, 'return');
    end if;
  end if;
  return npc_state(p_unit, 'hold');
end;
$$;


--
-- Name: npc_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_ready(p_unit uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_ap integer; v_at timestamptz; v_cd integer;
begin
  select u.ap, u.ap_updated_at, coalesce(t.action_seconds, game_setting_int('ship_action_cooldown_seconds', 30))
    into v_ap, v_at, v_cd
  from unit_positions u join unit_types t on t.id = u.unit_type
  where u.id = p_unit;
  if not found then return false; end if;

  if least(game_setting_int('ship_action_max', 2),
           v_ap + floor(extract(epoch from now() - v_at))::integer / greatest(1, v_cd)) < 1 then
    return false;
  end if;

  return true;
end;
$$;


--
-- Name: npc_remember(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_remember(p_unit uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare me record; br record; v_tgt uuid;
begin
  select u.id, u.x, u.y, u.hp into me from unit_positions u where u.id = p_unit;
  if not found then return; end if;
  select * into br from npc_brains where unit_id = p_unit;
  if not found then return; end if;

  if br.kind = 'marauder' and br.last_hp is not null and me.hp < br.last_hp and me.x is not null then
    select e.id into v_tgt from npc_enemies(p_unit, 10) e order by e.gap, e.hp, e.id limit 1;

    update npc_brains set aggro_until = now() + interval '60 seconds', target_id = coalesce(v_tgt, target_id)
    where unit_id = p_unit;

    update npc_brains nb
    set aggro_until = now() + interval '60 seconds',
        target_id = case when nb.aggro_until > now() then nb.target_id else coalesce(v_tgt, nb.target_id) end
    from unit_positions m
    where m.id = nb.unit_id and nb.kind = 'marauder' and nb.system_id = br.system_id
      and nb.unit_id <> p_unit and m.x is not null
      and greatest(abs(m.x - me.x), abs(m.y - me.y)) <= 6;
  end if;

  update npc_brains set last_hp = me.hp where unit_id = p_unit and last_hp is distinct from me.hp;
end;
$$;


--
-- Name: npc_return_fire(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_return_fire(p_target uuid, p_attacker uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  br record; a record; at_ record; t record; tt record; s record; sh record; r record;
  v_helpers integer := game_setting_int('npc_cover_helpers', 2);
  v_cover integer := 0; v_hp integer; v_dmg integer; v_total integer := 0; v_dead boolean := false;
  v_log jsonb := '{}'::jsonb; v_cur jsonb; v_key text; v_sys_name text;
begin
  if p_target is null or p_attacker is null then return 0; end if;
  select * into br from npc_brains where unit_id = p_attacker;
  if not found or br.kind in ('militia', 'partisan') then return 0; end if;
  select * into a from unit_positions where id = p_attacker;
  if not found or a.x is null or a.hp <= 0 or a.owner_user_id is not null then return 0; end if;
  select * into at_ from unit_types where id = a.unit_type;
  select * into t from unit_positions where id = p_target;
  if not found or t.x is null or t.owner_user_id is null or t.layer <> 'ground'
     or t.system_id <> a.system_id then
    return 0;
  end if;
  select * into tt from unit_types where id = t.unit_type;

  for s in
    select u.id, u.owner_user_id, u.faction, u.x, u.y, (u.id = p_target) as me
    from unit_positions u
    join unit_types ut on ut.id = u.unit_type
    cross join lateral unit_stats(u.id) us
    where u.system_id = a.system_id and u.layer = 'ground' and u.x is not null
      and u.faction = t.faction and u.owner_user_id is not null
      and u.x between a.x - 12 and a.x + 12 and u.y between a.y - 12 and a.y + 12
      and (u.hp > 0)
      and coalesce(ut.weapon_range, 0) > 0 and coalesce(ut.damage, 0) > 0
      and coalesce(ut.splash_size, 0) = 0
      and not exists (select 1 from npc_brains nb where nb.unit_id = u.id)
      -- На автомарше прикрывать некогда; сама цель отвечает всегда
      and (u.id = p_target
           or not exists (select 1 from auto_moves am where am.unit_id = u.id and am.status = 'active'))
      and box_gap(u.x, u.y, ut.width_cells, ut.height_cells, a.x, a.y, at_.width_cells, at_.height_cells)
          <= us.weapon_range
    order by (u.id = p_target) desc,
             box_gap(u.x, u.y, ut.width_cells, ut.height_cells, t.x, t.y, tt.width_cells, tt.height_cells),
             u.id
  loop
    exit when v_dead;
    if s.me then
      -- Из окопа цель уже ответила (trench_return_fire): второй раз не стреляет
      continue when unit_in_trench(s.id);
    else
      exit when v_cover >= v_helpers;
    end if;
    -- Нет очка действия — не стреляет; в минус не уходит
    continue when not npc_spend(s.id);
    if not s.me then v_cover := v_cover + 1; end if;

    perform reveal_unit(s.id);
    select * into sh from npc_shot(s.id, p_attacker);
    v_dmg := 0;
    if floor(random() * 100) < sh.chance then
      select hp into v_hp from unit_positions where id = p_attacker for update;
      exit when v_hp is null;
      if sh.dmg >= v_hp then
        v_dmg := v_hp;
        -- Общий путь гибели (зачёт убийства герою и уборка юнита)
        update unit_positions set hp = 1 where id = p_attacker;
        perform hero_strike(s.id, p_attacker, 1);
        v_dead := true;
      else
        v_dmg := sh.dmg;
        update unit_positions set hp = hp - sh.dmg where id = p_attacker;
      end if;
    end if;

    v_total := v_total + v_dmg;
    v_key := s.owner_user_id::text;
    v_cur := coalesce(v_log -> v_key, jsonb_build_object('f', s.faction, 'shots', 0, 'hits', 0, 'dmg', 0));
    v_log := v_log || jsonb_build_object(v_key, v_cur || jsonb_build_object(
               'shots', (v_cur ->> 'shots')::integer + 1,
               'hits', (v_cur ->> 'hits')::integer + case when v_dmg > 0 then 1 else 0 end,
               'dmg', (v_cur ->> 'dmg')::integer + v_dmg));
  end loop;

  if v_log = '{}'::jsonb then return 0; end if;

  -- Сводка: одно событие на игрока, строка на планету, урон копится
  select name into v_sys_name from systems where id = a.system_id;
  for r in select key, value from jsonb_each(v_log) loop
    perform log_event_digest(r.key::uuid, r.value ->> 'f', 'npc_return_fire', a.system_id,
      a.system_id, v_sys_name, 'урон по мародёрам', (r.value ->> 'dmg')::integer,
      case when v_dead then at_.name || ' уничтожен'
           else 'последний залп: попаданий ' || (r.value ->> 'hits') || ' из ' || (r.value ->> 'shots') end);
  end loop;
  return v_total;
end;
$$;


--
-- Name: npc_shoot(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_shoot(p_unit uuid, p_target uuid, p_state text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Цель жива, чужая и достаётся — иначе очко действия не тратим
  if not exists (
    select 1
    from unit_positions a join unit_types at_ on at_.id = a.unit_type
    join unit_positions t on t.id = p_target join unit_types tt on tt.id = t.unit_type
    where a.id = p_unit and a.x is not null and a.hp > 0 and t.x is not null and t.hp > 0
      and t.system_id = a.system_id and t.layer = a.layer and t.faction <> a.faction
      and box_gap(a.x, a.y, at_.width_cells, at_.height_cells, t.x, t.y, tt.width_cells, tt.height_cells)
          <= (select s.weapon_range from unit_stats(p_unit) s)) then
    return 'wait';
  end if;
  if not npc_spend(p_unit) then return 'wait'; end if;
  perform npc_state(p_unit, p_state);
  return p_state || ':' || coalesce(npc_fire_unit(p_unit, p_target)::text, 'x');
end;
$$;


--
-- Name: npc_shot(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_shot(p_attacker uuid, p_target uuid) RETURNS TABLE(dmg integer, chance integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select cap_hero_damage(p_target, d3.v), ch.v
  from unit_positions a
  join unit_types at_ on at_.id = a.unit_type
  cross join unit_stats(p_attacker) ast
  join unit_positions t on t.id = p_target
  join unit_types tt on tt.id = t.unit_type
  -- Из бункера стрелок бьёт сильнее, укрытие цели гасит часть урона
  cross join lateral (select greatest(1, round(ast.damage * damage_multiplier(at_.hull_class, tt.hull_class)
                             * structure_damage_mult(p_attacker))::integer) as v) d1
  cross join lateral (select greatest(1, d1.v) as v) d2
  cross join lateral (select greatest(1, round(d2.v * (100 - structure_cover(p_target)) / 100.0)::integer) as v) d3
  cross join lateral (select greatest(5, least(95, ast.accuracy
                             - greatest(0, tt.evasion + coalesce(t.bonus_evasion, 0)))) as v) ch
  where a.id = p_attacker;
$$;


--
-- Name: npc_spawn_cell_ok(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_spawn_cell_ok(p_system text, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select npc_cell_ok(p_system, p_x, p_y, null, 'marauder')
     and not is_in_settlement_zone(p_x, p_y)
     and coalesce(npc_turret_margin(p_system, p_x, p_y), 1) > 0
     and not exists (select 1 from deploy_zones d
                     where d.system_id = p_system
                       and box_gap(p_x, p_y, 1, 1, d.x, d.y, d.size, d.size) <= 3);
$$;


--
-- Name: npc_spend(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_spend(p_unit uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform spend_unit_action(p_unit);
  return true;
exception when others then perform err_db('npc_spend', sqlstate, sqlerrm, false);
  return false;
end;
$$;


--
-- Name: npc_state(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_state(p_unit uuid, p_state text) RETURNS text
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update npc_brains set state = p_state where unit_id = p_unit and state is distinct from p_state;
  select p_state;
$$;


--
-- Name: npc_step(uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_step(p_unit uuid, p_x integer, p_y integer, p_state text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare u record;
begin
  -- Последняя проверка клетки прямо перед шагом: за время хода её мог занять игрок
  select up.system_id, up.faction, t.width_cells, t.height_cells, t.is_vehicle into u
  from unit_positions up join unit_types t on t.id = up.unit_type where up.id = p_unit;
  if not found or not ground_box_free_for(u.system_id, p_x, p_y, u.width_cells, u.height_cells,
                                          p_unit, u.faction, coalesce(u.is_vehicle, false)) then
    return 'wait';
  end if;
  if not npc_spend(p_unit) then return 'wait'; end if;
  update unit_positions set x = p_x, y = p_y where id = p_unit;
  return npc_state(p_unit, p_state);
end;
$$;


--
-- Name: npc_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_res text;
begin
  -- Тики не накладываются друг на друга
  if not pg_try_advisory_xact_lock(hashtext('npc_tick')) then return; end if;

  -- Дневные налёты: предупреждение, появление банды, уход с добычей
  begin
    perform marauder_raid_tick();
  exception when others then perform err_db('npc_tick', sqlstate, sqlerrm, true);
    raise warning 'marauder_raid_tick: %', sqlerrm;
  end;

  -- Планета ушла к врагу — ополчение прежних хозяев расходится сразу
  delete from unit_positions u
  using npc_brains b, systems s
  where b.unit_id = u.id and b.kind = 'militia' and s.id = b.system_id
    and s.faction is distinct from u.faction;

  -- Подполье (sql/loyalty.sql): планета перешла к своим — бойцы подполья расходятся по домам
  delete from unit_positions u
  using npc_brains b, systems s
  where b.unit_id = u.id and b.kind = 'partisan' and s.id = b.system_id
    and s.faction is not distinct from u.faction;

  -- Тревога: идёт захват или у кольца стоят войска врага. Три минуты тишины — ополчение по домам.
  update npc_brains b set aggro_until = now()
  from systems s
  where b.kind = 'militia' and s.id = b.system_id
    and (exists (select 1 from system_capture c where c.system_id = b.system_id)
         or exists (select 1 from unit_positions e cross join settlement_zone_box() z
                    where e.system_id = b.system_id and e.layer = 'ground' and e.x is not null and e.hp > 0
                      and e.faction in ('republic', 'cis', 'marauder') and e.faction <> s.faction
                      and box_gap(e.x, e.y, 1, 1, z.x, z.y, z.size, z.size) <= 6));

  -- Подполье держится, пока идёт полоса захвата и в кольце стоит живой боец его стороны (игрока)
  update npc_brains b set aggro_until = now()
  from unit_positions pu
  where b.kind = 'partisan' and pu.id = b.unit_id
    and exists (select 1 from system_capture c where c.system_id = b.system_id and c.status <> 'distribution')
    and exists (select 1 from unit_positions x
                 where x.system_id = b.system_id and x.layer = 'ground' and x.hp > 0 and x.x is not null
                   and x.faction = pu.faction and x.owner_user_id is not null and is_in_settlement_zone(x.x, x.y));

  delete from unit_positions u
  using npc_brains b
  where b.unit_id = u.id and b.kind in ('militia', 'partisan')
    and coalesce(b.aggro_until, b.created_at) < now() - interval '3 minutes';

  -- Мародёр уходит: налёт кончился (state = 'leave') или нет задачи поселения
  -- (задачи стёрлись при смене хозяев планеты)
  delete from unit_positions u
  using npc_brains b
  where b.unit_id = u.id and b.kind = 'marauder'
    and (b.state = 'leave'
         or (b.created_at < now() - interval '10 minutes'
             and not exists (select 1 from settlement_tasks t
                    where t.system_id = b.system_id and t.kind = 'marauder'
                      and (t.payload ->> 'unit_id' = u.id::text
                           or coalesce(t.payload -> 'unit_ids', '[]'::jsonb) ? u.id::text))
             -- повстанцы мятежа держатся до его конца (sql/unrest_riot.sql)
             and not exists (select 1 from settlement_riots rr where rr.status = 'active' and u.id = any(rr.rebels))));

  -- Ход NPC: не больше одного действия на юнита
  for r in
    select b.unit_id, b.kind
    from npc_brains b
    join unit_positions u on u.id = b.unit_id
    where u.layer = 'ground' and u.x is not null and u.hp > 0
    order by b.kind desc, b.created_at, b.unit_id
  loop
    begin
      if r.kind = 'marauder' then
        v_res := npc_marauder_act(r.unit_id);
      else
        v_res := npc_militia_act(r.unit_id);
      end if;
    exception when others then perform err_db('npc_tick', sqlstate, sqlerrm, true);
      -- Один сбойный NPC не валит весь тик
      raise warning 'npc_tick %: %', r.unit_id, sqlerrm;
    end;
  end loop;
end;
$$;


--
-- Name: npc_turret_margin(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.npc_turret_margin(p_system text, p_x integer, p_y integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select min(box_gap(p_x, p_y, 1, 1, s.x, s.y, s.w, s.h) - st.radius)::integer
  from field_structures s join structure_types st on st.id = s.type_id
  where s.system_id = p_system and st.kind = 'turret' and s.faction in ('republic', 'cis');
$$;


--
-- Name: observer_near(text, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observer_near(p_system text, p_x integer, p_y integer, p_w integer, p_h integer, p_cells integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from unit_positions o join unit_types ot on ot.id = o.unit_type
    where o.system_id = p_system and o.layer = 'ground' and o.x is not null and o.hp > 0
      and (o.owner_user_id = auth.uid()
           or (o.faction = (select faction from profiles where id = auth.uid())
               and has_relay(auth.uid(), p_system, 'ground')
               and has_relay(o.owner_user_id, p_system, 'ground')))
      and box_gap(o.x, o.y, ot.width_cells, ot.height_cells, p_x, p_y, p_w, p_h) <= p_cells);
$$;


--
-- Name: orbital_drop_zones(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orbital_drop_zones() RETURNS TABLE(idx integer, x integer, y integer, size integer)
    LANGUAGE sql STABLE
    AS $$
  select z.idx, z.x, z.y, s.size
  from (select game_setting_int('orbital_drop_size', 6) as size,
               game_setting_int('space_grid_cells', 150) as grid) s,
  lateral (values
    (1, (s.grid / 4) - (s.size / 2), (s.grid / 2) - (s.size / 2)),
    (2, (s.grid * 3 / 4) - (s.size / 2), (s.grid / 2) - (s.size / 2))
  ) as z(idx, x, y);
$$;


--
-- Name: order_ship(text, text, integer, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_ship(p_system_id text, p_ship_type text, p_fighters integer DEFAULT 0, p_bombers integer DEFAULT 0, p_upgrades text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_faction text; v_credits integer; v_cost integer;
  v_type record; v_seconds integer; v_busy record;
  v_station record; v_sys_faction text;
  v_f record; v_b record; v_fighters integer; v_bombers integer;
  v_missing text; v_wrong text;
begin
  -- созревшие заказы выдаём сразу, не дожидаясь крона
  perform settle_due_orders();
  if v_user_id is null then raise exception 'Не авторизован'; end if;
  if p_ship_type = any(string_to_array(coalesce((select value from game_settings where key = 'locked_for_test'), ''), ',')) then
    raise exception 'Этот корабль пока закрыт';
  end if;

  perform assert_planet_operational(p_system_id);

  select * into v_station from space_stations where system_id = p_system_id for update;
  if not found then raise exception 'В этой системе нет космической станции'; end if;

  perform assert_production_access(v_user_id, p_system_id, null);

  if v_station.completes_at is not null and v_station.completes_at > now() then
    raise exception 'Станция ещё строится: осталось % с',
      greatest(0, ceil(extract(epoch from v_station.completes_at - now()))::integer);
  end if;

  select faction into v_sys_faction from systems where id = p_system_id;
  if v_station.faction is distinct from v_sys_faction then
    raise exception 'Трофейная станция не работает на нового хозяина';
  end if;

  select * into v_busy from shipyard_busy(p_system_id);

  if found then
    raise exception 'Стапель занят: % будет готов через % с',
      coalesce(v_busy.name, 'корабль'),
      greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer);
  end if;

  select * into v_type from ship_types where id = p_ship_type;
  if not found then raise exception 'Неизвестный корабль'; end if;
  if v_type.is_fighter then
    raise exception 'Машины ангара не строятся отдельно — только вместе с носителем';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user_id;
  if v_type.faction is distinct from v_faction then
    raise exception 'Этот корабль недоступен твоей фракции';
  end if;

  select r.name into v_missing
  from unnest(coalesce(p_upgrades, '{}')) u
  join researches r on r.id = u
  where not exists (
    select 1 from player_research pr
    where pr.user_id = v_user_id and pr.research_id = u)
  limit 1;

  if v_missing is not null then
    raise exception 'Не изучено: %', v_missing;
  end if;

  -- Дополнение может не подходить этому классу корабля
  select r.name into v_wrong
  from unnest(coalesce(p_upgrades, '{}')) u
  join researches r on r.id = u
  where not (p_ship_type = any(r.applies_to))
  limit 1;

  if v_wrong is not null then
    raise exception 'Не ставится на этот корабль: %', v_wrong;
  end if;

  v_fighters := greatest(0, coalesce(p_fighters, 0));
  v_bombers  := greatest(0, coalesce(p_bombers, 0));

  if v_fighters + v_bombers > v_type.hangar_slots + coalesce((
       select sum(r.effect_value)::integer from researches r
       where r.id = any(coalesce(p_upgrades,'{}')) and r.effect_kind = 'hangar'), 0) then
    raise exception 'Мест в ангаре не хватает';
  end if;

  select * into v_f from ship_types
  where faction = v_faction and is_fighter and hull_class = 'fighter' limit 1;
  select * into v_b from ship_types
  where faction = v_faction and is_fighter and hull_class = 'bomber' limit 1;

  if v_fighters > 0 and v_f.id is null then raise exception 'У твоей фракции нет истребителей'; end if;
  if v_bombers > 0 and v_b.id is null then raise exception 'У твоей фракции нет бомбардировщиков'; end if;

  v_cost := v_type.cost
          + v_fighters * coalesce(v_f.cost, 0)
          + v_bombers  * coalesce(v_b.cost, 0)
          + coalesce((select sum(r.cost / 4)::integer from researches r
                      where r.id = any(coalesce(p_upgrades,'{}'))), 0);

  if v_credits < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;

  select value::integer into v_seconds from game_settings where key = 'ship_build_seconds';
  v_seconds := coalesce(v_seconds, 60)
             + (v_fighters + v_bombers) * game_setting_int('fighter_build_seconds', 20)
             + coalesce(array_length(p_upgrades, 1), 0) * 10;
  -- законы фракции: ±% времени найма
  v_seconds := greatest(5, round(v_seconds * (100 + effect_sum(p_system_id, 'hire_time')) / 100.0)::integer);

  insert into ship_orders (system_id, ship_type, owner_user_id, faction,
                           completes_at, fighters, bombers, upgrades)
  values (p_system_id, p_ship_type, v_user_id, v_faction,
          now() + make_interval(secs => v_seconds), v_fighters, v_bombers,
          coalesce(p_upgrades, '{}'));

  perform take_build_resources(p_system_id,
             (select cost_resources from ship_types where id = p_ship_type), 1);

  update profiles set credits = credits - v_cost where id = v_user_id;
end;
$$;


--
-- Name: order_unit(uuid, text, integer, integer, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_unit(p_building_id uuid, p_unit_type text, p_quantity integer, p_target_x integer DEFAULT NULL::integer, p_target_y integer DEFAULT NULL::integer, p_upgrades text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_faction text; v_credits integer;
  v_system text; v_completes timestamptz; v_btype_code text;
  v_bld_faction text; v_sys_faction text;
  v_max integer; v_slots integer; v_speed integer; v_active integer;
  v_unit_cost integer; v_unit_faction text; v_produced_by text;
  v_seconds integer; v_total integer; v_free integer;
  v_busy record; v_missing text; v_wrong text;
begin
  -- созревшие заказы выдаём сразу, не дожидаясь крона
  perform settle_due_orders();
  if v_user_id is null then raise exception 'Не авторизован'; end if;
  if p_unit_type = any(string_to_array(coalesce((select value from game_settings where key = 'locked_for_test'), ''), ',')) then
    raise exception 'Этот боец пока закрыт';
  end if;
  if p_quantity is null or p_quantity < 1 then raise exception 'Некорректное количество'; end if;

  select b.system_id, b.completes_at, bt.code, b.faction,
         bt.max_per_order, b.production_slots, b.speed_bonus_pct
    into v_system, v_completes, v_btype_code, v_bld_faction,
         v_max, v_slots, v_speed
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.id = p_building_id
  for update of b;

  if v_system is null then raise exception 'Постройка не найдена'; end if;

  if p_quantity > coalesce(v_max, 5) then
    raise exception 'Эта постройка делает не больше % за раз', coalesce(v_max, 5);
  end if;

  perform assert_planet_operational(v_system);

  -- Управляющий или арендатор этого здания (см. production_leases)
  perform assert_production_access(v_user_id, v_system, p_building_id);

  select faction into v_sys_faction from systems where id = v_system;
  if v_bld_faction is distinct from v_sys_faction then
    raise exception 'Трофейная постройка не работает на нового хозяина — её можно только снести';
  end if;

  if v_completes is not null and v_completes > now() then
    raise exception 'Постройка ещё не достроена';
  end if;

  v_active := building_line_used(p_building_id);

  if v_active >= coalesce(v_slots, 1) then
    select uo.completes_at, ut.name into v_busy
    from unit_orders uo
    left join unit_types ut on ut.id = uo.unit_type
    where uo.building_id = p_building_id and not uo.delivered
    order by uo.completes_at limit 1;

    raise exception 'Линия занята: % будут готовы через % с',
      coalesce(v_busy.name, 'юниты'),
      greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer);
  end if;

  select cost, faction, produced_by into v_unit_cost, v_unit_faction, v_produced_by
  from unit_types where id = p_unit_type;

  if v_unit_cost is null then raise exception 'Неизвестный юнит'; end if;
  if v_produced_by is distinct from v_btype_code then
    raise exception 'Эта постройка не производит такой юнит';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user_id;
  if v_unit_faction is distinct from v_faction then
    raise exception 'Юнит недоступен твоей фракции';
  end if;

  -- Дополнения: изучены лично и подходят именно этому бойцу
  select r.name into v_missing
  from unnest(coalesce(p_upgrades, '{}')) u
  join researches r on r.id = u
  where not exists (select 1 from player_research pr
                    where pr.user_id = v_user_id and pr.research_id = u)
  limit 1;

  if exists (select 1 from unnest(coalesce(p_upgrades, '{}')) u2
             where not exists (select 1 from researches r2 where r2.id = u2)) then
    raise exception 'Неизвестное дополнение';
  end if;

  if v_missing is not null then raise exception 'Не изучено: %', v_missing; end if;

  select r.name into v_wrong
  from unnest(coalesce(p_upgrades, '{}')) u
  join researches r on r.id = u
  where not (p_unit_type = any(r.applies_units)) or r.scope is distinct from 'unit'
  limit 1;

  if v_wrong is not null then
    raise exception 'Не ставится на этого бойца: %', v_wrong;
  end if;

  if p_target_x is not null and p_target_y is not null then
    if not is_deploy_cell_free(v_system, p_target_x, p_target_y) then
      raise exception 'Эта клетка занята или вне зоны высадки';
    end if;
  end if;

  -- Наземка 2.0: бойцы выходят у самой постройки; зоны высадки — запас
  v_free := spawn_space(v_system, p_building_id);
  if v_free < p_quantity then
    raise exception 'У постройки не хватает места: свободно %', greatest(0, v_free);
  end if;

  -- Дополнения оплачиваются на каждого бойца отдельно
  v_total := (v_unit_cost
             + coalesce((select sum(coalesce(r.unit_price, r.cost / 4))::integer from researches r
                         where r.id = any(coalesce(p_upgrades,'{}'))), 0)) * p_quantity;

  if v_credits < v_total then raise exception 'Недостаточно кредитов: нужно %', v_total; end if;

  select value::integer into v_seconds from game_settings where key = 'unit_build_seconds';
  v_seconds := coalesce(v_seconds, 60);
  -- Тяжёлые машины (артиллерия) строятся дольше общего срока
  v_seconds := greatest(v_seconds,
    coalesce((select ut2.build_seconds from unit_types ut2 where ut2.id = p_unit_type), 0));
  v_seconds := greatest(5, round(v_seconds * (100 - coalesce(v_speed, 0)) / 100.0)::integer);
  if settlement_has_district(v_system, 'workshops') then
    v_seconds := greatest(5, round(v_seconds * (100 - (select effect_value from district_types where id = 'workshops')) / 100.0)::integer);
  end if;
  -- законы фракции: ±% времени найма
  v_seconds := greatest(5, round(v_seconds * (100 + effect_sum(v_system, 'hire_time')) / 100.0)::integer);

  insert into unit_orders (system_id, building_id, unit_type, owner_user_id, faction,
                           quantity, completes_at, target_x, target_y, upgrades)
  values (v_system, p_building_id, p_unit_type, v_user_id, v_faction, p_quantity,
          now() + make_interval(secs => v_seconds * p_quantity),
          p_target_x, p_target_y, coalesce(p_upgrades, '{}'));

  perform take_build_resources(v_system,
             (select cost_resources from unit_types where id = p_unit_type), p_quantity);

  update profiles set credits = credits - v_total where id = v_user_id;
end;
$$;


--
-- Name: payout_eligible(timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payout_eligible(p_started timestamp with time zone, p_completed timestamp with time zone, p_payout timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(p_started, '-infinity'::timestamptz)
           < p_payout - make_interval(hours => game_setting_int('payout_lock_hours', 4))
     and coalesce(p_completed, '-infinity'::timestamptz) <= p_payout;
$$;


--
-- Name: place_ship_in_hyperspace(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_ship_in_hyperspace(p_ship_id uuid, p_system_id text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  s record; t record;
  v_side text; v_facing integer;
  v_w integer; v_h integer;
  v_grid integer := game_setting_int('space_grid_cells', 150);
  v_zh integer := game_setting_int('hyperspace_zone_height', 14);
  v_y0 integer; v_y1 integer;
  v_rows integer; v_cols integer;
  v_rmid integer; v_cmid integer;
  dr integer; dc integer; sr integer; sc integer;
  kr integer; kc integer;
  ri integer; ci integer;
  cx integer; cy integer;
begin
  select * into s from ships where id = p_ship_id for update;
  if not found then return false; end if;

  select * into t from ship_types where id = s.ship_type;

  v_side := hyperspace_side(p_system_id, s.faction);
  v_facing := hyperspace_facing(v_side);
  v_w := ship_box_w(t.width_cells, t.height_cells, v_facing);
  v_h := ship_box_h(t.width_cells, t.height_cells, v_facing);

  if v_side = 'top' then
    v_y0 := 0; v_y1 := v_zh - v_h;
  else
    v_y0 := v_grid - v_zh; v_y1 := v_grid - v_h;
  end if;

  v_rows := greatest(0, floor((v_y1 - v_y0) / v_h::numeric)::integer);
  v_cols := greatest(0, floor((v_grid - v_w) / v_w::numeric)::integer);
  v_rmid := v_rows / 2;
  v_cmid := v_cols / 2;

  -- От середины полосы наружу
  for dr in 0..v_rows loop
    for kr in 0..1 loop
      sr := case when kr = 0 then 1 else -1 end;
      continue when dr = 0 and sr = -1;

      ri := v_rmid + sr * dr;
      continue when ri < 0 or ri > v_rows;
      cy := v_y0 + ri * v_h;

      for dc in 0..v_cols loop
        for kc in 0..1 loop
          sc := case when kc = 0 then 1 else -1 end;
          continue when dc = 0 and sc = -1;

          ci := v_cmid + sc * dc;
          continue when ci < 0 or ci > v_cols;
          cx := ci * v_w;

          if is_ship_box_free(p_system_id, cx, cy, v_w, v_h, p_ship_id) then
            update ships set system_id = p_system_id, x = cx, y = cy,
                             facing = v_facing, in_transit = false
            where id = p_ship_id;
            return true;
          end if;
        end loop;
      end loop;
    end loop;
  end loop;

  -- Полоса забита — встаём у её кромки в открытом космосе
  if v_side = 'top' then
    cy := v_zh;
    while cy <= v_grid - v_h loop
      cx := 0;
      while cx <= v_grid - v_w loop
        if hyperspace_band_at(cy, v_h) is null
           and is_ship_box_free(p_system_id, cx, cy, v_w, v_h, p_ship_id) then
          update ships set system_id = p_system_id, x = cx, y = cy,
                           facing = v_facing, in_transit = false
          where id = p_ship_id;
          return true;
        end if;
        cx := cx + v_w;
      end loop;
      cy := cy + v_h;
    end loop;
  else
    cy := v_grid - v_zh - v_h;
    while cy >= 0 loop
      cx := 0;
      while cx <= v_grid - v_w loop
        if hyperspace_band_at(cy, v_h) is null
           and is_ship_box_free(p_system_id, cx, cy, v_w, v_h, p_ship_id) then
          update ships set system_id = p_system_id, x = cx, y = cy,
                           facing = v_facing, in_transit = false
          where id = p_ship_id;
          return true;
        end if;
        cx := cx + v_w;
      end loop;
      cy := cy - v_h;
    end loop;
  end if;

  -- Совсем некуда: корабль остаётся в пути и попробует сесть
  -- на следующем проходе крона, а не пропадает
  return false;
end;
$$;


--
-- Name: planet_cell_ok(text, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.planet_cell_ok(p_system text, p_x integer, p_y integer, p_w integer, p_h integer, p_move text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  pm planet_maps%rowtype;
  mask text;
  i integer; j integer;
begin
  if p_move = 'air' then return true; end if;
  select * into pm from planet_maps where system_id = p_system;
  if not found then return true; end if;
  if p_x < 0 or p_y < 0 or p_x + p_w > pm.w or p_y + p_h > pm.h then return false; end if;
  if p_w >= 2 and p_h >= 2 then
    mask := case when p_move = 'hover' then pm.hover2 else pm.track2 end;
    for j in 0 .. p_h - 2 loop
      for i in 0 .. p_w - 2 loop
        if substr(mask, (p_y + j) * pm.w + p_x + i + 1, 1) <> '1' then return false; end if;
      end loop;
    end loop;
    return true;
  end if;
  mask := case when p_move = 'hover' then pm.hover1 when p_move = 'track' then pm.track1 else pm.foot1 end;
  for j in 0 .. p_h - 1 loop
    for i in 0 .. p_w - 1 loop
      if substr(mask, (p_y + j) * pm.w + p_x + i + 1, 1) <> '1' then return false; end if;
    end loop;
  end loop;
  return true;
end;
$$;


--
-- Name: planet_stock_cap(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.planet_stock_cap(p_system_id text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select game_setting_int('planet_stock_base_cap', 200)
       + case when settlement_has_district(p_system_id, 'warehouses')
              then (select effect_value from district_types where id = 'warehouses') else 0 end
       + coalesce((
           select sum(bt.storage_bonus)::integer
           from buildings b join building_types bt on bt.id = b.building_type_id
           join systems sy on sy.id = b.system_id
           where b.system_id = p_system_id
             and (b.completes_at is null or b.completes_at <= now())
             and b.faction = sy.faction
         ), 0);
$$;


--
-- Name: production_access_error(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_access_error(p_user uuid, p_system_id text, p_building_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare l public.production_leases; v_ctrl boolean; v_name text;
begin
  l := lease_live_for(p_system_id, p_building_id);
  v_ctrl := exists (select 1 from system_control sc
                    where sc.system_id = p_system_id and sc.controller_user_id = p_user);
  if l.id is not null then
    if l.lessee_id = p_user then return null; end if;
    if v_ctrl then
      select nickname into v_name from profiles where id = l.lessee_id;
      return format('Сдано в аренду игроку %s ещё на %s — пока аренда идёт, %s здесь может только он',
                    coalesce(v_name, 'союзнику'), lease_left_text(l.ends_at),
                    case when p_building_id is null then 'заказывать корабли' else 'нанимать' end);
    end if;
    return 'Планета под контролем другого игрока';
  end if;
  if not v_ctrl then
    -- Бывший арендатор: объясняем, что срок вышел, а не «чужая планета»
    if exists (select 1 from production_leases x
               where x.lessee_id = p_user and x.system_id = p_system_id
                 and x.building_id is not distinct from p_building_id
                 and x.status in ('active','ended','void') and x.starts_at is not null
                 and coalesce(x.closed_at, x.ends_at) > now() - interval '1 day') then
      return 'Аренда закончилась — производство вернулось хозяину планеты';
    end if;
    return 'Планета под контролем другого игрока';
  end if;
  return null;
end;
$$;


--
-- Name: production_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  b record; k text; v_need integer; v_rate integer; v_got integer;
  v_enough boolean; v_room integer; v_have integer;
  v_day integer := game_setting_int('settlement_day_seconds', 86400);
  -- Все доходы приходят в один час (04:00 по серверу). Здание, начатое
  -- позже 00:00, в эту выдачу не попадает — ждёт следующих суток.
  v_p timestamptz := last_payout_at();
begin
  for b in
    select bd.id, bd.system_id, bd.faction,
           bt.produces_resource as res, bt.produces_per_day as per_day,
           bt.consumes,
           s.primary_resource as prim, s.secondary_resource as sec,
           sc.controller_user_id
    from buildings bd
    join building_types bt on bt.id = bd.building_type_id
    join systems s on s.id = bd.system_id
    left join system_control sc on sc.system_id = bd.system_id
    where bt.produces_resource is not null
      and not exists (select 1 from mine_sites ms where ms.building_id = bd.id)
      and bt.produces_per_day > 0
      and (bd.completes_at is null or bd.completes_at <= now())
      and (bd.last_extract_at is null or bd.last_extract_at < v_p)
      and payout_eligible(bd.built_at, bd.completes_at, v_p)
  loop
    if b.consumes = '{}'::jsonb then
      -- ---------- добыча ----------
      if    b.res = b.prim then v_rate := b.per_day;
      elsif b.res = b.sec  then v_rate := b.per_day / 2;
      else  v_rate := 0;
      end if;
      -- донесения и события: ±% добычи на планете
      if v_rate > 0 then v_rate := greatest(0, round(v_rate * (100 + effect_sum(b.system_id, 'extract')) / 100.0))::integer; end if;

      if v_rate > 0 then
        v_got := add_planet_stock(b.system_id, b.res, v_rate);

        if b.controller_user_id is not null then
          perform log_event_digest(b.controller_user_id, b.faction, 'resource_extracted',
            b.system_id || ':' || b.res, b.system_id,
            (select name from systems where id = b.system_id),
            (select name from resources where id = b.res), v_got,
            case when v_rate - v_got > 0 then 'склад полон, потеряно ' || (v_rate - v_got) end);
        end if;
      end if;

      update buildings set last_extract_at = now() where id = b.id;

    else
      -- ---------- передел ----------
      -- Сначала убеждаемся, что и сырья хватает, и готовому есть куда лечь:
      -- иначе переработка съела бы руду и выбросила результат в переполненный склад
      v_enough := true;

      for k in select jsonb_object_keys(b.consumes) loop
        v_need := (b.consumes ->> k)::integer;
        select coalesce(amount, 0) into v_have
        from planet_stock where system_id = b.system_id and resource = k;
        if coalesce(v_have, 0) < v_need then v_enough := false; end if;
      end loop;

      select planet_stock_cap(b.system_id)
             - coalesce((select amount from planet_stock
                         where system_id = b.system_id and resource = b.res), 0)
        into v_room;

      if not v_enough then
        if b.controller_user_id is not null then
          -- Раньше это писалось каждые пять минут, пока цех стоит
          perform log_event_digest(b.controller_user_id, b.faction, 'production_idle',
            b.id::text, b.system_id, (select name from systems where id = b.system_id),
            (select name from resources where id = b.res), null, 'не хватает сырья', false);
        end if;
        -- Сутки не сбрасываем: как только сырьё появится, цех подхватит
        continue;
      end if;

      if v_room <= 0 then
        if b.controller_user_id is not null then
          perform log_event_digest(b.controller_user_id, b.faction, 'production_idle',
            b.id::text, b.system_id, (select name from systems where id = b.system_id),
            (select name from resources where id = b.res), null, 'склад полон', false);
        end if;
        continue;
      end if;

      for k in select jsonb_object_keys(b.consumes) loop
        perform take_planet_stock(b.system_id, k, (b.consumes ->> k)::integer);
      end loop;

      v_got := add_planet_stock(b.system_id, b.res, b.per_day);

      if b.controller_user_id is not null then
        perform log_event_digest(b.controller_user_id, b.faction, 'resource_refined',
          b.system_id || ':' || b.res, b.system_id,
          (select name from systems where id = b.system_id),
          (select name from resources where id = b.res), v_got, null);
      end if;

      update buildings set last_extract_at = now() where id = b.id;
    end if;
  end loop;
end;
$$;


--
-- Name: push_ship_out_of_band(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_ship_out_of_band(p_ship_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  s record; t record;
  v_grid integer := game_setting_int('space_grid_cells', 150);
  v_zh integer := game_setting_int('hyperspace_zone_height', 14);
  v_w integer; v_h integer; v_band text;
  cy integer; cx integer; step integer;
begin
  select * into s from ships where id = p_ship_id for update;
  if not found then return false; end if;

  select * into t from ship_types where id = s.ship_type;
  v_w := ship_box_w(t.width_cells, t.height_cells, s.facing);
  v_h := ship_box_h(t.width_cells, t.height_cells, s.facing);

  v_band := hyperspace_band_at(s.y, v_h);
  if v_band is null then return true; end if;

  -- Идём от кромки вглубь карты, сохраняя положение по горизонтали
  if v_band = 'top' then
    cy := v_zh; step := v_h;
  else
    cy := v_grid - v_zh - v_h; step := -v_h;
  end if;

  while cy >= 0 and cy + v_h <= v_grid loop
    if hyperspace_band_at(cy, v_h) is null then
      for cx in 0..(v_grid - v_w) loop
        if is_ship_box_free(s.system_id, cx, cy, v_w, v_h, p_ship_id) then
          update ships set x = cx, y = cy where id = p_ship_id;
          return true;
        end if;
      end loop;
    end if;
    cy := cy + step;
  end loop;

  return false;
end;
$$;


--
-- Name: radar_covers(text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.radar_covers(p_system text, p_faction text, p_x integer, p_y integer, p_w integer, p_h integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_faction is not null and p_x is not null and exists (
    select 1 from field_structures s join structure_types st on st.id = s.type_id
    where s.system_id = p_system and st.kind = 'radar' and s.faction = p_faction
      and s.completes_at <= now()
      and box_gap(p_x, p_y, p_w, p_h, s.x, s.y, s.w, s.h) <= st.radius);
$$;


--
-- Name: raise_militia(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_militia(p_system text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  ss record; zb record; sb record;
  v_fac text; v_type text; v_hp integer; v_wr integer; v_garrison boolean;
  v_count integer; v_alive integer; v_n integer := 0;
  v_cx integer; v_cy integer; v_id uuid; v_ctrl uuid; v_meta jsonb; i integer;
begin
  select faction into v_fac from systems where id = p_system and not is_deep_space;
  if v_fac is null or v_fac not in ('republic', 'cis') then return 0; end if;
  -- забастовки и мятеж (sql/unrest_riot.sql): люди не встают на защиту
  if game_setting_int('unrest_penalties_enabled', 0) = 1
     and coalesce((select value from settlement_unrest where system_id = p_system), 0) >= 75 then return 0; end if;

  select * into ss from settlement_state where system_id = p_system for update;
  if not found then return 0; end if;
  if ss.militia_ready_at is not null and ss.militia_ready_at > now() then return 0; end if;

  -- Сколько жителей возьмётся за оружие (уровень, казармы, довольство) — одна формула с окном поселения
  v_garrison := settlement_has_district(p_system, 'garrison');
  v_count := coalesce(settlement_militia_count(p_system), 0);

  -- Кто ещё стоит с прошлого сбора — в счёт
  select count(*) into v_alive
  from npc_brains b join unit_positions u on u.id = b.unit_id
  where b.kind = 'militia' and b.system_id = p_system and u.hp > 0;
  v_count := v_count - v_alive;
  if v_count <= 0 then return 0; end if;

  v_type := case v_fac when 'republic' then 'rep_militia' else 'cis_militia' end;
  select max_hp, weapon_range into v_hp, v_wr from unit_types where id = v_type;
  select * into zb from settlement_zone_box();
  select * into sb from settlement_box();

  for i in 1..v_count loop
    -- Кольцо захвата вокруг поселения, ближе к тем, кто его штурмует, но не вплотную:
    -- на дистанции своего выстрела (вплотную — под меч джедая)
    select g.cx, g.cy into v_cx, v_cy
    from (select gx as cx, gy as cy
          from generate_series(zb.x, zb.x + zb.size - 1) gx,
               generate_series(zb.y, zb.y + zb.size - 1) gy) g
    cross join lateral (
      select min(box_gap(g.cx, g.cy, 1, 1, e.x, e.y, et.width_cells, et.height_cells)) as v
      from unit_positions e join unit_types et on et.id = e.unit_type
      where e.system_id = p_system and e.layer = 'ground' and e.x is not null and e.hp > 0
        and e.faction in ('republic', 'cis', 'marauder') and e.faction <> v_fac) mg
    where not boxes_overlap(g.cx, g.cy, 1, 1, sb.x, sb.y, sb.size, sb.size)
      and ground_box_free_for(p_system, g.cx, g.cy, 1, 1, null, v_fac, false)
    order by (mg.v is null), abs(mg.v - greatest(1, v_wr)), mg.v, random()
    limit 1;
    exit when not found;

    insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type, quantity, hp)
    values (p_system, 'ground', v_cx, v_cy, null, v_fac, v_type, 1, v_hp)
    returning id into v_id;

    -- aggro_until у ополчения — «последняя тревога»: по ней npc_tick распускает сбор
    insert into npc_brains (unit_id, kind, system_id, home_x, home_y, leash, state, last_hp, aggro_until)
    values (v_id, 'militia', p_system, v_cx, v_cy, 3, 'hold', v_hp, now());
    v_n := v_n + 1;
  end loop;

  if v_n = 0 then return 0; end if;

  update settlement_state
  set militia_raised_at = now(),
      militia_ready_at = now() + case when v_garrison then interval '3 hours' else interval '6 hours' end
  where system_id = p_system;

  v_meta := jsonb_build_object('count', v_n, 'x', sb.x + sb.size / 2, 'y', sb.y + sb.size / 2);
  perform log_event(null, v_fac, p_system, 'militia_raised', v_type, v_n, 'faction', v_meta);

  select controller_user_id into v_ctrl from system_control where system_id = p_system;
  if v_ctrl is not null then
    perform log_event(v_ctrl, v_fac, p_system, 'militia_raised', v_type, v_n, 'private', v_meta);
  end if;
  return v_n;
end;
$$;


--
-- Name: raise_partisans(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_partisans(p_system text, p_faction text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sy record; pl planet_loyalty; st jsonb; v_cell integer; v_n integer; v_type text; v_hp integer; zb record; sb record;
  v_cx integer; v_cy integer; v_id uuid; v_made integer := 0; v_ctl uuid; v_meta jsonb; i integer; v_g timestamptz;
begin
  if not loyalty_on('effects') or p_faction is null or p_faction not in ('republic', 'cis') then return 0; end if;
  select id, name, faction into sy from systems where id = p_system and not coalesce(is_deep_space, false);
  if not found or coalesce(sy.faction, '') not in ('republic', 'cis') or sy.faction = p_faction then return 0; end if;
  if loyalty_capital(p_system) then return 0; end if;
  select * into pl from planet_loyalty where system_id = p_system for update;
  if not found then return 0; end if;
  v_g := loyalty_grace_until(p_system);
  if v_g is not null and v_g > now() then return 0; end if;
  if pl.partisans_at is not null and pl.partisans_at > now() - interval '6 hours' then return 0; end if;

  st := loyalty_stage_of(pl.value * loyalty_side(sy.faction));
  select level into v_cell from loyalty_cells where system_id = p_system and faction = p_faction;
  v_n := coalesce(v_cell, 0) * 2
       + case when (st ->> 'n')::integer <= -3 then 3 when (st ->> 'n')::integer = -2 and v_cell is not null then 1 else 0 end;
  v_n := least(9, v_n) - (select count(*) from npc_brains b join unit_positions u on u.id = b.unit_id
                           where b.kind = 'partisan' and b.system_id = p_system and u.hp > 0 and u.faction = p_faction);
  if v_n <= 0 then return 0; end if;

  v_type := case p_faction when 'republic' then 'rep_militia' else 'cis_militia' end;
  select max_hp into v_hp from unit_types where id = v_type;
  select * into zb from settlement_zone_box();
  select * into sb from settlement_box();
  for i in 1..v_n loop
    -- в кольце захвата рядом с наступающими: подполье выходит к своим
    select g.cx, g.cy into v_cx, v_cy
    from (select gx as cx, gy as cy
          from generate_series(zb.x, zb.x + zb.size - 1) gx,
               generate_series(zb.y, zb.y + zb.size - 1) gy) g
    cross join lateral (
      select min(box_gap(g.cx, g.cy, 1, 1, e.x, e.y, et.width_cells, et.height_cells)) as v
      from unit_positions e join unit_types et on et.id = e.unit_type
      where e.system_id = p_system and e.layer = 'ground' and e.x is not null and e.hp > 0
        and e.faction = p_faction) al
    where not boxes_overlap(g.cx, g.cy, 1, 1, sb.x, sb.y, sb.size, sb.size)
      and ground_box_free_for(p_system, g.cx, g.cy, 1, 1, null, p_faction, false)
    order by (al.v is null), al.v, random()
    limit 1;
    exit when not found;

    insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type, quantity, hp)
    values (p_system, 'ground', v_cx, v_cy, null, p_faction, v_type, 1, v_hp)
    returning id into v_id;
    insert into npc_brains (unit_id, kind, system_id, home_x, home_y, leash, state, last_hp, aggro_until)
    values (v_id, 'partisan', p_system, v_cx, v_cy, 3, 'hold', v_hp, now());
    v_made := v_made + 1;
  end loop;
  if v_made = 0 then return 0; end if;

  update planet_loyalty set partisans_at = now() where system_id = p_system;
  v_meta := jsonb_build_object('count', v_made, 'x', sb.x + sb.size / 2, 'y', sb.y + sb.size / 2, 'faction', p_faction);
  perform log_event(null, p_faction, p_system, 'partisans_raised', sy.name || ': подполье поднялось за нас · ' || v_made, v_made, 'faction', v_meta);
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  if v_ctl is not null then
    perform log_event(v_ctl, sy.faction, p_system, 'partisans_enemy', sy.name || ': подполье встало за врага · ' || v_made, v_made, 'private', v_meta);
  end if;
  return v_made;
end;
$$;


--
-- Name: record_hero_kill(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_hero_kill(p_killer uuid, p_victim_type text, p_victim_faction text, p_victim_owner uuid, p_system text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_hero uuid;
begin
  if p_killer is null then return; end if;
  select hero_id into v_hero from unit_positions where id = p_killer;
  if v_hero is null then return; end if;

  insert into hero_kills (hero_id, victim_unit_type, victim_faction,
                          victim_owner_user_id, system_id)
  values (v_hero, p_victim_type, p_victim_faction, p_victim_owner, p_system);
end;
$$;


--
-- Name: refund_build_resources(text, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_build_resources(p_system_id text, p_cost jsonb, p_share numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare k text; v_amt integer; v_got integer; v_out jsonb := '{}'::jsonb;
begin
  if p_cost is null or p_cost = '{}'::jsonb or coalesce(p_share, 0) <= 0 then return v_out; end if;
  for k in select jsonb_object_keys(p_cost) loop
    v_amt := floor(coalesce((p_cost ->> k)::numeric, 0) * least(1, p_share))::integer;
    continue when v_amt <= 0;
    v_got := add_planet_stock(p_system_id, k, v_amt);
    v_out := v_out || jsonb_build_object(k, coalesce(v_got, 0));
  end loop;
  return v_out;
end;
$$;


--
-- Name: refund_pending_on_capture(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_pending_on_capture(p_system_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  r record;
  v_half integer;
  o record;
  v_back integer;
  v_goods integer;
  v_fit integer;
begin
  -- Юниты в производстве
  for r in
    select uo.id, uo.owner_user_id, uo.quantity, ut.cost, ut.name
    from unit_orders uo
    join unit_types ut on ut.id = uo.unit_type
    where uo.system_id = p_system_id and not uo.delivered
  loop
    v_half := floor(coalesce(r.cost, 0) * r.quantity / 2.0);
    update profiles set credits = credits + v_half where id = r.owner_user_id;
    delete from unit_orders where id = r.id;

    perform log_event(r.owner_user_id, null, p_system_id, 'order_refunded',
                      r.name, r.quantity, 'private',
                      jsonb_build_object('refund', v_half, 'reason', 'capture'));
  end loop;

  -- Незаконченный ремонт
  for r in
    select ro.id, ro.owner_user_id, ro.cost
    from repair_orders ro
    where ro.system_id = p_system_id and not ro.delivered
  loop
    v_half := floor(coalesce(r.cost, 0) / 2.0);
    update profiles set credits = credits + v_half where id = r.owner_user_id;
    delete from repair_orders where id = r.id;

    perform log_event(r.owner_user_id, null, p_system_id, 'order_refunded',
                      'Ремонт', 1, 'private',
                      jsonb_build_object('refund', v_half, 'reason', 'capture'));
  end loop;

  -- Корабли на стапеле
  for r in
    select so.id, so.owner_user_id, st.cost, st.name
    from ship_orders so
    join ship_types st on st.id = so.ship_type
    where so.system_id = p_system_id and not so.delivered
  loop
    v_half := floor(coalesce(r.cost, 0) / 2.0);
    update profiles set credits = credits + v_half where id = r.owner_user_id;
    delete from ship_orders where id = r.id;

    perform log_event(r.owner_user_id, null, p_system_id, 'order_refunded',
                      r.name, 1, 'private',
                      jsonb_build_object('refund', v_half, 'reason', 'capture'));
  end loop;

  -- Недостроенные здания
  for r in
    select b.id, b.owner_user_id, bt.cost, bt.name
    from buildings b
    join building_types bt on bt.id = b.building_type_id
    where b.system_id = p_system_id
      and b.completes_at is not null and b.completes_at > now()
  loop
    v_half := floor(coalesce(r.cost, 0) / 2.0);
    update profiles set credits = credits + v_half where id = r.owner_user_id;
    delete from buildings where id = r.id;

    perform log_event(r.owner_user_id, null, p_system_id, 'construction_refunded',
                      r.name, 1, 'private',
                      jsonb_build_object('refund', v_half, 'reason', 'capture'));
  end loop;

  -- Рынок: лоты на захваченной планете закрываются. Покупателям — деньги по броням,
  -- товар (непроданный и забронированный) остаётся на складе планеты: ресурсы при захвате остаются на ней
  perform 1 from market_orders mo join market_lots l on l.id = mo.lot_id
   where l.system_id = p_system_id and l.active and mo.status = 'reserved'
   order by mo.id for update of mo;
  for r in
    select l.* from market_lots l where l.system_id = p_system_id and l.active order by l.id for update
  loop
    v_goods := r.amount_left;
    for o in
      select * from market_orders mo where mo.lot_id = r.id and mo.status = 'reserved' for update
    loop
      v_back := o.amount_left * o.price_per_unit;
      update profiles set credits = credits + v_back where id = o.buyer_user_id;
      update market_orders set status = 'cancelled', amount_left = 0 where id = o.id;
      v_goods := v_goods + o.amount_left;
      perform log_event(o.buyer_user_id, null, p_system_id, 'market_order_cancelled', null, v_back, 'private',
                        jsonb_build_object('reason', 'capture'));
    end loop;
    -- ресурсы при захвате остаются на планете целиком — и то, что выше предела склада (как запас, внесённый вручную)
    v_fit := add_planet_stock(p_system_id, r.resource, v_goods);
    if v_goods > v_fit then
      update planet_stock set amount = amount + (v_goods - v_fit)
       where system_id = p_system_id and resource = r.resource;
    end if;
    update market_lots set active = false, amount_left = 0 where id = r.id;
    perform log_event(r.seller_user_id, r.seller_faction, p_system_id, 'market_cancelled', r.resource, v_goods, 'private',
                      jsonb_build_object('reason', 'capture'));
  end loop;

  -- Недостроенная станция
  for r in
    select ss.system_id, ss.owner_user_id, ss.faction, bt.cost
    from space_stations ss
    left join building_types bt on bt.is_space and bt.faction = ss.faction
    where ss.system_id = p_system_id
      and ss.completes_at is not null and ss.completes_at > now()
  loop
    v_half := floor(coalesce(r.cost, 5000) / 2.0);
    update profiles set credits = credits + v_half where id = r.owner_user_id;
    delete from space_stations where system_id = p_system_id;

    perform log_event(r.owner_user_id, null, p_system_id, 'construction_refunded',
                      'Орбитальная станция', 1, 'private',
                      jsonb_build_object('refund', v_half, 'reason', 'capture'));
  end loop;
end;
$$;


--
-- Name: rename_hero(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_hero(p_hero_id uuid, p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_user uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_old text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if length(v_name) < 2 then raise exception 'Кличка слишком короткая'; end if;
  if length(v_name) > 24 then raise exception 'Кличка длиннее 24 символов'; end if;
  if v_name !~ '^[[:alnum:] ''-]+$' then
    raise exception 'В кличке можно использовать только буквы, цифры, пробел, дефис и апостроф';
  end if;

  select name into v_old from heroes
  where id = p_hero_id and owner_user_id = v_user and died_at is null;

  if v_old is null then raise exception 'Одарённый не найден'; end if;

  if exists (select 1 from heroes
             where owner_user_id = v_user and died_at is null
               and id <> p_hero_id and lower(name) = lower(v_name)) then
    raise exception 'Кличка % уже занята', v_name;
  end if;

  update heroes set name = v_name where id = p_hero_id;
  update unit_positions set hero_name = v_name where hero_id = p_hero_id;
end;
$_$;


--
-- Name: rename_ship(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_ship(p_ship_id uuid, p_name text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_name text;
  s record;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  v_name := ship_name_clean(p_name);

  select id, owner_user_id into s from ships where id = p_ship_id for update;
  if not found or s.owner_user_id is distinct from v_user then
    raise exception 'Корабль не найден';
  end if;

  if v_name is not null then
    perform pg_advisory_xact_lock(hashtext('ship_name:' || v_user::text));
    if exists (select 1 from ships
               where owner_user_id = v_user and id <> p_ship_id
                 and lower(name) = lower(v_name)) then
      raise exception 'Корабль с именем «%» у тебя уже есть', v_name;
    end if;
  end if;

  update ships set name = v_name where id = p_ship_id;
  return v_name;
end $$;


--
-- Name: repair_building_kind(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_building_kind(p_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_code in ('rep_medical', 'cis_repair')  then 'infantry'
    when p_code in ('rep_vehicle', 'cis_vehicle') then 'vehicle'
    else null end;
$$;


--
-- Name: repair_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_quote(p_unit_id uuid) RETURNS TABLE(missing integer, full_hp integer, cost integer, seconds integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select m.missing, m.full_hp,
         greatest(1, ceil(t.cost * m.missing::numeric / nullif(m.full_hp, 0)
                          * game_setting_int('repair_cost_pct', 100) / 100.0)::integer),
         greatest(5, round(game_setting_int('repair_seconds_full', 120)
                           * m.missing::numeric / nullif(m.full_hp, 0))::integer)
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  cross join lateral (
    select (t.max_hp + u.bonus_hp) as full_hp,
           greatest(0, (t.max_hp + u.bonus_hp) - u.hp) as missing
  ) m
  where u.id = p_unit_id;
$$;


--
-- Name: report_apply(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_apply(p_id uuid, p_choice integer, p_auto boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r player_reports; c report_catalog; o jsonb; u jsonb; fx jsonb; v_tot numeric := 0; v_roll numeric; v_i integer := 0; v_pick integer := 0; k text; v_n integer;
  v_got jsonb := '{}'::jsonb; v_title text; v_fac text; v_have integer; v_take integer; v_res jsonb := '{}'::jsonb; v_cr integer := 0; v_unit uuid;
begin
  select * into r from player_reports where id = p_id for update;
  if not found or r.status <> 'new' then return null; end if;
  select * into c from report_catalog where id = r.report_id;
  o := c.data->'opts'->p_choice;
  if o is null then raise exception 'Нет такого варианта'; end if;
  select faction into v_fac from profiles where id = r.user_id;
  -- планета уже не своя: донесение закрывается без последствий (чужой склад и поселение не трогаем)
  if not exists (select 1 from system_control where system_id = r.system_id and controller_user_id = r.user_id) then
    u := jsonb_build_object('i', -1, 'text', 'Планета больше не под нашим контролем — донесение потеряло смысл.', 'got', '{}'::jsonb, 'lost', true);
    update player_reports set status = 'expired', choice = null, auto = true, resolved_at = now(), outcome = u where id = r.id;
    perform log_event(r.user_id, v_fac, r.system_id, 'report_result', (c.data->>'title') || ': планета потеряна', 1, 'private', jsonb_build_object('report', r.id, 'auto', true));
    return u || jsonb_build_object('next', false);
  end if;
  for u in select * from jsonb_array_elements(o->'outs') loop v_tot := v_tot + (u->>'p')::numeric; end loop;
  v_roll := random() * v_tot;
  for u in select * from jsonb_array_elements(o->'outs') loop
    v_roll := v_roll - (u->>'p')::numeric;
    if v_roll < 0 then v_pick := v_i; exit; end if;
    v_i := v_i + 1;
    v_pick := v_i;
  end loop;
  v_pick := least(v_pick, jsonb_array_length(o->'outs') - 1);
  u := o->'outs'->v_pick; fx := coalesce(u->'fx', '{}'::jsonb);
  v_title := (c.data->>'title') || ' · ' || (o->>'label');
  foreach k in array array['mood', 'extract', 'income'] loop
    if fx ? k then
      insert into active_effects (system_id, kind, value, title, source, source_id, user_id, ends_at)
      values (r.system_id, k, (fx->k->>0)::integer, v_title, 'report', r.id, r.user_id, now() + make_interval(hours => (fx->k->>1)::integer));
      v_got := v_got || jsonb_build_object(k, fx->k);
    end if;
  end loop;
  if fx ? 'cr' then
    v_n := (fx->>'cr')::integer;
    if v_n < 0 then select greatest(-credits, v_n) into v_n from profiles where id = r.user_id; end if;
    update profiles set credits = credits + v_n where id = r.user_id;
    v_cr := v_n; v_got := v_got || jsonb_build_object('cr', v_n);
  end if;
  if fx ? 'res' then
    for k, v_n in select key, value::integer from jsonb_each_text(fx->'res') loop
      if v_n > 0 then v_take := add_planet_stock(r.system_id, k, v_n);
      else
        select coalesce(amount, 0) into v_have from planet_stock where system_id = r.system_id and resource = k;
        v_take := least(coalesce(v_have, 0), -v_n);
        if v_take > 0 then perform take_planet_stock(r.system_id, k, v_take); end if;
        v_take := -v_take;
      end if;
      if v_take <> 0 then v_res := v_res || jsonb_build_object(k, v_take); end if;
    end loop;
    if v_res <> '{}'::jsonb then v_got := v_got || jsonb_build_object('res', v_res); end if;
  end if;
  if fx ? 'raid' then
    begin perform spawn_marauder_gang(r.system_id, (fx->>'raid')::integer); v_got := v_got || jsonb_build_object('raid', (fx->>'raid')::integer);
    exception when others then perform err_db('report_apply', sqlstate, sqlerrm, true); null; end;
  end if;
  if fx ? 'gift' then
    begin v_unit := report_gift(r.system_id, r.user_id, fx->>'gift' = 'veh'); if v_unit is not null then v_got := v_got || jsonb_build_object('gift', fx->>'gift'); end if;
    exception when others then perform err_db('report_apply', sqlstate, sqlerrm, true); null; end;
  end if;
  -- донесение с участка (sql/mine_reports.sql): последствия на самом участке
  if fx ? 'mine' and r.building_id is not null then
    begin v_got := v_got || jsonb_build_object('mine', mine_report_fx(r.building_id, fx->'mine'));
    exception when others then perform err_db('report_apply', sqlstate, sqlerrm, true); end;
  end if;
  update player_reports set status = case when p_auto then 'expired' else 'done' end, choice = p_choice, auto = p_auto, resolved_at = now(),
         outcome = jsonb_build_object('i', v_pick, 'text', u->>'text', 'got', v_got),
         next_id = fx->>'next', next_at = case when fx ? 'next' then now() + make_interval(hours => 20 + floor(random() * 8)::integer) end
   where id = r.id;
  perform log_event(r.user_id, v_fac, r.system_id, 'report_result', (c.data->>'title') || ': ' || left(u->>'text', 80), 1, 'private', jsonb_build_object('report', r.id, 'auto', p_auto));
  return jsonb_build_object('i', v_pick, 'text', u->>'text', 'got', v_got, 'next', fx ? 'next');
end;
$$;


--
-- Name: report_badge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_badge() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::integer from player_reports where user_id = auth.uid() and status = 'new' and expires_at > now();
$$;


--
-- Name: report_choose(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_choose(p_id uuid, p_choice integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); r player_reports; c report_catalog; o jsonb; k text; v_n integer; v_have integer; v_res jsonb;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select * into r from player_reports where id = p_id and user_id = v_me for update;
  if not found then raise exception 'Донесение не найдено'; end if;
  if r.status <> 'new' then raise exception 'Решение уже принято'; end if;
  if r.expires_at <= now() then raise exception 'Время на ответ вышло'; end if;
  select * into c from report_catalog where id = r.report_id;
  if p_choice is null or p_choice < 0 or p_choice >= coalesce(jsonb_array_length(c.data->'opts'), 0) then
    raise exception 'Нет такого варианта';
  end if;
  o := c.data->'opts'->p_choice;
  if o is null then raise exception 'Нет такого варианта'; end if;
  -- планета потеряна — закрыть без цены и последствий
  if not exists (select 1 from system_control where system_id = r.system_id and controller_user_id = v_me) then
    return report_apply(r.id, p_choice, false);
  end if;
  if o->'cost' is not null and jsonb_typeof(o->'cost') = 'object' then
    if (o->'cost') ? 'cr' then
      if (select credits from profiles where id = v_me) < (o->'cost'->>'cr')::integer then raise exception 'Не хватает кредитов: нужно %', o->'cost'->>'cr'; end if;
    end if;
    v_res := coalesce(o->'cost'->'res', '{}'::jsonb);
    for k, v_n in select key, value::integer from jsonb_each_text(v_res) loop
      select coalesce(amount, 0) into v_have from planet_stock where system_id = r.system_id and resource = k;
      if coalesce(v_have, 0) < v_n then raise exception 'На складе планеты не хватает: % (нужно %, есть %)', coalesce((select name from resources where id = k), k), v_n, coalesce(v_have, 0); end if;
    end loop;
    if (o->'cost') ? 'cr' then update profiles set credits = credits - (o->'cost'->>'cr')::integer where id = v_me; end if;
    for k, v_n in select key, value::integer from jsonb_each_text(v_res) loop perform take_planet_stock(r.system_id, k, v_n); end loop;
  end if;
  return report_apply(r.id, p_choice, false);
end;
$$;


--
-- Name: report_client_errors(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_client_errors(p_items jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := auth.uid();
  v_n integer; v_acc integer := 0;
  it jsonb; v_msg text; v_src text; v_line integer; v_col integer; v_cnt integer; v_sig text;
begin
  if v_me is null or p_items is null or jsonb_typeof(p_items) <> 'array' then return 0; end if;
  insert into client_error_rate as r (user_id, win, n) values (v_me, now(), 0)
  on conflict (user_id) do update
     set win = case when r.win < now() - interval '10 minutes' then now() else r.win end,
         n   = case when r.win < now() - interval '10 minutes' then 0 else r.n end
  returning n into v_n;
  if v_n >= 40 then return 0; end if;
  for it in select e from jsonb_array_elements(p_items) with ordinality q(e, o) where o <= 10 loop
    exit when v_n >= 40;
    continue when jsonb_typeof(it) <> 'object' or coalesce(btrim(it ->> 'msg'), '') = '';
    v_msg  := left(btrim(it ->> 'msg'), 500);
    v_src  := left(nullif(it ->> 'src', ''), 300);
    v_line := case when (it ->> 'line') ~ '^\d{1,7}$' then (it ->> 'line')::integer end;
    v_col  := case when (it ->> 'col') ~ '^\d{1,7}$' then (it ->> 'col')::integer end;
    v_cnt  := least(greatest(case when (it ->> 'n') ~ '^\d{1,7}$' then (it ->> 'n')::integer else 1 end, 1), 10000);
    v_sig  := md5(v_msg || '|' || coalesce(v_src, '') || '|' || coalesce(v_line::text, '') || '|' || coalesce(v_col::text, ''));
    if not exists (select 1 from client_errors where sig = v_sig)
       and (select count(*) from client_errors) >= 3000 then
      continue;
    end if;
    insert into client_errors as c (sig, msg, src, line, col, stack, page, ctx, ua, n, last_user)
    values (v_sig, v_msg, v_src, v_line, v_col,
            left(nullif(it ->> 'stack', ''), 4000), left(nullif(it ->> 'page', ''), 200),
            left(nullif(it ->> 'ctx', ''), 60), left(nullif(it ->> 'ua', ''), 300), v_cnt, v_me)
    on conflict (sig) do update
       set n = least(c.n + excluded.n, 2000000000), last_at = now(), last_user = v_me,
           stack = coalesce(excluded.stack, c.stack), page = coalesce(excluded.page, c.page),
           ctx = coalesce(excluded.ctx, c.ctx), ua = coalesce(excluded.ua, c.ua);
    insert into client_error_users (sig, user_id) values (v_sig, v_me) on conflict do nothing;
    if found then
      update client_errors set users = (select count(*) from client_error_users u where u.sig = v_sig) where sig = v_sig;
    end if;
    v_n := v_n + 1; v_acc := v_acc + 1;
  end loop;
  update client_error_rate set n = v_n where user_id = v_me;
  return v_acc;
end;
$_$;


--
-- Name: report_deliver(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_deliver(p_user uuid, p_report text, p_system text, p_slot integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c report_catalog; v_id uuid; v_fac text;
begin
  select * into c from report_catalog where id = p_report;
  if not found then return null; end if;
  select faction into v_fac from profiles where id = p_user;
  insert into player_reports (user_id, report_id, system_id, day, slot, expires_at)
  values (p_user, p_report, p_system, (now() at time zone event_tz())::date, p_slot,
          now() + make_interval(hours => event_setting_int('report_answer_hours', 12)))
  returning id into v_id;
  perform log_event(p_user, v_fac, p_system, 'report_new', c.data->>'title', 1, 'private', jsonb_build_object('report', v_id));
  return v_id;
end;
$$;


--
-- Name: report_gift(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_gift(p_system text, p_user uuid, p_vehicle boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_faction text; v_type record; z record; cx integer; cy integer; tries integer := 0; v_id uuid;
begin
  select faction into v_faction from profiles where id = p_user;
  if v_faction is null then return null; end if;
  select * into v_type from unit_types where faction = v_faction and is_vehicle = coalesce(p_vehicle, false) and produced_by is not null order by random() limit 1;
  if not found then return null; end if;
  select * into z from settlement_zone_box();
  while tries < 80 loop
    tries := tries + 1;
    cx := z.x - 4 + floor(random() * (z.size + 8))::integer;
    cy := z.y - 4 + floor(random() * (z.size + 8))::integer;
    continue when not is_ground_box_free(p_system, cx, cy, v_type.width_cells, v_type.height_cells, null);
    insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type, quantity, hp)
    values (p_system, 'ground', cx, cy, p_user, v_faction, v_type.id, 1, v_type.max_hp) returning id into v_id;
    return v_id;
  end loop;
  return null;
end;
$$;


--
-- Name: report_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_list() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid();
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  return jsonb_build_object(
    'now', now(),
    'per_day', event_setting_int('report_per_day', 2), 'from_h', event_setting_int('report_start_hour', 10),
    'to_h', event_setting_int('report_end_hour', 22), 'answer_h', event_setting_int('report_answer_hours', 12),
    'credits', (select credits from profiles where id = v_me),
    'reports', (select coalesce(jsonb_agg(x order by x->>'status' = 'new' desc, x->>'at' desc), '[]'::jsonb) from (
       select jsonb_build_object('id', r.id, 'report', r.report_id, 'cat', c.cat, 'chain', c.chain, 'status', r.status, 'at', r.created_at, 'expires', r.expires_at,
                'system', r.system_id, 'planet', s.name, 'site', (select bt.name from buildings bd join building_types bt on bt.id = bd.building_type_id where bd.id = r.building_id), 'def', c.def, 'choice', r.choice, 'auto', r.auto, 'outcome', r.outcome, 'resolved', r.resolved_at,
                'next', r.next_id is not null and not r.next_sent,
                'data', jsonb_build_object('title', c.data->'title', 'text', c.data->'text',
                          'opts', (select jsonb_agg(o - 'outs' order by n) from jsonb_array_elements(c.data->'opts') with ordinality t(o, n))),
                'stock', case when r.status = 'new' and exists (select 1 from system_control scx
                                   where scx.system_id = r.system_id and scx.controller_user_id = v_me) then (select coalesce(jsonb_object_agg(ps.resource, ps.amount), '{}'::jsonb) from planet_stock ps where ps.system_id = r.system_id) end) x
       from player_reports r join report_catalog c on c.id = r.report_id left join systems s on s.id = r.system_id
       where r.user_id = v_me and (r.status = 'new' or r.resolved_at > now() - interval '7 days')
       order by r.created_at desc limit 40) q),
    'effects', (select coalesce(jsonb_agg(jsonb_build_object('system', e.system_id, 'planet', s.name, 'kind', e.kind, 'value', e.value, 'title', e.title, 'ends', e.ends_at) order by e.ends_at), '[]'::jsonb)
       from (select system_id, kind, value, title, ends_at from active_effects where ends_at > now() and starts_at <= now()
             union all
             select system_id, kind, value, case when source like 'event:%' then 'Событие · ' when source in ('unrest', 'riot', 'riot_end') then 'Напряжение · ' when source = 'loyalty' then 'Настроения · ' else 'Казна · ' end || title, ends_at from faction_effects
              where system_id is not null and kind in ('mood', 'extract', 'income') and ends_at > now() and starts_at <= now()
                and faction = (select faction from profiles where id = v_me)) e
       left join systems s on s.id = e.system_id
       where e.system_id in (select system_id from system_control where controller_user_id = v_me)),
    'laws', (select coalesce(jsonb_agg(jsonb_build_object('kind', fe.kind, 'value', fe.value, 'title', fe.title, 'ends', fe.ends_at, 'decree', fe.source = 'decree',
                 'src', case when fe.source like 'event:%' then 'event' when fe.source like 'find:%' then 'find' when fe.source = 'decree' then 'decree' else 'law' end) order by fe.ends_at), '[]'::jsonb)
       from faction_effects fe where fe.faction = (select faction from profiles where id = v_me) and fe.starts_at <= now() and fe.ends_at > now()
         and fe.system_id is null and fe.kind in ('mood', 'extract', 'income')),
    'planets', (select coalesce(jsonb_agg(jsonb_build_object('system', sc.system_id, 'planet', s.name,
                  'mood', effect_sum(sc.system_id, 'mood'), 'extract', effect_sum(sc.system_id, 'extract'), 'income', effect_sum(sc.system_id, 'income'))), '[]'::jsonb)
       from system_control sc join systems s on s.id = sc.system_id where sc.controller_user_id = v_me));
end;
$$;


--
-- Name: report_pick(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pick(p_user uuid, p_side text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.id from report_catalog c
  where c.side = p_side and c.active and not c.chain and c.cat <> 'site'
    and not exists (select 1 from player_reports r where r.user_id = p_user and r.report_id = c.id and r.created_at > now() - interval '14 days')
  order by -ln(random()) / greatest(c.w, 1) limit 1;
$$;


--
-- Name: report_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  tz text := event_tz(); v_now timestamptz := now(); v_day date := (now() at time zone event_tz())::date; r record; p record;
  v_start integer := event_setting_int('report_start_hour', 10); v_end integer := event_setting_int('report_end_hour', 22);
  v_per integer := greatest(0, least(6, event_setting_int('report_per_day', 2))); v_block numeric; v_k integer; v_due timestamptz; v_sys text; v_pick text; v_n integer := 0;
begin
  if not pg_try_advisory_xact_lock(hashtext('report_tick')) then return 0; end if;
  for r in select pr.id, c.def from player_reports pr join report_catalog c on c.id = pr.report_id where pr.status = 'new' and pr.expires_at <= v_now loop
    perform report_apply(r.id, r.def, true);
  end loop;
  for r in select pr.* from player_reports pr where pr.next_id is not null and not pr.next_sent and pr.next_at <= v_now loop
    update player_reports set next_sent = true where id = r.id;
    select coalesce((select system_id from system_control where system_id = r.system_id and controller_user_id = r.user_id),
                    (select system_id from system_control where controller_user_id = r.user_id order by random() limit 1)) into v_sys;
    if v_sys is not null then perform report_deliver(r.user_id, r.next_id, v_sys, null); v_n := v_n + 1; end if;
  end loop;
  if v_per = 0 then return v_n; end if;
  v_block := (v_end - v_start) * 60.0 / v_per;
  for p in select pf.id, pf.faction from profiles pf
            where pf.faction is not null and pf.last_seen_at > v_now - make_interval(days => event_setting_int('report_seen_days', 3))
              and exists (select 1 from system_control sc where sc.controller_user_id = pf.id) loop
    select count(*) into v_k from player_reports where user_id = p.id and day = v_day and slot is not null;
    continue when v_k >= v_per;
    v_due := ((v_day + make_interval(hours => v_start)) at time zone tz)
             + make_interval(mins => floor(v_k * v_block + abs(hashtext(p.id::text || v_day::text || v_k)) % greatest(1, floor(v_block * 0.6)::integer))::integer);
    continue when v_now < v_due or v_now >= ((v_day + make_interval(hours => v_end)) at time zone tz);
    select system_id into v_sys from system_control where controller_user_id = p.id order by random() limit 1;
    v_pick := report_pick(p.id, p.faction);
    continue when v_pick is null or v_sys is null;
    perform report_deliver(p.id, v_pick, v_sys, v_k);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: request_planet(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_planet(p_system_id text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_faction text; v_name text; v_sys record; v_leader uuid; v_ctrl uuid; v_id uuid; v_to uuid;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction, nickname into v_faction, v_name from profiles where id = v_me;
  if v_faction is null then raise exception 'Фракция ещё не назначена'; end if;

  select * into v_sys from systems where id = p_system_id;
  if not found or v_sys.is_deep_space then raise exception 'Планета не найдена'; end if;
  if v_sys.faction is distinct from v_faction then
    raise exception 'Запросить можно только планету своей фракции';
  end if;

  select leader_user_id into v_leader from faction_leadership where faction = v_faction;
  if v_leader is null and not exists (
       select 1 from faction_role_members m join faction_roles r on r.id = m.role_id
       join profiles pr on pr.id = m.user_id
       where r.faction = v_faction and not r.archived and pr.faction = v_faction
         and 'planet_requests' = any(r.powers) and m.user_id <> v_me) then
    raise exception 'Некому рассмотреть запрос: у фракции нет лидера';
  end if;
  if v_leader = v_me then
    raise exception 'Ты лидер — назначь управляющего в панели управления фракции';
  end if;

  select controller_user_id into v_ctrl from system_control where system_id = p_system_id;
  if v_ctrl = v_me then raise exception 'Эта планета уже под твоим управлением'; end if;

  if exists (select 1 from planet_requests
             where user_id = v_me and system_id = p_system_id and status = 'pending') then
    raise exception 'Запрос на эту планету уже отправлен';
  end if;

  if (select count(*) from planet_requests where user_id = v_me and status = 'pending') >= 3 then
    raise exception 'Не больше трёх запросов одновременно — дождись ответа лидера';
  end if;

  insert into planet_requests (system_id, user_id, faction, note)
  values (p_system_id, v_me, v_faction, nullif(left(btrim(coalesce(p_note, '')), 140), ''))
  returning id into v_id;

  -- Уведомление лидеру и всем, кому поручены заявки
  for v_to in
    select distinct u from (
      select v_leader as u
      union all
      select m.user_id from faction_role_members m join faction_roles r on r.id = m.role_id
      join profiles pr on pr.id = m.user_id
      where r.faction = v_faction and not r.archived and pr.faction = v_faction
        and 'planet_requests' = any(r.powers)) q
    where u is not null and u <> v_me
  loop
    perform log_event(v_to, v_faction, p_system_id, 'planet_request',
                      v_name || ' просит управление', 1, 'private',
                      jsonb_build_object('request_id', v_id));
  end loop;
  return v_id;
end;
$$;


--
-- Name: request_supply_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_supply_access(p_owner_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_fac text; v_ofac text; v_id uuid; v_name text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_owner_user_id is null or p_owner_user_id = v_user then raise exception 'Нельзя запросить доступ у себя'; end if;
  select faction, nickname into v_fac, v_name from profiles where id = v_user;
  select faction into v_ofac from profiles where id = p_owner_user_id;
  if v_ofac is null then raise exception 'Игрок не найден'; end if;
  if v_ofac is distinct from v_fac then raise exception 'Доступ можно просить только у своей стороны'; end if;

  select g.id into v_id from supply_grants g
   where g.owner_user_id = p_owner_user_id and g.grantee_user_id = v_user and g.status in ('pending', 'active');
  if v_id is not null then return v_id; end if;

  if exists (select 1 from supply_grants g
             where g.owner_user_id = p_owner_user_id and g.grantee_user_id = v_user
               and g.status in ('declined', 'revoked')
               and coalesce(g.decided_at, g.created_at) > now() - interval '10 minutes') then
    raise exception 'Запрос уже отклонён — попробуй позже';
  end if;

  insert into supply_grants (owner_user_id, grantee_user_id, status, requested_by)
  values (p_owner_user_id, v_user, 'pending', v_user)
  returning id into v_id;

  perform log_event(p_owner_user_id, v_fac, null, 'supply_access_requested', v_name, 1, 'private',
                    jsonb_build_object('grant_id', v_id, 'from_user', v_user));
  return v_id;
end $$;


--
-- Name: reset_settlement_on_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_settlement_on_capture() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.faction is distinct from old.faction then
    update settlement_state
    set satisfaction = 0, cycle_started = now(),
        level = greatest(1, level - 1), dev_points = 0, upgrade_until = null, upgrade_to = null,
        fed = null, food_short = 0, militia_ready_at = null
    where system_id = new.id;

    delete from settlement_districts where system_id = new.id;
    delete from settlement_tasks where system_id = new.id;
    perform issue_settlement_tasks(new.id, now());
  end if;
  return null;
end;
$$;


--
-- Name: resolve_planet_request(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_planet_request(p_id uuid, p_approve boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  r record; v_sys text; v_req_faction text; v_sys_faction text; o record; v_name text;
begin
  select system_id into v_sys from planet_requests where id = p_id;
  if v_sys is null then raise exception 'Запрос не найден'; end if;

  -- Сначала планета, потом запрос: два одновременных «Выдать» на одну
  -- планету выстраиваются в очередь, и второй увидит, что её уже отдали
  perform 1 from systems where id = v_sys for update;

  select * into r from planet_requests where id = p_id for update;
  if not faction_power(v_me, r.faction, 'planet_requests') then
    raise exception 'Рассматривать запросы может лидер и те, кому он это поручил';
  end if;
  -- Свою же заявку ответственный не выдаёт сам себе
  if r.user_id = v_me and not is_faction_leader(v_me, r.faction) then
    raise exception 'Свою заявку рассматривает лидер или другой ответственный';
  end if;
  if r.status <> 'pending' then
    return jsonb_build_object('ok', false, 'message', 'Запрос уже рассмотрен');
  end if;

  select nickname into v_name from profiles where id = r.user_id;

  if not p_approve then
    update planet_requests set status = 'rejected', resolved_at = now() where id = p_id;
    perform log_event(r.user_id, r.faction, r.system_id, 'planet_request_rejected',
                      null, 1, 'private', jsonb_build_object('request_id', p_id));
    return jsonb_build_object('ok', true, 'message', 'Запрос отклонён');
  end if;

  select faction into v_req_faction from profiles where id = r.user_id;
  select faction into v_sys_faction from systems where id = r.system_id;
  if v_req_faction is distinct from r.faction or v_sys_faction is distinct from r.faction then
    update planet_requests set status = 'closed', resolved_at = now() where id = p_id;
    perform log_event(r.user_id, r.faction, r.system_id, 'planet_request_closed',
                      null, 1, 'private', jsonb_build_object('request_id', p_id));
    return jsonb_build_object('ok', false,
      'message', 'Планета или игрок больше не во фракции — запрос закрыт');
  end if;

  -- у планеты уже другой управляющий: выдать её — значит снять его, это полномочие «Управляющие»
  if exists (select 1 from system_control sc where sc.system_id = r.system_id
               and sc.controller_user_id is not null and sc.controller_user_id <> r.user_id)
     and not faction_power(v_me, r.faction, 'planet_controllers') then
    raise exception 'У планеты уже есть управляющий — сменить его может лидер или тот, у кого полномочие «Управляющие»';
  end if;

  insert into system_control (system_id, controller_user_id)
  values (r.system_id, r.user_id)
  on conflict (system_id) do update set controller_user_id = excluded.controller_user_id;

  update planet_requests set status = 'approved', resolved_at = now() where id = p_id;

  for o in select * from planet_requests
           where system_id = r.system_id and status = 'pending' and id <> p_id for update loop
    update planet_requests set status = 'closed', resolved_at = now() where id = o.id;
    perform log_event(o.user_id, o.faction, o.system_id, 'planet_request_closed',
                      null, 1, 'private', jsonb_build_object('request_id', o.id));
  end loop;

  return jsonb_build_object('ok', true,
    'message', (select name from systems where id = r.system_id) || ' выдана игроку ' || coalesce(v_name, ''));
end;
$$;


--
-- Name: resource_slots(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resource_slots(p_amount integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select ceil(p_amount::numeric
              / greatest(1, game_setting_int('cargo_units_per_slot', 2)))::integer;
$$;


--
-- Name: respond_supply_access(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_supply_access(p_grant_id uuid, p_accept boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); g record; v_fac text; v_name text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select * into g from supply_grants where id = p_grant_id for update;
  if not found or g.owner_user_id <> v_user then raise exception 'Запрос не найден'; end if;
  if g.status <> 'pending' then raise exception 'Запрос уже рассмотрен'; end if;
  select faction, nickname into v_fac, v_name from profiles where id = v_user;

  if coalesce(p_accept, false) then
    if (select faction from profiles where id = g.grantee_user_id) is distinct from v_fac then
      raise exception 'Игрок уже не на твоей стороне';
    end if;
    update supply_grants set status = 'active', decided_at = now() where id = g.id;
    perform log_event(g.grantee_user_id, v_fac, null, 'supply_access_granted', v_name, 1, 'private',
                      jsonb_build_object('grant_id', g.id, 'from_user', v_user));
  else
    update supply_grants set status = 'declined', decided_at = now() where id = g.id;
  end if;
end $$;


--
-- Name: respond_transfer(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_transfer(p_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  t record; it record; v_block text; v_owner uuid; v_sys text; v_name text;
  v_from_name text; v_to_name text; v_cap integer; v_bad text;
  v_before jsonb := '{}'::jsonb; v_after integer; sysrow record;
  v_ships uuid[]; v_units uuid[];
begin
  if v_me is null then raise exception 'Не авторизован'; end if;

  select * into t from troop_transfers where id = p_id for update;
  if not found or t.to_user <> v_me then raise exception 'Передача не найдена'; end if;
  if t.status <> 'pending' then raise exception 'Передача уже закрыта'; end if;

  select nickname into v_from_name from profiles where id = t.from_user;
  select nickname into v_to_name from profiles where id = t.to_user;

  if t.expires_at <= now() then
    update troop_transfers set status = 'expired', resolved_at = now() where id = p_id;
    return jsonb_build_object('ok', false, 'message', 'Срок предложения истёк');
  end if;

  if not p_accept then
    update troop_transfers set status = 'declined', resolved_at = now() where id = p_id;
    perform log_event(t.from_user, t.faction, null, 'transfer_declined',
                      v_to_name || ' · ' || coalesce(t.summary, ''), 1, 'private',
                      jsonb_build_object('transfer_id', p_id));
    return jsonb_build_object('ok', true, 'message', 'Передача отклонена');
  end if;

  if (select faction from profiles where id = t.from_user) is distinct from t.faction
     or (select faction from profiles where id = t.to_user) is distinct from t.faction then
    update troop_transfers set status = 'stale', resolved_at = now() where id = p_id;
    return jsonb_build_object('ok', false, 'message', 'Вы больше не в одной фракции');
  end if;

  -- Получатель соглашался ровно на этот состав. Если что-то погибло,
  -- улетело, село в транспорт или ушло в ремонт — передача срывается
  for it in select * from troop_transfer_items where transfer_id = p_id loop
    if it.kind = 'ship' then
      select owner_user_id, system_id into v_owner, v_sys from ships where id = it.item_id for update;
      v_block := case when found then transfer_block_ship(it.item_id) else 'погиб' end;
    else
      select owner_user_id, system_id into v_owner, v_sys from unit_positions where id = it.item_id for update;
      v_block := case when found then transfer_block_unit(it.item_id) else 'погиб' end;
    end if;

    if v_block is null and v_owner is distinct from t.from_user then v_block := 'уже не у отправителя'; end if;
    if v_block is null and v_sys is distinct from it.system_id then v_block := 'сменил планету'; end if;

    if v_block is not null then
      v_bad := coalesce(it.snapshot->>'name', 'юнит') || ' — ' || v_block;
      update troop_transfers set status = 'stale', resolved_at = now() where id = p_id;
      perform log_event(t.from_user, t.faction, null, 'transfer_stale',
                        v_bad, 1, 'private', jsonb_build_object('transfer_id', p_id));
      return jsonb_build_object('ok', false,
        'message', 'Состав изменился: ' || coalesce(it.snapshot->>'name', 'юнит') || ' — ' ||
                   split_part(v_block, ' — ', 1) ||
                   '. Передача отменена — пусть союзник соберёт её заново');
    end if;
  end loop;

  select array_agg(item_id) into v_ships from troop_transfer_items where transfer_id = p_id and kind = 'ship';
  select array_agg(item_id) into v_units from troop_transfer_items where transfer_id = p_id and kind = 'unit';
  v_ships := coalesce(v_ships, '{}'); v_units := coalesce(v_units, '{}');

  perform set_config('app.owner_transfer', '1', true);

  -- Корабли вместе с ангаром. Командир остаётся у прежнего хозяина,
  -- поэтому корабли выходят из-под него и встают гарнизоном
  update ships set owner_user_id = t.to_user, commander_id = null
  where id = any(v_ships) or carrier_ship_id = any(v_ships);

  -- Всё наземное внутри кораблей и техники
  update unit_positions set owner_user_id = t.to_user, commander_id = null
  where id = any(v_units)
     or id in (select i.id from unnest(v_units) u(id), transfer_unit_inside(u.id) i)
     or id in (select i.id from unnest(v_ships) s(id), transfer_ship_inside(s.id) i);

  perform set_config('app.owner_transfer', '', true);

  update troop_transfers set status = 'accepted', resolved_at = now() where id = p_id;

  perform log_event(t.from_user, t.faction, null, 'transfer_accepted',
                    v_to_name || ' · ' || coalesce(t.summary, ''), 1, 'private',
                    jsonb_build_object('transfer_id', p_id));
  perform log_event(t.to_user, t.faction, null, 'transfer_received',
                    v_from_name || ' · ' || coalesce(t.summary, ''), 1, 'private',
                    jsonb_build_object('transfer_id', p_id));

  return jsonb_build_object('ok', true, 'message', 'Войска получены');
end;
$$;


--
-- Name: reveal_unit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reveal_unit(p_unit_id uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update unit_positions
  set revealed_until = now() + make_interval(secs => game_setting_int('camo_reveal_seconds', 120))
  where id = p_unit_id;
$$;


--
-- Name: revoke_supply_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_supply_access(p_grant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); g record; v_fac text; v_name text; v_other uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select * into g from supply_grants where id = p_grant_id for update;
  if not found or (g.owner_user_id <> v_user and g.grantee_user_id <> v_user) then
    raise exception 'Доступ не найден';
  end if;
  if g.status not in ('pending', 'active') then return; end if;

  update supply_grants set status = 'revoked', decided_at = now() where id = g.id;

  if g.status = 'active' then
    select faction, nickname into v_fac, v_name from profiles where id = v_user;
    v_other := case when g.owner_user_id = v_user then g.grantee_user_id else g.owner_user_id end;
    perform log_event(v_other, v_fac, null, 'supply_access_revoked', v_name, 1, 'private',
                      jsonb_build_object('grant_id', g.id, 'from_user', v_user));
  end if;
end $$;


--
-- Name: riot_finish(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.riot_finish(p_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; sy record; v_ctl uuid; v_alive integer; v_val integer; v_lvl integer; v_txt text; v_meta jsonb;
begin
  if p_status not in ('suppressed', 'negotiated', 'failed', 'captured') then raise exception 'riot_finish: %', p_status; end if;
  select * into r from settlement_riots where id = p_id and status = 'active' for update;
  if not found then return; end if;
  select id, name, faction into sy from systems where id = r.system_id;
  select controller_user_id into v_ctl from system_control where system_id = r.system_id;
  select count(*) into v_alive from unit_positions x where x.id = any(r.rebels) and x.hp > 0;

  -- эффекты мятежа гаснут, уцелевшие повстанцы уходят (npc_tick и бой на сервере уводят state = 'leave')
  update faction_effects set ends_at = now() where system_id = r.system_id and source = 'riot' and ends_at > now();
  update npc_brains set state = 'leave' where unit_id = any(r.rebels) and state is distinct from 'leave';

  if p_status = 'suppressed' then
    v_val := 50; v_txt := sy.name || ': мятеж подавлен';
    insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at)
    values (r.faction, 'mood', -10, 'После мятежа', 'riot_end', r.system_id, now(), now() + interval '24 hours');
  elsif p_status = 'negotiated' then
    v_val := 60; v_txt := sy.name || ': с повстанцами договорились';
  elsif p_status = 'failed' then
    v_val := 40; v_txt := sy.name || ': мятеж не подавлен';
    select level into v_lvl from settlement_state where system_id = r.system_id;
    -- как при захвате (reset_settlement_on_capture): ступень вниз, развитие с нуля, расширение отменено
    update settlement_state set level = greatest(1, coalesce(level, 1) - 1), dev_points = 0, upgrade_until = null, upgrade_to = null
     where system_id = r.system_id;
    if v_ctl is not null then update system_control set controller_user_id = null where system_id = r.system_id; end if;
    insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at) values
      (r.faction, 'extract', -50, 'Разорение после мятежа', 'riot_end', r.system_id, now(), now() + interval '24 hours'),
      (r.faction, 'income',  -50, 'Разорение после мятежа', 'riot_end', r.system_id, now(), now() + interval '24 hours');
  end if;

  update settlement_riots set status = p_status, ended_at = now(),
         result = jsonb_build_object('alive', v_alive, 'controller', v_ctl, 'level_from', v_lvl)
   where id = p_id;

  if sy.faction is distinct from r.faction then return; end if;          -- захвачена: шкалу ставит unrest_on_capture
  if v_val is not null then
    update settlement_unrest set value = v_val, high_days = 0, updated_at = now() where system_id = r.system_id;
    perform unrest_penalty(r.system_id, v_val);
  end if;
  if v_txt is null then return; end if;

  v_meta := jsonb_build_object('planet', sy.name, 'status', p_status, 'total', r.total, 'alive', v_alive,
                               'level', case when v_lvl > 1 then v_lvl - 1 end, 'value', v_val);
  perform log_event(null, r.faction, r.system_id, case when p_status = 'failed' then 'unrest_riot_lost' else 'unrest_riot_end' end,
                    v_txt, r.total, 'faction', v_meta);
  if v_ctl is not null then
    perform log_event(v_ctl, r.faction, r.system_id, case when p_status = 'failed' then 'unrest_riot_lost' else 'unrest_riot_end' end,
                      v_txt, r.total, 'private', v_meta);
  end if;
end;
$$;


--
-- Name: riot_start(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.riot_start(p_system text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sy record; v_ctl uuid; v_lvl integer; v_ids uuid[]; v_n integer; v_id uuid; v_end timestamptz; v_meta jsonb; ld record;
  v_caps text[] := string_to_array(coalesce((select value from game_settings where key = 'unrest_capitals'), ''), ',');
begin
  select id, name, faction into sy from systems where id = p_system;
  if sy.faction is null or sy.faction not in ('republic', 'cis') or p_system = any(v_caps) then return null; end if;
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  if v_ctl is null or is_capture_active(p_system) then return null; end if;
  if exists (select 1 from settlement_riots where faction = sy.faction and status = 'active') then return null; end if;

  begin
    select greatest(1, coalesce(level, 1)) into v_lvl from settlement_state where system_id = p_system;
    v_lvl := coalesce(v_lvl, 1);
    v_ids := spawn_marauder_gang(p_system, least(10, 2 + 2 * v_lvl));
    v_n := coalesce(array_length(v_ids, 1), 0);
    if v_n = 0 then return null; end if;                       -- банде негде встать — попробуем на следующих сутках
    v_end := now() + make_interval(hours => game_setting_int('unrest_riot_hours', 48));
    insert into settlement_riots (system_id, faction, rebels, total, level, ends_at)
    values (p_system, sy.faction, v_ids, v_n, v_lvl, v_end) returning id into v_id;
  exception when unique_violation then
    return null;                                               -- другая планета фракции успела раньше: банда откатилась вместе с записью
  end;

  update faction_effects set ends_at = now() where system_id = p_system and source = 'unrest' and ends_at > now();
  insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at) values
    (sy.faction, 'extract',    -50, 'Мятеж', 'riot', p_system, now(), v_end),
    (sy.faction, 'income',     -50, 'Мятеж', 'riot', p_system, now(), v_end),
    (sy.faction, 'build_time',  50, 'Мятеж', 'riot', p_system, now(), v_end),
    (sy.faction, 'hire_time',   50, 'Мятеж', 'riot', p_system, now(), v_end);

  select u.x, u.y into ld from unit_positions u where u.id = v_ids[1];
  v_meta := jsonb_build_object('planet', sy.name, 'rebels', v_n, 'ends', v_end, 'riot', v_id, 'x', ld.x, 'y', ld.y);
  perform log_event(null, sy.faction, p_system, 'unrest_riot', sy.name || ': мятеж · повстанцев ' || v_n, v_n, 'faction', v_meta);
  perform log_event(v_ctl, sy.faction, p_system, 'unrest_riot', sy.name || ': мятеж · повстанцев ' || v_n, v_n, 'private', v_meta);
  return v_id;
end;
$$;


--
-- Name: riot_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.riot_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_fac text;
begin
  if not pg_try_advisory_xact_lock(hashtext('riot_tick')) then return; end if;
  for r in select * from settlement_riots where status = 'active' order by started_at loop
    begin
      select faction into v_fac from systems where id = r.system_id;
      if v_fac is distinct from r.faction then
        perform riot_finish(r.id, 'captured');
      elsif not exists (select 1 from unit_positions x where x.id = any(r.rebels) and x.hp > 0) then
        perform riot_finish(r.id, 'suppressed');
      elsif r.ends_at <= now() then
        perform riot_finish(r.id, 'failed');
      end if;
    exception when others then perform err_db('riot_tick', sqlstate, sqlerrm, true);
      raise warning 'riot_tick %: %', r.id, sqlerrm;
    end;
  end loop;
end;
$$;


--
-- Name: rt_battle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_battle_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  k text := case when tg_table_name = 'ships' then 'ship' else 'unit' end;
  bid uuid;
  fire_at timestamptz;
begin
  if coalesce(current_setting('app.rt_battle', true), '') = '1'
     or coalesce(current_setting('app.capture_transfer', true), '') = '1' then
    return case when tg_op = 'UPDATE' then new else old end;
  end if;
  select l.battle_id into bid from rt_battle_locks l where l.obj_kind = k and l.obj_id = old.id;
  if bid is null then
    return case when tg_op = 'UPDATE' then new else old end;
  end if;
  if rt_obj_busy_2_0(k, old.id) is null then
    return case when tg_op = 'UPDATE' then new else old end;
  end if;
  if k = 'ship' and tg_op = 'UPDATE' then
    if new.in_transit and not old.in_transit then
      select (b.snapshot->'fire'->>old.id::text)::timestamptz into fire_at from rt_battles b where b.id = bid;
      if fire_at is not null and fire_at > now() - interval '30 seconds' then
        raise exception 'Корабль под огнём — в гиперпространство не уйти' using errcode = 'P0001', hint = 'rt_busy';
      end if;
      select (b.snapshot->'held'->>old.id::text)::timestamptz into fire_at from rt_battles b where b.id = bid;
      if fire_at is not null and fire_at > now() then
        raise exception 'Корабль «%» в притягивающем луче — в гиперпространство не уйти',
          coalesce(old.name, (select t.name from ship_types t where t.id = old.ship_type), '') using errcode = 'P0001', hint = 'rt_busy';
      end if;
      return new;
    end if;
    if new.hp = old.hp and new.x is not distinct from old.x and new.y is not distinct from old.y and new.facing is not distinct from old.facing
       and new.system_id is not distinct from old.system_id and new.in_transit = old.in_transit
       and new.shield_fore is not distinct from old.shield_fore and new.shield_aft is not distinct from old.shield_aft
       and new.shield_port is not distinct from old.shield_port and new.shield_starboard is not distinct from old.shield_starboard
       and new.trophy is not distinct from old.trophy and new.owner_user_id is not distinct from old.owner_user_id
       and new.faction is not distinct from old.faction and new.carrier_ship_id is not distinct from old.carrier_ship_id
       and new.ap is not distinct from old.ap then
      return new;
    end if;
    if auth.uid() is null and new.hp >= old.hp and new.x is not distinct from old.x and new.y is not distinct from old.y
       and new.system_id is not distinct from old.system_id and new.in_transit = old.in_transit
       and new.owner_user_id is not distinct from old.owner_user_id and new.faction is not distinct from old.faction then
      return new;
    end if;
  end if;
  if k = 'unit' and tg_op = 'UPDATE' then
    -- погрузка на корабль или в технику из панелей игры (армия, трюм): можно, если боец не под огнём
    if (new.carrier_ship_id is not null and old.carrier_ship_id is null) or (new.carrier_unit_id is not null and old.carrier_unit_id is null) then
      select (b.snapshot->'fire'->>old.id::text)::timestamptz into fire_at from rt_battles b where b.id = bid;
      if fire_at is not null and fire_at > now() - interval '30 seconds' then
        raise exception 'Боец под огнём — погрузка невозможна' using errcode = 'P0001', hint = 'rt_busy';
      end if;
      return new;
    end if;
    -- имя героя и прочее небоевое
    if new.hp = old.hp and new.x is not distinct from old.x and new.y is not distinct from old.y and new.system_id is not distinct from old.system_id
       and new.owner_user_id is not distinct from old.owner_user_id and new.faction is not distinct from old.faction
       and new.carrier_ship_id is not distinct from old.carrier_ship_id and new.carrier_unit_id is not distinct from old.carrier_unit_id
       and new.ap is not distinct from old.ap and new.layer is not distinct from old.layer then
      return new;
    end if;
  end if;
  if auth.uid() is not null then
    raise exception '%', case when k = 'ship' then 'Корабль сейчас в бою 2.0' else 'Отряд сейчас в бою 2.0' end
      using errcode = 'P0001', hint = 'rt_busy';
  end if;
  return null;
end;
$$;


--
-- Name: rt_battle_guard_ref(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_battle_guard_ref() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  j jsonb;
  busy boolean := false;
  fire_at timestamptz;
begin
  if coalesce(current_setting('app.rt_battle', true), '') = '1' then return new; end if;
  if not exists (select 1 from rt_battles where status = 'active') then return new; end if;
  j := to_jsonb(new);
  -- верфь на живой орбите: можно, если корабль не под огнём (снимок боя: когда по нему били)
  if tg_table_name = 'repair_orders' and (j->>'ship_id') is not null then
    if rt_obj_busy_2_0('ship', (j->>'ship_id')::uuid) is null then return new; end if;
    select (b.snapshot->'fire'->>(j->>'ship_id'))::timestamptz into fire_at
      from rt_battle_locks l join rt_battles b on b.id = l.battle_id
     where l.obj_kind = 'ship' and l.obj_id = (j->>'ship_id')::uuid and b.status = 'active'
     limit 1;
    if fire_at is null or fire_at <= now() - interval '30 seconds' then return new; end if;
    if auth.uid() is not null then
      raise exception 'Корабль под огнём — верфь примет его, когда бой вокруг стихнет' using errcode = 'P0001', hint = 'rt_busy';
    end if;
    return null;
  end if;
  if tg_table_name = 'troop_transfer_items' then
    busy := (j->>'kind') in ('unit','ship') and (j->>'item_id') is not null
            and rt_obj_busy_2_0(j->>'kind', (j->>'item_id')::uuid) is not null;
  else
    busy := ((j->>'unit_id') is not null and rt_obj_busy_2_0('unit', (j->>'unit_id')::uuid) is not null)
         or ((j->>'ship_id') is not null and rt_obj_busy_2_0('ship', (j->>'ship_id')::uuid) is not null);
  end if;
  if not busy then return new; end if;
  if auth.uid() is not null then
    raise exception 'Отряд или корабль сейчас в бою 2.0' using errcode = 'P0001', hint = 'rt_busy';
  end if;
  return null;
end;
$$;


--
-- Name: rt_bench_submit(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_bench_submit(p_scenario text, p_device jsonb, p_results jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare rid bigint;
begin
  if auth.uid() is null then raise exception 'Нет входа в игру'; end if;
  if (select count(*) from rt_bench where user_id = auth.uid() and at > now() - interval '1 hour') >= 30 then
    raise exception 'Слишком много замеров, попробуй позже';
  end if;
  if length(coalesce(p_device::text, '')) > 4000 or length(coalesce(p_results::text, '')) > 20000 then
    raise exception 'Слишком большой замер';
  end if;
  insert into rt_bench (user_id, scenario, device, results)
  values (auth.uid(), left(coalesce(p_scenario, ''), 40), p_device, p_results)
  returning id into rid;
  return rid;
end;
$$;


--
-- Name: rt_event_abort(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_event_abort(p_key text, p_match uuid, p_why text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  update event_matches set status = 'aborted', ended_at = now(), result = jsonb_build_object('why', left(coalesce(p_why, ''), 200))
   where id = p_match and status in ('forming', 'live');
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: rt_event_beat(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_event_beat(p_key text, p_match uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  update event_matches set beat_at = now() where id = p_match and status = 'live';
end;
$$;


--
-- Name: rt_event_finish(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_event_finish(p_key text, p_match uuid, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  m event_matches; e record; tr record; p jsonb; v_user uuid; v_won boolean; v_share numeric; v_t integer; v_present jsonb; v_void boolean;
  v_cr integer; v_res jsonb; v_planet text; v_fit integer; v_left integer; k text; v_amt integer; v_pts integer; v_title text; out_ jsonb := '[]'::jsonb;
  v_day date; v_paid jsonb; v_capped boolean;
begin
  perform rt_need_key(p_key);
  select * into m from event_matches where id = p_match for update;
  if not found then raise exception 'нет такого матча'; end if;
  if m.status = 'done' then return jsonb_build_object('ok', true, 'again', true); end if;
  if m.status <> 'live' then raise exception 'матч не идёт: %', m.status; end if;
  select * into e from event_catalog where id = m.event_id;
  select * into tr from event_tiers where n = m.tier;
  v_t := coalesce((p_result->>'t')::integer, 0);
  v_present := p_result->'present';
  v_void := coalesce((p_result->>'forfeit')::boolean, false) and v_t < 180;
  update event_matches set status = 'done', ended_at = now(), result = p_result, winner = p_result->>'winner' where id = p_match;
  if m.test then return jsonb_build_object('ok', true, 'test', true); end if;
  v_day := coalesce(m.day, (now() at time zone event_tz())::date);
  for p in select * from jsonb_array_elements(m.players) loop
    continue when coalesce((p->>'bot')::boolean, false) or (p->>'user') !~ '^[0-9a-f-]{36}$';
    continue when jsonb_typeof(v_present) = 'array' and not (v_present ? (p->>'user'));
    continue when v_void;
    v_user := (p->>'user')::uuid;
    v_won := (p->>'role') = (p_result->>'winner');
    v_paid := event_paid_today(v_user, v_day);
    v_capped := (v_won and (v_paid->>'win')::boolean) or (not v_won and ((v_paid->>'any')::boolean or m.bots));
    v_share := case when v_capped then 0 when v_won then 1 when v_t >= 180 then 0.25 else 0 end * coalesce(m.reward_k, 1);
    v_cr := (round(e.reward_cr * tr.k * v_share / 5) * 5)::integer; v_res := '{}'::jsonb;
    select sc.system_id into v_planet from system_control sc where sc.controller_user_id = v_user order by sc.system_id limit 1;
    for k, v_amt in select key, (round(value::numeric * tr.k * v_share / 5) * 5)::integer from jsonb_each_text(e.reward_res) loop
      continue when v_amt <= 0;
      v_fit := case when v_planet is not null then add_planet_stock(v_planet, k, v_amt) else 0 end;
      v_left := v_amt - v_fit;
      if v_fit > 0 then v_res := v_res || jsonb_build_object(k, v_fit); end if;
      if v_left > 0 then v_cr := v_cr + v_left * coalesce((select base_price from resources where id = k), 10); end if;
    end loop;
    if v_cr > 0 then update profiles set credits = credits + v_cr where id = v_user; end if;
    v_pts := case when v_won then case when m.bots then ceil(tr.pts / 2.0)::integer else tr.pts end when v_t >= 180 and not m.bots then 3 else 0 end;
    insert into event_awards (match_id, user_id, role, won, credits, resources, planet, points, paid)
    values (p_match, v_user, p->>'role', v_won, v_cr, v_res, case when v_res <> '{}'::jsonb then v_planet end, v_pts, v_cr > 0 or v_res <> '{}'::jsonb)
    on conflict (match_id, user_id) do nothing;
    insert into event_profile (user_id, points, wins, games) values (v_user, v_pts, case when v_won then 1 else 0 end, 1)
    on conflict (user_id) do update set points = event_profile.points + excluded.points, wins = event_profile.wins + excluded.wins, games = event_profile.games + 1;
    v_title := null;
    if v_won then
      insert into event_trophies (user_id, event_id, tier, match_id) values (v_user, m.event_id, m.tier, p_match) on conflict do nothing;
      if m.tier = 3 then
        v_title := e.titles->>(p->>'role');
        if v_title is not null then insert into event_titles (user_id, title, event_id) values (v_user, v_title, m.event_id) on conflict do nothing; end if;
      end if;
    end if;
    out_ := out_ || jsonb_build_array(jsonb_build_object('user', v_user, 'won', v_won, 'credits', v_cr, 'res', v_res, 'points', v_pts, 'title', v_title, 'capped', v_capped));
  end loop;
  return jsonb_build_object('ok', true, 'awards', out_);
end;
$_$;


--
-- Name: rt_event_open(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_event_open(p_key text, p_match uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare m event_matches; e record;
begin
  perform rt_need_key(p_key);
  update rt_servers set seen_at = now() where id = 'main';
  select * into m from event_matches where id = p_match for update;
  if not found then raise exception 'нет такого матча'; end if;
  if m.status not in ('forming', 'live') then raise exception 'матч уже %', m.status; end if;
  -- идущий матч без сердцебиения больше полутора минут не открывается заново (бой не восстановить)
  if m.status = 'live' and coalesce(m.beat_at, m.started_at) < now() - interval '90 seconds' then raise exception 'матч уже идёт'; end if;
  if m.status = 'forming' then update event_matches set status = 'live', started_at = now(), beat_at = now() where id = p_match;
  else update event_matches set beat_at = now() where id = p_match; end if;
  select * into e from event_catalog where id = m.event_id;
  return jsonb_build_object('id', m.id, 'event', m.event_id, 'tier', m.tier, 'map', m.map, 'players', m.players, 'test', m.test, 'seed', m.seed,
                            'created_by', m.created_by, 'minutes', e.minutes);
end;
$$;


--
-- Name: rt_ground_act(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_act(p_key text, p_user uuid, p_fn text, p_args jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  res jsonb;
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', p_user, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', p_user::text, true);
  if p_fn = 'load_unit_from_ground' then
    res := to_jsonb(load_unit_from_ground((p_args->>'unit')::uuid, (p_args->>'ship')::uuid));
  elsif p_fn = 'load_vehicle_to_ship' then
    res := to_jsonb(load_vehicle_to_ship((p_args->>'unit')::uuid, (p_args->>'ship')::uuid));
  elsif p_fn = 'build_structure' then
    res := to_jsonb(build_structure((p_args->>'unit')::uuid, p_args->>'type', (p_args->>'x')::integer, (p_args->>'y')::integer));
  elsif p_fn = 'start_scout_move' then
    res := to_jsonb(start_scout_move((p_args->>'unit')::uuid, p_args->>'system'));
  else
    raise exception 'rt: действие не разрешено: %', p_fn;
  end if;
  return jsonb_build_object('ok', true, 'result', res);
end;
$$;


--
-- Name: rt_ground_battle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_battle(p_system text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select b.id from rt_battles b
  where b.kind = 'ground' and b.system_id = p_system and b.status = 'active'
    and b.heartbeat_at > now() - interval '90 seconds'
  order by b.created_at desc limit 1;
$$;


--
-- Name: rt_ground_close(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_close(p_key text, p_battle uuid, p_result jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  update rt_battles set status = 'finished', ended_at = now(), result = p_result where id = p_battle and status = 'active';
  return found;
end;
$$;


--
-- Name: rt_ground_map(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_map(p_key text, p_system text, p_masks jsonb, p_version text DEFAULT 'town'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  insert into planet_maps (system_id, w, h, foot1, track1, track2, hover1, hover2, version)
  values (p_system, coalesce((p_masks->>'w')::integer, 144), coalesce((p_masks->>'h')::integer, 144),
          p_masks->>'foot1', p_masks->>'track1', p_masks->>'track2', p_masks->>'hover1', p_masks->>'hover2', p_version)
  on conflict (system_id) do update
    set foot1 = excluded.foot1, track1 = excluded.track1, track2 = excluded.track2, hover1 = excluded.hover1, hover2 = excluded.hover2,
        version = excluded.version, updated_at = now();
  return true;
end;
$$;


--
-- Name: rt_ground_map_base(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_map_base(p_key text, p_system text, p_masks jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  perform rt_need_key(p_key);
  insert into planet_maps (system_id, w, h, foot1, track1, track2, hover1, hover2, version)
  values (p_system, coalesce((p_masks->>'w')::integer, 144), coalesce((p_masks->>'h')::integer, 144),
          p_masks->>'foot1', p_masks->>'track1', p_masks->>'track2', p_masks->>'hover1', p_masks->>'hover2', 'base')
  on conflict (system_id) do nothing;
  get diagnostics n = row_count;
  return n > 0;
end;
$$;


--
-- Name: rt_ground_map_missing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_map_missing(p_key text) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  return coalesce((select array_agg(s.id order by s.id) from systems s
                    where not coalesce(s.is_deep_space, false)
                      and not exists (select 1 from planet_maps pm where pm.system_id = s.id)), '{}');
end;
$$;


--
-- Name: rt_ground_open(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_open(p_key text, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  bid uuid;
  st jsonb;
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);
  bid := rt_ground_battle(p_system);
  if bid is null then
    update rt_battles set status = 'aborted', ended_at = now()
     where kind = 'ground' and system_id = p_system and status = 'active';
    insert into rt_battles (kind, system_id, meta) values ('ground', p_system, jsonb_build_object('opened', now()))
    returning id into bid;
  end if;
  insert into rt_battle_locks (obj_kind, obj_id, battle_id)
  select 'unit', u.id, bid from unit_positions u
  where u.system_id = p_system and u.layer = 'ground' and u.x is not null and u.hp > 0 and u.transit_to is null
  on conflict (obj_kind, obj_id) do update set battle_id = excluded.battle_id, locked_at = now();
  update auto_moves m set status = 'stopped', stop_reason = 'rt_ground', updated_at = now()
   where m.system_id = p_system and m.layer = 'ground' and m.status = 'active';
  st := rt_ground_state(p_system);
  return st || jsonb_build_object('battle_id', bid, 'units', rt_ground_units(p_system));
end;
$$;


--
-- Name: rt_ground_pull(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_pull(p_key text, p_battle uuid, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);
  update rt_servers set seen_at = now() where id = 'main';
  update rt_battles set heartbeat_at = now() where id = p_battle and status = 'active';
  if not found then return jsonb_build_object('closed', true); end if;
  insert into rt_battle_locks (obj_kind, obj_id, battle_id)
  select 'unit', u.id, p_battle from unit_positions u
  where u.system_id = p_system and u.layer = 'ground' and u.x is not null and u.hp > 0 and u.transit_to is null
    and not exists (select 1 from rt_battle_locks l where l.obj_kind = 'unit' and l.obj_id = u.id and l.battle_id = p_battle)
  on conflict (obj_kind, obj_id) do update set battle_id = excluded.battle_id, locked_at = now();
  return rt_ground_state(p_system) || jsonb_build_object('units', rt_ground_units(p_system));
end;
$$;


--
-- Name: rt_ground_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_state(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'system', (select jsonb_build_object('id', s.id, 'name', s.name, 'faction', s.faction,
                                        'controller', (select c.controller_user_id from system_control c where c.system_id = s.id))
               from systems s where s.id = p_system),
    'settle', (select jsonb_build_object('level', st.level, 'name', l.name,
                 'districts', (select coalesce(jsonb_agg(jsonb_build_object('slot', d.slot, 'id', d.district_id, 'building', d.completes_at is not null and d.completes_at > now()) order by d.slot), '[]'::jsonb)
                               from settlement_districts d where d.system_id = st.system_id),
                 'satisfaction', settlement_effective(p_system), 'militia_ready_at', st.militia_ready_at)
               from settlement_state st join settlement_levels l on l.level = st.level where st.system_id = p_system),
    'structs', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'type', f.type_id, 'kind', st.kind, 'x', f.x, 'y', f.y, 'w', f.w, 'h', f.h, 'hp', f.hp, 'hpMax', st.max_hp,
                                                             'faction', f.faction, 'owner', f.owner_user_id, 'building', f.completes_at is not null and f.completes_at > now())), '[]'::jsonb)
                from field_structures f join structure_types st on st.id = f.type_id where f.system_id = p_system),
    'buildings', (select coalesce(jsonb_agg(jsonb_build_object('slot', b.slot_index, 'x', ps.x, 'y', ps.y, 'type', b.building_type_id, 'code', bt.code, 'name', bt.name, 'image', bt.image, 'faction', b.faction, 'owner', b.owner_user_id,
                                                               'ready', b.completes_at is null or b.completes_at <= now())), '[]'::jsonb)
                  from buildings b join planet_slots ps on ps.system_id = b.system_id and ps.slot_index = b.slot_index
                  left join building_types bt on bt.id = b.building_type_id
                  where b.system_id = p_system),
    'plots', (select coalesce(jsonb_agg(jsonb_build_object('slot', ps.slot_index, 'x', ps.x, 'y', ps.y) order by ps.slot_index), '[]'::jsonb) from planet_slots ps where ps.system_id = p_system),
    'zones', (select coalesce(jsonb_agg(jsonb_build_object('x', z.x, 'y', z.y, 'size', z.size)), '[]'::jsonb) from deploy_zones z where z.system_id = p_system),
    'capture', (select jsonb_build_object('faction', c.faction, 'progress', capture_progress(p_system), 'rate', c.rate, 'status', c.status,
                                          'goal', case when c.status = 'distribution' then capture_goal(p_system) else coalesce(c.goal, capture_goal(p_system)) end)
                from system_capture c where c.system_id = p_system),
    'capture_goal', coalesce((select sc.goal from system_capture sc where sc.system_id = p_system and sc.status <> 'distribution'), capture_goal(p_system)),
    'loyalty', loyalty_battle(p_system),
    'zone_box', (select jsonb_build_object('x', b.x, 'y', b.y, 'size', b.size) from settlement_zone_box() b)
  );
$$;


--
-- Name: rt_ground_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_status(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('server', rt_server_status());
$$;


--
-- Name: rt_ground_sync(text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_sync(p_key text, p_battle uuid, p_units jsonb DEFAULT '[]'::jsonb, p_structs jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n_u integer := 0; n_s integer := 0; n_d integer := 0; n_k integer := 0; n_b integer := 0; v_wait uuid[] := '{}';
  r record;
  rl record;
  fire jsonb;
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);

  -- погибшие: как в attack_unit — убийство герою, строка с карты долой. Первыми: клетка павшего
  -- свободна для живых в этом же пакете
  for r in
    select (x->>'id')::uuid as id, nullif(x->>'by', '')::uuid as killer
    from jsonb_array_elements(coalesce(p_units, '[]'::jsonb)) x
    where coalesce((x->>'hp')::integer, 0) <= 0
  loop
    if not exists (select 1 from rt_battle_locks l where l.obj_kind = 'unit' and l.obj_id = r.id and l.battle_id = p_battle) then
      continue;
    end if;
    -- уже не на земле (в пути, на борту): запоздавшая гибель не стирает бойца
    if not exists (select 1 from unit_positions t where t.id = r.id and t.x is not null and t.transit_to is null and t.carrier_ship_id is null) then
      continue;
    end if;
    if r.killer is not null then
      perform record_hero_kill(r.killer, t.unit_type, t.faction, t.owner_user_id, t.system_id)
        from unit_positions t where t.id = r.id;
    end if;
    delete from unit_positions where id = r.id;
    delete from rt_battle_locks where obj_kind = 'unit' and obj_id = r.id;
    n_d := n_d + 1;
  end loop;

  -- живые: клетка и прочность (только бойцы этого боя). По одному бойцу: в базе на клетку один
  -- боец (idx_unit_positions_cell), а в живом бою двое стоят в одной клетке или меняются местами —
  -- общий запрос падал целиком, и ни позиции, ни здоровье, ни погибшие не записывались.
  -- Клетка занята — второй заход после остальных (цепочки и обмены местами); всё ещё занята —
  -- боец остаётся в прежней клетке до следующей сверки, здоровье пишется всегда.
  for rl in
    select (x->>'id')::uuid as id, (x->>'x')::integer as x, (x->>'y')::integer as y, (x->>'hp')::integer as hp
    from jsonb_array_elements(coalesce(p_units, '[]'::jsonb)) x
    join rt_battle_locks l on l.obj_kind = 'unit' and l.obj_id = (x->>'id')::uuid and l.battle_id = p_battle
    where coalesce((x->>'hp')::integer, 0) > 0
  loop
    begin
      update unit_positions u set x = rl.x, y = rl.y, hp = rl.hp, updated_at = now()
       where u.id = rl.id and u.layer = 'ground' and u.x is not null;
      get diagnostics n_k = row_count; n_u := n_u + n_k;
    exception when unique_violation then
      v_wait := v_wait || rl.id;
    end;
  end loop;
  if array_length(v_wait, 1) > 0 then
    for rl in
      select (x->>'id')::uuid as id, (x->>'x')::integer as x, (x->>'y')::integer as y, (x->>'hp')::integer as hp
      from jsonb_array_elements(coalesce(p_units, '[]'::jsonb)) x
      where (x->>'id')::uuid = any(v_wait)
    loop
      begin
        update unit_positions u set x = rl.x, y = rl.y, hp = rl.hp, updated_at = now()
         where u.id = rl.id and u.layer = 'ground' and u.x is not null;
        get diagnostics n_k = row_count; n_u := n_u + n_k;
      exception when unique_violation then
        update unit_positions u set hp = rl.hp, updated_at = now()
         where u.id = rl.id and u.layer = 'ground' and u.x is not null;
        get diagnostics n_k = row_count; n_u := n_u + n_k; n_b := n_b + n_k;
      end;
    end loop;
  end if;

  with rows as (
    select (x->>'id')::uuid as id, greatest(0, (x->>'hp')::integer) as hp
    from jsonb_array_elements(coalesce(p_structs, '[]'::jsonb)) x)
  update field_structures f set hp = rows.hp from rows where f.id = rows.id;
  get diagnostics n_s = row_count;

  -- кто под огнём (rt_battle_guard: погрузка на корабль и его уход закрыты 30 с после попадания)
  select coalesce(jsonb_object_agg(x->>'id', to_jsonb(now())), '{}'::jsonb) into fire
    from jsonb_array_elements(coalesce(p_units, '[]'::jsonb)) x where coalesce((x->>'fire')::boolean, false);
  update rt_battles b
     set heartbeat_at = now(),
         snapshot = jsonb_build_object('fire', coalesce((
           select jsonb_object_agg(k, v) from jsonb_each(coalesce(b.snapshot->'fire', '{}'::jsonb)) e(k, v)
            where (v #>> '{}')::timestamptz > now() - interval '60 seconds' and not (fire ? k)), '{}'::jsonb) || fire),
         snapshot_at = now()
   where b.id = p_battle and b.status = 'active';
  return jsonb_build_object('units', n_u, 'dead', n_d, 'structs', n_s, 'busy', n_b);
end;
$$;


--
-- Name: rt_ground_units(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_ground_units(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', u.id, 'type', u.unit_type, 'x', u.x, 'y', u.y, 'hp', u.hp, 'owner', u.owner_user_id, 'faction', u.faction,
    'hero', u.hero_id, 'name', u.hero_name, 'portrait', u.portrait,
    'bonus', jsonb_build_object('hp', coalesce(u.bonus_hp, 0), 'damage', coalesce(u.bonus_damage, 0), 'vision', coalesce(u.bonus_vision, 0),
                                'move', coalesce(u.bonus_move, 0), 'range', coalesce(u.bonus_range, 0), 'accuracy', coalesce(u.bonus_accuracy, 0), 'evasion', coalesce(u.bonus_evasion, 0)),
    'npc', (select b.kind from npc_brains b where b.unit_id = u.id),
    'brain', (select jsonb_build_object('hx', b.home_x, 'hy', b.home_y, 'st', b.state)
                from npc_brains b where b.unit_id = u.id and b.kind = 'marauder'),
    'abil', (select coalesce(jsonb_agg(h.ability_id), '[]'::jsonb) from hero_learned h where h.hero_id = u.hero_id),
    'skills', (select coalesce(jsonb_agg(jsonb_build_array(substr(r.effect_kind, 9), r.effect_value, coalesce(r.ability_damage, 0)) order by r.sort_order), '[]'::jsonb)
                 from researches r where r.id = any(coalesce(u.upgrades, '{}')) and r.effect_kind like 'ability\_%'),
    'training', u.training_until is not null and u.training_until > now(),
    'carrier', u.carrier_unit_id,
    'updated', u.updated_at
  ) order by u.id), '[]'::jsonb)
  from unit_positions u
  where u.system_id = p_system and u.layer = 'ground' and u.x is not null and u.hp > 0
    and u.transit_to is null;
$$;


--
-- Name: rt_key_ok(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_key_ok(p_key text, p_server text DEFAULT 'main'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(p_key, '') <> '' and exists (
    select 1 from rt_servers s
    where s.id = coalesce(p_server, 'main')
      and s.key_hash = encode(sha256(convert_to(p_key, 'UTF8')), 'hex'));
$$;


--
-- Name: rt_log(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_log(p_key text, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  perform rt_need_key(p_key);
  update rt_servers set seen_at = now() where id = 'main';
  insert into rt_server_log (at, level, msg, data)
  select coalesce((r->>'at')::timestamptz, now()),
         left(coalesce(r->>'level', 'info'), 16),
         left(coalesce(r->>'msg', ''), 500),
         r->'data'
  from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
  limit 500;
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: rt_need_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_need_key(p_key text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not rt_key_ok(p_key) then
    raise exception 'rt: неверный ключ сервера' using errcode = '28000';
  end if;
end;
$$;


--
-- Name: rt_obj_busy_2_0(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_obj_busy_2_0(p_kind text, p_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.battle_id
  from rt_battle_locks l join rt_battles b on b.id = l.battle_id
  where l.obj_kind = p_kind and l.obj_id = p_id
    and b.status = 'active' and b.heartbeat_at > now() - interval '90 seconds'
    -- корабль ушёл из системы боя (гиперпространство, другая система) — замок уже не его
    and (p_kind <> 'ship' or not exists (
          select 1 from ships s
           where s.id = p_id
             and (coalesce(s.in_transit, false)
                  or (s.carrier_ship_id is null and s.system_id is distinct from b.system_id))))
    -- боец в пути (разведчик) или уже не на планете боя — замок тоже не его
    and (p_kind <> 'unit' or not exists (
          select 1 from unit_positions u
           where u.id = p_id
             and (u.transit_to is not null or u.system_id is distinct from b.system_id)))
  limit 1;
$$;


--
-- Name: rt_server_hello(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_server_hello(p_key text, p_url text, p_version text, p_info jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  update rt_servers set url = p_url, version = p_version, info = p_info,
         started_at = now(), seen_at = now()
   where id = 'main';
  return coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'kind', b.kind, 'system_id', b.system_id,
                                                       'snapshot', b.snapshot, 'meta', b.meta))
                   from rt_battles b where b.status = 'active'), '[]'::jsonb);
end;
$$;


--
-- Name: rt_server_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_server_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select jsonb_build_object('url', url, 'version', version, 'seen_at', seen_at,
                                             'online', seen_at > now() - interval '60 seconds')
                   from rt_servers where id = 'main'), jsonb_build_object('online', false));
$$;


--
-- Name: rt_space_battle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_battle(p_system text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select b.id from rt_battles b
   where b.kind = 'space' and b.system_id = p_system and b.status = 'active'
     and b.heartbeat_at > now() - interval '90 seconds'
   order by b.created_at desc limit 1;
$$;


--
-- Name: rt_space_close(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_close(p_key text, p_battle uuid, p_result jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform rt_need_key(p_key);
  update rt_battles set status = 'finished', ended_at = now(), result = p_result where id = p_battle and status = 'active';
  return found;
end;
$$;


--
-- Name: rt_space_lock(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_lock(p_battle uuid, p_system text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n integer;
begin
  insert into rt_battle_locks (obj_kind, obj_id, battle_id)
  select 'ship', s.id, p_battle from ships s
   where (s.system_id = p_system and not coalesce(s.in_transit, false) and s.carrier_ship_id is null)
      or s.carrier_ship_id in (select c.id from ships c where c.system_id = p_system and not coalesce(c.in_transit, false) and c.carrier_ship_id is null)
  on conflict (obj_kind, obj_id) do update set battle_id = excluded.battle_id, locked_at = now();
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: rt_space_open(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_open(p_key text, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  bid uuid;
  st jsonb;
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);
  if not exists (select 1 from systems where id = p_system) then
    raise exception 'rt: нет системы %', p_system;
  end if;
  bid := rt_space_battle(p_system);
  if bid is null then
    update rt_battles set status = 'finished', ended_at = now() where kind = 'space' and system_id = p_system and status = 'active';
    insert into rt_battles (kind, system_id, meta) values ('space', p_system, jsonb_build_object('v', '2.0')) returning id into bid;
  else
    update rt_battles set heartbeat_at = now() where id = bid;
  end if;
  perform rt_space_lock(bid, p_system);
  update auto_moves set status = 'stopped', stop_reason = 'бой 2.0', updated_at = now()
   where system_id = p_system and layer = 'space' and status = 'active';
  st := rt_space_state(p_system);
  return st || jsonb_build_object('battle_id', bid);
end;
$$;


--
-- Name: rt_space_orders_take(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_orders_take(p_key text, p_battle uuid, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  perform rt_need_key(p_key);
  with t as (
    update rt_space_orders o set taken_at = now()
     where o.system_id = p_system and o.taken_at is null and o.created_at > now() - interval '5 minutes'
    returning o.ship_id, o.x, o.y
  )
  select coalesce(jsonb_agg(jsonb_build_object('ship_id', t.ship_id, 'x', t.x, 'y', t.y)), '[]'::jsonb) into v from t;
  return v;
end $$;


--
-- Name: rt_space_posts(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_posts(p_key text, p_battle uuid, p_ships jsonb DEFAULT '[]'::jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n integer := 0;
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);
  with rows as (
    select (x->>'id')::uuid as id, case when jsonb_typeof(x->'posts') = 'object' and x->'posts' <> '{}'::jsonb then x->'posts' end as posts
    from jsonb_array_elements(coalesce(p_ships, '[]'::jsonb)) x)
  update ships s set troop_posts = rows.posts
    from rows join rt_battle_locks l on l.obj_kind = 'ship' and l.obj_id = rows.id and l.battle_id = p_battle
   where s.id = rows.id;
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: rt_space_pull(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_pull(p_key text, p_battle uuid, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  st jsonb;
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);
  if not exists (select 1 from rt_battles b where b.id = p_battle and b.status = 'active') then
    return jsonb_build_object('closed', true);
  end if;
  update rt_battles set heartbeat_at = now() where id = p_battle;
  perform rt_space_lock(p_battle, p_system);
  st := rt_space_state(p_system);
  return st || jsonb_build_object('battle_id', p_battle);
end;
$$;


--
-- Name: rt_space_ships(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_ships(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id, 'ship_type', s.ship_type, 'name', s.name, 'owner_user_id', s.owner_user_id, 'faction', s.faction,
    'x', s.x, 'y', s.y, 'facing', coalesce(s.facing, 0), 'hp', s.hp,
    'shield_fore', s.shield_fore, 'shield_aft', s.shield_aft, 'shield_port', s.shield_port, 'shield_starboard', s.shield_starboard,
    'shields_updated_at', s.shields_updated_at, 'trophy', coalesce(s.trophy, false),
    'bonus_hp', s.bonus_hp, 'bonus_shield', s.bonus_shield, 'bonus_fore', s.bonus_fore, 'bonus_damage', s.bonus_damage,
    'bonus_vision', s.bonus_vision, 'bonus_move', s.bonus_move, 'bonus_hangar', s.bonus_hangar, 'bonus_capacity', s.bonus_capacity,
    'upgrades', to_jsonb(coalesce(s.upgrades, '{}'::text[])), 'commander_id', s.commander_id, 'jump_lock_until', s.jump_lock_until,
    'troop_posts', s.troop_posts,
    'rt_pose', case when s.rt_x is not null and s.rt_y is not null and s.rt_hd is not null then jsonb_build_array(s.rt_x, s.rt_y, s.rt_hd) end,
    'craft', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'ship_type', f.ship_type, 'hp', f.hp, 'carrier_ship_id', f.carrier_ship_id, 'owner_user_id', f.owner_user_id, 'faction', f.faction) order by f.created_at), '[]'::jsonb)
                from ships f where f.carrier_ship_id = s.id and f.hp > 0),
    'units', (select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'unit_type', u.unit_type, 'quantity', u.quantity, 'hp', u.hp,
                       'bonus_hp', u.bonus_hp, 'bonus_damage', u.bonus_damage, 'hero_name', u.hero_name, 'hero_id', u.hero_id,
                       'portrait', u.portrait, 'owner_user_id', u.owner_user_id, 'carrier_ship_id', u.carrier_ship_id)), '[]'::jsonb)
                from unit_positions u where u.carrier_ship_id = s.id and u.carrier_unit_id is null and u.hp > 0)
  ) order by s.created_at), '[]'::jsonb)
  from ships s
  where s.system_id = p_system and not coalesce(s.in_transit, false) and s.carrier_ship_id is null and s.hp > 0;
$$;


--
-- Name: rt_space_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_state(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'system', (select jsonb_build_object('id', s.id, 'name', s.name, 'faction', s.faction, 'deep', coalesce(s.is_deep_space, false),
                                         'controller', (select c.controller_user_id from system_control c where c.system_id = s.id))
                 from systems s where s.id = p_system),
    'ships', rt_space_ships(p_system),
    'types', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'faction', t.faction, 'max_hp', t.max_hp, 'max_shield', t.max_shield,
                        'shield_regen', t.shield_regen, 'damage', t.damage, 'capacity', t.capacity, 'hangar_slots', t.hangar_slots,
                        'width_cells', t.width_cells, 'height_cells', t.height_cells, 'is_fighter', coalesce(t.is_fighter, false), 'image', t.image)), '[]'::jsonb)
                from ship_types t),
    'settings', jsonb_build_object('grid', game_setting_int('space_grid_cells', 150), 'zone', game_setting_int('hyperspace_zone_height', 14),
                                   'pad', game_setting_int('orbital_drop_size', 6), 'regen', game_setting_int('shield_regen_seconds', 30)),
    'pads', (select jsonb_build_array(
               jsonb_build_object('idx', 1, 'x', g.grid / 4 - g.sz / 2, 'y', g.grid / 2 - g.sz / 2, 'size', g.sz),
               jsonb_build_object('idx', 2, 'x', g.grid * 3 / 4 - g.sz / 2, 'y', g.grid / 2 - g.sz / 2, 'size', g.sz))
             from (select game_setting_int('space_grid_cells', 150) as grid, game_setting_int('orbital_drop_size', 6) as sz) g),
    'station', (select jsonb_build_object('id', st.id, 'faction', st.faction, 'owner', st.owner_user_id, 'name', st.name,
                                          'ready', st.completes_at is null or st.completes_at <= now(),
                                          'x', sl.x, 'y', sl.y, 'size', sl.size)
                  from space_stations st left join station_slots sl on sl.system_id = st.system_id
                 where st.system_id = p_system limit 1),
    'slot', (select jsonb_build_object('x', sl.x, 'y', sl.y, 'size', sl.size) from station_slots sl where sl.system_id = p_system limit 1),
    'find', void_find_room(p_system)
  );
$$;


--
-- Name: rt_space_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_status(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('server', rt_server_status());
$$;


--
-- Name: rt_space_sync(text, uuid, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_space_sync(p_key text, p_battle uuid, p_ships jsonb DEFAULT '[]'::jsonb, p_craft jsonb DEFAULT '[]'::jsonb, p_units jsonb DEFAULT '[]'::jsonb, p_captured jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n_s integer := 0; n_c integer := 0; n_u integer := 0; n_t integer := 0; n_d integer := 0;
  r record;
  v_max integer;
  fire jsonb;
  held jsonb; held_off text[];
begin
  perform rt_need_key(p_key);
  perform set_config('app.rt_battle', '1', true);

  -- живые корабли: клетка, разворот, корпус, щиты
  with rows as (
    select (x->>'id')::uuid as id, (x->>'x')::integer as x, (x->>'y')::integer as y, (x->>'facing')::integer as facing,
           greatest(0, (x->>'hp')::integer) as hp,
           greatest(0, (x->'sh'->>0)::integer) as sf, greatest(0, (x->'sh'->>1)::integer) as ss,
           greatest(0, (x->'sh'->>2)::integer) as sa, greatest(0, (x->'sh'->>3)::integer) as sp,
           (x->>'mx')::double precision as mx, (x->>'my')::double precision as my, (x->>'hd')::double precision as hd
    from jsonb_array_elements(coalesce(p_ships, '[]'::jsonb)) x
    where coalesce((x->>'hp')::integer, 0) > 0)
  update ships s
     set x = coalesce(rows.x, s.x), y = coalesce(rows.y, s.y), facing = coalesce(rows.facing, s.facing), hp = rows.hp,
         shield_fore = rows.sf, shield_starboard = rows.ss, shield_aft = rows.sa, shield_port = rows.sp, shields_updated_at = now(),
         rt_x = rows.mx, rt_y = rows.my, rt_hd = rows.hd
    from rows join rt_battle_locks l on l.obj_kind = 'ship' and l.obj_id = rows.id and l.battle_id = p_battle
   where s.id = rows.id and not coalesce(s.in_transit, false)
     and s.system_id = (select b.system_id from rt_battles b where b.id = p_battle);
  get diagnostics n_s = row_count;

  -- машины ангара и истребители на орбите
  with rows as (
    select (x->>'id')::uuid as id, greatest(0, (x->>'hp')::integer) as hp
    from jsonb_array_elements(coalesce(p_craft, '[]'::jsonb)) x
    where coalesce((x->>'hp')::integer, 0) > 0)
  update ships f set hp = rows.hp
    from rows join rt_battle_locks l on l.obj_kind = 'ship' and l.obj_id = rows.id and l.battle_id = p_battle
   where f.id = rows.id;
  get diagnostics n_c = row_count;

  -- бойцы на борту
  with rows as (
    select (x->>'id')::uuid as id, greatest(0, (x->>'hp')::integer) as hp
    from jsonb_array_elements(coalesce(p_units, '[]'::jsonb)) x
    where coalesce((x->>'hp')::integer, 0) > 0)
  update unit_positions u set hp = rows.hp, updated_at = now()
    from rows
   where u.id = rows.id and u.carrier_ship_id is not null
     and exists (select 1 from rt_battle_locks l where l.obj_kind = 'ship' and l.obj_id = u.carrier_ship_id and l.battle_id = p_battle);
  get diagnostics n_u = row_count;

  -- трофеи
  for r in
    select (x->>'id')::uuid as id, (x->>'by')::uuid as captor, x->>'faction' as faction
    from jsonb_array_elements(coalesce(p_captured, '[]'::jsonb)) x
  loop
    if r.captor is null or r.faction not in ('republic', 'cis') then continue; end if;
    if not exists (select 1 from rt_battle_locks l where l.obj_kind = 'ship' and l.obj_id = r.id and l.battle_id = p_battle) then continue; end if;
    select t.max_hp + coalesce(s.bonus_hp, 0) into v_max from ships s join ship_types t on t.id = s.ship_type where s.id = r.id;
    delete from unit_positions where carrier_ship_id = r.id and carrier_unit_id is null;
    perform set_config('app.owner_transfer', '1', true);
    update ships set owner_user_id = r.captor, faction = r.faction, commander_id = null,
                     hp = least(hp, greatest(1, ceil(coalesce(v_max, hp) * 0.25)::integer)),
                     shield_fore = 0, shield_aft = 0, shield_port = 0, shield_starboard = 0, shields_updated_at = now(),
                     trophy = true, jump_lock_until = now() + make_interval(hours => greatest(0, game_setting_int('trophy_jump_lock_hours', 12)))
     where id = r.id;
    update ships set owner_user_id = r.captor, faction = r.faction where carrier_ship_id = r.id;
    perform set_config('app.owner_transfer', '', true);
    update repair_orders set delivered = true where ship_id = r.id and not delivered;
    n_t := n_t + 1;
  end loop;

  -- погибшие: бойцы, машины, корабли (груз и ангар уходят каскадом, как в старой игре)
  for r in
    select (x->>'id')::uuid as id from jsonb_array_elements(coalesce(p_units, '[]'::jsonb)) x where coalesce((x->>'hp')::integer, 0) <= 0
  loop
    delete from unit_positions u where u.id = r.id and u.carrier_ship_id is not null
       and exists (select 1 from rt_battle_locks l where l.obj_kind = 'ship' and l.obj_id = u.carrier_ship_id and l.battle_id = p_battle);
    n_d := n_d + 1;
  end loop;
  for r in
    select (x->>'id')::uuid as id from jsonb_array_elements(coalesce(p_craft, '[]'::jsonb) || coalesce(p_ships, '[]'::jsonb)) x where coalesce((x->>'hp')::integer, 0) <= 0
  loop
    if not exists (select 1 from rt_battle_locks l where l.obj_kind = 'ship' and l.obj_id = r.id and l.battle_id = p_battle) then continue; end if;
    delete from ships where id = r.id;
    delete from rt_battle_locks where obj_kind = 'ship' and obj_id = r.id;
    n_d := n_d + 1;
  end loop;

  -- кто под огнём (для запрета прыжка)
  select coalesce(jsonb_object_agg(x->>'id', to_jsonb(now())), '{}'::jsonb) into fire
    from jsonb_array_elements(coalesce(p_ships, '[]'::jsonb)) x where (x->>'fire')::boolean;
  -- притягивающий луч: корабль держат до этого времени (rt_battle_guard не пускает в гиперпространство); 0 — отпустили
  select coalesce(jsonb_object_agg(x->>'id', to_jsonb(now() + make_interval(secs => least(60, (x->>'held')::numeric)::double precision))), '{}'::jsonb) into held
    from jsonb_array_elements(coalesce(p_ships, '[]'::jsonb)) x where coalesce((x->>'held')::numeric, 0) > 0;
  select coalesce(array_agg(x->>'id'), '{}') into held_off
    from jsonb_array_elements(coalesce(p_ships, '[]'::jsonb)) x where x ? 'held' and coalesce((x->>'held')::numeric, 0) <= 0;
  update rt_battles b
     set heartbeat_at = now(),
         snapshot = jsonb_build_object('fire', coalesce((
           select jsonb_object_agg(k, v) from jsonb_each(coalesce(b.snapshot->'fire', '{}'::jsonb)) e(k, v)
            where (v #>> '{}')::timestamptz > now() - interval '60 seconds' and not (fire ? k)), '{}'::jsonb) || fire,
                                       'held', coalesce((
           select jsonb_object_agg(k, v) from jsonb_each(coalesce(b.snapshot->'held', '{}'::jsonb)) e(k, v)
            where (v #>> '{}')::timestamptz > now() and not (held ? k) and not (k = any(held_off))), '{}'::jsonb) || held),
         snapshot_at = now()
   where b.id = p_battle and b.status = 'active';
  return jsonb_build_object('ships', n_s, 'craft', n_c, 'units', n_u, 'captured', n_t, 'gone', n_d);
end;
$$;


--
-- Name: rt_void_sync(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rt_void_sync(p_key text, p_battle uuid, p_find uuid, p_guards jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare f record; t void_find_types;
begin
  perform rt_need_key(p_key);
  select * into f from void_finds where id = p_find and status = 'active' for update;
  if not found then return jsonb_build_object('closed', true); end if;

  update void_finds set guards = (
    select coalesce(jsonb_agg(g || coalesce((
             select jsonb_build_object('hp', least(coalesce((g ->> 'hp')::numeric, 1), greatest(0, least(1, round((u ->> 'hp')::numeric, 3)))),
                                       'x', round((u ->> 'x')::numeric), 'y', round((u ->> 'y')::numeric), 'hd', round((u ->> 'hd')::numeric, 3))
             from jsonb_array_elements(coalesce(p_guards, '[]'::jsonb)) u
             where (u ->> 'i')::int = (g ->> 'i')::int and jsonb_typeof(u -> 'hp') = 'number'
             limit 1), '{}'::jsonb) order by (g ->> 'i')::int), '[]'::jsonb)
    from jsonb_array_elements(f.guards) g)
   where id = f.id
   returning * into f;

  if f.guards_down_at is null and not exists (select 1 from jsonb_array_elements(f.guards) g where (g ->> 'hp')::numeric > 0) then
    update void_finds set guards_down_at = now(), tick_at = now() where id = f.id;
    select * into t from void_find_types where id = f.type_id;
    perform void_find_notify('void_find_guards', f.system_id,
      t.guard_name || ' разбиты у находки «' || t.title || '». Удержание открыто: '
        || void_find_dur(greatest(1, game_setting_int('void_find_hold_min', 180)) * 60) || ' в зоне — и находка ваша',
      jsonb_build_object('find', f.id, 'type', f.type_id, 'layer', 'space'));
  end if;
  return void_find_room(f.system_id);
end $$;


--
-- Name: ru_plural(integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ru_plural(p_n integer, p_one text, p_few text, p_many text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_n || ' ' || case
    when p_n % 10 = 1 and p_n % 100 <> 11 then p_one
    when p_n % 10 between 2 and 4 and (p_n % 100 < 12 or p_n % 100 > 14) then p_few
    else p_many end;
$$;


--
-- Name: save_faction_role(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_faction_role(p_id uuid, p_name text, p_powers text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); v_fac text; v_lead boolean; v_mine text[];
  v_name text := btrim(coalesce(p_name, ''));
  v_powers text[]; v_bad text; r record; v_id uuid;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_me;
  if not faction_power(v_me, v_fac, 'manage_roles') then
    raise exception 'Должностями управляет лидер и те, кому он это поручил';
  end if;
  perform pg_advisory_xact_lock(hashtext('faction_roles:' || v_fac));

  v_lead := is_faction_leader(v_me, v_fac);
  v_mine := my_faction_powers();

  if char_length(v_name) < 2 or char_length(v_name) > 32 then
    raise exception 'Название должности — от 2 до 32 знаков';
  end if;

  select string_agg(x, ', ') into v_bad from unnest(coalesce(p_powers, '{}')) x
  where not x = any(faction_power_list());
  if v_bad is not null then raise exception 'Неизвестные полномочия: %', v_bad; end if;

  select coalesce(array_agg(distinct x order by x), '{}') into v_powers
  from unnest(coalesce(p_powers, '{}')) x;

  if not v_lead and not (v_powers <@ v_mine) then
    raise exception 'Нельзя выдать полномочия, которых нет у тебя самого';
  end if;

  if p_id is null then
    if (select count(*) from faction_roles where faction = v_fac and not archived) >= 10 then
      raise exception 'Не больше 10 должностей во фракции';
    end if;
    begin
      insert into faction_roles (faction, name, powers, created_by)
      values (v_fac, v_name, v_powers, v_me) returning id into v_id;
    exception when unique_violation then
      raise exception 'Должность «%» уже есть', v_name;
    end;
    return v_id;
  end if;

  select * into r from faction_roles where id = p_id and faction = v_fac and not archived for update;
  if not found then raise exception 'Должность не найдена'; end if;

  if not v_lead then
    if exists (select 1 from faction_role_members where user_id = v_me and role_id = p_id) then
      raise exception 'Свою должность меняет лидер или тот, кто стоит выше';
    end if;
    if not (r.powers <@ v_mine) then
      raise exception 'Эта должность выше твоих полномочий';
    end if;
  end if;

  begin
    update faction_roles set name = v_name, powers = v_powers where id = p_id;
  exception when unique_violation then
    raise exception 'Должность «%» уже есть', v_name;
  end;
  return p_id;
end;
$$;


--
-- Name: scrap_trophy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrap_trophy(p_ship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid(); s record; t record; v_station record; v_sys_faction text; v_got jsonb;
  v_pct integer := greatest(0, least(100, game_setting_int('trophy_scrap_pct', 40)));
begin
  perform settle_due_orders();
  if v_user is null then raise exception 'Не авторизован'; end if;
  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if not s.trophy then raise exception 'Разбирают только трофеи — свой корабль сначала нужно потерять'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  perform assert_planet_operational(s.system_id);
  select * into v_station from space_stations where system_id = s.system_id for update;
  if not found then raise exception 'В этой системе нет космической станции'; end if;
  perform assert_production_access(v_user, s.system_id, null);
  if v_station.completes_at is not null and v_station.completes_at > now() then
    raise exception 'Станция ещё строится';
  end if;
  select faction into v_sys_faction from systems where id = s.system_id;
  if v_station.faction is distinct from v_sys_faction then
    raise exception 'Трофейная станция не работает на нового хозяина';
  end if;
  if not is_ship_at_dock(s.id) then
    raise exception 'Подведи корабль к станции — разбирают только у причала';
  end if;
  if exists (select 1 from repair_orders where ship_id = s.id and not delivered) then
    raise exception 'Этот корабль уже в работе';
  end if;
  if exists (select 1 from unit_positions where carrier_ship_id = s.id) then
    raise exception 'Сначала высади бойцов и технику из трюма';
  end if;
  if exists (select 1 from ships where carrier_ship_id = s.id) then
    raise exception 'Сначала выведи машины из ангара';
  end if;
  if exists (select 1 from ship_resource_cargo where ship_id = s.id and amount > 0) then
    raise exception 'Сначала выгрузи ресурсы из трюма';
  end if;

  select * into t from ship_types where id = s.ship_type;
  v_got := refund_build_resources(s.system_id, t.cost_resources, v_pct / 100.0);
  perform log_event(v_user, s.faction, s.system_id, 'ship_scrapped', coalesce(s.name, t.name), 1, 'private',
                    jsonb_build_object('got', v_got, 'layer', 'space', 'ship_type', s.ship_type));
  perform set_config('app.boarding_quiet', '1', true);
  perform boarding_drop_ship(s.id);
  perform set_config('app.boarding_quiet', '', true);
  return jsonb_build_object('got', v_got, 'pct', v_pct);
end;
$$;


--
-- Name: sell_to_trade_post(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sell_to_trade_post(p_system_id text, p_resource text, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_faction text; v_post text; v_price integer; v_total integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_amount < 1 then raise exception 'Некорректное количество'; end if;

  if not exists (select 1 from system_control sc
                 where sc.system_id = p_system_id and sc.controller_user_id = v_user) then
    raise exception 'Планета не под твоим контролем';
  end if;

  select faction into v_faction from profiles where id = v_user;
  v_post := case when v_faction = 'republic' then 'rep_trade' else 'cis_trade' end;

  if not exists (
    select 1 from buildings b join building_types bt on bt.id = b.building_type_id
    where b.system_id = p_system_id and bt.code = v_post
      and (b.completes_at is null or b.completes_at <= now())
      and b.faction = (select faction from systems where id = p_system_id)
  ) then
    raise exception 'На этой планете нет достроенного торгового поста';
  end if;

  perform take_planet_stock(p_system_id, p_resource, p_amount);

  v_price := trade_post_price(p_resource);
  v_total := v_price * p_amount;

  update profiles set credits = credits + v_total where id = v_user;

  perform log_event(v_user, v_faction, p_system_id, 'trade_sold',
                    p_resource, p_amount, 'private',
                    jsonb_build_object('credits', v_total, 'price', v_price));

  return v_total;
end;
$$;


--
-- Name: server_tz(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_tz() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select value from game_settings where key = 'server_tz'), 'Europe/Moscow');
$$;


--
-- Name: set_faction_directive(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_faction_directive(p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_text text := btrim(coalesce(p_text, '')); m record; v_prev timestamptz;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_me;
  if not faction_power(v_me, v_fac, 'orders') then
    raise exception 'Приказы отдаёт лидер и те, кому он это поручил';
  end if;
  if char_length(v_text) > 280 then raise exception 'Приказ — не длиннее 280 знаков'; end if;

  select updated_at into v_prev from faction_directives where faction = v_fac for update;
  insert into faction_directives (faction, text, updated_by, updated_at)
  values (v_fac, v_text, v_me, now())
  on conflict (faction) do update
    set text = excluded.text, updated_by = excluded.updated_by, updated_at = excluded.updated_at;

  if v_text = '' then return; end if;
  if v_prev is not null and v_prev > now() - interval '2 minutes' then return; end if;

  -- В сводку фракции — одной строкой, каждому в уведомления — лично
  perform log_event(v_me, v_fac, null, 'faction_order', left(v_text, 90), 1, 'faction', null);
  for m in select id from profiles where faction = v_fac and id <> v_me loop
    perform log_event(m.id, v_fac, null, 'faction_order', left(v_text, 90), 1, 'private', null);
  end loop;
end;
$$;


--
-- Name: set_faction_target(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_faction_target(p_system_id text, p_kind text, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid(); v_fac text; v_note text := nullif(btrim(coalesce(p_note, '')), '');
  s record;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_me;
  if not faction_power(v_me, v_fac, 'orders') then
    raise exception 'Цели ставит лидер и те, кому он это поручил';
  end if;
  perform pg_advisory_xact_lock(hashtext('faction_targets:' || v_fac));

  select * into s from systems where id = p_system_id;
  if not found or coalesce(s.is_deep_space, false) then raise exception 'Планета не найдена'; end if;

  if p_kind is null or p_kind = '' then
    update faction_targets set active = false where faction = v_fac and system_id = p_system_id and active;
    return;
  end if;

  if p_kind not in ('attack', 'defend', 'supply', 'gather') then
    raise exception 'Неизвестный приказ';
  end if;
  if v_note is not null and char_length(v_note) > 80 then
    raise exception 'Пояснение — не длиннее 80 знаков';
  end if;
  if p_kind = 'attack' and s.faction = v_fac then
    raise exception 'Наступать можно только на чужую планету';
  end if;
  if p_kind in ('defend', 'supply') and s.faction is distinct from v_fac then
    raise exception 'Оборонять и снабжать можно только свою планету';
  end if;

  if not exists (select 1 from faction_targets where faction = v_fac and system_id = p_system_id and active)
     and (select count(*) from faction_targets where faction = v_fac and active) >= 8 then
    raise exception 'Не больше 8 целей одновременно — сними старые';
  end if;

  update faction_targets set kind = p_kind, note = v_note, created_by = v_me, created_at = now()
  where faction = v_fac and system_id = p_system_id and active;
  if not found then
    insert into faction_targets (faction, system_id, kind, note, created_by)
    values (v_fac, p_system_id, p_kind, v_note, v_me);
  end if;

  perform log_event(v_me, v_fac, p_system_id, 'faction_target',
                    case p_kind when 'attack' then 'наступать' when 'defend' then 'оборонять'
                                when 'supply' then 'снабжать' else 'сбор сил' end,
                    1, 'faction', jsonb_build_object('kind', p_kind, 'note', v_note));
end;
$$;


--
-- Name: set_supply_route_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_supply_route_status(p_route_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); r record; cm record; v_txt text;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_status is null or p_status not in ('active', 'paused', 'stopped') then
    raise exception 'Неверное состояние рейса';
  end if;
  select * into r from supply_routes x where x.id = p_route_id and x.owner_user_id = v_user for update;
  if not found then raise exception 'Рейс не найден'; end if;
  if r.status = 'stopped' then raise exception 'Рейс уже завершён'; end if;
  if r.status = p_status then return; end if;

  select * into cm from commanders c where c.id = r.commander_id;

  if p_status = 'active' then
    if cm.id is null or cm.user_id <> v_user or not cm.unlocked then
      raise exception 'Командир рейса недоступен';
    end if;
    if not exists (select 1 from ships s where s.commander_id = cm.id and s.carrier_ship_id is null) then
      raise exception 'У командира не осталось кораблей';
    end if;
    update supply_routes x
       set status = 'active',
           expect_system = coalesce(cm.moving_to, cm.current_system),
           phase = case when x.phase in ('waiting', 'returning') then x.phase else 'travel' end,
           transit_wait_since = null,
           last_note = 'Рейс продолжен', updated_at = now()
     where x.id = r.id;
    v_txt := 'Рейс продолжен';
  elsif p_status = 'paused' then
    update supply_routes x set status = 'paused', last_note = 'Пауза', updated_at = now() where x.id = r.id;
    v_txt := 'Рейс на паузе';
  else
    update supply_routes x set status = 'stopped', last_note = 'Рейс завершён', wait_until = null,
                             updated_at = now() where x.id = r.id;
    v_txt := 'Рейс завершён игроком';
  end if;
  perform supply_log(r.id, (select c.current_system from commanders c where c.id = r.commander_id), v_txt, 0);
end $$;


--
-- Name: set_supply_rule(text, text, boolean, integer, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_supply_rule(p_system_id text, p_resource text, p_share boolean, p_keep_min integer, p_max_per_day integer, p_audience text, p_want_min integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if not exists (select 1 from system_control sc
                 where sc.system_id = p_system_id and sc.controller_user_id = v_user) then
    raise exception 'Правила склада задаёт только хозяин планеты';
  end if;
  if not exists (select 1 from resources r where r.id = p_resource) then
    raise exception 'Неизвестный ресурс';
  end if;
  if coalesce(p_keep_min, 0) < 0 or coalesce(p_want_min, 0) < 0 or coalesce(p_max_per_day, 0) < 0 then
    raise exception 'Значения не могут быть отрицательными';
  end if;
  if coalesce(p_keep_min, 0) > 1000000 or coalesce(p_want_min, 0) > 1000000
     or coalesce(p_max_per_day, 0) > 1000000 then
    raise exception 'Слишком большое значение';
  end if;
  if coalesce(p_audience, 'faction') not in ('faction', 'trusted') then
    raise exception 'Кому отдавать: фракции или доверенным';
  end if;

  insert into supply_rules (system_id, resource, share, keep_min, max_per_day, audience, want_min, set_by, updated_at)
  values (p_system_id, p_resource, coalesce(p_share, false), coalesce(p_keep_min, 0), p_max_per_day,
          coalesce(p_audience, 'faction'), coalesce(p_want_min, 0), v_user, now())
  on conflict on constraint supply_rules_pkey do update
    set share = excluded.share, keep_min = excluded.keep_min, max_per_day = excluded.max_per_day,
        audience = excluded.audience, want_min = excluded.want_min,
        set_by = excluded.set_by, updated_at = now();
end $$;


--
-- Name: settle_due_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_due_orders() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  -- Каждая выдача в своём подблоке: сбой выдачи не должен ронять
  -- действие игрока, крон всё равно подхватит заказ через полминуты
  if exists (select 1 from research_orders where not delivered and completes_at <= now()) then
    begin perform deliver_ready_research(); exception when others then perform err_db('settle_due_orders', sqlstate, sqlerrm, true); null; end;
  end if;
  if exists (select 1 from unit_orders where not delivered and completes_at <= now()) then
    begin perform deliver_ready_units(); exception when others then perform err_db('settle_due_orders', sqlstate, sqlerrm, true); null; end;
  end if;
  if exists (select 1 from repair_orders where not delivered and completes_at <= now()) then
    begin perform deliver_ready_repairs(); exception when others then perform err_db('settle_due_orders', sqlstate, sqlerrm, true); null; end;
  end if;
  if exists (select 1 from ship_orders where not delivered and completes_at <= now()) then
    begin perform deliver_ready_ships(); exception when others then perform err_db('settle_due_orders', sqlstate, sqlerrm, true); null; end;
  end if;
end;
$$;


--
-- Name: settlement_box(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_box() RETURNS TABLE(x integer, y integer, size integer)
    LANGUAGE sql STABLE
    AS $$
  select (f - s) / 2, (f - s) / 2, s
  from (select game_setting_int('ground_grid_cells', 144)
               - game_setting_int('ground_attack_zone_height', 4) as f,
               game_setting_int('settlement_size', 6) as s) q;
$$;


--
-- Name: settlement_cond(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_cond(p_system text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_total integer := 0; v_done integer := 0; v_left jsonb := '[]'::jsonb; t record; d boolean;
begin
  for t in select tk.id, tk.kind, tk.target, tk.payload from settlement_tasks tk
             join settlement_state st on st.system_id = tk.system_id and st.cycle_started = tk.cycle_start
            where tk.system_id = p_system order by tk.kind loop
    v_total := v_total + 1;
    d := settlement_task_done(t.id);
    if d then v_done := v_done + 1;
    else v_left := v_left || to_jsonb(settlement_task_label(t.kind, t.target, t.payload)); end if;
  end loop;
  return jsonb_build_object('total', v_total, 'done', v_done, 'left', v_left);
end;
$$;


--
-- Name: settlement_day_income(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_day_income(p_system text, p_sat integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select round(settlement_income(coalesce(p_sat, settlement_effective(p_system)))
               * coalesce((select l.income_mult from settlement_levels l
                           join settlement_state s on s.level = l.level
                           where s.system_id = p_system), 1)
               * case when settlement_has_district(p_system, 'market')
                      then 1 + (select effect_value from district_types where id = 'market') / 100.0
                      else 1 end
               * (100 + effect_sum(p_system, 'income')) / 100.0)::integer;
$$;


--
-- Name: settlement_dev_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_dev_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare st record; d record; v_ctrl uuid; v_name text; v_heal integer;
begin
  -- Захват идёт — расширение стоит: таймер сдвигается вперёд на шаг тика
  update settlement_state s set upgrade_until = s.upgrade_until + interval '30 seconds'
  where s.upgrade_until is not null and s.upgrade_until > now() and is_capture_active(s.system_id);
  update settlement_districts sd set completes_at = sd.completes_at + interval '30 seconds'
  where sd.completes_at > now() and is_capture_active(sd.system_id);

  for st in
    select s.system_id, s.upgrade_to, sy.faction, sy.name
    from settlement_state s join systems sy on sy.id = s.system_id
    where s.upgrade_until is not null and s.upgrade_until <= now()
    for update of s
  loop
    update settlement_state
    set level = st.upgrade_to, dev_points = 0, upgrade_until = null, upgrade_to = null
    where system_id = st.system_id;

    select name into v_name from settlement_levels where level = st.upgrade_to;
    select controller_user_id into v_ctrl from system_control where system_id = st.system_id;
    perform log_event(null, st.faction, st.system_id, 'settlement_level_up', v_name, st.upgrade_to, 'faction',
                      jsonb_build_object('level', st.upgrade_to));
  end loop;

  for d in
    select sd.system_id, sd.slot, sd.built_by, dt.name, sy.faction
    from settlement_districts sd
    join district_types dt on dt.id = sd.district_id
    join systems sy on sy.id = sd.system_id
    where not sd.notified and sd.completes_at <= now()
    for update of sd
  loop
    update settlement_districts set notified = true where system_id = d.system_id and slot = d.slot;
    perform log_event(d.built_by, d.faction, d.system_id, 'district_built', d.name, 1, 'private', null);
  end loop;

  -- Госпиталь: своя пехота рядом с поселением подлечивается (+5% в минуту)
  for d in
    select sd.system_id, sy.faction from settlement_districts sd join systems sy on sy.id = sd.system_id
    where sd.district_id = 'hospital' and sd.completes_at <= now()
  loop
    update unit_positions u
    set hp = least(t.max_hp + u.bonus_hp,
                   u.hp + greatest(1, ceil((t.max_hp + u.bonus_hp)
                          * (select effect_value from district_types where id = 'hospital') / 200.0)::integer))
    from unit_types t, settlement_box() b
    where t.id = u.unit_type and u.system_id = d.system_id and u.layer = 'ground'
      and u.x is not null and u.hp > 0 and not t.is_vehicle and u.faction = d.faction
      and u.hp < t.max_hp + u.bonus_hp
      and box_gap(u.x, u.y, t.width_cells, t.height_cells, b.x, b.y, b.size, b.size) <= 4;
  end loop;
end;
$$;


--
-- Name: settlement_effective(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_effective(p_system text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(0, least(game_setting_int('settlement_satisfaction_max', 100),
                           coalesce(sum(value), 0)))::integer
  from settlement_factors(p_system);
$$;


--
-- Name: settlement_factors(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_factors(p_system text) RETURNS TABLE(label text, value integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_ev integer; st record; v_bonus integer; v_mar integer; v_need integer; v_have integer; v_fields integer; b record;
begin
  select s.satisfaction, s.fed, s.level into st from settlement_state s where s.system_id = p_system;
  if not found then return; end if;

  label := 'Выполненные условия'; value := coalesce(st.satisfaction, 0); return next;

  if not exists (select 1 from system_control c where c.system_id = p_system and c.controller_user_id is not null) then
    label := 'Нет управляющего'; value := -game_setting_int('settlement_no_ruler_penalty', 10); return next;
  end if;

  v_bonus := settlement_structure_bonus(p_system);
  if v_bonus > 0 then label := 'Кантина'; value := v_bonus; return next; end if;

  if settlement_has_district(p_system, 'square') then
    label := 'Площадь'; value := (select effect_value from district_types where id = 'square'); return next;
  end if;

  select food_per_day into v_need from settlement_levels where level = st.level;
  if coalesce(v_need, 0) > 0 then
    select coalesce(amount, 0) into v_have from planet_stock where system_id = p_system and resource = 'food';
    v_fields := case when settlement_has_district(p_system, 'fields')
                     then (select effect_value from district_types where id = 'fields') else 0 end;
    if coalesce(v_have, 0) + v_fields < v_need then
      label := 'Голод'; value := -15; return next;
    elsif st.fed is true then
      label := 'Сыто'; value := 5; return next;
    end if;
  end if;

  v_ev := effect_sum(p_system, 'mood');
  if v_ev <> 0 then label := 'События'; value := v_ev; return next; end if;

  select * into b from settlement_box();
  select count(*) into v_mar
  from npc_brains nb join unit_positions u on u.id = nb.unit_id
  where nb.system_id = p_system and nb.kind = 'marauder' and u.hp > 0 and u.x is not null
    and box_gap(u.x, u.y, 1, 1, b.x, b.y, b.size, b.size) <= 8;
  if v_mar > 0 then
    label := 'Мародёры у стен'; value := -least(15, v_mar * 5); return next;
  end if;
end;
$$;


--
-- Name: settlement_feed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_feed(p_system text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_need integer; v_have integer; v_take integer; v_fed boolean; v_ctrl uuid; v_fields integer;
begin
  select l.food_per_day into v_need
  from settlement_state s join settlement_levels l on l.level = s.level where s.system_id = p_system;

  if settlement_has_district(p_system, 'fields') then
    v_fields := (select effect_value from district_types where id = 'fields');
    perform add_planet_stock(p_system, 'food', v_fields);
  end if;

  if coalesce(v_need, 0) <= 0 then
    update settlement_state set fed = null, food_short = 0 where system_id = p_system;
    return null;
  end if;

  select coalesce(amount, 0) into v_have from planet_stock where system_id = p_system and resource = 'food';
  v_take := least(coalesce(v_have, 0), v_need);
  if v_take > 0 then perform take_planet_stock(p_system, 'food', v_take); end if;

  v_fed := v_take >= v_need;
  update settlement_state set fed = v_fed, food_short = v_need - v_take where system_id = p_system;

  if not v_fed then
    select controller_user_id into v_ctrl from system_control where system_id = p_system;
    perform log_event(v_ctrl, (select faction from systems where id = p_system), p_system,
                      'settlement_hungry', null, v_need - v_take, 'private',
                      jsonb_build_object('need', v_need, 'got', v_take));
  end if;
  return v_fed;
end;
$$;


--
-- Name: settlement_gift(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_gift(p_system_id text, p_controller uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare
  v_faction text; v_vehicle boolean;
  v_type record; z record;
  cx integer; cy integer; tries integer := 0; v_id uuid;
begin
  select faction into v_faction from systems where id = p_system_id;
  if v_faction is null or p_controller is null then return null; end if;

  if floor(random() * 100) >= game_setting_int('settlement_gift_chance', 18) then
    return null;
  end if;

  v_vehicle := floor(random() * 100) < game_setting_int('settlement_gift_vehicle_chance', 4);

  -- Берём то, что эта фракция вообще умеет делать: подарок должен
  -- выглядеть как выпуск с местного завода, а не как чудо
  select * into v_type from unit_types
  where faction = v_faction and is_vehicle = v_vehicle and produced_by is not null
  order by random() limit 1;

  if not found then return null; end if;

  select * into z from settlement_zone_box();

  while tries < 80 loop
    tries := tries + 1;
    cx := z.x - 4 + floor(random() * (z.size + 8))::integer;
    cy := z.y - 4 + floor(random() * (z.size + 8))::integer;

    continue when not is_ground_box_free(p_system_id, cx, cy,
                                         v_type.width_cells, v_type.height_cells, null);

    insert into unit_positions (system_id, layer, x, y, owner_user_id,
                                faction, unit_type, quantity, hp)
    values (p_system_id, 'ground', cx, cy, p_controller,
            v_faction, v_type.id, 1, v_type.max_hp)
    returning id into v_id;

    perform log_event(p_controller, v_faction, p_system_id, 'settlement_gift',
                      v_type.name, 1, 'private',
                      jsonb_build_object('vehicle', v_vehicle));
    return v_id;
  end loop;

  return null;
end;
$$;


--
-- Name: settlement_has_district(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_has_district(p_system text, p_district text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from settlement_districts d
    where d.system_id = p_system and d.district_id = p_district and d.completes_at <= now()
      -- Во время расчёта выдачи settlement_tick ставит app.payout_at:
      -- квартал, начатый в окне перед выдачей, в неё не идёт
      and (coalesce(current_setting('app.payout_at', true), '') = ''
           or payout_eligible(d.created_at, d.completes_at,
                              current_setting('app.payout_at', true)::timestamptz)));
$$;


--
-- Name: settlement_income(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_income(p_satisfaction integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select game_setting_int('settlement_base_income', 300)
       + coalesce(p_satisfaction, 0) * game_setting_int('settlement_income_per_point', 10);
$$;


--
-- Name: settlement_militia_count(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_militia_count(p_system text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with base as (
    select coalesce(l.militia_base, 0)
           + case when settlement_has_district(p_system, 'garrison')
                  then (select effect_value from district_types where id = 'garrison') else 0 end as n,
           settlement_effective(p_system) as sat,
           loyalty_militia_k(p_system) as k
    from settlement_state s join settlement_levels l on l.level = s.level
    where s.system_id = p_system)
  select least(game_setting_int('militia_max', 15),
               floor(n * case when sat < 25 then 0.5 when sat < 60 then 0.75 else 1 end * k + 0.5))::integer
    from base;
$$;


--
-- Name: settlement_militia_why(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_militia_why(p_system text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s integer;
begin
  if coalesce(settlement_militia_count(p_system), 0) > 0 then
    if game_setting_int('unrest_penalties_enabled', 0) = 1
       and coalesce((select value from settlement_unrest where system_id = p_system), 0) >= 75 then
      return 'забастовки: жители не встают на защиту';
    end if;
    return null;
  end if;
  v_s := loyalty_support(p_system);
  if loyalty_on('effects') and v_s is not null and v_s < -19 then return 'народ ропщет на власть — защищать её некому'; end if;
  return 'не соберётся';
end;
$$;


--
-- Name: settlement_notice_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_notice_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cycle timestamptz := last_payout_at(); v_next timestamptz := next_payout_at(); u record; v_n integer := 0;
  v_kind text; v_list jsonb; v_left integer; v_one text; v_title text;
begin
  if now() < v_cycle + make_interval(hours => game_setting_int('settlement_morning_hours', 3)) then v_kind := 'morning';
  elsif now() >= v_next - make_interval(hours => game_setting_int('settlement_remind_before_hours', 8)) then v_kind := 'evening';
  else return 0; end if;

  for u in select sc.controller_user_id uid, s.faction from system_control sc join systems s on s.id = sc.system_id
            where sc.controller_user_id is not null group by 1, 2 loop
    -- уже сказано за эти сутки
    continue when exists (select 1 from settlement_notices n where n.user_id = u.uid and n.cycle = v_cycle and n.kind = v_kind);
    select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'total', (c ->> 'total')::integer,
                                                 'done', (c ->> 'done')::integer, 'left', c -> 'left') order by s.name), '[]'::jsonb)
      into v_list
      from system_control sc join systems s on s.id = sc.system_id
      join settlement_state st on st.system_id = s.id and st.cycle_started = v_cycle
      cross join lateral (select settlement_cond(s.id) c) q
     where sc.controller_user_id = u.uid and (q.c ->> 'total')::integer > 0;
    continue when jsonb_array_length(v_list) = 0;        -- условия этих суток ещё не выданы
    select coalesce(sum(jsonb_array_length(x -> 'left')), 0) into v_left from jsonb_array_elements(v_list) x;
    insert into settlement_notices (user_id, cycle, kind) values (u.uid, v_cycle, v_kind) on conflict do nothing;
    continue when v_kind = 'evening' and v_left = 0;      -- всё сделано — напоминать нечего
    v_one := case when jsonb_array_length(v_list) = 1 then v_list -> 0 ->> 'id' end;
    v_title := case when v_kind = 'morning'
      then 'Условия на сутки: ' || ru_plural(jsonb_array_length(v_list), 'планета', 'планеты', 'планет')
      else 'До итогов ' || game_setting_int('settlement_remind_before_hours', 8) || ' ч · не выполнено ' || v_left end;
    perform log_event(u.uid, u.faction, v_one, case when v_kind = 'morning' then 'settlement_conditions' else 'settlement_remind' end,
                      v_title, v_left, 'private', jsonb_build_object('planets', v_list, 'ends', v_next, 'digest', true,
                        'lines', (select coalesce(jsonb_agg(jsonb_build_object('txt', x ->> 'name' || ': ' ||
                                   case when jsonb_array_length(x -> 'left') = 0 then 'всё выполнено'
                                        else (select string_agg(l, ', ') from jsonb_array_elements_text(x -> 'left') l) end)), '[]'::jsonb)
                                  from jsonb_array_elements(v_list) x)));
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: settlement_pay_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_pay_task(p_task_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  t record; v_user uuid := auth.uid(); v_cost integer; v_credits integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into t from settlement_tasks where id = p_task_id for update;
  if not found then raise exception 'Задача не найдена'; end if;
  if t.done then raise exception 'Уже выполнено'; end if;

  if t.kind not in ('donation', 'festival') then
    raise exception 'Эту задачу деньгами не закрыть';
  end if;

  if not exists (
    select 1 from system_control sc
    where sc.system_id = t.system_id and sc.controller_user_id = v_user
  ) then
    raise exception 'Планета под управлением другого игрока';
  end if;

  -- Сумма зафиксирована при выдаче задачи: иначе её можно было бы
  -- переждать до более выгодного дня
  v_cost := t.target;

  select credits into v_credits from profiles where id = v_user;
  if v_credits < v_cost then
    raise exception 'Не хватает кредитов: нужно %', v_cost;
  end if;

  update profiles set credits = credits - v_cost where id = v_user;
  update settlement_tasks set done = true where id = p_task_id;

  perform log_event(v_user, null, t.system_id,
                    case t.kind when 'festival' then 'settlement_festival'
                                else 'settlement_donation' end,
                    null, v_cost, 'private', null);

  return v_cost;
end;
$$;


--
-- Name: settlement_structure_bonus(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_structure_bonus(p_system text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(st.satisfaction_bonus), 0)::integer
  from field_structures s
  join structure_types st on st.id = s.type_id
  join systems sy on sy.id = s.system_id
  where s.system_id = p_system and s.faction = sy.faction
    and s.completes_at <= now() and st.satisfaction_bonus > 0;
$$;


--
-- Name: settlement_task_done(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_task_done(p_task_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  t record; v_faction text; v_count integer;
begin
  select * into t from settlement_tasks where id = p_task_id;
  if not found then return false; end if;

  if t.kind in ('donation', 'festival') then
    return t.done;
  end if;

  select faction into v_faction from systems where id = t.system_id;

  if t.kind = 'guard' then
    select count(*) into v_count
    from unit_positions u join unit_types ut on ut.id = u.unit_type
    where u.system_id = t.system_id and u.layer = 'ground'
      and u.x is not null and u.hp > 0 and not ut.is_vehicle
      and u.faction = v_faction and u.owner_user_id is not null
      and is_in_settlement_zone(u.x, u.y);
    return v_count >= t.target;

  elsif t.kind = 'patrol' then
    select count(*) into v_count
    from unit_positions u join unit_types ut on ut.id = u.unit_type
    where u.system_id = t.system_id and u.layer = 'ground'
      and u.x is not null and u.hp > 0 and ut.is_vehicle
      and u.faction = v_faction and is_in_settlement_zone(u.x, u.y);
    return v_count >= t.target;

  elsif t.kind = 'orbit' then
    -- Корабль должен целиком стоять в одной из площадок сброса
    select count(*) into v_count
    from ships s join ship_types stp on stp.id = s.ship_type
    where s.system_id = t.system_id
      and s.faction = v_faction
      and not s.in_transit
      and s.hp > 0
      and is_in_orbital_drop(s.x, s.y,
            ship_box_w(stp.width_cells, stp.height_cells, s.facing),
            ship_box_h(stp.width_cells, stp.height_cells, s.facing)) is not null;
    return v_count >= t.target;

  elsif t.kind = 'factories' then
    select count(*) into v_count
    from buildings b join building_types bt on bt.id = b.building_type_id
    where b.system_id = t.system_id and bt.code in ('rep_vehicle', 'cis_vehicle');
    return v_count <= t.target;

  elsif t.kind = 'medical' then
    select count(*) into v_count
    from buildings b join building_types bt on bt.id = b.building_type_id
    where b.system_id = t.system_id
      and bt.code in ('rep_medical', 'cis_repair')
      and (b.completes_at is null or b.completes_at <= now());
    return v_count >= t.target;

  elsif t.kind = 'marauder' then
    -- Дневной налёт: ушли с добычей — провал; отменён, не состоялся или отбит — выполнено;
    -- до появления банды — ждём (а если время налёта прошло без неё — не в укор)
    if coalesce((t.payload ->> 'escaped')::boolean, false) then return false; end if;
    if t.payload ->> 'stage' in ('cancelled', 'calm', 'defeated') then return true; end if;
    if t.payload ->> 'stage' in ('scouted', 'warned') then
      return now() >= (t.payload ->> 'raid_ends')::timestamptz;
    end if;
    -- Банда: условие выполнено, когда не осталось никого из её состава
    return not exists (
      select 1 from unit_positions u
      where u.hp > 0
        and u.id in (select j.v::uuid
                     from jsonb_array_elements_text(coalesce(t.payload -> 'unit_ids',
                                                             jsonb_build_array(t.payload ->> 'unit_id'))) j(v)));
  end if;

  return false;
end;
$$;


--
-- Name: settlement_task_label(text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_task_label(p_kind text, p_target integer, p_payload jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_kind
    when 'guard'     then 'охрана: ' || p_target || ' пех. на площади'
    when 'patrol'    then 'патруль: ' || p_target || ' техн. в поселении'
    when 'orbit'     then 'корабль в площадке сброса'
    when 'marauder'  then case coalesce(p_payload ->> 'stage', '')
                            when 'raid' then 'налёт идёт — отбить'
                            when 'scouted' then 'налёт около ' || to_char(((p_payload ->> 'raid_at')::timestamptz) at time zone server_tz(), 'HH24:MI')
                            when 'warned' then 'налёт около ' || to_char(((p_payload ->> 'raid_at')::timestamptz) at time zone server_tz(), 'HH24:MI')
                            else 'налёт мародёров' end
    when 'donation'  then 'пожертвование ' || p_target || ' кр.'
    when 'festival'  then 'праздник ' || p_target || ' кр.'
    when 'factories' then 'заводов не больше ' || p_target
    when 'medical'   then 'лазарет'
    else p_kind end;
$$;


--
-- Name: settlement_tasks_on_assign(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_tasks_on_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_cycle timestamptz;
begin
  if new.controller_user_id is null then return null; end if;
  if tg_op = 'UPDATE' and old.controller_user_id is not null then return null; end if;
  select cycle_started into v_cycle from settlement_state where system_id = new.system_id;
  if v_cycle is null then return null; end if;
  if exists (select 1 from settlement_tasks where system_id = new.system_id and cycle_start = v_cycle) then return null; end if;
  perform issue_settlement_tasks(new.system_id, v_cycle);
  return null;
end;
$$;


--
-- Name: settlement_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sys record; st record;
  v_day integer := game_setting_int('settlement_day_seconds', 86400);
  v_step integer := game_setting_int('settlement_satisfaction_step', 15);
  v_pen integer := game_setting_int('settlement_satisfaction_penalty', 10);
  v_max integer := game_setting_int('settlement_satisfaction_max', 100);
  v_total integer; v_done integer; v_income integer;
  v_controller uuid; v_satisfaction integer; v_fed boolean; v_next_need integer; v_eff integer;
  v_p timestamptz := last_payout_at();
  v_lock integer := game_setting_int('payout_lock_hours', 4);
begin
  perform settlement_dev_tick();

  for sys in select id, faction from systems
                 where faction is not null and not is_deep_space loop

    select * into st from settlement_state where system_id = sys.id;

    if not found then
      insert into settlement_state (system_id, satisfaction, cycle_started)
      values (sys.id, 0, now());
      perform issue_settlement_tasks(sys.id, now());
      continue;
    end if;

    -- Итоги суток подводятся в час выдачи (04:00 по серверу)
    continue when st.cycle_started >= v_p;

    -- Сутки начались меньше чем за payout_lock_hours до выдачи (планету
    -- только что взяли): судить не за что. Без дохода и без штрафа —
    -- просто начинаем полные сутки с этой выдачи.
    if st.cycle_started > v_p - make_interval(hours => v_lock) then
      delete from unit_positions u
      using settlement_tasks t
      where t.system_id = sys.id and t.cycle_start = st.cycle_started
        and t.kind = 'marauder'
        and u.id in (select j.v::uuid
                     from jsonb_array_elements_text(coalesce(t.payload -> 'unit_ids',
                                                             jsonb_build_array(t.payload ->> 'unit_id'))) j(v));
      update settlement_state set cycle_started = v_p where system_id = sys.id;
      perform issue_settlement_tasks(sys.id, v_p);
      continue;
    end if;

    -- Кварталы, начатые в окне перед выдачей, в расчёт не идут
    perform set_config('app.payout_at', v_p::text, true);

    select count(*), count(*) filter (where settlement_task_done(t.id))
      into v_total, v_done
    from settlement_tasks t
    where t.system_id = sys.id and t.cycle_start = st.cycle_started;

    update settlement_tasks t
    set done = settlement_task_done(t.id)
    where t.system_id = sys.id and t.cycle_start = st.cycle_started;

    -- Каждое условие в зачёт: выполнено +gain, провалено −loss, все — ещё +bonus
    -- (sql/settlement_conditions.sql). Без управляющего условий нет, довольство падает.
    -- Ниже нуля не уходит: минимальный доход поселение платит всегда.
    if v_total > 0 then
      update settlement_state set satisfaction = least(v_max, greatest(0, satisfaction
          + v_done * game_setting_int('settlement_task_gain', 5)
          - (v_total - v_done) * game_setting_int('settlement_task_loss', 4)
          + case when v_done = v_total then game_setting_int('settlement_task_bonus', 5) else 0 end))
      where system_id = sys.id;
    elsif not exists (select 1 from system_control c where c.system_id = sys.id and c.controller_user_id is not null) then
      update settlement_state set satisfaction = greatest(0, satisfaction - game_setting_int('settlement_no_ruler_penalty', 10))
      where system_id = sys.id;
    end if;

    -- Поселение ест; сытость и голод сразу входят в довольство
    v_fed := settlement_feed(sys.id);

    -- Очки развития: чистые сутки без голода растят город, голод откатывает
    select l.dev_need into v_next_need
    from settlement_levels l where l.level = st.level + 1;
    if v_fed is false then
      update settlement_state set dev_points = greatest(0, dev_points - 1) where system_id = sys.id;
    elsif v_next_need is not null and v_total > 0 and v_done = v_total then
      update settlement_state set dev_points = least(v_next_need, dev_points + 1) where system_id = sys.id;
    end if;

    select satisfaction into v_satisfaction from settlement_state where system_id = sys.id;
    select controller_user_id into v_controller from system_control where system_id = sys.id;

    -- Банда прошлых суток уходит до расчёта дохода: провал условий уже наказан
    delete from unit_positions u
    using settlement_tasks t
    where t.system_id = sys.id and t.cycle_start = st.cycle_started
      and t.kind = 'marauder'
      and u.id in (select j.v::uuid
                   from jsonb_array_elements_text(coalesce(t.payload -> 'unit_ids',
                                                           jsonb_build_array(t.payload ->> 'unit_id'))) j(v));

    v_eff := settlement_effective(sys.id);
    -- напряжение на планете (sql/unrest.sql): сбой шкалы выплату не срывает
    begin perform unrest_day(sys.id, v_fed, v_eff, v_controller); exception when others then perform err_db('settlement_tick', sqlstate, sqlerrm, true); null; end;
    -- настроения планеты (sql/loyalty.sql): сбой шкалы выплату не срывает
    begin perform loyalty_day(sys.id); exception when others then perform err_db('settlement_tick', sqlstate, sqlerrm, true); null; end;
    v_income := settlement_day_income(sys.id);
    perform set_config('app.payout_at', '', true);

    -- Итог суток храним у поселения: сводка доходов берёт его отсюда,
    -- а не из ленты, где планеты теперь сложены в одно уведомление
    update settlement_state
    set last_done = v_done, last_total = v_total,
        last_income = case when v_controller is not null then v_income else last_income end
    where system_id = sys.id;

    if v_controller is not null then
      update profiles set credits = credits + v_income where id = v_controller;
      -- закон о налоге: доля дохода — в казну фракции
      begin perform treasury_tax(sys.faction, sys.id, v_income); exception when others then perform err_db('settlement_tick', sqlstate, sqlerrm, true); null; end;

      update settlement_state
      set last_paid_at = now(), total_paid = total_paid + v_income
      where system_id = sys.id;

      perform log_event_digest(v_controller, sys.faction, 'settlement_income', sys.id, sys.id,
        (select name from systems where id = sys.id), null, v_income,
        'довольство ' || v_eff ||
        case when v_fed is false then ' · голод' else '' end ||
        case when v_total > 0 then ' · условия ' || v_done || '/' || v_total ||
             case when v_done < v_total then ' — частично' else ' — все' end
             else '' end);

      -- Подарок только при полном довольстве и только текущему управляющему
      if v_eff >= v_max then
        perform settlement_gift(sys.id, v_controller);
      end if;
    end if;


    update settlement_state set cycle_started = v_p where system_id = sys.id;
    perform issue_settlement_tasks(sys.id, v_p);
  end loop;
end;
$$;


--
-- Name: settlement_zone_box(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settlement_zone_box() RETURNS TABLE(x integer, y integer, size integer)
    LANGUAGE sql STABLE
    AS $$
  select b.x - m, b.y - m, b.size + m * 2
  from settlement_box() b,
       (select game_setting_int('settlement_zone_margin', 2) as m) q;
$$;


--
-- Name: ship_box_h(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_box_h(p_w integer, p_h integer, p_facing integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_facing in (90,270) then p_w else p_h end;
$$;


--
-- Name: ship_box_w(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_box_w(p_w integer, p_h integer, p_facing integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_facing in (90,270) then p_h else p_w end;
$$;


--
-- Name: ship_load_used(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_load_used(p_ship_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select coalesce((
           select sum(c.quantity * coalesce(t.slot_size, 1))
           from ship_cargo c join unit_types t on t.id = c.unit_type
           where c.ship_id = p_ship_id
         ), 0)
       + coalesce((
           select sum(unit_total_slots(v.id))
           from unit_positions v
           where v.carrier_ship_id = p_ship_id
         ), 0)
       + coalesce((
           select sum(resource_slots(rc.amount))::integer
           from ship_resource_cargo rc
           where rc.ship_id = p_ship_id
         ), 0);
$$;


--
-- Name: ship_name_clean(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_name_clean(p_name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  v text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_low text;
begin
  if v = '' then return null; end if;
  if char_length(v) < 2 then raise exception 'Имя слишком короткое — нужно хотя бы 2 символа'; end if;
  if char_length(v) > 24 then raise exception 'Имя длиннее 24 символов'; end if;
  if v !~ '^[[:alnum:] ''-]+$' then
    raise exception 'В имени можно использовать только буквы, цифры, пробел, дефис и апостроф';
  end if;
  v_low := translate(lower(v), 'aeopcxykhmtb', 'аеорсхукнмтв');
  if v_low ~ '(ху[йеёяи]|пизд|\mеб[аулн]|(за|при|у|вы|на|по|отъ|съ|до|раз|въ)еб|ёб|\mбля(\M|д|т)|мудак|мудил|пид[оа]р|пидр|залуп|шлюх|гандон|\mсук[аи]\M|сучк|дроч)' then
    raise exception 'Такое имя не пройдёт цензуру флота';
  end if;
  return v;
end $_$;


--
-- Name: ship_repair_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_repair_quote(p_ship_id uuid) RETURNS TABLE(missing integer, full_hp integer, cost integer, seconds integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with parts as (
    select s.hp, (t.max_hp + s.bonus_hp) as full_hp, t.cost
    from ships s join ship_types t on t.id = s.ship_type
    where s.id = p_ship_id
    union all
    select f.hp, (ft.max_hp + f.bonus_hp), ft.cost
    from ships f join ship_types ft on ft.id = f.ship_type
    where f.carrier_ship_id = p_ship_id
  ),
  sums as (
    select sum(greatest(0, full_hp - hp))::integer as missing,
           sum(full_hp)::integer as full_hp,
           coalesce(sum(cost * greatest(0, full_hp - hp)::numeric / nullif(full_hp, 0)), 0) as raw_cost
    from parts
  ),
  tr as (
    select coalesce(s.trophy, false) as trophy, t.cost as tcost
    from ships s join ship_types t on t.id = s.ship_type
    where s.id = p_ship_id
  )
  select sums.missing, sums.full_hp,
         case when sums.missing <= 0 and not coalesce(tr.trophy, false) then 0
              when coalesce(tr.trophy, false) then
                greatest(1, ceil(greatest(sums.raw_cost, tr.tcost * 0.1)
                                 * game_setting_int('ship_repair_cost_pct', 100) / 100.0
                                 * game_setting_int('trophy_repair_pct', 150) / 100.0)::integer)
              else greatest(1, ceil(sums.raw_cost * game_setting_int('ship_repair_cost_pct', 100) / 100.0)::integer)
         end,
         case when sums.missing <= 0 and not coalesce(tr.trophy, false) then 0
              else greatest(case when coalesce(tr.trophy, false) then 60 else 5 end,
                            round(game_setting_int('ship_repair_seconds_full', 180)
                                  * sums.missing::numeric / nullif(sums.full_hp, 0))::integer)
         end
  from sums left join tr on true;
$$;


--
-- Name: ship_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_stats(p_ship_id uuid) RETURNS TABLE(max_hp integer, max_shield integer, fore_shield integer, damage integer, vision_range integer, move_range integer, hangar_slots integer, capacity integer, has_tractor boolean)
    LANGUAGE sql STABLE
    AS $$
  select t.max_hp + s.bonus_hp,
         t.max_shield + s.bonus_shield,
         t.max_shield + s.bonus_shield + s.bonus_fore,
         case when s.trophy then greatest(1, ceil((t.damage + s.bonus_damage) / 2.0)::integer)
              else t.damage + s.bonus_damage end,
         t.vision_range + s.bonus_vision,
         case when s.trophy then greatest(1, (t.move_range + s.bonus_move) / 2)
              else t.move_range + s.bonus_move end,
         t.hangar_slots + s.bonus_hangar,
         t.capacity + s.bonus_capacity,
         s.has_tractor
  from ships s join ship_types t on t.id = s.ship_type
  where s.id = p_ship_id;
$$;


--
-- Name: ship_transit_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ship_transit_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_flying boolean;
begin
  select in_transit into v_flying from ships
  where id = coalesce(new.ship_id, old.ship_id);

  if v_flying then
    raise exception 'Корабль в гиперпространстве — трюм недоступен';
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: shipyard_busy(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shipyard_busy(p_system_id text) RETURNS TABLE(name text, completes_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select * from (
    select coalesce(stp.name, 'корабль') as name, so.completes_at
    from ship_orders so
    left join ship_types stp on stp.id = so.ship_type
    where so.system_id = p_system_id and not so.delivered

    union all

    select case ro.kind
             when 'refit'  then 'модернизация ' || coalesce(s2.name, st2.name, 'корабля')
             when 'hangar' then 'пополнение ангара ' || coalesce(s2.name, st2.name, '')
             else 'ремонт ' || coalesce(s2.name, st2.name, 'корабля')
           end,
           ro.completes_at
    from repair_orders ro
    left join ships s2 on s2.id = ro.ship_id
    left join ship_types st2 on st2.id = s2.ship_type
    where ro.system_id = p_system_id and ro.building_id is null and not ro.delivered
  ) q
  order by q.completes_at
  limit 1;
$$;


--
-- Name: spawn_character_on_faction_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spawn_character_on_faction_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  capital_id text;
    i integer;
    begin
      if new.faction is not null and (old.faction is null or old.faction is distinct from new.faction) then
          if new.faction = 'republic' then
                capital_id := 'coruscant';
                    elsif new.faction = 'cis' then
                          capital_id := 'raxus';
                              else
                                    return new;
                                        end if;


                                                                        -- 5 слотов командиров, только первый разблокирован и стоит в столице
                                                                            for i in 1..5 loop
                                                                                  insert into commanders (user_id, faction, slot_index, unlocked, name, current_system)
                                                                                        values (
                                                                                                new.id,
                                                                                                        new.faction,
                                                                                                                i,
                                                                                                                        (i = 1),
                                                                                                                                new.nickname || ' — командир ' || i,
                                                                                                                                        case when i = 1 then capital_id else null end
                                                                                                                                              )
                                                                                                                                                    on conflict (user_id, slot_index) do update
                                                                                                                                                            set faction = excluded.faction;
                                                                                                                                                                end loop;
                                                                                                                                                                  end if;
                                                                                                                                                                    return new;
                                                                                                                                                                    end;
                                                                                                                                                                    $$;


--
-- Name: spawn_marauder(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spawn_marauder(p_system_id text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  return (spawn_marauder_gang(p_system_id, 1))[1];
end;
$$;


--
-- Name: spawn_marauder_gang(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spawn_marauder_gang(p_system_id text, p_n integer) RETURNS uuid[]
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  zb record; v_ids uuid[] := '{}'; v_id uuid; v_hp integer;
  v_hx integer; v_hy integer; v_cx integer; v_cy integer; tries integer := 0; i integer;
begin
  if coalesce(p_n, 0) < 1 then return v_ids; end if;
  select * into zb from settlement_zone_box();
  select max_hp into v_hp from unit_types where id = 'marauder';

  while tries < 80 and v_hx is null loop
    tries := tries + 1;
    v_cx := zb.x - 9 + floor(random() * (zb.size + 18))::integer;
    v_cy := zb.y - 9 + floor(random() * (zb.size + 18))::integer;
    continue when box_gap(v_cx, v_cy, 1, 1, zb.x, zb.y, zb.size, zb.size) not between 5 and 9;
    continue when not npc_spawn_cell_ok(p_system_id, v_cx, v_cy);
    v_hx := v_cx; v_hy := v_cy;
  end loop;
  if v_hx is null then return v_ids; end if;

  for i in 1..p_n loop
    if i = 1 then
      v_cx := v_hx; v_cy := v_hy;
    else
      select g.cx, g.cy into v_cx, v_cy
      from (select v_hx + dx as cx, v_hy + dy as cy
            from generate_series(-2, 2) dx, generate_series(-2, 2) dy
            where dx <> 0 or dy <> 0) g
      where npc_spawn_cell_ok(p_system_id, g.cx, g.cy)
      order by greatest(abs(g.cx - v_hx), abs(g.cy - v_hy)), random()
      limit 1;
      exit when not found;
    end if;

    insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type, quantity, hp)
    values (p_system_id, 'ground', v_cx, v_cy, null, 'marauder', 'marauder', 1, v_hp)
    returning id into v_id;

    insert into npc_brains (unit_id, kind, system_id, home_x, home_y, leash, state, last_hp)
    values (v_id, 'marauder', p_system_id, v_hx, v_hy, 8, 'idle', v_hp);

    v_ids := v_ids || v_id;
  end loop;

  return v_ids;
end;
$$;


--
-- Name: spawn_space(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spawn_space(p_system_id text, p_building uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(0,
    (select count(*)::integer from find_spawn_box_near(p_system_id, p_building, 1, 1))
    + (select count(*)::integer from free_deploy_cells(p_system_id, 0, 0))
    - coalesce((select sum(quantity)::integer from unit_orders where system_id = p_system_id and not delivered), 0));
$$;


--
-- Name: spend_ship_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spend_ship_action(p_ship_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_cd integer := game_setting_int('ship_action_cooldown_seconds', 30);
  v_max integer := game_setting_int('ship_action_max', 2);
  v_ap integer;
  v_at timestamptz;
  v_elapsed integer;
  v_gain integer;
  v_eff integer;
  v_anchor timestamptz;
begin
  select s.ap, s.ap_updated_at into v_ap, v_at
  from ships s where s.id = p_ship_id for update;

  v_elapsed := floor(extract(epoch from now() - v_at))::integer;
  v_gain := v_elapsed / v_cd;
  v_eff := least(v_max, v_ap + v_gain);

  if v_eff < 1 then
    raise exception 'Действие ещё не восстановилось: осталось % с', v_cd - (v_elapsed % v_cd);
  end if;

  if v_eff >= v_max then
    v_anchor := now();
  else
    v_anchor := v_at + make_interval(secs => v_gain * v_cd);
  end if;

  update ships set ap = v_eff - 1, ap_updated_at = v_anchor
  where id = p_ship_id;
end;
$$;


--
-- Name: spend_unit_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spend_unit_action(p_unit_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_cd integer := coalesce(
    (select t.action_seconds from unit_positions uu join unit_types t on t.id = uu.unit_type
     where uu.id = p_unit_id),
    game_setting_int('ship_action_cooldown_seconds', 30));
  v_max integer := game_setting_int('ship_action_max', 2);
  v_ap integer; v_at timestamptz;
  v_elapsed integer; v_gain integer; v_eff integer; v_anchor timestamptz;
begin
  select u.ap, u.ap_updated_at into v_ap, v_at
  from unit_positions u where u.id = p_unit_id for update;

  v_elapsed := floor(extract(epoch from now() - v_at))::integer;
  v_gain := v_elapsed / v_cd;
  v_eff := least(v_max, v_ap + v_gain);

  if v_eff < 1 then
    raise exception 'Юнит ещё не готов: осталось % с', v_cd - (v_elapsed % v_cd);
  end if;

  if v_eff >= v_max then
    v_anchor := now();
  else
    v_anchor := v_at + make_interval(secs => v_gain * v_cd);
  end if;

  update unit_positions set ap = v_eff - 1, ap_updated_at = v_anchor
  where id = p_unit_id;
end;
$$;


--
-- Name: spotting_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spotting_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  p record;
  v_forget interval := make_interval(mins => game_setting_int('spot_forget_minutes', 30));
begin
  -- ===== наземные: одна строка на пару «игрок — враг» =====
  for p in
    select distinct on (o.owner_user_id, e.id)
           o.owner_user_id as owner, o.faction, o.system_id,
           e.id as target, et.name as target_name, e.x as tx, e.y as ty
    from unit_positions o
    join unit_types ot on ot.id = o.unit_type
    join unit_positions e on e.system_id = o.system_id and e.layer = 'ground'
      and e.x is not null and e.faction is distinct from o.faction
    join unit_types et on et.id = e.unit_type
    where o.layer = 'ground' and o.x is not null and o.owner_user_id is not null
      and greatest(abs(e.x - o.x), abs(e.y - o.y)) <= (ot.vision_range + o.bonus_vision)
  loop
    update spotted_pairs set last_seen = now()
    where player_id = p.owner and target_id = p.target and layer = 'ground';
    continue when found;

    insert into spotted_pairs (player_id, target_id, layer)
    values (p.owner, p.target, 'ground') on conflict do nothing;

    perform log_event(p.owner, p.faction, p.system_id, 'enemy_spotted',
                      p.target_name, 1, 'private',
                      jsonb_build_object('x', p.tx, 'y', p.ty, 'layer', 'ground'));
  end loop;

  -- ===== космос =====
  for p in
    select distinct on (o.owner_user_id, e.id)
           o.owner_user_id as owner, o.faction, o.system_id,
           e.id as target, et.name as target_name, e.x as tx, e.y as ty
    from ships o
    join ship_types ot on ot.id = o.ship_type
    join ships e on e.system_id = o.system_id and e.x is not null
      and e.faction is distinct from o.faction and not e.in_transit
    join ship_types et on et.id = e.ship_type
    where o.x is not null and not o.in_transit and o.owner_user_id is not null
      and greatest(abs(e.x - o.x), abs(e.y - o.y)) <= (ot.vision_range + o.bonus_vision)
  loop
    update spotted_pairs set last_seen = now()
    where player_id = p.owner and target_id = p.target and layer = 'space';
    continue when found;

    insert into spotted_pairs (player_id, target_id, layer)
    values (p.owner, p.target, 'space') on conflict do nothing;

    perform log_event(p.owner, p.faction, p.system_id, 'enemy_spotted',
                      p.target_name, 1, 'private',
                      jsonb_build_object('x', p.tx, 'y', p.ty, 'layer', 'space'));
  end loop;

  delete from spotted_pairs where last_seen < now() - v_forget;
end;
$$;


--
-- Name: spy_agitate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_agitate(p_group uuid, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); g spy_groups; sy record; v_ctl uuid; v_j integer; v_cr integer; v_until timestamptz;
  v_cost integer := game_setting_int('loyalty_agit_cost', 250); v_go timestamptz;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  if not loyalty_on('ops') then raise exception 'Агитация сейчас недоступна'; end if;
  select * into g from spy_groups where id = p_group and owner_user_id = v_me for update;
  if not found or g.status = 'lost' then raise exception 'Группа не найдена'; end if;
  if g.status = 'mission' then raise exception 'Группа уже на задании'; end if;
  if g.ready_at > now() then raise exception 'Группа ещё не готова'; end if;
  if not spy_hq_ok(g.hq_building, v_me) then raise exception 'Штаб группы потерян — операции ведёт только действующий штаб'; end if;
  select id, name, faction into sy from systems where id = p_system and not coalesce(is_deep_space, false);
  if not found or coalesce(sy.faction, '') not in ('republic', 'cis') or sy.faction = g.faction then raise exception 'Агитация — только на планете врага'; end if;
  v_j := spy_jumps(g.base_system, p_system);
  if v_j is null or v_j < 1 then raise exception 'Цель дальше % гиперпутей от штаба группы', game_setting_int('spy_max_jumps', 3); end if;
  -- две группы стороны одновременно на одну планету: вторая ждёт первую и упирается в откат
  perform pg_advisory_xact_lock(hashtext('agit:' || p_system || ':' || g.faction));
  v_until := loyalty_agit_cd(p_system, g.faction);
  if v_until is not null and v_until > now() then
    raise exception 'На этой планете наши агитаторы уже работали — следующая агитация не раньше чем через % ч', ceil(extract(epoch from v_until - now()) / 3600);
  end if;
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  -- общий потолок на хозяина: агитация и диверсии разом не проскочат его вдвоём (как в spy_launch)
  if v_ctl is not null then perform pg_advisory_xact_lock(hashtext('spy_victim:' || v_ctl::text)); end if;
  if v_ctl is not null and (select count(*) from spy_ops where victim = v_ctl and launched_at > now() - interval '24 hours' and result is distinct from 'void') >= 2 then
    raise exception 'Хозяин этой планеты за сутки уже пережил две операции — его не трогают до завтра';
  end if;
  select credits into v_cr from profiles where id = v_me for update;
  if coalesce(v_cr, 0) < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;
  update profiles set credits = credits - v_cost where id = v_me;
  v_go := now() + make_interval(mins => v_j * game_setting_int('spy_jump_min', 30));
  insert into spy_ops (group_id, attacker, attacker_faction, base_system, target_building, target_system, victim, kind, spot, jumps, seed,
                       approach_at, act_at, back_at)
  values (g.id, v_me, g.faction, g.base_system, null, p_system, v_ctl, 'agitate', -3, v_j, floor(random() * 1000000000)::integer, v_go,
          v_go + make_interval(mins => game_setting_int('spy_approach_min', 15)),
          v_go + make_interval(mins => game_setting_int('spy_approach_min', 15) + game_setting_int('spy_exit_min', 10) + v_j * game_setting_int('spy_jump_min', 30)));
  update spy_groups set status = 'mission' where id = g.id;
  return spy_state();
end;
$$;


--
-- Name: spy_chance(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_chance(p_building uuid, p_wins integer, p_at timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(10, least(90, game_setting_int('spy_base_pct', 75)
       + case when spy_night(p_at) then game_setting_int('spy_night_pct', 10) else 0 end
       + game_setting_int('spy_vet_pct', 5) * least(3, coalesce(p_wins, 0))
       - game_setting_int('spy_guard_pct', 12) * coalesce(spy_guards(p_building), 0)
       - case when exists (select 1 from mine_shifts sh where sh.building_id = p_building and sh.status = 'run' and sh.task = 'guard')
              then game_setting_int('spy_watch_pct', 20) else 0 end
       - case when settlement_has_district((select system_id from mine_sites where building_id = p_building), 'comms')
              then game_setting_int('spy_comms_pct', 10) else 0 end));
$$;


--
-- Name: spy_chance_known(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_chance_known(p_wins integer, p_at timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(10, least(90, game_setting_int('spy_base_pct', 75)
       + case when spy_night(p_at) then game_setting_int('spy_night_pct', 10) else 0 end
       + game_setting_int('spy_vet_pct', 5) * least(3, coalesce(p_wins, 0))));
$$;


--
-- Name: spy_guards(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_guards(p_building uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select least(s.guards, mine_max_guards(s.places)) + case when settlement_has_district(s.system_id, 'garrison') then 1 else 0 end
    from mine_sites s where s.building_id = p_building;
$$;


--
-- Name: spy_hq_ok(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_hq_ok(p_building uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from buildings bd join building_types bt on bt.id = bd.building_type_id join systems sy on sy.id = bd.system_id
      join system_control sc on sc.system_id = bd.system_id
     where bd.id = p_building and bt.code in ('rep_hq', 'cis_control')
       and (bd.completes_at is null or bd.completes_at <= now())
       and bd.faction is not distinct from sy.faction and sc.controller_user_id = p_user);
$$;


--
-- Name: spy_jumps(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_jumps(p_a text, p_b text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with recursive w(sys, d) as (
    select p_a, 0
    union
    select case when h.system_a = w.sys then h.system_b else h.system_a end, w.d + 1
      from w join hyperlanes h on h.system_a = w.sys or h.system_b = w.sys
     where w.d < game_setting_int('spy_max_jumps', 3))
  select min(d) from w where sys = p_b;
$$;


--
-- Name: spy_kind_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_kind_name(p_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_kind when 'blast' then 'Саботаж оборудования' when 'strike' then 'Подстрекательство' when 'virus' then 'Вирус в дроидах'
                     when 'poison' then 'Срыв снабжения' when 'theft' then 'Кража со склада' when 'agitate' then 'Агитация' else p_kind end;
$$;


--
-- Name: spy_launch(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_launch(p_group uuid, p_building uuid, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); g spy_groups; s mine_sites; v_ctl uuid; v_sfac text; v_j integer; v_cr integer;
  v_cost integer := game_setting_int('spy_op_cost', 200); v_go timestamptz; v_until timestamptz;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  if p_kind not in ('blast', 'strike', 'virus', 'poison', 'theft') then raise exception 'Нет такой операции'; end if;
  select * into g from spy_groups where id = p_group and owner_user_id = v_me for update;
  if not found or g.status = 'lost' then raise exception 'Группа не найдена'; end if;
  if g.status = 'mission' then raise exception 'Группа уже на задании'; end if;
  if g.ready_at > now() then raise exception 'Группа ещё не готова'; end if;
  if not spy_hq_ok(g.hq_building, v_me) then raise exception 'Штаб группы потерян — операции ведёт только действующий штаб'; end if;
  select * into s from mine_sites where building_id = p_building;
  if not found or s.gone then raise exception 'Цель не найдена'; end if;
  select sc.controller_user_id, sy.faction into v_ctl, v_sfac from systems sy left join system_control sc on sc.system_id = sy.id where sy.id = s.system_id;
  if v_ctl is null or v_ctl = v_me or v_sfac is not distinct from g.faction then raise exception 'Диверсия — только против чужой планеты'; end if;
  v_j := spy_jumps(g.base_system, s.system_id);
  if v_j is null or v_j < 1 then raise exception 'Цель дальше % гиперпутей от штаба группы', game_setting_int('spy_max_jumps', 3); end if;
  perform pg_advisory_xact_lock(hashtext('spy_victim:' || v_ctl::text));
  perform pg_advisory_xact_lock(hashtext('spy_target:' || p_building::text));
  select max(launched_at) + interval '24 hours' into v_until from spy_ops
   where target_building = p_building and launched_at > now() - interval '24 hours' and result is distinct from 'void';
  if v_until is not null then raise exception 'По этой цели уже работали — следующая операция не раньше чем через % ч', ceil(extract(epoch from v_until - now()) / 3600); end if;
  if (select count(*) from spy_ops where victim = v_ctl and launched_at > now() - interval '24 hours' and result is distinct from 'void') >= 2 then
    raise exception 'Хозяин этой планеты за сутки уже пережил две операции — его не трогают до завтра';
  end if;
  select credits into v_cr from profiles where id = v_me for update;
  if coalesce(v_cr, 0) < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;
  update profiles set credits = credits - v_cost where id = v_me;
  v_go := now() + make_interval(mins => v_j * game_setting_int('spy_jump_min', 30));
  insert into spy_ops (group_id, attacker, attacker_faction, base_system, target_building, target_system, victim, kind, spot, jumps, seed,
                       approach_at, act_at, back_at)
  values (g.id, v_me, g.faction, g.base_system, p_building, s.system_id, v_ctl, p_kind,
          case when p_kind in ('blast', 'virus') then floor(random() * greatest(1, s.places))::integer when p_kind = 'strike' then -2 else -1 end,
          v_j, floor(random() * 1000000000)::integer, v_go,
          v_go + make_interval(mins => game_setting_int('spy_approach_min', 15)),
          v_go + make_interval(mins => game_setting_int('spy_approach_min', 15) + game_setting_int('spy_exit_min', 10) + v_j * game_setting_int('spy_jump_min', 30)));
  update spy_groups set status = 'mission' where id = g.id;
  return spy_state();
end;
$$;


--
-- Name: spy_night(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_night(p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select extract(hour from p_at at time zone coalesce((select value from game_settings where key = 'server_tz'), 'Europe/Moscow')) not between 6 and 21;
$$;


--
-- Name: spy_resolve(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_resolve(p_op uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o spy_ops; g spy_groups; s mine_sites; v_ctl uuid; v_vfac text; v_sname text; v_bname text; v_slot integer;
  v_ch integer; v_roll numeric; v_eff jsonb := '{}'::jsonb; v_sh mine_shifts; v_n integer; v_h numeric; v_have integer;
  v_txt text; v_take integer := 0; v_meta jsonb; v_aname text; v_bounty integer := game_setting_int('spy_bounty', 300);
begin
  select * into o from spy_ops where id = p_op and status = 'go' for update;
  if not found then return; end if;
  -- агитация — без цели-постройки (sql/loyalty.sql)
  if o.kind = 'agitate' then perform loyalty_agitate_resolve(p_op); return; end if;
  select * into g from spy_groups where id = o.group_id for update;
  -- порядок блокировок как у mine_tick и mine_finish: сначала идущая смена, потом участок
  perform 1 from mine_shifts where building_id = o.target_building and status = 'run' for update;
  select * into s from mine_sites where building_id = o.target_building for update;
  select sc.controller_user_id, sy.faction, sy.name into v_ctl, v_vfac, v_sname
    from systems sy left join system_control sc on sc.system_id = sy.id where sy.id = o.target_system;
  select bd.slot_index, bt.name into v_slot, v_bname
    from buildings bd join building_types bt on bt.id = bd.building_type_id where bd.id = o.target_building;
  select nickname into v_aname from profiles where id = o.attacker;
  v_meta := jsonb_build_object('slot', v_slot, 'building_id', o.target_building, 'op', o.id);

  -- цели больше нет или планета перешла к своим — группа возвращается ни с чем
  if s.building_id is null or s.gone or v_slot is null or v_ctl is null or v_vfac is not distinct from o.attacker_faction then
    update spy_ops set status = 'acted', acted_at = now(), result = 'void' where id = p_op;
    perform log_event(o.attacker, o.attacker_faction, o.target_system, 'spy_result',
      spy_kind_name(o.kind) || ': цели больше нет — группа возвращается', null, 'private', '{}'::jsonb);
    return;
  end if;

  v_ch := spy_chance(o.target_building, g.wins, now());
  v_roll := random() * 100;

  if v_roll >= v_ch then
    -- охрана заметила: группа схвачена, хозяин узнаёт сразу и получает награду
    update spy_ops set status = 'acted', acted_at = now(), result = 'caught', chance = v_ch, roll = v_roll, victim = v_ctl,
                       revealed = true, reveal_at = now() where id = p_op;
    update spy_groups set status = 'lost', lost_at = now() where id = g.id;
    update profiles set credits = credits + v_bounty where id = v_ctl;
    perform log_event(v_ctl, v_vfac, o.target_system, 'sabotage_caught',
      v_bname || ': охрана задержала диверсантов игрока ' || coalesce(v_aname, '?') || ' · награда ' || v_bounty || ' кр.',
      null, 'private', v_meta);
    perform log_event(o.attacker, o.attacker_faction, o.target_system, 'spy_result',
      'Провал: ' || g.name || ' в плену — ' || lower(spy_kind_name(o.kind)) || ', ' || v_bname || ' · шанс был ' || v_ch || ' %', null, 'private', '{}'::jsonb);
    return;
  end if;

  select * into v_sh from mine_shifts where building_id = s.building_id and status = 'run';
  if o.kind = 'blast' then
    update mine_sites set wear = least(100, wear + 30) where building_id = s.building_id;
    if v_sh.id is not null then perform mine_finish(v_sh.id, 'stopped'); end if;
    v_eff := jsonb_build_object('wear', 30, 'shift', v_sh.id is not null);
    v_txt := 'установка №' || (o.spot + 1) || ' выведена из строя: износ +30 %' || case when v_sh.id is not null then ', смена оборвана' else '' end;
  elsif o.kind = 'strike' then
    if s.humans > 0 then
      if v_sh.id is not null and v_sh.humans > 0 then perform mine_finish(v_sh.id, 'stopped'); end if;
      insert into mine_hurt (building_id, kind, n, until, reason) values (s.building_id, 'h', s.humans, now() + interval '6 hours', 'strike');
      v_txt := 'бригада бастует: ' || s.humans || ' чел. не выйдут 6 ч';
    else
      v_txt := 'подстрекатели у ворот, но людей в бригаде нет';
    end if;
    v_eff := jsonb_build_object('humans', s.humans);
  elsif o.kind = 'virus' then
    v_n := ceil(s.droids / 2.0)::integer;
    v_h := case when settlement_has_district(s.system_id, 'workshops') then 3 else 6 end;
    if v_n > 0 then
      if v_sh.id is not null and v_sh.droids > 0 then perform mine_finish(v_sh.id, 'stopped'); end if;
      insert into mine_hurt (building_id, kind, n, until, reason) values (s.building_id, 'd', v_n, now() + make_interval(hours => v_h::integer), 'virus');
      v_txt := 'сбой дроидов: ' || v_n || ' встали на ' || v_h || ' ч';
    else
      v_txt := 'вирус в сети, но дроидов в бригаде нет';
    end if;
    v_eff := jsonb_build_object('droids', v_n, 'hours', v_h);
  elsif o.kind = 'poison' then
    select coalesce(amount, 0) into v_have from planet_stock where system_id = s.system_id and resource = 'food' for update;
    v_n := least(40, ceil(coalesce(v_have, 0) * 0.25))::integer;
    if v_n > 0 then update planet_stock set amount = amount - v_n where system_id = s.system_id and resource = 'food'; end if;
    update mine_sites set spoiled_until = now() + interval '12 hours' where building_id = s.building_id;
    v_eff := jsonb_build_object('food', v_n);
    v_txt := 'снабжение сорвано: −' || coalesce(v_n, 0) || ' еды, ближайшая смена людей без пайка';
  else
    select coalesce(amount, 0) into v_have from planet_stock where system_id = s.system_id and resource = s.resource for update;
    v_take := least(120, floor(coalesce(v_have, 0) * 0.3))::integer;
    if v_take > 0 then update planet_stock set amount = amount - v_take where system_id = s.system_id and resource = s.resource; end if;
    v_eff := jsonb_build_object('stolen', v_take, 'res', s.resource);
    v_txt := 'склад вскрыт: пропало ' || v_take || ' — ' || lower((select name from resources where id = s.resource));
  end if;

  v_h := case when settlement_has_district(s.system_id, 'comms') then game_setting_int('spy_reveal_comms_h', 3) else game_setting_int('spy_reveal_h', 8) end
       * case when coalesce(spy_guards(s.building_id), 0) > 0 then 0.5 else 1 end;
  update spy_ops set status = 'acted', acted_at = now(), result = 'ok', chance = v_ch, roll = v_roll, victim = v_ctl, effect = v_eff,
                     stolen = v_take, stolen_res = case when v_take > 0 then s.resource end,
                     reveal_at = now() + make_interval(mins => round(v_h * 60)::integer)
   where id = p_op;
  perform log_event(v_ctl, v_vfac, o.target_system, 'sabotage_incident',
    v_bname || ': ' || v_txt || ' · причина выясняется, итоги следствия через ' || replace(rtrim(rtrim(to_char(v_h, 'FM990.0'), '0'), '.'), '.', ',') || ' ч',
    null, 'private', v_meta);
  perform log_event(o.attacker, o.attacker_faction, o.target_system, 'spy_result',
    g.name || ': «' || spy_kind_name(o.kind) || '» — успех, ' || v_bname || ', ' || v_sname || ' · ' || v_txt, null, 'private', '{}'::jsonb);
end;
$$;


--
-- Name: spy_site_ops(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_site_ops(p_building uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id, 'approach_at', o.approach_at, 'act_at', o.act_at, 'acted_at', o.acted_at, 'seed', o.seed,
           'side', o.attacker_faction, 'spot', case when o.acted_at is not null then o.spot end,
           'kind', case when o.acted_at is not null then o.kind end,
           'name', case when o.acted_at is not null then spy_kind_name(o.kind) end,
           'result', o.result, 'effect', case when o.acted_at is not null then o.effect end,
           'reveal_at', o.reveal_at, 'revealed', o.revealed,
           'who', case when o.revealed then (select nickname from profiles where id = o.attacker) end)
         order by o.approach_at desc), '[]'::jsonb)
    from spy_ops o
   where o.target_building = p_building and o.approach_at <= now() and o.approach_at > now() - interval '48 hours'
     and o.result is distinct from 'void';
$$;


--
-- Name: spy_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_state() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  select faction into v_fac from profiles where id = v_me;
  return jsonb_build_object(
    'now', now(), 'faction', v_fac, 'credits', (select credits from profiles where id = v_me),
    'max', game_setting_int('spy_max_groups', 2),
    'hqs', (select coalesce(jsonb_agg(jsonb_build_object('id', bd.id, 'system_id', bd.system_id, 'system_name', sy.name,
              'electronics', coalesce((select amount from planet_stock where system_id = bd.system_id and resource = 'electronics'), 0))
              order by sy.name), '[]'::jsonb)
              from buildings bd join building_types bt on bt.id = bd.building_type_id join systems sy on sy.id = bd.system_id
             where bt.code in ('rep_hq', 'cis_control') and spy_hq_ok(bd.id, v_me)),
    'groups', (select coalesce(jsonb_agg(jsonb_build_object(
                 'id', g.id, 'name', g.name, 'status', g.status, 'ready_at', g.ready_at, 'wins', g.wins, 'created_at', g.created_at,
                 'base_system', g.base_system, 'base_name', (select name from systems where id = g.base_system),
                 'hq_ok', spy_hq_ok(g.hq_building, v_me),
                 'op', (select jsonb_build_object('id', o.id, 'kind', o.kind, 'name', spy_kind_name(o.kind), 'target_name', sy.name,
                          'target_system', o.target_system, 'base_system', o.base_system, 'jumps', o.jumps,
                          'building_name', bt.name, 'launched_at', o.launched_at, 'approach_at', o.approach_at, 'act_at', o.act_at,
                          'back_at', o.back_at, 'acted_at', o.acted_at, 'result', o.result, 'stolen', o.stolen)
                          from spy_ops o join systems sy on sy.id = o.target_system
                          left join buildings bd on bd.id = o.target_building left join building_types bt on bt.id = bd.building_type_id
                         where o.group_id = g.id and o.status <> 'done' order by o.launched_at desc limit 1))
                 order by g.created_at), '[]'::jsonb)
                 from spy_groups g where g.owner_user_id = v_me and g.status <> 'lost'),
    'log', (select coalesce(jsonb_agg(x order by x->>'at' desc), '[]'::jsonb) from (
              select jsonb_build_object('at', coalesce(o.acted_at, o.launched_at), 'name', spy_kind_name(o.kind), 'kind', o.kind,
                       'target_name', sy.name, 'building_name', bt.name, 'result', o.result, 'chance', o.chance, 'stolen', o.stolen,
                       'group', (select name from spy_groups where id = o.group_id)) x
                from spy_ops o join systems sy on sy.id = o.target_system
                left join buildings bd on bd.id = o.target_building left join building_types bt on bt.id = bd.building_type_id
               where o.attacker = v_me and o.result is not null and o.launched_at > now() - interval '7 days'
               order by o.launched_at desc limit 12) q),
    -- карта операций: штабы и группы, всё в spy_max_jumps гиперпутях от них, пути между этими планетами
    'map', (with bases as (
              select bd.system_id s from buildings bd join building_types bt on bt.id = bd.building_type_id
               where bt.code in ('rep_hq', 'cis_control') and spy_hq_ok(bd.id, v_me)
              union select base_system from spy_groups where owner_user_id = v_me and status <> 'lost'),
            near as (select distinct sy.id from systems sy, bases b where not sy.is_deep_space and spy_jumps(b.s, sy.id) is not null)
            select jsonb_build_object(
              'systems', (select coalesce(jsonb_agg(jsonb_build_object('id', sy.id, 'name', sy.name, 'tex', sy.texture, 'x', sy.world_x, 'y', sy.world_y,
                            'faction', sy.faction, 'base', sy.id in (select s from bases),
                            'mine', exists (select 1 from system_control sc where sc.system_id = sy.id and sc.controller_user_id = v_me))), '[]'::jsonb)
                            from systems sy where sy.id in (select id from near)),
              'lanes', (select coalesce(jsonb_agg(jsonb_build_array(h.system_a, h.system_b)), '[]'::jsonb) from hyperlanes h
                         where h.system_a in (select id from near) and h.system_b in (select id from near)))),
    'cfg', jsonb_build_object(
      'cost', game_setting_int('spy_group_cost', 1200), 'electronics', game_setting_int('spy_group_electronics', 20),
      'train_min', game_setting_int('spy_train_min', 120), 'op_cost', game_setting_int('spy_op_cost', 200),
      'jump_min', game_setting_int('spy_jump_min', 30), 'max_jumps', game_setting_int('spy_max_jumps', 3), 'approach_min', game_setting_int('spy_approach_min', 15),
      'exit_min', game_setting_int('spy_exit_min', 10), 'rest_h', game_setting_int('spy_rest_h', 12),
      'base', game_setting_int('spy_base_pct', 75), 'guard', game_setting_int('spy_guard_pct', 12),
      'watch', game_setting_int('spy_watch_pct', 20), 'comms', game_setting_int('spy_comms_pct', 10),
      'night', game_setting_int('spy_night_pct', 10), 'vet', game_setting_int('spy_vet_pct', 5)));
end;
$$;


--
-- Name: spy_targets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_targets(p_group uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); g spy_groups; v_ops boolean := loyalty_on('ops');
begin
  select * into g from spy_groups where id = p_group and owner_user_id = v_me and status <> 'lost';
  if not found then raise exception 'Группа не найдена'; end if;
  return (select coalesce(jsonb_agg(p order by (p->>'jumps')::integer, p->>'system_name'), '[]'::jsonb) from (
    select jsonb_build_object('system_id', sy.id, 'system_name', sy.name, 'jumps', spy_jumps(g.base_system, sy.id),
             'owner', (select nickname from profiles where id = sc.controller_user_id),
             'victim_full', sc.controller_user_id is not null
                            and (select count(*) from spy_ops o where o.victim = sc.controller_user_id and o.launched_at > now() - interval '24 hours'
                                  and o.result is distinct from 'void') >= 2,
             'arrive', now() + make_interval(mins => spy_jumps(g.base_system, sy.id) * game_setting_int('spy_jump_min', 30)),
             'chance', spy_chance_known(g.wins, now() + make_interval(mins => spy_jumps(g.base_system, sy.id) * game_setting_int('spy_jump_min', 30)
                                                                       + game_setting_int('spy_approach_min', 15))),
             'sites', case when sc.controller_user_id is null or sc.controller_user_id = v_me then '[]'::jsonb else (
                       select coalesce(jsonb_agg(jsonb_build_object('building_id', ms.building_id, 'code', bt.code, 'name', bt.name,
                         'resource', ms.resource, 'res_name', r.name, 'color', r.color, 'places', ms.places,
                         'refine', mine_is_refine(ms.resource),
                         'cooldown_until', (select max(o.launched_at) + interval '24 hours' from spy_ops o where o.target_building = ms.building_id
                                             and o.launched_at > now() - interval '24 hours' and o.result is distinct from 'void'))
                         order by bt.name), '[]'::jsonb)
                         from mine_sites ms join buildings bd on bd.id = ms.building_id join building_types bt on bt.id = bd.building_type_id
                         join resources r on r.id = ms.resource
                        where ms.system_id = sy.id and not ms.gone and bd.faction is not distinct from sy.faction) end,
             -- агитация (sql/loyalty.sql): поддержка хозяина, наша сеть, когда снова можно, шанс без учёта гарнизона
             'agit', case when v_ops then jsonb_build_object(
                       's', loyalty_support(sy.id), 'capital', loyalty_capital(sy.id),
                       'cell', (select c.level from loyalty_cells c where c.system_id = sy.id and c.faction = g.faction),
                       'cd_until', loyalty_agit_cd(sy.id, g.faction),
                       'chance', greatest(10, least(90, spy_chance_known(g.wins, now() + make_interval(mins => spy_jumps(g.base_system, sy.id) * game_setting_int('spy_jump_min', 30)
                                                                       + game_setting_int('spy_approach_min', 15))) - loyalty_agit_pen(sy.id))),
                       'cost', game_setting_int('loyalty_agit_cost', 250), 'gain', game_setting_int('loyalty_agit_gain', 4)) end) p
      from systems sy left join system_control sc on sc.system_id = sy.id
     where sy.id <> g.base_system and not coalesce(sy.is_deep_space, false)
       and sy.faction in ('republic', 'cis') and sy.faction <> g.faction
       and spy_jumps(g.base_system, sy.id) between 1 and game_setting_int('spy_max_jumps', 3)
       and ((sc.controller_user_id is not null and sc.controller_user_id <> v_me
             and exists (select 1 from mine_sites ms where ms.system_id = sy.id and not ms.gone))
            or v_ops)) q);
end;
$$;


--
-- Name: spy_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v integer; v_bname text; v_sname text; v_aname text; v_afac text;
begin
  -- действие: группа на месте, подход прошёл
  for r in select id from spy_ops where status = 'go' and act_at <= now() order by act_at loop
    begin perform spy_resolve(r.id);
    exception when others then perform err_db('spy_tick', sqlstate, sqlerrm, true); end;
  end loop;
  -- возвращение: отдых, опыт, добыча кражи — на склад планеты штаба
  for r in select * from spy_ops where status = 'acted' and back_at <= now() loop
    begin
      update spy_ops set status = 'done' where id = r.id;
      if r.result in ('ok', 'void') then
        update spy_groups set status = 'home', ready_at = now() + make_interval(hours => game_setting_int('spy_rest_h', 12)),
                              wins = wins + case when r.result = 'ok' then 1 else 0 end
         where id = r.group_id and status = 'mission';
        if r.stolen > 0 then
          v := add_planet_stock(r.base_system, r.stolen_res, r.stolen);
          perform log_event(r.attacker, r.attacker_faction, r.base_system, 'spy_back',
            (select name from spy_groups where id = r.group_id) || ' на базе: ' || lower((select name from resources where id = r.stolen_res)) || ' +' || v
            || case when v < r.stolen then ' (склад полон, потеряно ' || (r.stolen - v) || ')' else '' end, v, 'private', '{}'::jsonb);
        end if;
      end if;
    exception when others then perform err_db('spy_tick', sqlstate, sqlerrm, true); end;
  end loop;
  -- следствие: хозяину — кто это сделал
  for r in select * from spy_ops where result = 'ok' and not revealed and reveal_at <= now() loop
    begin
      update spy_ops set revealed = true where id = r.id;
      select bt.name, sy.name into v_bname, v_sname from buildings bd join building_types bt on bt.id = bd.building_type_id
        join systems sy on sy.id = bd.system_id where bd.id = r.target_building;
      select nickname into v_aname from profiles where id = r.attacker;
      v_afac := case r.attacker_faction when 'republic' then 'Республика' when 'cis' then 'КНС' else r.attacker_faction end;
      perform log_event(r.victim, (select faction from systems where id = r.target_system), r.target_system, 'sabotage_revealed',
        coalesce(v_bname, 'Участок') || ': ' || lower(spy_kind_name(r.kind)) || ' — диверсия. Исполнитель — группа игрока '
        || coalesce(v_aname, '?') || ' (' || v_afac || ')', null, 'private',
        jsonb_build_object('slot', (select slot_index from buildings where id = r.target_building), 'building_id', r.target_building, 'op', r.id));
    exception when others then perform err_db('spy_tick', sqlstate, sqlerrm, true); end;
  end loop;
end;
$$;


--
-- Name: spy_train(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spy_train(p_hq uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_sys text; v_cr integer; v_cost integer := game_setting_int('spy_group_cost', 1200);
  v_name text; v_n integer;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  if not spy_hq_ok(p_hq, v_me) then raise exception 'Группы готовит штаб на своей планете'; end if;
  select faction into v_fac from profiles where id = v_me for update;
  select system_id into v_sys from buildings where id = p_hq;
  perform assert_planet_operational(v_sys);
  if (select count(*) from spy_groups where owner_user_id = v_me and status <> 'lost') >= game_setting_int('spy_max_groups', 2) then
    raise exception 'Групп не больше %', game_setting_int('spy_max_groups', 2);
  end if;
  select credits into v_cr from profiles where id = v_me for update;
  if coalesce(v_cr, 0) < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;
  perform take_planet_stock(v_sys, 'electronics', game_setting_int('spy_group_electronics', 20));
  update profiles set credits = credits - v_cost where id = v_me;
  select count(*) + 1 into v_n from spy_groups where owner_user_id = v_me;
  v_name := case when v_fac = 'cis'
    then 'Звено ИН-' || (10 + floor(random() * 89))::integer
    else 'Группа «' || (array['Тень', 'Сумрак', 'Шорох', 'Клинок', 'Вьюга', 'Полночь', 'Рысь', 'Туман'])[1 + floor(random() * 8)::integer] || '-' || v_n || '»' end;
  insert into spy_groups (owner_user_id, faction, hq_building, base_system, name, status, ready_at)
  values (v_me, v_fac, p_hq, v_sys, v_name, 'home', now() + make_interval(mins => game_setting_int('spy_train_min', 120)));
  return spy_state();
end;
$$;


--
-- Name: start_commander_move(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_commander_move(p_commander_id uuid, p_target_system text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_current text;
  v_unlocked boolean;
  v_arrives timestamptz;
  v_seconds integer;
  v_side text;
  v_not_ready integer;
  v_held text;
  v_moving text;
begin
  if v_user_id is null then
    raise exception 'Не авторизован';
  end if;

  select current_system, unlocked, arrives_at, moving_to
    into v_current, v_unlocked, v_arrives, v_moving
  from commanders
  where id = p_commander_id and user_id = v_user_id
  for update;

  if v_current is null and v_unlocked is null then
    raise exception 'Командир не найден';
  end if;

  if not v_unlocked then
    raise exception 'Командир ещё не разблокирован';
  end if;

  if v_moving is not null then
    if v_arrives is not null and v_arrives > now() then
      raise exception 'Командир уже в пути';
    end if;
    raise exception 'Флот только что прибыл — подожди пару секунд и повтори';
  end if;

  if v_current is null then
    raise exception 'Неизвестна текущая система командира';
  end if;

  if v_current = p_target_system then
    raise exception 'Командир уже находится в этой системе';
  end if;

  if not exists (
    select 1 from hyperlanes h
    where (h.system_a = v_current and h.system_b = p_target_system)
       or (h.system_b = v_current and h.system_a = p_target_system)
  ) then
    raise exception 'Между системами нет прямого маршрута';
  end if;

  select hyperspace_side(v_current, faction) into v_side
  from profiles where id = v_user_id;

  select count(*) into v_not_ready
  from ships s
  join ship_types t on t.id = s.ship_type
  where s.commander_id = p_commander_id
    and s.system_id = v_current
    and not s.in_transit
    and s.carrier_ship_id is null
    and not is_in_hyperspace_zone(
      s.y, ship_box_h(t.width_cells, t.height_cells, s.facing), v_side);

  if v_not_ready > 0 then
    raise exception 'Флот не готов к прыжку: % корабль(ей) вне зоны гиперпространства', v_not_ready;
  end if;

  select coalesce(s.name, t.name) || '» — ещё ' || ceil(extract(epoch from s.jump_lock_until - now()) / 3600.0)::integer || ' ч'
    into v_held
  from ships s join ship_types t on t.id = s.ship_type
  where s.commander_id = p_commander_id and s.system_id = v_current
    and not s.in_transit and s.carrier_ship_id is null
    and s.jump_lock_until is not null and s.jump_lock_until > now()
  order by s.jump_lock_until desc
  limit 1;
  if v_held is not null then
    raise exception 'Флот не может прыгнуть: гипердвигатель трофея «% (ремонт в доке снимет запрет)', v_held;
  end if;

  select value::integer into v_seconds from game_settings where key = 'travel_seconds';
  v_seconds := coalesce(v_seconds, 60);
  -- галактические события на этом гиперпути: шторм дольше, линия снабжения быстрее (sql/galaxy_events_2.sql)
  v_seconds := greatest(10, round(v_seconds * (100 + ge_travel_mod(v_current, p_target_system)) / 100.0)::integer);

  update commanders
  set warned_at = null,
      moving_from = v_current,
      moving_to = p_target_system,
      departed_at = now(),
      arrives_at = now() + make_interval(secs => v_seconds)
  where id = p_commander_id;

  -- Флот уходит в гиперпространство одновременно с командиром:
  -- пропадает с карты и освобождает клетки
  update ships
  set in_transit = true
  where commander_id = p_commander_id and system_id = v_current
    and carrier_ship_id is null;
end;
$$;


--
-- Name: start_commander_route(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_commander_route(p_commander_id uuid, p_target text) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); c record; v_fac text; v_path text[];
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select * into c from commanders where id = p_commander_id and user_id = v_user;
  if not found then raise exception 'Командир не найден'; end if;
  if not c.unlocked then raise exception 'Командир ещё не разблокирован'; end if;
  if c.moving_to is not null then raise exception 'Командир уже в пути'; end if;
  if c.current_system is null then raise exception 'Неизвестна текущая система командира'; end if;
  if c.current_system = p_target then raise exception 'Командир уже находится в этой системе'; end if;

  if exists (select 1 from supply_routes sr where sr.commander_id = c.id and sr.status = 'active') then
    raise exception 'Командир занят снабжением — сначала сними его с рейса';
  end if;

  select faction into v_fac from profiles where id = v_user;
  v_path := convoy_route_to(c.current_system, p_target, v_fac);
  if v_path is null then
    raise exception 'Нет пути через свои планеты — пролететь сквозь чужую систему нельзя';
  end if;

  perform start_commander_move(c.id, v_path[2]);

  update commanders
  set route = case when cardinality(v_path) > 2 then v_path[3:] else null end
  where id = c.id;

  return v_path;
end;
$$;


--
-- Name: start_hangar_restock(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_hangar_restock(p_ship_id uuid, p_fighters integer, p_bombers integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; st record; f record; b record;
  v_free integer; v_fi integer; v_bo integer;
  v_cost integer; v_seconds integer; v_credits integer;
begin
  perform assert_dock_ready(p_ship_id);

  select * into s from ships where id = p_ship_id;
  select * into st from ship_stats(p_ship_id);

  v_fi := greatest(0, coalesce(p_fighters, 0));
  v_bo := greatest(0, coalesce(p_bombers, 0));
  if v_fi + v_bo = 0 then raise exception 'Не выбрано ни одной машины'; end if;

  v_free := st.hangar_slots - hangar_used(p_ship_id);
  if v_fi + v_bo > v_free then
    raise exception 'Свободных мест в ангаре: %', greatest(0, v_free);
  end if;

  select * into f from ship_types
  where faction = s.faction and is_fighter and hull_class = 'fighter' limit 1;
  select * into b from ship_types
  where faction = s.faction and is_fighter and hull_class = 'bomber' limit 1;

  if v_fi > 0 and f.id is null then raise exception 'У твоей фракции нет истребителей'; end if;
  if v_bo > 0 and b.id is null then raise exception 'У твоей фракции нет бомбардировщиков'; end if;

  v_cost := v_fi * coalesce(f.cost, 0) + v_bo * coalesce(b.cost, 0);

  select credits into v_credits from profiles where id = v_user;
  if v_credits < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;

  v_seconds := greatest(5, (v_fi + v_bo) * game_setting_int('fighter_build_seconds', 20));

  insert into repair_orders (system_id, owner_user_id, faction, kind,
                             ship_id, fighters, bombers, cost, completes_at)
  values (s.system_id, v_user, s.faction, 'hangar', p_ship_id, v_fi, v_bo, v_cost,
          now() + make_interval(secs => v_seconds));

  update profiles set credits = credits - v_cost where id = v_user;
end;
$$;


--
-- Name: start_hero_training(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_hero_training(p_unit_id uuid, p_ability_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; t record; a record; h record;
  v_sys_faction text; v_kills integer; v_credits integer;
  v_shrine text; v_seconds integer; v_completes timestamptz;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Боец не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой боец'; end if;
  if u.hero_id is null then raise exception 'Обучать можно только одарённых'; end if;
  if u.x is null then raise exception 'Боец уже не на карте'; end if;

  select * into h from heroes where id = u.hero_id;
  if h.died_at is not null then raise exception 'Этот одарённый погиб'; end if;

  if exists (select 1 from hero_training where hero_id = u.hero_id and not delivered) then
    raise exception 'Обучение уже идёт';
  end if;

  perform assert_planet_operational(u.system_id);

  -- Храм на планете есть — решает аренда храма; нет — как раньше, управляющий
  select production_access_error(v_user, u.system_id, b.id) into v_shrine
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.system_id = u.system_id and bt.code in ('rep_temple', 'cis_sith')
  order by (production_access_error(v_user, u.system_id, b.id) is null) desc
  limit 1;
  if found then
    if v_shrine is not null then raise exception '%', v_shrine; end if;
  elsif not exists (
    select 1 from system_control sc
    where sc.system_id = u.system_id and sc.controller_user_id = v_user
  ) then
    raise exception 'Планета под контролем другого игрока';
  end if;

  select * into t from unit_types where id = u.unit_type;

  -- Обучение идёт в тылу: боец должен целиком стоять в зоне высадки
  if not is_box_in_deploy_zone(u.system_id, u.x, u.y, t.width_cells, t.height_cells) then
    raise exception 'Отведи одарённого в зону высадки — обучение идёт только в тылу';
  end if;

  -- Наставлять есть где: на планете нужен целый храм или святилище
  v_shrine := case when h.faction = 'republic' then 'rep_temple' else 'cis_sith' end;
  select faction into v_sys_faction from systems where id = u.system_id;

  if not exists (
    select 1 from buildings b join building_types bt on bt.id = b.building_type_id
    where b.system_id = u.system_id and bt.code = v_shrine
      and (b.completes_at is null or b.completes_at <= now())
      and b.faction = v_sys_faction
  ) then
    raise exception 'На планете нет достроенного %',
      case when h.faction = 'republic' then 'храма джедаев' else 'святилища ситхов' end;
  end if;

  select * into a from hero_abilities where id = p_ability_id;
  if not found then raise exception 'Способность не найдена'; end if;
  if a.faction <> h.faction then raise exception 'Эта способность для другой стороны'; end if;

  if exists (select 1 from hero_learned
             where hero_id = u.hero_id and ability_id = p_ability_id) then
    raise exception 'Уже изучено';
  end if;

  if exists (
    select 1 from unnest(a.requires) req
    where req not in (select ability_id from hero_learned where hero_id = u.hero_id)
  ) then
    raise exception 'Сначала нужно освоить предыдущую ступень ветки';
  end if;

  select count(*) into v_kills from hero_kills where hero_id = u.hero_id;
  if v_kills < a.kills_required then
    raise exception 'Нужно % убитых, а на счету %', a.kills_required, v_kills;
  end if;

  select credits into v_credits from profiles where id = v_user;
  if v_credits < a.cost_credits then
    raise exception 'Недостаточно кредитов: нужно %', a.cost_credits;
  end if;

  v_seconds := a.train_seconds;
  v_completes := now() + make_interval(secs => v_seconds);

  insert into hero_training (hero_id, unit_id, ability_id, system_id,
                             owner_user_id, cost, completes_at)
  values (u.hero_id, p_unit_id, p_ability_id, u.system_id,
          v_user, a.cost_credits, v_completes);

  -- Снимаем с карты. Строку не удаляем: удаление означало бы гибель,
  -- на нём висит триггер мемориала.
  update unit_positions
  set x = null, y = null, training_until = v_completes
  where id = p_unit_id;

  update profiles set credits = credits - a.cost_credits where id = v_user;

  perform log_event(v_user, h.faction, u.system_id, 'hero_training',
                    h.name, 1, 'private',
                    jsonb_build_object('ability', p_ability_id));
end;
$$;


--
-- Name: start_interception(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_interception(p_commander_id uuid, p_target_commander uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  me record; tgt record; v_lane text; v_seconds integer; v_arrive timestamptz;
  v_id uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into me from commanders where id = p_commander_id and user_id = v_user;
  if not found then raise exception 'Командир не найден'; end if;

  select * into tgt from commanders where id = p_target_commander;
  if not found then raise exception 'Цель не найдена'; end if;

  if tgt.faction is not distinct from me.faction then
    raise exception 'Это флот своей стороны';
  end if;

  if tgt.moving_to is null or tgt.arrives_at is null or tgt.arrives_at <= now() then
    raise exception 'Этот флот уже не в пути';
  end if;

  v_lane := lane_system(tgt.moving_from, tgt.moving_to);
  if v_lane is null then raise exception 'У этого маршрута нет точки перехвата'; end if;

  -- Выходить можно только с конца того же пути: гиперпрыжок идёт
  -- по прямой линии, и дотянуться из другого угла карты нельзя
  if me.current_system is distinct from tgt.moving_from
     and me.current_system is distinct from tgt.moving_to then
    raise exception 'Перехват возможен только с одного из концов маршрута';
  end if;

  -- Штаб — глаза и штабная работа: без него приказа не отдать
  if not exists (
    select 1 from buildings b join building_types bt on bt.id = b.building_type_id
    join systems s on s.id = b.system_id
    where b.system_id = me.current_system
      and bt.code in ('rep_hq', 'cis_control')
      and (b.completes_at is null or b.completes_at <= now())
      and b.faction = s.faction
  ) then
    raise exception 'На планете нет достроенного штаба';
  end if;

  select coalesce(value::integer, 60) into v_seconds
  from game_settings where key = 'travel_seconds';
  v_seconds := coalesce(v_seconds, 60);
  v_arrive := now() + make_interval(secs => v_seconds);

  if v_arrive >= tgt.arrives_at then
    raise exception 'Не успеть: цель будет на месте через % с, а флоту идти %',
      greatest(0, ceil(extract(epoch from tgt.arrives_at - now()))::integer), v_seconds;
  end if;

  if exists (select 1 from supply_routes sr where sr.commander_id = me.id and sr.status = 'active') then
    raise exception 'Командир занят снабжением — сначала сними его с рейса';
  end if;
  perform pg_advisory_xact_lock(hashtext('intercept:' || p_target_commander::text));
  if exists (select 1 from interceptions
             where target_commander = p_target_commander and status = 'pending') then
    raise exception 'Этот флот уже перехватывают';
  end if;

  -- Сам прыжок: проверит и разблокировку, и что флот стоит в зоне
  perform start_commander_move(p_commander_id, v_lane);

  insert into interceptions (hunter_commander, target_commander, lane_system,
                             hunter_user, target_user, resolves_at)
  values (p_commander_id, p_target_commander, v_lane, v_user, tgt.user_id, v_arrive)
  returning id into v_id;

  perform log_event(v_user, me.faction, v_lane, 'interception_launched',
                    tgt.name, 1, 'private', null);

  return v_id;
end;
$$;


--
-- Name: start_repair(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_repair(p_building_id uuid, p_unit_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_faction text; v_credits integer;
  v_system text; v_completes timestamptz; v_code text;
  v_bld_faction text; v_sys_faction text;
  v_slots integer; v_speed integer; v_active integer;
  v_kind text; u record; t record; q record; v_busy record;
begin
  -- созревшие заказы выдаём сразу, не дожидаясь крона
  perform settle_due_orders();
  if v_user is null then raise exception 'Не авторизован'; end if;

  select b.system_id, b.completes_at, bt.code, b.faction,
         b.production_slots, b.speed_bonus_pct
    into v_system, v_completes, v_code, v_bld_faction, v_slots, v_speed
  from buildings b join building_types bt on bt.id = b.building_type_id
  where b.id = p_building_id
  for update of b;

  if v_system is null then raise exception 'Постройка не найдена'; end if;

  v_kind := repair_building_kind(v_code);
  if v_kind is null then raise exception 'Эта постройка не занимается ремонтом'; end if;

  perform assert_planet_operational(v_system);

  perform assert_production_access(v_user, v_system, p_building_id);

  select faction into v_sys_faction from systems where id = v_system;
  if v_bld_faction is distinct from v_sys_faction then
    raise exception 'Трофейная постройка не работает на нового хозяина — её можно только снести';
  end if;

  if v_completes is not null and v_completes > now() then
    raise exception 'Постройка ещё не достроена';
  end if;

  v_active := building_line_used(p_building_id);
  if v_active >= coalesce(v_slots, 1) then
    select uo.completes_at, coalesce(uo.hero_name, ut.name) as name into v_busy
    from unit_orders uo
    left join unit_types ut on ut.id = uo.unit_type
    where uo.building_id = p_building_id and not uo.delivered
    order by uo.completes_at limit 1;

    if not found then
      select ro.completes_at, coalesce(u2.hero_name, ut2.name) as name into v_busy
      from repair_orders ro
      left join unit_positions u2 on u2.id = ro.unit_id
      left join unit_types ut2 on ut2.id = u2.unit_type
      where ro.building_id = p_building_id and not ro.delivered
      order by ro.completes_at limit 1;
    end if;

    raise exception 'Линия занята: % будет готов через % с',
      coalesce(v_busy.name, 'заказ'),
      greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer);
  end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.system_id <> v_system then raise exception 'Юнит на другой планете'; end if;
  if u.layer <> 'ground' or u.x is null then
    raise exception 'Юнит должен стоять на поверхности';
  end if;

  select * into t from unit_types where id = u.unit_type;

  if (case when t.is_vehicle then 'vehicle' else 'infantry' end) <> v_kind then
    raise exception 'Эта постройка чинит другое: %',
      case v_kind when 'vehicle' then 'только технику' else 'только пехоту' end;
  end if;

  -- Лечим только в тылу: юнит должен целиком стоять в зоне высадки
  if not is_box_in_deploy_zone(v_system, u.x, u.y, t.width_cells, t.height_cells) then
    raise exception 'Отведи раненого в зону высадки — на передовой не лечим';
  end if;

  if exists (select 1 from repair_orders where unit_id = p_unit_id and not delivered) then
    raise exception 'Этот боец уже в ремонте';
  end if;

  select * into q from repair_quote(p_unit_id);
  if q.missing <= 0 then raise exception 'Этот боец цел'; end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user;
  if v_credits < q.cost then
    raise exception 'Недостаточно кредитов: нужно %', q.cost;
  end if;

  insert into repair_orders (system_id, building_id, owner_user_id, faction, kind,
                             unit_id, heal_amount, cost, completes_at)
  values (v_system, p_building_id, v_user, v_faction, 'unit',
          p_unit_id, q.missing, q.cost,
          now() + make_interval(secs => greatest(5,
            round(q.seconds * (100 - coalesce(v_speed, 0)) / 100.0)::integer)));

  update profiles set credits = credits - q.cost where id = v_user;
end;
$$;


--
-- Name: start_research(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_research(p_building_id uuid, p_research_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  b record; bt record; r record;
  v_faction text; v_credits integer; v_busy record;
begin
  -- созревшие заказы выдаём сразу, не дожидаясь крона
  perform settle_due_orders();
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into b from buildings where id = p_building_id;
  if not found then raise exception 'Постройка не найдена'; end if;

  select * into bt from building_types where id = b.building_type_id;
  if bt.code not in ('rep_research', 'cis_lab') then
    raise exception 'Исследования ведёт только научный центр';
  end if;

  perform assert_planet_operational(b.system_id);

  if not exists (
    select 1 from system_control sc
    where sc.system_id = b.system_id and sc.controller_user_id = v_user
  ) then
    raise exception 'Планета под контролем другого игрока';
  end if;

  if b.completes_at is not null and b.completes_at > now() then
    raise exception 'Постройка ещё не достроена';
  end if;

  select faction, credits into v_faction, v_credits from profiles where id = v_user for update;

  if b.faction is distinct from v_faction then
    raise exception 'Трофейная постройка не работает на нового хозяина';
  end if;

  select * into r from researches where id = p_research_id;
  if not found then raise exception 'Неизвестное исследование'; end if;
  if not exists (select 1 from unit_types ut2 where ut2.faction = v_faction
                 and ut2.id = any(coalesce(r.applies_units, '{}')))
     and not exists (select 1 from ship_types st2 where st2.faction = v_faction
                     and st2.id = any(coalesce(r.applies_to, '{}'))) then
    raise exception 'Эта тема не для твоей фракции';
  end if;

  if exists (select 1 from player_research
             where user_id = v_user and research_id = p_research_id) then
    raise exception 'Уже изучено';
  end if;

  if r.requires is not null and not exists (
    select 1 from player_research
    where user_id = v_user and research_id = r.requires
  ) then
    raise exception 'Сначала нужно изучить: %',
      (select name from researches where id = r.requires);
  end if;

  -- Одна тема за раз на игрока: параллельно учиться нельзя
  select ro.completes_at, rs.name into v_busy
  from research_orders ro
  join researches rs on rs.id = ro.research_id
  where ro.owner_user_id = v_user and not ro.delivered
  order by ro.completes_at limit 1;

  if found then
    raise exception 'Ты уже изучаешь: % будет готово через % с',
      v_busy.name,
      greatest(0, ceil(extract(epoch from v_busy.completes_at - now()))::integer);
  end if;

  if v_credits < r.cost then
    raise exception 'Недостаточно кредитов: нужно %', r.cost;
  end if;

  insert into research_orders (system_id, building_id, faction, research_id,
                               owner_user_id, completes_at)
  values (b.system_id, p_building_id, v_faction, p_research_id, v_user,
          now() + make_interval(secs => r.research_seconds));

  update profiles set credits = credits - r.cost where id = v_user;
end;
$$;


--
-- Name: start_scout_move(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_scout_move(p_unit_id uuid, p_target_system text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; ut record; v_sys_faction text; v_attacking boolean;
  v_seconds integer := game_setting_int('scout_transit_seconds', 60);
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.x is null then raise exception 'Юнит уже в пути или в транспорте'; end if;
  if u.hp <= 0 then raise exception 'Юнит уничтожен'; end if;

  select * into ut from unit_types where id = u.unit_type;
  if not ut.is_scout then raise exception 'Сам по себе летать умеет только разведчик'; end if;

  -- Только со стороны десанта: разведчик улетает оттуда же, откуда прибыл
  select faction into v_sys_faction from systems where id = u.system_id;
  v_attacking := v_sys_faction is distinct from u.faction;

  if v_attacking then
    if not is_in_ground_attack_zone(u.y) then
      raise exception 'Отправить можно только из полосы вторжения';
    end if;
  else
    if not is_in_deploy_zone(u.system_id, u.x, u.y) then
      raise exception 'Отправить можно только из зоны высадки';
    end if;
  end if;

  if p_target_system = u.system_id then raise exception 'Он уже здесь'; end if;

  if exists (select 1 from systems where id = p_target_system and is_deep_space) then
    raise exception 'В открытом космосе нет поверхности — разведчику некуда сесть';
  end if;

  if not exists (
    select 1 from hyperlanes h
    where (h.system_a = u.system_id and h.system_b = p_target_system)
       or (h.system_b = u.system_id and h.system_a = p_target_system)
  ) then
    raise exception 'С этой планетой нет прямой связи';
  end if;

  -- Убираем с карты: в пути его не видит никто, включая владельца
  update unit_positions
  set x = null, y = null,
      transit_to = p_target_system,
      transit_arrives = now() + make_interval(secs => v_seconds)
  where id = p_unit_id;

  perform log_event(v_user, u.faction, p_target_system, 'scout_departed',
                    ut.name, 1, 'private',
                    jsonb_build_object('from', u.system_id));

  return v_seconds;
end;
$$;


--
-- Name: start_settlement_upgrade(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_settlement_upgrade(p_system_id text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_dev jsonb; nx record; v_until timestamptz;
begin
  if v_me is null then raise exception 'Не авторизован'; end if;
  perform assert_planet_operational(p_system_id);
  perform 1 from settlement_state where system_id = p_system_id for update;
  perform 1 from profiles where id = v_me for update;

  v_dev := get_settlement_dev(p_system_id);
  if v_dev is null then raise exception 'Поселение недоступно'; end if;
  if not (v_dev ->> 'can_upgrade')::boolean then raise exception '%', v_dev ->> 'upgrade_block'; end if;

  select * into nx from settlement_levels where level = (v_dev ->> 'level')::integer + 1;

  perform take_build_resources(p_system_id, nx.cost_resources, 1);
  update profiles set credits = credits - nx.cost_credits where id = v_me;

  v_until := now() + make_interval(secs => nx.build_seconds);
  update settlement_state set upgrade_until = v_until, upgrade_to = nx.level where system_id = p_system_id;

  perform log_event(v_me, (select faction from systems where id = p_system_id), p_system_id,
                    'settlement_upgrade', nx.name, nx.level, 'private', jsonb_build_object('until', v_until));
  return v_until;
end;
$$;


--
-- Name: start_ship_refit(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_ship_refit(p_ship_id uuid, p_upgrades text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; v_credits integer; v_cost integer; v_seconds integer;
  v_bad text; v_n integer;
begin
  perform assert_dock_ready(p_ship_id);

  select * into s from ships where id = p_ship_id;
  if exists (select 1 from ship_types st where st.id = s.ship_type and st.faction is distinct from s.faction) then
    raise exception 'Трофей чужой фракции не улучшают — только чинят или разбирают';
  end if;

  v_n := coalesce(array_length(p_upgrades, 1), 0);
  if v_n = 0 then raise exception 'Не выбрано ни одного улучшения'; end if;

  -- Уже стоит
  select r.name into v_bad
  from unnest(p_upgrades) u join researches r on r.id = u
  where u = any(coalesce(s.upgrades, '{}')) limit 1;
  if v_bad is not null then raise exception 'Уже установлено: %', v_bad; end if;

  -- Не изучено лично
  select r.name into v_bad
  from unnest(p_upgrades) u join researches r on r.id = u
  where not exists (select 1 from player_research pr
                    where pr.user_id = v_user and pr.research_id = u) limit 1;
  if v_bad is not null then raise exception 'Не изучено: %', v_bad; end if;

  -- Не подходит этому классу
  select r.name into v_bad
  from unnest(p_upgrades) u join researches r on r.id = u
  where not (s.ship_type = any(r.applies_to)) limit 1;
  if v_bad is not null then raise exception 'Не ставится на этот корабль: %', v_bad; end if;

  select coalesce(sum(r.cost / 4)::integer, 0) into v_cost
  from researches r where r.id = any(p_upgrades);

  select credits into v_credits from profiles where id = v_user;
  if v_credits < v_cost then raise exception 'Недостаточно кредитов: нужно %', v_cost; end if;

  v_seconds := greatest(5, v_n * game_setting_int('refit_seconds_per_upgrade', 30));

  insert into repair_orders (system_id, owner_user_id, faction, kind,
                             ship_id, upgrades, cost, completes_at)
  values (s.system_id, v_user, s.faction, 'refit', p_ship_id, p_upgrades, v_cost,
          now() + make_interval(secs => v_seconds));

  update profiles set credits = credits - v_cost where id = v_user;
end;
$$;


--
-- Name: start_ship_repair(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_ship_repair(p_ship_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; q record; v_credits integer;
begin
  perform assert_dock_ready(p_ship_id);

  select * into s from ships where id = p_ship_id;
  select * into q from ship_repair_quote(p_ship_id);

  if q.missing <= 0 and not s.trophy then raise exception 'Корабль цел'; end if;

  select credits into v_credits from profiles where id = v_user;
  if v_credits < q.cost then raise exception 'Недостаточно кредитов: нужно %', q.cost; end if;

  insert into repair_orders (system_id, owner_user_id, faction, kind,
                             ship_id, heal_amount, cost, completes_at)
  values (s.system_id, v_user, s.faction, 'ship', p_ship_id, q.missing, q.cost,
          now() + make_interval(secs => q.seconds));

  update profiles set credits = credits - q.cost where id = v_user;
end;
$$;


--
-- Name: structure_cover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.structure_cover(p_unit_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(max(st.cover_pct), 0)::integer
  from unit_positions u
  join unit_types ut on ut.id = u.unit_type
  join field_structures s on s.system_id = u.system_id and s.faction = u.faction
                          and s.completes_at <= now()
  join structure_types st on st.id = s.type_id
  where u.id = p_unit_id and u.layer = 'ground' and u.x is not null
    and st.cover_pct > 0
    and (not st.infantry_only or not ut.is_vehicle)
    and boxes_overlap(u.x, u.y, ut.width_cells, ut.height_cells, s.x, s.y, s.w, s.h);
$$;


--
-- Name: structure_damage_mult(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.structure_damage_mult(p_unit_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(max(st.damage_mult), 1)
  from unit_positions u
  join unit_types ut on ut.id = u.unit_type
  join field_structures s on s.system_id = u.system_id and s.faction = u.faction
                          and s.completes_at <= now()
  join structure_types st on st.id = s.type_id
  where u.id = p_unit_id and u.layer = 'ground' and u.x is not null
    and st.damage_mult > 1
    and (not st.infantry_only or not ut.is_vehicle)
    and boxes_overlap(u.x, u.y, ut.width_cells, ut.height_cells, s.x, s.y, s.w, s.h);
$$;


--
-- Name: structures_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.structures_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  s record; tg record; v record;
  v_day integer := game_setting_int('settlement_day_seconds', 86400);
  v_p timestamptz := last_payout_at();
  v_detect integer := game_setting_int('camo_detect_cells', 3);
  v_found boolean; v_got integer; v_chance integer; v_dmg integer; v_hp integer;
  zx integer; zy integer;
begin
  -- Планета ушла к врагу — полевые постройки прежних хозяев не выстояли
  for s in
    select fs.id from field_structures fs join systems sy on sy.id = fs.system_id
    where sy.faction is distinct from fs.faction
  loop
    perform destroy_structure(s.id, null);
  end loop;

  -- Сработавшие мины: бой записал им прочность 0 — убираем, место и предел свободны
  delete from field_structures f using structure_types t
   where t.id = f.type_id and t.kind = 'landmine' and f.hp <= 0;

  -- Достроено
  for s in
    select fs.id, fs.owner_user_id, fs.faction, fs.system_id, st.name, sy.name as sys_name
    from field_structures fs
    join structure_types st on st.id = fs.type_id
    join systems sy on sy.id = fs.system_id
    where not fs.notified and fs.completes_at <= now()
    for update of fs
  loop
    update field_structures set notified = true, last_tick_at = now() where id = s.id;
    perform log_event_digest(s.owner_user_id, s.faction, 'structure_built', 'fs:' || s.id,
                             s.system_id, s.sys_name, s.name, null, null);
  end loop;

  -- Сутки: мини-добыча на склад планеты, кантина — кредиты владельцу
  for s in
    select fs.id, fs.owner_user_id, fs.faction, fs.system_id, st.name,
           st.produces_resource, st.produces_per_day, st.credits_per_day, sy.name as sys_name
    from field_structures fs
    join structure_types st on st.id = fs.type_id
    join systems sy on sy.id = fs.system_id
    where fs.notified and fs.last_tick_at is not null
      and fs.last_tick_at < v_p
      and payout_eligible(fs.created_at, fs.completes_at, v_p)
      and (st.produces_per_day > 0 or st.credits_per_day > 0)
      and sy.faction = fs.faction
    for update of fs
  loop
    if s.produces_resource is not null and s.produces_per_day > 0 then
      v_got := add_planet_stock(s.system_id, s.produces_resource, s.produces_per_day);
      perform log_event_digest(s.owner_user_id, s.faction, 'resource_extracted',
        'fs:' || s.id, s.system_id, s.sys_name,
        (select name from resources where id = s.produces_resource), v_got,
        case when s.produces_per_day - v_got > 0
             then 'склад полон, потеряно ' || (s.produces_per_day - v_got) end);
    end if;

    if s.credits_per_day > 0 and s.owner_user_id is not null then
      update profiles set credits = credits + s.credits_per_day where id = s.owner_user_id;
      perform log_event_digest(s.owner_user_id, s.faction, 'settlement_income',
        'fs:' || s.id, s.system_id, s.sys_name, s.name, s.credits_per_day, null);
    end if;

    update field_structures set last_tick_at = now() where id = s.id;
  end loop;

  -- Глушилки: вражеский разведчик ближе radius клеток сгорает
  for s in
    select fs.id, fs.owner_user_id, fs.faction, fs.system_id, fs.x, fs.y, fs.w, fs.h, st.radius
    from field_structures fs
    join structure_types st on st.id = fs.type_id
    join systems sy on sy.id = fs.system_id
    where st.kind = 'jammer' and fs.completes_at <= now() and sy.faction = fs.faction
  loop
    zx := s.x + s.w / 2 - s.radius / 2;
    zy := s.y + s.h / 2 - s.radius / 2;
    for v in
      select u.id, u.owner_user_id, u.faction, u.x, u.y, t.name
      from unit_positions u join unit_types t on t.id = u.unit_type
      where u.system_id = s.system_id and u.layer = 'ground' and u.x is not null and u.hp > 0
        and t.is_scout and u.faction is distinct from s.faction
        and box_gap(u.x, u.y, t.width_cells, t.height_cells, s.x, s.y, s.w, s.h) <= s.radius
      for update of u
    loop
      delete from unit_positions where id = v.id;
      perform log_event(v.owner_user_id, v.faction, s.system_id, 'unit_killed', v.name, 1, 'private',
                        jsonb_build_object('jammed', true, 'x', v.x, 'y', v.y));
      perform log_event(s.owner_user_id, s.faction, s.system_id, 'scout_jammed', v.name, 1, 'private',
                        jsonb_build_object('x', v.x, 'y', v.y));
    end loop;
  end loop;

  -- Турели: заметила врага — через откат первый выстрел, дальше раз в откат
  for s in
    select fs.id, fs.owner_user_id, fs.faction, fs.system_id, fs.x, fs.y, fs.w, fs.h,
           fs.spotted_at, fs.last_shot_at, st.name, st.radius, st.damage, st.accuracy,
           st.cooldown_seconds, sy.name as sys_name
    from field_structures fs
    join structure_types st on st.id = fs.type_id
    join systems sy on sy.id = fs.system_id
    where st.kind = 'turret' and fs.completes_at <= now() and sy.faction = fs.faction
    for update of fs
  loop
    select u.id, u.unit_type, u.faction, u.owner_user_id, u.x, u.y, t.name as tname, t.hull_class,
           t.evasion + coalesce(u.bonus_evasion, 0) as ev
      into tg
    from unit_positions u join unit_types t on t.id = u.unit_type
    cross join lateral (select box_gap(s.x, s.y, s.w, s.h, u.x, u.y, t.width_cells, t.height_cells) as gap) g
    where u.system_id = s.system_id and u.layer = 'ground' and u.x is not null and u.hp > 0
      and u.faction is distinct from s.faction
      and g.gap <= s.radius
      and (t.stealth_range is null or g.gap <= t.stealth_range
           or radar_covers(s.system_id, s.faction, u.x, u.y, t.width_cells, t.height_cells))
      and (g.gap <= v_detect
           or coalesce(u.revealed_until, '-infinity'::timestamptz) > now()
           or radar_covers(s.system_id, s.faction, u.x, u.y, t.width_cells, t.height_cells)
           or not exists (
             select 1 from field_structures c join structure_types ct on ct.id = c.type_id
             where c.system_id = s.system_id and ct.kind = 'camo' and c.faction = u.faction
               and c.completes_at <= now()
               and boxes_overlap(u.x, u.y, t.width_cells, t.height_cells,
                                 c.x - ct.radius, c.y - ct.radius, c.w + ct.radius * 2, c.h + ct.radius * 2)))
    order by g.gap, u.hp
    limit 1;
    v_found := found;

    if not v_found then
      if s.spotted_at is not null then
        update field_structures set spotted_at = null where id = s.id;
      end if;
      continue;
    end if;

    if s.spotted_at is null then
      update field_structures set spotted_at = now() where id = s.id;
      continue;
    end if;

    continue when now() < s.spotted_at + make_interval(secs => s.cooldown_seconds);
    continue when s.last_shot_at is not null
               and now() < s.last_shot_at + make_interval(secs => s.cooldown_seconds);

    update field_structures set last_shot_at = now() where id = s.id;

    v_chance := greatest(5, least(95, s.accuracy - greatest(0, tg.ev)));
    if floor(random() * 100) >= v_chance then
      perform log_event_digest(s.owner_user_id, s.faction, 'turret_report', 'fs:' || s.id,
        s.system_id, s.sys_name, s.name, 1, 'промах по «' || tg.tname || '»');
      continue;
    end if;

    v_dmg := greatest(1, round(s.damage * damage_multiplier('turret', tg.hull_class))::integer);
    v_dmg := greatest(1, v_dmg);
    v_dmg := greatest(1, round(v_dmg * (100 - structure_cover(tg.id)) / 100.0)::integer);
    v_dmg := cap_hero_damage(tg.id, v_dmg);

    update unit_positions set hp = greatest(0, hp - v_dmg) where id = tg.id returning hp into v_hp;

    if v_hp > 0 then
      perform log_event(tg.owner_user_id, tg.faction, s.system_id, 'unit_damaged', tg.tname, v_dmg,
                        'private', jsonb_build_object('x', tg.x, 'y', tg.y, 'hp_left', v_hp, 'turret', true, 'unit_id', tg.id));
      perform log_event_digest(s.owner_user_id, s.faction, 'turret_report', 'fs:' || s.id,
        s.system_id, s.sys_name, s.name, 1, '«' || tg.tname || '» −' || v_dmg);
    else
      perform log_event(tg.owner_user_id, tg.faction, s.system_id, 'unit_killed', tg.tname, 1, 'private', jsonb_build_object('turret', true, 'x', tg.x, 'y', tg.y));
      delete from unit_positions where id = tg.id;
      perform log_event_digest(s.owner_user_id, s.faction, 'turret_report', 'fs:' || s.id,
        s.system_id, s.sys_name, s.name, 1, '«' || tg.tname || '» уничтожен');
    end if;
  end loop;
end;
$$;


--
-- Name: supply_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_cleanup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_del text := 'del' || 'ete from ';
begin
  -- журналы рейсов и supply_takes старше 7 дней и так чистит cleanup_old_records; здесь — то, что держат ссылки
  execute v_del || 'supply_route_log l using supply_routes r where l.route_id = r.id and r.status = ''stopped'' and r.updated_at < now() - interval ''14 days''';
  execute v_del || 'supply_routes where status = ''stopped'' and updated_at < now() - interval ''14 days''';
  execute v_del || 'market_orders o where o.status <> ''reserved'' and o.created_at < now() - interval ''14 days''
                     and not exists (select 1 from supply_routes r where r.order_id = o.id)';
  execute v_del || 'market_lots l where not l.active and l.created_at < now() - interval ''14 days''
                     and not exists (select 1 from market_orders o where o.lot_id = l.id)';
  execute v_del || 'supply_grants where status in (''revoked'', ''declined'') and coalesce(decided_at, created_at) < now() - interval ''30 days''';
exception when others then
  perform err_db('supply_cleanup', sqlstate, sqlerrm, true);
end;
$$;


--
-- Name: supply_fleet_free(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_fleet_free(p_commander_id uuid, p_here text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(greatest(0, st.capacity - ship_load_used(s.id))), 0)::integer
         * game_setting_int('cargo_units_per_slot', 2)
  from ships s cross join lateral ship_stats(s.id) st
  where s.commander_id = p_commander_id and not s.in_transit and s.system_id = p_here;
$$;


--
-- Name: supply_fleet_to_pad(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_fleet_to_pad(p_route_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  r record; cm record; v_fac text; v_here text; v_hname text;
  v_grid int := game_setting_int('space_grid_cells', 150);
  v_reach int := greatest(4, game_setting_int('supply_pad_reach', 7));
  v_pcx numeric; v_pcy numeric; v_live boolean; v_out int;
  s record; c record; v_w int; v_h int; v_l int; v_mr int; v_tx int; v_ty int; v_found boolean;
  v_txa int[] := '{}'; v_tya int[] := '{}'; v_twa int[] := '{}'; v_tha int[] := '{}';
  v_path jsonb; v_group uuid; v_new uuid[] := '{}'; v_id uuid; v_n int := 0; a uuid;
begin
  select * into r from supply_routes where id = p_route_id;
  select * into cm from commanders where id = r.commander_id;
  if r.id is null or cm.id is null or cm.moving_to is not null or cm.current_system is null then return 'ready'; end if;
  v_here := cm.current_system;
  select p.faction into v_fac from profiles p where p.id = r.owner_user_id;
  select sy.name into v_hname from systems sy where sy.id = v_here;

  -- ближайшая к флоту площадка (их две — слева и справа от планеты)
  select z.x + z.size / 2.0, z.y + z.size / 2.0 into v_pcx, v_pcy
  from orbital_drop_zones() z
  order by (select coalesce(sum(power(sh.x + ship_box_w(t.width_cells, t.height_cells, sh.facing) / 2.0 - (z.x + z.size / 2.0), 2)
                                + power(sh.y + ship_box_h(t.width_cells, t.height_cells, sh.facing) / 2.0 - (z.y + z.size / 2.0), 2)), 0)
            from ships sh join ship_types t on t.id = sh.ship_type
            where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null), z.idx
  limit 1;

  -- большому флоту нужен круг шире: площадь кораблей ×2 (половину круга занимает планета) + запас
  select greatest(v_reach, ceil(sqrt(2 * coalesce(sum(power(greatest(t.width_cells, t.height_cells), 2)), 0) / pi()))::int + 2)
    into v_reach
  from ships sh join ship_types t on t.id = sh.ship_type
  where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null;

  v_live := exists (select 1 from ships sh where sh.commander_id = cm.id and sh.system_id = v_here
                     and not sh.in_transit and sh.carrier_ship_id is null and rt_obj_busy_2_0('ship', sh.id) is not null);

  -- кто ещё далеко: середина корабля дальше v_reach клеток от середины площадки
  select count(*)::int into v_out
  from ships sh join ship_types t on t.id = sh.ship_type
  where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null
    and power(sh.x + ship_box_w(t.width_cells, t.height_cells, sh.facing) / 2.0 - v_pcx, 2)
      + power(sh.y + ship_box_h(t.width_cells, t.height_cells, sh.facing) / 2.0 - v_pcy, 2) > v_reach * v_reach;
  if v_out = 0 then
    if r.zone_tries <> 0 then update supply_routes set zone_tries = 0 where id = r.id; end if;
    execute 'del' || 'ete from rt_space_orders o where o.ship_id in (select sh.id from ships sh where sh.commander_id = $1)' using cm.id;
    return 'ready';
  end if;

  if v_live then
    update auto_moves am set status = 'stopped', stop_reason = 'cancelled', updated_at = now()
     where am.status = 'active' and am.label = 'К площадке сброса'
       and am.ship_id in (select sh.id from ships sh where sh.commander_id = cm.id);
    if exists (select 1 from rt_space_orders o join ships sh on sh.id = o.ship_id
                where sh.commander_id = cm.id and o.system_id = v_here
                  and (o.taken_at is null and o.created_at > now() - interval '5 minutes'
                       or o.taken_at > now() - interval '4 minutes')) then
      return 'moving';
    end if;
  elsif exists (select 1 from auto_moves am join ships sh on sh.id = am.ship_id
                 where am.status = 'active' and sh.commander_id = cm.id and sh.system_id = v_here) then
    return 'moving';
  end if;

  if r.zone_tries >= 3 then
    return 'blocked:Флот не может подойти к площадке сброса у ' || coalesce(v_hname, v_here);
  end if;

  if not v_live then
    begin
      perform 1 from ships sh where sh.commander_id = cm.id and sh.system_id = v_here
        and not sh.in_transit and sh.carrier_ship_id is null order by sh.id for update nowait;
    exception when lock_not_available then
      return 'moving';
    end;
  end if;

  update supply_routes set zone_tries = zone_tries + 1 where id = r.id;
  v_group := case when v_out > 1 then gen_random_uuid() end;

  -- ближние к площадке — первыми: им места у самой площадки
  for s in
    select sh.id, sh.x, sh.y, sh.facing, t.width_cells as tw, t.height_cells as th
    from ships sh join ship_types t on t.id = sh.ship_type
    where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null
      and power(sh.x + ship_box_w(t.width_cells, t.height_cells, sh.facing) / 2.0 - v_pcx, 2)
        + power(sh.y + ship_box_h(t.width_cells, t.height_cells, sh.facing) / 2.0 - v_pcy, 2) > v_reach * v_reach
    order by power(sh.x - v_pcx, 2) + power(sh.y - v_pcy, 2), sh.id
  loop
    v_w := ship_box_w(s.tw, s.th, s.facing);
    v_h := ship_box_h(s.tw, s.th, s.facing);
    v_l := greatest(s.tw, s.th);
    select ss.move_range into v_mr from ship_stats(s.id) ss;
    v_mr := greatest(1, coalesce(v_mr, 1));

    -- место: квадрат L×L, середина не дальше v_reach − 1 от середины площадки, ближайшие — первыми
    v_found := false;
    for c in
      select gx, gy
      from generate_series(greatest(0, floor(v_pcx - v_reach - v_l)::int), least(v_grid - v_l, ceil(v_pcx + v_reach)::int)) gx,
           generate_series(greatest(0, floor(v_pcy - v_reach - v_l)::int), least(v_grid - v_l, ceil(v_pcy + v_reach)::int)) gy
      where power(gx + v_l / 2.0 - v_pcx, 2) + power(gy + v_l / 2.0 - v_pcy, 2) <= power(v_reach - 1, 2)
      order by power(gx + v_l / 2.0 - v_pcx, 2) + power(gy + v_l / 2.0 - v_pcy, 2), gy, gx
    loop
      if automove_box_ok('space', v_here, s.id, c.gx, c.gy, v_l, v_l, v_fac, false)
         and not exists (select 1 from unnest(v_txa, v_tya, v_twa, v_tha) e(ex, ey, ew, eh)
                         where boxes_overlap(c.gx, c.gy, v_l, v_l, e.ex, e.ey, e.ew, e.eh)) then
        v_tx := c.gx; v_ty := c.gy; v_found := true;
        exit;
      end if;
    end loop;
    continue when not v_found;

    if v_live then
      v_txa := v_txa || v_tx; v_tya := v_tya || v_ty; v_twa := v_twa || v_l; v_tha := v_tha || v_l;
      insert into rt_space_orders (ship_id, system_id, x, y, reason, created_at, taken_at)
      values (s.id, v_here, round((v_tx + v_l / 2.0) * 200)::int, round((v_ty + v_l / 2.0) * 200)::int, 'supply', now(), null)
      on conflict (ship_id) do update set system_id = excluded.system_id, x = excluded.x, y = excluded.y,
                                          reason = excluded.reason, created_at = now(), taken_at = null;
      v_n := v_n + 1;
      continue;
    end if;

    v_path := automove_route('space', v_here, s.x, s.y, v_tx, v_ty, v_w, v_h, v_mr, v_fac, false);
    continue when jsonb_array_length(v_path) = 0;

    v_txa := v_txa || v_tx; v_tya := v_tya || v_ty; v_twa := v_twa || v_l; v_tha := v_tha || v_l;
    v_id := null;
    begin
      insert into auto_moves (owner_user_id, system_id, layer, ship_id, group_id, target_x, target_y, path,
                              step_range, member_idx, faction, label, status)
      values (r.owner_user_id, v_here, 'space', s.id, v_group, v_tx, v_ty, v_path, v_mr, v_n, v_fac,
              'К площадке сброса', 'active')
      returning id into v_id;
    exception when others then
      if sqlerrm not like '%в бою 2.0%' then raise; end if;
    end;
    if v_id is not null then v_new := v_new || v_id; end if;
    v_n := v_n + 1;
  end loop;

  if v_n = 0 then
    return 'blocked:У площадки сброса ' || coalesce(v_hname, v_here) || ' нет места или к ней нет пути';
  end if;

  foreach a in array v_new loop
    begin
      perform automove_step(a);
    exception when others then perform err_db('supply_fleet_to_pad', sqlstate, sqlerrm, true);
    end;
  end loop;
  return 'moving';
end $_$;


--
-- Name: supply_fleet_to_zone(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_fleet_to_zone(p_route_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  r record; cm record; v_fac text; v_side text; v_here text; v_hname text;
  v_grid int := game_setting_int('space_grid_cells', 150);
  v_zh int := game_setting_int('hyperspace_zone_height', 14);
  s record; v_w int; v_h int; v_l int; v_mr int; v_tx int; v_ty int; v_found boolean; v_live boolean;
  v_txa int[] := '{}'; v_tya int[] := '{}'; v_twa int[] := '{}'; v_tha int[] := '{}';
  v_y0 int; v_y1 int; v_mid int; v_d int; v_cx int; v_cy int; v_k int; v_rows int[];
  v_path jsonb; v_group uuid; v_new uuid[] := '{}'; v_id uuid; v_n int := 0; v_out int; a uuid;
begin
  select * into r from supply_routes where id = p_route_id;
  select * into cm from commanders where id = r.commander_id;
  if r.id is null or cm.id is null or cm.moving_to is not null or cm.current_system is null then return 'ready'; end if;
  v_here := cm.current_system;
  select p.faction into v_fac from profiles p where p.id = r.owner_user_id;
  select sy.name into v_hname from systems sy where sy.id = v_here;
  v_side := hyperspace_side(v_here, v_fac);

  -- живая орбита: корабли ведёт сервер боя
  v_live := exists (select 1 from ships sh where sh.commander_id = cm.id and sh.system_id = v_here
                     and not sh.in_transit and sh.carrier_ship_id is null and rt_obj_busy_2_0('ship', sh.id) is not null);

  select count(*)::int into v_out
  from ships sh join ship_types t on t.id = sh.ship_type
  where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null
    and not is_in_hyperspace_zone(sh.y, ship_box_h(t.width_cells, t.height_cells, sh.facing), v_side);
  if v_out = 0 then
    if r.zone_tries <> 0 then update supply_routes set zone_tries = 0 where id = r.id; end if;
    execute 'del' || 'ete from rt_space_orders o where o.ship_id in (select sh.id from ships sh where sh.commander_id = $1)' using cm.id;
    return 'ready';
  end if;

  if v_live then
    -- наш автоход из базы в живой орбите не сделает ни шага — снимаем, дальше ведёт сервер боя
    update auto_moves am set status = 'stopped', stop_reason = 'cancelled', updated_at = now()
     where am.status = 'active' and am.label = 'Выход к гиперлинии'
       and am.ship_id in (select sh.id from ships sh where sh.commander_id = cm.id);
    -- приказ ещё не забран или корабли ещё идут (до 4 минут после выдачи)
    if exists (select 1 from rt_space_orders o join ships sh on sh.id = o.ship_id
                where sh.commander_id = cm.id and o.system_id = v_here
                  and (o.taken_at is null and o.created_at > now() - interval '5 minutes'
                       or o.taken_at > now() - interval '4 minutes')) then
      return 'moving';
    end if;
  elsif exists (select 1 from auto_moves am join ships sh on sh.id = am.ship_id
                 where am.status = 'active' and sh.commander_id = cm.id and sh.system_id = v_here) then
    -- уже идут (наш автоход или приказ самого игрока) — ждём, чужой приказ не перебиваем
    return 'moving';
  end if;

  if r.zone_tries >= 3 then
    return 'blocked:Флот не может выйти к гиперлинии у ' || coalesce(v_hname, v_here)
      || ': путь к полосе прыжка перекрыт — выведи корабли к краю карты космоса и нажми «Продолжить»';
  end if;

  if not v_live then
    -- корабли заняты другим приказом прямо сейчас — попробуем на следующем такте
    begin
      perform 1 from ships sh where sh.commander_id = cm.id and sh.system_id = v_here
        and not sh.in_transit and sh.carrier_ship_id is null order by sh.id for update nowait;
    exception when lock_not_available then
      return 'moving';
    end;
  end if;

  update supply_routes set zone_tries = zone_tries + 1 where id = r.id;
  v_group := case when v_out > 1 then gen_random_uuid() end;

  -- ближние к полосе — первыми: им лучшие места
  for s in
    select sh.id, sh.x, sh.y, sh.facing, t.width_cells as tw, t.height_cells as th
    from ships sh join ship_types t on t.id = sh.ship_type
    where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null
      and not is_in_hyperspace_zone(sh.y, ship_box_h(t.width_cells, t.height_cells, sh.facing), v_side)
    order by case when v_side = 'top' then sh.y else -sh.y end, sh.x
  loop
    v_w := ship_box_w(s.tw, s.th, s.facing);
    v_h := ship_box_h(s.tw, s.th, s.facing);
    v_l := greatest(s.tw, s.th);                     -- в любом развороте корабль помещается в квадрат L×L
    select ss.move_range into v_mr from ship_stats(s.id) ss;
    v_mr := greatest(1, coalesce(v_mr, 1));
    -- ряды полосы, где квадрат целиком внутри; от середины полосы к краям
    if v_side = 'top' then v_y0 := 0; v_y1 := v_zh - v_l;
    else v_y0 := v_grid - v_zh; v_y1 := v_grid - v_l; end if;
    continue when v_y1 < v_y0;                       -- корабль длиннее полосы: такой не прыгнет ни в каком случае
    v_mid := (v_y0 + v_y1) / 2;
    select array_agg(g order by abs(g - v_mid), g) into v_rows from generate_series(v_y0, v_y1) g;

    -- место: напротив корабля, затем всё дальше вбок
    v_found := false;
    <<search>>
    for v_d in 0 .. least(v_grid, 80) loop
      foreach v_cy in array v_rows loop
        foreach v_cx in array array[least(greatest(0, s.x - v_d), v_grid - v_l), least(greatest(0, s.x + v_d), v_grid - v_l)] loop
          if automove_box_ok('space', v_here, s.id, v_cx, v_cy, v_l, v_l, v_fac, false)
             and not exists (select 1 from unnest(v_txa, v_tya, v_twa, v_tha) e(ex, ey, ew, eh)
                             where boxes_overlap(v_cx, v_cy, v_l, v_l, e.ex, e.ey, e.ew, e.eh)) then
            v_tx := v_cx; v_ty := v_cy; v_found := true;
            exit search;
          end if;
        end loop;
      end loop;
      exit when v_d > 0 and s.x - v_d <= 0 and s.x + v_d >= v_grid - v_l;
    end loop;
    continue when not v_found;

    if v_live then
      -- центр квадрата в метрах: сервер боя ведёт корабль туда в реальном времени
      v_txa := v_txa || v_tx; v_tya := v_tya || v_ty; v_twa := v_twa || v_l; v_tha := v_tha || v_l;
      insert into rt_space_orders (ship_id, system_id, x, y, reason, created_at, taken_at)
      values (s.id, v_here, round((v_tx + v_l / 2.0) * 200)::int, round((v_ty + v_l / 2.0) * 200)::int, 'supply', now(), null)
      on conflict (ship_id) do update set system_id = excluded.system_id, x = excluded.x, y = excluded.y,
                                          reason = excluded.reason, created_at = now(), taken_at = null;
      v_n := v_n + 1;
      continue;
    end if;

    v_path := automove_route('space', v_here, s.x, s.y, v_tx, v_ty, v_w, v_h, v_mr, v_fac, false);
    continue when jsonb_array_length(v_path) = 0;

    v_txa := v_txa || v_tx; v_tya := v_tya || v_ty; v_twa := v_twa || v_l; v_tha := v_tha || v_l;
    v_id := null;
    begin
      insert into auto_moves (owner_user_id, system_id, layer, ship_id, group_id, target_x, target_y, path,
                              step_range, member_idx, faction, label, status)
      values (r.owner_user_id, v_here, 'space', s.id, v_group, v_tx, v_ty, v_path, v_mr, v_n, v_fac,
              'Выход к гиперлинии', 'active')
      returning id into v_id;
    exception when others then
      -- орбиту как раз открыли (бой 2.0): автоход не нужен, на следующем такте приказ получит сервер боя
      if sqlerrm not like '%в бою 2.0%' then raise; end if;
    end;
    if v_id is not null then v_new := v_new || v_id; end if;
    v_n := v_n + 1;
  end loop;

  if v_n = 0 then
    return 'blocked:Флот не может выйти к гиперлинии у ' || coalesce((select name from systems where id = v_here), v_here)
      || ': в полосе прыжка нет свободного места или к ней нет пути — освободи место и нажми «Продолжить»';
  end if;

  -- первый шаг сразу — у кого есть очки действий
  foreach a in array v_new loop
    begin
      perform automove_step(a);
    exception when others then perform err_db('supply_fleet_to_zone', sqlstate, sqlerrm, true);
    end;
  end loop;
  return 'moving';
end $_$;


--
-- Name: supply_has_hub(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_has_hub(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from buildings b
    join building_types bt on bt.id = b.building_type_id
    join systems sy on sy.id = b.system_id
    join profiles p on p.id = p_user
    left join system_control sc on sc.system_id = b.system_id
    where bt.code = case when p.faction = 'republic' then 'rep_logistics' else 'cis_logistics' end
      and (b.completes_at is null or b.completes_at <= now())
      and b.faction = p.faction
      and sy.faction = p.faction
      and (b.owner_user_id = p_user or sc.controller_user_id = p_user));
$$;


--
-- Name: supply_hold_total(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_hold_total(p_commander_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(rc.amount), 0)::integer
  from ship_resource_cargo rc join ships s on s.id = rc.ship_id
  where s.commander_id = p_commander_id;
$$;


--
-- Name: supply_log(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_log(p_route_id uuid, p_system_id text, p_text text, p_moved integer) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into supply_route_log (route_id, system_id, text, moved)
  values (p_route_id, p_system_id, p_text, coalesce(p_moved, 0));
$$;


--
-- Name: supply_normalize_stops(jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_normalize_stops(p_stops jsonb, p_faction text, p_loop boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_n integer; st jsonb; a jsonb; v_out jsonb := '[]'::jsonb; v_acts jsonb;
  v_sys text; v_name text; v_fac text; v_deep boolean; v_op text; v_res text; v_mode text; v_amt integer;
  v_prev text; v_first text; v_total_acts integer := 0; i integer := 0; v_pname text;
begin
  if p_stops is null or jsonb_typeof(p_stops) <> 'array' then
    raise exception 'Не заданы остановки рейса';
  end if;
  v_n := jsonb_array_length(p_stops);
  if v_n < 2 then raise exception 'В рейсе нужно не меньше двух остановок'; end if;
  if v_n > 6 then raise exception 'В рейсе не больше шести остановок'; end if;

  for st in select value from jsonb_array_elements(p_stops) loop
    i := i + 1;
    if jsonb_typeof(st) <> 'object' then raise exception 'Остановка % задана неверно', i; end if;
    v_sys := st ->> 'system_id';
    v_name := null;
    select s.name, s.faction, s.is_deep_space into v_name, v_fac, v_deep from systems s where s.id = v_sys;
    if v_name is null then raise exception 'Остановка %: такой планеты нет', i; end if;
    if v_deep then raise exception 'Остановка %: в глубоком космосе склада нет', i; end if;
    if v_fac is distinct from p_faction then
      raise exception 'Остановка %: % — не планета твоей стороны', i, v_name;
    end if;
    if v_prev is not null then
      if v_prev = v_sys then raise exception 'Остановки % и % — одна и та же планета', i - 1, i; end if;
      if convoy_route(v_prev, v_sys, p_faction) is null then
        select s.name into v_pname from systems s where s.id = v_prev;
        raise exception 'Нет пути через миры своей стороны: % → %', v_pname, v_name;
      end if;
    else
      v_first := v_sys;
    end if;

    v_acts := '[]'::jsonb;
    if st ? 'actions' and jsonb_typeof(st -> 'actions') <> 'array' then
      raise exception 'Остановка %: действия заданы неверно', i;
    end if;
    if jsonb_array_length(coalesce(st -> 'actions', '[]'::jsonb)) > 10 then
      raise exception 'Остановка %: не больше десяти действий', i;
    end if;
    for a in select value from jsonb_array_elements(coalesce(st -> 'actions', '[]'::jsonb)) loop
      if jsonb_typeof(a) <> 'object' then raise exception 'Остановка %: действие задано неверно', i; end if;
      v_op := a ->> 'op'; v_res := a ->> 'resource'; v_mode := coalesce(a ->> 'mode', 'all');
      if v_op is null or v_op not in ('load', 'unload') then
        raise exception 'Остановка %: неизвестное действие', i;
      end if;
      if v_res is null or (v_res <> '*' and not exists (select 1 from resources r where r.id = v_res)) then
        raise exception 'Остановка %: неизвестный ресурс', i;
      end if;
      if v_op = 'load' and v_res = '*' then
        raise exception 'Остановка %: для погрузки выбери конкретный ресурс', i;
      end if;
      if (v_op = 'load' and v_mode not in ('all', 'amount'))
         or (v_op = 'unload' and v_mode not in ('all', 'amount', 'need')) then
        raise exception 'Остановка %: неверный режим действия', i;
      end if;
      v_amt := null;
      if v_mode = 'amount' then
        begin
          v_amt := (a ->> 'amount')::numeric::integer;
        exception when others then
          raise exception 'Остановка %: количество должно быть целым числом', i;
        end;
        if v_amt is null or v_amt < 1 or v_amt > 100000 then
          raise exception 'Остановка %: количество должно быть от 1 до 100000', i;
        end if;
      end if;
      v_acts := v_acts || jsonb_build_array(jsonb_build_object(
        'op', v_op, 'resource', v_res, 'mode', v_mode, 'amount', v_amt));
      v_total_acts := v_total_acts + 1;
    end loop;

    v_out := v_out || jsonb_build_array(jsonb_build_object('system_id', v_sys, 'actions', v_acts));
    v_prev := v_sys;
  end loop;

  if v_total_acts = 0 then raise exception 'Добавь хотя бы одно действие: погрузить или выгрузить'; end if;

  if p_loop and v_prev = v_first then
    raise exception 'В рейсе по кругу последняя остановка не должна совпадать с первой';
  end if;
  if p_loop and v_prev <> v_first and convoy_route(v_prev, v_first, p_faction) is null then
    raise exception 'Круг не замкнуть: от последней остановки нет пути к первой';
  end if;
  return v_out;
end $$;


--
-- Name: supply_pickup_live(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_pickup_live(p_stop jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from jsonb_array_elements(coalesce(p_stop -> 'actions', '[]'::jsonb)) a
                 join market_orders o on o.id = (a.value ->> 'order_id')::uuid
                  where a.value ->> 'op' = 'pickup' and o.status = 'reserved');
$$;


--
-- Name: supply_pickup_load(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_pickup_load(p_route_id uuid, p_here text, p_order_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; o record; l record; v_free integer; v_put integer; v_pay integer; v_sys text; v_buyer_fac text;
begin
  select * into r from supply_routes where id = p_route_id;
  select name into v_sys from systems where id = p_here;
  select * into o from market_orders where id = p_order_id for update;
  if not found or o.status <> 'reserved' or o.amount_left <= 0 then
    perform supply_log(r.id, p_here, 'Покупку уже не забрать — '
      || case coalesce(o.status, '')
           when 'expired' then 'бронь истекла, деньги вернулись'
           when 'cancelled' then 'планету захватили, деньги вернулись'
           when 'collected' then 'она уже вывезена'
           else 'брони больше нет' end || ' · ' || coalesce(v_sys, p_here), 0);
    return 0;
  end if;
  -- пока за бронью летит флот, рынок держит её до 6 ч сверх срока (market_expire_tick) — здесь то же окно
  if o.expires_at <= now() - interval '6 hours' then
    perform supply_log(r.id, p_here, 'Бронь истекла — деньги вернутся с ближайшим тактом рынка · ' || coalesce(v_sys, p_here), 0);
    return 0;
  end if;

  select * into l from market_lots where id = o.lot_id;
  if l.system_id is distinct from p_here then
    perform supply_log(r.id, p_here, 'Товар лежит не здесь — покупка не забрана', 0);
    return 0;
  end if;

  v_free := supply_fleet_free(r.commander_id, p_here);
  v_put := supply_put_cargo(r.commander_id, p_here, l.resource, least(o.amount_left, v_free));
  if v_put <= 0 then
    perform supply_log(r.id, p_here, 'Трюм полон — покупку не забрать · ' || coalesce(v_sys, p_here), 0);
    return 0;
  end if;

  v_pay := v_put * o.price_per_unit;
  update profiles set credits = credits + v_pay where id = l.seller_user_id;
  update market_orders
     set amount_left = amount_left - v_put,
         status = case when amount_left - v_put <= 0 then 'collected' else 'reserved' end
   where id = o.id;

  select faction into v_buyer_fac from profiles where id = r.owner_user_id;
  perform log_event(l.seller_user_id, l.seller_faction, l.system_id, 'market_paid',
                    l.resource, v_put, 'private', jsonb_build_object('credits', v_pay));
  perform log_event(r.owner_user_id, v_buyer_fac, l.system_id, 'market_collected',
                    l.resource, v_put, 'private', jsonb_build_object('route_id', r.id));
  perform supply_log(r.id, p_here, 'Покупка забрана: ' || v_put || ' ' || supply_res_gen(l.resource)
    || ' · ' || coalesce(v_sys, p_here)
    || case when v_put < o.amount_left
            then ' — не влезло ' || (o.amount_left - v_put) || ', остаток ждёт по брони' else '' end, v_put);
  return v_put;
end;
$$;


--
-- Name: supply_put_cargo(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_put_cargo(p_commander_id uuid, p_here text, p_res text, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_unit integer := game_setting_int('cargo_units_per_slot', 2);
  sh record; v_left integer := p_amount; v_fit integer;
begin
  if p_amount <= 0 then return 0; end if;
  for sh in
    select s.id, st.capacity - ship_load_used(s.id) as free_slots
    from ships s cross join lateral ship_stats(s.id) st
    where s.commander_id = p_commander_id and not s.in_transit and s.system_id = p_here
    order by s.id
  loop
    exit when v_left <= 0;
    v_fit := least(v_left, greatest(0, sh.free_slots) * v_unit);
    continue when v_fit <= 0;
    insert into ship_resource_cargo (ship_id, resource, amount)
    values (sh.id, p_res, v_fit)
    on conflict (ship_id, resource) do update
      set amount = ship_resource_cargo.amount + excluded.amount;
    v_left := v_left - v_fit;
  end loop;
  return p_amount - v_left;
end $$;


--
-- Name: supply_res_gen(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_res_gen(p_res text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_res
    when 'ore' then 'руды' when 'gas' then 'тибанны' when 'crystals' then 'кристаллов'
    when 'food' then 'продовольствия' when 'durasteel' then 'дюрастали'
    when 'cells' then 'топливных ячеек' when 'electronics' then 'электроники'
    else p_res end;
$$;


--
-- Name: supply_route_has_work(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_route_has_work(p_route_id uuid, p_commander_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; st jsonb; a jsonb; v_sys text; v_free integer; ti record; v_ctrl uuid;
  rc record; v_stock integer; v_want integer;
begin
  select * into r from supply_routes where id = p_route_id;
  if not found then return false; end if;
  v_free := commander_free_cargo(p_commander_id);

  for st in select value from jsonb_array_elements(r.stops) loop
    v_sys := st ->> 'system_id';
    for a in select value from jsonb_array_elements(coalesce(st -> 'actions', '[]'::jsonb)) loop
      if a ->> 'op' = 'load' then
        continue when v_free <= 0;
        select * into ti from supply_take_info(v_sys, a ->> 'resource', r.owner_user_id);
        if ti.can_take and ti.available > 0 then return true; end if;
      else
        v_ctrl := null;
        select sc.controller_user_id into v_ctrl from system_control sc where sc.system_id = v_sys;
        continue when v_ctrl is null;
        for rc in
          select x.resource as res
          from ship_resource_cargo x join ships s on s.id = x.ship_id
          where s.commander_id = p_commander_id
            and (a ->> 'resource' = '*' or x.resource = a ->> 'resource')
          group by x.resource
        loop
          v_stock := null;
          select ps.amount into v_stock from planet_stock ps
           where ps.system_id = v_sys and ps.resource = rc.res;
          v_stock := coalesce(v_stock, 0);
          if a ->> 'mode' = 'need' then
            v_want := null;
            select ru.want_min into v_want from supply_rules ru
             where ru.system_id = v_sys and ru.resource = rc.res and ru.set_by = v_ctrl;
            if coalesce(v_want, 0) - v_stock > 0 then return true; end if;
          elsif planet_stock_cap(v_sys) - v_stock > 0 then
            return true;
          end if;
        end loop;
      end if;
    end loop;
  end loop;
  return false;
end $$;


--
-- Name: supply_route_stall(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_route_stall(p_route_id uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_here text; v_fac text;
begin
  select * into r from supply_routes where id = p_route_id for update;
  if not found or r.status <> 'active' then return; end if;
  select coalesce(c.current_system, c.moving_from) into v_here from commanders c where c.id = r.commander_id;
  select faction into v_fac from profiles where id = r.owner_user_id;
  update supply_routes set status = 'stalled', last_note = p_note, updated_at = now() where id = p_route_id;
  perform supply_log(p_route_id, v_here, 'Рейс встал: ' || p_note, 0);
  perform log_event(r.owner_user_id, v_fac, v_here, 'supply_route_stalled',
                    r.name || ' — ' || p_note, 1, 'private',
                    jsonb_build_object('route_id', r.id, 'layer', 'space'));
end $$;


--
-- Name: supply_route_step(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_route_step(p_route_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; cm record; v_fac text; v_here text; v_target text; v_route text[]; v_n integer;
  v_moved integer; v_cb integer; v_unl integer; i integer := 0; v_deep boolean; v_hname text;
  v_tname text; v_err text; v_tfac text; v_loop boolean; v_zone text;
begin
  loop
    i := i + 1;
    exit when i > 6;

    select * into r from supply_routes where id = p_route_id for update;
    exit when not found or r.status <> 'active';

    select * into cm from commanders where id = r.commander_id;
    if cm.id is null or cm.user_id <> r.owner_user_id or not cm.unlocked then
      update supply_routes set status = 'stopped', last_note = 'Командир недоступен — рейс завершён',
                               updated_at = now() where id = r.id;
      perform supply_log(r.id, null, 'Командир недоступен — рейс завершён', 0);
      exit;
    end if;

    select faction into v_fac from profiles where id = r.owner_user_id;
    v_n := jsonb_array_length(r.stops);

    -- ----- в пути -----
    if cm.moving_to is not null then
      if cm.moving_to is distinct from r.expect_system then
        v_tname := null;
        select name into v_tname from systems where id = cm.moving_to;
        perform supply_route_stall(r.id, 'Флот оказался не там, где ждали (курс на '
          || coalesce(v_tname, cm.moving_to) || ') — проверь и нажми «Продолжить»');
        exit;
      end if;
      if cm.arrives_at is not null and cm.arrives_at <= now() then
        begin
          perform finish_commander_move(cm.id);
        exception when others then
          if sqlerrm like '%в бою 2.0%' or sqlerrm like '%под огнём%' then exit; end if;
          raise;
        end;
        continue;
      end if;
      exit;
    end if;

    v_here := cm.current_system;
    v_deep := null; v_hname := null;
    select s.is_deep_space, s.name into v_deep, v_hname from systems s where s.id = v_here;

    if v_here is distinct from r.expect_system then
      if coalesce(v_deep, false) then
        perform supply_route_stall(r.id, 'Флот перехвачен в глубоком космосе · ' || coalesce(v_hname, v_here));
      else
        perform supply_route_stall(r.id, 'Флот оказался не там, где ждали (сейчас у '
          || coalesce(v_hname, v_here) || ') — проверь и нажми «Продолжить»');
      end if;
      exit;
    end if;

    -- ----- у командира не осталось кораблей -----
    if not exists (select 1 from ships s where s.commander_id = cm.id and s.carrier_ship_id is null) then
      perform supply_route_stall(r.id, 'У командира не осталось кораблей');
      exit;
    end if;

    -- ----- корабли выходят из гиперпространства (не дольше 5 минут) -----
    if exists (select 1 from ships s where s.commander_id = cm.id
               and s.in_transit and s.carrier_ship_id is null) then
      if r.transit_wait_since is null then
        update supply_routes set transit_wait_since = now() where id = r.id;
      elsif r.transit_wait_since < now() - interval '5 minutes' then
        perform supply_route_stall(r.id, 'Корабли не могут выйти из гиперпространства у '
          || coalesce(v_hname, v_here) || ' — зона прыжка занята, освободи место и нажми «Продолжить»');
      end if;
      exit;
    elsif r.transit_wait_since is not null then
      update supply_routes set transit_wait_since = null where id = r.id;
    end if;

    -- ----- ожидание после пустого круга: стоим на месте, пока не появится работа -----
    if r.phase = 'waiting' then
      exit when r.wait_until is not null and r.wait_until > now();
      if supply_route_has_work(r.id, cm.id) then
        update supply_routes set phase = 'travel', wait_until = null,
                                 last_note = 'Появился груз — рейс продолжается', updated_at = now()
         where id = r.id;
        perform supply_log(r.id, v_here, 'Появился груз — рейс продолжается', 0);
        continue;
      end if;
      update supply_routes set wait_until = now() + interval '10 minutes' where id = r.id;
      exit;
    end if;

    -- ----- груз передан, разовый рейс окончен: флот возвращается к гиперлинии (sql/supply_pad.sql) -----
    if r.phase = 'returning' then
      v_zone := supply_fleet_to_zone(r.id);
      if v_zone = 'moving' then exit; end if;
      v_cb := supply_hold_total(cm.id);
      update supply_routes
         set status = 'stopped', phase = 'at_stop', zone_tries = 0, updated_at = now(),
             last_note = case when v_cb > 0 then 'Рейс выполнен — в трюме осталось ' || v_cb || ' ед.: склад полон'
                              when v_zone like 'blocked:%' then 'Рейс выполнен — флот остался у площадки'
                              else 'Рейс выполнен' end
       where id = r.id;
      perform supply_log(r.id, v_here, 'Рейс выполнен: доставлено ' || r.moved_total || ' ед.', 0);
      if v_cb > 0 then
        perform log_event(r.owner_user_id, v_fac, v_here, 'supply_cargo_left',
          coalesce(r.name, 'Рейс') || ' — в трюме осталось ' || v_cb || ' ед.: склад полон. Разгрузи или отвези в другое место',
          v_cb, 'private', jsonb_build_object('route_id', r.id, 'layer', 'space'));
      end if;
      exit;
    end if;

    if r.stop_index < 0 or r.stop_index >= v_n then
      update supply_routes set stop_index = 0, phase = 'travel' where id = r.id;
      continue;
    end if;
    v_target := r.stops -> r.stop_index ->> 'system_id';

    v_tfac := null; v_tname := null;
    select s.faction, s.name into v_tfac, v_tname from systems s where s.id = v_target;

    if r.order_id is not null
       and ((supply_stop_is_pickup(r.stops -> r.stop_index) and not supply_pickup_live(r.stops -> r.stop_index))
            or (v_tfac is distinct from v_fac and not supply_stop_is_pickup(r.stops -> r.stop_index))) then
      perform supply_log(r.id, v_here,
        case when supply_stop_is_pickup(r.stops -> r.stop_index) then 'Покупка закрыта — к продавцу не летим'
             else coalesce(v_tname, v_target) || ' больше не планета фракции — остановка пропущена' end, 0);
      if r.stop_index + 1 < v_n then
        update supply_routes set stop_index = r.stop_index + 1, phase = 'travel', updated_at = now() where id = r.id;
        continue;
      end if;
      update supply_routes
         set status = 'stopped', phase = 'at_stop',
             last_note = case when supply_hold_total(cm.id) > 0 then 'Рейс завершён — груз остался в трюме' else 'Рейс завершён' end,
             updated_at = now()
       where id = r.id;
      perform supply_log(r.id, v_here, 'Рейс завершён: дальше лететь некуда', 0);
      exit;
    end if;
    if v_tfac is distinct from v_fac and not supply_stop_is_pickup(r.stops -> r.stop_index) then
      perform supply_route_stall(r.id, 'Остановка ' || (r.stop_index + 1) || ' ('
        || coalesce(v_tname, v_target) || ') больше не планета фракции — измени рейс');
      exit;
    end if;

    -- ----- перелёт к остановке -----
    if r.phase = 'travel' then
      if v_here = v_target then
        update supply_routes set phase = 'at_stop', updated_at = now() where id = r.id;
        continue;
      end if;

      v_route := case when v_tfac is distinct from v_fac then convoy_route_to(v_here, v_target, v_fac)
                      else convoy_route(v_here, v_target, v_fac) end;
      if v_route is null or array_length(v_route, 1) < 2 then
        perform supply_route_stall(r.id, 'Нет пути через миры своей стороны: '
          || coalesce(v_hname, v_here) || ' → ' || coalesce(v_tname, v_target));
        exit;
      end if;

      -- флот вне полосы прыжка — сам выходит к гиперлинии (sql/supply_zone.sql), рейс ждёт
      v_zone := supply_fleet_to_zone(r.id);
      if v_zone like 'blocked:%' then
        perform supply_route_stall(r.id, substr(v_zone, 9));
        update supply_routes set zone_tries = 0 where id = r.id;
        exit;
      end if;
      if v_zone = 'moving' then
        if r.last_note is distinct from 'Флот выходит к гиперлинии · ' || coalesce(v_hname, v_here) then
          update supply_routes set last_note = 'Флот выходит к гиперлинии · ' || coalesce(v_hname, v_here),
                                   updated_at = now() where id = r.id;
          perform supply_log(r.id, v_here, 'Флот выходит к гиперлинии · ' || coalesce(v_hname, v_here), 0);
        end if;
        exit;
      end if;

      begin
        perform start_commander_move(cm.id, v_route[2]);
      exception when others then perform err_db('supply_route_step', sqlstate, sqlerrm, false);
        if sqlstate in ('40P01', '40001', '55P03') then raise; end if;
        v_err := sqlerrm;
        if v_err like '%притягивающем луче%' then
          update supply_routes set last_note = 'Корабль флота в притягивающем луче врага — прыжок, когда отпустят', updated_at = now()
           where id = r.id and last_note is distinct from 'Корабль флота в притягивающем луче врага — прыжок, когда отпустят';
          exit;
        end if;
        if v_err like 'Корабль под огнём%' or v_err like '%в бою 2.0%' then
          update supply_routes set last_note = 'Флот под огнём — прыжок, когда бой стихнет', updated_at = now()
           where id = r.id and last_note is distinct from 'Флот под огнём — прыжок, когда бой стихнет';
          exit;
        end if;
        if sqlstate = 'P0001' then
          perform supply_route_stall(r.id, v_err);
        else
          perform supply_log(r.id, v_here, 'Сбой прыжка: ' || v_err, 0);
          perform supply_route_stall(r.id, 'Сбой рейса — попробуй «Продолжить»');
        end if;
        exit;
      end;

      update supply_routes
         set expect_system = v_route[2], zone_tries = 0,
             last_note = 'Летит к ' || coalesce(v_tname, v_target),
             updated_at = now()
       where id = r.id;
      exit;
    end if;

    -- ----- на остановке -----
    if r.phase = 'at_stop' then
      -- груз меняют у площадки сброса: флот подходит к ней, потом погрузка и выгрузка (sql/supply_pad.sql)
      -- (только если есть что передать: погрузка, вывоз покупки или груз в трюме под выгрузку)
      if exists (select 1 from jsonb_array_elements(coalesce(r.stops -> r.stop_index -> 'actions', '[]'::jsonb)) x
                  where x.value ->> 'op' in ('load', 'pickup'))
         or (jsonb_array_length(coalesce(r.stops -> r.stop_index -> 'actions', '[]'::jsonb)) > 0
             and supply_hold_total(cm.id) > 0) then
        v_zone := supply_fleet_to_pad(r.id);
        if v_zone = 'moving' then
          if r.last_note is distinct from 'Флот идёт к площадке сброса · ' || coalesce(v_hname, v_here) then
            update supply_routes set last_note = 'Флот идёт к площадке сброса · ' || coalesce(v_hname, v_here),
                                     updated_at = now() where id = r.id;
            perform supply_log(r.id, v_here, 'Флот идёт к площадке сброса · ' || coalesce(v_hname, v_here), 0);
          end if;
          exit;
        end if;
        if v_zone like 'blocked:%' then
          perform supply_log(r.id, v_here, substr(v_zone, 9) || ' — груз передан с места', 0);
        end if;
        update supply_routes set zone_tries = 0 where id = r.id and zone_tries <> 0;
      end if;
      v_cb := supply_hold_total(cm.id);
      v_moved := supply_stop_actions(r.id, v_here);
      -- moved = погружено + выгружено, изменение трюма = погружено − выгружено
      v_unl := greatest(0, (v_moved - (supply_hold_total(cm.id) - v_cb)) / 2);

      update supply_routes
         set moved_total = moved_total + v_unl,
             moved_this_cycle = moved_this_cycle + v_moved,
             updated_at = now()
       where id = r.id
       returning * into r;

      if r.stop_index + 1 < v_n then
        update supply_routes set stop_index = r.stop_index + 1, phase = 'travel',
                                 last_note = case when v_moved > 0
                                                  then 'Погрузка и выгрузка: ' || v_moved || ' ед. · ' || v_hname
                                                  else last_note end
         where id = r.id;
        continue;
      end if;

      select x.loop into v_loop from supply_routes x where x.id = r.id;
      if not v_loop then
        update supply_routes set phase = 'returning', cycles = cycles + 1, zone_tries = 0,
                                 last_note = 'Флот возвращается к гиперлинии · ' || coalesce(v_hname, v_here),
                                 updated_at = now()
         where id = r.id;
        perform supply_log(r.id, v_here, 'Груз передан — флот возвращается к гиперлинии · ' || coalesce(v_hname, v_here), 0);
        continue;
      end if;

      if r.moved_this_cycle = 0 then
        update supply_routes
           set cycles = cycles + 1, stop_index = 0, moved_this_cycle = 0,
               idle_cycles = idle_cycles + 1, phase = 'waiting',
               wait_until = now() + interval '10 minutes',
               last_note = 'Круг без груза — ждём, пока появится груз', updated_at = now()
         where id = r.id;
        if r.idle_cycles = 0 then
          perform supply_log(r.id, v_here, 'Круг без груза — стоим и проверяем склады раз в 10 минут', 0);
        end if;
        exit;
      end if;

      update supply_routes
         set cycles = cycles + 1, stop_index = 0, moved_this_cycle = 0, idle_cycles = 0,
             phase = 'travel',
             last_note = 'Круг ' || (r.cycles + 1) || ' пройден · всего доставлено ' || r.moved_total || ' ед.',
             updated_at = now()
       where id = r.id;
      continue;
    end if;

    exit;
  end loop;
end $$;


--
-- Name: supply_stop_actions(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_stop_actions(p_route_id uuid, p_here text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; v_fac text; v_owner_name text; v_sys_name text; v_sys_fac text; v_stop jsonb; a jsonb;
  v_quiet boolean; v_moved integer := 0; ti record; v_free integer; v_amt integer; v_put integer;
  v_res text; v_have integer; v_want integer; v_stock integer; v_space integer; v_try integer;
  v_done integer; v_fit integer; v_ctrl uuid; v_rule record; v_need integer; sh record; v_left integer;
  v_any boolean; v_room integer;
begin
  select * into r from supply_routes where id = p_route_id;
  select faction, nickname into v_fac, v_owner_name from profiles where id = r.owner_user_id;
  select s.name, s.faction into v_sys_name, v_sys_fac from systems s where s.id = p_here;
  v_stop := r.stops -> r.stop_index;
  v_quiet := r.idle_cycles > 0;   -- повторные пустые круги не засоряют журнал

  if v_sys_fac is distinct from v_fac and not supply_stop_is_pickup(v_stop) then
    perform supply_log(r.id, p_here, 'Планета больше не наша — остановка пропущена · ' || v_sys_name, 0);
    return 0;
  end if;

  select sc.controller_user_id into v_ctrl from system_control sc where sc.system_id = p_here;

  for a in select value from jsonb_array_elements(coalesce(v_stop -> 'actions', '[]'::jsonb)) loop
    v_res := a ->> 'resource';

    -- ================= ЗАБРАТЬ ПОКУПКУ =================
    if a ->> 'op' = 'pickup' then
      v_moved := v_moved + supply_pickup_load(r.id, p_here, (a ->> 'order_id')::uuid);
      continue;
    end if;

    -- ================= ПОГРУЗКА =================
    if a ->> 'op' = 'load' then
      perform 1 from planet_stock ps where ps.system_id = p_here and ps.resource = v_res for update;
      select * into ti from supply_take_info(p_here, v_res, r.owner_user_id);
      v_free := supply_fleet_free(r.commander_id, p_here);
      v_amt := case when ti.can_take then ti.available else 0 end;
      if a ->> 'mode' = 'amount' then v_amt := least(v_amt, (a ->> 'amount')::integer); end if;
      v_amt := least(v_amt, v_free);

      -- не больше, чем примут склады дальше по рейсу (sql/supply_pad.sql): иначе флот стоит с полными трюмами
      if v_amt > 0 and not supply_stop_is_pickup(v_stop) then
        v_room := supply_unload_room(r.id, v_res);
        if v_room is not null and v_room < v_amt then
          if v_room <= 0 then
            if not v_quiet then
              perform supply_log(r.id, p_here, 'Не грузим ' || supply_res_gen(v_res)
                || ': склады назначения полны · ' || v_sys_name, 0);
            end if;
            continue;
          end if;
          if not v_quiet then
            perform supply_log(r.id, p_here, 'Берём ' || v_room || ' ' || supply_res_gen(v_res)
              || ' — больше склады назначения не примут · ' || v_sys_name, 0);
          end if;
          v_amt := v_room;
        end if;
      end if;

      if v_amt <= 0 then
        if not v_quiet then
          perform supply_log(r.id, p_here,
            'Нечего забрать: ' || lower(coalesce((select name from resources where id = v_res), v_res))
            || ' · ' || v_sys_name || ' — '
            || case when ti.can_take and ti.available > 0 and v_free <= 0 then 'трюм полон'
                    else coalesce(ti.reason, 'склад пуст') end, 0);
        end if;
        continue;
      end if;

      -- сначала в трюмы, потом со склада — ровно столько, сколько легло (половинки слотов не ломают погрузку)
      v_put := supply_put_cargo(r.commander_id, p_here, v_res, v_amt);
      if v_put <= 0 then
        if not v_quiet then
          perform supply_log(r.id, p_here, 'Трюм полон — ' || supply_res_gen(v_res) || ' не погрузить · ' || v_sys_name, 0);
        end if;
        continue;
      end if;
      perform take_planet_stock(p_here, v_res, v_put);
      v_amt := v_put;

      if ti.controller is distinct from r.owner_user_id then
        insert into supply_takes (system_id, resource, taker_user_id, owner_user_id, amount, route_id)
        values (p_here, v_res, r.owner_user_id, ti.controller, v_amt, r.id);
        perform log_event_digest(ti.controller, v_fac, 'supply_taken',
          'tk:' || p_here || ':' || v_res || ':' || r.owner_user_id::text, p_here,
          coalesce(v_owner_name, 'снабженец'), (select name from resources where id = v_res),
          v_amt, v_sys_name, true);
      end if;

      perform supply_log(r.id, p_here, 'Погружено ' || v_amt || ' ' || supply_res_gen(v_res) || ' · ' || v_sys_name, v_amt);
      v_moved := v_moved + v_amt;

    -- ================= РАЗГРУЗКА =================
    else
      if v_ctrl is null then
        if not v_quiet then
          perform supply_log(r.id, p_here, 'У планеты нет хозяина — выгрузка пропущена · ' || v_sys_name, 0);
        end if;
        continue;
      end if;

      v_any := false;
      for v_res in
        select rc.resource
        from ship_resource_cargo rc join ships s on s.id = rc.ship_id
        join resources rr on rr.id = rc.resource
        where s.commander_id = r.commander_id and s.system_id = p_here and not s.in_transit
          and (a ->> 'resource' = '*' or rc.resource = a ->> 'resource')
        group by rc.resource, rr.sort_order
        order by rr.sort_order
      loop
        v_any := true;
        select coalesce(sum(rc.amount), 0)::integer into v_have
        from ship_resource_cargo rc join ships s on s.id = rc.ship_id
        where s.commander_id = r.commander_id and s.system_id = p_here and not s.in_transit
          and rc.resource = v_res;

        select coalesce(ps.amount, 0) into v_stock from planet_stock ps
         where ps.system_id = p_here and ps.resource = v_res for update;
        v_stock := coalesce(v_stock, 0);

        v_want := v_have;
        if a ->> 'mode' = 'amount' then
          v_want := least(v_have, (a ->> 'amount')::integer);
        elsif a ->> 'mode' = 'need' then
          select * into v_rule from supply_rules ru
           where ru.system_id = p_here and ru.resource = v_res and ru.set_by = v_ctrl;
          v_need := greatest(0, coalesce(v_rule.want_min, 0) - v_stock);
          v_want := least(v_have, v_need);
          if v_want <= 0 then
            if not v_quiet then
              perform supply_log(r.id, p_here, 'Нужды нет: ' || supply_res_gen(v_res) || ' хватает · ' || v_sys_name, 0);
            end if;
            continue;
          end if;
        end if;
        continue when v_want <= 0;

        v_space := greatest(0, planet_stock_cap(p_here) - v_stock);
        v_try := least(v_want, v_space);
        v_done := 0;

        if v_try > 0 then
          v_left := v_try;
          for sh in
            select rc.ship_id, rc.amount
            from ship_resource_cargo rc join ships s on s.id = rc.ship_id
            where s.commander_id = r.commander_id and s.system_id = p_here and not s.in_transit
              and rc.resource = v_res
            order by rc.ship_id
          loop
            exit when v_left <= 0;
            v_fit := unload_resource_from_ship(sh.ship_id, v_res, least(v_left, sh.amount));
            v_done := v_done + v_fit;
            v_left := v_left - v_fit;
            exit when v_fit < least(v_left + v_fit, sh.amount);   -- склад упёрся в предел
          end loop;
        end if;

        if v_done > 0 then
          perform supply_log(r.id, p_here, 'Выгружено ' || v_done || ' ' || supply_res_gen(v_res) || ' · ' || v_sys_name, v_done);
          v_moved := v_moved + v_done;
          if v_ctrl is distinct from r.owner_user_id then
            perform log_event_digest(v_ctrl, v_fac, 'supply_delivered',
              'dl:' || p_here || ':' || v_res || ':' || r.owner_user_id::text, p_here,
              coalesce(v_owner_name, 'снабженец'), (select name from resources where id = v_res),
              v_done, v_sys_name, true);
          end if;
        end if;

        if v_want - v_done > 0 then
          perform supply_log(r.id, p_here,
            'Склад полон — ' || (v_want - v_done) || ' ' || supply_res_gen(v_res) || ' осталось в трюме · ' || v_sys_name, 0);
        end if;
      end loop;

      if not v_any and not v_quiet then
        perform supply_log(r.id, p_here,
          case when a ->> 'resource' = '*' then 'Трюм пуст — выгружать нечего'
               else 'Нечего выгружать: ' || supply_res_gen(a ->> 'resource') || ' в трюме нет' end
          || ' · ' || v_sys_name, 0);
      end if;
    end if;
  end loop;

  return v_moved;
end $$;


--
-- Name: supply_stop_is_pickup(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_stop_is_pickup(p_stop jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from jsonb_array_elements(coalesce(p_stop -> 'actions', '[]'::jsonb)) a
                  where a.value ->> 'op' = 'pickup');
$$;


--
-- Name: supply_take_info(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_take_info(p_system_id text, p_resource text, p_taker uuid) RETURNS TABLE(controller uuid, is_mine boolean, stock integer, available integer, can_take boolean, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_ctrl uuid; v_stock integer; ru record; v_taken integer; v_avail integer;
  v_sys_fac text; v_tk_fac text; v_ct_fac text; v_ok boolean;
begin
  select sc.controller_user_id into v_ctrl from system_control sc where sc.system_id = p_system_id;
  select coalesce(ps.amount, 0) into v_stock from planet_stock ps
   where ps.system_id = p_system_id and ps.resource = p_resource;
  v_stock := coalesce(v_stock, 0);

  if v_ctrl is null then
    return query select null::uuid, false, v_stock, 0, false, 'у планеты нет хозяина'::text; return;
  end if;
  if v_ctrl = p_taker then
    return query select v_ctrl, true, v_stock, v_stock, true,
      case when v_stock = 0 then 'склад пуст' end; return;
  end if;

  select s.faction into v_sys_fac from systems s where s.id = p_system_id;
  select p.faction into v_tk_fac from profiles p where p.id = p_taker;
  select p.faction into v_ct_fac from profiles p where p.id = v_ctrl;
  if v_tk_fac is null or v_tk_fac is distinct from v_sys_fac or v_tk_fac is distinct from v_ct_fac then
    return query select v_ctrl, false, v_stock, 0, false, 'чужая сторона'::text; return;
  end if;

  select * into ru from supply_rules r
   where r.system_id = p_system_id and r.resource = p_resource and r.set_by = v_ctrl;
  if not found or not ru.share then
    return query select v_ctrl, false, v_stock, 0, false, 'склад не отдаёт в сеть'::text; return;
  end if;

  select coalesce(sum(t.amount), 0)::integer into v_taken from supply_takes t
   where t.system_id = p_system_id and t.resource = p_resource
     and t.owner_user_id = v_ctrl and t.taken_at >= last_payout_at();

  v_avail := greatest(0, least(v_stock - ru.keep_min,
                               coalesce(ru.max_per_day - v_taken, 2147483647)));
  v_ok := ru.audience = 'faction' or exists (
    select 1 from supply_grants g
     where g.owner_user_id = v_ctrl and g.grantee_user_id = p_taker and g.status = 'active');

  return query select v_ctrl, false, v_stock, v_avail, v_ok,
    case when not v_ok then 'только доверенным'
         when v_avail > 0 then null
         when v_stock = 0 then 'склад пуст'
         when v_stock <= ru.keep_min then 'запас на минимуме'
         else 'дневной лимит исчерпан' end;
end $$;


--
-- Name: supply_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  rr record; v_claims text; v_sub text; v_quiet text; v_err text; v_state text;
begin
  if not pg_try_advisory_xact_lock(hashtext('supply_tick')) then return; end if;

  v_claims := current_setting('request.jwt.claims', true);
  v_sub    := current_setting('request.jwt.claim.sub', true);
  v_quiet  := current_setting('app.supply_quiet', true);

  for rr in
    select id, owner_user_id from supply_routes
    where status = 'active'
    order by updated_at
  loop
    begin
      -- от имени владельца (start_commander_move / unload_resource_from_ship смотрят auth.uid());
      -- app.supply_quiet глушит события прыжков и разгрузки
      perform set_config('request.jwt.claims',
        json_build_object('sub', rr.owner_user_id::text, 'role', 'authenticated')::text, true);
      perform set_config('request.jwt.claim.sub', rr.owner_user_id::text, true);
      perform set_config('app.supply_quiet', 'on', true);

      perform supply_route_step(rr.id);
    exception when others then perform err_db('supply_tick', sqlstate, sqlerrm, true);
      v_state := sqlstate;
      v_err := sqlerrm;
      if v_state not in ('40P01', '40001', '55P03') then
        begin
          perform set_config('app.supply_quiet', coalesce(v_quiet, ''), true);
          perform supply_log(rr.id, null, 'Сбой: ' || v_err, 0);
          perform supply_route_stall(rr.id, 'Сбой рейса — попробуй «Продолжить»');
        exception when others then perform err_db('supply_tick', sqlstate, sqlerrm, true);
          null;
        end;
      end if;
    end;
  end loop;

  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  perform set_config('app.supply_quiet', coalesce(v_quiet, ''), true);
end $$;


--
-- Name: supply_unload_room(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supply_unload_room(p_route_id uuid, p_res text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; v_n int; v_k int; v_i int; v_stop jsonb; a jsonb; v_sys text; v_seen text[] := '{}';
  v_any boolean := false; v_sum int := 0; v_ctrl uuid; v_stock int; v_room int; v_want int; v_hold int;
begin
  select * into r from supply_routes where id = p_route_id;
  if not found then return null; end if;
  v_n := jsonb_array_length(r.stops);
  for v_k in 1 .. greatest(0, v_n - 1) loop
    v_i := r.stop_index + v_k;
    if v_i >= v_n then
      exit when not r.loop;
      v_i := v_i - v_n;
    end if;
    v_stop := r.stops -> v_i;
    v_sys := v_stop ->> 'system_id';
    for a in select value from jsonb_array_elements(coalesce(v_stop -> 'actions', '[]'::jsonb)) loop
      continue when a ->> 'op' is distinct from 'unload';
      continue when not (a ->> 'resource' = '*' or a ->> 'resource' = p_res);
      continue when v_sys = any(v_seen);                 -- склад одной планеты считаем один раз
      v_any := true;
      v_seen := v_seen || v_sys;
      -- управляющий нужен только для «по нужде» (правило склада ставит он); склад принимает и без него
      v_ctrl := null;
      select sc.controller_user_id into v_ctrl from system_control sc where sc.system_id = v_sys;
      select coalesce(ps.amount, 0) into v_stock from planet_stock ps where ps.system_id = v_sys and ps.resource = p_res;
      v_stock := coalesce(v_stock, 0);
      v_room := greatest(0, planet_stock_cap(v_sys) - v_stock);
      if a ->> 'mode' = 'amount' then
        v_room := least(v_room, coalesce((a ->> 'amount')::int, 0));
      elsif a ->> 'mode' = 'need' then
        v_want := null;
        select ru.want_min into v_want from supply_rules ru
         where ru.system_id = v_sys and ru.resource = p_res and ru.set_by = v_ctrl;
        v_room := least(v_room, greatest(0, coalesce(v_want, 0) - v_stock));
      end if;
      v_sum := v_sum + v_room;
    end loop;
  end loop;
  if not v_any then return null; end if;
  -- то, что уже в трюме, тоже займёт место на складах
  select coalesce(sum(rc.amount), 0)::int into v_hold
  from ship_resource_cargo rc join ships s on s.id = rc.ship_id
  where s.commander_id = r.commander_id and rc.resource = p_res;
  return greatest(0, v_sum - v_hold);
end $$;


--
-- Name: sync_carried_system(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_carried_system() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update ships set system_id = new.system_id
  where carrier_ship_id = new.id and system_id is distinct from new.system_id;

  with recursive inside as (
    select id from unit_positions where carrier_ship_id = new.id
    union
    select u.id from unit_positions u join inside i on u.carrier_unit_id = i.id
  )
  update unit_positions u set system_id = new.system_id
  from inside i
  where u.id = i.id and u.system_id is distinct from new.system_id;

  return null;
end;
$$;


--
-- Name: system_hops(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_hops(p_from text, p_to text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  frontier text[] := array[p_from];
  visited  text[] := array[p_from];
  nxt text[];
  d integer := 0;
begin
  if p_from is null or p_to is null then return null; end if;
  if p_from = p_to then return 0; end if;

  while coalesce(array_length(frontier, 1), 0) > 0 and d < 12 loop
    d := d + 1;

    select coalesce(array_agg(distinct x.n), '{}')
      into nxt
    from (
      select case when h.system_a = any(frontier) then h.system_b else h.system_a end as n
      from hyperlanes h
      where h.system_a = any(frontier) or h.system_b = any(frontier)
    ) x
    join systems s on s.id = x.n
    where not s.is_deep_space
      and not (x.n = any(visited));

    if p_to = any(nxt) then return d; end if;

    visited := visited || nxt;
    frontier := nxt;
  end loop;

  return null;
end;
$$;


--
-- Name: take_build_resources(text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_build_resources(p_system_id text, p_cost jsonb, p_multiplier integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare k text;
begin
  if p_cost is null or p_cost = '{}'::jsonb then return; end if;

  for k in select jsonb_object_keys(p_cost) loop
    perform take_planet_stock(p_system_id, k,
                              (p_cost ->> k)::integer * greatest(1, p_multiplier));
  end loop;
end;
$$;


--
-- Name: take_planet_stock(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_planet_stock(p_system_id text, p_resource text, p_amount integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_have integer; v_name text;
begin
  if p_amount is null then raise exception 'Некорректное количество'; end if;
  if p_amount <= 0 then return; end if;

  select amount into v_have from planet_stock
  where system_id = p_system_id and resource = p_resource for update;

  if coalesce(v_have, 0) < p_amount then
    select name into v_name from resources where id = p_resource;
    raise exception 'На планете не хватает: % (нужно %, есть %)',
      coalesce(v_name, p_resource), p_amount, coalesce(v_have, 0);
  end if;

  update planet_stock set amount = amount - p_amount
  where system_id = p_system_id and resource = p_resource;
end;
$$;


--
-- Name: touch_presence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_presence() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Нужно войти в игру';
  end if;
  update profiles set last_seen_at = now()
  where id = auth.uid()
    and (last_seen_at is null or last_seen_at < now() - interval '60 seconds');
end;
$$;


--
-- Name: trade_post_price(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trade_post_price(p_resource text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(1, round(r.base_price * game_setting_int('trade_post_pct', 60) / 100.0 * (100 + ge_trade_mod()) / 100.0)::integer)
  from resources r where r.id = p_resource;
$$;


--
-- Name: transfer_block_ship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_block_ship(p_ship_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s record;
begin
  select * into s from ships where id = p_ship_id;
  if not found then return 'корабля больше нет'; end if;

  if s.carrier_ship_id is not null then return 'в ангаре носителя'; end if;
  if s.in_transit then return 'в гиперпространстве'; end if;
  if s.commander_id is not null and exists (
       select 1 from commanders where id = s.commander_id and moving_to is not null) then
    return 'командир в пути';
  end if;
  if s.commander_id is not null and exists (
       select 1 from supply_routes where commander_id = s.commander_id
         and status <> 'stopped') then
    return 'работает на рейсе снабжения';
  end if;
  if exists (select 1 from repair_orders r
             where not r.delivered
               and (r.ship_id = p_ship_id
                    or r.ship_id in (select f.id from ships f where f.carrier_ship_id = p_ship_id))) then
    return 'в ремонте или модернизации';
  end if;
  if exists (select 1 from transfer_ship_inside(p_ship_id) i
             join unit_positions c on c.id = i.id
             join unit_types ct on ct.id = c.unit_type
             where ct.is_hero or c.hero_id is not null) then
    return 'на борту одарённый — высади его';
  end if;
  return null;
end;
$$;


--
-- Name: transfer_block_unit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_block_unit(p_unit_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare u record; t record;
begin
  select * into u from unit_positions where id = p_unit_id;
  if not found then return 'юнита больше нет'; end if;
  select * into t from unit_types where id = u.unit_type;

  if t.is_hero or u.hero_id is not null then return 'одарённые не передаются'; end if;
  if u.training_until is not null then return 'на обучении'; end if;
  if u.transit_to is not null then return 'в пути'; end if;
  if u.carrier_ship_id is not null or u.carrier_unit_id is not null then return 'в транспорте'; end if;
  if exists (select 1 from repair_orders where unit_id = p_unit_id and not delivered) then
    return 'в ремонте';
  end if;
  if exists (select 1 from transfer_unit_inside(p_unit_id) i
             join unit_positions c on c.id = i.id
             join unit_types ct on ct.id = c.unit_type
             where ct.is_hero or c.hero_id is not null) then
    return 'внутри одарённый — высади его';
  end if;
  return null;
end;
$$;


--
-- Name: transfer_expire_old(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_expire_old() RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update troop_transfers set status = 'expired', resolved_at = now()
  where status = 'pending' and expires_at <= now();
$$;


--
-- Name: transfer_ship_inside(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_ship_inside(p_ship_id uuid) RETURNS TABLE(id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with recursive inside as (
    select u.id from unit_positions u where u.carrier_ship_id = p_ship_id
    union
    select c.id from unit_positions c join inside i on c.carrier_unit_id = i.id
  )
  select id from inside;
$$;


--
-- Name: transfer_snapshot(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_snapshot(p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r jsonb; u record; t record; s record; st record;
begin
  if p_kind = 'unit' then
    select * into u from unit_positions where id = p_id;
    if not found then return null; end if;
    select * into t from unit_types where id = u.unit_type;

    select jsonb_build_object(
      'type', u.unit_type, 'name', coalesce(u.hero_name, t.name),
      'image', coalesce(u.portrait, t.image),
      'hp', u.hp, 'max_hp', t.max_hp + coalesce(u.bonus_hp, 0),
      'vehicle', coalesce(t.is_vehicle, false), 'hero', coalesce(t.is_hero, false),
      'contents', coalesce((
        select jsonb_agg(jsonb_build_object('kind', 'unit', 'name', g.name,
                                            'image', g.image, 'count', g.n) order by g.n desc)
        from (select ct.name, ct.image, count(*)::integer n
              from transfer_unit_inside(p_id) i
              join unit_positions c on c.id = i.id
              join unit_types ct on ct.id = c.unit_type
              group by ct.name, ct.image) g), '[]'::jsonb),
      'resources', '[]'::jsonb)
    into r;
    return r;
  end if;

  select * into s from ships where id = p_id;
  if not found then return null; end if;
  select * into st from ship_types where id = s.ship_type;

  select jsonb_build_object(
    'type', s.ship_type, 'name', st.name, 'image', st.image,
    'hp', s.hp, 'max_hp', st.max_hp + coalesce(s.bonus_hp, 0),
    'fighter', coalesce(st.is_fighter, false),
    'contents', coalesce((
      select jsonb_agg(jsonb_build_object('kind', g.kind, 'name', g.name,
                                          'image', g.image, 'count', g.n)
                       order by g.ord, g.n desc, g.name)
      from (
        select x.kind, x.ord, x.name, x.image, sum(x.n)::integer n from (
          select 'fighter' kind, 1 ord, ft.name, ft.image, 1 n
          from ships f join ship_types ft on ft.id = f.ship_type
          where f.carrier_ship_id = p_id
          union all
          select case when ut.is_vehicle then 'vehicle' else 'unit' end,
                 case when ut.is_vehicle then 2 else 3 end,
                 coalesce(c.hero_name, ut.name), coalesce(c.portrait, ut.image), 1
          from transfer_ship_inside(p_id) i
          join unit_positions c on c.id = i.id
          join unit_types ut on ut.id = c.unit_type
          union all
          select 'unit', 3, ut.name, ut.image, sc.quantity
          from ship_cargo sc join unit_types ut on ut.id = sc.unit_type
          where sc.ship_id = p_id and sc.quantity > 0
        ) x group by x.kind, x.ord, x.name, x.image
      ) g), '[]'::jsonb),
    'resources', coalesce((
      select jsonb_agg(jsonb_build_object('name', coalesce(rs.name, rc.resource),
                                          'color', rs.color, 'amount', rc.amount)
                       order by rc.amount desc)
      from ship_resource_cargo rc left join resources rs on rs.id = rc.resource
      where rc.ship_id = p_id and rc.amount > 0), '[]'::jsonb))
  into r;
  return r;
end;
$$;


--
-- Name: transfer_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_summary(p_transfer_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with c as (
    select count(*) filter (where kind = 'ship')::integer s,
           count(*) filter (where kind = 'unit' and not coalesce((snapshot->>'vehicle')::boolean, false))::integer u,
           count(*) filter (where kind = 'unit' and coalesce((snapshot->>'vehicle')::boolean, false))::integer v
    from troop_transfer_items where transfer_id = p_transfer_id)
  select concat_ws(', ',
    case when s > 0 then ru_plural(s, 'корабль', 'корабля', 'кораблей') end,
    case when u > 0 then ru_plural(u, 'боец', 'бойца', 'бойцов') end,
    case when v > 0 then ru_plural(v, 'машина', 'машины', 'машин') end)
  from c;
$$;


--
-- Name: transfer_unit_inside(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_unit_inside(p_unit_id uuid) RETURNS TABLE(id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with recursive inside as (
    select u.id from unit_positions u where u.carrier_unit_id = p_unit_id
    union
    select c.id from unit_positions c join inside i on c.carrier_unit_id = i.id
  )
  select id from inside;
$$;


--
-- Name: treasury_add(text, integer, text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treasury_add(p_faction text, p_amount integer, p_kind text, p_user uuid, p_target uuid, p_system text, p_note text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_bal integer;
begin
  insert into faction_treasury (faction, credits) values (p_faction, p_amount)
  on conflict (faction) do update set credits = faction_treasury.credits + excluded.credits, updated_at = now()
  returning credits into v_bal;
  insert into treasury_log (faction, kind, amount, balance, user_id, target_user, system_id, note)
  values (p_faction, p_kind, p_amount, v_bal, p_user, p_target, p_system, p_note);
  return v_bal;
end;
$$;


--
-- Name: treasury_donate(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treasury_donate(p_amount integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_cr integer; v_min integer := event_setting_int('treasury_min_donate', 100);
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction, credits into v_fac, v_cr from profiles where id = v_me for update;
  if v_fac is null then raise exception 'Нет фракции'; end if;
  if p_amount is null or p_amount < v_min then raise exception 'Взнос — от % кр.', v_min; end if;
  if p_amount > 1000000 then raise exception 'Слишком большая сумма'; end if;
  if v_cr < p_amount then raise exception 'Не хватает кредитов: есть %', v_cr; end if;
  update profiles set credits = credits - p_amount where id = v_me;
  perform treasury_add(v_fac, p_amount, 'donate', v_me, null, null, null);
  perform log_event(v_me, v_fac, null, 'treasury_donate', null, p_amount, 'faction', null);
  return treasury_state();
end;
$$;


--
-- Name: treasury_grant(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treasury_grant(p_user uuid, p_amount integer, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_bal integer; v_to text; v_nick text; v_note text := nullif(btrim(coalesce(p_note, '')), '');
        v_min integer := event_setting_int('treasury_min_grant', 50);
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null or not faction_power(v_me, v_fac, 'treasury') then raise exception 'Казной распоряжается лидер и те, кому он это поручил'; end if;
  if p_user is null or p_user = v_me then raise exception 'Выбери другого игрока'; end if;
  select faction, nickname into v_to, v_nick from profiles where id = p_user;
  if v_to is distinct from v_fac then raise exception 'Игрок не из твоей фракции'; end if;
  if p_amount is null or p_amount < v_min then raise exception 'Выплата — от % кр.', v_min; end if;
  if v_note is not null and char_length(v_note) > 60 then raise exception 'Пометка — до 60 знаков'; end if;
  select credits into v_bal from faction_treasury where faction = v_fac for update;
  if coalesce(v_bal, 0) < p_amount then raise exception 'В казне только % кр.', greatest(coalesce(v_bal, 0), 0); end if;
  update profiles set credits = credits + p_amount where id = p_user;
  perform treasury_add(v_fac, -p_amount, 'grant', v_me, p_user, null, v_note);
  perform log_event(v_me, v_fac, null, 'treasury_grant', v_nick, p_amount, 'faction', jsonb_build_object('to', v_nick, 'note', v_note));
  perform log_event(p_user, v_fac, null, 'treasury_grant', coalesce(v_note, 'из казны фракции'), p_amount, 'private', jsonb_build_object('note', v_note));
  return treasury_state();
end;
$$;


--
-- Name: treasury_project(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treasury_project(p_project text, p_system text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; p treasury_projects; v_bal integer; v_sys record; v_ctrl uuid;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null or not faction_power(v_me, v_fac, 'treasury') then raise exception 'Казной распоряжается лидер и те, кому он это поручил'; end if;
  select * into p from treasury_projects where id = p_project and active;
  if not found then raise exception 'Такого проекта нет'; end if;
  select id, name, faction, coalesce(is_deep_space, false) deep into v_sys from systems where id = p_system;
  if not found or v_sys.faction is distinct from v_fac or v_sys.deep then raise exception 'Проект — только на планете своей фракции'; end if;
  select credits into v_bal from faction_treasury where faction = v_fac for update;
  if exists (select 1 from faction_effects where system_id = p_system and faction = v_fac and source = 'project:' || p.id and ends_at > now()) then
    raise exception '«%» на этой планете уже идёт', p.title;
  end if;
  if coalesce(v_bal, 0) < p.cost then raise exception 'В казне только % кр. — нужно %', greatest(coalesce(v_bal, 0), 0), p.cost; end if;
  insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at)
  values (v_fac, p.kind, p.value, p.title, 'project:' || p.id, p_system, now(), now() + make_interval(hours => p.hours));
  perform treasury_add(v_fac, -p.cost, 'project', v_me, null, p_system, p.title);
  perform log_event(v_me, v_fac, p_system, 'treasury_project', p.title, p.cost, 'faction', jsonb_build_object('project', p.id));
  select controller_user_id into v_ctrl from system_control where system_id = p_system;
  if v_ctrl is not null and v_ctrl <> v_me then
    perform log_event(v_ctrl, v_fac, p_system, 'treasury_project', p.title, p.cost, 'private', jsonb_build_object('project', p.id));
  end if;
  return treasury_state();
end;
$$;


--
-- Name: treasury_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treasury_state() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_spend boolean;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null then return jsonb_build_object('faction', null); end if;
  v_spend := faction_power(v_me, v_fac, 'treasury');
  return jsonb_build_object(
    'faction', v_fac, 'now', now(),
    'balance', coalesce((select credits from faction_treasury where faction = v_fac), 0),
    'can_spend', v_spend, 'is_leader', is_faction_leader(v_me, v_fac),
    'credits', (select credits from profiles where id = v_me),
    'min_donate', event_setting_int('treasury_min_donate', 100), 'min_grant', event_setting_int('treasury_min_grant', 50),
    'tax', (select coalesce(sum((l.funds->>'tax')::integer), 0) from faction_bills b join faction_laws l on l.id = b.law_id
            where b.faction = v_fac and b.status = 'active' and b.ends_at > now() and l.funds ? 'tax'),
    'debts', (select coalesce(jsonb_agg(jsonb_build_object('title', l.title, 'amount', (l.funds->>'end')::integer, 'at', b.ends_at) order by b.ends_at), '[]'::jsonb)
              from faction_bills b join faction_laws l on l.id = b.law_id
              where b.faction = v_fac and b.status = 'active' and b.ends_at > now() and l.funds ? 'end'),
    'projects', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'title', p.title, 'text', p.text, 'kind', p.kind, 'value', p.value,
                   'hours', p.hours, 'cost', p.cost) order by p.sort), '[]'::jsonb) from treasury_projects p where p.active),
    'planets', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'owner', pr.nickname, 'mine', sc.controller_user_id = v_me,
                   'running', (select coalesce(jsonb_agg(jsonb_build_object('project', substr(fe.source, 9), 'title', fe.title, 'ends', fe.ends_at)), '[]'::jsonb)
                               from faction_effects fe where fe.system_id = s.id and fe.faction = v_fac and fe.source like 'project:%' and fe.ends_at > now()))
                 order by (sc.controller_user_id = v_me) desc nulls last, s.name), '[]'::jsonb)
                from systems s left join system_control sc on sc.system_id = s.id left join profiles pr on pr.id = sc.controller_user_id
                where s.faction = v_fac and not coalesce(s.is_deep_space, false)),
    'members', case when v_spend then (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'nick', p.nickname) order by lower(p.nickname)), '[]'::jsonb)
                from profiles p where p.faction = v_fac and p.id <> v_me and p.nickname is not null) else '[]'::jsonb end,
    'log', (select coalesce(jsonb_agg(x order by (x->>'id')::bigint desc), '[]'::jsonb) from (
       select jsonb_build_object('id', t.id, 'at', t.at, 'kind', t.kind, 'amount', t.amount, 'balance', t.balance, 'by', a.nickname, 'to', b.nickname,
                'planet', s.name, 'note', t.note, 'n', t.n) x
       from treasury_log t left join profiles a on a.id = t.user_id left join profiles b on b.id = t.target_user left join systems s on s.id = t.system_id
       where t.faction = v_fac order by t.id desc limit 30) q));
end;
$$;


--
-- Name: treasury_tax(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treasury_tax(p_faction text, p_system text, p_income integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_pct integer; v_amt integer; v_bal integer; v_id bigint;
begin
  if p_faction is null or coalesce(p_income, 0) <= 0 then return 0; end if;
  select coalesce(sum((l.funds->>'tax')::integer), 0) into v_pct
  from faction_bills b join faction_laws l on l.id = b.law_id
  where b.faction = p_faction and b.status = 'active' and b.starts_at <= now() and b.ends_at > now() and l.funds ? 'tax';
  if v_pct <= 0 then return 0; end if;
  v_amt := round(p_income * least(v_pct, 50) / 100.0)::integer;
  if v_amt <= 0 then return 0; end if;
  insert into faction_treasury (faction, credits) values (p_faction, v_amt)
  on conflict (faction) do update set credits = faction_treasury.credits + excluded.credits, updated_at = now()
  returning credits into v_bal;
  update treasury_log set amount = amount + v_amt, balance = v_bal, n = n + 1, at = now()
   where id = (select id from treasury_log where faction = p_faction and kind = 'tax' and at > now() - interval '30 minutes' order by at desc limit 1)
  returning id into v_id;
  if v_id is null then
    insert into treasury_log (faction, kind, amount, balance, note) values (p_faction, 'tax', v_amt, v_bal, v_pct || '%');
  end if;
  return v_amt;
end;
$$;


--
-- Name: trench_return_fire(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trench_return_fire(p_defender uuid, p_attacker uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d record; dt record; a record; att record; ds record;
        v_gap integer; v_chance integer; v_dmg integer; v_hp integer;
begin
  if p_defender is null or p_attacker is null then return null; end if;
  if not unit_in_trench(p_defender) then return null; end if;

  select * into d from unit_positions where id = p_defender;
  if not found then return null; end if;
  select * into a from unit_positions where id = p_attacker;
  if not found then return null; end if;
  if d.hp <= 0 or a.hp <= 0 or a.x is null or d.x is null then return null; end if;

  select * into dt from unit_types where id = d.unit_type;
  select * into att from unit_types where id = a.unit_type;
  if coalesce(dt.weapon_range, 0) <= 0 or coalesce(dt.damage, 0) <= 0 then return null; end if;

  select * into ds from unit_stats(p_defender);
  v_gap := box_gap(d.x, d.y, dt.width_cells, dt.height_cells, a.x, a.y, att.width_cells, att.height_cells);
  if v_gap > ds.weapon_range then return null; end if;

  perform reveal_unit(p_defender);

  v_chance := greatest(5, least(95, ds.accuracy - greatest(0, att.evasion + coalesce(a.bonus_evasion, 0))));
  if floor(random() * 100) >= v_chance then
    perform duel_log('ground', p_defender, p_attacker, false, 0, false);
    return 0;
  end if;

  v_dmg := greatest(1, round(ds.damage * damage_multiplier(dt.hull_class, att.hull_class))::integer);
  v_dmg := greatest(1, v_dmg);
  v_dmg := greatest(1, round(v_dmg * (100 - structure_cover(p_attacker)) / 100.0)::integer);
  v_dmg := cap_hero_damage(p_attacker, v_dmg);

  update unit_positions set hp = greatest(0, hp - v_dmg) where id = p_attacker returning hp into v_hp;

  perform duel_log('ground', p_defender, p_attacker, true, v_dmg, v_hp <= 0);

  if v_hp > 0 then
    null;
  else
    null;
    perform record_hero_kill(p_defender, a.unit_type, a.faction, a.owner_user_id, a.system_id);
    delete from unit_positions where id = p_attacker;
  end if;
  return v_dmg;
end;
$$;


--
-- Name: tutorial_capital(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_capital(p_faction text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_faction when 'republic' then 'coruscant' when 'cis' then 'raxus' end;
$$;


--
-- Name: tutorial_eval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_eval(p_user uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare st record; s record; v_ok boolean := false; v_since timestamptz;
begin
  select * into st from tutorial_state where user_id = p_user for update;
  if not found or st.status <> 'active' or st.step_done then return; end if;

  select * into s from tutorial_steps where ord = st.step_ord;
  if not found or s.check_kind = 'ui' then return; end if;

  if s.check_kind = 'event' then
    -- Событие считаем с момента, когда выполнен ПРЕДЫДУЩИЙ шаг, а не когда
    -- игрок забрал за него награду. Перелёт идёт минуту: флот успевал
    -- прибыть, пока игрок читал наставника, и шаг «В пути» больше не
    -- закрывался никогда.
    select max(g.created_at) into v_since
    from game_events g
    join tutorial_steps ps on ps.ord = st.step_ord - 1
    where g.user_id = p_user and g.type = 'tutorial_done'
      and g.subject = ps.title and g.created_at >= st.started_at;
    v_since := least(st.step_since, coalesce(v_since, st.step_since));

    v_ok := exists (select 1 from game_events g
                    where g.user_id = p_user and g.type = s.check_key
                      and g.created_at >= v_since);
  else
    v_ok := case s.check_key
      when 'request_planet' then
        exists (select 1 from planet_requests where user_id = p_user)
        or exists (select 1 from system_control where controller_user_id = p_user)
      when 'ship_assigned' then
        exists (select 1 from ships where owner_user_id = p_user
                and commander_id is not null and carrier_ship_id is null)
      when 'cargo_loaded' then
        exists (select 1 from ship_cargo sc join ships sh on sh.id = sc.ship_id
                where sh.owner_user_id = p_user and sc.quantity > 0)
        or exists (select 1 from unit_positions u join ships sh on sh.id = u.carrier_ship_id
                   where sh.owner_user_id = p_user)
      when 'planet_owned' then
        exists (select 1 from system_control where controller_user_id = p_user)
      when 'barracks_built' then
        exists (select 1 from buildings b join building_types bt on bt.id = b.building_type_id
                where b.owner_user_id = p_user and bt.code in ('rep_barracks', 'cis_droid')
                  and (b.completes_at is null or b.completes_at <= now()))
      when 'recruited' then
        exists (select 1 from unit_orders o where o.owner_user_id = p_user and o.delivered)
      when 'settlement_guard' then
        -- Своя пехота в зоне поселения своей же планеты: ровно то, что
        -- жители засчитывают как охрану
        exists (select 1 from unit_positions u
                join unit_types ut on ut.id = u.unit_type
                join system_control sc on sc.system_id = u.system_id
                where u.owner_user_id = p_user and sc.controller_user_id = p_user
                  and u.layer = 'ground' and u.x is not null and u.hp > 0
                  and not ut.is_vehicle
                  and is_in_settlement_zone(u.x, u.y))
      when 'economy_built' then
        exists (select 1 from buildings b join building_types bt on bt.id = b.building_type_id
                where b.owner_user_id = p_user and bt.produces_resource is not null
                  and (b.completes_at is null or b.completes_at <= now()))
      when 'target_hit' then
        (st.meta ->> 'target_id') is null
        or not exists (select 1 from unit_positions u
                       where u.id = (st.meta ->> 'target_id')::uuid and u.hp >= 60)
      else false end;
  end if;

  if v_ok then
    update tutorial_state set step_done = true where user_id = p_user;
    perform log_event(p_user, (select faction from profiles where id = p_user), null,
                      'tutorial_done', s.title, 1, 'private',
                      jsonb_build_object('tutorial', true));
  end if;
end;
$$;


--
-- Name: tutorial_fill(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_fill(p_text text, p_faction text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select replace(replace(replace(replace(replace(replace(coalesce(p_text, ''),
    '{capital_gen}',   case p_faction when 'republic' then 'Корусанта' else 'Раксуса' end),
    '{capital}',       case p_faction when 'republic' then 'Корусант' else 'Раксус' end),
    '{ship}',          case p_faction when 'republic' then 'Акламатор' else 'Щедрый' end),
    '{troops}',        case p_faction when 'republic' then 'клонов' else 'боевых дроидов' end),
    '{barracks_name}', case p_faction when 'republic' then 'Казарма' else 'Завод дроидов' end),
    '{barracks}',      case p_faction when 'republic' then 'казарму' else 'завод дроидов' end);
$$;


--
-- Name: tutorial_focus(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_focus(p_user uuid, p_faction text, p_meta jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cap text := tutorial_capital(p_faction);
  v_ship jsonb; v_ship_sys text; v_ship_transit boolean;
  v_cmd jsonb; v_cmd_sys text;
  v_target jsonb; v_inf jsonb; v_barr integer;
  v_planet text; v_from text; v_nb text; v_troops text;
begin
  -- Всё необязательное собираем в jsonb: у незаполненной записи plpgsql
  -- нельзя даже спросить поле, а шаги курса видят данные постепенно
  if (p_meta ->> 'ship_id') is not null then
    select jsonb_build_object('id', s.id, 'system', s.system_id, 'in_transit', s.in_transit,
                              'x', s.x, 'y', s.y, 'assigned', s.commander_id is not null,
                              'w', ship_box_w(t.width_cells, t.height_cells, s.facing),
                              'h', ship_box_h(t.width_cells, t.height_cells, s.facing),
                              'in_jump_zone', not s.in_transit and is_in_hyperspace_zone(s.y,
                                  ship_box_h(t.width_cells, t.height_cells, s.facing),
                                  hyperspace_side(s.system_id, s.faction)),
                              'in_drop', not s.in_transit and is_in_orbital_drop(s.x, s.y,
                                  ship_box_w(t.width_cells, t.height_cells, s.facing),
                                  ship_box_h(t.width_cells, t.height_cells, s.facing)) is not null),
           s.system_id, s.in_transit
      into v_ship, v_ship_sys, v_ship_transit
    from ships s join ship_types t on t.id = s.ship_type
    where s.id = (p_meta ->> 'ship_id')::uuid;
  end if;

  select jsonb_build_object('id', c.id, 'system', c.current_system, 'moving_to', c.moving_to,
                            'arrives_at', c.arrives_at),
         c.current_system
    into v_cmd, v_cmd_sys
  from commanders c where c.user_id = p_user and c.unlocked
  order by c.slot_index limit 1;

  if (p_meta ->> 'target_id') is not null then
    select jsonb_build_object('system', u.system_id, 'x', u.x, 'y', u.y, 'hp', u.hp)
      into v_target
    from unit_positions u where u.id = (p_meta ->> 'target_id')::uuid;
  end if;

  -- Своя планета: выданная по ходу курса, иначе самая свежая
  select sc.system_id into v_planet from system_control sc
  where sc.controller_user_id = p_user
  order by (sc.system_id = p_meta ->> 'planet_id') desc nulls last,
           (select max(g.created_at) from game_events g
             where g.user_id = p_user and g.type = 'planet_granted'
               and g.system_id = sc.system_id) desc nulls last,
           sc.system_id
  limit 1;

  -- Куда прыгать: соседняя планета своей фракции; своя или запрошенная —
  -- в приоритете, тогда бойцы окажутся дома
  v_from := coalesce(case when coalesce(v_ship_transit, false) then null else v_ship_sys end,
                     v_cmd_sys, v_cap);
  select s.id into v_nb
  from hyperlanes h
  join systems s on s.id = case when h.system_a = v_from then h.system_b else h.system_a end
  where (h.system_a = v_from or h.system_b = v_from)
    and not s.is_deep_space and s.faction = p_faction
  order by exists (select 1 from system_control sc
                   where sc.system_id = s.id and sc.controller_user_id = p_user) desc,
           exists (select 1 from planet_requests r
                   where r.system_id = s.id and r.user_id = p_user and r.status = 'pending') desc,
           s.name
  limit 1;

  select u.system_id into v_troops from unit_positions u
  where u.owner_user_id = p_user and u.layer = 'ground' and u.x is not null and u.hp > 0
  order by (u.system_id = v_planet) desc nulls last, u.updated_at desc nulls last limit 1;

  if v_planet is not null then
    select b.slot_index into v_barr
    from buildings b join building_types bt on bt.id = b.building_type_id
    where b.system_id = v_planet and bt.code in ('rep_barracks', 'cis_droid')
    order by (b.owner_user_id = p_user) desc nulls last, b.built_at limit 1;

    select jsonb_build_object('id', u.id, 'x', u.x, 'y', u.y) into v_inf
    from unit_positions u join unit_types ut on ut.id = u.unit_type
    where u.system_id = v_planet and u.owner_user_id = p_user and u.layer = 'ground'
      and u.x is not null and u.hp > 0 and not ut.is_vehicle
    order by abs(u.x - 70) + abs(u.y - 70) limit 1;
  end if;

  return jsonb_build_object(
    'capital', v_cap,
    'capital_name', (select name from systems where id = v_cap),
    'ship', v_ship,
    'commander', v_cmd,
    'neighbor', v_nb,
    'neighbor_name', (select name from systems where id = v_nb),
    'troops_system', v_troops,
    'troops_name', (select name from systems where id = v_troops),
    'target', v_target,
    'planet', v_planet,
    'planet_name', (select name from systems where id = v_planet),
    'planet_resources', (select jsonb_build_array(primary_resource, secondary_resource)
                         from systems where id = v_planet),
    'barracks_slot', v_barr,
    'infantry', v_inf);
end;
$$;


--
-- Name: tutorial_give_ship(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_give_ship(p_user uuid, p_faction text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_type text; v_cap text := tutorial_capital(p_faction); v_id uuid; t record;
begin
  v_type := case p_faction when 'republic' then 'acclamator' else 'munificent' end;
  select * into t from ship_types where id = v_type;
  insert into ships (system_id, ship_type, owner_user_id, faction, x, y, hp, facing, in_transit)
  values (v_cap, v_type, p_user, p_faction, 0, 0, t.max_hp, 0, true)
  returning id into v_id;
  perform place_ship_in_hyperspace(v_id, v_cap);
  return v_id;
end;
$$;


--
-- Name: tutorial_give_troops(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_give_troops(p_user uuid, p_faction text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_type text; v_cap text := tutorial_capital(p_faction); t record; c record; n integer := 0; z record;
begin
  v_type := case p_faction when 'republic' then 'rep_dc15a' else 'cis_b1' end;
  select * into t from unit_types where id = v_type;
  select * into z from deploy_zones where system_id = v_cap order by zone_index limit 1;

  for c in select * from free_deploy_cells_internal(v_cap, coalesce(z.x, 0) + 2, coalesce(z.y, 0) + 2) limit 6 loop
    insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type,
                                quantity, hp, ap, ap_updated_at)
    values (v_cap, 'ground', c.x, c.y, p_user, p_faction, v_type, 1, t.max_hp, 2, now());
    n := n + 1;
  end loop;
  return n;
end;
$$;


--
-- Name: tutorial_restart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_restart(p_user uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into tutorial_state (user_id) values (p_user)
  on conflict (user_id) do update set status = 'active', step_ord = 1, step_since = now(),
    step_done = false, meta = '{}'::jsonb, started_at = now(), finished_at = null;
$$;


--
-- Name: tutorial_spawn_target(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_spawn_target(p_user uuid, p_since timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_sys text; u record; c record;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
  v_r integer; v_zx integer; v_zy integer; v_id uuid;
begin
  select g.system_id into v_sys from game_events g
  where g.user_id = p_user and g.type = 'unit_deployed' and g.created_at >= p_since
  order by g.created_at desc limit 1;
  if v_sys is null then return null; end if;

  select * into u from unit_positions
  where owner_user_id = p_user and system_id = v_sys and x is not null and layer = 'ground'
  order by updated_at desc nulls last limit 1;
  if not found then return null; end if;

  select greatest(12, coalesce(max((coalesce(t.weapon_range, 0) + coalesce(g.bonus_range, 0)) * 3), 0) + 4) into v_r
  from unit_positions g join unit_types t on t.id = g.unit_type
  where g.system_id = v_sys and g.layer = 'ground' and g.x is not null and g.hp > 0 and g.faction <> 'marauder';
  select z.x + z.size / 2, z.y + z.size / 2 into v_zx, v_zy from settlement_zone_box() z;

  for c in
    select q.cx, q.cy
    from (select u.x + dx as cx, u.y + dy as cy, greatest(abs(dx), abs(dy)) as r
          from generate_series(-(v_r + 10), v_r + 10) dx, generate_series(-(v_r + 10), v_r + 10) dy
          where greatest(abs(dx), abs(dy)) between v_r and v_r + 10) q
    where q.cx >= 2 and q.cy >= 2 and q.cx < v_grid - 2 and q.cy < v_grid - 2
      and not is_in_settlement_zone(q.cx, q.cy)
      and not exists (select 1 from unit_positions g join unit_types t on t.id = g.unit_type
                      where g.system_id = v_sys and g.layer = 'ground' and g.x is not null and g.hp > 0 and g.faction <> 'marauder'
                        and greatest(abs(g.x - q.cx), abs(g.y - q.cy)) <= (coalesce(t.weapon_range, 0) + coalesce(g.bonus_range, 0)) * 3 + 3)
      and not exists (select 1 from field_structures s join structure_types st on st.id = s.type_id
                      where s.system_id = v_sys and st.kind = 'turret'
                        and greatest(abs(s.x - q.cx), abs(s.y - q.cy)) <= coalesce(st.radius, 0) * 3 + 3)
    order by greatest(abs(q.cx - v_zx), abs(q.cy - v_zy)) <= 42, q.r,
             (q.cx - v_zx) * (q.cx - v_zx) + (q.cy - v_zy) * (q.cy - v_zy), q.cx, q.cy
  loop
    continue when not is_ground_box_free(v_sys, c.cx, c.cy, 1, 1, null);
    insert into unit_positions (system_id, layer, x, y, owner_user_id, faction, unit_type, quantity, hp)
    values (v_sys, 'ground', c.cx, c.cy, null, 'marauder', 'marauder', 1, 60)
    returning id into v_id;
    return v_id;
  end loop;
  return null;
end;
$$;


--
-- Name: tutorial_ui(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tutorial_ui(p_key text, p_system text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); st record; s record; v_faction text;
begin
  if v_me is null then return false; end if;
  select * into st from tutorial_state where user_id = v_me for update;
  if not found or st.status <> 'active' or st.step_done then return false; end if;
  select * into s from tutorial_steps where ord = st.step_ord;
  if s.check_kind <> 'ui' or s.check_key <> p_key then return false; end if;

  if p_key = 'capital' then
    select faction into v_faction from profiles where id = v_me;
    if p_system is distinct from tutorial_capital(v_faction) then return false; end if;
  elsif p_key in ('my_planet', 'settlement') then
    if not exists (select 1 from system_control
                   where system_id = p_system and controller_user_id = v_me) then
      return false;
    end if;
  end if;

  -- Осмотр игрок видит сам, в ленту его не пишем — там и так людно
  update tutorial_state set step_done = true where user_id = v_me;
  return true;
end;
$$;


--
-- Name: unit_in_trench(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unit_in_trench(p_unit_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from unit_positions u
    join unit_types ut on ut.id = u.unit_type
    join field_structures s on s.system_id = u.system_id and s.faction = u.faction
                            and s.completes_at <= now()
    join structure_types st on st.id = s.type_id and st.kind = 'trench'
    where u.id = p_unit_id and u.layer = 'ground' and u.x is not null
      and not (st.infantry_only and ut.is_vehicle)
      and boxes_overlap(u.x, u.y, ut.width_cells, ut.height_cells, s.x, s.y, s.w, s.h));
$$;


--
-- Name: unit_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unit_stats(p_unit_id uuid) RETURNS TABLE(max_hp integer, damage integer, vision_range integer, move_range integer, weapon_range integer, accuracy integer, evasion integer)
    LANGUAGE sql STABLE
    AS $$
  select t.max_hp + u.bonus_hp,
         t.damage + u.bonus_damage,
         t.vision_range + u.bonus_vision,
         greatest(1, t.move_range + u.bonus_move),
         t.weapon_range + u.bonus_range,
         greatest(1, t.accuracy + u.bonus_accuracy),
         greatest(0, t.evasion + u.bonus_evasion)
  from unit_positions u join unit_types t on t.id = u.unit_type
  where u.id = p_unit_id;
$$;


--
-- Name: unit_total_slots(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unit_total_slots(p_unit_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select coalesce(t.slot_size, 1)
       + coalesce((
           select sum(coalesce(it.slot_size, 1))
           from unit_positions inner_u
           join unit_types it on it.id = inner_u.unit_type
           where inner_u.carrier_unit_id = p_unit_id
         ), 0)
  from unit_positions u
  join unit_types t on t.id = u.unit_type
  where u.id = p_unit_id;
$$;


--
-- Name: unload_from_ship(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unload_from_ship(p_ship_id uuid, p_unit_type text, p_quantity integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  s record; t record; ut record;
  v_sys_faction text;
  v_have integer; v_unit uuid;
  v_placed integer := 0;
  cell record;
begin
  if v_user_id is null then raise exception 'Не авторизован'; end if;
  if p_quantity is null or p_quantity < 1 then raise exception 'Некорректное количество'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user_id then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  select * into t from ship_types where id = s.ship_type;
  select * into ut from unit_types where id = p_unit_type;
  if not found or ut.is_vehicle or ut.is_hero then
    raise exception 'Технику и героев высаживают по одному';
  end if;

  select faction into v_sys_faction from systems where id = s.system_id;
  if v_sys_faction is distinct from s.faction then
    raise exception 'На вражеской планете высадка идёт поштучно, в полосу вторжения';
  end if;

  if is_in_orbital_drop(s.x, s.y,
       ship_box_w(t.width_cells, t.height_cells, s.facing),
       ship_box_h(t.width_cells, t.height_cells, s.facing)) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса';
  end if;

  select count(*) into v_have from unit_positions
  where carrier_ship_id = p_ship_id and unit_type = p_unit_type;
  if v_have < p_quantity then raise exception 'В трюме столько нет'; end if;

  for cell in select * from free_deploy_cells_internal(s.system_id, 0, 0) loop
    exit when v_placed >= p_quantity;

    select id into v_unit from unit_positions
    where carrier_ship_id = p_ship_id and unit_type = p_unit_type
    order by coalesce(cardinality(upgrades), 0) desc, hp desc, id
    limit 1
    for update;
    exit when v_unit is null;

    if is_ground_box_free(s.system_id, cell.x, cell.y, 1, 1, null) then
      update unit_positions
      set x = cell.x, y = cell.y, carrier_ship_id = null, system_id = s.system_id
      where id = v_unit;

      perform log_event(v_user_id, s.faction, s.system_id, 'unit_deployed', p_unit_type, 1, 'private',
                        jsonb_build_object('unit_id', v_unit, 'x', cell.x, 'y', cell.y));
      v_placed := v_placed + 1;
    end if;
    v_unit := null;
  end loop;

  if v_placed = 0 then raise exception 'В зонах высадки нет свободного места'; end if;

  return v_placed;
end;
$$;


--
-- Name: unload_resource_from_ship(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unload_resource_from_ship(p_ship_id uuid, p_resource text, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; v_have integer; v_sys_faction text; v_fit integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  if p_amount is null or p_amount < 1 then raise exception 'Некорректное количество'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  select faction into v_sys_faction from systems where id = s.system_id;
  if v_sys_faction is distinct from s.faction then
    raise exception 'Эта планета не за твою сторону';
  end if;

  select amount into v_have from ship_resource_cargo
  where ship_id = p_ship_id and resource = p_resource for update;

  if coalesce(v_have, 0) < p_amount then
    raise exception 'В трюме столько нет: есть %', coalesce(v_have, 0);
  end if;

  v_fit := add_planet_stock(s.system_id, p_resource, p_amount);

  if v_fit = 0 then
    raise exception 'Склады планеты полны, разгружать некуда';
  end if;

  if v_have - v_fit <= 0 then
    delete from ship_resource_cargo
    where ship_id = p_ship_id and resource = p_resource;
  else
    update ship_resource_cargo set amount = amount - v_fit
    where ship_id = p_ship_id and resource = p_resource;
  end if;

  perform log_event(case when coalesce(current_setting('app.supply_quiet', true), '') = 'on'
                         then null::uuid else v_user end, s.faction, s.system_id, 'cargo_delivered',
                    p_resource, v_fit, 'private', null);

  return v_fit;
end;
$$;


--
-- Name: unload_unit_at(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unload_unit_at(p_ship_id uuid, p_unit_type text, p_x integer, p_y integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  s record; t record; ut record;
  v_sys_faction text;
  v_attacking boolean;
  v_zone integer;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
  v_unit uuid;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into s from ships where id = p_ship_id for update;
  if not found then raise exception 'Корабль не найден'; end if;
  if s.owner_user_id <> v_user then raise exception 'Это не твой корабль'; end if;
  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  select * into t from ship_types where id = s.ship_type;
  select * into ut from unit_types where id = p_unit_type;
  select faction into v_sys_faction from systems where id = s.system_id;
  v_attacking := v_sys_faction is distinct from s.faction;

  -- Проверяем груз до всего остального: незачем разбирать геометрию,
  -- если высаживать нечего. Первым идёт самый прокачанный и целый.
  select id into v_unit from unit_positions
  where carrier_ship_id = p_ship_id and unit_type = p_unit_type
    and not coalesce(ut.is_vehicle, false) and not coalesce(ut.is_hero, false)
  order by coalesce(cardinality(upgrades), 0) desc, hp desc, id
  limit 1
  for update;

  if v_unit is null then raise exception 'В трюме нет таких юнитов'; end if;

  if p_x < 0 or p_y < 0 or p_x >= v_grid or p_y >= v_grid then
    raise exception 'Клетка вне карты';
  end if;

  if v_attacking then
    -- Чужая планета: корабль должен стоять в площадке сброса целиком
    v_zone := is_in_orbital_drop(
      s.x, s.y,
      ship_box_w(t.width_cells, t.height_cells, s.facing),
      ship_box_h(t.width_cells, t.height_cells, s.facing));

    if v_zone is null then
      raise exception 'Корабль должен целиком стоять в площадке сброса';
    end if;

    if not is_in_ground_attack_zone(p_y) then
      raise exception 'Десант высаживается только в полосе вторжения';
    end if;
  else
    -- Своя и союзная планета: тоже только из площадки сброса (как unload_from_ship и unload_vehicle_at)
    if is_in_orbital_drop(s.x, s.y,
         ship_box_w(t.width_cells, t.height_cells, s.facing),
         ship_box_h(t.width_cells, t.height_cells, s.facing)) is null then
      raise exception 'Корабль должен целиком стоять в площадке сброса';
    end if;
    -- Своя планета: работают обычные зоны высадки
    if not is_in_deploy_zone(s.system_id, p_x, p_y) then
      raise exception 'Клетка вне зоны высадки';
    end if;
  end if;

  if p_x is null or p_y is null then raise exception 'Клетка вне карты'; end if;
  if not is_ground_box_free(s.system_id, p_x, p_y, 1, 1, null) then
    raise exception 'Клетка занята';
  end if;

  update unit_positions
  set x = p_x, y = p_y, carrier_ship_id = null, system_id = s.system_id
  where id = v_unit;

  perform log_event(v_user, s.faction, s.system_id, 'unit_deployed', p_unit_type, 1, 'private',
                    jsonb_build_object('unit_id', v_unit, 'x', p_x, 'y', p_y));

  return v_unit;
end;
$$;


--
-- Name: unload_vehicle_at(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unload_vehicle_at(p_unit_id uuid, p_x integer, p_y integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; ut record; s record; st record;
  v_sys_faction text; v_attacking boolean;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Юнит не найден'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твой юнит'; end if;
  if u.carrier_ship_id is null then raise exception 'Юнит не в трюме корабля'; end if;

  select * into ut from unit_types where id = u.unit_type;
  select * into s from ships where id = u.carrier_ship_id;
  select * into st from ship_types where id = s.ship_type;

  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  if is_in_orbital_drop(s.x, s.y,
       ship_box_w(st.width_cells, st.height_cells, s.facing),
       ship_box_h(st.width_cells, st.height_cells, s.facing)) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса';
  end if;

  select faction into v_sys_faction from systems where id = s.system_id;
  v_attacking := v_sys_faction is distinct from s.faction;

  if v_attacking then
    if not is_box_in_attack_zone(p_y, ut.height_cells) then
      raise exception 'Техника высаживается только в полосе вторжения';
    end if;
  else
    if not is_box_in_deploy_zone(s.system_id, p_x, p_y, ut.width_cells, ut.height_cells) then
      raise exception 'Клетка вне зоны высадки';
    end if;
  end if;

  if p_x is null or p_y is null then raise exception 'Клетка вне карты'; end if;
  if not is_ground_box_free(s.system_id, p_x, p_y, ut.width_cells, ut.height_cells, p_unit_id) then
    raise exception 'Место занято или выходит за край карты';
  end if;

  update unit_positions
  set x = p_x, y = p_y, carrier_ship_id = null, system_id = s.system_id
  where id = p_unit_id;
end;
$$;


--
-- Name: unload_vehicle_auto(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unload_vehicle_auto(p_unit_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  u record; ut record; s record; st record;
  v_sys_faction text; v_attacking boolean;
  spot record;
  v_grid integer := game_setting_int('ground_grid_cells', 144);
  v_ah integer := game_setting_int('ground_attack_zone_height', 4);
  cy integer; cx integer;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;

  select * into u from unit_positions where id = p_unit_id for update;
  if not found then raise exception 'Техника не найдена'; end if;
  if u.owner_user_id <> v_user then raise exception 'Это не твоя техника'; end if;
  if u.carrier_ship_id is null then raise exception 'Техника не в трюме корабля'; end if;

  select * into ut from unit_types where id = u.unit_type;
  select * into s from ships where id = u.carrier_ship_id;
  select * into st from ship_types where id = s.ship_type;

  if s.in_transit then raise exception 'Корабль в гиперпространстве'; end if;

  if is_in_orbital_drop(s.x, s.y,
       ship_box_w(st.width_cells, st.height_cells, s.facing),
       ship_box_h(st.width_cells, st.height_cells, s.facing)) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса';
  end if;

  select faction into v_sys_faction from systems where id = s.system_id;
  v_attacking := v_sys_faction is distinct from u.faction;

  if v_attacking then
    -- Ищем место в полосе вторжения, от её начала вглубь
    cy := v_grid - v_ah;
    while cy <= v_grid - ut.height_cells loop
      cx := 0;
      while cx <= v_grid - ut.width_cells loop
        if is_ground_box_free(s.system_id, cx, cy, ut.width_cells, ut.height_cells, p_unit_id) then
          update unit_positions
          set x = cx, y = cy, carrier_ship_id = null, system_id = s.system_id
          where id = p_unit_id;
          return true;
        end if;
        cx := cx + 1;
      end loop;
      cy := cy + 1;
    end loop;
  else
    select * into spot
    from find_deploy_box(s.system_id, ut.width_cells, ut.height_cells, 0, 0)
    limit 1;

    if found then
      update unit_positions
      set x = spot.x, y = spot.y, carrier_ship_id = null, system_id = s.system_id
      where id = p_unit_id;
      return true;
    end if;
  end if;

  raise exception 'Нет свободного места нужного размера';
end;
$$;


--
-- Name: unrest_calc(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_calc(p_system text, p_fed boolean DEFAULT NULL::boolean, p_eff integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sy record; st record; u record; v_ctl uuid; v_seen timestamptz; v_born timestamptz;
  v_eff integer; v_need integer; v_have integer; v_fields integer; v_hunger boolean;
  v_enemy boolean; v_raid boolean; v_gar integer; v_cap integer := 100; v_cap_why text; v_hold text; v_hold_until timestamptz;
  v_rows jsonb := '[]'::jsonb; v_up integer := 0; v_down integer := 0; v_mrush integer; v_mhungry integer; v_mcare integer; v_mall integer;
  v_caps text[] := string_to_array(coalesce((select value from game_settings where key = 'unrest_capitals'), ''), ',');
begin
  select id, name, faction into sy from systems where id = p_system;
  if not found or sy.faction is null then return null; end if;
  select * into st from settlement_state where system_id = p_system;
  select * into u from settlement_unrest where system_id = p_system;
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  if v_ctl is not null then select last_seen_at, created_at into v_seen, v_born from profiles where id = v_ctl; end if;

  v_eff := coalesce(p_eff, settlement_effective(p_system), 0);

  -- рост
  if p_fed is not null then v_hunger := p_fed is false;
  else
    select coalesce(food_per_day, 0) into v_need from settlement_levels where level = coalesce(st.level, 1);
    select coalesce(amount, 0) into v_have from planet_stock where system_id = p_system and resource = 'food';
    v_fields := case when settlement_has_district(p_system, 'fields') then (select effect_value from district_types where id = 'fields') else 0 end;
    v_hunger := coalesce(v_need, 0) > 0 and coalesce(v_have, 0) + coalesce(v_fields, 0) < v_need;
  end if;
  if v_hunger then v_up := v_up + 15; v_rows := v_rows || jsonb_build_object('label', 'Голод', 'value', 15); end if;

  v_enemy := is_capture_active(p_system) or exists (
    select 1 from unit_positions x
     where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.carrier_ship_id is null
       and x.faction in ('republic', 'cis') and x.faction <> sy.faction and is_in_settlement_zone(x.x, x.y));
  if v_enemy then v_up := v_up + 10; v_rows := v_rows || jsonb_build_object('label', 'Враг у стен', 'value', 10); end if;

  v_raid := st.cycle_started is not null and exists (
    select 1 from settlement_tasks t where t.system_id = p_system and t.cycle_start = st.cycle_started
       and t.kind = 'marauder' and coalesce((t.payload ->> 'escaped')::boolean, false));
  if v_raid then v_up := v_up + 10; v_rows := v_rows || jsonb_build_object('label', 'Мародёры ушли с добычей', 'value', 10); end if;

  if v_eff < 20 and coalesce(u.low_days, 0) >= 2 then
    v_up := v_up + 5; v_rows := v_rows || jsonb_build_object('label', 'Запустение: довольство ниже 20', 'value', 5);
  end if;

  -- участки добычи за сутки: авралы и голодные смены — ропот, бережная работа — спокойнее
  select count(*) filter (where sh.pace = 'rush'), count(*) filter (where not (sh.fed_h and sh.fed_d)), count(*) filter (where sh.pace = 'careful'), count(*)
    into v_mrush, v_mhungry, v_mcare, v_mall
    from mine_shifts sh where sh.system_id = p_system and sh.started_at > now() - interval '24 hours' and sh.status <> 'lost';
  if v_mrush > 0 then v_up := v_up + least(8, 3 * v_mrush); v_rows := v_rows || jsonb_build_object('label', 'Авралы на участках: ' || v_mrush, 'value', least(8, 3 * v_mrush)); end if;
  if v_mhungry > 0 then v_up := v_up + 4; v_rows := v_rows || jsonb_build_object('label', 'Бригады без пайка', 'value', 4); end if;
  if v_mall > 0 and v_mcare * 2 >= v_mall and v_mrush = 0 then v_down := v_down + 2; v_rows := v_rows || jsonb_build_object('label', 'Бережная работа на участках', 'value', -2); end if;
  if exists (select 1 from spy_ops o where o.target_system = p_system and o.kind = 'strike' and o.result = 'ok' and o.acted_at > now() - interval '24 hours') then
    v_up := v_up + 4; v_rows := v_rows || jsonb_build_object('label', 'Подстрекатели на участках', 'value', 4);
  end if;

  -- настроения планеты (sql/loyalty.sql): ропот на власть и подполье в городе
  if loyalty_on('effects') and coalesce(loyalty_support(p_system), 0) <= -20 then
    if loyalty_support(p_system) <= -50 then v_up := v_up + 5; v_rows := v_rows || jsonb_build_object('label', 'Подполье в городе', 'value', 5);
    else v_up := v_up + 3; v_rows := v_rows || jsonb_build_object('label', 'Народ ропщет на власть', 'value', 3); end if;
  end if;

  -- гасители
  if v_eff >= 60 then v_down := v_down + 20; v_rows := v_rows || jsonb_build_object('label', 'Довольство 60+', 'value', -20);
  elsif v_eff >= 40 then v_down := v_down + 10; v_rows := v_rows || jsonb_build_object('label', 'Довольство 40+', 'value', -10); end if;

  select count(*) into v_gar from unit_positions x
   where x.system_id = p_system and x.layer = 'ground' and x.hp > 0 and x.x is not null and x.carrier_ship_id is null
     and x.faction = sy.faction and x.owner_user_id is not null and is_in_settlement_zone(x.x, x.y);
  if v_gar >= 15 then v_down := v_down + 10; v_rows := v_rows || jsonb_build_object('label', 'Гарнизон в поселении: ' || v_gar, 'value', -10);
  elsif v_gar >= 5 then v_down := v_down + 5; v_rows := v_rows || jsonb_build_object('label', 'Гарнизон в поселении: ' || v_gar, 'value', -5); end if;

  if v_ctl is not null and v_seen > now() - interval '24 hours' then
    v_down := v_down + 3; v_rows := v_rows || jsonb_build_object('label', 'Присмотр управляющего', 'value', -3);
  end if;

  if v_up = 0 then v_down := v_down + 5; v_rows := v_rows || jsonb_build_object('label', 'Спокойные сутки', 'value', -5); end if;

  -- пределы и заморозка роста
  if v_ctl is null then v_cap := game_setting_int('unrest_cap_free', 49); v_cap_why := 'ничья планета — только ропот';
  elsif p_system = any(v_caps) then v_cap := game_setting_int('unrest_cap_capital', 74); v_cap_why := 'столица — без мятежа'; end if;
  if u.hold_until > now() then v_hold := coalesce(u.hold_why, 'передышка'); v_hold_until := u.hold_until;
  elsif v_ctl is not null and v_born > now() - make_interval(days => game_setting_int('unrest_newbie_days', 7)) then
    v_hold := 'новый управляющий'; v_hold_until := v_born + make_interval(days => game_setting_int('unrest_newbie_days', 7));
  end if;

  return jsonb_build_object('delta', v_up - v_down, 'up', v_up, 'down', v_down, 'rows', v_rows, 'eff', v_eff,
    'garrison', v_gar, 'cap', v_cap, 'cap_why', v_cap_why, 'hold', v_hold, 'hold_until', v_hold_until,
    'free', v_ctl is null, 'controller', v_ctl);
end;
$$;


--
-- Name: unrest_day(text, boolean, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_day(p_system text, p_fed boolean, p_eff integer, p_controller uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c jsonb; u record; v_old integer; v_new integer; v_d integer; s_old jsonb; s_new jsonb; sy record; v_lead uuid; v_meta jsonb; v_to uuid;
  v_riot uuid; v_started uuid; v_wait boolean := false; v_obs boolean := game_setting_int('unrest_penalties_enabled', 0) <> 1;
begin
  if game_setting_int('unrest_enabled', 1) <> 1 then return; end if;
  select id, name, faction into sy from systems where id = p_system;
  if sy.faction is null then return; end if;
  insert into settlement_unrest (system_id) values (p_system) on conflict (system_id) do nothing;
  select * into u from settlement_unrest where system_id = p_system for update;
  c := unrest_calc(p_system, p_fed, p_eff);
  if c is null then return; end if;

  v_old := u.value;
  select id into v_riot from settlement_riots where system_id = p_system and status = 'active';
  if v_riot is not null then
    v_new := 100;                                          -- пока идёт свой мятеж, шкала стоит на 100
  else
    v_d := (c ->> 'delta')::integer;
    if c ->> 'hold' is not null and v_d > 0 then v_d := 0; end if;
    v_new := least((c ->> 'cap')::integer, greatest(0, v_old + v_d));
    -- один мятеж на фракцию: пока он идёт на другой планете, здесь шкала держится на 99
    if v_new >= 100 and game_setting_int('unrest_riot_enabled', 0) = 1
       and exists (select 1 from settlement_riots r where r.faction = sy.faction and r.status = 'active') then
      v_new := 99; v_wait := true;
    end if;
  end if;

  update settlement_unrest
     set value = v_new,
         low_days = case when coalesce(p_eff, 0) < 20 then low_days + 1 else 0 end,
         high_days = case when v_new >= 75 then high_days + 1 else 0 end,
         last_delta = v_new - v_old, last_rows = c -> 'rows', last_at = now(), updated_at = now()
   where system_id = p_system;
  insert into settlement_unrest_log (system_id, value, delta, eff, rows) values (p_system, v_new, v_new - v_old, p_eff, c -> 'rows');

  -- штрафы на сутки и мятеж (переключатели unrest_penalties_enabled / unrest_riot_enabled)
  perform unrest_penalty(p_system, v_new);
  if v_riot is null and v_new >= 100 and game_setting_int('unrest_riot_enabled', 0) = 1 then
    v_started := riot_start(p_system);
  end if;

  select leader_user_id into v_lead from faction_leadership where faction = sy.faction;

  -- забастовки и следующие сутки с тем же ростом доведут до мятежа — вся фракция узнаёт заранее
  if v_riot is null and v_started is null and not v_wait and game_setting_int('unrest_riot_enabled', 0) = 1
     and v_new between 75 and 99 and v_new > v_old and v_new + (v_new - v_old) >= 100 then
    perform log_event(null, sy.faction, p_system, 'unrest_near', sy.name || ': мятеж близко · ' || v_new, v_new, 'faction',
                      jsonb_build_object('value', v_new, 'prev', v_old, 'planet', sy.name));
  end if;

  if v_started is not null or v_riot is not null then return; end if;   -- о мятеже — свои извещения
  s_old := unrest_state_of(v_old); s_new := unrest_state_of(v_new);
  if (s_new ->> 'n')::integer = (s_old ->> 'n')::integer then return; end if;
  if (s_new ->> 'n')::integer < (s_old ->> 'n')::integer and (s_new ->> 'n')::integer > 0 then return; end if;   -- спад, но не до спокойствия — без шума

  v_meta := jsonb_build_object('value', v_new, 'prev', v_old, 'state', s_new ->> 'k', 'state_t', s_new ->> 't', 'planet', sy.name, 'obs', v_obs);
  for v_to in select distinct x from unnest(array[p_controller, v_lead]) x where x is not null loop
    if (s_new ->> 'n')::integer = 0 then
      perform log_event(v_to, sy.faction, p_system, 'unrest_calm', sy.name || ': спокойно', v_new, 'private', v_meta);
    else
      perform log_event(v_to, sy.faction, p_system, 'unrest_level', sy.name || ': ' || (s_new ->> 't') || ' · ' || v_new, v_new, 'private', v_meta);
    end if;
  end loop;
end;
$$;


--
-- Name: unrest_deal(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_deal(p_system text, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  sy record; u record; st record; rt record; v_ctl uuid; v_lvl integer; v_cr integer; v_food integer; v_have integer;
  v_self boolean; v_tre boolean; v_why text; v_again timestamptz; v_bank integer; v_mine integer;
begin
  select id, name, faction into sy from systems where id = p_system;
  if sy.faction is null or sy.faction not in ('republic', 'cis') then return null; end if;
  select * into u from settlement_unrest where system_id = p_system;
  select * into st from settlement_state where system_id = p_system;
  select * into rt from settlement_riots where system_id = p_system and status = 'active';
  select controller_user_id into v_ctl from system_control where system_id = p_system;
  v_lvl := greatest(1, coalesce(st.level, 1));
  v_cr := game_setting_int('unrest_deal_credits', 500) * v_lvl;
  v_food := game_setting_int('unrest_deal_food', 50) * v_lvl;
  select coalesce(amount, 0) into v_have from planet_stock where system_id = p_system and resource = 'food';
  v_self := p_user is not null and v_ctl = p_user;
  v_tre := p_user is not null and faction_power(p_user, sy.faction, 'treasury');
  v_again := u.negotiated_at + make_interval(days => game_setting_int('unrest_deal_cooldown_days', 7));

  v_why := case
    when game_setting_int('unrest_penalties_enabled', 0) <> 1 then 'Переговоры откроются вместе с последствиями напряжения'
    when rt.id is null and coalesce(u.value, 0) < 75 then 'Переговоры — при забастовках (75+) или мятеже'
    when rt.id is not null and rt.started_at < now() - make_interval(hours => game_setting_int('unrest_deal_riot_hours', 12))
      then 'Мятеж идёт дольше ' || game_setting_int('unrest_deal_riot_hours', 12) || ' ч — теперь только подавить'
    when rt.id is null and coalesce(u.high_days, 0) > game_setting_int('unrest_deal_max_days', 3)
      then 'Забастовки идут дольше ' || game_setting_int('unrest_deal_max_days', 3) || ' суток — обещаниям не верят'
    when v_again > now() then 'Уже договаривались — снова можно через ' ||
      case when v_again - now() > interval '1 day' then ceil(extract(epoch from v_again - now()) / 86400)::integer || ' сут.'
           else ceil(extract(epoch from v_again - now()) / 3600)::integer || ' ч' end
    when st.fed is false or coalesce(u.last_rows, '[]'::jsonb) @> '[{"label":"Голод"}]'::jsonb then 'Голод: пока склад пуст, слушать не станут'
    when not (v_self or v_tre) then 'Договориться может управляющий, лидер или казначей фракции'
  end;
  if v_self then select credits into v_mine from profiles where id = p_user; end if;
  if v_tre then select credits into v_bank from faction_treasury where faction = sy.faction; end if;
  return jsonb_build_object('ok', v_why is null, 'why', v_why, 'credits', v_cr, 'food', v_food, 'food_have', coalesce(v_have, 0),
    'self', v_self, 'treasury', v_tre, 'my_credits', v_mine, 'bank', coalesce(v_bank, 0), 'again_at', v_again,
    'riot', rt.id is not null, 'value', 60);
end;
$$;


--
-- Name: unrest_effects_of(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_effects_of(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('kind', fe.kind, 'value', fe.value, 'title', fe.title, 'source', fe.source, 'ends', fe.ends_at)
                            order by fe.source, fe.kind), '[]'::jsonb)
    from faction_effects fe join systems s on s.id = fe.system_id and s.faction = fe.faction
   where fe.system_id = p_system and fe.source in ('unrest', 'riot', 'riot_end') and fe.starts_at <= now() and fe.ends_at > now();
$$;


--
-- Name: unrest_faction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_faction() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; v_out jsonb; v_pen boolean := game_setting_int('unrest_penalties_enabled', 0) = 1;
begin
  select faction into v_fac from profiles where id = v_me;
  if v_fac is null then return null; end if;
  select coalesce(jsonb_agg(r order by (r ->> 'value')::integer desc, r ->> 'name'), '[]'::jsonb) into v_out from (
    select jsonb_build_object('id', s.id, 'name', s.name, 'value', coalesce(u.value, 0),
             'state', unrest_state_of(coalesce(u.value, 0)), 'last_delta', u.last_delta,
             'forecast', (c ->> 'delta')::integer, 'cap', (c ->> 'cap')::integer, 'hold', c ->> 'hold',
             'controller', p.nickname, 'mine', sc.controller_user_id = v_me,
             'seen_days', case when p.id is not null then floor(extract(epoch from now() - coalesce(p.last_seen_at, p.created_at)) / 86400)::integer end,
             'cond', settlement_cond(s.id),
             'riot', unrest_riot_info(s.id),
             'pen', (select -min(fe.value) from faction_effects fe where fe.system_id = s.id and fe.faction = v_fac and fe.source = 'unrest'
                        and fe.kind = 'extract' and fe.starts_at <= now() and fe.ends_at > now())) r
      from systems s
      left join settlement_unrest u on u.system_id = s.id
      left join system_control sc on sc.system_id = s.id
      left join profiles p on p.id = sc.controller_user_id
      cross join lateral (select unrest_calc(s.id) c) q
     where s.faction = v_fac and not coalesce(s.is_deep_space, false)) z;
  return jsonb_build_object('faction', v_fac, 'enabled', game_setting_int('unrest_enabled', 1) = 1, 'observe', not v_pen,
                            'penalties', v_pen, 'riots', game_setting_int('unrest_riot_enabled', 0) = 1,
                            'planets', v_out, 'next_at', next_payout_at(), 'is_leader', is_faction_leader(v_me, v_fac),
                            'gain', game_setting_int('settlement_task_gain', 5), 'loss', game_setting_int('settlement_task_loss', 4),
                            'bonus', game_setting_int('settlement_task_bonus', 5), 'no_ruler', game_setting_int('settlement_no_ruler_penalty', 10));
end;
$$;


--
-- Name: unrest_negotiate(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_negotiate(p_system text, p_treasury boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); sy record; d jsonb; v_cr integer; v_food integer; v_have integer; v_bank integer; v_riot uuid; v_old integer;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select id, name, faction into sy from systems where id = p_system;
  if sy.faction is distinct from (select faction from profiles where id = v_me) then raise exception 'Это не планета твоей фракции'; end if;
  select value into v_old from settlement_unrest where system_id = p_system for update;     -- двое разом не договорятся
  d := unrest_deal(p_system, v_me);
  if d is null then raise exception 'Здесь договариваться не с кем'; end if;
  if not (d ->> 'ok')::boolean then raise exception '%', d ->> 'why'; end if;
  v_cr := (d ->> 'credits')::integer; v_food := (d ->> 'food')::integer;

  select coalesce(amount, 0) into v_have from planet_stock where system_id = p_system and resource = 'food' for update;
  if coalesce(v_have, 0) < v_food then raise exception 'На складе планеты не хватает еды: нужно %, есть %', v_food, coalesce(v_have, 0); end if;

  if p_treasury then
    if not (d ->> 'treasury')::boolean then raise exception 'Из казны платят лидер или казначей фракции'; end if;
    select credits into v_bank from faction_treasury where faction = sy.faction for update;
    if coalesce(v_bank, 0) < v_cr then raise exception 'В казне не хватает: нужно % кр.', v_cr; end if;
    perform treasury_add(sy.faction, -v_cr, 'project', v_me, null, p_system, 'Переговоры: ' || sy.name);
  else
    if not (d ->> 'self')::boolean then raise exception 'Своими кредитами платит только управляющий планеты'; end if;
    update profiles set credits = credits - v_cr where id = v_me and credits >= v_cr;
    if not found then raise exception 'Не хватает кредитов: нужно %', v_cr; end if;
  end if;
  update planet_stock set amount = amount - v_food where system_id = p_system and resource = 'food';

  update settlement_unrest set value = 60, high_days = 0, negotiated_at = now(), updated_at = now() where system_id = p_system;
  select id into v_riot from settlement_riots where system_id = p_system and status = 'active';
  if v_riot is not null then
    perform riot_finish(v_riot, 'negotiated');
  else
    perform unrest_penalty(p_system, 60);
    perform log_event(null, sy.faction, p_system, 'unrest_riot_end', sy.name || ': с забастовщиками договорились', 0, 'faction',
                      jsonb_build_object('planet', sy.name, 'status', 'deal', 'value', 60, 'prev', v_old));
  end if;
  return jsonb_build_object('value', 60, 'credits', v_cr, 'food', v_food, 'treasury', p_treasury);
end;
$$;


--
-- Name: unrest_on_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_on_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_riot uuid;
begin
  if new.faction is distinct from old.faction then
    for v_riot in select id from settlement_riots where system_id = new.id and status = 'active' loop
      perform riot_finish(v_riot, 'captured');
    end loop;
    update faction_effects set ends_at = now() where system_id = new.id and source in ('unrest', 'riot', 'riot_end') and ends_at > now();
    insert into settlement_unrest (system_id, value, low_days, high_days, hold_until, hold_why, updated_at)
    values (new.id, case when new.faction is null then 0 else 30 end, 0, 0,
            now() + make_interval(hours => game_setting_int('unrest_hold_capture_hours', 72)), 'после захвата', now())
    on conflict (system_id) do update set value = excluded.value, low_days = 0, high_days = 0, hold_until = excluded.hold_until,
      hold_why = excluded.hold_why, last_delta = null, last_rows = null, updated_at = now();
  end if;
  return null;
end;
$$;


--
-- Name: unrest_penalty(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_penalty(p_system text, p_value integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_fac text; v_pct integer; v_t text;
begin
  update faction_effects set ends_at = now() where system_id = p_system and source = 'unrest' and ends_at > now();
  select faction into v_fac from systems where id = p_system;
  if v_fac is null or v_fac not in ('republic', 'cis') or game_setting_int('unrest_penalties_enabled', 0) <> 1 then return 0; end if;
  if exists (select 1 from settlement_riots where system_id = p_system and status = 'active') then return 0; end if;
  if p_value >= 75 then v_pct := game_setting_int('unrest_strike_pct', 30); v_t := 'Забастовки';
  elsif p_value >= 50 then v_pct := game_setting_int('unrest_unrest_pct', 15); v_t := 'Волнения';
  else return 0; end if;
  insert into faction_effects (faction, kind, value, title, source, system_id, starts_at, ends_at)
  select v_fac, k, -v_pct, v_t, 'unrest', p_system, now(), next_payout_at() + interval '1 hour'
    from unnest(array['extract', 'income']) k;
  return v_pct;
end;
$$;


--
-- Name: unrest_riot_info(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_riot_info(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('id', r.id, 'started_at', r.started_at, 'ends_at', r.ends_at, 'total', r.total,
           'alive', (select count(*) from unit_positions x where x.id = any(r.rebels) and x.hp > 0),
           'x', (select x.x from unit_positions x where x.id = any(r.rebels) and x.hp > 0 and x.x is not null order by x.id limit 1),
           'y', (select x.y from unit_positions x where x.id = any(r.rebels) and x.hp > 0 and x.x is not null order by x.id limit 1))
    from settlement_riots r where r.system_id = p_system and r.status = 'active';
$$;


--
-- Name: unrest_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_state(p_system text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text; sy record; u record; c jsonb; v_hist jsonb; v_pen boolean; v_riots boolean; v_else text;
begin
  select faction into v_fac from profiles where id = v_me;
  select id, faction into sy from systems where id = p_system;
  if v_fac is null or sy.faction is distinct from v_fac then return null; end if;
  select * into u from settlement_unrest where system_id = p_system;
  c := unrest_calc(p_system);
  select coalesce(jsonb_agg(jsonb_build_object('at', l.at, 'value', l.value, 'delta', l.delta) order by l.at), '[]'::jsonb) into v_hist
    from (select * from settlement_unrest_log where system_id = p_system order by at desc limit 7) l;
  v_pen := game_setting_int('unrest_penalties_enabled', 0) = 1;
  v_riots := game_setting_int('unrest_riot_enabled', 0) = 1;
  select s.name into v_else from settlement_riots r join systems s on s.id = r.system_id
   where r.faction = v_fac and r.status = 'active' and r.system_id <> p_system;
  return jsonb_build_object(
    'enabled', game_setting_int('unrest_enabled', 1) = 1,
    'value', coalesce(u.value, 0), 'state', unrest_state_of(coalesce(u.value, 0)),
    'last_delta', u.last_delta, 'last_rows', coalesce(u.last_rows, '[]'::jsonb), 'last_at', u.last_at,
    'forecast', c, 'history', v_hist, 'next_at', next_payout_at(),
    'observe', not v_pen, 'penalties', v_pen, 'riots', v_riots,
    'pct', jsonb_build_object('unrest', game_setting_int('unrest_unrest_pct', 15), 'strike', game_setting_int('unrest_strike_pct', 30)),
    'high_days', coalesce(u.high_days, 0),
    'riot', unrest_riot_info(p_system), 'riot_elsewhere', v_else,
    'effects', unrest_effects_of(p_system),
    'deal', case when v_pen and (coalesce(u.value, 0) >= 75 or exists (select 1 from settlement_riots r where r.system_id = p_system and r.status = 'active'))
                 then unrest_deal(p_system, v_me) end);
end;
$$;


--
-- Name: unrest_state_of(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unrest_state_of(p_value integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_value >= 100 then '{"k":"riot","t":"мятеж назрел","n":4}'::jsonb
    when p_value >= 75 then '{"k":"strike","t":"забастовки","n":3}'::jsonb
    when p_value >= 50 then '{"k":"unrest","t":"волнения","n":2}'::jsonb
    when p_value >= 30 then '{"k":"murmur","t":"ропот","n":1}'::jsonb
    else '{"k":"calm","t":"спокойно","n":0}'::jsonb end;
$$;


--
-- Name: update_supply_route(uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_supply_route(p_route_id uuid, p_name text, p_stops jsonb, p_loop boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid := auth.uid(); v_status text; v_old_loop boolean; v_old_name text;
        v_fac text; v_stops jsonb; v_name text; v_loop boolean;
begin
  if v_user is null then raise exception 'Не авторизован'; end if;
  select x.status, x.loop, x.name into v_status, v_old_loop, v_old_name
    from supply_routes x where x.id = p_route_id and x.owner_user_id = v_user for update;
  if v_status is null then raise exception 'Рейс не найден'; end if;
  if v_status = 'stopped' then raise exception 'Рейс уже завершён'; end if;
  if exists (select 1 from supply_routes x where x.id = p_route_id and x.order_id is not null) then
    raise exception 'Вывоз покупки не меняется — заверши его и отправь флот заново';
  end if;
  select faction into v_fac from profiles where id = v_user;

  v_loop := coalesce(p_loop, v_old_loop);
  v_stops := supply_normalize_stops(p_stops, v_fac, v_loop);
  v_name := coalesce(left(nullif(btrim(coalesce(p_name, '')), ''), 40), v_old_name);

  update supply_routes x
     set name = v_name, stops = v_stops, loop = v_loop,
         stop_index = 0,
         phase = case when x.phase = 'at_stop' then 'travel' else x.phase end,
         moved_this_cycle = 0, idle_cycles = 0,
         last_note = 'Маршрут изменён', updated_at = now()
   where x.id = p_route_id;
  perform supply_log(p_route_id, null, 'Маршрут изменён — начинаем с первой остановки', 0);
end $$;


--
-- Name: void_find_dur(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_dur(p_sec integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when greatest(0, p_sec) >= 3600
              then (greatest(0, p_sec) / 3600) || ' ч' || case when (greatest(0, p_sec) % 3600) / 60 > 0 then ' ' || (greatest(0, p_sec) % 3600) / 60 || ' мин' else '' end
              else greatest(1, greatest(0, p_sec) / 60) || ' мин' end;
$$;


--
-- Name: void_find_finish(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_finish(p_find uuid, p_winner text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  f record; t void_find_types; h record; c record; e jsonb; k text; v_amt int; v_left int; v_total numeric;
  v_share numeric; v_cr int; v_put jsonb; v_lost jsonb; v_rows jsonb := '[]'::jsonb; v_text text;
  v_fname text; v_meta jsonb;
begin
  select * into f from void_finds where id = p_find for update;
  if not found or f.status <> 'active' then return; end if;
  select * into t from void_find_types where id = f.type_id;
  v_meta := jsonb_build_object('find', f.id, 'type', f.type_id, 'layer', 'space');

  -- находка закрывается: флоты в узле сами выходят к гиперлинии — домой (корабли остаются в узле, груз ниже доходит)
  for c in select cm.id from commanders cm where cm.current_system = f.system_id and cm.moving_to is null and cm.unlocked loop
    begin
      perform void_find_move(f.id, c.id, 'band');
    exception when others then perform err_db('void_find_finish', sqlstate, sqlerrm, true);
    end;
  end loop;

  if p_winner is null then
    update void_finds set status = 'lost', ended_at = now(), holder = null where id = f.id;
    perform void_find_notify('void_find_lost', f.system_id,
      t.title || ' — никто не удержал за ' || void_find_dur(extract(epoch from f.ends_at - f.started_at)::int) || '. Находка ушла в Пустоту, флоты выходят к гиперлинии', v_meta);
    return;
  end if;

  v_fname := case p_winner when 'republic' then 'Республика' else 'Конфедерация' end;
  select coalesce(sum(seconds), 0) into v_total from void_find_holders where find_id = f.id and faction = p_winner and seconds > 0;

  for h in
    select hd.user_id, hd.seconds, p.nickname from void_find_holders hd join profiles p on p.id = hd.user_id
    where hd.find_id = f.id and hd.faction = p_winner and hd.seconds > 0 and p.faction = p_winner
    order by hd.seconds desc
  loop
    v_share := case when v_total > 0 then h.seconds / v_total else 1 end;
    v_cr := greatest(50, round(coalesce((t.reward ->> 'credits')::int, 0) * v_share)::int);
    update profiles set credits = credits + v_cr where id = h.user_id;
    v_put := '{}'::jsonb; v_lost := '{}'::jsonb;
    for k, v_amt in select key, round(value::numeric * v_share)::int from jsonb_each_text(coalesce(t.reward -> 'cargo', '{}'::jsonb)) loop
      continue when v_amt <= 0;
      v_left := v_amt;
      for c in select cm.id from commanders cm where cm.user_id = h.user_id and cm.current_system = f.system_id and cm.moving_to is null order by cm.slot_index loop
        exit when v_left <= 0;
        v_left := v_left - supply_put_cargo(c.id, f.system_id, k, v_left);
      end loop;
      if v_amt - v_left > 0 then v_put := v_put || jsonb_build_object(k, v_amt - v_left); end if;
      if v_left > 0 then v_lost := v_lost || jsonb_build_object(k, v_left); end if;
    end loop;
    v_rows := v_rows || jsonb_build_object('user', h.user_id, 'nick', h.nickname, 'seconds', h.seconds, 'credits', v_cr, 'cargo', v_put, 'lost', v_lost);
    v_text := t.title || ' · ' || v_cr || ' кр.'
      || coalesce((select ' · в трюм: ' || string_agg(lower(r.name) || ' ' || x.value, ', ' order by r.sort_order)
                     from jsonb_each_text(v_put) x join resources r on r.id = x.key), '')
      || coalesce((select ' · не влезло: ' || string_agg(lower(r.name) || ' ' || x.value, ', ' order by r.sort_order)
                     from jsonb_each_text(v_lost) x join resources r on r.id = x.key), '');
    perform log_event(h.user_id, p_winner, f.system_id, 'void_find_reward', v_text, 0, 'private',
                      v_meta || jsonb_build_object('credits', v_cr, 'cargo', v_put, 'lost', v_lost, 'seconds', h.seconds));
  end loop;

  for e in select value from jsonb_array_elements(coalesce(t.reward -> 'effects', '[]'::jsonb)) loop
    insert into faction_effects (faction, kind, value, title, source, source_id, starts_at, ends_at, system_id)
    values (p_winner, e ->> 'kind', (e ->> 'value')::int, t.title, 'find:' || f.id, f.id, now(),
            now() + make_interval(hours => greatest(1, (e ->> 'hours')::int)), null);
  end loop;

  update void_finds set status = 'won', winner = p_winner, ended_at = now(), holder = null,
                        result = jsonb_build_object('rows', v_rows)
   where id = f.id;

  perform void_find_notify('void_find_won', f.system_id,
    v_fname || ' забрала «' || t.title || '»' || case when jsonb_array_length(v_rows) > 0
      then ' · держали: ' || (select string_agg(x ->> 'nick', ', ') from jsonb_array_elements(v_rows) x) else '' end,
    v_meta || jsonb_build_object('winner', p_winner));
end $$;


--
-- Name: void_find_fleet(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_fleet(p_commander uuid, p_to text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); cm record; f record; v text;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  if p_to not in ('zone', 'band') then raise exception 'Куда вести флот — к находке или к гиперлинии'; end if;
  select * into cm from commanders where id = p_commander and user_id = v_me;
  if not found then raise exception 'Это не твой командир'; end if;
  if cm.moving_to is not null then raise exception 'Командир в пути'; end if;
  select * into f from void_finds where system_id = cm.current_system and status = 'active';
  -- находка закрыта, флот ещё в узле — к гиперлинии всё равно выведем
  if not found and p_to = 'band' then
    select * into f from void_finds where system_id = cm.current_system order by started_at desc limit 1;
  end if;
  if f.id is null then raise exception 'Здесь нет находки'; end if;
  if exists (select 1 from supply_routes x where x.commander_id = cm.id and x.status = 'active') then
    raise exception 'Командир на рейсе снабжения';
  end if;
  v := void_find_move(f.id, cm.id, p_to);
  if v like 'blocked:%' then raise exception '%', substr(v, 9); end if;
  return v;
end $$;


--
-- Name: void_find_in_zone(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_in_zone(p_find uuid) RETURNS TABLE(user_id uuid, faction text, ships integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.owner_user_id, s.faction, count(*)::integer
  from void_finds f
  join ships s on s.system_id = f.system_id and not s.in_transit and s.carrier_ship_id is null
  join ship_types t on t.id = s.ship_type and not coalesce(t.is_fighter, false)
  where f.id = p_find
    and power(s.x + ship_box_w(t.width_cells, t.height_cells, s.facing) / 2.0 - (f.cx + 0.5), 2)
      + power(s.y + ship_box_h(t.width_cells, t.height_cells, s.facing) / 2.0 - (f.cy + 0.5), 2) <= power(f.r, 2)
  group by s.owner_user_id, s.faction;
$$;


--
-- Name: void_find_move(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_move(p_find uuid, p_commander uuid, p_to text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  f record; cm record; v_fac text; v_side text; v_here text; v_label text; v_live boolean;
  v_grid int := game_setting_int('space_grid_cells', 150);
  v_zh int := game_setting_int('hyperspace_zone_height', 14);
  s record; c record; g jsonb; v_w int; v_h int; v_l int; v_mr int; v_tx int; v_ty int; v_found boolean;
  v_txa int[] := '{}'; v_tya int[] := '{}'; v_twa int[] := '{}'; v_tha int[] := '{}';
  v_gx numeric[] := '{}'; v_gy numeric[] := '{}';
  v_zx numeric; v_zy numeric; v_fy numeric; v_y0 int; v_y1 int; v_mid int; v_d int; v_cx int; v_cy int; v_rows int[];
  v_path jsonb; v_group uuid; v_new uuid[] := '{}'; v_id uuid; v_n int := 0; v_out int := 0; a uuid;
begin
  select * into f from void_finds where id = p_find;
  select * into cm from commanders where id = p_commander;
  -- к гиперлинии можно и от закрытой находки: флоту надо как-то улететь домой
  if f.id is null or (f.status <> 'active' and p_to <> 'band') or cm.id is null or cm.moving_to is not null
     or cm.current_system is distinct from f.system_id then return 'ready'; end if;
  v_here := f.system_id;
  select p.faction into v_fac from profiles p where p.id = cm.user_id;
  v_side := hyperspace_side(v_here, v_fac);
  v_label := case when p_to = 'band' then 'К гиперлинии' else 'К находке' end;
  v_zx := f.cx + 0.5; v_zy := f.cy + 0.5;
  -- середина своей половины зоны: туда флот и встаёт, лицом к чужой
  v_fy := case when v_side = 'top' then v_zy - f.r * 0.45 else v_zy + f.r * 0.45 end;

  v_live := exists (select 1 from ships sh where sh.commander_id = cm.id and sh.system_id = v_here
                     and not sh.in_transit and sh.carrier_ship_id is null and rt_obj_busy_2_0('ship', sh.id) is not null);

  if f.guards_down_at is null then
    for g in select value from jsonb_array_elements(f.guards) loop
      continue when coalesce((g ->> 'hp')::numeric, 0) <= 0;
      v_gx := v_gx || ((g ->> 'x')::numeric / 200); v_gy := v_gy || ((g ->> 'y')::numeric / 200);
    end loop;
  end if;

  -- прежний наш приказ этому флоту (к находке или к гиперлинии) снимаем: новый важнее
  update auto_moves am set status = 'stopped', stop_reason = 'cancelled', updated_at = now()
   where am.status = 'active' and am.label in ('К находке', 'К гиперлинии')
     and am.ship_id in (select sh.id from ships sh where sh.commander_id = cm.id);

  if not v_live then
    begin
      perform 1 from ships sh where sh.commander_id = cm.id and sh.system_id = v_here
        and not sh.in_transit and sh.carrier_ship_id is null order by sh.id for update nowait;
    exception when lock_not_available then
      return 'blocked:Корабли заняты другим приказом — попробуй через минуту';
    end;
  end if;

  for s in
    select sh.id, sh.x, sh.y, sh.facing, t.width_cells as tw, t.height_cells as th
    from ships sh join ship_types t on t.id = sh.ship_type
    where sh.commander_id = cm.id and sh.system_id = v_here and not sh.in_transit and sh.carrier_ship_id is null
    order by case when p_to = 'band' then (case when v_side = 'top' then sh.y else -sh.y end)
                  else power(sh.x - v_zx, 2) + power(sh.y - v_zy, 2) end, sh.id
  loop
    v_w := ship_box_w(s.tw, s.th, s.facing);
    v_h := ship_box_h(s.tw, s.th, s.facing);
    v_l := greatest(s.tw, s.th);
    -- уже на месте
    if p_to = 'band' then
      continue when is_in_hyperspace_zone(s.y, v_h, v_side);
    else
      continue when power(s.x + v_w / 2.0 - v_zx, 2) + power(s.y + v_h / 2.0 - v_zy, 2) <= power(f.r - 1, 2);
    end if;
    v_out := v_out + 1;
    select ss.move_range into v_mr from ship_stats(s.id) ss;
    v_mr := greatest(1, coalesce(v_mr, 1));

    v_found := false;
    if p_to = 'band' then
      if v_side = 'top' then v_y0 := 0; v_y1 := v_zh - v_l; else v_y0 := v_grid - v_zh; v_y1 := v_grid - v_l; end if;
      continue when v_y1 < v_y0;
      v_mid := (v_y0 + v_y1) / 2;
      select array_agg(gg order by abs(gg - v_mid), gg) into v_rows from generate_series(v_y0, v_y1) gg;
      <<band>>
      for v_d in 0 .. least(v_grid, 80) loop
        foreach v_cy in array v_rows loop
          foreach v_cx in array array[least(greatest(0, s.x - v_d), v_grid - v_l), least(greatest(0, s.x + v_d), v_grid - v_l)] loop
            if automove_box_ok('space', v_here, s.id, v_cx, v_cy, v_l, v_l, v_fac, false)
               and not exists (select 1 from unnest(v_txa, v_tya, v_twa, v_tha) e(ex, ey, ew, eh)
                               where boxes_overlap(v_cx, v_cy, v_l, v_l, e.ex, e.ey, e.ew, e.eh)) then
              v_tx := v_cx; v_ty := v_cy; v_found := true;
              exit band;
            end if;
          end loop;
        end loop;
        exit when v_d > 0 and s.x - v_d <= 0 and s.x + v_d >= v_grid - v_l;
      end loop;
    else
      for c in
        select gx, gy
        from generate_series(greatest(0, floor(v_zx - f.r - v_l)::int), least(v_grid - v_l, ceil(v_zx + f.r)::int)) gx,
             generate_series(greatest(0, floor(v_zy - f.r - v_l)::int), least(v_grid - v_l, ceil(v_zy + f.r)::int)) gy
        where power(gx + v_l / 2.0 - v_zx, 2) + power(gy + v_l / 2.0 - v_zy, 2) <= power(f.r - 2, 2)
          and (case when v_side = 'top' then gy + v_l / 2.0 <= v_zy - 1 else gy + v_l / 2.0 >= v_zy + 1 end)
          and not exists (select 1 from unnest(v_gx, v_gy) q(qx, qy)
                          where power(gx + v_l / 2.0 - q.qx, 2) + power(gy + v_l / 2.0 - q.qy, 2) < 49)
        order by power(gx + v_l / 2.0 - v_zx, 2) * 0.35 + power(gy + v_l / 2.0 - v_fy, 2), gx
      loop
        if automove_box_ok('space', v_here, s.id, c.gx, c.gy, v_l, v_l, v_fac, false)
           and not exists (select 1 from unnest(v_txa, v_tya, v_twa, v_tha) e(ex, ey, ew, eh)
                           where boxes_overlap(c.gx, c.gy, v_l, v_l, e.ex, e.ey, e.ew, e.eh)) then
          v_tx := c.gx; v_ty := c.gy; v_found := true;
          exit;
        end if;
      end loop;
    end if;
    continue when not v_found;

    if v_live then
      v_txa := v_txa || v_tx; v_tya := v_tya || v_ty; v_twa := v_twa || v_l; v_tha := v_tha || v_l;
      insert into rt_space_orders (ship_id, system_id, x, y, reason, created_at, taken_at)
      values (s.id, v_here, round((v_tx + v_l / 2.0) * 200)::int, round((v_ty + v_l / 2.0) * 200)::int, 'find', now(), null)
      on conflict (ship_id) do update set system_id = excluded.system_id, x = excluded.x, y = excluded.y,
                                          reason = excluded.reason, created_at = now(), taken_at = null;
      v_n := v_n + 1;
      continue;
    end if;

    v_path := automove_route('space', v_here, s.x, s.y, v_tx, v_ty, v_w, v_h, v_mr, v_fac, false);
    continue when jsonb_array_length(v_path) = 0;

    v_txa := v_txa || v_tx; v_tya := v_tya || v_ty; v_twa := v_twa || v_l; v_tha := v_tha || v_l;
    if v_group is null then v_group := gen_random_uuid(); end if;
    v_id := null;
    begin
      insert into auto_moves (owner_user_id, system_id, layer, ship_id, group_id, target_x, target_y, path,
                              step_range, member_idx, faction, label, status)
      values (cm.user_id, v_here, 'space', s.id, v_group, v_tx, v_ty, v_path, v_mr, v_n, v_fac, v_label, 'active')
      returning id into v_id;
    exception when others then
      if sqlerrm not like '%в бою 2.0%' then raise; end if;
    end;
    if v_id is not null then v_new := v_new || v_id; end if;
    v_n := v_n + 1;
  end loop;

  if v_out = 0 then return 'ready'; end if;
  if v_n = 0 then
    return 'blocked:' || case when p_to = 'band' then 'В полосе прыжка нет свободного места или к ней нет пути'
                              else 'У находки нет свободного места или к ней нет пути' end;
  end if;

  foreach a in array v_new loop
    begin
      perform automove_step(a);
    exception when others then perform err_db('void_find_move', sqlstate, sqlerrm, true);
    end;
  end loop;
  return 'moving';
end $$;


--
-- Name: void_find_next_at(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_next_at(p_after timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  tz text := event_tz();
  h0 integer := least(23, greatest(0, game_setting_int('void_find_hour_from', 18)));
  h1 integer := least(24, greatest(h0 + 1, game_setting_int('void_find_hour_to', 21)));
  d date := (p_after at time zone tz)::date;
  t timestamptz;
begin
  for k in 0 .. 2 loop
    t := ((d + k)::timestamp + make_interval(mins => (h0 * 60 + floor(random() * (h1 - h0) * 60))::integer)) at time zone tz;
    if t >= p_after then return t; end if;
  end loop;
  return p_after + interval '1 day';
end $$;


--
-- Name: void_find_notify(text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_notify(p_type text, p_system text, p_subject text, p_meta jsonb, p_faction text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p record; n integer := 0;
begin
  for p in
    select pf.id, pf.faction from profiles pf
    where pf.faction in ('republic', 'cis') and (p_faction is null or pf.faction = p_faction)
      and pf.last_seen_at > now() - interval '3 days'
  loop
    perform log_event(p.id, p.faction, p_system, p_type, p_subject, 0, 'private', p_meta);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: void_find_open(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_open(p_system text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from void_finds f where f.system_id = p_system and f.status = 'active' and f.ends_at > now());
$$;


--
-- Name: void_find_room(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_room(p_system text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('id', f.id, 'type', f.type_id, 'title', t.title, 'glyph', t.glyph, 'art', t.art, 'guard_name', t.guard_name,
                            'cx', f.cx, 'cy', f.cy, 'r', f.r, 'guards', f.guards, 'down', f.guards_down_at is not null,
                            'hold', jsonb_build_object('republic', f.hold_rep, 'cis', f.hold_cis),
                            'need', greatest(1, game_setting_int('void_find_hold_min', 180)) * 60,
                            'holder', f.holder, 'since', f.holder_since, 'tick', f.tick_at, 'ends', f.ends_at, 'now', now())
  from void_finds f join void_find_types t on t.id = f.type_id
  where f.system_id = p_system and f.status = 'active'
  limit 1;
$$;


--
-- Name: void_find_spawn(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_spawn(p_type text DEFAULT NULL::text, p_system text DEFAULT NULL::text, p_dev boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t void_find_types; v_sys text; v_near text[]; v_grid int := game_setting_int('space_grid_cells', 150);
  v_c int; v_r int := greatest(6, game_setting_int('void_find_zone', 15)); v_n int; v_g jsonb := '[]'::jsonb;
  g jsonb; i int := 0; v_ang numeric; v_rad numeric; v_id uuid; v_names text;
begin
  if p_type is not null then
    select * into t from void_find_types where id = p_type and active;
    if not found then raise exception 'Нет такой находки'; end if;
  else
    select * into t from void_find_types vt
    where vt.active and vt.id is distinct from (select type_id from void_finds order by started_at desc limit 1)
    order by -ln(random()) / greatest(vt.weight, 1) limit 1;
    if not found then return null; end if;
  end if;

  -- узел Пустоты на фронте: одним концом к Республике, другим к КНС; недавние узлы — в последнюю очередь
  select s.id into v_sys
  from systems s
  where s.is_deep_space and (p_system is null or s.id = p_system)
    and not exists (select 1 from void_finds f where f.system_id = s.id and f.status = 'active')
    and (p_system is not null or (
         exists (select 1 from hyperlanes h join systems a on a.id = case when h.system_a = s.id then h.system_b else h.system_a end
                 where (h.system_a = s.id or h.system_b = s.id) and not a.is_deep_space and a.faction = 'republic')
     and exists (select 1 from hyperlanes h join systems a on a.id = case when h.system_a = s.id then h.system_b else h.system_a end
                 where (h.system_a = s.id or h.system_b = s.id) and not a.is_deep_space and a.faction = 'cis')))
  order by (select count(*) from void_finds f where f.system_id = s.id and f.started_at > now() - interval '21 days'), random()
  limit 1;
  if v_sys is null then return null; end if;

  select coalesce(array_agg(a.id order by a.faction, a.id), '{}') into v_near
  from hyperlanes h join systems a on a.id = case when h.system_a = v_sys then h.system_b else h.system_a end
  where (h.system_a = v_sys or h.system_b = v_sys) and not a.is_deep_space;

  -- охрана кольцом вокруг находки: вожак ближе, сопровождение дальше; нос — наружу
  v_c := v_grid / 2;
  v_n := jsonb_array_length(t.guards);
  for g in select value from jsonb_array_elements(t.guards) loop
    v_ang := pi() / 2 + i * 2 * pi() / greatest(1, v_n) + pi() / 6;
    v_rad := case when coalesce((g ->> 'lead')::boolean, false) then 700 else 1700 end;
    v_g := v_g || jsonb_build_object('i', i, 'cls', g ->> 'cls', 'name', g ->> 'name', 'lead', coalesce((g ->> 'lead')::boolean, false),
                                     'hp', 1, 'x', round((v_c + 0.5) * 200 + cos(v_ang) * v_rad), 'y', round((v_c + 0.5) * 200 + sin(v_ang) * v_rad),
                                     'hd', round(v_ang::numeric, 3),
                                     -- пост: куда охрана возвращается (x/y/hd бой переписывает, пост — нет)
                                     'px', round((v_c + 0.5) * 200 + cos(v_ang) * v_rad), 'py', round((v_c + 0.5) * 200 + sin(v_ang) * v_rad),
                                     'phd', round(v_ang::numeric, 3));
    i := i + 1;
  end loop;

  insert into void_finds (type_id, system_id, near, ends_at, cx, cy, r, guards, dev)
  values (t.id, v_sys, v_near, now() + make_interval(hours => greatest(1, game_setting_int('void_find_hours', 48))),
          v_c, v_c, v_r, v_g, p_dev)
  returning id into v_id;

  select string_agg(a.name, ' — ' order by a.faction desc) into v_names from systems a where a.id = any(v_near);
  perform void_find_notify('void_find_new', v_sys,
    t.title || ' · ' || coalesce(v_names, 'Пустота') || '. Стерегут: ' || t.guard_name,
    jsonb_build_object('find', v_id, 'type', t.id, 'layer', 'space'));
  return v_id;
end $$;


--
-- Name: void_find_state_json(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_state_json() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_fac text;
begin
  if v_me is null then raise exception 'Нужно войти'; end if;
  select faction into v_fac from profiles where id = v_me;
  return jsonb_build_object(
    'now', now(), 'faction', v_fac, 'need', greatest(1, game_setting_int('void_find_hold_min', 180)) * 60,
    'next', (select next_at from void_find_state where id = 1),
    'active', (select coalesce(jsonb_agg(x order by x ->> 'started'), '[]'::jsonb) from (
      select jsonb_build_object(
        'id', f.id, 'type', f.type_id, 'title', t.title, 'glyph', t.glyph, 'art', t.art, 'text', t.text, 'guard_name', t.guard_name,
        'reward', t.reward, 'system_id', f.system_id, 'system_name', sy.name,
        'pos', jsonb_build_object('x', sy.world_x, 'y', sy.world_y),
        'near', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'faction', a.faction) order by a.faction desc), '[]'::jsonb)
                   from systems a where a.id = any(f.near)),
        'started', f.started_at, 'ends', f.ends_at, 'tick', f.tick_at,
        'guards', (select coalesce(jsonb_agg(jsonb_build_object('name', g ->> 'name', 'cls', g ->> 'cls', 'lead', coalesce((g ->> 'lead')::boolean, false),
                                                                'hp', (g ->> 'hp')::numeric, 'type_name', st.name) order by (g ->> 'i')::int), '[]'::jsonb)
                   from jsonb_array_elements(f.guards) g left join ship_types st on st.id = g ->> 'cls'),
        'down', f.guards_down_at,
        'hold', jsonb_build_object('republic', f.hold_rep, 'cis', f.hold_cis),
        'holder', f.holder, 'since', f.holder_since,
        'zone', (select coalesce(jsonb_object_agg(z.faction, z.n), '{}'::jsonb)
                   from (select q.faction, sum(q.ships)::int n from void_find_in_zone(f.id) q group by q.faction) z),
        'here', (select coalesce(jsonb_object_agg(z.faction, z.n), '{}'::jsonb)
                   from (select s.faction, count(*)::int n from ships s join ship_types tt on tt.id = s.ship_type
                         where s.system_id = f.system_id and not s.in_transit and s.carrier_ship_id is null and not coalesce(tt.is_fighter, false)
                           and s.faction = v_fac   -- чужие корабли в узле — только разведкой, не отсюда
                         group by s.faction) z),
        -- свои: кто держал и сколько (чужих имён не видно)
        'mine', (select coalesce(jsonb_agg(jsonb_build_object('nick', p.nickname, 'seconds', h.seconds, 'me', h.user_id = v_me) order by h.seconds desc), '[]'::jsonb)
                   from void_find_holders h join profiles p on p.id = h.user_id
                   where h.find_id = f.id and h.faction = v_fac and h.seconds > 0),
        -- мои командиры: у находки (в зоне или нет) и в пути к ней
        'fleets', (select coalesce(jsonb_agg(jsonb_build_object(
                      'id', cm.id, 'name', cm.name,
                      'state', case when cm.moving_to = f.system_id then 'flying' else 'here' end,
                      'arrives', case when cm.moving_to = f.system_id then cm.arrives_at end,
                      'ships', (select count(*) from ships s where s.commander_id = cm.id and s.carrier_ship_id is null
                                  and (s.system_id = f.system_id or cm.moving_to = f.system_id)),
                      'in_zone', (select count(*) from ships s join ship_types tt on tt.id = s.ship_type
                                  where s.commander_id = cm.id and s.system_id = f.system_id and not s.in_transit and s.carrier_ship_id is null
                                    and power(s.x + ship_box_w(tt.width_cells, tt.height_cells, s.facing) / 2.0 - (f.cx + 0.5), 2)
                                      + power(s.y + ship_box_h(tt.width_cells, tt.height_cells, s.facing) / 2.0 - (f.cy + 0.5), 2) <= power(f.r, 2)),
                      'moving', exists (select 1 from auto_moves am join ships s on s.id = am.ship_id
                                        where s.commander_id = cm.id and am.status = 'active' and am.label in ('К находке', 'К гиперлинии'))
                    ) order by cm.slot_index), '[]'::jsonb)
                   from commanders cm
                   where cm.user_id = v_me and cm.unlocked
                     and (cm.moving_to = f.system_id or (cm.current_system = f.system_id and cm.moving_to is null)))
      ) x
      from void_finds f join void_find_types t on t.id = f.type_id join systems sy on sy.id = f.system_id
      where f.status = 'active' and f.ends_at > now()) q),
    'recent', (select coalesce(jsonb_agg(x order by x ->> 'ended' desc), '[]'::jsonb) from (
      select jsonb_build_object('id', f.id, 'title', t.title, 'glyph', t.glyph, 'status', f.status, 'winner', f.winner, 'ended', f.ended_at,
                                'system_name', sy.name,
                                'mine', (select x2 from jsonb_array_elements(coalesce(f.result -> 'rows', '[]'::jsonb)) x2 where (x2 ->> 'user')::uuid = v_me limit 1)) x
      from void_finds f join void_find_types t on t.id = f.type_id join systems sy on sy.id = f.system_id
      where f.status <> 'active' and f.ended_at > now() - interval '7 days' and not f.dev
      order by f.ended_at desc limit 4) q)
  );
end $$;


--
-- Name: void_find_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_find_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  st record; f record; t void_find_types; c record; v_need int; v_dt int; v_rep int; v_cis int; v_holder text; v_prev text;
  v_gap numeric; v_n int := 0; v_meta jsonb; v_left int; v_name text; v_res text;
begin
  if not pg_try_advisory_xact_lock(hashtext('void_find_tick')) then return 0; end if;
  if game_setting_int('void_find_enabled', 1) <> 1 then return 0; end if;
  v_need := greatest(1, game_setting_int('void_find_hold_min', 180)) * 60;

  -- 1. появление: по расписанию, одна обычная находка за раз
  select * into st from void_find_state where id = 1 for update;
  if st.next_at is null then
    update void_find_state set next_at = void_find_next_at(now()) where id = 1;
  elsif st.next_at <= now() and not exists (select 1 from void_finds where status = 'active' and not dev) then
    if void_find_spawn(null, null, false) is not null then v_n := v_n + 1; end if;
    v_gap := game_setting_int('void_find_gap_min', 84) + random() * greatest(0, game_setting_int('void_find_gap_max', 168) - game_setting_int('void_find_gap_min', 84));
    update void_find_state set next_at = void_find_next_at(now() + make_interval(hours => v_gap::int)) where id = 1;
  end if;

  -- 2. идущие
  for f in select * from void_finds where status = 'active' order by started_at loop
    if f.ends_at <= now() then perform void_find_finish(f.id, null); continue; end if;
    select * into t from void_find_types where id = f.type_id;
    v_meta := jsonb_build_object('find', f.id, 'type', f.type_id, 'layer', 'space');
    v_dt := least(120, greatest(0, extract(epoch from now() - f.tick_at)::int));

    -- прибывшие флоты сами идут к находке (раз за прилёт); улетевших забываем
    execute 'del' || 'ete from void_find_fleets vf where vf.find_id = $1 and not exists (select 1 from commanders cm '
         || 'where cm.id = vf.commander_id and cm.current_system = $2 and cm.moving_to is null)' using f.id, f.system_id;
    for c in
      select cm.id, cm.user_id, cm.name from commanders cm
      where cm.current_system = f.system_id and cm.moving_to is null and cm.unlocked
        and exists (select 1 from ships s where s.commander_id = cm.id and s.system_id = f.system_id and not s.in_transit and s.carrier_ship_id is null)
        and not exists (select 1 from void_find_fleets vf where vf.find_id = f.id and vf.commander_id = cm.id)
    loop
      -- отметка «обработан» — в том же блоке: упал ход или корабли заняты — повторим на следующем такте
      begin
        insert into void_find_fleets (find_id, commander_id) values (f.id, c.id) on conflict do nothing;
        v_res := void_find_move(f.id, c.id, 'zone');
        if v_res like 'blocked:Корабли заняты%' then
          execute 'del' || 'ete from void_find_fleets where find_id = $1 and commander_id = $2' using f.id, c.id;
          continue;
        end if;
        perform log_event(c.user_id, null, f.system_id, 'void_find_fleet',
          coalesce(c.name, 'Флот') || case when v_res = 'moving' then ' идёт к находке «' || t.title || '»'
                                           when v_res = 'ready' then ' у находки «' || t.title || '»'
                                           else ' прибыл к находке «' || t.title || '» — ' || substr(v_res, 9) end,
          0, 'private', v_meta);
      exception when others then perform err_db('void_find_tick', sqlstate, sqlerrm, true);
      end;
    end loop;

    -- охрана жива: удержания нет
    if f.guards_down_at is null then
      update void_finds set tick_at = now(), holder = null, holder_since = case when holder is null then holder_since else now() end where id = f.id;
      continue;
    end if;

    select coalesce(sum(z.ships) filter (where z.faction = 'republic'), 0), coalesce(sum(z.ships) filter (where z.faction = 'cis'), 0)
      into v_rep, v_cis from void_find_in_zone(f.id) z;
    v_holder := case when v_rep > 0 and v_cis > 0 then 'contested' when v_rep > 0 then 'republic' when v_cis > 0 then 'cis' end;
    v_prev := f.holder;

    if v_holder in ('republic', 'cis') and v_dt > 0 then
      insert into void_find_holders (find_id, user_id, faction, seconds)
      select f.id, z.user_id, z.faction, v_dt from void_find_in_zone(f.id) z where z.faction = v_holder
      on conflict (find_id, user_id) do update set seconds = void_find_holders.seconds + excluded.seconds;
    end if;

    update void_finds set tick_at = now(),
           hold_rep = hold_rep + case when v_holder = 'republic' then v_dt else 0 end,
           hold_cis = hold_cis + case when v_holder = 'cis' then v_dt else 0 end,
           holder = v_holder,
           holder_since = case when holder is distinct from v_holder then now() else holder_since end
     where id = f.id
     returning * into f;

    -- одна сторона встала в зону — обеим в ленту (не чаще раза в 30 минут на сторону)
    if v_holder in ('republic', 'cis') and v_prev is distinct from v_holder
       and coalesce((f.noted ->> v_holder)::timestamptz, now() - interval '1 day') < now() - interval '30 minutes' then
      v_left := v_need - case when v_holder = 'republic' then f.hold_rep else f.hold_cis end;
      v_name := case v_holder when 'republic' then 'Республика' else 'Конфедерация' end;
      perform void_find_notify('void_find_hold', f.system_id,
        'Наши держат «' || t.title || '» — до победы ' || void_find_dur(v_left) || '. Не пускайте врага в зону', v_meta, v_holder);
      perform void_find_notify('void_find_hold', f.system_id,
        v_name || ' держит «' || t.title || '» — через ' || void_find_dur(v_left) || ' находка уйдёт к ней. Встань в зону — удержание остановится', v_meta,
        case v_holder when 'republic' then 'cis' else 'republic' end);
      update void_finds set noted = noted || jsonb_build_object(v_holder, now()) where id = f.id;
    end if;

    if (v_holder = 'republic' and f.hold_rep >= v_need) or (v_holder = 'cis' and f.hold_cis >= v_need) then
      perform void_find_finish(f.id, v_holder);
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end $_$;


