--
-- Name: system_control Faction staff can assign system controller; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Faction staff can assign system controller" ON public.system_control FOR INSERT TO authenticated WITH CHECK ((public.faction_power(auth.uid(), ( SELECT s.faction
   FROM public.systems s
  WHERE (s.id = system_control.system_id)), 'planet_controllers'::text) AND ((controller_user_id IS NULL) OR (EXISTS ( SELECT 1
   FROM (public.profiles p
     JOIN public.systems s ON ((s.id = system_control.system_id)))
  WHERE ((p.id = system_control.controller_user_id) AND (p.faction = s.faction)))))));


--
-- Name: system_control Faction staff can update system controller; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Faction staff can update system controller" ON public.system_control FOR UPDATE TO authenticated USING (public.faction_power(auth.uid(), ( SELECT s.faction
   FROM public.systems s
  WHERE (s.id = system_control.system_id)), 'planet_controllers'::text)) WITH CHECK ((public.faction_power(auth.uid(), ( SELECT s.faction
   FROM public.systems s
  WHERE (s.id = system_control.system_id)), 'planet_controllers'::text) AND ((controller_user_id IS NULL) OR (EXISTS ( SELECT 1
   FROM (public.profiles p
     JOIN public.systems s ON ((s.id = system_control.system_id)))
  WHERE ((p.id = system_control.controller_user_id) AND (p.faction = s.faction)))))));


