--
-- Name: settlement_state Довольство видно своей фракции; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Довольство видно своей фракции" ON public.settlement_state FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.systems s
  WHERE ((s.id = settlement_state.system_id) AND (s.faction = ( SELECT profiles.faction
           FROM public.profiles
          WHERE (profiles.id = auth.uid())))))));


--
-- Name: settlement_tasks Задачи видны своей фракции; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Задачи видны своей фракции" ON public.settlement_tasks FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.systems s
  WHERE ((s.id = settlement_tasks.system_id) AND (s.faction = ( SELECT profiles.faction
           FROM public.profiles
          WHERE (profiles.id = auth.uid())))))));


--
-- Name: system_capture Захват виден всем; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Захват виден всем" ON public.system_capture FOR SELECT USING (true);


