--
-- Name: research_orders Свои заказы науки; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Свои заказы науки" ON public.research_orders FOR SELECT USING ((owner_user_id = auth.uid()));


--
-- Name: game_events Свои события и события фракции; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Свои события и события фракции" ON public.game_events FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR (visibility = 'all'::text) OR ((visibility = 'faction'::text) AND (faction = ( SELECT profiles.faction
   FROM public.profiles
  WHERE (profiles.id = auth.uid()))))));


--
-- Name: player_research Своё изученное; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Своё изученное" ON public.player_research FOR SELECT USING ((user_id = auth.uid()));


